#define MAX_USERS 100

typedef struct {
    int rnti;
    // Other fields...
} MAC_TransportChannelInfo;

typedef struct {
    int logicalChannelIdentity;
    // Other fields...
} TransportChannelConfig;

MAC_TransportChannelInfo transportChannels[MAX_USERS];
TransportChannelConfig channelConfigs[MAX_USERS];

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initializeTransportChannels() {
    for (int i = 0; i < MAX_USERS; i++) {
        pthread_mutex_lock(&mutex);
        transportChannels[i].rnti = i + 1;
        channelConfigs[i].logicalChannelIdentity = i * 2; // Example dynamic assignment
        pthread_mutex_unlock(&mutex);
    }
}

void* updateTransportChannel(void* arg) {
    int userId = *(int*)arg;
    pthread_mutex_lock(&mutex);
    transportChannels[userId].rnti += 10; // Example update
    channelConfigs[userId].logicalChannelIdentity += 5; // Example update
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    initializeTransportChannels();

    pthread_t threads[MAX_USERS];
    int userIds[MAX_USERS];

    for (int i = 0; i < MAX_USERS; i++) {
        userIds[i] = i;
        pthread_create(&threads[i], NULL, updateTransportChannel, &userIds[i]);
    }

    for (int i = 0; i < MAX_USERS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
