#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void initialize_collections(long max_offset, int max_key, int key_set[], int key_count, int range_start, int range_end) {
    long *offsets = (long *)malloc(max_offset * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return;
    }

    int *keys = (int *)malloc(max_key * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        return;
    }

    record *records = (record *)malloc(max_key * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize offsets
    for (long i = 0; i < max_offset; ++i) {
        offsets[i] = i;
    }

    // Initialize keys with unique values from the predefined set
    srand(time(NULL));
    int key_index = 0;
    for (int i = 0; i < max_key; ++i) {
        while (1) {
            int random_key = key_set[rand() % key_count];
            if (!is_key_used(keys, i, random_key)) {
                keys[i] = random_key;
                break;
            }
        }
    }

    // Initialize records with random values within the given range
    for (int i = 0; i < max_key; ++i) {
        int value;
        do {
            value = rand() % (range_end - range_start + 1) + range_start;
        } while (i > 0 && records[i - 1].value == value);
        records[i].value = value;
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

int is_key_used(int *keys, int count, int key) {
    for (int i = 0; i < count; ++i) {
        if (keys[i] == key) {
            return 1;
        }
    }
    return 0;
}
