#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <zlib.h>

#define MAX_FILE_SIZE 1024 * 1024 // 1MB

void parse_arguments(int argc, char *argv[]);
void process_file(const char *filename, const char *log_filename);
void batch_process_directory(const char *directory, const char *log_filename);
void log_message(const char *message, const char *log_filename);

int main(int argc, char *argv[]) {
    parse_arguments(argc, argv);
    return 0;
}

void parse_arguments(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s [file1] [file2] ... [-l log_file]\n", argv[0]);
        exit(1);
    }

    const char *log_filename = NULL;
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            log_filename = argv[++i];
        } else {
            process_file(argv[i], log_filename);
        }
    }

    if (log_filename != NULL) {
        log_message("Processing completed.", log_filename);
    }
}

void process_file(const char *filename, const char *log_filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file");
        return;
    }

    gzFile zfile = gzdopen(fileno(file), "r");
    if (!zfile) {
        fclose(file);
        perror("Error opening gzip file");
        return;
    }

    char buffer[MAX_FILE_SIZE];
    size_t bytes_read;
    size_t total_lines = 0;

    while ((bytes_read = gzread(zfile, buffer, sizeof(buffer))) > 0) {
        for (size_t i = 0; i < bytes_read; ++i) {
            if (buffer[i] == '\n') {
                ++total_lines;
            }
        }
    }

    gzclose(zfile);
    fclose(file);

    printf("File: %s, Lines: %zu\n", filename, total_lines);

    if (log_filename != NULL) {
        log_message(filename, log_filename);
        log_message(buffer, log_filename); // Log the content for demonstration
    }
}

void batch_process_directory(const char *directory, const char *log_filename) {
    DIR *dir = opendir(directory);
    if (!dir) {
        perror("Error opening directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            char path[1024];
            snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);
            process_file(path, log_filename);
        }
    }

    closedir(dir);

    if (log_filename != NULL) {
        log_message("Batch processing completed.", log_filename);
    }
}

void log_message(const char *message, const char *log_filename) {
    FILE *log_file = fopen(log_filename, "a");
    if (!log_file) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_file, "%s\n", message);
    fclose(log_file);
}
