#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define MAX_HOSTNAME_LENGTH 256

typedef struct {
    char *data;
    int line_number;
} LineData;

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    char ip_address[INET_ADDRSTRLEN];
} HostInfo;

void *resolve_dns(void *arg) {
    LineData *line_data = (LineData *)arg;
    HostInfo *host_info = malloc(sizeof(HostInfo));
    if (!host_info) {
        perror("Failed to allocate memory for host info");
        return NULL;
    }

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(line_data->data, NULL, &hints, &res);
    if (status != 0) {
        fprintf(stderr, "DNS resolution failed for line %d: %s\n", line_data->line_number, gai_strerror(status));
        free(host_info);
        return NULL;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &(ipv4->sin_addr), host_info->ip_address, INET_ADDRSTRLEN);

    strcpy(host_info->hostname, line_data->data);
    freeaddrinfo(res);

    // Store or use the resolved IP address as needed
    printf("Resolved %s to %s\n", host_info->hostname, host_info->ip_address);

    return host_info;
}

void process_line(LineData *line_data) {
    char *token = strtok(line_data->data, ",");
    int count = 0;
    double sum = 0;

    while (token != NULL) {
        if (count >= 2) {
            sum += atof(token);
        }
        token = strtok(NULL, ",");
        count++;
    }

    if (count < 2) {
        fprintf(stderr, "Invalid line format on line %d\n", line_data->line_number);
        return;
    }

    double average = sum / 2;
    printf("Line %d: Average of last two fields = %.2f\n", line_data->line_number, average);

    // Optionally, store the average for further use
}

int main() {
    FILE *file = fopen("data.csv", "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_LINE_LENGTH];
    LineData line_data[MAX_LINE_LENGTH];

    int line_number = 0;
    while (fgets(line_data[line_number].data, MAX_LINE_LENGTH, file)) {
        line_data[line_number].line_number = line_number + 1;
        process_line(&line_data[line_number]);

        if (pthread_create(&threads[line_number], NULL, resolve_dns, &line_data[line_number]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }

        line_number++;
    }

    fclose(file);

    for (int i = 0; i < line_number; i++) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
