#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024

typedef struct LogMessage {
    char message[MAX_LOG_SIZE];
    int priority;
    struct LogMessage *next;
} LogMessage;

typedef struct Logger {
    pthread_mutex_t lock;
    LogMessage *head;
    LogMessage *tail;
} Logger;

void init_logger(Logger *logger) {
    pthread_mutex_init(&logger->lock, NULL);
    logger->head = logger->tail = NULL;
}

void log_message(Logger *logger, int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    LogMessage *new_msg = (LogMessage *)malloc(sizeof(LogMessage));
    if (!new_msg) {
        perror("Failed to allocate memory for log message");
        return;
    }

    vsnprintf(new_msg->message, MAX_LOG_SIZE, format, args);
    new_msg->priority = priority;
    new_msg->next = NULL;

    pthread_mutex_lock(&logger->lock);

    if (logger->tail) {
        logger->tail->next = new_msg;
    } else {
        logger->head = new_msg;
    }
    logger->tail = new_msg;

    pthread_mutex_unlock(&logger->lock);
}

void process_logs(Logger *logger, void (*process_func)(LogMessage *)) {
    LogMessage *current;
    while (1) {
        pthread_mutex_lock(&logger->lock);

        if (!logger->head) {
            pthread_mutex_unlock(&logger->lock);
            break;
        }

        current = logger->head;
        logger->head = logger->head->next;

        if (!logger->head) {
            logger->tail = NULL;
        }

        pthread_mutex_unlock(&logger->lock);

        process_func(current);

        free(current);
    }
}

void example_process_func(LogMessage *msg) {
    // Example processing function that could timestamp and prioritize messages
    printf("Priority %d: %s\n", msg->priority, msg->message);
}
```

This code provides a basic structure for a thread-safe logger in C. It includes functions to initialize the logger, log messages with varying priorities, and process logs using a user-provided function. The `log_message` function uses variadic arguments to format messages dynamically and ensures that no single message exceeds `MAX_LOG_SIZE`. The `process_logs` function is designed to be called by a separate thread or process to handle the logging queue efficiently. This example does not include timestamping, which would typically be handled by the existing logging framework.']

