public class PokemonReportService {

    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final ExternalApiService apiService;
    private final CacheService cacheService;

    public PokemonReportService(ExternalApiService apiService, CacheService cacheService) {
        this.apiService = apiService;
        this.cacheService = cacheService;
    }

    public List<PokemonReport> generateReports(List<Pokemon> pokemons) {
        return pokemons.stream()
                .map(this::generateReportAsync)
                .map(CompletableFuture::join)
                .toList();
    }

    private CompletableFuture<PokemonReport> generateReportAsync(Pokemon pokemon) {
        return CompletableFuture.supplyAsync(() -> {
            PokemonTypeData typeData = cacheService.getTypeData(pokemon.getType());
            if (typeData == null) {
                typeData = apiService.fetchTypeData(pokemon.getType());
                cacheService.cacheTypeData(pokemon.getType(), typeData);
            }

            EvolutionChain evolutionChain = cacheService.getEvolutionChain(pokemon.getName());
            if (evolutionChain == null) {
                evolutionChain = apiService.fetchEvolutionChain(pokemon.getName());
                cacheService.cacheEvolutionChain(pokemon.getName(), evolutionChain);
            }

            List<Pokemon> compatibleSpecies = apiService.findCompatibleSpecies(pokemon.getType());

            return new PokemonReport(
                    pokemon,
                    typeData.getWeaknesses(),
                    compatibleSpecies,
                    evolutionChain
            );
        }, executor);
    }
}

