#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 100

typedef struct {
    sem_t *sem;
    int value;
} Semaphore;

Semaphore semaphore_pool[MAX_SEMAPHORES];
int semaphore_count = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

void init_semaphore_system() {
    log_file = fopen("semaphore_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

Semaphore* create_semaphore(int initial_value) {
    pthread_mutex_lock(&pool_lock);
    if (semaphore_count >= MAX_SEMAPHORES) {
        fprintf(stderr, "Maximum semaphore limit reached\n");
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }

    Semaphore *new_sem = &semaphore_pool[semaphore_count++];
    new_sem->sem = malloc(sizeof(sem_t));
    if (!new_sem->sem) {
        perror("Failed to allocate memory for semaphore");
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }
    sem_init(new_sem->sem, 0, initial_value);

    fprintf(log_file, "Semaphore created with value %d\n", initial_value);
    pthread_mutex_unlock(&pool_lock);
    return new_sem;
}

int get_semaphore_value(Semaphore *sem) {
    int value;
    sem_getvalue(sem->sem, &value);
    return value;
}

void increment_semaphore(Semaphore *sem) {
    sem_post(sem->sem);
    fprintf(log_file, "Semaphore incremented\n");
}

void decrement_semaphore(Semaphore *sem) {
    sem_wait(sem->sem);
    fprintf(log_file, "Semaphore decremented\n");
}

void delete_semaphore(Semaphore *sem) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < semaphore_count; i++) {
        if (&semaphore_pool[i] == sem) {
            sem_destroy(sem->sem);
            free(sem->sem);
            for (; i < semaphore_count - 1; i++) {
                semaphore_pool[i] = semaphore_pool[i + 1];
            }
            semaphore_count--;
            fprintf(log_file, "Semaphore deleted\n");
            pthread_mutex_unlock(&pool_lock);
            return;
        }
    }
    pthread_mutex_unlock(&pool_lock);
    fprintf(stderr, "Semaphore not found in pool\n");
}

void cleanup_semaphore_system() {
    for (int i = 0; i < semaphore_count; i++) {
        sem_destroy(semaphore_pool[i].sem);
        free(semaphore_pool[i].sem);
    }
    fclose(log_file);
}
