#include <vector>
#include <mutex>

std::pair<std::vector<int>, std::vector<int>> replaceAndLog(
    std::vector<int>& vec, int target, int replacement, size_t logIndex) {

    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);

    if (vec.empty()) {
        vec.push_back(replacement);
        return {{replacement}, {static_cast<int>(logIndex)}};
    }

    for (size_t i = 0; i < vec.size(); ++i) {
        if (vec[i] == target) {
            vec[i] = replacement;
            std::vector<int> logVec(1, static_cast<int>(logIndex));
            return {vec, logVec};
        }
    }

    vec.push_back(replacement);
    std::vector<int> logVec(1, static_cast<int>(logIndex));
    return {vec, logVec};
}
