using System;
using System.Data;
using System.Data.SqlClient;
using Polly;
using Polly.Retry;

public class StoredProcedureExecutor
{
    private readonly ILogger _logger;
    private readonly IExternalDataSource _externalDataSource;
    private readonly RetryPolicy _retryPolicy;

    public StoredProcedureExecutor(ILogger logger, IExternalDataSource externalDataSource)
    {
        _logger = logger;
        _externalDataSource = externalDataSource;
        _retryPolicy = Policy
            .Handle<SqlException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
    }

    public async Task<IDataReader> ExecuteStoredProcedureAsync(
        SqlConnection connection,
        StoredProcedureConfig config,
        Action<IDataReader> resultSetCallback,
        int timeout)
    {
        _logger.LogInformation("Starting stored procedure execution.");

        var parameters = await FetchParametersAsync(config);
        using (var command = new SqlCommand(config.ProcedureName, connection))
        {
            command.CommandType = CommandType.StoredProcedure;
            command.CommandTimeout = timeout;

            foreach (var param in parameters)
            {
                command.Parameters.Add(param);
            }

            try
            {
                _retryPolicy.ExecuteAsync(async () =>
                {
                    await connection.OpenAsync();
                    using (var reader = await command.ExecuteReaderAsync(CommandBehavior.Default))
                    {
                        resultSetCallback(reader);
                    }
                });

                _logger.LogInformation("Stored procedure executed successfully.");
                return null; // Assuming the callback handles the result set
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error executing stored procedure.");
                throw;
            }
        }
    }

    private async Task<SqlParameter[]> FetchParametersAsync(StoredProcedureConfig config)
    {
        var parameters = new List<SqlParameter>();

        foreach (var param in config.Parameters)
        {
            if (param.Value is string externalValue)
            {
                var cachedValue = await _externalDataSource.GetValueAsync(externalValue);
                parameters.Add(new SqlParameter(param.Name, cachedValue));
            }
            else
            {
                parameters.Add(new SqlParameter(param.Name, param.Value));
            }
        }

        return parameters.ToArray();
    }
}

public class StoredProcedureConfig
{
    public string ProcedureName { get; set; }
    public List<SqlParameter> Parameters { get; set; } = new List<SqlParameter>();
}

public interface ILogger
{
    void LogInformation(string message);
    void LogError(Exception ex, string message);
}

public interface IExternalDataSource
{
    Task<object> GetValueAsync(string key);
}
