    {
        if (cachedConfig != null)
            return cachedConfig;

        try
        {
            var configJson = await File.ReadAllTextAsync(CacheFilePath);
            cachedConfig = JsonConvert.DeserializeObject<GameConfig>(configJson);
        }
        catch
        {
            cachedConfig = await FetchConfigFromApiAsync();
            SaveConfigToCache(cachedConfig);
        }

        return cachedConfig;
    }

    private async Task<GameConfig> FetchConfigFromApiAsync()
    {
        using (var client = new HttpClient())
        {
            try
            {
                var response = await client.GetAsync("https://api.example.com/config");
                response.EnsureSuccessStatusCode();
                var configJson = await response.Content.ReadAsStringAsync();
                return JsonConvert.DeserializeObject<GameConfig>(configJson);
            }
            catch (HttpRequestException)
            {
                // Handle network failure gracefully
                throw new Exception("Failed to fetch configuration from API.");
            }
        }
    }

