using System.Net;
using System.Threading.Tasks;

public class DirectoryConfigurator
{
    private string configFilePath = "system.config";
    private XPathDocument cachedXmlDocument;
    private object lockObject = new object();

    public void CreateDirectoryAndUpdateConfig(string directoryName)
    {
        if (!File.Exists(configFilePath))
        {
            File.Create(configFilePath).Close();
        }

        Directory.CreateDirectory(directoryName);
        UpdateConfigWithDirectoryPath(directoryName);
    }

    private void UpdateConfigWithDirectoryPath(string directoryPath)
    {
        lock (lockObject)
        {
            using (StreamWriter writer = new StreamWriter(configFilePath, true))
            {
                writer.WriteLine($"<directory>{directoryPath}</directory>");
            }
        }
    }

    public string GetElementValueFromXml(string elementName)
    {
        if (cachedXmlDocument == null || DateTime.Now - cachedXmlDocument.DocumentElement.LastModified > TimeSpan.FromMinutes(10))
        {
            lock (lockObject)
            {
                if (cachedXmlDocument == null || DateTime.Now - cachedXmlDocument.DocumentElement.LastModified > TimeSpan.FromMinutes(10))
                {
                    try
                    {
                        using (WebClient client = new WebClient())
                        {
                            string xmlContent = client.DownloadString("http://example.com/config.xml");
                            cachedXmlDocument = new XPathDocument(new StringReader(xmlContent));
                        }
                    }
                    catch (WebException ex)
                    {
                        Console.WriteLine($"Network error: {ex.Message}");
                        return null;
                    }
                }
            }
        }

        try
        {
            XPathNavigator navigator = cachedXmlDocument.CreateNavigator();
            XPathNodeIterator nodes = navigator.Select($"//{elementName}");

            if (!nodes.MoveNext())
            {
                Console.WriteLine($"Warning: No element found with name '{elementName}'");
                return null;
            }

            if (nodes.MoveNext())
            {
                Console.WriteLine($"Error: Multiple elements found with name '{elementName}'");
                Environment.Exit(1);
            }

            return nodes.Current.Value;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex.Message}");
            return null;
        }
    }
}
