public class StringHasher {
    private static final Map<String, String> cache = new ConcurrentHashMap<>();
    private static final ExternalDataSource dataSource = new ExternalDataSource();

    public static Map<String, String> processStrings(List<String> strings) {
        Map<String, String> result = new HashMap<>();

        for (String str : strings) {
            try {
                if (!cache.containsKey(str)) {
                    cache.put(str, computeMD5Hash(str));
                }
                result.put(str, cache.get(str));

                // Fetch additional metadata from external data source
                Metadata metadata = dataSource.fetchMetadata(str);
                if (metadata != null) {
                    // Process metadata as needed
                }
            } catch (Exception e) {
                // Handle exceptions gracefully
                System.err.println("Error processing string: " + str);
                e.printStackTrace();
            }
        }

        return result;
    }

    private static String computeMD5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();

        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        return hexString.toString();
    }
}

