        _elementService = elementService;
        _cache = cache;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateElement([FromBody] ElementUpdateRequest request)
    {
        if (!ModelState.IsValid)
            return BadRequest(ModelState);

        try
        {
            var pageSection = await _elementService.GetPageSection(request.PageSectionId);
            if (pageSection == null)
                return NotFound("Page section not found");

            var element = await _elementService.GetElement(pageSection, request.ElementId);
            if (element == null)
                return NotFound("Element not found");

            var updatedElement = await _elementService.UpdateElement(element, request.HtmlContent);

            // Cache the updated element to minimize redundant updates
            _cache.Set(updatedElement.Id, updatedElement, new MemoryCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10)
            });

            // Notify front-end client-side script to trigger a partial page reload
            return Ok(new { message = "Element updated successfully", elementId = updatedElement.Id });
        }
        catch (Exception ex)
        {
            // Log the exception and retry logic for external service calls
            // Implement robust error handling and retry logic here

            return StatusCode(500, "Internal server error");
        }
    }
}

