const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');

async function processFiles(directory, extension) {
  try {
    const files = await fs.readdir(directory);
    const filteredFiles = files.filter(file => path.extname(file).toLowerCase() === `.${extension}`);

    const filePromises = filteredFiles.map(async (file) => {
      const filePath = path.join(directory, file);
      const content = await fs.readFile(filePath, 'utf8');
      try {
        const response = await axios.get('https://api.example.com/metadata', { params: { filename: file } });
        return { name: file, extension: path.extname(file), content, metadata: response.data };
      } catch (error) {
        console.error(`Failed to retrieve metadata for ${file}:`, error);
        return { name: file, extension: path.extname(file), content, metadata: null };
      }
    });

    const results = await Promise.all(filePromises);
    return results;
  } catch (error) {
    console.error('Error processing files:', error);
    throw error;
  }
}

// Example usage:
processFiles('/path/to/directory', 'txt')
  .then(files => console.log(files))
  .catch(error => console.error(error));
```

This code snippet demonstrates how to asynchronously process files in a specified directory, filter them by extension, and retrieve metadata from an external API. It handles errors gracefully, integrates with the API using Axios for robust network handling, and processes multiple files concurrently for efficiency."]

