const blueslip = require('blueslip');
const fs = require('fs');
const path = require('path');

function runTests(modulePath, environment) {
    const module = require(modulePath);
    const tests = module.tests;
    const log = createLogger();

    function createLogger() {
        return {
            info: (message) => console.log(message),
            error: (message) => console.error(message)
        };
    }

    async function runTest(test, testConfig) {
        blueslip.reset();
        try {
            await test(blueslip, testConfig);
            log.info(`Test passed: ${test.name}`);
        } catch (error) {
            log.error(`Test failed: ${test.name} - ${error.message}`);
        }
    }

    async function runAllTests() {
        for (const [name, test] of Object.entries(tests)) {
            const startTime = Date.now();
            await runTest(test, environment);
            const endTime = Date.now();
            log.info(`Test completed in ${endTime - startTime}ms`);
        }
    }

    runAllTests().catch((error) => {
        log.error(`Error during test execution: ${error.message}`);
    });
}

module.exports = { runTests };
```

