angular.module('dialogServiceModule', [])
.service('DialogFieldUpdateService', ['$window', '$timeout', function($window, $timeout) {
    var self = this;
    var forwardList = [];
    var localState = {};

    // Method to update dialog fields in the parent window
    self.updateFields = function(resourceId, url, targetList) {
        angular.forEach(targetList, function(fieldName) {
            if (forwardList.indexOf(fieldName) !== -1) {
                $window.parent.postMessage({ resourceId: resourceId, url: url, fieldName: fieldName }, '*');
            }
        });
    };

    // Helper method to insert a new field name into the forward list
    self.insertFieldAfter = function(targetFieldName, newFieldName) {
        var index = forwardList.indexOf(targetFieldName);
        if (index !== -1) {
            forwardList.splice(index + 1, 0, newFieldName);
        } else {
            forwardList.push(newFieldName);
        }
    };

    // Event listener for messages from the parent window
    $window.addEventListener('message', function(event) {
        var data = event.data;
        if (data && data.resourceId && data.url && data.fieldName) {
            localState[data.fieldName] = true; // Update local state
            self.updateUI(data.fieldName); // Trigger UI update
        }
    });

    // Method to trigger UI updates based on field changes
    self.updateUI = function(fieldName) {
        $timeout(function() {
            // Perform UI update logic here
            console.log('Updated UI for field:', fieldName);
        });
    };
}]);
