class DataBuffer {
  constructor(config) {
    this.config = config;
    this.buffer = [];
    this.paused = false;
    this.timer = null;
    this.setupListeners();
  }

  setupListeners() {
    // Simulate network stream events
    setInterval(() => this.fetchData(), this.config.delayRange.min);
  }

  fetchData() {
    if (this.paused) return;

    // Simulate data fetching from network
    const newData = this.simulateNetworkRequest();

    if (newData) {
      this.buffer.push(newData);
      this.processBuffer();
    }
  }

  simulateNetworkRequest() {
    // Simulate random data generation
    return Math.random().toString(36).substr(2, 5);
  }

  processBuffer() {
    while (this.buffer.length > 0 && !this.paused) {
      const data = this.buffer.shift();
      try {
        this.saveData(data);
      } catch (error) {
        console.error('Error saving data:', error);
        // Handle error and retry logic
        this.buffer.unshift(data); // Retry by putting it back in the buffer
        break;
      }
    }

    if (this.buffer.length > 0 && !this.paused) {
      this.timer = setTimeout(() => this.processBuffer(), this.config.delayRange.min);
    } else {
      clearTimeout(this.timer);
    }
  }

  saveData(data) {
    // Simulate saving data to storage
    console.log('Saving data:', data);
    // External processing pipeline integration point
    this.processExternalPipeline(data);
  }

  processExternalPipeline(data) {
    // Placeholder for external processing logic
    console.log('Processing data in external pipeline:', data);
  }

  pause() {
    this.paused = true;
    clearTimeout(this.timer);
  }

  resume() {
    this.paused = false;
    this.processBuffer();
  }

  configure(newConfig) {
    Object.assign(this.config, newConfig);
  }
}

