["```javascript
class PacketQueue {
  constructor() {
    this.queue = [];
    this.fragmentMap = new Map();
  }

  enqueue(buffer) {
    const packet = { buffer, offset: 0 };
    if (packet.buffer.length > 1400) {
      // Fragment large packets
      for (let i = 0; i < packet.buffer.length; i += 1400) {
        this.queue.push({ buffer: packet.buffer.slice(i, i + 1400), offset: i });
      }
    } else {
      this.queue.push(packet);
    }
  }

  dequeue(count) {
    const result = [];
    for (let i = 0; i < count; i++) {
      if (this.queue.length === 0) break;
      const packet = this.queue.shift();
      if (packet.offset === 0) {
        // Start of a new packet
        result.push(packet.buffer);
      } else {
        // Fragmented part, store in map for reassembly
        if (!this.fragmentMap.has(packet.offset)) {
          this.fragmentMap.set(packet.offset, []);
        }
        this.fragmentMap.get(packet.offset).push(packet.buffer);
      }
    }

    // Reassemble fragmented packets
    for (const [offset, fragments] of this.fragmentMap.entries()) {
      const sortedFragments = fragments.sort((a, b) => a.offset - b.offset);
      const completePacket = Buffer.concat(sortedFragments.map(f => f.buffer));
      result.push(completePacket);
      this.fragmentMap.delete(offset);
    }

    return Buffer.concat(result);
  }
}

// Example usage:
const queue = new PacketQueue();
queue.enqueue(Buffer.from('Hello, '));
queue.enqueue(Buffer.from('world!'));
console.log(queue.dequeue(2).toString()); // Output: Hello, world!
```"]

