function traverseDOM(node, selector, config) {
  if (!node || !selector || !config) return [];

  const { minDepth, maxDepth, classes, ids, maxElements } = config;
  let result = [];
  let currentDepth = 0;

  function traverse(currentNode, depth) {
    if (depth < minDepth || depth > maxDepth) return;
    if (currentNode.nodeType !== Node.ELEMENT_NODE) return;

    const matchesSelector = currentNode.matches(selector);
    const hasClasses = classes ? classes.every(cls => currentNode.classList.contains(cls)) : true;
    const hasIds = ids ? ids.every(id => currentNode.id === id) : true;

    if (matchesSelector && hasClasses && hasIds) {
      result.push(currentNode);
      if (result.length >= maxElements) return;
    }

    for (let i = 0; i < currentNode.childNodes.length; i++) {
      traverse(currentNode.childNodes[i], depth + 1);
    }
  }

  traverse(node, currentDepth);
  return result;
}
```']

