async function loadModuleCached(directory, filename) {
  if (moduleCache.has(filename)) {
    return moduleCache.get(filename);
  }

  const filePath = path.join(directory, filename);
  try {
    const content = await fs.promises.readFile(filePath, 'utf8');
    // Modify the file extension using the C utility function
    const modifiedFile = modifyFileExtension(filename, directory);
    const modulePath = path.join(directory, modifiedFile);
    // Write the modified content back to the file
    await fs.promises.writeFile(modulePath, content);
    // Execute the module and cache it
    const module = require(modulePath);
    moduleCache.set(filename, module);
    return module;
