import java.util.HashMap;
import java.util.Map;

public class AnagramCounter {

    public static Map<String, Integer> countUniqueAnagrams(String[] strings) {
        if (strings == null || strings.length == 0) {
            throw new IllegalArgumentException("Input array must not be null or empty");
        }

        Map<String, Integer> anagramCount = new HashMap<>();
        for (String str : strings) {
            String sortedStr = sortString(str);
            anagramCount.put(sortedStr, anagramCount.getOrDefault(sortedStr, 0) + 1);
        }
        return anagramCount;
    }

    private static String sortString(String str) {
        char[] chars = str.toCharArray();
        java.util.Arrays.sort(chars);
        return new String(chars);
    }

    public static void main(String[] args) {
        // Example usage
        String[] strings = {"listen", "silent", "enlist", "google", "gooegl"};
        Map<String, Integer> result = countUniqueAnagrams(strings);
        System.out.println(result); // Output: {eilnst=2, eeglo=1}
    }
}
```

