import java.io.IOException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ThemeCacheManager {
    private final ConcurrentHashMap<String, Bitmap> cache = new ConcurrentHashMap<>();
    private final ScheduledExecutorService executorService = Executors.newScheduledThreadPool(1);
    private int maxCacheSize = 50; // Maximum number of themes in cache

    public void loadTheme(String themeId) {
        if (!cache.containsKey(themeId)) {
            executorService.submit(() -> {
                try {
                    Bitmap bitmap = fetchThemeBitmapFromNetwork(themeId);
                    cache.put(themeId, bitmap);
                    evictLeastRecentlyUsed();
                } catch (IOException e) {
                    handleException(e);
                }
            });
        }
    }

    private Bitmap fetchThemeBitmapFromNetwork(String themeId) throws IOException {
        // Simulate network request
        TimeUnit.SECONDS.sleep(1);
        return new Bitmap(); // Placeholder for actual bitmap fetching logic
    }

    private void evictLeastRecentlyUsed() {
        if (cache.size() > maxCacheSize) {
            cache.entrySet().stream()
                .sorted(Map.Entry.comparingByValue())
                .limit(cache.size() - maxCacheSize)
                .forEach(entry -> cache.remove(entry.getKey()));
        }
    }

    private void handleException(IOException e) {
        // Log the exception and notify user
        System.err.println("Error loading theme: " + e.getMessage());
    }

    public Bitmap getTheme(String themeId) {
        return cache.get(themeId);
    }

    public void shutdown() {
        executorService.shutdown();
    }
}
