import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceManager {
    private boolean isRunning = false;
    private ScheduledExecutorService scheduler;
    private int startInterval;
    private int stopInterval;
    private int healthCheckInterval;

    public ServiceManager(int startInterval, int stopInterval, int healthCheckInterval) {
        this.startInterval = startInterval;
        this.stopInterval = stopInterval;
        this.healthCheckInterval = healthCheckInterval;
        scheduler = Executors.newScheduledThreadPool(3);
    }

    public void startService() {
        if (!isRunning) {
            isRunning = true;
            scheduler.scheduleAtFixedRate(this::performStart, 0, startInterval, TimeUnit.SECONDS);
            scheduler.scheduleAtFixedRate(this::performStop, 0, stopInterval, TimeUnit.SECONDS);
            scheduler.scheduleAtFixedRate(this::monitorHealth, 0, healthCheckInterval, TimeUnit.SECONDS);
        }
    }

    public void performStart() {
        // Simulate service start logic
        System.out.println("Service starting...");
        if (!isRunning) {
            isRunning = true;
            retryStart();
        }
    }

    private void retryStart() {
        int maxRetries = 5;
        for (int attempt = 1; attempt <= maxRetries; attempt++) {
            try {
                // Attempt to start the service
                System.out.println("Attempt " + attempt + " to start service...");
                Thread.sleep(1000); // Simulate startup time
                break;
            } catch (Exception e) {
                if (attempt == maxRetries) {
                    publishStopMessage();
                    throw new RuntimeException("Failed to start service after " + maxRetries + " attempts", e);
                }
                System.out.println("Service start failed, retrying...");
            }
        }
    }

    public void performStop() {
        // Simulate service stop logic
        if (isRunning) {
            isRunning = false;
            publishStopMessage();
            System.out.println("Service stopped.");
        }
    }

    private void publishStopMessage() {
        // Publish stop message to distributed messaging system
        System.out.println("Publishing stop message...");
    }

    public void monitorHealth() {
        if (isRunning) {
            // Simulate health check logic
            int healthScore = 100; // Assume perfect health for now
            if (healthScore < 50) {
                System.out.println("Service is unhealthy, alerting monitoring platform...");
                // Alert external monitoring platform
            } else {
                System.out.println("Service is healthy.");
            }
        }
    }

    public void stop() {
        scheduler.shutdown();
        try {
            if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            scheduler.shutdownNow();
        }
    }

    public static void main(String[] args) {
        ServiceManager serviceManager = new ServiceManager(10, 20, 5);
        serviceManager.startService();

        // Simulate running for a while
        try {
            Thread.sleep(60000); // Run for 1 minute
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        serviceManager.stop();
    }
}
