function loadConfiguration($env) {
    $configFile = "config.{$env}.php";
    if (!file_exists($configFile)) {
        throw new Exception("Configuration file not found: {$configFile}");
    }
    return include $configFile;
}

// Validate configuration against schema
function validateConfiguration($config, $schema) {
    foreach ($schema as $key => $type) {
        if (!isset($config[$key]) || gettype($config[$key]) !== $type) {
            throw new Exception("Invalid configuration: {$key} must be of type {$type}");
        }
    }
}

// Cache configuration in memory
function cacheConfiguration($config) {
    static $cache = [];
    $cache['config'] = $config;
    return $cache['config'];
}

// Log configuration changes and errors
function logEvent($message, $level = 'info') {
    // Implement logging logic here (e.g., file, database, external service)
    echo "[$level] {$message}\n";
}

// Handle exceptions gracefully
function handleException($exception) {
    logEvent("Error: {$exception->getMessage()}", 'error');
    // Provide fallback configuration or error handling logic
}

// Main script execution
