<?php

function updatePatientStatus($patientId, $newStatus, $ipAddress) {
    $db = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');
    $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    $transactionStarted = false;
    try {
        $db->beginTransaction();
        $transactionStarted = true;

        // Update main patient table
        $stmt = $db->prepare("UPDATE patients SET status = :status, last_modified_ip = :ip, last_modified_time = NOW() WHERE id = :patientId");
        $stmt->execute(['status' => $newStatus, 'ip' => $ipAddress, 'patientId' => $patientId]);

        // Update related tables
        updateRelatedTables($db, $patientId, $newStatus);

        $db->commit();
    } catch (PDOException $e) {
        if ($transactionStarted) {
            $db->rollBack();
        }
        return [
            'status' => 'failure',
            'message' => 'Database transaction failed: ' . $e->getMessage(),
            'errors' => [$e->getMessage()]
        ];
    } catch (Exception $e) {
        if ($transactionStarted) {
            $db->rollBack();
        }
        return [
            'status' => 'failure',
            'message' => 'An unexpected error occurred: ' . $e->getMessage(),
            'errors' => [$e->getMessage()]
        ];
    }

    return [
        'status' => 'success',
        'message' => 'Patient status updated successfully'
    ];
}

function updateRelatedTables($db, $patientId, $newStatus) {
    // Example related table updates
    try {
        $stmt = $db->prepare("UPDATE appointments SET status = :status WHERE patient_id = :patientId");
        $stmt->execute(['status' => $newStatus, 'patientId' => $patientId]);

        $stmt = $db->prepare("UPDATE medical_records SET last_modified_time = NOW() WHERE patient_id = :patientId");
        $stmt->execute(['patientId' => $patientId]);
    } catch (PDOException $e) {
        throw new Exception('Failed to update related tables: ' . $e->getMessage());
    }
}

// Example usage
