    const [privateKey, certificate] = await Promise.all([
      fetch(privateKeyUrl).then(res => res.text()),
      fetch(certificateUrl).then(res => res.text())
    ]);

    // Initialize combined certificate
    let combinedCertificate = `-----BEGIN PRIVATE KEY-----\n${privateKey}\n-----END PRIVATE KEY-----\n`;

    // Fetch and combine additional parts of the certificate chain from external APIs
    const apiUrls = ['https://api1.example.com/certificate', 'https://api2.example.com/certificate'];
    for (const apiUrl of apiUrls) {
      const partOfCertificate = await fetch(apiUrl).then(res => res.text());
      combinedCertificate += `-----BEGIN CERTIFICATE-----\n${partOfCertificate}\n-----END CERTIFICATE-----\n`;
    }

    return combinedCertificate;
  } catch (error) {
    console.error('Error fetching or combining certificates:', error);
    throw error;
  }
}
