            throw new Exception("User does not have permission to change password.");
        }

        // Validate against last ten passwords
        if ($this->isPasswordReuseAttempt($userId, $newPassword)) {
            throw new Exception("New password cannot be the same as any of the last ten passwords.");
        }

        // Check complexity rules using external authentication service
        if (!$this->authService->validatePasswordComplexity($newPassword)) {
            throw new Exception("Password does not meet complexity requirements.");
        }

        // Prevent rapid succession of password changes
        $lastChangeTime = $this->cache->get("user_last_change_time:$userId");
        if ($lastChangeTime && time() - $lastChangeTime < 1800) {
            throw new Exception("Password change too frequent. Please wait before trying again.");
