        $stmt = $db->prepare("UPDATE users SET password = :password WHERE id = :id");
        $stmt->execute(['password' => password_hash($newPassword, PASSWORD_DEFAULT), 'id' => $userId]);

        // Update cache with new last change time
        $this->cache->set("user_last_change_time:$userId", time(), 1800);

        // Log the password change
        $this->logPasswordChange($userId, $newPassword);

        return true;
