#include <stdlib.h>
#include <pthread.h>
#include "fsa_logger.h"

typedef struct State {
    int id;
    struct State* next;
} State;

typedef struct FSA {
    State** states;
    int num_states;
} FSA;

int manage_state_list(State** current_states, int num_states, FSA* fsa, State* last_state) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    State* new_state_list = (State*)malloc(num_states * sizeof(State));
    if (!new_state_list) {
        fsa_logger_log("Out of memory", LOG_ERROR);
        pthread_mutex_unlock(&lock);
        return -1; // Out of memory error
    }

    for (int i = 0; i < num_states; i++) {
        new_state_list[i].id = fsa->states[i]->id;
        new_state_list[i].next = NULL;
    }

    if (last_state) {
        last_state->next = new_state_list;
    } else {
        *current_states = new_state_list;
    }

    pthread_mutex_unlock(&lock);
    return 0; // Success
}
