#include <iostream>
#include <mutex>
#include <vector>

class OctreeNode {
public:
    std::vector<OctreeNode*> children;
    int dataCapacity;
    int occupiedNodes;

    OctreeNode(int capacity) : dataCapacity(capacity), occupiedNodes(0) {
        if (capacity > 1) {
            for (int i = 0; i < 8; ++i) {
                children.push_back(new OctreeNode(capacity / 2));
            }
        }
    }

    ~OctreeNode() {
        for (auto& child : children) {
            delete child;
        }
    }

    void insert(int data, int featureSize) {
        if (dataCapacity == 1) {
            // Base case: store data directly
            std::lock_guard<std::mutex> lock(mutex);
            ++occupiedNodes;
        } else {
            // Recursive case: find the correct child node
            int index = calculateChildIndex(data, featureSize);
