#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1500
#define SLIDING_WINDOW_SIZE 5

typedef struct {
    int packet_id;
    int payload_size;
} Packet;

typedef struct {
    Packet packets[SLIDING_WINDOW_SIZE];
    int front, rear;
    int count;
    int total_payload;
} SlidingWindow;

void initSlidingWindow(SlidingWindow *window) {
    window->front = 0;
    window->rear = -1;
    window->count = 0;
    window->total_payload = 0;
}

int isFull(SlidingWindow *window) {
    return (window->count == SLIDING_WINDOW_SIZE);
}

void enqueuePacket(SlidingWindow *window, Packet packet) {
    if (isFull(window)) {
        window->total_payload -= window->packets[window->front].payload_size;
        window->front = (window->front + 1) % SLIDING_WINDOW_SIZE;
    }
    window->rear = (window->rear + 1) % SLIDING_WINDOW_SIZE;
    window->packets[window->rear] = packet;
    window->total_payload += packet.payload_size;
    window->count++;
}

Packet dequeuePacket(SlidingWindow *window) {
    Packet packet = window->packets[window->front];
    window->front = (window->front + 1) % SLIDING_WINDOW_SIZE;
    window->count--;
    return packet;
}

int getMaxCumulativePayload(SlidingWindow *window, int minPacketSize, int maxPacketsInLast5ms) {
    if (window->count == 0) {
        return -1; // No packets in the window
    }

    int maxPayload = 0;
    for (int i = 0; i < window->count; i++) {
        Packet packet = dequeuePacket(window);
        if (packet.payload_size >= minPacketSize && window->count <= maxPacketsInLast5ms) {
            maxPayload = (maxPayload > window->total_payload) ? maxPayload : window->total_payload;
        }
        enqueuePacket(window, packet);
    }

    return maxPayload;
}

int main() {
    SlidingWindow window;
    initSlidingWindow(&window);

    // Example usage
    Packet packets[] = {{1, 100}, {2, 200}, {3, 300}, {4, 400}, {5, 500}};
    for (int i = 0; i < sizeof(packets) / sizeof(packets[0]); i++) {
        enqueuePacket(&window, packets[i]);
    }

    int maxPayload = getMaxCumulativePayload(&window, 100, 3);
    printf("Max Cumulative Payload: %d\n", maxPayload);

    return 0;
}
```

This code snippet provides a basic implementation of the required functionality. It includes a sliding window data structure to maintain recent packets and a function to calculate the maximum cumulative payload size based on packet size thresholds and the number of packets in the last 5 milliseconds. The `main` function demonstrates how to use these functions with an example set of packets.']

