class GameCharacter {
public:
    void performAttack() {
        std::lock_guard<std::mutex> lock(mutex_);
        int selectedAttack = selectAttack();
        if (selectedAttack != -1) {
            std::cout << "Attacking with attack " << selectedAttack << std::endl;
            cooldowns_[selectedAttack] = std::chrono::seconds(9);
        }
    }

private:
    std::mutex mutex_;
    std::vector<std::atomic<int>> cooldowns_{std::chrono::seconds(0), std::chrono::seconds(0),
                                            std::chrono::seconds(0), std::chrono::seconds(0),
                                            std::chrono::seconds(0)};

    int selectAttack() {
        for (int i = 0; i < 5; ++i) {
            if (cooldowns_[i].load() == std::chrono::seconds(0)) {
                return i;
            }
        }
        return -1;
    }

    void decrementCooldowns() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
            for (auto& cooldown : cooldowns_) {
                if (cooldown.load() != std::chrono::seconds(0)) {
                    cooldown.store(cooldown.load() - std::chrono::seconds(1));
                }
            }
        }
    }

public:
    GameCharacter() {
        std::thread([this]() { decrementCooldowns(); }).detach();
    }
};

int main() {
    GameCharacter character;
    for (int i = 0; i < 20; ++i) {
        character.performAttack();
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
    return 0;
}
