public class DynamicValueGenerator
{
    private double _minValue;
    private double _maxValue;
    private Random _random;

    public DynamicValueGenerator(double minValue, double maxValue)
    {
        SetRange(minValue, maxValue);
        _random = new Random();
    }

    public void SetRange(double minValue, double maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public double GenerateRandomDouble(bool inclusiveMax = true)
    {
        return _random.NextDouble() * (_maxValue - _minValue) + _minValue + (inclusiveMax ? 0 : -double.Epsilon);
    }

    public int GenerateRandomInt()
    {
        return _random.Next((int)_minValue, (int)Math.Ceiling(_maxValue));
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}";
    }
}
