#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* processString(char* input, size_t limit) {
    if (input == NULL || limit <= 0) {
        return NULL;
    }

    size_t length = strlen(input);
    if (length >= limit) {
        return NULL;
    }

    char* result = realloc(input, length + 2); // Allocate space for the new character and null terminator
    if (result == NULL) {
        return NULL; // Memory allocation failed
    }

    result[length] = '/'; // Append forward slash
    result[length + 1] = '\0'; // Null terminate the string

    return result;
}
