        if (bitsPerSample > MAX_BITS_PER_SAMPLE) {
            // Handle error: Bits per sample exceeds maximum
            TIFFClose(tif);
            return result;
        }
    } else {
        // Handle error: Unable to get bits per sample
        TIFFClose(tif);
        return result;
    }

    if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel)) {
        if (samplesPerPixel != EXPECTED_SAMPLES_PER_PIXEL) {
            // Handle error: Sample per pixel does not match expected value
            TIFFClose(tif);
            return result;
        }
    } else {
        // Handle error: Unable to get sample per pixel
        TIFFClose(tif);
        return result;
    }

    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples)) {
        // Process extra samples if present
    }

    MD5_CTX md5Context;
    MD5_Init(&md5Context);
    MD5_Update(&md5Context, inputString, strlen(inputString));
    MD5_Final(result.hash, &md5Context);

    TIFFClose(tif);
    result.bitsPerSample = bitsPerSample;
    result.samplesPerPixel = samplesPerPixel;
    result.extraSamples = extraSamples;

    return result;
}
