#define MAX_FILENAME_LENGTH 256

int get_directory_depth(const char *path) {
    int depth = 0;
    const char *p = path;
    while (*p != '\0') {
        if (*p == '/') {
            depth++;
        }
        p++;
    }
    return depth;
}

void generate_new_filename(const char *original_filename, char *new_filename, size_t new_filename_size) {
    char directory[MAX_FILENAME_LENGTH];
    char base_name[MAX_FILENAME_LENGTH];
    char extension[MAX_FILENAME_LENGTH] = ".txt";
    int digits = get_directory_depth(original_filename);
    int number = 1;
    DIR *dir;
    struct dirent *entry;

    // Extract directory and base name
    strncpy(directory, original_filename, sizeof(directory) - 1);
    directory[sizeof(directory) - 1] = '\0';
    char *last_slash = strrchr(directory, '/');
    if (last_slash != NULL) {
        last_slash[1] = '\0';
        strcpy(base_name, last_slash + 1);
    } else {
        strcpy(directory, "");
        strcpy(base_name, original_filename);
    }

    // Extract extension
    char *dot = strrchr(base_name, '.');
    if (dot != NULL) {
        strcpy(extension, dot);
        *dot = '\0';
    }

    // Generate new filename
    while (1) {
        snprintf(new_filename, new_filename_size, "%s%.*s_%d%s", directory, (int)strlen(base_name), base_name, number, extension);
        if (new_filename[strlen(new_filename) - 1] == '\0') {
            break;
        }
        dir = opendir(directory);
        if (dir != NULL) {
            while ((entry = readdir(dir)) != NULL) {
                if (strcmp(entry->d_name, new_filename) == 0) {
                    number++;
                    closedir(dir);
                    break;
                }
            }
            closedir(dir);
        } else {
            // Handle error
            break;
        }
    }
}

int main() {
    char original_filename[] = "/home/user/documents/report.txt";
    char new_filename[MAX_FILENAME_LENGTH];

    generate_new_filename(original_filename, new_filename, sizeof(new_filename));

    printf("Original filename: %s\n", original_filename);
    printf("New filename: %s\n", new_filename);

    return 0;
}
