#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

// Define a structure to hold cryptographic context
typedef struct {
    EVP_CIPHER_CTX *aes_ctx;
    EVP_CIPHER_CTX *camellia_ctx;
    EVP_MD_CTX *md5_ctx;
    EVP_MD_CTX *sha_ctx;
    RSA *rsa_key;
    pthread_mutex_t lock;
} CryptoContext;

// Initialize the cryptographic context
CryptoContext* init_crypto_context() {
    CryptoContext *ctx = (CryptoContext*)malloc(sizeof(CryptoContext));
    if (!ctx) return NULL;

    ctx->aes_ctx = EVP_CIPHER_CTX_new();
    ctx->camellia_ctx = EVP_CIPHER_CTX_new();
    ctx->md5_ctx = EVP_MD_CTX_new();
    ctx->sha_ctx = EVP_MD_CTX_new();
    ctx->rsa_key = RSA_new();

    pthread_mutex_init(&ctx->lock, NULL);

    return ctx;
}

// Clean up the cryptographic context
void cleanup_crypto_context(CryptoContext *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx->aes_ctx);
        EVP_CIPHER_CTX_free(ctx->camellia_ctx);
        EVP_MD_CTX_free(ctx->md5_ctx);
        EVP_MD_CTX_free(ctx->sha_ctx);
        RSA_free(ctx->rsa_key);
        pthread_mutex_destroy(&ctx->lock);
        free(ctx);
    }
}

// Encrypt data using AES
int aes_encrypt(CryptoContext *ctx, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    pthread_mutex_lock(&ctx->lock);
    int len;
    int ciphertext_len = 0;

    if (1 != EVP_EncryptInit_ex(ctx->aes_ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    if (1 != EVP_EncryptUpdate(ctx->aes_ctx, ciphertext, &len, plaintext, plaintext_len)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx->aes_ctx, ciphertext + len, &len)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }
    ciphertext_len += len;

    pthread_mutex_unlock(&ctx->lock);
    return ciphertext_len;
}

// Decrypt data using AES
int aes_decrypt(CryptoContext *ctx, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    pthread_mutex_lock(&ctx->lock);
    int len;
    int plaintext_len = 0;

    if (1 != EVP_DecryptInit_ex(ctx->aes_ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    if (1 != EVP_DecryptUpdate(ctx->aes_ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx->aes_ctx, plaintext + len, &len)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }
    plaintext_len += len;

    pthread_mutex_unlock(&ctx->lock);
    return plaintext_len;
}

// Perform MD5 hash
int md5_hash(CryptoContext *ctx, const unsigned char *data, int data_len, unsigned char *digest) {
    pthread_mutex_lock(&ctx->lock);
    if (1 != EVP_DigestInit_ex(ctx->md5_ctx, EVP_md5(), NULL)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    if (1 != EVP_DigestUpdate(ctx->md5_ctx, data, data_len)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    if (1 != EVP_DigestFinal_ex(ctx->md5_ctx, digest, NULL)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    pthread_mutex_unlock(&ctx->lock);
    return 16; // MD5 produces a 16-byte hash
}

// Perform SHA-1 hash
int sha1_hash(CryptoContext *ctx, const unsigned char *data, int data_len, unsigned char *digest) {
    pthread_mutex_lock(&ctx->lock);
    if (1 != EVP_DigestInit_ex(ctx->sha_ctx, EVP_sha1(), NULL)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    if (1 != EVP_DigestUpdate(ctx->sha_ctx, data, data_len)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    if (1 != EVP_DigestFinal_ex(ctx->sha_ctx, digest, NULL)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    pthread_mutex_unlock(&ctx->lock);
    return 20; // SHA-1 produces a 20-byte hash
}

// Generate RSA key pair
int generate_rsa_key(CryptoContext *ctx, int bits) {
    pthread_mutex_lock(&ctx->lock);
    if (1 != RSA_generate_key_ex(ctx->rsa_key, bits, NULL, NULL)) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }
    pthread_mutex_unlock(&ctx->lock);
    return 0;
}

// Encrypt data using RSA with SHA-1 padding
int rsa_encrypt(CryptoContext *ctx, const unsigned char *data, int data_len, unsigned char *ciphertext) {
    pthread_mutex_lock(&ctx->lock);
    int ciphertext_len = RSA_size(ctx->rsa_key);

    if (RSA_public_encrypt(data_len, data, ciphertext, ctx->rsa_key, RSA_PKCS1_PADDING) <= 0) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    pthread_mutex_unlock(&ctx->lock);
    return ciphertext_len;
}

// Decrypt data using RSA with SHA-1 padding
int rsa_decrypt(CryptoContext *ctx, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    pthread_mutex_lock(&ctx->lock);
    int plaintext_len = RSA_size(ctx->rsa_key);

    if (RSA_private_decrypt(ciphertext_len, ciphertext, plaintext, ctx->rsa_key, RSA_PKCS1_PADDING) <= 0) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    pthread_mutex_unlock(&ctx->lock);
    return plaintext_len;
}
