import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ShellCommandExecutor {

    private static final ExecutorService executor = Executors.newCachedThreadPool();

    public static void main(String[] args) {
        try (Path tempDir = Files.createTempDirectory("shell_commands")) {
            executeShellCommands(tempDir, "echo Hello World", "ls -la");
        } catch (IOException e) {
            System.err.println("Failed to create temporary directory: " + e.getMessage());
        }
    }

    public static void executeShellCommands(Path tempDir, String... commands) throws IOException {
        for (String command : commands) {
            Path scriptPath = Files.createTempFile(tempDir, null, ".sh");
            Files.write(scriptPath, ("#!/bin/bash\n" + command).getBytes());
            ProcessBuilder processBuilder = new ProcessBuilder("bash", scriptPath.toString());
            processBuilder.directory(tempDir.toFile());

            try (Process process = processBuilder.start()) {
                captureOutput(process.getInputStream(), "stdout");
                captureOutput(process.getErrorStream(), "stderr");

                int exitCode = process.waitFor();
                if (exitCode != 0) {
                    System.err.println("Command failed with exit code: " + exitCode);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.err.println("Command execution interrupted");
            }
        }
    }

    private static void captureOutput(InputStream inputStream, String streamType) {
        executor.submit(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(streamType + ": " + line);
                    // Log the output using an existing logging framework
                }
            } catch (IOException e) {
                System.err.println("Failed to read " + streamType + " stream: " + e.getMessage());
            }
        });
    }

    static {
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            executor.shutdown();
            try {
                if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException e) {
                executor.shutdownNow();
            }
        }));
    }
}
