using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AesCbcDecryptor
{
    public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, PaddingMode paddingMode)
    {
        if (ciphertext == null || key == null || iv == null)
            throw new ArgumentNullException("Input parameters cannot be null.");

        if (!IsValidKeyLength(key.Length) || !IsValidIvLength(iv.Length))
            throw new ArgumentException("Invalid key or IV length. Key must be 16, 24, or 32 bytes; IV must be 16 bytes.");

        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Padding = paddingMode;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    return ReadFully(csDecrypt);
                }
            }
        }
    }

    private static bool IsValidKeyLength(int length)
    {
        return length == 16 || length == 24 || length == 32;
    }

    private static bool IsValidIvLength(int length)
    {
        return length == 16;
    }

    private static byte[] ReadFully(Stream input)
    {
        using (MemoryStream ms = new MemoryStream())
        {
            input.CopyTo(ms);
            return ms.ToArray();
        }
    }
}
```

