using System;
using System.IO;
using System.IO.Compression;
using System.Threading.Tasks;

public class DataProcessor
{
    public async Task<T> LoadAndDeserializeAsync<T>(string filePath)
    {
        using (var stream = File.OpenRead(filePath))
        {
            var fileExtension = Path.GetExtension(filePath).ToLower();
            var compressionType = GetCompressionType(fileExtension, stream.Length);

            switch (compressionType)
            {
                case CompressionType.Gzip:
                    return await DecompressAndDeserializeAsync<T>(stream, DecompressionStream.Create(stream));
                case CompressionType.Zip:
                    using (var zipArchive = new ZipArchive(stream))
                    {
                        var entry = zipArchive.Entries.FirstOrDefault();
                        if (entry != null)
                            return await DecompressAndDeserializeAsync<T>(entry.Open(), new MemoryStream());
                    }
                    break;
                case CompressionType.Lzma:
                    return await DecompressAndDeserializeAsync<T>(stream, LzmaStream.Create(stream));
                default:
                    throw new NotSupportedException($"Unsupported compression type: {compressionType}");
            }

            throw new InvalidOperationException("Failed to load and deserialize data.");
        }
    }

    private async Task<T> DecompressAndDeserializeAsync<T>(Stream compressedStream, Stream decompressedStream)
    {
        using (var reader = new BinaryReader(decompressedStream))
        {
            try
            {
                return Deserialize<T>(reader);
            }
            catch (Exception ex)
            {
                LogError($"Failed to deserialize data: {ex.Message}");
                throw;
            }
        }
    }

    private CompressionType GetCompressionType(string fileExtension, long fileSize)
    {
        if (fileExtension == ".gz" || fileSize > 1024 * 1024) // GZIP for small files or unknown types
            return CompressionType.Gzip;
        else if (fileExtension == ".zip")
            return CompressionType.Zip;
        else if (fileExtension == ".xz" || fileSize > 5 * 1024 * 1024) // LZMA for large files
            return CompressionType.Lzma;

        LogWarning($"Unknown file extension: {fileExtension}. Defaulting to GZIP.");
        return CompressionType.Gzip;
    }

    private T Deserialize<T>(BinaryReader reader)
    {
        // Implement deserialization logic here
        throw new NotImplementedException();
    }

    private void LogError(string message)
    {
        Console.Error.WriteLine($"ERROR: {message}");
    }

    private void LogWarning(string message)
    {
        Console.WriteLine($"WARNING: {message}");
    }
}

public enum CompressionType
{
    Gzip,
    Zip,
    Lzma
}
