import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.lang.reflect.Constructor;
import java.util.logging.Logger;

public class DynamicDeserializer {

    private static final Logger logger = Logger.getLogger(DynamicDeserializer.class.getName());

    public static <T> T deserialize(byte[] data, Class<T> clazz) {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bis)) {

            // Attempt to reconstruct the class instance
            return clazz.cast(ois.readObject());
        } catch (IOException | ClassNotFoundException e) {
            logger.severe("Deserialization failed: " + e.getMessage());
            try {
                // Fallback to default constructor if available
                Constructor<T> constructor = clazz.getDeclaredConstructor();
                constructor.setAccessible(true);
                return constructor.newInstance();
            } catch (Exception ex) {
                logger.severe("Failed to create default instance: " + ex.getMessage());
                return null;
            }
        }
    }

    public static void main(String[] args) {
        // Example usage
        byte[] serializedData = ...; // Obtain the serialized data from an external source
        MyClass myObject = deserialize(serializedData, MyClass.class);
