struct record {
    int value;
};

void initializeCollections(long maxOffset, int maxKey, const std::set<int>& keySet, int minValue, int maxValue) {
    if (maxValue - minValue + 1 <= 0 || maxKey <= 0 || maxOffset < 0) {
        throw std::invalid_argument("Invalid input values");
    }

    std::vector<long> offsets(maxOffset + 1);
    for (long i = 0; i <= maxOffset; ++i) {
        offsets[i] = i;
    }

    std::vector<int> keys;
    int keyCount = 0;
    for (int key : keySet) {
        if (key > maxKey) break;
        keys.push_back(key);
        ++keyCount;
    }
    if (keyCount != keySet.size()) {
        throw std::invalid_argument("Not enough unique keys within the specified range");
    }

    std::vector<record> records(maxOffset + 1);
    srand(time(0));
    int lastValue = minValue - 1;
    for (long i = 0; i <= maxOffset; ++i) {
        int newValue;
        do {
            newValue = rand() % (maxValue - minValue + 1) + minValue;
        } while (newValue == lastValue);
        records[i].value = newValue;
        lastValue = newValue;
    }

    // Simulate file upload
    std::ofstream file("uploaded_file.txt");
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file for writing");
    }
    file << "File uploaded successfully";
    file.close();

    // Free allocated memory
    offsets.clear();
    keys.clear();
    records.clear();
}

int main() {
    try {
        initializeCollections(100, 50, {10, 20, 30, 40, 50}, 1, 100);
        std::cout << "Initialization successful" << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
