["```javascript
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

class ShellCommandExecutor {
  constructor(options = {}) {
    this.options = {
      logExecutionTime: false,
      suppressOutput: false,
      cacheDirectory: path.join(__dirname, 'cache'),
      ...options
    };

    if (!fs.existsSync(this.options.cacheDirectory)) {
      fs.mkdirSync(this.options.cacheDirectory);
    }
  }

  async execute(command, args = [], options = {}) {
    const { logExecutionTime, suppressOutput } = this.options;
    const cacheKey = `${command}-${args.join('-')}`;
    const cacheFilePath = path.join(this.options.cacheDirectory, `${cacheKey}.json`);

    if (!options.force && fs.existsSync(cacheFilePath)) {
      return JSON.parse(fs.readFileSync(cacheFilePath));
    }

    const startTime = Date.now();
    const child = spawn(command, args, { ...options, stdio: suppressOutput ? 'ignore' : 'pipe' });

    let stdout = '';
    let stderr = '';

    if (!suppressOutput) {
      child.stdout.on('data', (data) => {
        stdout += data.toString();
      });

      child.stderr.on('data', (data) => {
        stderr += data.toString();
      });
    }

    return new Promise((resolve, reject) => {
      child.on('close', (code) => {
        const endTime = Date.now();
        const executionTime = logExecutionTime ? ` (${endTime - startTime}ms)` : '';

        if (code !== 0) {
          console.error(`Command failed with code ${code}${executionTime}`);
          reject(new Error(stderr));
        } else {
          const result = { stdout, stderr };
          if (!suppressOutput) {
            console.log(`Command executed successfully${executionTime}`);
          }
          fs.writeFileSync(cacheFilePath, JSON.stringify(result));
          resolve(result);
        }
      });
    });
  }

  static async run(command, args = [], options = {}) {
    return new ShellCommandExecutor().execute(command, args, options);
  }
}

module.exports = ShellCommandExecutor;
```

This code defines a `ShellCommandExecutor` class that encapsulates the functionality for executing shell commands asynchronously. It includes features such as logging execution times, suppressing output, caching results, and handling errors gracefully. The utility is designed to be modular, extensible, and maintainable, making it suitable for integration into existing application frameworks."]

