                               boost::property<boost::vertex_name_t, std::string>,
                               boost::property<boost::edge_weight_t, int>> Graph;

// Global variables for thread safety and synchronization
std::mutex mtx;
std::condition_variable cv;
bool ready = false;

void worker_thread(Graph& g) {
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, []{ return ready; });
    // Perform vertex and edge operations here
}

int main() {
    Graph g;

    // Simulate dynamic generation of vertices and edges
    for (int i = 0; i < 100; ++i) {
        boost::add_vertex(boost::property<boost::vertex_name_t, std::string>("Vertex" + std::to_string(i)), g);
    }

    for (int i = 0; i < 50; ++i) {
        int u = rand() % 100;
        int v = rand() % 100;
        boost::add_edge(u, v, boost::property<boost::edge_weight_t, int>(rand() % 10), g);
    }

    // Simulate concurrent operations
    std::thread t(worker_thread, std::ref(g));
    {
        std::lock_guard<std::mutex> lock(mtx);
        ready = true;
    }
    cv.notify_one();
    t.join();

    return 0;
}
