use tokio::net::{TcpListener, TcpStream};
use tokio::sync::mpsc;
use tokio::task;
use log::{info, error};
use std::collections::HashMap;
use std::time::Duration;

#[tokio::main]
async fn main() {
    // Initialize logging
    env_logger::init();

    // Parse command-line arguments
    let args: Vec<String> = std::env::args().collect();
    let task_name = &args[1];

    // Create channels for communication between tasks
    let (tx, mut rx) = mpsc::channel(32);

    // Spawn a task based on the command-line argument
    match task_name.as_str() {
        "database_task" => task::spawn(database_task(tx)),
        "message_queue_task" => task::spawn(message_queue_task(tx)),
        _ => error!("Unknown task: {}", task_name),
    }

    // Handle incoming connections and distribute tasks
    let listener = TcpListener::bind("127.0.0.1:8080").await.unwrap();
    info!("Server listening on 127.0.0.1:8080");
    loop {
        match listener.accept().await {
            Ok((stream, addr)) => {
                let tx = tx.clone();
                task::spawn(async move {
                    handle_connection(stream, tx).await;
                });
            }
            Err(e) => error!("Failed to accept connection: {}", e),
        }
    }
}

async fn database_task(tx: mpsc::Sender<String>) {
    // Simulate database operations
    loop {
        info!("Performing database operation");
        tx.send("Database operation completed".to_string()).await.unwrap();
        tokio::time::sleep(Duration::from_secs(5)).await;
    }
}

async fn message_queue_task(tx: mpsc::Sender<String>) {
    // Simulate message queue operations
    loop {
        info!("Processing message from queue");
        tx.send("Message processed".to_string()).await.unwrap();
        tokio::time::sleep(Duration::from_secs(3)).await;
    }
}

async fn handle_connection(mut stream: TcpStream, tx: mpsc::Sender<String>) {
    let mut buffer = [0; 1024];
    while let Ok(n) = stream.read(&mut buffer).await {
        if n == 0 {
            break;
        }
        // Process the received data and send tasks
        tx.send("Task executed".to_string()).await.unwrap();
    }
}
```

