import json
from abc import ABC, abstractmethod

class Configurable(ABC):
    @abstractmethod
    def close(self):
        pass

class ConfigRegistry:
    registry = {}

    @classmethod
    def register(cls, subclass_id, subclass):
        if subclass_id in cls.registry:
            raise ValueError(f"ID '{subclass_id}' already registered")
        cls.registry[subclass_id] = subclass

    @classmethod
    def get_subclass(cls, subclass_id):
        return cls.registry.get(subclass_id)

class BaseConfig(Configurable):
    def __init__(self, config):
        self.config = config

    def close(self):
        pass

class CustomConfig(BaseConfig):
    def process_data(self):
        # Custom processing logic
        pass

# Registering subclasses
ConfigRegistry.register('custom', CustomConfig)

def create_instance(subclass_id, config):
    subclass = ConfigRegistry.get_subclass(subclass_id)
    if subclass:
        return subclass(config)
    else:
        raise ValueError(f"Unknown subclass ID: {subclass_id}")

# Example usage
config_data = '{"type": "custom", "data": {"key": "value"}}'
config_dict = json.loads(config_data)
instance = create_instance(config_dict['type'], config_dict)
instance.process_data()
instance.close()
