long* allocateLongArray(int size) {
    return (long*)malloc(size * sizeof(long));
}

int* allocateIntArray(int size) {
    return (int*)malloc(size * sizeof(int));
}

record* allocateRecordArray(int size) {
    return (record*)malloc(size * sizeof(record));
}

void initializeArrays(long* offsets, int* keys, record* records, int size, int maxKey, int minValue, int maxValue) {
    for (int i = 0; i < size; i++) {
        offsets[i] = i;
        keys[i] = rand() % (maxKey + 1);
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }
}

void findAndPrintMax(int* inputArray, int length) {
    if (length == 0) {
        printf("No elements to compare.\n");
        return;
    }

    int max = inputArray[0];
    for (int i = 1; i < length; i++) {
        if (inputArray[i] > max) {
            max = inputArray[i];
        }
    }
    printf("The largest integer is: %d\n", max);
}

void processAndFindMax(int size, int maxKey, int minValue, int maxValue, const char* filename) {
    long* offsets = allocateLongArray(size);
    int* keys = allocateIntArray(size);
    record* records = allocateRecordArray(size);

    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    initializeArrays(offsets, keys, records, size, maxKey, minValue, maxValue);

    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open file.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    int* inputArray = allocateIntArray(size);
    if (inputArray == NULL) {
        printf("Memory allocation failed for input array.\n");
        fclose(file);
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    int count = 0;
    while (fscanf(file, "%d", &inputArray[count]) != EOF && count < size) {
        count++;
    }
    fclose(file);

    findAndPrintMax(inputArray, count);

    free(offsets);
    free(keys);
    free(records);
    free(inputArray);
}

int main() {
    srand(time(NULL));
    processAndFindMax(10, 50, -100, 100, "input.txt");
    return 0;
}
