#define MAX_VALUE 100

typedef struct {
    int value;
    long* offset;
    int key;
} record;

record* initialize_records(int n, int* error_flag) {
    if (n > MAX_MEMORY / sizeof(record)) {
        *error_flag = 1;
        return NULL;
    }

    record* records = malloc(n * sizeof(record));
    if (!records) {
        *error_flag = 2;
        return NULL;
    }

    long* offsets = malloc(n * sizeof(long));
    if (!offsets) {
        free(records);
        *error_flag = 3;
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < n; i++) {
        records[i].value = MIN_VALUE + rand() % (MAX_VALUE - MIN_VALUE + 1);
        offsets[i] = (long)&records[i];
        records[i].offset = &offsets[i];
        records[i].key = i;
    }

    *error_flag = 0;
    return records;
}
