class DataProcessor {
private:
    RandomNumberGenerator::Generator rng;
    std::vector<std::string> lines;

public:
    void readConfig(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            std::cerr << "Failed to open file: " << filename << std::endl;
            return;
        }

        std::string line;
        while (std::getline(file, line)) {
            lines.push_back(line);
        }
    }

    void processLines() {
        for (auto& line : lines) {
            std::istringstream iss(line);
            std::vector<std::string> fields(std::istream_iterator<std::string>{iss},
                                            std::istream_iterator<std::string>());
            if (fields.size() < 2) continue;

            double sum = std::stod(fields[fields.size() - 1]) + std::stod(fields[fields.size() - 2]);
            double average = sum / 2.0;
            fields.push_back(std::to_string(average));

            std::cout << line << " " << average << std::endl;
        }
    }

    void processLinesConcurrently(int numThreads) {
        std::vector<std::thread> threads(numThreads);
        int chunkSize = lines.size() / numThreads;

        for (int i = 0; i < numThreads; ++i) {
            int start = i * chunkSize;
            int end = (i == numThreads - 1) ? lines.size() : start + chunkSize;
            threads[i] = std::thread([this, start, end]() {
                for (int j = start; j < end; ++j) {
                    processLine(lines[j]);
                }
            });
        }

        for (auto& thread : threads) {
            thread.join();
        }
    }

private:
    void processLine(const std::string& line) {
        std::istringstream iss(line);
        std::vector<std::string> fields(std::istream_iterator<std::string>{iss},
                                            std::istream_iterator<std::string>());
        if (fields.size() < 2) return;

        double sum = std::stod(fields[fields.size() - 1]) + std::stod(fields[fields.size() - 2]);
        double average = sum / 2.0;
        fields.push_back(std::to_string(average));

        std::cout << line << " " << average << std::endl;
    }
};

int main() {
    DataProcessor processor;
    processor.readConfig("config.txt");
    processor.processLinesConcurrently(4);
    return 0;
}
