#define MAX_LINE_LENGTH 1024

typedef struct {
    float *data;
    size_t count;
} Dataset;

Dataset* read_dataset(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    Dataset *dataset = (Dataset*)malloc(sizeof(Dataset));
    dataset->data = NULL;
    dataset->count = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        float number;
        if (sscanf(line, "%f", &number) == 1) {
            dataset->count++;
            dataset->data = realloc(dataset->data, dataset->count * sizeof(float));
            dataset->data[dataset->count - 1] = number;
        }
    }

    fclose(file);
    return dataset;
}

void calculate_statistics(Dataset *dataset) {
    if (!dataset || !dataset->data || dataset->count == 0) {
        fprintf(stderr, "Invalid dataset for statistics calculation\n");
        return;
    }

    float sum = 0.0f;
    for (size_t i = 0; i < dataset->count; i++) {
        sum += dataset->data[i];
    }
    float mean = sum / dataset->count;

    float variance_sum = 0.0f;
    for (size_t i = 0; i < dataset->count; i++) {
        variance_sum += pow(dataset->data[i] - mean, 2);
    }
    float variance = variance_sum / dataset->count;
    float standard_deviation = sqrt(variance);

    printf("Mean: %f\n", mean);
    printf("Standard Deviation: %f\n", standard_deviation);
}

void free_dataset(Dataset *dataset) {
    if (dataset && dataset->data) {
        free(dataset->data);
        free(dataset);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    Dataset *dataset = read_dataset(argv[1]);
    if (!dataset) {
        return 1;
    }

    calculate_statistics(dataset);
    free_dataset(dataset);

    return 0;
}
```

This code provides a basic implementation of the required functionality. It reads a dataset from a CSV file, calculates the mean and standard deviation of the valid numbers, and handles memory allocation and deallocation properly. The `read_dataset` function dynamically allocates memory as it reads the file, ensuring efficient use of resources. Error handling is included for malformed CSV files and invalid input. The program also includes a simple main function to demonstrate usage.']

