#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    int parent;
    int rank;
} UnionFindNode;

void initializeDataStructures(long maxOffset, int maxKey, int minValue, int maxValue) {
    long *offsets = (long *)malloc(maxOffset * sizeof(long));
    int *keys = (int *)malloc(maxKey * sizeof(int));
    record *records = (record *)malloc(maxOffset * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    UnionFindNode *ufNodes = (UnionFindNode *)malloc(maxOffset * sizeof(UnionFindNode));
    if (!ufNodes) {
        fprintf(stderr, "Memory allocation failed for Union-Find nodes\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Initialize offsets
    for (long i = 0; i < maxOffset; ++i) {
        offsets[i] = i;
    }

    // Initialize keys and records
    srand(time(NULL));
    int currentKey = 1;
    for (long i = 0; i < maxOffset; ++i) {
        while (currentKey <= maxKey && (i > 0 && keys[i - 1] == currentKey)) {
            currentKey++;
        }
        if (currentKey > maxKey) {
            fprintf(stderr, "Not enough unique keys available\n");
            free(offsets);
            free(keys);
            free(records);
            free(ufNodes);
            return;
        }
        keys[i] = currentKey;
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;

        // Union-Find initialization
        ufNodes[i].parent = i;
        ufNodes[i].rank = 0;
    }

    // Perform disjointness checks and print time taken for each comparison
    clock_t start, end;
    double cpu_time_used;
    for (long i = 0; i < maxOffset - 1; ++i) {
        start = clock();
        int rootI = find(ufNodes, i);
        int rootJ = find(ufNodes, i + 1);
        if (rootI == rootJ) {
            printf("Records %ld and %ld are in the same group\n", i, i + 1);
        }
        end = clock();
        cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;
        printf("Time taken for comparison: %.6f seconds\n", cpu_time_used);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(ufNodes);
}

int find(UnionFindNode *ufNodes, int i) {
    if (ufNodes[i].parent != i) {
        ufNodes[i].parent = find(ufNodes, ufNodes[i].parent); // Path compression
    }
    return ufNodes[i].parent;
}

void unionSets(UnionFindNode *ufNodes, int i, int j) {
    int rootI = find(ufNodes, i);
    int rootJ = find(ufNodes, j);

    if (rootI != rootJ) {
        if (ufNodes[rootI].rank > ufNodes[rootJ].rank) {
            ufNodes[rootJ].parent = rootI;
        } else if (ufNodes[rootI].rank < ufNodes[rootJ].rank) {
            ufNodes[rootI].parent = rootJ;
        } else {
            ufNodes[rootJ].parent = rootI;
            ufNodes[rootI].rank++;
        }
    }
}
