#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 256
#define INITIAL_ARRAY_SIZE 10
#define THRESHOLD_LINES 1000

char** processAndAnalyzeText(const char* filename, int* fileLineCount) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Allocate initial memory for the array of strings
    char** lines = (char**)malloc(INITIAL_ARRAY_SIZE * sizeof(char*));
    if (!lines) {
        fclose(file);
        perror("Memory allocation failed");
        return NULL;
    }
    *fileLineCount = 0;

    // Read lines from file and store them in the array
    while (*fileLineCount < THRESHOLD_LINES && fgets(lines[*fileLineCount], MAX_LINE_LENGTH, file)) {
        // Trim leading whitespace
        char* start = lines[*fileLineCount];
        while (*start == ' ') start++;

        // Find end of line and trim trailing whitespace
        char* end = strchr(start, '\n');
        if (end) *end = '\0';
        else {
            // If no newline found, read until EOF or limit reached
            while ((end = fgets(lines[*fileLineCount] + strlen(start), MAX_LINE_LENGTH - strlen(start), file)) && *end != '\n') {}
            if (!end) break; // End of file reached
            end[0] = '\0';
        }

        // Check for null characters and allocate memory accordingly
        size_t len = strlen(start);
        lines[*fileLineCount] = (char*)realloc(lines[*fileLineCount], len + 1);
        if (!lines[*fileLineCount]) {
            perror("Memory reallocation failed");
            break;
        }
        strcpy(lines[*fileLineCount], start);

        (*fileLineCount)++;
    }

    fclose(file);

    // Resize array to fit exactly the number of lines read
    char** resizedLines = (char**)realloc(lines, *fileLineCount * sizeof(char*));
    if (!resizedLines) {
        perror("Memory reallocation failed");
        free(lines);
        return NULL;
    }
    lines = resizedLines;

    // Allocate memory for auxiliary array to store lines from standard input
    char** auxLines = (char**)malloc(INITIAL_ARRAY_SIZE * sizeof(char*));
    if (!auxLines) {
        perror("Memory allocation failed");
        free(lines);
        return NULL;
    }

    int auxLineCount = 0;

    // Read lines from standard input until end-of-input marker is encountered
    while (fgets(auxLines[auxLineCount], MAX_LINE_LENGTH, stdin)) {
        if (strcmp(auxLines[auxLineCount], "END\n") == 0) break; // End-of-input marker

        // Trim leading whitespace and allocate memory accordingly
        char* start = auxLines[auxLineCount];
        while (*start == ' ') start++;
        size_t len = strlen(start);
        auxLines[auxLineCount] = (char*)realloc(auxLines[auxLineCount], len + 1);
        if (!auxLines[auxLineCount]) {
            perror("Memory reallocation failed");
            break;
        }
        strcpy(auxLines[auxLineCount], start);

        auxLineCount++;
    }

    // Resize auxiliary array to fit exactly the number of lines read
    char** resizedAuxLines = (char**)realloc(auxLines, auxLineCount * sizeof(char*));
    if (!resizedAuxLines) {
        perror("Memory reallocation failed");
        free(lines);
        for (int i = 0; i < auxLineCount; i++) free(auxLines[i]);
        free(auxLines);
        return NULL;
    }
    auxLines = resizedAuxLines;

    // Return the arrays of lines
    *fileLineCount = auxLineCount;
    return lines;
}

void freeMemory(char** lines, int count) {
    for (int i = 0; i < count; i++) free(lines[i]);
    free(lines);
}
