#include <time.h>

#define MAX_SHAPES 100
#define DISTANCE_STEP 2.5
#define BOUNDING_BOX_SIZE 100
#define MIN_DISTANCE 5

typedef struct Point {
    double x, y;
} Point;

typedef enum ShapeType { CIRCLE, RECTANGLE, TRIANGLE } ShapeType;

typedef struct Shape {
    ShapeType type;
    double distance;
    Point coordinates[3];
    char color[20];
    int outlineWidth;
} Shape;

void initializeGeometricShapes(Shape **shapes, int *shapeCount) {
    srand(time(NULL));
    *shapeCount = 0;

    for (int i = 0; i < MAX_SHAPES && *shapeCount < MAX_SHAPES; i++) {
        shapes[*shapeCount] = (Shape *)malloc(sizeof(Shape));
        if (!shapes[*shapeCount]) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        // Initialize distance
        shapes[*shapeCount]->distance = i * DISTANCE_STEP;

        // Generate coordinates for a random shape type
        int shapeType = rand() % 3; // Randomly choose between circle, rectangle, and triangle
        shapes[*shapeCount]->type = (ShapeType)shapeType;
        switch (shapeType) {
            case CIRCLE:
                shapes[*shapeCount]->coordinates[0].x = rand() % BOUNDING_BOX_SIZE;
                shapes[*shapeCount]->coordinates[0].y = rand() % BOUNDING_BOX_SIZE;
                break;
            case RECTANGLE:
                shapes[*shapeCount]->coordinates[0].x = rand() % (BOUNDING_BOX_SIZE - MIN_DISTANCE);
                shapes[*shapeCount]->coordinates[0].y = rand() % (BOUNDING_BOX_SIZE - MIN_DISTANCE);
                shapes[*shapeCount]->coordinates[1].x = shapes[*shapeCount]->coordinates[0].x + MIN_DISTANCE;
                shapes[*shapeCount]->coordinates[1].y = shapes[*shapeCount]->coordinates[0].y;
                shapes[*shapeCount]->coordinates[2].x = shapes[*shapeCount]->coordinates[0].x + MIN_DISTANCE;
                shapes[*shapeCount]->coordinates[2].y = shapes[*shapeCount]->coordinates[0].y + MIN_DISTANCE;
                break;
            case TRIANGLE:
                shapes[*shapeCount]->coordinates[0].x = rand() % (BOUNDING_BOX_SIZE - MIN_DISTANCE);
                shapes[*shapeCount]->coordinates[0].y = rand() % (BOUNDING_BOX_SIZE - MIN_DISTANCE);
                shapes[*shapeCount]->coordinates[1].x = shapes[*shapeCount]->coordinates[0].x + MIN_DISTANCE;
                shapes[*shapeCount]->coordinates[1].y = shapes[*shapeCount]->coordinates[0].y;
                shapes[*shapeCount]->coordinates[2].x = shapes[*shapeCount]->coordinates[0].x + MIN_DISTANCE / 2;
                shapes[*shapeCount]->coordinates[2].y = shapes[*shapeCount]->coordinates[0].y + MIN_DISTANCE * sqrt(3) / 2;
                break;
        }

        // Assign default colors and outline widths
        switch (shapeType) {
            case CIRCLE:
                strcpy(shapes[*shapeCount]->color, "Red");
                shapes[*shapeCount]->outlineWidth = 1;
                break;
            case RECTANGLE:
                strcpy(shapes[*shapeCount]->color, "Blue");
                shapes[*shapeCount]->outlineWidth = 2;
                break;
            case TRIANGLE:
                strcpy(shapes[*shapeCount]->color, "Green");
                shapes[*shapeCount]->outlineWidth = 3;
                break;
        }

        (*shapeCount)++;
    }
}

int main() {
    Shape *shapes[MAX_SHAPES];
    int shapeCount;

    initializeGeometricShapes(shapes, &shapeCount);

    for (int i = 0; i < shapeCount; i++) {
        printf("Shape %d: Type=%s, Distance=%.2f\n", i, shapes[i]->type == CIRCLE ? "Circle" : shapes[i]->type == RECTANGLE ? "Rectangle" : "Triangle", shapes[i]->distance);
    }

    // Free allocated memory
    for (int i = 0; i < shapeCount; i++) {
        free(shapes[i]);
    }

    return 0;
}
