#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEY_VALUE 1000
#define RECORD_RANGE 100

typedef struct {
    int value;
} Record;

void* manage_memory_and_processes(void* arg) {
    long* offsets = NULL;
    int* keys = NULL;
    Record** records = NULL;
    int max_key_value = MAX_KEY_VALUE;
    int record_count = 0;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Allocate memory for arrays
    offsets = (long*)malloc(record_count * sizeof(long));
    keys = (int*)malloc(record_count * sizeof(int));
    records = (Record**)malloc(record_count * sizeof(Record*));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        goto cleanup;
    }

    // Initialize arrays
    for (int i = 0; i < record_count; i++) {
        offsets[i] = i;
        keys[i] = rand() % max_key_value;
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            perror("Memory allocation failed");
            goto cleanup;
        }
        records[i]->value = rand() % RECORD_RANGE;
    }

    // Periodically update maximum key value
    while (1) {
        pthread_mutex_lock(&lock);
        max_key_value += 100; // Example increment
        for (int i = 0; i < record_count; i++) {
            if (keys[i] >= max_key_value) {
                keys[i] = rand() % max_key_value;
            }
        }
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&lock);

        sleep(60); // Example interval
    }

cleanup:
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int run_command(const char* command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("Fork failed");
        return 0;
    } else if (pid == 0) {
        execlp(command, command, NULL);
        perror("Exec failed");
        exit(EXIT_FAILURE);
    } else {
        int status;
        wait(&status);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0;
    }
}

int main() {
    pthread_t thread;
    srand(time(NULL));

    if (pthread_create(&thread, NULL, manage_memory_and_processes, NULL) != 0) {
        perror("Thread creation failed");
        return EXIT_FAILURE;
    }

    // Run a command in the background
    if (!run_command("ls -l")) {
        fprintf(stderr, "Command execution failed\n");
    }

    pthread_join(thread, NULL);

    return EXIT_SUCCESS;
}
