int is_prime(int num) {
    if (num <= 1) return 0;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) return 0;
    }
    return 1;
}

void* allocate_memory(void* arg) {
    // Simulate memory allocation and initialization
    int size = *(int*)arg;
    long* offsets = malloc(size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_exit(NULL);
    }
    for (int i = 0; i < size; i++) {
        offsets[i] = i * 10; // Example initialization
    }

    int* keys = malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        pthread_exit(NULL);
    }
    for (int i = 0; i < size; i++) {
        keys[i] = offsets[i] % 100; // Example transformation
    }

    record* records = malloc(size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        pthread_exit(NULL);
    }
    for (int i = 0; i < size; i++) {
        int prime;
        do {
            prime = rand() % 1000 + 2; // Example range
        } while (!is_prime(prime));
        records[i].prime = prime;
    }

    printf("Allocated memory for offsets, keys, and records\n");
    pthread_exit(NULL);
}

void free_memory(long* offsets, int* keys, record* records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
    printf("Memory freed\n");
}

int main() {
    int size = 100; // Example size
    pthread_t thread;
    if (pthread_create(&thread, NULL, allocate_memory, &size) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        return 1;
    }
    pthread_join(thread, NULL);

    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;

    // Simulate concurrent access
    pthread_t thread2;
    if (pthread_create(&thread2, NULL, allocate_memory, &size) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        return 1;
    }
    pthread_join(thread2, NULL);

    free_memory(offsets, keys, records);
    return 0;
}
