int allocate_and_populate_array(size_t N, size_t max_size, NFAPI_CRC_INDICATION_PDU_T** array) {
    *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        log_failure("Memory allocation failed");
        return -1;
    }

    unsigned short rntis[MAX_RNTI] = {0};
    int count = 0;

    for (size_t i = 0; i < N && count < MAX_RNTI; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand();
        (*array)[i].RNTI = rntis[count];
        if (rntis[count] == 0) {
            do {
                (*array)[i].RNTI = rand() % MAX_RNTI;
            } while (rntis[(*array)[i].RNTI] != 0);
            rntis[(*array)[i].RNTI] = 1;
        }
        if (count > 0 && (*array)[i].RNTI == (*array)[i - 1].RNTI) {
            log_duplicate_rnti((*array)[i].RNTI);
        }
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    if (count < N) {
        free(*array);
        *array = NULL;
        return -1;
    }

    return count;
}

int main() {
    size_t N = 1000;
    size_t max_size = 1024 * 1024; // 1MB
    NFAPI_CRC_INDICATION_PDU_T* array;

    int result = allocate_and_populate_array(N, max_size, &array);
    if (result >= 0) {
        printf("Successfully allocated and populated array with %d elements.\n", result);
        free(array);
    } else {
        printf("Failed to allocate and populate array.\n");
    }

    return 0;
}
```

