}

void initializeArrays(size_t size, long** offsets, int** keys, record** records) {
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % 1000; // Random value between 0 and 999
        (*records)[i].value = rand() % 1000; // Random value between 0 and 999

        (*records)[i].buffer = (char*)malloc(256 * sizeof(char));
        if ((*records)[i].buffer == NULL) {
            fprintf(stderr, "Memory allocation failed for record buffer\n");
            exit(EXIT_FAILURE);
        }

        generateRandomString((*records)[i].buffer, rand() % 255 + 1); // Random length between 1 and 255
    }
}

void freeArrays(size_t size, long* offsets, int* keys, record* records) {
    for (size_t i = 0; i < size; ++i) {
        free(records[i].buffer);
    }

    free(offsets);
    free(keys);
    free(records);
}

int main() {
