<?php

function generateSecureTokenAndHash($length, $characterSet, $inputData, $environment) {
    // Validate input parameters
    if (!is_int($length) || $length <= 0) {
        throw new InvalidArgumentException("Length must be a positive integer.");
    }
    if (!is_string($characterSet) || empty($characterSet)) {
        throw new InvalidArgumentException("Character set must be a non-empty string.");
    }
    if (!is_string($inputData)) {
        throw new InvalidArgumentException("Input data must be a string.");
    }
    if (!in_array($environment, ['development', 'staging', 'production'])) {
        throw new InvalidArgumentException("Environment must be one of: development, staging, production.");
    }

    // Generate random string
    $randomString = substr(str_shuffle(str_repeat($characterSet, ceil($length / strlen($characterSet)))), 1, $length);

    // Hash data based on environment
    switch ($environment) {
        case 'development':
            $hashedData = password_hash($inputData, PASSWORD_BCRYPT, ['cost' => 4]);
            break;
        case 'staging':
            $hashedData = password_hash($inputData, PASSWORD_BCRYPT, ['cost' => 6]);
            break;
        case 'production':
            $hashedData = password_hash($inputData, PASSWORD_BCRYPT, ['cost' => 10]);
            break;
    }

    // Return result as associative array
    return [
        'randomString' => $randomString,
        'hashedData' => $hashedData
    ];
}

// Example usage:
try {
    $result = generateSecureTokenAndHash(16, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', 'sensitive_data', 'production');
    print_r($result);
} catch (InvalidArgumentException $e) {
    echo "Error: " . $e->getMessage();
}
?>
