#include <string.h>

#define INITIAL_BUFFER_SIZE 1024

typedef struct {
    char *buffer;
    size_t buffer_size;
    size_t data_length;
} CertificateStream;

CertificateStream* createCertificateStream() {
    CertificateStream *stream = (CertificateStream*)malloc(sizeof(CertificateStream));
    stream->buffer = (char*)malloc(INITIAL_BUFFER_SIZE);
    stream->buffer_size = INITIAL_BUFFER_SIZE;
    stream->data_length = 0;
    return stream;
}

void freeCertificateStream(CertificateStream *stream) {
    free(stream->buffer);
    free(stream);
}

int processCertificateStream(CertificateStream *stream, const char *new_data, size_t new_data_length) {
    if (stream->data_length + new_data_length > stream->buffer_size) {
        size_t new_buffer_size = stream->buffer_size * 2;
        while (new_buffer_size < stream->data_length + new_data_length) {
            new_buffer_size *= 2;
        }
        char *new_buffer = (char*)realloc(stream->buffer, new_buffer_size);
        if (!new_buffer) {
            return -1; // Memory allocation failed
        }
        stream->buffer = new_buffer;
        stream->buffer_size = new_buffer_size;
    }
    memcpy(stream->buffer + stream->data_length, new_data, new_data_length);
    stream->data_length += new_data_length;
    return 0;
}

int findLargestInteger(const char *data, size_t length) {
    int largest = INT_MIN;
    for (size_t i = 0; i < length; ++i) {
        if (isdigit(data[i])) {
            int num = 0;
            while (i < length && isdigit(data[i])) {
                num = num * 10 + (data[i] - '0');
                ++i;
            }
            largest = (num > largest) ? num : largest;
        }
    }
    return largest;
}

int main() {
    CertificateStream *stream = createCertificateStream();

    // Simulate data streaming
    const char *data1 = "certificate_data_12345";
    const char *data2 = "_key_data_67890";
    processCertificateStream(stream, data1, strlen(data1));
    processCertificateStream(stream, data2, strlen(data2));

    int largest_integer = findLargestInteger(stream->buffer, stream->data_length);
    printf("Largest integer found: %d\n", largest_integer);

    freeCertificateStream(stream);
    return 0;
}
