#include <string.h>
#include <semaphore.h>
#include <dirent.h>

#define MAX_FILENAME_LENGTH 256

int rename_file_with_semaphore(const char *directory_path, const char *old_filename, int initial_semaphore_value) {
    sem_t semaphore;
    if (sem_init(&semaphore, 0, initial_semaphore_value) != 0) {
        perror("Failed to initialize semaphore");
        return -1;
    }

    // Lock the semaphore before performing file operations
    if (sem_wait(&semaphore) != 0) {
        perror("Failed to acquire semaphore lock");
        sem_destroy(&semaphore);
        return -1;
    }

    char new_filename[MAX_FILENAME_LENGTH];
    strcpy(new_filename, old_filename);

    // Modify the extension based on directory path length and file type
    int digits = strlen(directory_path);
    if (digits > 3) {
        digits -= 3; // Adjust for typical directory structure
    }
    char *dot_position = strrchr(new_filename, '.');
    if (dot_position == NULL) {
        dot_position = new_filename + strlen(new_filename);
        strcat(new_filename, ".txt");
    } else {
        strcpy(dot_position + 1, "000"); // Default to three digits
    }

    // Ensure the new filename does not exceed the maximum length
    if (strlen(new_filename) > MAX_FILENAME_LENGTH - 1) {
        sem_post(&semaphore);
        sem_destroy(&semaphore);
        return -2;
    }

    // Check for uniqueness and append a number if necessary
    DIR *dir = opendir(directory_path);
    if (dir == NULL) {
        perror("Failed to open directory");
        sem_post(&semaphore);
        sem_destroy(&semaphore);
        return -3;
    }
    int file_number = 0;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, new_filename) == 0) {
            file_number++;
            sprintf(dot_position + 1, "%03d", file_number);
        }
    }
    closedir(dir);

    // Rename the file
    char old_path[MAX_FILENAME_LENGTH];
    char new_path[MAX_FILENAME_LENGTH];
    snprintf(old_path, MAX_FILENAME_LENGTH, "%s/%s", directory_path, old_filename);
    snprintf(new_path, MAX_FILENAME_LENGTH, "%s/%s", directory_path, new_filename);
    if (rename(old_path, new_path) != 0) {
        perror("Failed to rename file");
        sem_post(&semaphore);
        sem_destroy(&semaphore);
        return -4;
    }

    // Unlock the semaphore after completing file operations
    if (sem_post(&semaphore) != 0) {
        perror("Failed to release semaphore lock");
        sem_destroy(&semaphore);
        return -5;
    }

    sem_destroy(&semaphore);
    return 0; // Success
}
