typedef struct {
    int key;
    long offset;
} record;

record* initialize_records(int numOffsets, const int* validKeys, int numValidKeys, long minOffset, long maxOffset) {
    if (numOffsets <= 0 || numValidKeys <= 0 || minOffset > maxOffset) {
        return NULL; // Invalid input
    }

    record* records = (record*)malloc(numOffsets * sizeof(record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    if (!offsets) {
        free(records);
        return NULL; // Memory allocation failed
    }

    int* keys = (int*)malloc(numOffsets * sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < numOffsets; ++i) {
        keys[i] = validKeys[rand() % numValidKeys];
        offsets[i] = minOffset + rand() % (maxOffset - minOffset + 1);
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    free(offsets); // No longer needed
    free(keys);   // No longer needed

    return records;
}
