void initialize_aes_cipher(const char *password, unsigned char **key, unsigned char **iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    // Derive key using SHA-256
    unsigned char derived_key[32];
    SHA256((unsigned char *)password, strlen(password), derived_key);

    // Allocate memory for key and IV
    *key = malloc(32);
    *iv = malloc(16);
    if (!*key || !*iv) {
        fprintf(stderr, "Failed to allocate memory\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Copy derived key and generate random IV
    memcpy(*key, derived_key, 32);
    if (!RAND_bytes(*iv, 16)) {
        fprintf(stderr, "Failed to generate random IV\n");
        free(*key);
        free(*iv);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Initialize AES-256-CBC cipher
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, *key, *iv) != 1) {
        fprintf(stderr, "Failed to initialize AES cipher\n");
        free(*key);
        free(*iv);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
}

