typedef struct {
    char* buffer;
    int index;
} record;

typedef struct {
    record* rec_ptr;
    size_t size_bytes;
} metadata;

record* create_record(size_t buffer_size) {
    if (buffer_size == 0) return NULL;
    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) return NULL;
    new_record->buffer = (char*)calloc(buffer_size, sizeof(char));
    if (!new_record->buffer) {
        free(new_record);
        return NULL;
    }
    new_record->index = -1; // Initialize index to an invalid value
    return new_record;
}

metadata* create_metadata(record* rec_ptr, size_t size_bytes) {
    if (!rec_ptr || size_bytes == 0) return NULL;
    metadata* new_meta = (metadata*)malloc(sizeof(metadata));
    if (!new_meta) return NULL;
    new_meta->rec_ptr = rec_ptr;
    new_meta->size_bytes = size_bytes;
    return new_meta;
}

void free_record(record* rec_ptr) {
    if (rec_ptr) {
        free(rec_ptr->buffer);
        free(rec_ptr);
    }
}

void free_metadata(metadata* meta_ptr) {
    if (meta_ptr) {
        free(meta_ptr);
    }
}
