#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
#include <pthread.h>

#define MAX_FILES 100
#define BUFFER_SIZE 4096

typedef struct {
    char *filename;
    int compression_level;
} FileTask;

void* compress_file(void* arg) {
    FileTask *task = (FileTask*)arg;
    FILE *input = fopen(task->filename, "rb");
    if (!input) {
        perror("Failed to open input file");
        return NULL;
    }

    char output_filename[256];
    snprintf(output_filename, sizeof(output_filename), "%s.zip", task->filename);

    gzFile output = gzdopen(open(output_filename, O_WRONLY | O_CREAT | O_TRUNC, 0644), "wb");
    if (!output) {
        perror("Failed to open output file");
        fclose(input);
        return NULL;
    }

    unsigned char buffer[BUFFER_SIZE];
    int bytes_read;

    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, input)) > 0) {
        gzwrite(output, buffer, bytes_read);
    }

    gzclose(output);
    fclose(input);

    printf("Compressed %s\n", task->filename);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <output_dir> <compression_level> <file1> [<file2> ...]\n", argv[0]);
        return 1;
    }

    char *output_dir = argv[1];
    int compression_level = atoi(argv[2]);

    FileTask tasks[MAX_FILES];
    int task_count = 0;

    for (int i = 3; i < argc; i++) {
        if (task_count >= MAX_FILES) {
            fprintf(stderr, "Too many files\n");
            return 1;
        }
        tasks[task_count].filename = argv[i];
        tasks[task_count].compression_level = compression_level;
        task_count++;
    }

    pthread_t threads[MAX_FILES];
    for (int i = 0; i < task_count; i++) {
        if (pthread_create(&threads[i], NULL, compress_file, &tasks[i]) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < task_count; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("All files compressed successfully\n");
    return 0;
}
