class CacheManager {
public:
    void set(const std::string& key, const std::string& value, std::chrono::seconds expiration) {
        // Simulate cache set operation
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        cache[key] = {value, std::chrono::steady_clock::now() + expiration};
    }

    std::optional<std::string> get(const std::string& key) {
        // Simulate cache get operation
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
        auto it = cache.find(key);
        if (it != cache.end()) {
            if (std::chrono::steady_clock::now() < it->second.expiration) {
                return it->second.value;
            } else {
                cache.erase(it); // Remove expired entry
            }
        }
        return std::nullopt;
    }

private:
    struct CacheEntry {
        std::string value;
        std::chrono::time_point<std::chrono::steady_clock> expiration;
    };

    std::map<std::string, CacheEntry> cache;
};

class SandeshClient {
public:
    void addCacheEntries(int numEntries) {
        for (int i = 0; i < numEntries; ++i) {
            std::string key = "key" + std::to_string(i);
            std::string value = "value" + std::to_string(i);
            std::chrono::seconds expiration = std::chrono::seconds(10 + rand() % 20);
            cacheManager.set(key, value, expiration);
        }
    }

    void simulateCacheOperations(int numOperations) {
        for (int i = 0; i < numOperations; ++i) {
            int operationType = rand() % 2;
            if (operationType == 0) {
                // GET operation
                std::string key = "key" + std::to_string(rand() % numOperations);
                auto result = cacheManager.get(key);
                if (result) {
                    std::cout << "GET " << key << ": " << *result << std::endl;
                } else {
                    std::cout << "GET " << key << ": Not Found" << std::endl;
                }
            } else {
                // SET operation
                std::string key = "key" + std::to_string(rand() % numOperations);
                std::string value = "value" + std::to_string(rand() % numOperations);
                std::chrono::seconds expiration = std::chrono::seconds(10 + rand() % 20);
                cacheManager.set(key, value, expiration);
            }
        }
    }

private:
    CacheManager cacheManager;
};

int main() {
    SandeshClient client;
    client.addCacheEntries(100);
    client.simulateCacheOperations(1000);

    return 0;
}
