class SandeshClient {
public:
    SandeshClient(boost::asio::io_context& io_context, int numOffsets, std::vector<int> validKeys, long minOffset, long maxOffset)
        : io_context_(io_context), numOffsets_(numOffsets), validKeys_(validKeys), minOffset_(minOffset), maxOffset_(maxOffset) {
        // Initialize records with random offsets
        for (int i = 0; i < numOffsets_; ++i) {
            int key = validKeys_[rand() % validKeys_.size()];
            long offset = minOffset_ + rand() % (maxOffset_ - minOffset_ + 1);
            records_.push_back({key, offset});
        }
    }

    void start() {
        // Start asynchronous operations
        for (int i = 0; i < numOffsets_; ++i) {
            boost::asio::post(io_context_, boost::bind(&SandeshClient::setRecord, this, i));
        }
    }

private:
    boost::asio::io_context& io_context_;
    int numOffsets_;
    std::vector<int> validKeys_;
    long minOffset_;
    long maxOffset_;
    std::vector<std::pair<int, long>> records_;

    void setRecord(int index) {
        // Simulate SET operation
        std::cout << "Setting record " << index << ": key=" << records_[index].first << ", offset=" << records_[index].second << std::endl;
        boost::this_thread::sleep(boost::posix_time::milliseconds(rand() % 100)); // Simulate network delay
    }
};

int main() {
    try {
        boost::asio::io_context io_context;

        int numOffsets = 10;
        std::vector<int> validKeys = {1, 2, 3, 4, 5};
        long minOffset = 100;
        long maxOffset = 1000;

        SandeshClient client(io_context, numOffsets, validKeys, minOffset, maxOffset);
        client.start();

        io_context.run();
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    return 0;
}
