import subprocess
import requests
from threading import Lock
from time import sleep

# Define a lock for thread-safe file updates
file_lock = Lock()

def fetch_data(api_url):
    response = requests.get(api_url)
    if response.status_code != 200:
        raise Exception(f"Failed to fetch data from {api_url}, status code: {response.status_code}")
    return response.json()

def update_storage_config(data, config_file_path):
    with file_lock:
        with open(config_file_path, 'w') as file:
            for key, value in data.items():
                file.write(f"{key}={value}\n")

def retry_with_exponential_backoff(func, max_retries=5, initial_delay=1):
    delay = initial_delay
    for attempt in range(max_retries + 1):
        try:
            return func()
        except Exception as e:
            if attempt == max_retries:
                raise e
            sleep(delay)
            delay *= 2

def configure_vm_storage(params):
    config_data = {}
    for key, value in params.items():
        if key.endswith('_API'):
            api_url = value
            data = retry_with_exponential_backoff(lambda: fetch_data(api_url))
            config_data.update(data)
        else:
            config_data[key] = value

    update_storage_config(config_data, '/path/to/storage/config')

# Example usage
params = {
    'AWS_API': 'https://api.aws.com/storage',
    'GCP_API': 'https://api.gcp.com/storage',
    'VM_NAME': 'my_vm'
}
configure_vm_storage(params)
