record* initialize_records(int numOffsets, int* validKeys, int numValidKeys, long minOffset, long maxOffset) {
    if (numOffsets <= 0 || numValidKeys == 0) {
        return NULL;
    }

    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    if (!offsets) {
        return NULL;
    }

    int* keys = (int*)malloc(numOffsets * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    record* records = (record*)malloc(numOffsets * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < numOffsets; ++i) {
        keys[i] = validKeys[rand() % numValidKeys];
        offsets[i] = minOffset + rand() % (maxOffset - minOffset + 1);
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    free(offsets);
    free(keys);

    return records;
}

