import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class SensorDataProcessor {

    private static final int THREAD_POOL_SIZE = 10;
    private ExecutorService executorService;
    private List<SensorReading> buffer;
    private AnomalyDetectionModel anomalyModel;
    private WeatherService weatherService;

    public SensorDataProcessor() {
        this.executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        this.buffer = new ArrayList<>();
        this.anomalyModel = loadAnomalyDetectionModel();
        this.weatherService = new WeatherService();
    }

    public void startProcessing() {
        executorService.submit(() -> {
            while (true) {
                SensorReading reading = buffer.poll();
                if (reading != null) {
                    enrichWithWeatherInfo(reading);
                    boolean isAnomaly = anomalyModel.detect(reading);
                    logProcessingResult(reading, isAnomaly);
                }
            }
        });
    }

    public void addSensorReading(SensorReading reading) {
        buffer.add(reading);
    }

    private AnomalyDetectionModel loadAnomalyDetectionModel() {
        // Load pre-trained model from file
        return new AnomalyDetectionModel("path/to/model");
    }

    private void enrichWithWeatherInfo(SensorReading reading) {
        WeatherData weather = weatherService.getWeatherForLocation(reading.getLocation());
        reading.setTemperature(weather.getTemperature());
        reading.setHumidity(weather.getHumidity());
