#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <time.h>

#define MAX_HOSTNAMES 100
#define DNS_SERVERS 3

typedef struct {
    char hostname[256];
    int status;
} HostnameResult;

void* resolve_hostname(void* arg) {
    HostnameResult* result = (HostnameResult*)arg;
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(result->hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        result->status = -1;
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char ipstr[INET6_ADDRSTRLEN];

        // Get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // Convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        printf("  %s: %s\n", result->hostname, ipstr);

        freeaddrinfo(res); // Free the linked list
        result->status = 0;
        return NULL;
    }

    fprintf(stderr, "Failed to resolve hostname: %s\n", result->hostname);
    result->status = -1;
    return NULL;
}

int main() {
    char hostnames[MAX_HOSTNAMES][256];
    HostnameResult results[MAX_HOSTNAMES];
    pthread_t threads[MAX_HOSTNAMES];
    int num_hostnames;

    // Populate hostnames array with actual hostnames
    // ...

    for (num_hostnames = 0; num_hostnames < MAX_HOSTNAMES && strlen(hostnames[num_hostnames]) > 0; num_hostnames++) {
        strcpy(results[num_hostnames].hostname, hostnames[num_hostnames]);
        if (pthread_create(&threads[num_hostnames], NULL, resolve_hostname, &results[num_hostnames]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_hostnames; i++) {
        pthread_join(threads[i], NULL);
    }

    // Log results
    // ...

    return EXIT_SUCCESS;
}
```

