#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SESSIONS 1000

typedef struct {
    char imsi[20];
    int bearerConfig;
} UserSessionState;

typedef struct {
    UserSessionState sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
} SessionManager;

void initialize_session_manager(SessionManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
}

int add_user_session(SessionManager *manager, const char *imsi, int bearerConfig) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (manager->sessions[i].imsi[0] == '\0') {
            snprintf(manager->sessions[i].imsi, sizeof(manager->sessions[i].imsi), "%s", imsi);
            manager->sessions[i].bearerConfig = bearerConfig;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // No available slot
}

int update_bearer_config(SessionManager *manager, const char *imsi, int newBearerConfig) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (strcmp(manager->sessions[i].imsi, imsi) == 0) {
            manager->sessions[i].bearerConfig = newBearerConfig;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

void destroy_session_manager(SessionManager *manager) {
    pthread_mutex_destroy(&manager->lock);
}
```

