// Function to validate file path and handle different file formats
fn process_file(file_path: &str, target_arch: Option<&str>) -> Result<String, String> {
    let path = Path::new(file_path);
    if !path.exists() {
        return Err("File not found".to_string());
    }

    let extension = path.extension().and_then(|ext| ext.to_str()).unwrap_or("");
    let (lexer, parser) = match extension {
        "cpp" => (Box::new(CPPLexer), Box::new(CPPParser)),
        "c" => (Box::new(CLexer), Box::new(CLexer)),
        _ => return Err("Unsupported file format".to_string()),
    };

    let content = fs::read_to_string(file_path).map_err(|_| "Failed to read file")?;
    let tokens = lexer.tokenize(&content);
    let parsed_code = parser.parse(&tokens);

    let llvm_ir_generator = match target_arch {
        Some("x86_64") => Box::new(X86_64LLVMIRGenerator),
        Some("aarch64") => Box::new(AArch64LLVMIRGenerator),
        _ => return Err("Unsupported target architecture".to_string()),
    };

    let llvm_ir = llvm_ir_generator.generate_ir(&parsed_code, target_arch.unwrap_or(""));

    println!("Parsed Nodes: {:?}", tokens);
    println!("Selected Lexer and Parser: CPPLexer, CPPParser");
    println!("Target Architecture: {}", target_arch.unwrap_or_default());
    println!("Generated LLVM IR Code:\n{}", llvm_ir);

    Ok(llvm_ir)
}

// Example usage
fn main() {
    match process_file("example.cpp", Some("x86_64")) {
        Ok(ir) => println!("{}", ir),
        Err(e) => eprintln!("Error: {}", e),
    }
}
```

