#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOAD_FACTOR 0.75

typedef struct HashNode {
    int key;
    void* value;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    HashNode** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable(size_t initialCapacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (HashNode**)calloc(initialCapacity, sizeof(HashNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = initialCapacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* next = node->next;
            free(node);
            node = next;
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

size_t hashFunction(int key, size_t capacity) {
    return abs(key) % capacity;
}

int insert(HashTable* table, int key, void* value) {
    pthread_mutex_lock(&table->lock);

    if ((double)table->size / table->capacity > MAX_LOAD_FACTOR) {
        // Resize the hash table
        HashNode** oldBuckets = table->buckets;
        size_t oldCapacity = table->capacity;

        table->capacity *= 2;
        table->buckets = (HashNode**)calloc(table->capacity, sizeof(HashNode*));
        if (!table->buckets) {
            pthread_mutex_unlock(&table->lock);
            return -1; // Memory allocation failed
        }

        for (size_t i = 0; i < oldCapacity; ++i) {
            HashNode* node = oldBuckets[i];
            while (node) {
                HashNode* next = node->next;
                size_t index = hashFunction(node->key, table->capacity);
                node->next = table->buckets[index];
                table->buckets[index] = node;
                node = next;
            }
        }

        free(oldBuckets);
    }

    size_t index = hashFunction(key, table->capacity);
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    if (!newNode) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Memory allocation failed
    }

    newNode->key = key;
    newNode->value = value;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    ++table->size;

    pthread_mutex_unlock(&table->lock);
    return 0;
}

void* get(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);

    size_t index = hashFunction(key, table->capacity);
    HashNode* node = table->buckets[index];
    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&table->lock);
            return node->value;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL; // Key not found
}

int removeKey(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);

    size_t index = hashFunction(key, table->capacity);
    HashNode** prevPtr = &table->buckets[index];
    HashNode* node = *prevPtr;
    while (node) {
        if (node->key == key) {
            *prevPtr = node->next;
            free(node);
            --table->size;
            pthread_mutex_unlock(&table->lock);
            return 0; // Key removed successfully
        }
        prevPtr = &node->next;
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return -1; // Key not found
}
