using System;
using System.Collections.Generic;
using UnityEngine;

public class ConfigurableRandomGenerator
{
    private Random _random;
    private int _minValue;
    private int _maxValue;
    private Dictionary<int, int> _frequencyDistribution;
    private object _lockObject = new object();

    public ConfigurableRandomGenerator(int minValue, int maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Min value must be less than max value.");

        _random = new Random();
        _minValue = minValue;
        _maxValue = maxValue;
        _frequencyDistribution = new Dictionary<int, int>();
    }

    public void ResetGenerator()
    {
        lock (_lockObject)
        {
            _random = new Random();
            _frequencyDistribution.Clear();
        }
    }

    public float GenerateRandomFloat()
    {
        return (float)_random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GenerateRandomInt()
    {
        return _random.Next(_minValue, _maxValue);
    }

    public void SimulateFrequencyDistribution(int iterations)
    {
        lock (_lockObject)
        {
            for (int i = 0; i < iterations; i++)
            {
                int number = GenerateRandomInt();
                if (_frequencyDistribution.ContainsKey(number))
                    _frequencyDistribution[number]++;
                else
                    _frequencyDistribution[number] = 1;
            }
        }
    }

    public void RecalibrateState()
    {
        lock (_lockObject)
        {
            ResetGenerator();
        }
    }

    public override string ToString()
    {
        lock (_lockObject)
        {
            return $"Min Value: {_minValue}, Max Value: {_maxValue}, Frequency Distribution: {string.Join(", ", _frequencyDistribution)}";
        }
    }
}
