#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_EXTRA_DATA_SIZE 1024 // 1KB
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int value;
    long* offset;
    int key;
    void* extra;
} record;

record* allocate_records(int n, int compressed_mode) {
    if (n * sizeof(record) + n * MAX_EXTRA_DATA_SIZE > MAX_MEMORY) {
        return NULL; // Exceeds maximum memory limit
    }

    record* records = malloc(n * sizeof(record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    long* offsets = malloc(n * sizeof(long));
    if (!offsets) {
        free(records);
        return NULL; // Memory allocation failed
    }

    void** extra_data = compressed_mode ? malloc(n * sizeof(void*)) : NULL;
    if (compressed_mode && !extra_data) {
        free(offsets);
        free(records);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        offsets[i] = (long)((char*)records + sizeof(record) * n + i * MAX_EXTRA_DATA_SIZE);
        records[i].offset = &offsets[i];
        records[i].key = i;

        if (!compressed_mode) {
            records[i].extra = malloc(MAX_EXTRA_DATA_SIZE);
            if (!records[i].extra) {
                for (int j = 0; j < i; j++) {
                    free(records[j].extra);
                }
                free(extra_data);
                free(offsets);
                free(records);
                return NULL; // Memory allocation failed
            }
        } else {
            records[i].extra = extra_data[i];
        }
    }

    if (compressed_mode) {
        void* common_extra_data = malloc(MAX_EXTRA_DATA_SIZE);
        if (!common_extra_data) {
            for (int i = 0; i < n; i++) {
                free(records[i].extra);
            }
            free(extra_data);
            free(offsets);
            free(records);
            return NULL; // Memory allocation failed
        }

        for (int i = 0; i < n; i++) {
            extra_data[i] = common_extra_data;
        }
    }

    return records;
}

void free_records(record* records, int n, int compressed_mode) {
    if (!records) {
        return;
    }

    for (int i = 0; i < n; i++) {
        if (!compressed_mode && records[i].extra) {
            free(records[i].extra);
        }
    }

    if (compressed_mode) {
        // Assuming common_extra_data is managed elsewhere
    }

    free(records[n - 1].offset); // Free the offsets array
    free(records); // Free the records array
}
