typedef struct {
    NetworkConnectionStatusReport *reports;
    int count;
    int maxSize;
} DynamicNetworkArray;

DynamicNetworkArray* initDynamicNetworkArray(int maxSize) {
    DynamicNetworkArray *array = (DynamicNetworkArray*)malloc(sizeof(DynamicNetworkArray));
    array->reports = (NetworkConnectionStatusReport*)calloc(maxSize, sizeof(NetworkConnectionStatusReport));
    array->count = 0;
    array->maxSize = maxSize;
    return array;
}

void freeDynamicNetworkArray(DynamicNetworkArray *array) {
    free(array->reports);
    free(array);
}

int addOrUpdateReport(DynamicNetworkArray *array, NetworkConnectionStatusReport report) {
    for (int i = 0; i < array->count; i++) {
        if (strcmp(array->reports[i].DeviceIdentifier, report.DeviceIdentifier) == 0) {
            array->reports[i] = report;
            return 1; // Updated
        }
    }
    if (array->count < array->maxSize) {
        array->reports[array->count++] = report;
        return 2; // Added
    }
    return 0; // Not added due to size limit
}

void fetchAndProcessData(DynamicNetworkArray *array, int (*fetchDataFromAPI)(NetworkConnectionStatusReport *)) {
    clock_t start = clock();
    while (clock() - start < CLOCKS_PER_SEC / MAX_API_REQUESTS_PER_SECOND) {
        NetworkConnectionStatusReport report;
        if (fetchDataFromAPI(&report)) {
            addOrUpdateReport(array, report);
        }
    }
}

// Example fetchDataFromAPI function
int fetchDataFromAPI(NetworkConnectionStatusReport *report) {
    // Simulate fetching data from an API
    static int count = 0;
    if (count >= MAX_DEVICES) return 0; // No more devices to fetch

    strcpy(report->DeviceIdentifier, "Device");
    report->SignalStrength = rand() % 100;
    report->TransmissionErrorCount = rand() % 5;

    count++;
    return 1;
}

int main() {
    DynamicNetworkArray *array = initDynamicNetworkArray(MAX_DEVICES);
    fetchAndProcessData(array, fetchDataFromAPI);

    // Example of accessing data
    for (int i = 0; i < array->count; i++) {
        printf("Device: %s, Signal Strength: %d, Error Count: %d\n",
               array->reports[i].DeviceIdentifier,
               array->reports[i].SignalStrength,
               array->reports[i].TransmissionErrorCount);
    }

    freeDynamicNetworkArray(array);
    return 0;
}
