void initNetworkConnectionStatusReportManager(NetworkConnectionStatusReportManager* manager) {
    manager->reports = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

void freeNetworkConnectionStatusReportManager(NetworkConnectionStatusReportManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        // Free any dynamically allocated memory within each report
    }
    free(manager->reports);
    manager->reports = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

void addNetworkConnectionStatusReport(NetworkConnectionStatusReportManager* manager, NetworkConnectionStatusReport report) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        NetworkConnectionStatusReport* new_reports = realloc(manager->reports, new_capacity * sizeof(NetworkConnectionStatusReport));
        if (new_reports == NULL) {
            // Handle memory allocation failure
