int compareLongs(const void *a, const void *b) {
    return (*(long*)a - *(long*)b);
}

void initializeArrays(long **offsets, NetworkConnectionStatusReport **reports, int maxDevices) {
    *offsets = (long *)malloc(maxDevices * sizeof(long));
    *reports = (NetworkConnectionStatusReport *)malloc(maxDevices * sizeof(NetworkConnectionStatusReport));

    if (*offsets == NULL || *reports == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    srand(time(NULL));
    for (int i = 0; i < maxDevices; i++) {
        (*offsets)[i] = rand() % (maxDevices * 2); // Random values within a range
        while (i > 0 && (*offsets)[i] == (*offsets)[i - 1]) {
            (*offsets)[i] = rand() % (maxDevices * 2);
        }
    }

    qsort(*offsets, maxDevices, sizeof(long), compareLongs);

    for (int i = 0; i < maxDevices; i++) {
        (*reports)[i].DeviceIdentifier = i + 1;
        (*reports)[i].SignalStrength = rand() % 100; // Random signal strength
        (*reports)[i].TransmissionErrorCount = rand() % 10; // Random error count
    }
}

void freeArrays(long *offsets, NetworkConnectionStatusReport *reports) {
    free(offsets);
    free(reports);
}

int main() {
    long *offsets;
    NetworkConnectionStatusReport *reports;

    initializeArrays(&offsets, &reports, MAX_DEVICES);

    // Use offsets and reports as needed

    freeArrays(offsets, reports);

    return 0;
}
