struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
};

class DistributedCache {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> cache;
    std::mutex mtx;
    std::unordered_set<int> usedTags;

public:
    void set(int index, const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index >= 0 && index < cache.size()) {
            cache[index] = pdu;
            usedTags.insert(pdu.RX_UE_INFORMATION_TAG);
            usedTags.insert(pdu.CRC_INDICATION_REL8_TAG);
        }
    }

    NFAPI_CRC_INDICATION_PDU_T get(int index) const {
        std::lock_guard<std::mutex> lock(mtx);
        if (index >= 0 && index < cache.size()) {
            return cache[index];
        }
        return {};
    }

    void initialize(int numOffsets, int minFlag, int maxFlag, const std::vector<int>& validTags) {
        cache.resize(numOffsets);
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> tagDist(0, validTags.size() - 1);
        std::uniform_int_distribution<> crcFlagDist(minFlag, maxFlag);

        for (int i = 0; i < numOffsets; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            do {
                pdu.RX_UE_INFORMATION_TAG = validTags[tagDist(gen)];
            } while (usedTags.find(pdu.RX_UE_INFORMATION_TAG) != usedTags.end());

            do {
                pdu.CRC_INDICATION_REL8_TAG = validTags[tagDist(gen)];
            } while (usedTags.find(pdu.CRC_INDICATION_REL8_TAG) != usedTags.end());

            pdu.CRCFLAG = crcFlagDist(gen);
            set(i, pdu);
        }
    }

    void monitorAndAdjust() {
        // Implement monitoring and adjustment logic here
    }
};

int main() {
    int numOffsets = 100;
    int minFlag = 0;
    int maxFlag = 255;
    std::vector<int> validTags = {1, 2, 3, 4, 5}; // Example tags

    DistributedCache cache;
    cache.initialize(numOffsets, minFlag, maxFlag, validTags);

    // Simulate concurrent GET and SET operations
    std::thread t1([&cache]() {
        for (int i = 0; i < 10; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu = cache.get(i);
            std::cout << "GET: RX_UE_INFORMATION_TAG=" << pdu.RX_UE_INFORMATION_TAG
                      << ", RNTI=" << pdu.RNTI
                      << ", CRC_INDICATION_REL8_TAG=" << pdu.CRC_INDICATION_REL8_TAG
                      << ", CRCFLAG=" << pdu.CRCFLAG << std::endl;
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    });

    std::thread t2([&cache]() {
        for (int i = 0; i < 10; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.RX_UE_INFORMATION_TAG = validTags[i % validTags.size()];
            pdu.RNTI = i + 100;
            pdu.CRC_INDICATION_REL8_TAG = validTags[(i + 5) % validTags.size()];
            pdu.CRCFLAG = (i * 2) % 256;
            cache.set(i, pdu);
            std::cout << "SET: RX_UE_INFORMATION_TAG=" << pdu.RX_UE_INFORMATION_TAG
                      << ", RNTI=" << pdu.RNTI
                      << ", CRC_INDICATION_REL8_TAG=" << pdu.CRC_INDICATION_REL8_TAG
                      << ", CRCFLAG=" << pdu.CRCFLAG << std::endl;
            std::this_thread::sleep_for(std::chrono::milliseconds(150));
        }
    });

    t1.join();
    t2.join();

    cache.monitorAndAdjust();

    return 0;
}
