#define MAX_LINE_LENGTH 1024
#define DNS_CACHE_SIZE 100

typedef struct {
    char hostname[MAX_LINE_LENGTH];
    char ip_address[INET_ADDRSTRLEN];
} DnsEntry;

DnsEntry dns_cache[DNS_CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* process_line(void* arg) {
    char* line = (char*)arg;
    // Process the line to calculate average and perform DNS resolution
    return NULL;
}

void resolve_dns(char* hostname, char* ip_address) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            strcpy(ip_address, dns_cache[i].ip_address);
            pthread_mutex_unlock(&cache_lock);
            return;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char* ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s: %s\n", ipver, ipstr);

        strcpy(ip_address, ipstr);
        break;
    }

    freeaddrinfo(res); // all done with this structure
}

int main() {
    FILE* file = fopen("data.csv", "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        // Process each line
        pthread_t thread;
        pthread_create(&thread, NULL, process_line, line);
        pthread_join(thread, NULL);
    }

    fclose(file);
    return EXIT_SUCCESS;
}
