                perror("rename");
            }
        } else if (S_ISDIR(file_stat.st_mode)) {
            // Handle directory entries
        }
    }

    closedir(dir);
    return NULL;
}

int main() {
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    DirectoryRequest requests[MAX_CONCURRENT_REQUESTS];

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        snprintf(requests[i].directory_path, sizeof(requests[i].directory_path), "/path/to/directory%d", i);
