#define SALT_SIZE 16
#define KEY_SIZE 32

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[KEY_SIZE];
    unsigned char salt[SALT_SIZE];
} AESCipher;

AESCipher* aes_init(const char *passphrase, size_t passphrase_len) {
    AESCipher *cipher = (AESCipher*)malloc(sizeof(AESCipher));
    if (!cipher) return NULL;

    // Generate a random salt
    if (!RAND_bytes(cipher->salt, SALT_SIZE)) {
        free(cipher);
        return NULL;
    }

    // Derive the key using SHA-256 and the passphrase
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, cipher->salt, SALT_SIZE);
    SHA256_Update(&sha256, passphrase, passphrase_len);
    SHA256_Final(hash, &sha256);

    // Copy the first 32 bytes of the hash as the key
    memcpy(cipher->key, hash, KEY_SIZE);

    // Initialize the AES-128-GCM cipher context
    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        free(cipher);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(cipher->ctx, EVP_aes_128_gcm(), NULL, cipher->key, NULL)) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
        return NULL;
    }

    // Set the IV length based on the chosen cipher mode
    if (1 != EVP_CIPHER_CTX_ctrl(cipher->ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL)) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
        return NULL;
    }

    return cipher;
}

void aes_cleanup(AESCipher *cipher) {
    if (cipher) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
    }
}
