const axios = require('axios');
const FormData = require('form-data');
const retry = require('async-retry');

async function uploadFile(url, fileUrl, metadata) {
  const form = new FormData();
  form.append('file', await axios.get(fileUrl, { responseType: 'stream' }).then(response => response.data));
  Object.keys(metadata).forEach(key => form.append(key, metadata[key]));

  return retry(async bail => {
    try {
      const response = await axios.post(url, form, {
        headers: form.getHeaders(),
        maxContentLength: Infinity,
        maxBodyLength: Infinity
      });
      return response.data;
    } catch (error) {
      if (error.response && error.response.status >= 500) {
        throw new Error('Server error');
      }
      bail(error);
    }
  }, {
    retries: 5,
    factor: 2,
    minTimeout: 1000,
    maxTimeout: 60000
  });
}

// Example usage:
uploadFile('https://example.com/upload', 'https://example.com/file.jpg', { filename: 'file.jpg' })
  .then(data => console.log(data))
  .catch(error => console.error(error));
```

This code snippet provides a basic implementation of the file upload function with retry logic and exponential backoff. It uses `axios` for HTTP requests, `form-data` to handle multipart/form-data uploads, and `async-retry` for implementing the retry mechanism. The function appends the file and metadata to a form data object and sends it as a POST request to the specified URL. If the server returns a 500 status code, indicating a server error, the function retries the upload. Otherwise, it throws an error to be caught by the `retry` function."]

