#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_EXTRA_DATA_SIZE 1024 // 1KB
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct Record {
    int value;
    long* offset;
    int key;
    void* extra_data;
} Record;

Record* create_records(int n, int mode) {
    if (n * sizeof(Record) + n * MAX_EXTRA_DATA_SIZE > MAX_MEMORY) {
        fprintf(stderr, "Error: Exceeds maximum memory limit.\n");
        return NULL;
    }

    Record* records = malloc(n * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    long* offsets = malloc(n * sizeof(long));
    if (!offsets) {
        free(records);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    void** extra_data_pool = NULL;
    int pool_size = 0;

    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        offsets[i] = (long)((char*)records + sizeof(Record) * n + pool_size);
        records[i].offset = &offsets[i];
        records[i].key = i;

        if (mode == 'compressed') {
            if (i % 2 == 0) {
                extra_data_pool = realloc(extra_data_pool, (pool_size + MAX_EXTRA_DATA_SIZE) * sizeof(void*));
                if (!extra_data_pool) {
                    free(records);
                    free(offsets);
                    fprintf(stderr, "Error: Memory allocation failed.\n");
                    return NULL;
                }
                records[i].extra_data = extra_data_pool + pool_size / sizeof(void*);
                pool_size += MAX_EXTRA_DATA_SIZE;
            } else {
                records[i].extra_data = extra_data_pool;
            }
        } else {
            records[i].extra_data = malloc(MAX_EXTRA_DATA_SIZE);
            if (!records[i].extra_data) {
                free(records);
                free(offsets);
                fprintf(stderr, "Error: Memory allocation failed.\n");
                return NULL;
            }
        }
    }

    return records;
}

void free_records(Record* records, int n, int mode) {
    for (int i = 0; i < n; i++) {
        if (mode == 'compressed' && i % 2 != 0) {
            continue;
        }
        free(records[i].extra_data);
    }

    free(records);
    free(offsets);
}

int main() {
    srand(time(NULL));
    int n = 100;
    Record* records = create_records(n, 'compressed');
    if (records) {
        // Use the records
        free_records(records, n, 'compressed');
    }
    return 0;
}
