#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_KEYS 1000
#define RECORD_RANGE 100

typedef struct {
    long offset;
    int key;
    int value;
} Record;

int find(int *parent, int i) {
    if (parent[i] == i)
        return i;
    return parent[i] = find(parent, parent[i]);
}

void unionSet(int *parent, int *rank, int x, int y) {
    int rootX = find(parent, x);
    int rootY = find(parent, y);

    if (rootX != rootY) {
        if (rank[rootX] > rank[rootY])
            parent[rootY] = rootX;
        else if (rank[rootX] < rank[rootY])
            parent[rootX] = rootY;
        else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }
}

void resourceManager(int method, int key, Record *records, int *parent, int *rank) {
    clock_t start, end;
    double cpu_time_used;

    if (method == PUT) {
        start = clock();
        // Apply new data to the record
        records[key].value = rand() % RECORD_RANGE + 1;
        while (records[key].value == records[key - 1].value)
            records[key].value = rand() % RECORD_RANGE + 1;
        end = clock();
        cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC * 1000;
        printf("PUT operation took %f milliseconds\n", cpu_time_used);
    } else if (method == DELETE) {
        start = clock();
        // Replace the record with a placeholder
        records[key].value = -1; // Placeholder value indicating deletion
        unionSet(parent, rank, key, MAX_KEYS); // Union with a special key for deleted records
        end = clock();
        cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC * 1000;
        printf("DELETE operation took %f milliseconds\n", cpu_time_used);
    }
}

int main() {
    srand(time(0));
    Record records[MAX_KEYS];
    int parent[MAX_KEYS], rank[MAX_KEYS];

    // Initialize arrays
    for (int i = 0; i < MAX_KEYS; i++) {
        records[i].offset = i;
        records[i].key = i;
        records[i].value = rand() % RECORD_RANGE + 1;
        while (records[i].value == records[i - 1].value)
            records[i].value = rand() % RECORD_RANGE + 1;
        parent[i] = i;
        rank[i] = 0;
    }

    // Simulate PUT and DELETE operations
    resourceManager(PUT, 500, records, parent, rank);
    resourceManager(DELETE, 300, records, parent, rank);

    return 0;
}
```

