#include <stdio.h>
#include <stdlib.h>

// Function to calculate the sum of even numbers in a file
long long sumEvenNumbersFromFile(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    // Initial buffer size and growth factor
    const int initialSize = 1024;
    int bufferSize = initialSize;
    int* numbers = (int*)malloc(bufferSize * sizeof(int));
    if (!numbers) {
        fclose(file);
        perror("Error allocating memory");
        return -1;
    }

    int count = 0;
    int num;
    while (fscanf(file, "%d", &num) == 1) {
        // Resize array if needed
        if (count >= bufferSize) {
            bufferSize *= 2;
            numbers = (int*)realloc(numbers, bufferSize * sizeof(int));
            if (!numbers) {
                fclose(file);
                perror("Error reallocating memory");
                return -1;
            }
        }
        numbers[count++] = num;
    }

    fclose(file);

    // Calculate sum of even numbers
    long long sum = 0;
    for (int i = 0; i < count; ++i) {
        if (numbers[i] % 2 == 0) {
            sum += numbers[i];
        }
    }

    // Free allocated memory
    free(numbers);

    return sum;
}

// Example usage
int main() {
    long long result = sumEvenNumbersFromFile("large_numbers.txt");
    if (result != -1) {
        printf("Sum of even numbers: %lld\n", result);
    }
    return 0;
}
```

