typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->array) {
        free(pool);
        return NULL;
    }

    pool->size = 0;
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->array);
    pthread_mutex_unlock(&pool->lock);
    free(pool);
}

int allocate_and_populate(NFAPI_CRC_INDICATION_PDU_T** result, size_t N, MemoryPool* pool, size_t max_size) {
    pthread_mutex_lock(&pool->lock);

    if (N * sizeof(NFAPI_CRC_INDICATION_PDU_T) > max_size - pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Allocation exceeds maximum size
    }

    for (size_t i = 0; i < N; ++i) {
        result[i] = &pool->array[pool->size++];

        // Populate the structure with valid values
        result[i]->RX_UE_INFORMATION_TAG = rand() % 1000;
        result[i]->RNTI = rand() % 65536; // Random RNTI value
        result[i]->CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG

        // Check for unique RNTI values and log duplicates
        for (size_t j = 0; j < i; ++j) {
            if (result[j]->RNTI == result[i]->RNTI) {
                FILE* duplicate_log = fopen("duplicate_rnti.log", "a");
                fprintf(duplicate_log, "Duplicate RNTI: %d\n", result[i]->RNTI);
                fclose(duplicate_log);
            }
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Example usage
int main() {
    MemoryPool* pool = create_memory_pool(100);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T** results = (NFAPI_CRC_INDICATION_PDU_T**)malloc(5 * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!results) {
        fprintf(stderr, "Failed to allocate memory for results\n");
        destroy_memory_pool(pool);
        return 1;
    }

    int result_code = allocate_and_populate(results, 5, pool, MAX_SIZE);
    if (result_code != 0) {
        fprintf(stderr, "Allocation failed\n");
    } else {
        // Process the results
    }

    free(results);
    destroy_memory_pool(pool);

    return 0;
}
