MemoryPool memory_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void* custom_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_memory_pool(size_t initial_size) {
    memory_pool.array = custom_malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memory_pool.size = 0;
    memory_pool.allocated_size = initial_size;
    pthread_mutex_init(&memory_pool.lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    pthread_mutex_lock(&memory_pool.lock);

    if (memory_pool.size >= memory_pool.allocated_size) {
        size_t new_size = memory_pool.allocated_size * 2;
        if ((double)new_size / sysconf(_SC_PHYS_PAGES) > MAX_MEMORY_USAGE) {
            fprintf(stderr, "Memory limit approaching\n");
            pthread_mutex_unlock(&memory_pool.lock);
            return NULL;
        }
        memory_pool.array = custom_realloc(memory_pool.array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memory_pool.allocated_size = new_size;
