#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1 MB
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int value;
    long* offset;
    int key;
    char type;
} record;

typedef struct {
    bool valid;
    size_t index;
} extra_metadata;

record* allocate_records(size_t n) {
    if (n * sizeof(record) > MAX_MEMORY) {
        // Handle error: too many records
        return NULL;
    }

    record* records = malloc(n * sizeof(record));
    if (!records) {
        // Handle memory allocation failure
        return NULL;
    }

    long* offsets = malloc(n * sizeof(long));
    if (!offsets) {
        free(records);
        return NULL;
    }

    extra_metadata* metadata = malloc(n * sizeof(extra_metadata));
    if (!metadata) {
        free(offsets);
        free(records);
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        offsets[i] = (long)((char*)records + sizeof(record) * i);
        records[i].offset = &offsets[i];
        records[i].key = i;
        records[i].type = 'R';

        metadata[i].valid = true;
        metadata[i].index = i;
    }

    return records;
}

void free_records(record* records, size_t n) {
    if (records) {
        free(records);
    }
}
