#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/sysinfo.h>

#define MAX_MEMORY_USAGE 0.9

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool;

void initialize_memory_pool(size_t initial_size) {
    memory_pool.pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memory_pool.pool) {
        fprintf(stderr, "Failed to allocate initial memory pool\n");
        exit(EXIT_FAILURE);
    }
    memory_pool.pool_size = initial_size;
    memory_pool.used_count = 0;
    pthread_mutex_init(&memory_pool.lock, NULL);
}

void *allocate_from_memory_pool() {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.used_count >= memory_pool.pool_size) {
        size_t new_size = memory_pool.pool_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T *)realloc(memory_pool.pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            fprintf(stderr, "Failed to reallocate memory pool\n");
            pthread_mutex_unlock(&memory_pool.lock);
            return NULL;
        }
        memory_pool.pool = new_pool;
        memory_pool.pool_size = new_size;
    }
    NFAPI_CRC_INDICATION_PDU_T *ptr = &memory_pool.pool[memory_pool.used_count++];
    pthread_mutex_unlock(&memory_pool.lock);
    return ptr;
}

void free_memory_pool() {
    pthread_mutex_lock(&memory_pool.lock);
    free(memory_pool.pool);
    memory_pool.pool = NULL;
    memory_pool.pool_size = 0;
    memory_pool.used_count = 0;
    pthread_mutex_unlock(&memory_pool.lock);
}

int get_available_memory() {
    struct sysinfo info;
    if (sysinfo(&info) != 0) {
        fprintf(stderr, "Failed to retrieve system information\n");
        return -1;
    }
    return info.freeram * info.mem_unit;
}

void log_memory_usage_warning(int available_memory) {
    int total_memory = get_available_memory();
    double usage_percentage = (double)(total_memory - available_memory) / total_memory;
    if (usage_percentage > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Warning: Memory usage is approaching the limit\n");
    }
}

void *allocate_rnti_from_database() {
    // Simulate database connection and RNTI retrieval
    sleep(1); // Simulate latency
    return malloc(sizeof(int)); // Simulate successful allocation
}

void free_rnti_to_database(void *rnti) {
    free(rnti);
}

void process_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu, int rnti) {
    // Process CRC indication with RNTI
    pdu->RNTI = rnti;
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
}

void *worker_thread(void *arg) {
    int thread_id = *(int *)arg;
    NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_from_memory_pool();
    if (!pdu) {
        fprintf(stderr, "Failed to allocate memory for PDU in thread %d\n", thread_id);
        return NULL;
    }
    int rnti = (int)allocate_rnti_from_database();
    if (!rnti) {
        fprintf(stderr, "Failed to retrieve RNTI from database in thread %d\n", thread_id);
        free_memory_pool();
        return NULL;
    }
    process_crc_indication(pdu, rnti);
    free_rnti_to_database((void *)rnti);
    free_memory_pool();
    return NULL;
}

int main() {
    int num_threads = 10; // Example number of threads
    pthread_t threads[num_threads];
    int thread_ids[num_threads];

    initialize_memory_pool(num_threads);

    for (int i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, worker_thread, &thread_ids[i]) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_threads; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread %d\n", i);
            return EXIT_FAILURE;
        }
    }

    free_memory_pool();
    return EXIT_SUCCESS;
}
