void init_records(int n) {
    pthread_mutex_lock(&mutex);
    if (records != NULL) {
        free(records);
    }
    records = (Record*)malloc(n * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    record_count = n;
    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        records[i].offset = (long*)malloc(sizeof(long));
        *records[i].offset = i;
        records[i].key = i;
    }
    pthread_mutex_unlock(&mutex);
}

void update_record(int key, int new_value) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            records[i].value = new_value;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void delete_record(int key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            free(records[i].offset);
            records[i] = records[record_count - 1];
            record_count--;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

