#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int allocate_and_populate_array(int N, size_t max_size, FILE* log_file) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(log_file, "Memory allocation failed for %d structures\n", N);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    unsigned short rnti_set[MAX_RNTI] = {0};
    int unique_rntis = 0;

    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        while (1) {
            unsigned short rnti = rand() % MAX_RNTI;
            if (!rnti_set[rnti]) {
                array[i].RX_UE_INFORMATION_TAG = i + 1;
                array[i].RNTI = rnti;
                array[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 0 : 1;
                rnti_set[rnti] = 1;
                unique_rntis++;
                break;
            }
        }

        if ((i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T) > max_size) {
            fprintf(log_file, "Memory limit exceeded after %d structures\n", i);
            free(array);
            pthread_mutex_unlock(&mutex);
            return -2;
        }
    }

    if (unique_rntis != N) {
        fprintf(log_file, "Duplicate RNTI assignments detected\n");
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}
