#include <pthread.h>

#define RECORD_COUNT 100
#define RANDOM_RANGE 1000

typedef struct {
    int value;
} record;

void* initialize_records(void* arg) {
    long* offsets = (long*)malloc(RECORD_COUNT * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return NULL;
    }

    int* keys = (int*)malloc(RECORD_COUNT * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        return NULL;
    }

    record* records = (record*)malloc(RECORD_COUNT * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < RECORD_COUNT; i++) {
        records[i].value = rand() % RANDOM_RANGE;
    }

    const char* data_dir = getenv("DATA_DIR");
    if (!data_dir) {
        char home_path[1024];
        if (getenv("HOME") && snprintf(home_path, sizeof(home_path), "%s/data_store", getenv("HOME")) > 0) {
            mkdir(home_path, 0755);
            setenv("DATA_DIR", home_path, 1);
            data_dir = home_path;
        } else {
            fprintf(stderr, "Failed to create data directory\n");
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
    }

    // Periodic check for directory creation or environment variable setting
    DIR* dir = opendir(data_dir);
    if (!dir) {
        fprintf(stderr, "Failed to open directory: %s\n", data_dir);
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }
    closedir(dir);

    // Thread-safe mechanism for concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    // Perform operations that require thread safety here
    pthread_mutex_unlock(&mutex);

    return records;
}

int main() {
    void* result = initialize_records(NULL);
    if (result) {
        record* records = (record*)result;
        for (int i = 0; i < RECORD_COUNT; i++) {
            printf("Record %d: Value = %d\n", i, records[i].value);
        }
        free(records);
    }
    return 0;
}
