    if (N <= 0 || max_rnti <= 0) {
        return NULL; // Invalid input
    }

    NFAPI_RX_PDU_T *pdus = (NFAPI_RX_PDU_T*)malloc(N * sizeof(NFAPI_RX_PDU_T));
    if (!pdus) {
        *total_created = 0;
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    int current_rnti = rand() % max_rnti + 1;
    int created_count = 0;

    for (int i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = i + 1;
        pdus[i].RNTI = current_rnti;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly generate CRC flag

        // Ensure no two consecutive PDUs have the same RNTI
        do {
            current_rnti = rand() % max_rnti + 1;
        } while (current_rnti == pdus[i - 1].RNTI);

        created_count++;
    }

    *total_created = created_count;
    return pdus;
}
