        String key = generateKey(character);
        AttackData attackData = attackCache.get(key);

        if (attackData == null || !isDataFresh(attackData)) {
            // Fallback to default or random attack if data is stale
            return new DefaultAttack();
        }

        // Select attack based on character attributes and compatibility
        return chooseBestAttack(attackData, character);
    }

