        keys.resize(10);
        records.resize(10);

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, value_range);

        for (int i = 0; i < 10; ++i) {
            offsets[i] = i * 100;
            keys[i] = i * 10;
            records[i].value = dis(gen);
        }
    }

    void runCycle() {
        initializeData();
        int duration = std::uniform_int_distribution<>(1, 5)(std::mt19937(std::random_device{}()));
        std::this_thread::sleep_for(std::chrono::seconds(duration));
        shutdownService();
    }

    void shutdownService() {
        std::lock_guard<std::mutex> lock(mtx);
        // Serialize and send data to messaging system
        for (int i = 0; i < offsets.size(); ++i) {
            std::cout << "Sending offset: " << offsets[i] << ", key: " << keys[i] << ", value: " << records[i].value << " to " << messaging_endpoint << std::endl;
        }
    }
};

int main() {
    int range = 1000;
    std::string endpoint = "http://example.com/messaging";
    ServiceManager manager(range, endpoint);
    manager.startService();
    return 0;
}
