#define MAX_RECORDS 10000
#define MEMORY_THRESHOLD 500000

typedef struct {
    int *data;
    size_t capacity;
    size_t size;
} RecordCollection;

void initialize_records(RecordCollection *collection, size_t initial_size, int min_value, int max_value) {
    if (initial_size > MAX_RECORDS || initial_size * sizeof(int) > MEMORY_THRESHOLD) {
        // Log memory allocation failure
        return;
    }
    collection->data = malloc(initial_size * sizeof(int));
    if (!collection->data) {
        // Log memory allocation failure
        return;
    }
    collection->capacity = initial_size;
    collection->size = 0;

    srand(time(NULL));
    for (size_t i = 0; i < initial_size; ++i) {
        collection->data[i] = min_value + rand() % (max_value - min_value + 1);
    }
}

void resize_records(RecordCollection *collection, size_t new_capacity) {
    if (new_capacity > MAX_RECORDS || new_capacity * sizeof(int) > MEMORY_THRESHOLD) {
        // Log memory allocation failure
        return;
    }
    int *new_data = realloc(collection->data, new_capacity * sizeof(int));
    if (!new_data) {
        // Log memory allocation failure
        return;
    }
    collection->data = new_data;
    collection->capacity = new_capacity;
}

void add_record(RecordCollection *collection, int value) {
    if (collection->size == collection->capacity) {
        resize_records(collection, collection->capacity * 2);
    }
    collection->data[collection->size++] = value;
}

void free_records(RecordCollection *collection) {
    free(collection->data);
    collection->data = NULL;
    collection->capacity = 0;
    collection->size = 0;
}
