enum LogLevel { DEBUG, INFO, WARNING, ERROR, CRITICAL };

struct LoggingConfig {
    LogLevel log_level;
    std::string file_path;
    size_t max_file_size;
    int rotation_interval;
    std::unordered_set<std::string> logging_node_ids;
};

std::mutex config_mutex;

bool validateLoggingConfig(const Json::Value& config) {
    if (!config.isObject()) return false;

    std::lock_guard<std::mutex> lock(config_mutex);

    auto log_level = config.get("log_level", "").asString();
    if (log_level != "DEBUG" && log_level != "INFO" && log_level != "WARNING" && log_level != "ERROR" && log_level != "CRITICAL") return false;

    auto file_path = config.get("file_path", "").asString();
    std::ifstream file(file_path);
    if (!file.is_open()) return false;

    auto max_file_size = config.get("max_file_size", 0).asUInt64();
    if (max_file_size > 1024 * 1024 * 1024) return false; // 1GB

    auto rotation_interval = config.get("rotation_interval", -1).asInt();
    if (rotation_interval < 0 || rotation_interval > 86400) return false;

    auto node_ids = config.get("logging_node_ids", Json::Value(Json::arrayValue));
    std::unordered_set<std::string> unique_ids;
    for (const auto& id : node_ids) {
        if (!id.isString() || !unique_ids.insert(id.asString()).second) return false; // Duplicate ID
    }

    return true;
}

int main() {
    Json::Value config = Json::parse("{\"log_level\":\"INFO\",\"file_path\":\"/var/log/app.log\",\"max_file_size\":512,\"rotation_interval\":3600,\"logging_node_ids\":[\"node1\",\"node2\"]}");
    if (validateLoggingConfig(config)) {
        std::cout << "Configuration is valid." << std::endl;
    } else {
        std::cout << "Configuration is invalid." << std::endl;
    }
    return 0;
}
