#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} UE_INFO;

int find_largest(UE_INFO *array, int size) {
    int largest = array[0].RX_UE_INFORMATION_TAG;
    for (int i = 1; i < size; i++) {
        if (array[i].RX_UE_INFORMATION_TAG > largest) {
            largest = array[i].RX_UE_INFORMATION_TAG;
        }
    }
    return largest;
}

void *process_integers(void *arg) {
    int *input = (int *)arg;
    UE_INFO *array = malloc(sizeof(UE_INFO) * MAX_SIZE);
    if (!array) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    int size = 0;
    while (*input != -1 && size < MAX_SIZE) {
        array[size].RX_UE_INFORMATION_TAG = *input++;
        array[size].RNTI = rand() % (MAX_RNTI + 1);
        array[size].CRC_INDICATION_REL8_TAG = rand() % 2;
        size++;
    }

    if (*input != -1) {
        fprintf(stderr, "Too many integers provided\n");
        exit(EXIT_FAILURE);
    }

    int largest = find_largest(array, size);
    printf("Largest integer: %d\n", largest);

    free(array);
    return NULL;
}

int main() {
    pthread_t thread;
    int input[MAX_SIZE + 1];
    int i = 0;

    while (scanf("%d", &input[i]) == 1 && i < MAX_SIZE) {
        if (input[i] == -1) break;
        i++;
    }
    input[i] = -1;

    pthread_create(&thread, NULL, process_integers, input);
    pthread_join(thread, NULL);

    return 0;
}
