#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <dirent.h>
#include <pthread.h>

#define RECORD_SIZE sizeof(record)
#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

void* initialize_records(void* arg) {
    long* offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return NULL;
    }

    int* keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        return NULL;
    }

    record* records = (record*)malloc(MAX_RECORDS * RECORD_SIZE);
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize offsets and keys
    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = i * 1024;
        keys[i] = rand() % 1000;
    }

    // Check if DATA_DIR is set, if not create a new directory
    char* data_dir = getenv("DATA_DIR");
    if (!data_dir) {
        char home_dir[1024];
        snprintf(home_dir, sizeof(home_dir), "%s/.data_store", getenv("HOME"));
        mkdir(home_dir, 0755);
        setenv("DATA_DIR", home_dir, 1);
        data_dir = home_dir;
    }

    // Serialize records to a binary file
    FILE* file = fopen(data_dir, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_mutex_lock(&lock);
        fwrite(&records[i], RECORD_SIZE, 1, file);
        pthread_mutex_unlock(&lock);
    }

    fclose(file);
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, initialize_records, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(thread, NULL);

    return 0;
}
