    void* (*decompress)(const char*, size_t, size_t*);
    int level;
    int mode;
} CompressionConfig;

CompressionConfig* create_compression_config(CompressionAlgorithm algorithm, int level, int mode) {
    CompressionConfig* config = (CompressionConfig*)malloc(sizeof(CompressionConfig));
    if (!config) return NULL;

    switch (algorithm) {
        case COMPRESSION_LZ4:
            config->compress = LZ4_compress_default;
            config->decompress = LZ4_decompress_safe;
            break;
        case COMPRESSION_ZLIB:
            config->compress = compress;
            config->decompress = uncompress;
            break;
        case COMPRESSION_SNAPPY:
            config->compress = snappy_compress;
            config->decompress = snappy_uncompress;
            break;
        default:
            free(config);
            return NULL;
    }

    config->level = level;
    config->mode = mode;

    return config;
}

void destroy_compression_config(CompressionConfig* config) {
    if (config) {
        free(config);
    }
