from concurrent.futures import ThreadPoolExecutor
from cryptography.fernet import Fernet

# Mock external data sources and notification service
class ExternalDataSource:
    def fetch_data(self):
        # Simulate fetching data from cloud storage
        return {"storage_settings": "default"}

class NotificationService:
    def send_notification(self, message):
        # Simulate sending a notification to administrators
        print(f"Notification: {message}")

# Singleton pattern for caching
class Cache:
    _instance = None

    @staticmethod
    def get_instance():
        if Cache._instance is None:
            Cache._instance = Cache()
        return Cache._instance

    def __init__(self):
        self.cache = {}

    def get_data(self, key):
        return self.cache.get(key)

    def set_data(self, key, value):
        self.cache[key] = value

# Singleton pattern for configuration
class Configuration:
    _instance = None

    @staticmethod
    def get_instance():
        if Configuration._instance is None:
            Configuration._instance = Configuration()
        return Configuration._instance

    def __init__(self):
        self.config = {}

    def update_config(self, new_config):
        self.config.update(new_config)

# Singleton pattern for logging
class Logger:
    _instance = None

    @staticmethod
    def get_instance():
        if Logger._instance is None:
            Logger._instance = Logger()
        return Logger._instance

    def log(self, message):
        print(f"Log: {message}")

# Main script class
class StorageConfigurator:
    def __init__(self, data_sources, notification_service):
        self.data_sources = data_sources
        self.notification_service = notification_service
        self.cache = Cache.get_instance()
        self.config = Configuration.get_instance()
        self.logger = Logger.get_instance()

    def fetch_data(self):
        for source in self.data_sources:
            key = f"data_{id(source)}"
            cached_data = self.cache.get_data(key)
            if cached_data is None:
                data = source.fetch_data()
                self.cache.set_data(key, data)
                return data
            else:
                return cached_data

    def update_storage_config(self):
        new_config = self.fetch_data()
        try:
            self.config.update_config(new_config)
            self.logger.log("Storage configuration updated successfully.")
            self.notification_service.send_notification("Storage configuration updated successfully.")
        except Exception as e:
            self.logger.log(f"Failed to update storage configuration: {e}")
            self.notification_service.send_notification(f"Failed to update storage configuration: {e}")

    def run(self):
        with ThreadPoolExecutor(max_workers=5) as executor:
            for _ in range(10):  # Simulate multiple nodes
                executor.submit(self.update_storage_config)

# Usage example
if __name__ == "__main__":
    data_sources = [ExternalDataSource()]
    notification_service = NotificationService()
    configurator = StorageConfigurator(data_sources, notification_service)
    configurator.run()
```

