#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    double value;
    char* category;
} Item;

typedef struct Node {
    Item item;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ItemCollection;

ItemCollection* create_collection() {
    ItemCollection* collection = (ItemCollection*)malloc(sizeof(ItemCollection));
    if (collection) {
        collection->head = NULL;
        pthread_mutex_init(&collection->lock, NULL);
    }
    return collection;
}

void add_item(ItemCollection* collection, Item item) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node) {
        new_node->item = item;
        new_node->next = collection->head;
        collection->head = new_node;
    }
}

void update_timestamps(ItemCollection* collection, long start_time, long end_time, long increment) {
    pthread_mutex_lock(&collection->lock);
    Node* current = collection->head;
    while (current) {
        if (current->item.timestamp >= start_time && current->item.timestamp <= end_time) {
            current->item.timestamp += increment;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
}

void free_collection(ItemCollection* collection) {
    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
