    std::time_t timestamp;
};

class DataProcessingService {
public:
    void addOrUpdateRecord(int key, long offset, int newValue) {
        std::lock_guard<std::mutex> lock(mutex_);
        records_[key] = {newValue, std::time(nullptr)};
    }

    Record getRecord(int key) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = records_.find(key);
        if (it != records_.end()) {
            return it->second;
        }
        throw std::runtime_error("Record not found");
    }

    void processBatch(long startOffset, long endOffset) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& record : records_) {
            if (record.second.timestamp >= startOffset && record.second.timestamp <= endOffset) {
                record.second.value = generateRandomValue();
                record.second.timestamp = std::time(nullptr);
            }
        }
    }

private:
    std::unordered_map<int, Record> records_;
    mutable std::mutex mutex_;

    int generateRandomValue() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(INT_MIN, INT_MAX);
        return dis(gen);
    }
};

class MessagingSystem {
public:
    void sendMessage(const std::string& message) {
        // Simulate sending a message
        std::cout << "Sending message: " << message << std::endl;
    }

    bool sendWithRetry(const std::string& message, int maxRetries = 3) {
        for (int i = 0; i <= maxRetries; ++i) {
            try {
                sendMessage(message);
                return true;
            } catch (const std::exception& e) {
                if (i == maxRetries) throw;
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        }
        return false;
    }
};

class Logger {
public:
    void log(const std::string& message) {
        // Simulate logging
        std::cout << "Log: " << message << std::endl;
    }
};

int main() {
    DataProcessingService service;
    MessagingSystem messaging;
    Logger logger;

    try {
        for (int i = 0; i < 10; ++i) {
            service.addOrUpdateRecord(i, std::time(nullptr), i * 10);
        }

        long startOffset = std::time(nullptr) - 3600; // One hour ago
        long endOffset = std::time(nullptr);

        service.processBatch(startOffset, endOffset);

        for (int i = 0; i < 10; ++i) {
            Record record = service.getRecord(i);
            logger.log("Updated record: " + std::to_string(record.value));
        }

        if (!messaging.sendWithRetry("Batch processed successfully")) {
            logger.log("Failed to send batch processing message");
        }
    } catch (const std::exception& e) {
        logger.log("Error: " + std::string(e.what()));
    }

    return 0;
}
