using System.Threading.Tasks;

public class DynamicRangeGenerator
{
    private Random _random = new Random();
    private double _minValue;
    private double _maxValue;
    private ILogger _logger;

    public DynamicRangeGenerator(ILogger logger)
    {
        _logger = logger;
    }

    public void SetRange(double minValue, double maxValue)
    {
        if (minValue >= maxValue || minValue == 0 || maxValue == 0)
        {
            throw new ArgumentException("Invalid range values.");
        }
        _minValue = minValue;
        _maxValue = maxValue;
        _logger.Log($"Range set to [{_minValue}, {_maxValue}].");
    }

    public double GenerateRandomFloat(bool inclusive = true, bool exclusiveMax = false)
    {
        double value = _random.NextDouble() * (_maxValue - _minValue) + _minValue;
        if (inclusive && !exclusiveMax)
        {
            value = Math.Min(value, _maxValue);
        }
        return value;
    }

    public int GenerateRandomInt(bool inclusive = true, bool exclusiveMax = false)
    {
        double minValue = inclusive ? _minValue : _minValue + 1;
        double maxValue = exclusiveMax ? _maxValue - 1 : _maxValue;
        if (minValue > maxValue)
        {
            throw new InvalidOperationException("Invalid range for integer generation.");
        }
        return (int)Math.Round(GenerateRandomFloat(inclusive, exclusiveMax));
    }

    public void SaveState(string filePath)
    {
        try
        {
            // Serialize state to file
            _logger.Log($"Saving state to {filePath}.");
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to save state: {ex.Message}");
        }
    }

    public void LoadState(string filePath)
    {
        try
        {
            // Deserialize state from file
            _logger.Log($"Loading state from {filePath}.");
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to load state: {ex.Message}");
        }
    }
}

public interface ILogger
{
    void Log(string message);
    void LogError(string error);
}

public class ConsoleLogger : ILogger
{
    public void Log(string message)
    {
        Console.WriteLine(message);
    }

    public void LogError(string error)
    {
        Console.Error.WriteLine(error);
    }
}
