            // Logic to batch serialize event logs asynchronously
        }
    }
}

class MetricsCollector {
    private final Object lock = new Object();
    private int putCount;
    private int removeCount;

    public void recordMetric(String operation, int count) {
        synchronized (lock) {
            if ("put".equals(operation)) {
                putCount += count;
            } else if ("remove".equals(operation)) {
                removeCount += count;
            }
            // Logic to handle metrics collection and reporting
        }
    }

    public void reportMetrics() {
        System.out.println("Put operations: " + putCount);
        System.out.println("Remove operations: " + removeCount);
    }
}
