#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    char ip[16];
    int port;
    int status;
} ConnectionAttempt;

typedef struct QueueNode {
    ConnectionAttempt data;
    struct QueueNode* next;
} QueueNode;

typedef struct {
    QueueNode* front;
    QueueNode* rear;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} ConnectionQueue;

void initConnectionQueue(ConnectionQueue* queue) {
    queue->front = queue->rear = NULL;
    queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

void enqueue(ConnectionQueue* queue, const ConnectionAttempt* attempt) {
    QueueNode* newNode = (QueueNode*)malloc(sizeof(QueueNode));
    if (!newNode) return; // Handle memory allocation failure

    newNode->data = *attempt;
    newNode->next = NULL;

    pthread_mutex_lock(&queue->mutex);
    if (queue->rear == NULL) {
        queue->front = queue->rear = newNode;
    } else {
        queue->rear->next = newNode;
        queue->rear = newNode;
    }
    queue->size++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

void dequeue(ConnectionQueue* queue, ConnectionAttempt* attempt) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->front == NULL) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    QueueNode* temp = queue->front;
    *attempt = temp->data;
    queue->front = queue->front->next;
    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);
    queue->size--;
    pthread_mutex_unlock(&queue->mutex);
}

void destroyConnectionQueue(ConnectionQueue* queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->front != NULL) {
        QueueNode* temp = queue->front;
        queue->front = queue->front->next;
        free(temp);
    }
    queue->rear = NULL;
    queue->size = 0;
    pthread_mutex_unlock(&queue->mutex);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
}

// Example usage
int main() {
    ConnectionQueue queue;
    initConnectionQueue(&queue);

    ConnectionAttempt attempt1 = {"192.168.1.1", 8080, 1};
    enqueue(&queue, &attempt1);

    ConnectionAttempt attempt2 = {"192.168.1.2", 8081, 0};
    enqueue(&queue, &attempt2);

    ConnectionAttempt result;
    dequeue(&queue, &result);
    printf("Dequeued: IP=%s, Port=%d, Status=%d\n", result.ip, result.port, result.status);

    destroyConnectionQueue(&queue);
    return 0;
}
```

This code provides a basic implementation of a thread-safe queue for managing connection attempts. It includes functions to initialize, enqueue, dequeue, and destroy the queue. The example usage in `main` demonstrates how to use these functions. Note that this is a simplified version and does not include advanced features like dynamic resizing or external monitoring service integration as described in the task.']

