// Define the record structure
typedef struct {
    int key;
    long offset;
    int value;
} Record;

// Function to initialize the records with random values
Record* init_records(int size, int range, unsigned int seed) {
    if (size <= 0 || range <= 0) {
        return NULL; // Invalid input
    }

    Record* records = (Record*)malloc(size * sizeof(Record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    srand(seed);
    for (int i = 0; i < size; ++i) {
        records[i].key = rand() % range;
        records[i].offset = (long)(rand() % range);
        records[i].value = rand() % range;
    }

    return records;
}

// Function to free the allocated memory
void free_records(Record* records, int size) {
    if (records) {
        free(records);
    }
}

// Function to verify the integrity of the data structure
int verify_records(const Record* records, int size, int range) {
    for (int i = 0; i < size; ++i) {
        if (records[i].key < 0 || records[i].key >= range ||
            records[i].offset < 0 || records[i].offset >= range ||
            records[i].value < 0 || records[i].value >= range) {
            return 0; // Invalid value found
        }
    }
    return 1; // All values are valid
}

// Example usage
int main() {
    int size = 1000;
    int range = 10000;
    unsigned int seed = time(NULL);

    Record* records = init_records(size, range, seed);
    if (records) {
        if (verify_records(records, size, range)) {
            printf("Records initialized and verified successfully.\n");
        } else {
            printf("Error: Invalid values found in records.\n");
        }
        free_records(records, size);
    } else {
        printf("Failed to initialize records.\n");
    }

    return 0;
}
```

