import java.util.concurrent.TimeUnit;

public class StringHasher {

    private static final Map<String, String> cache = new ConcurrentHashMap<>();
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private static final ExternalAPIService apiService = new ExternalAPIService();

    public static Map<String, String> processStrings(List<String> strings) {
        Map<String, CompletableFuture<String>> futures = new HashMap<>();

        for (String str : strings) {
            if (!cache.containsKey(str)) {
                CompletableFuture<String> future = CompletableFuture.supplyAsync(() -> hashString(str), executor);
                future.thenAccept(hash -> cache.put(str, hash));
                futures.put(str, future);
            } else {
                futures.put(str, CompletableFuture.completedFuture(cache.get(str)));
            }
        }

        Map<String, String> result = new HashMap<>();
        for (Map.Entry<String, CompletableFuture<String>> entry : futures.entrySet()) {
            try {
                result.put(entry.getKey(), entry.getValue().get());
            } catch (Exception e) {
                // Handle exception
            }
        }

        return result;
    }

    private static String hashString(String str) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(str.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            // Handle exception
            return null;
        }
    }

