import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class HashProcessor {

    private static final int MAX_HASHES_PER_REQUEST = 100;
    private static final Set<String> processedHashes = new HashSet<>();

    public List<String> processBatch(List<String> batch) {
        if (batch == null || batch.isEmpty()) {
            return List.of();
        }

        List<String> hashes = batch.stream()
                .limit(MAX_HASHES_PER_REQUEST)
                .map(this::generateMD5Hash)
                .filter(hash -> hash != null && processedHashes.add(hash))
                .toList();

        return hashes;
    }

    private String generateMD5Hash(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            // Handle exception, possibly log and retry or fallback
            return null;
        }
    }

    public static void main(String[] args) {
        HashProcessor processor = new HashProcessor();
        List<String> batch = List.of("example1", "example2", "example3");
        List<String> hashes = processor.processBatch(batch);
        System.out.println(hashes);
    }
}
```

