#define MAX_RECORDS 1000

typedef struct {
    int key;
    int value;
    char error[256];
    double timestamp;
    int status;
} Record;

Record* create_records(int max_size, int range_start, int range_end, int *counter) {
    Record *records = (Record *)malloc(max_size * sizeof(Record));
    if (!records) {
        *counter = 0;
        return NULL;
    }

    time_t now = time(NULL);
    srand(now);

    for (*counter = 0; *counter < max_size; (*counter)++) {
        records[*counter].key = rand() % (range_end - range_start + 1) + range_start;
        records[*counter].value = rand();
        snprintf(records[*counter].error, sizeof(records[*counter].error), "%s", ctime(&now));
        records[*counter].timestamp = (double)clock() / CLOCKS_PER_SEC;
        records[*counter].status = 1; // Assuming all allocations succeed for simplicity
    }

    return records;
}

void free_records(Record *records, int counter) {
    if (records) {
        free(records);
    }
}

int main() {
    int max_size = 500;
    int range_start = 1;
    int range_end = 1000;
    int counter;

    Record *records = create_records(max_size, range_start, range_end, &counter);

    if (records) {
        printf("Successfully created %d records.\n", counter);
        free_records(records, counter);
    } else {
        printf("Failed to create records.\n");
    }

    return 0;
