int initialize_and_populate_channels(MAC_TransportChannelInfo *channels, int num_channels) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_channels; i++) {
        channels[i].rnti = i + 1; // Assign unique rnti values
        channels[i].config.logicalChannelIdentity = i % MAX_LOGICAL_CHANNEL_IDENTITY;

        // Validate configuration against network constraints
        if (channels[i].rnti > MAX_RNTI || channels[i].config.logicalChannelIdentity >= MAX_LOGICAL_CHANNEL_IDENTITY) {
            fprintf(stderr, "Validation error: Invalid rnti or logicalChannelIdentity\n");
            pthread_mutex_unlock(&mutex);
            return -1;
        }

        // Log the addition of each cryptographic primitive
        printf("Added channel with rnti %d and logicalChannelIdentity %d\n", channels[i].rnti, channels[i].config.logicalChannelIdentity);
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

int main() {
    MAC_TransportChannelInfo channels[MAX_RNTI];
    int num_channels = MAX_RNTI;

    if (initialize_and_populate_channels(channels, num_channels) == 0) {
        printf("Initialization successful\n");
    } else {
        printf("Initialization failed\n");
    }

    return 0;
}
