#include <string.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FIELD_LENGTH 256

typedef struct {
    char *data;
} Record;

Record* parseAndAnalyzeCSV(const char *filename, const char delimiter, int maxFieldLength) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    Record *records = NULL;
    size_t recordsSize = 0;
    size_t recordsCapacity = 16;

    while (1) {
        char line[MAX_LINE_LENGTH];
        if (!fgets(line, sizeof(line), file)) break;

        // Trim leading and trailing whitespace
        char *start = line;
        while (*start == ' ') start++;
        char *end = line + strlen(line) - 1;
        while (end > start && *end == ' ') end--;
        *(end + 1) = '\0';

        if (strlen(start) == 0) continue; // Skip empty lines

        Record newRecord;
        newRecord.data = malloc((end - start + 2) * sizeof(char));
        if (!newRecord.data) {
            perror("Failed to allocate memory for record");
            free(records);
            fclose(file);
            return NULL;
        }
        strncpy(newRecord.data, start, end - start + 1);
        newRecord.data[end - start + 1] = '\0';

        // Truncate fields exceeding maxFieldLength
        char *field = strtok(newRecord.data, &delimiter);
        while (field) {
            if (strlen(field) > maxFieldLength) {
                field[maxFieldLength] = '\0';
            }
            field = strtok(NULL, &delimiter);
        }

        recordsSize++;
        if (recordsSize >= recordsCapacity) {
            recordsCapacity *= 2;
            records = realloc(records, recordsCapacity * sizeof(Record));
            if (!records) {
                perror("Failed to reallocate memory for records");
                free(newRecord.data);
                fclose(file);
                return NULL;
            }
        }
        records[recordsSize - 1] = newRecord;
    }

    fclose(file);

    // Process input from standard input
    while (1) {
        char line[MAX_LINE_LENGTH];
        if (!fgets(line, sizeof(line), stdin)) break;

        // Trim leading and trailing whitespace
        char *start = line;
        while (*start == ' ') start++;
        char *end = line + strlen(line) - 1;
        while (end > start && *end == ' ') end--;
        *(end + 1) = '\0';

        if (strcmp(start, "END") == 0) break;

        // Process the input row
        // ...

    }

    // Free allocated memory
    for (size_t i = 0; i < recordsSize; i++) {
        free(records[i].data);
    }
    free(records);

    return NULL;
}
