void processAndAnalyzeData(int maxKeys, int maxValue, int minValue, const char* inputFilePath) {
    long* offsets = (long*)malloc(maxKeys * sizeof(long));
    int* keys = (int*)malloc(maxKeys * sizeof(int));
    record* records = (record*)malloc(maxKeys * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize arrays
    for (int i = 0; i < maxKeys; ++i) {
        offsets[i] = i;
        keys[i] = rand() % maxValue + minValue;
        records[i].value = rand() % (maxValue - minValue + 1);
    }

    // Read input data and analyze
    FILE* file = fopen(inputFilePath, "r");
    if (!file) {
        fprintf(stderr, "Failed to open input file\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    int* auxArray = (int*)malloc(1024 * sizeof(int)); // Assuming a buffer size of 1024
    if (!auxArray) {
        fprintf(stderr, "Memory allocation failed for auxiliary array\n");
        fclose(file);
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    int auxIndex = 0;
    while (fscanf(file, "%d", &auxArray[auxIndex]) == 1) {
        if (auxIndex >= 1023) {
            // Handle buffer overflow
            fprintf(stderr, "Input data exceeds buffer size\n");
            break;
        }
        ++auxIndex;
    }

    fclose(file);

    int largestValue = auxArray[0];
    for (int i = 1; i < auxIndex; ++i) {
        if (auxArray[i] > largestValue) {
            largestValue = auxArray[i];
        }
    }

    printf("Largest value in input data: %d\n", largestValue);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(auxArray);
}
