#include <time.h>

#define MAX_KEYS 1000000
#define RECORD_RANGE 1000

typedef struct {
    int value;
} record;

typedef struct {
    int parent;
    int rank;
} UnionFindNode;

void initializeDataStructures(long **offsets, int **keys, record **records, int numRecords) {
    *offsets = (long *)malloc(numRecords * sizeof(long));
    *keys = (int *)malloc(numRecords * sizeof(int));
    *records = (record *)malloc(numRecords * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize offsets
    for (int i = 0; i < numRecords; i++) {
        (*offsets)[i] = i * 2; // Simulating data sparsity with gaps
    }

    // Initialize keys and records
    srand(time(NULL));
    int keySet[MAX_KEYS];
    for (int i = 0; i < MAX_KEYS; i++) {
        keySet[i] = i;
    }
    shuffle(keySet, MAX_KEYS);

    for (int i = 0; i < numRecords; i++) {
        (*keys)[i] = keySet[i % MAX_KEYS];
        (*records)[i].value = rand() % RECORD_RANGE + 1;

        // Ensure no two consecutive records have the same value
        if (i > 0 && (*records)[i].value == (*records)[i - 1].value) {
            (*records)[i].value = ((*records)[i].value + 1) % RECORD_RANGE;
        }
    }

    // Initialize Union-Find structure
    UnionFindNode *uf = (UnionFindNode *)malloc(numRecords * sizeof(UnionFindNode));
    for (int i = 0; i < numRecords; i++) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }

    // Perform disjointness checks
    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < numRecords - 1; i++) {
        start = clock();
        int rootI = find(uf, i);
        int rootJ = find(uf, i + 1);

        if (rootI == rootJ) {
            printf("Non-disjoint pair found between records %d and %d\n", i, i + 1);
        }

        end = clock();
        cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;
        printf("Time taken for comparison %d: %.2f ms\n", i, cpu_time_used * 1000);
    }

    // Free allocated memory
    free(*offsets);
    free(*keys);
    free(*records);
    free(uf);
}

void shuffle(int arr[], int n) {
    srand(time(NULL));
    for (int i = n - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

int find(UnionFindNode *uf, int x) {
    if (uf[x].parent != x) {
        uf[x].parent = find(uf, uf[x].parent); // Path compression
    }
    return uf[x].parent;
}
