#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    size_t offset;
    void* metadata;
} Record;

typedef struct Dataset {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Dataset;

Dataset* create_dataset(size_t initial_capacity) {
    Dataset* dataset = (Dataset*)malloc(sizeof(Dataset));
    if (!dataset) return NULL;

    dataset->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!dataset->records) {
        free(dataset);
        return NULL;
    }

    dataset->capacity = initial_capacity;
    dataset->size = 0;
    pthread_mutex_init(&dataset->lock, NULL);

    return dataset;
}

void destroy_dataset(Dataset* dataset) {
    for (size_t i = 0; i < dataset->size; ++i) {
        free(dataset->records[i]->metadata);
        free(dataset->records[i]);
    }
    free(dataset->records);
    pthread_mutex_destroy(&dataset->lock);
    free(dataset);
}

int insert_record(Dataset* dataset, int key, size_t offset, void* metadata) {
    pthread_mutex_lock(&dataset->lock);

    if (dataset->size == dataset->capacity) {
        Record** new_records = (Record**)realloc(dataset->records, dataset->capacity * 2 * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&dataset->lock);
            return -1;
        }
        dataset->records = new_records;
        dataset->capacity *= 2;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&dataset->lock);
        return -1;
    }

    record->key = key;
    record->offset = offset;
    record->metadata = metadata;

    dataset->records[dataset->size++] = record;

    pthread_mutex_unlock(&dataset->lock);
    return 0;
}

int delete_record(Dataset* dataset, int key) {
    pthread_mutex_lock(&dataset->lock);

    for (size_t i = 0; i < dataset->size; ++i) {
        if (dataset->records[i]->key == key) {
            free(dataset->records[i]->metadata);
            free(dataset->records[i]);
            for (size_t j = i; j < dataset->size - 1; ++j) {
                dataset->records[j] = dataset->records[j + 1];
            }
            --dataset->size;
            pthread_mutex_unlock(&dataset->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&dataset->lock);
    return -1;
}

Record* lookup_record(Dataset* dataset, int key) {
    pthread_mutex_lock(&dataset->lock);

    for (size_t i = 0; i < dataset->size; ++i) {
        if (dataset->records[i]->key == key) {
            Record* record = dataset->records[i];
            pthread_mutex_unlock(&dataset->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&dataset->lock);
    return NULL;
}

void compact_dataset(Dataset* dataset) {
    pthread_mutex_lock(&dataset->lock);

    Record** new_records = (Record**)realloc(dataset->records, dataset->size * sizeof(Record*));
    if (!new_records) {
        pthread_mutex_unlock(&dataset->lock);
        return;
    }
    dataset->records = new_records;

    pthread_mutex_unlock(&dataset->lock);
}

int update_dataset(Dataset* dataset, int key, size_t offset, void* metadata) {
    Record* record = lookup_record(dataset, key);
    if (!record) return -1;

    free(record->metadata);
    record->offset = offset;
    record->metadata = metadata;

    return 0;
}
