#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    float weight;
} Record;

typedef struct memory_pool {
    size_t block_size;
    size_t num_blocks;
    void* blocks;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct hash_table_entry {
    int key;
    Record* record;
    struct hash_table_entry* next;
} HashTableEntry;

typedef struct hash_table {
    size_t size;
    HashTableEntry** entries;
    pthread_mutex_t lock;
} HashTable;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = malloc(block_size * num_blocks);
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->blocks);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

HashTableEntry** create_hash_table(size_t size) {
    HashTableEntry** entries = (HashTableEntry**)calloc(size, sizeof(HashTableEntry*));
    if (!entries) return NULL;

    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_init(&entries[i]->lock, NULL);
    }

    return entries;
}

void destroy_hash_table(HashTableEntry** entries, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        HashTableEntry* entry = entries[i];
        while (entry) {
            HashTableEntry* next = entry->next;
            free(entry);
            entry = next;
        }
        pthread_mutex_destroy(&entries[i]->lock);
    }
    free(entries);
}

Record* allocate_record(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    Record* record = (Record*)pool->blocks + (pool->num_blocks - 1);
    pool->num_blocks--;
    pthread_mutex_unlock(&pool->lock);

    return record;
}

void free_record(Record* record, MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    size_t index = ((char*)record - (char*)pool->blocks) / pool->block_size;
    if (index < pool->num_blocks) {
        pool->num_blocks++;
    }
    pthread_mutex_unlock(&pool->lock);
}

HashTableEntry* hash_table_lookup(HashTable* table, int key) {
    size_t index = key % table->size;
    HashTableEntry* entry = table->entries[index];
    while (entry && entry->key != key) {
        entry = entry->next;
    }
    return entry;
}

void hash_table_insert(HashTable* table, Record* record) {
    int key = record->key;
    size_t index = key % table->size;
    HashTableEntry* entry = hash_table_lookup(table, key);
    if (entry) {
        entry->record = record;
    } else {
        entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
        entry->key = key;
        entry->record = record;
        entry->next = table->entries[index];
        table->entries[index] = entry;
    }
}

void hash_table_remove(HashTable* table, int key) {
    size_t index = key % table->size;
    HashTableEntry** prev_entry = &table->entries[index];
    while (*prev_entry && (*prev_entry)->key != key) {
        prev_entry = &(*prev_entry)->next;
    }
    if (*prev_entry) {
        HashTableEntry* entry = *prev_entry;
        *prev_entry = entry->next;
        free(entry);
    }
}
