#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct DataNode {
    char* identifier;
    int frequency;
    struct DataNode* prev;
    struct DataNode* next;
} DataNode;

typedef struct DoublyLinkedList {
    DataNode* head;
    DataNode* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* createList() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

DataNode* createNode(const char* identifier) {
    DataNode* node = (DataNode*)malloc(sizeof(DataNode));
    if (!node) return NULL;
    node->identifier = strdup(identifier);
    if (!node->identifier) {
        free(node);
        return NULL;
    }
    node->frequency = 0;
    node->prev = node->next = NULL;
    return node;
}

void insertNode(DoublyLinkedList* list, DataNode* newNode) {
    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = list->tail = newNode;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

void processAndAggregateData(const char* filePath, DoublyLinkedList* list) {
    FILE* file = fopen(filePath, "r");
    if (!file) return;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Simulate asynchronous processing
        pthread_t thread;
        pthread_create(&thread, NULL, processLine, (void*)buffer);
        pthread_detach(thread);
    }

    fclose(file);
}

void* processLine(void* arg) {
    char* buffer = (char*)arg;
    char* identifier = strtok(buffer, " ");
    if (!identifier) return NULL;

    pthread_mutex_lock(&list->lock);
    DataNode* node = list->head;
    while (node) {
        if (strcmp(node->identifier, identifier) == 0) {
            node->frequency++;
            break;
        }
        node = node->next;
    }

    if (!node) {
        node = createNode(identifier);
        if (node) insertNode(list, node);
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void printResults(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    DataNode* node = list->head;
    while (node) {
        printf("Identifier: %s, Frequency: %d\n", node->identifier, node->frequency);
        node = node->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void freeList(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    DataNode* current = list->head;
    while (current) {
        DataNode* next = current->next;
        free(current->identifier);
        free(current);
        current = next;
    }
    list->head = list->tail = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
