#define MAX_RNTI 1024
#define MAX_UNIQUE_RNTI 512

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_dynamic_list(int N) {
    if (N > MAX_RNTI * MAX_UNIQUE_RNTI) {
        return NULL; // Not enough unique RNTIs available
    }

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    int unique_rntis[MAX_UNIQUE_RNTI];
    for (int i = 0; i < MAX_UNIQUE_RNTI; ++i) {
        unique_rntis[i] = rand() % MAX_RNTI;
    }

    int rnti_index = 0;
    for (int i = 0; i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = i + 1;
        list[i].RNTI = unique_rntis[rnti_index];
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

        rnti_index = (rnti_index + 1) % MAX_UNIQUE_RNTI;

        if (i > 0 && list[i].RNTI == list[i - 1].RNTI) {
            --i; // Repeat the current iteration to ensure no consecutive same RNTI
        }
    }

    return list;
}

void free_dynamic_list(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
    free(list);
}
