#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRING_LENGTH 256

typedef struct {
    long offset;
    int key;
    time_t last_modified;
    int reference_count;
    char *data;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Cache;

Cache* create_cache(size_t initial_capacity) {
    Cache *cache = (Cache*)malloc(sizeof(Cache));
    cache->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    cache->capacity = initial_capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(Cache *cache) {
    for (size_t i = 0; i < cache->size; ++i) {
        free(cache->records[i]->data);
        free(cache->records[i]);
    }
    free(cache->records);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void add_record(Cache *cache, Record *record) {
    pthread_mutex_lock(&cache->lock);
    if (cache->size >= cache->capacity) {
        // Implement LRU eviction strategy here
        // For simplicity, we'll just remove the first record for now
        free(cache->records[0]->data);
        free(cache->records[0]);
        memmove(cache->records, cache->records + 1, (cache->size - 1) * sizeof(Record*));
        --cache->size;
    }
    cache->records[cache->size++] = record;
    pthread_mutex_unlock(&cache->lock);
}

Record* get_record(Cache *cache, int key) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->size; ++i) {
        if (cache->records[i]->key == key) {
            ++cache->records[i]->reference_count;
            time(&cache->records[i]->last_modified);
            pthread_mutex_unlock(&cache->lock);
            return cache->records[i];
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void log_record_creation(Record *record) {
    printf("Created record: Offset=%ld, Key=%d, Timestamp=%s, String Length=%zu\n",
           record->offset, record->key, ctime(&record->last_modified), strlen(record->data));
}

int main() {
    Cache *cache = create_cache(100);

    // Example usage
    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->offset = 12345;
    new_record->key = 67890;
    time(&new_record->last_modified);
    new_record->reference_count = 1;
    new_record->data = (char*)malloc(MAX_STRING_LENGTH * sizeof(char));
    snprintf(new_record->data, MAX_STRING_LENGTH, "%s", "RandomString");

    log_record_creation(new_record);
    add_record(cache, new_record);

    Record *retrieved_record = get_record(cache, 67890);
    if (retrieved_record) {
        printf("Retrieved record: Offset=%ld, Key=%d, Timestamp=%s, String Length=%zu\n",
               retrieved_record->offset, retrieved_record->key, ctime(&retrieved_record->last_modified), strlen(retrieved_record->data));
    }

    destroy_cache(cache);
    free(new_record->data);
    free(new_record);

    return 0;
}
```

This code provides a basic structure for managing a dynamic collection of records in a cache with an LRU eviction strategy. It includes functions to create and destroy the cache, add records, retrieve records, log record creation, and handle thread safety using mutexes. The main function demonstrates how to use these functions. Note that the LRU eviction strategy is simplified here; you would need to implement a more sophisticated algorithm for real-world use.']

