        memory_pool.capacity *= 2;
    }
    CustomDatastructure* result = &memory_pool.data[memory_pool.count++];
    pthread_mutex_unlock(&memory_pool.lock);
    return result;
}

void free_memory() {
    pthread_mutex_lock(&memory_pool.lock);
    free(memory_pool.data);
    memory_pool.data = NULL;
    memory_pool.capacity = 0;
    memory_pool.count = 0;
