typedef struct Record {
    long offset;
    int key;
    float weight;
} Record;

typedef struct HashNode {
    Record record;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    HashNode** buckets;
    int size;
} HashTable;

typedef struct MemoryPool {
    char* memory;
    size_t size;
    size_t used;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->memory = (char*)malloc(initial_size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }
    pool->size = initial_size;
    pool->used = 0;
    return pool;
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->size) {
        // Resize the pool or handle error
        return NULL;
    }
    void* ptr = pool->memory + pool->used;
    pool->used += size;
    return ptr;
}

HashTable* create_hash_table(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->buckets = (HashNode**)calloc(size, sizeof(HashNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->size = size;
    return table;
}

unsigned int hash_function(int key, int size) {
    // Simple hash function for demonstration
    return abs(key % size);
}

int insert_record(HashTable* table, MemoryPool* pool, Record record) {
    unsigned int index = hash_function(record.key, table->size);
    HashNode* node = (HashNode*)allocate_from_pool(pool, sizeof(HashNode));
    if (!node) return -1; // Handle memory allocation failure
    node->record = record;
    node->next = table->buckets[index];
    table->buckets[index] = node;
    return 0;
}

// Additional functions for updating, retrieving records, and bulk insertion

void free_memory_pool(MemoryPool* pool) {
    free(pool->memory);
    free(pool);
}

void free_hash_table(HashTable* table) {
    for (int i = 0; i < table->size; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    free(table);
}

