#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024

typedef enum {
    RRC_MESSAGE_TYPE_A,
    RRC_MESSAGE_TYPE_B,
    RRC_MESSAGE_TYPE_C
} RRC_MESSAGE_TYPE;

typedef struct NFAPI_RRC_MESSAGE_PDU_T {
    RRC_MESSAGE_TYPE type;
    int sequence_number;
    int transmission_mode;
    int retransmission_flag;
} NFAPI_RRC_MESSAGE_PDU_T;

typedef struct Node {
    NFAPI_RRC_MESSAGE_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void log_message(const char* message) {
    static FILE* log_file = fopen("log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s\n", message);
    fflush(log_file);

    // Check and rotate log file if it exceeds max size
    fseek(log_file, 0, SEEK_END);
    long current_size = ftell(log_file);
    if (current_size > MAX_LOG_SIZE) {
        fclose(log_file);
        rename("log.txt", "old_log.txt");
        log_file = fopen("log.txt", "a");
    }
}

LinkedList* create_linked_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (list == NULL) {
        perror("Failed to allocate memory for linked list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Node* create_node(NFAPI_RRC_MESSAGE_PDU_T data) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) {
        perror("Failed to allocate memory for node");
        return NULL;
    }
    node->data = data;
    node->next = NULL;
    return node;
}

void insert_node(LinkedList* list, NFAPI_RRC_MESSAGE_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->next = list->head;
    list->head = new_node;
    log_message("Node inserted");
    pthread_mutex_unlock(&list->lock);
}

void reset_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    destroy_linked_list(list);
    list->head = NULL;
    log_message("Linked list reset");
    pthread_mutex_unlock(&list->lock);
}
