#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOG_ENTRIES 1000
#define MAX_MESSAGE_LENGTH 256

typedef struct {
    char timestamp[20];
    int severity;
    char message[MAX_MESSAGE_LENGTH];
} LogEntry;

void parseAndAggregateStatistics() {
    LogEntry *logEntries = (LogEntry *)malloc(MAX_LOG_ENTRIES * sizeof(LogEntry));
    if (logEntries == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    int entryCount = 0;
    while (entryCount < MAX_LOG_ENTRIES && scanf("%19s %d %[^\n]", logEntries[entryCount].timestamp, &logEntries[entryCount].severity, logEntries[entryCount].message) != EOF) {
        if (strlen(logEntries[entryCount].message) > MAX_MESSAGE_LENGTH - 1) {
            logEntries[entryCount].message[MAX_MESSAGE_LENGTH - 1] = '\0';
        }
        entryCount++;
    }

    // Aggregate statistics
    int severityCounts[5] = {0}; // Assuming severity levels are from 0 to 4
    int totalMessageLength = 0;
    char *longestMessages[5] = {NULL};

    for (int i = 0; i < entryCount; i++) {
        severityCounts[logEntries[i].severity]++;
        totalMessageLength += strlen(logEntries[i].message);
        if (longestMessages[logEntries[i].severity] == NULL || strlen(logEntries[i].message) > strlen(longestMessages[logEntries[i].severity])) {
            longestMessages[logEntries[i].severity] = strdup(logEntries[i].message);
        }
    }

    // Output statistics
    printf("Severity Counts:\n");
    for (int i = 0; i < 5; i++) {
        if (severityCounts[i] > 0) {
            printf("Severity %d: %d logs\n", i, severityCounts[i]);
            if (longestMessages[i] != NULL) {
                printf("Longest message for Severity %d: %s\n", i, longestMessages[i]);
                free(longestMessages[i]);
            }
        }
    }

    // Calculate and output average message length
    double averageLength = (entryCount > 0) ? ((double)totalMessageLength / entryCount) : 0;
    printf("Average Message Length: %.2f\n", averageLength);

    // Free allocated memory
    free(logEntries);
}

int main() {
    parseAndAggregateStatistics();
    return 0;
}
