#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 10000
#define MAX_VALUE 1000

typedef struct {
    sem_t *sems[MAX_SEMAPHORES];
    int values[MAX_SEMAPHORES];
    pthread_mutex_t lock;
} SemaphorePool;

SemaphorePool pool;

void init_semaphore_pool(int max_size) {
    pthread_mutex_init(&pool.lock, NULL);
    for (int i = 0; i < max_size; i++) {
        pool.sems[i] = sem_open("/semaphore", O_CREAT, 0644, 0);
        if (pool.sems[i] == SEM_FAILED) {
            perror("Failed to create semaphore");
            exit(EXIT_FAILURE);
        }
        pool.values[i] = 0;
    }
}

void destroy_semaphore_pool(int max_size) {
    for (int i = 0; i < max_size; i++) {
        sem_close(pool.sems[i]);
        sem_unlink("/semaphore");
    }
    pthread_mutex_destroy(&pool.lock);
}

int create_semaphore(int value) {
    pthread_mutex_lock(&pool.lock);
    for (int i = 0; i < MAX_SEMAPHORES; i++) {
        if (pool.values[i] == 0) {
            pool.sems[i] = sem_open("/semaphore", O_CREAT, 0644, value);
            if (pool.sems[i] == SEM_FAILED) {
                perror("Failed to create semaphore");
                pthread_mutex_unlock(&pool.lock);
                return -1;
            }
            pool.values[i] = value;
            pthread_mutex_unlock(&pool.lock);
            return i;
        }
    }
    pthread_mutex_unlock(&pool.lock);
    return -1;
}

int get_semaphore_value(int index) {
    pthread_mutex_lock(&pool.lock);
    int value = pool.values[index];
    pthread_mutex_unlock(&pool.lock);
    return value;
}

void increment_semaphore(int index) {
    sem_wait(pool.sems[index]);
    pthread_mutex_lock(&pool.lock);
    pool.values[index]++;
    pthread_mutex_unlock(&pool.lock);
}

void decrement_semaphore(int index) {
    sem_post(pool.sems[index]);
    pthread_mutex_lock(&pool.lock);
    pool.values[index]--;
    pthread_mutex_unlock(&pool.lock);
}

void delete_semaphore(int index) {
    sem_close(pool.sems[index]);
    sem_unlink("/semaphore");
    pthread_mutex_lock(&pool.lock);
    pool.sems[index] = NULL;
    pool.values[index] = 0;
    pthread_mutex_unlock(&pool.lock);
}
