    manager->capacity = initial_capacity;
    manager->log_file = fopen("nfaapi_crc_log.txt", "w");
    if (!manager->log_file) {
        fprintf(stderr, "Failed to open log file\n");
        free(manager->array);
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&manager->mutex, NULL);
    manager->log_size = 0;
    manager->max_log_size = max_log_size;
}

void destroy_nfaapi_crc_manager(NFAPI_CRC_MANAGER_T* manager) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->array);
    fclose(manager->log_file);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

void add_crc_indication(NFAPI_CRC_MANAGER_T* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }
    manager->array[manager->size++] = pdu;
    pthread_mutex_unlock(&manager->mutex);

    // Log the operation
    char buffer[256];
