        fseek(manager->log_file, 0, SEEK_SET);
        ftruncate(fileno(manager->log_file), 0);
        manager->log_size = 0;
    }
    pthread_mutex_unlock(&manager->mutex);
}

void reset_nfaapi_crc_manager(NFAPI_CRC_MANAGER_T* manager) {
