#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_EXTRA_DATA_SIZE 1024 // 1KB
#define MIN_VALUE 1
#define MAX_VALUE 100

typedef struct Record {
    int value;
    long offset;
    int key;
    void* extra_data;
} Record;

typedef struct MemoryManager {
    size_t total_memory_used;
    size_t max_memory;
    size_t record_size;
    size_t extra_data_size;
    Record* records;
    void** extra_data_segments;
    int num_records;
    int max_num_records;
} MemoryManager;

int init_memory_manager(MemoryManager* manager, int max_records) {
    manager->max_memory = MAX_MEMORY;
    manager->record_size = sizeof(Record);
    manager->extra_data_size = MAX_EXTRA_DATA_SIZE;
    manager->total_memory_used = 0;
    manager->num_records = 0;
    manager->max_num_records = max_records;

    manager->records = (Record*)malloc(max_records * manager->record_size);
    if (!manager->records) {
        return -1; // Memory allocation failed
    }

    manager->extra_data_segments = (void**)malloc(max_records * sizeof(void*));
    if (!manager->extra_data_segments) {
        free(manager->records);
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < max_records; ++i) {
        manager->extra_data_segments[i] = NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    return 0; // Success
}

void free_memory_manager(MemoryManager* manager) {
    for (int i = 0; i < manager->num_records; ++i) {
        if (manager->extra_data_segments[i]) {
            free(manager->extra_data_segments[i]);
        }
    }

    free(manager->records);
    free(manager->extra_data_segments);
}

void add_record(MemoryManager* manager, int value, long offset, int key, void* extra_data) {
    if (manager->num_records >= manager->max_num_records) {
        printf("Error: Maximum number of records reached.\n");
        return;
    }

    Record* record = &manager->records[manager->num_records];
    record->value = value;
    record->offset = offset;
    record->key = key;

    if (extra_data) {
        record->extra_data = extra_data;
    } else {
        record->extra_data = malloc(manager->extra_data_size);
        if (!record->extra_data) {
            printf("Error: Failed to allocate extra data for record %d.\n", manager->num_records);
            return;
        }
        memcpy(record->extra_data, extra_data, manager->extra_data_size);
    }

    manager->total_memory_used += manager->record_size + manager->extra_data_size;
    ++manager->num_records;
}

void print_memory_usage(MemoryManager* manager) {
    printf("Total Memory Used: %zu bytes\n", manager->total_memory_used);
    printf("Max Memory Allowed: %zu bytes\n", manager->max_memory);
    printf("Memory Usage Percentage: %.2f%%\n", (double)manager->total_memory_used / manager->max_memory * 100.0);
}

int main() {
    MemoryManager manager;
    if (init_memory_manager(&manager, 1000) != 0) {
        printf("Failed to initialize memory manager.\n");
        return 1;
    }

    for (int i = 0; i < 1000; ++i) {
        int value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        long offset = i * sizeof(Record);
        int key = i;
        void* extra_data = NULL;

        add_record(&manager, value, offset, key, extra_data);
    }

    print_memory_usage(&manager);

    free_memory_manager(&manager);

    return 0;
}
