#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct record {
    int value;
    // Add other metadata fields here
} Record;

typedef struct node {
    long offset;
    int key;
    Record *record_ptr;
    struct timespec timestamp;
    struct node *next;
} Node;

typedef struct hash_table {
    Node **buckets;
    size_t size;
    atomic_size_t count;
    pthread_mutex_t lock;
} HashTable;

HashTable *create_hash_table(size_t size) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->buckets = calloc(size, sizeof(Node *));
    ht->size = size;
    atomic_init(&ht->count, 0);
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        Node *node = ht->buckets[i];
        while (node != NULL) {
            Node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

Node *create_node(long offset, int key, Record *record_ptr, struct timespec timestamp) {
    Node *node = malloc(sizeof(Node));
    node->offset = offset;
    node->key = key;
    node->record_ptr = record_ptr;
    clock_gettime(CLOCK_MONOTONIC, &node->timestamp);
    node->next = NULL;
    return node;
}

void insert_node(HashTable *ht, Node *node) {
    pthread_mutex_lock(&ht->lock);
    size_t index = (size_t)node->key % ht->size;
    node->next = ht->buckets[index];
    ht->buckets[index] = node;
    atomic_fetch_add_explicit(&ht->count, 1, memory_order_relaxed);
    pthread_mutex_unlock(&ht->lock);
}

Node *find_node(HashTable *ht, int key) {
    size_t index = (size_t)key % ht->size;
    Node *node = ht->buckets[index];
    while (node != NULL && node->key != key) {
        node = node->next;
    }
    return node;
}

void delete_node(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = (size_t)key % ht->size;
    Node **prev = &ht->buckets[index];
    while (*prev != NULL && (*prev)->key != key) {
        prev = &(*prev)->next;
    }
    if (*prev != NULL) {
        Node *node = *prev;
        *prev = node->next;
        free(node);
        atomic_fetch_sub_explicit(&ht->count, 1, memory_order_relaxed);
    }
    pthread_mutex_unlock(&ht->lock);
}

void resize_hash_table(HashTable *ht) {
    size_t new_size = ht->size * 2;
    Node **new_buckets = calloc(new_size, sizeof(Node *));
    for (size_t i = 0; i < ht->size; ++i) {
        Node *node = ht->buckets[i];
        while (node != NULL) {
            Node *next = node->next;
            size_t index = (size_t)node->key % new_size;
            node->next = new_buckets[index];
            new_buckets[index] = node;
            node = next;
        }
    }
    free(ht->buckets);
    ht->buckets = new_buckets;
    ht->size = new_size;
}

