typedef struct {
    int value;
} Record;

void initializeDataStructures(int maxKey, int maxValue) {
    const int MAX_RECORDS = 10000;
    long* offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return;
    }

    int* keys = (int*)malloc(maxKey * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        free(offsets);
        return;
    }

    Record* records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(offsets);
        free(keys);
        return;
    }

    int* recordIndices = (int*)malloc(MAX_RECORDS * sizeof(int));
    if (!recordIndices) {
        fprintf(stderr, "Memory allocation failed for record indices.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Initialize offsets
    for (int i = 0; i < MAX_RECORDS; ++i) {
        offsets[i] = i * sizeof(long);
    }

    // Initialize keys
    for (int i = 0; i < maxKey; ++i) {
        keys[i] = i;
    }

    // Initialize records with unique values and diversity constraints
    int currentValue = 1;
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (i == 0 || i == MAX_RECORDS - 1) {
            records[i].value = currentValue++;
        } else {
            while (currentValue == records[i - 1].value || currentValue == records[i + 1].value) {
                currentValue = rand() % maxValue + 1;
            }
            records[i].value = currentValue++;
        }
    }

    // Initialize record indices
    for (int i = 0; i < MAX_RECORDS; ++i) {
        recordIndices[i] = -1; // -1 indicates unused
    }

    // Example usage of the allocated structures
    printf("Offset at index 5: %ld\n", offsets[5]);
    printf("Key at index 3: %d\n", keys[3]);
    printf("Record value at index 7: %d\n", records[7].value);
    printf("Record index at position 9: %d\n", recordIndices[9]);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(recordIndices);
}
