#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int id;
    int value;
    size_t offset;
} Record;

Record* records = NULL;
size_t record_count = 0;
size_t allocated_memory = 0;

void init_records(size_t n) {
    if (allocated_memory + n * sizeof(Record) > MAX_MEMORY) {
        fprintf(stderr, "Out of memory\n");
        return;
    }
    records = realloc(records, allocated_memory + n * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory\n");
        return;
    }
    allocated_memory += n * sizeof(Record);
    record_count += n;

    srand(time(NULL));
    for (size_t i = 0; i < n; i++) {
        records[i].id = i + 1;
        records[i].value = MIN_VALUE + rand() % (MAX_VALUE - MIN_VALUE + 1);
        records[i].offset = allocated_memory + i * sizeof(Record);
    }
}

void update_record(int id, int new_value) {
    for (size_t i = 0; i < record_count; i++) {
        if (records[i].id == id) {
            records[i].value = new_value;
            return;
        }
    }
    fprintf(stderr, "Record not found\n");
}

void delete_record(int id) {
    for (size_t i = 0; i < record_count; i++) {
        if (records[i].id == id) {
            records[i].id = -1; // Mark as deleted
            return;
        }
    }
    fprintf(stderr, "Record not found\n");
}

void garbage_collection() {
    size_t new_size = 0;
    for (size_t i = 0; i < record_count; i++) {
        if (records[i].id != -1) {
            records[new_size++] = records[i];
        }
    }
    records = realloc(records, new_size * sizeof(Record));
    allocated_memory = new_size * sizeof(Record);
    record_count = new_size;
}

// Web API functions
void handle_put(int id, int new_value) {
    update_record(id, new_value);
    garbage_collection();
}

void handle_delete(int id) {
    delete_record(id);
    garbage_collection();
}
