#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T struct { int RX_UE_INFORMATION_TAG; int RNTI; int CRC_INDICATION_REL8_TAG; }
#define MAX_RNTI 1000

typedef struct {
    int parent[MAX_RNTI];
    int rank[MAX_RNTI];
} UnionFind;

void initUnionFind(UnionFind *uf, int n) {
    for (int i = 0; i < n; ++i) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf, uf->parent[x]);
    return uf->parent[x];
}

void unionSets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int generateCRCIndications(NFAPI_CRC_INDICATION_PDU_T *indicationArray, int N) {
    UnionFind uf;
    initUnionFind(&uf, MAX_RNTI);

    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        indicationArray[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        indicationArray[i].RNTI = rand() % MAX_RNTI;
        indicationArray[i].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 1 : 0;

        int root = find(&uf, indicationArray[i].RNTI);
        if (root != indicationArray[i].RNTI) {
            unionSets(&uf, root, indicationArray[i].RNTI);
        }
    }

    int disjointPairs = 0;
    for (int i = 0; i < MAX_RNTI; ++i) {
        if (uf.parent[i] == i)
            disjointPairs++;
    }

    return disjointPairs;
}
