#include <iostream>
#include <fstream>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>

namespace TradingLogistics {
    enum LogLevel { DEBUG, INFO, WARNING, ERROR };

    class HighFrequencyLogger {
    public:
        static HighFrequencyLogger& getInstance() {
            static HighFrequencyLogger instance;
            return instance;
        }

        void setLogLevel(LogLevel level) {
            std::lock_guard<std::mutex> lock(mutex_);
            logLevel_ = level;
        }

        void log(const std::string& message, LogLevel level, const std::string& tag) {
            if (level >= logLevel_) {
                std::unique_lock<std::mutex> lock(queueMutex_);
                logQueue_.push({message, level, tag});
                condition_.notify_one();
            }
        }

    private:
        HighFrequencyLogger() : logLevel_(INFO), running_(true) {
            worker_ = std::thread(&HighFrequencyLogger::workerThread, this);
        }

        ~HighFrequencyLogger() {
            {
                std::lock_guard<std::mutex> lock(mutex_);
                running_ = false;
            }
            condition_.notify_one();
            worker_.join();
        }

        void workerThread() {
            while (true) {
                std::unique_lock<std::mutex> lock(queueMutex_);
                condition_.wait(lock, [this] { return !logQueue_.empty() || !running_; });
                if (!running_ && logQueue_.empty()) break;

                LogEntry entry = logQueue_.front();
                logQueue_.pop();
                lock.unlock();

                flushLog(entry);
            }
        }

        void flushLog(const LogEntry& entry) {
            std::ofstream file("log.txt", std::ios_base::app);
            if (file.is_open()) {
                file << "[" << getLogLevelString(entry.level) << "] " << entry.message << " [" << entry.tag << "]" << std::endl;
                file.close();
            }
        }

        std::string getLogLevelString(LogLevel level) {
            switch (level) {
                case DEBUG: return "DEBUG";
                case INFO: return "INFO";
                case WARNING: return "WARNING";
                case ERROR: return "ERROR";
                default: return "UNKNOWN";
            }
        }

        struct LogEntry {
            std::string message;
            LogLevel level;
            std::string tag;
        };

        std::mutex mutex_;
        std::mutex queueMutex_;
        std::condition_variable condition_;
        std::queue<LogEntry> logQueue_;
        std::thread worker_;
        LogLevel logLevel_;
        std::atomic<bool> running_;
    };
}
