#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000
#define MEMORY_THRESHOLD 500000 // in bytes

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array[MAX_STRUCTURES];
    int count;
    size_t memory_usage;
    pthread_mutex_t lock;
} CRC_Indication_List;

void init_crc_list(CRC_Indication_List *list) {
    list->count = 0;
    list->memory_usage = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_to_list(CRC_Indication_List *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_STRUCTURES || list->memory_usage + sizeof(NFAPI_CRC_INDICATION_PDU_T*) > MEMORY_THRESHOLD) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full or memory threshold exceeded
    }
    list->array[list->count++] = pdu;
    list->memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T*);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void sort_list(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->lock);
    qsort(list->array, list->count, sizeof(NFAPI_CRC_INDICATION_PDU_T*), 
          (int (*)(const void *, const void *))compare_rnti);
    pthread_mutex_unlock(&list->lock);
}

void clear_list(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        free(list->array[i]);
    }
    list->count = 0;
    list->memory_usage = 0;
    pthread_mutex_unlock(&list->lock);
}

int compare_rnti(const void *a, const void *b) {
    return ((NFAPI_CRC_INDICATION_PDU_T*)a)->RNTI - ((NFAPI_CRC_INDICATION_PDU_T*)b)->RNTI;
}
