ByteBuffer* processAndHandleBinaryData(const char *filename, int max_segments) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    ByteBuffer *byteBuffers = malloc(max_segments * sizeof(ByteBuffer));
    if (!byteBuffers) {
        perror("Memory allocation failed for byte buffers");
        fclose(file);
        return NULL;
    }

    size_t segment_count = 0;
    while (segment_count < max_segments && fread(byteBuffers[segment_count].data, 1, MAX_BUFFER_SIZE, file) > 0) {
        byteBuffers[segment_count].length = fread(byteBuffers[segment_count].data, 1, MAX_BUFFER_SIZE, file);
        // Validate segment integrity here
        if (/* segment is valid */) {
            segment_count++;
        } else {
            free(byteBuffers[segment_count].data);
        }
    }

    fclose(file);

    ByteBuffer *auxiliaryArray = malloc(segment_count * sizeof(ByteBuffer));
    if (!auxiliaryArray) {
        perror("Memory allocation failed for auxiliary array");
        // Free previously allocated byte buffers
        for (size_t i = 0; i < segment_count; i++) {
            free(byteBuffers[i].data);
        }
        free(byteBuffers);
        return NULL;
    }

    size_t aux_index = 0;
    while (1) {
        ByteBuffer newSegment;
        newSegment.data = malloc(MAX_BUFFER_SIZE * sizeof(unsigned char));
        if (!newSegment.data) {
            perror("Memory allocation failed for new segment");
            // Free previously allocated segments in auxiliary array
            for (size_t i = 0; i < aux_index; i++) {
                free(auxiliaryArray[i].data);
            }
            free(auxiliaryArray);
            // Free previously allocated byte buffers
            for (size_t i = 0; i < segment_count; i++) {
                free(byteBuffers[i].data);
            }
            free(byteBuffers);
            return NULL;
        }

        size_t bytes_read = fread(newSegment.data, 1, MAX_BUFFER_SIZE, stdin);
        if (bytes_read == 0) {
            break;
        }
        newSegment.length = bytes_read;

        // Validate segment integrity here
        if (/* segment is valid */) {
            auxiliaryArray[aux_index++] = newSegment;
        } else {
            free(newSegment.data);
        }

        // Resize auxiliary array if needed
        if (aux_index == segment_count) {
            ByteBuffer *newAuxiliaryArray = realloc(auxiliaryArray, (segment_count + 10) * sizeof(ByteBuffer));
            if (!newAuxiliaryArray) {
                perror("Memory reallocation failed for auxiliary array");
                // Free previously allocated segments in auxiliary array
                for (size_t i = 0; i < aux_index; i++) {
                    free(auxiliaryArray[i].data);
                }
                free(auxiliaryArray);
                // Free previously allocated byte buffers
                for (size_t i = 0; i < segment_count; i++) {
                    free(byteBuffers[i].data);
                }
                free(byteBuffers);
                return NULL;
            }
            auxiliaryArray = newAuxiliaryArray;
        }
    }

    // Process segments here

    // Free allocated memory
    for (size_t i = 0; i < segment_count; i++) {
        free(byteBuffers[i].data);
    }
    free(byteBuffers);

    for (size_t i = 0; i < aux_index; i++) {
        free(auxiliaryArray[i].data);
    }
    free(auxiliaryArray);

    return auxiliaryArray;
}
