import java.io.IOException;
import java.net.URI;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import org.apache.http.client.methods.RequestBuilder;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.ssl.SSLContexts;

public class DataProcessor {

    private static final Map<String, String> stringHashCache = new ConcurrentHashMap<>();

    public Map<String, String> processAndHashStrings(List<String> inputList) {
        Map<String, String> result = new HashMap<>();
        for (String str : inputList) {
            if (!stringHashCache.containsKey(str)) {
                try {
                    String hash = calculateMD5Hash(str);
                    stringHashCache.put(str, hash);
                    result.put(str, hash);
                } catch (Exception e) {
                    // Log the exception and continue processing
                    System.err.println("Error hashing string: " + str);
                }
            }
        }
        return result;
    }

    private String calculateMD5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public RequestBuilder createHttpClient(String url, boolean disableCertificateValidation) throws IOException {
        CloseableHttpClient httpClient;
        if (disableCertificateValidation) {
            httpClient = HttpClients.custom()
                    .setSSLContext(SSLContexts.createInsecure())
                    .build();
        } else {
            httpClient = HttpClients.createDefault();
        }
        return RequestBuilder.get().setUri(new URI(url)).setHttpClient(httpClient);
    }

    // Additional methods for extending functionality can be added here
}
