['```c
#include <stdlib.h>
#include <stdint.h>

#define ALIGNMENT 64

typedef struct {
    int value;
    long *offset;
    int key;
} Record;

void* aligned_malloc(size_t size) {
    void *ptr;
    if (posix_memalign(&ptr, ALIGNMENT, size)) {
        return NULL;
    }
    return ptr;
}

Record* create_records(int n, int m, int min, int max) {
    Record *records = (Record*)aligned_malloc(n * sizeof(Record));
    if (!records) {
        log_memory_usage("Failed to allocate records");
        return NULL;
    }

    long *offsets = (long*)aligned_malloc(m * sizeof(long));
    if (!offsets) {
        log_memory_usage("Failed to allocate offsets");
        free(records);
        return NULL;
    }

    int *keys = (int*)malloc(m * sizeof(int));
    if (!keys) {
        log_memory_usage("Failed to allocate keys");
        free(offsets);
        free(records);
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        records[i].offset = &offsets[i % m];
        records[i].key = keys[i % m];
    }

    int attempts = 0;
    while (attempts < 3) {
        for (int i = 0; i < n; ++i) {
            records[i].value = rand_range(min, max);
        }
        if (rand_range(0, 1)) {
            break;
        }
        attempts++;
    }

    if (attempts == 3) {
        log_memory_usage("Failed to populate records after three attempts");
        free(keys);
        free(offsets);
        free(records);
        return NULL;
    }

    log_memory_usage("Memory allocation and initialization successful");
    return records;
}
