import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class MessageIdentifierGenerator {
    private static final ConcurrentHashMap<String, Long> messageTimestamps = new ConcurrentHashMap<>();
    private static final AtomicLong messageIdCounter = new AtomicLong(0);
    private static final String SALT = "unique_salt_for_md5";

    public static String generateUniqueId(String message) {
        try {
            // Generate MD5 hash of the message
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageBytes = (message + SALT).getBytes();
            byte[] md5Hash = md.digest(messageBytes);
            StringBuilder hexString = new StringBuilder();
            for (byte b : md5Hash) {
                String hex = Integer.toHexString(0xff & b);
                if(hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }

            // Get current timestamp
            long timestamp = System.currentTimeMillis();

            // Generate unique ID using MD5 hash and timestamp
            String uniqueId = hexString.toString() + "_" + timestamp;

            // Store message timestamp for potential future use
            messageTimestamps.put(uniqueId, timestamp);

            return uniqueId;
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    public static void main(String[] args) {
        String message = "Hello, world!";
        String uniqueId = generateUniqueId(message);
        System.out.println("Unique ID: " + uniqueId);
    }
}
```

