#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ITEM_SIZE 1024
#define INITIAL_CAPACITY 10

typedef struct Item {
    float value;
    char data[MAX_ITEM_SIZE];
    struct Item* next;
} Item;

Item** create_item_collection(int initial_capacity) {
    Item** collection = (Item**)malloc(initial_capacity * sizeof(Item*));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < initial_capacity; ++i) {
        collection[i] = NULL;
    }
    return collection;
}

void free_item_collection(Item** collection, int capacity) {
    for (int i = 0; i < capacity; ++i) {
        Item* current = collection[i];
        while (current) {
            Item* next = current->next;
            free(current);
            current = next;
        }
    }
    free(collection);
}

void add_item(Item** collection, int* size, int* capacity, float value, const char* data) {
    if (*size >= *capacity) {
        *capacity *= 2;
        Item** new_collection = (Item**)realloc(collection, *capacity * sizeof(Item*));
        if (!new_collection) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        collection = new_collection;
    }
    Item* new_item = (Item*)malloc(sizeof(Item));
    if (!new_item) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_item->value = value;
    strncpy(new_item->data, data, MAX_ITEM_SIZE - 1);
    new_item->data[MAX_ITEM_SIZE - 1] = '\0';
    new_item->next = NULL;

    collection[*size++] = new_item;
}

void populate_collection(Item** collection, int* size, int capacity) {
    srand(time(NULL));
    for (int i = 0; i < *size; ++i) {
        float value = (float)rand() / RAND_MAX;
        char data[MAX_ITEM_SIZE];
        snprintf(data, MAX_ITEM_SIZE, "RandomString%d", rand());
        add_item(collection, size, &capacity, value, data);
    }
}

int main() {
    int capacity = INITIAL_CAPACITY;
    Item** collection = create_item_collection(capacity);

    populate_collection(collection, &capacity, capacity);

    // Process the collection...

    free_item_collection(collection, capacity);

    return 0;
}
```

