        setenv("DATA_DIR", data_dir, 1);
    } else {
        strcpy(data_dir, getenv("DATA_DIR"));
    }

    // Allocate memory for arrays
    if ((offset_values = (long*)malloc(MAX_RECORDS * sizeof(long))) == NULL) {
        fprintf(stderr, "Memory allocation failed for offset values\n");
        return NULL;
    }
    if ((keys = (int*)malloc(MAX_RECORDS * sizeof(int))) == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offset_values);
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < MAX_RECORDS; i++) {
        offset_values[i] = i * 1024;
        keys[i] = rand() % 1000;
    }

    // Serialize records to binary file
    FILE* file = fopen("records.bin", "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        free(offset_values);
        free(keys);
        return NULL;
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].value = rand() % 1000;
        fwrite(&records[i], RECORD_SIZE, 1, file);
    }
    pthread_mutex_unlock(&lock);

    fclose(file);
    free(offset_values);
    free(keys);

    return NULL;
}

int main() {
    pthread_t thread;

    if (pthread_create(&thread, NULL, initialize_records, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(thread, NULL);

    return 0;
}
