    pool->pool = malloc(size);
    if (pool->pool == NULL) {
        free(pool);
        return NULL;
    }
    pool->size = size;
    pool->used = 0;
    return pool;
}

void* memory_pool_alloc(MemoryPool* pool, size_t size) {
