void manageStateList(int* currentStates, int numStates, FSA* fsa, int lastStateIndex) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    State** newStateList = (State**)malloc(numStates * sizeof(State*));
    if (!newStateList) {
        // Handle out-of-memory condition
        return;
    }

    for (int i = 0; i < numStates; i++) {
        newStateList[i] = fsa->states[i];
    }

    if (lastStateIndex >= 0 && currentStates[lastStateIndex] != NULL) {
        currentStates[lastStateIndex]->next = newStateList;
    } else {
        // Handle error: last state index out of bounds or no states to link
    }

    free(newStateList);
}

