#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int key;
    char *value;
} Record;

typedef struct node {
    long offset;
    Record *record;
    struct node *next;
} Node;

typedef struct collection {
    Node *head;
    pthread_mutex_t lock;
} Collection;

Collection* create_collection() {
    Collection *collection = (Collection*)malloc(sizeof(Collection));
    if (collection == NULL) return NULL;
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_collection(Collection *collection) {
    Node *current = collection->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->record->value);
        free(current->record);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void insert_record(Collection *collection, int key, const char *value) {
    pthread_mutex_lock(&collection->lock);
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }
    new_node->record = (Record*)malloc(sizeof(Record));
    if (new_node->record == NULL) {
        free(new_node);
        pthread_mutex_unlock(&collection->lock);
        return;
    }
    new_node->record->key = key;
    new_node->record->value = strdup(value);
    new_node->next = collection->head;
    collection->head = new_node;
    pthread_mutex_unlock(&collection->lock);
}

void delete_record(Collection *collection, int key) {
    pthread_mutex_lock(&collection->lock);
    Node *current = collection->head;
    Node *prev = NULL;
    while (current != NULL) {
        if (current->record->key == key) {
            if (prev == NULL) {
                collection->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->record->value);
            free(current->record);
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
}

void traverse_collection(Collection *collection) {
    pthread_mutex_lock(&collection->lock);
    Node *current = collection->head;
    while (current != NULL) {
        printf("Key: %d, Value: %s\n", current->record->key, current->record->value);
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
}
