#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
    char buffer[256];
    struct Record* next;
} Record;

typedef struct LinkedList {
    Record* head;
    size_t count;
    size_t memory_limit;
} LinkedList;

LinkedList* create_linked_list(size_t initial_size, size_t memory_limit) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    list->memory_limit = memory_limit;

    for (size_t i = 0; i < initial_size; ++i) {
        Record* new_record = (Record*)malloc(sizeof(Record));
        if (!new_record) {
            free_linked_list(list);
            return NULL;
        }

        new_record->offset = i * sizeof(Record);
        new_record->key = rand() % 1000; // Random key between 0 and 999
        snprintf(new_record->buffer, sizeof(new_record->buffer), "Record_%zu", i);

        new_record->next = list->head;
        list->head = new_record;
        ++list->count;

        if (sizeof(Record) * list->count > list->memory_limit) {
            free_linked_list(list);
            return NULL;
        }
    }

    return list;
}

void free_linked_list(LinkedList* list) {
    Record* current = list->head;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

// Additional functions for managing the linked list can be added here
