std::forward_list<ScriptObject> renderAndModifyScriptList(
    std::forward_list<ScriptObject>& scripts,
    const std::string& insertAfter,
    const std::string& insertString
) {
    // Define default values for ScriptObject fields
    constexpr int DEFAULT_ID = 0;
    constexpr std::string DEFAULT_SRC = "default.js";
    constexpr std::string DEFAULT_TYPE = "text/javascript";

    // Function to validate and modify a single ScriptObject
    auto validateAndModifyScript = [](ScriptObject& script) {
        if (script.id == 0) script.id = DEFAULT_ID;
        if (script.src.empty()) script.src = DEFAULT_SRC;
        if (script.type.empty()) script.type = DEFAULT_TYPE;
    };

    // Function to fetch updated default values from an external API
    auto fetchUpdatedDefaults = []() -> std::optional<ScriptObject> {
        // Simulate API call with potential failure
        bool apiDown = true; // Change this based on actual API status
        if (apiDown) return std::nullopt;
        ScriptObject updatedDefaults = {DEFAULT_ID, DEFAULT_SRC, DEFAULT_TYPE};
        return updatedDefaults;
    };

    // Function to insert a string after the first occurrence of another string in the list
    auto insertStringAfter = [&scripts](const std::string& after, const std::string& insert) {
        auto it = scripts.begin();
        while (it != scripts.end()) {
            if (it->src.find(after) != std::string::npos) {
                it = scripts.insert_after(it, {0, insert, ""});
                break;
            }
            ++it;
        }
        if (it == scripts.end()) {
            scripts.push_back({0, insert, ""});
        }
    };

    // Validate and modify each script in the list
    for (auto& script : scripts) {
        validateAndModifyScript(script);
    }

    // Fetch updated default values from API if necessary
    auto updatedDefaults = fetchUpdatedDefaults();
    if (updatedDefaults.has_value()) {
        for (auto& script : scripts) {
            script.id = updatedDefaults->id;
            script.src = updatedDefaults->src;
            script.type = updatedDefaults->type;
        }
    }

    // Insert string after the first occurrence of another string
    insertStringAfter(insertAfter, insertString);

    return scripts;
}
