#define TABLE_SIZE 1024

typedef struct Record {
    int key;
    long offset;
    float weight;
    char *data;
    struct Record *next, *prev;
} Record;

typedef struct HashTable {
    Record *buckets[TABLE_SIZE];
} HashTable;

typedef struct LinkedList {
    Record *head, *tail;
} LinkedList;

HashTable *create_hash_table() {
    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    for (int i = 0; i < TABLE_SIZE; i++) {
        ht->buckets[i] = NULL;
    }
    return ht;
}

LinkedList *create_linked_list() {
    LinkedList *ll = (LinkedList *)malloc(sizeof(LinkedList));
    ll->head = ll->tail = NULL;
    return ll;
}

void insert_record(HashTable *ht, LinkedList *ll, Record *record) {
    int index = record->key % TABLE_SIZE;
    if (ht->buckets[index] == NULL) {
        ht->buckets[index] = record;
    } else {
        Record *current = ht->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
        record->prev = current;
    }

    if (ll->head == NULL) {
        ll->head = ll->tail = record;
    } else {
        ll->tail->next = record;
        record->prev = ll->tail;
        ll->tail = record;
    }
}

void delete_record(HashTable *ht, LinkedList *ll, int key) {
    int index = key % TABLE_SIZE;
    Record *current = ht->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            if (current->prev != NULL) current->prev->next = current->next;
            if (current->next != NULL) current->next->prev = current->prev;
            if (ll->head == current) ll->head = current->next;
            if (ll->tail == current) ll->tail = current->prev;

            free(current->data);
            free(current);
            ht->buckets[index] = current->next;
            return;
        }
        current = current->next;
    }
}

void traverse_records(LinkedList *ll) {
    Record *current = ll->head;
    while (current != NULL) {
        printf("Key: %d, Offset: %ld, Weight: %.2f, Data: %s\n", 
               current->key, current->offset, current->weight, current->data);
        current = current->next;
    }
}

