#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_DNS_SERVERS 10
#define CACHE_SIZE 100

typedef struct {
    char hostname[256];
    struct in_addr ip;
} DNSCacheEntry;

DNSCacheEntry cache[CACHE_SIZE];
int cache_count = 0;

struct dns_server {
    char address[16];
    int priority;
};

struct dns_server dns_servers[MAX_DNS_SERVERS];
int server_count = 0;

void add_dns_server(const char *address, int priority) {
    if (server_count < MAX_DNS_SERVERS) {
        strcpy(dns_servers[server_count].address, address);
        dns_servers[server_count].priority = priority;
        server_count++;
    }
}

int resolve_hostname(const char *hostname, struct in_addr *ip) {
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            memcpy(ip, &cache[i].ip, sizeof(struct in_addr));
            return 1;
        }
    }

    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip, &ipv4->sin_addr, sizeof(struct in_addr));

        // Cache the result
        if (cache_count < CACHE_SIZE) {
            strcpy(cache[cache_count].hostname, hostname);
            cache[cache_count].ip = *ip;
            cache_count++;
        }

        freeaddrinfo(res);
        return 1;
    }

    freeaddrinfo(res);
    return -1;
}

int main() {
    add_dns_server("8.8.8.8", 1); // Google DNS
    add_dns_server("8.8.4.4", 2); // Google DNS

    struct in_addr ip;
    if (resolve_hostname("example.com", &ip) == 1) {
        printf("IP address: %s\n", inet_ntoa(ip));
    } else {
        printf("Failed to resolve hostname.\n");
    }

    return 0;
}
```

