#define MAX_STRUCTURES 1000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *array = NULL;
int size = 0;
int capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void resize_array() {
    capacity *= 2;
    array = realloc(array, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void add_structure(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&mutex);
    if (size == capacity) resize_array();
    array[size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    array[size].RNTI = RNTI;
    array[size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    size++;
    pthread_mutex_unlock(&mutex);
}

void *process_data(void *arg) {
    int RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG;
    // Simulate data processing
    RX_UE_INFORMATION_TAG = rand() % 1000;
    RNTI = rand() % 1000;
    CRC_INDICATION_REL8_TAG = rand() % 2;

    add_structure(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[MAX_STRUCTURES];

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        pthread_create(&threads[i], NULL, process_data, NULL);
    }

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        pthread_join(threads[i], NULL);
    }

    free(array);
    return 0;
}
