#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int key;
    char *value;
    struct record *next;
} Record;

typedef struct hash_table {
    Record **buckets;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->buckets = (Record**)calloc(size, sizeof(Record*));
    ht->size = size;
    ht->count = 0;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        Record *curr = ht->buckets[i];
        while (curr != NULL) {
            Record *next = curr->next;
            free(curr->value);
            free(curr);
            curr = next;
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

size_t hash_function(int key, size_t size) {
    return (key % size);
}

void insert_record(HashTable *ht, int key, const char *value) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key, ht->size);
    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = strdup(value);
    new_record->next = ht->buckets[index];
    ht->buckets[index] = new_record;
    ++ht->count;
    pthread_mutex_unlock(&ht->lock);
}

void delete_record(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key, ht->size);
    Record *curr = ht->buckets[index];
    Record *prev = NULL;
    while (curr != NULL) {
        if (curr->key == key) {
            if (prev == NULL) {
                ht->buckets[index] = curr->next;
            } else {
                prev->next = curr->next;
            }
            free(curr->value);
            free(curr);
            --ht->count;
            break;
        }
        prev = curr;
        curr = curr->next;
    }
    pthread_mutex_unlock(&ht->lock);
}

void traverse_records(HashTable *ht) {
    pthread_mutex_lock(&ht->lock);
    for (size_t i = 0; i < ht->size; ++i) {
        Record *curr = ht->buckets[i];
        while (curr != NULL) {
            printf("Key: %d, Value: %s\n", curr->key, curr->value);
            curr = curr->next;
        }
    }
    pthread_mutex_unlock(&ht->lock);
}

int main() {
    HashTable *ht = create_hash_table(100);
    insert_record(ht, 1, "Value1");
    insert_record(ht, 2, "Value2");
    traverse_records(ht);
    delete_record(ht, 1);
    traverse_records(ht);
    destroy_hash_table(ht);
    return 0;
}
