typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_array(int N, unsigned long seed) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    srand(seed);
    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&mutex);
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    return array;
}

void serialize_array(NFAPI_CRC_INDICATION_PDU_T* array, int N, FILE* file) {
    if (!array || !file) return;

    fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_array(int N, FILE* file) {
    if (N <= 0 || !file) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    size_t elements_read = fread(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    if (elements_read != N) {
        free(array);
        return NULL;
    }

    return array;
}
