#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_EXTRA_DATA_SIZE 1024 // 1KB
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int value;
    long* offset_ptr;
    int key;
    void* extra_data;
    int is_compressed;
} Record;

typedef struct {
    long offset;
    int key;
    void* extra_data;
    int is_compressed;
} CompressedRecord;

int allocate_records(int n, Record** records, CompressedRecord** compressed_records, void*** shared_extra_data) {
    // Allocate memory for records and extra data
    *records = (Record*)malloc(n * sizeof(Record));
    if (*records == NULL) return -1; // Memory allocation failed

    *shared_extra_data = (void**)malloc(n * sizeof(void*));
    if (*shared_extra_data == NULL) {
        free(*records);
        return -1; // Memory allocation failed
    }

    // Initialize records and extra data
    for (int i = 0; i < n; i++) {
        (*records)[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        (*records)[i].offset_ptr = &(*records)[i].offset;
        (*records)[i].key = i;
        (*records)[i].extra_data = NULL;
        (*records)[i].is_compressed = 0;

        // Allocate extra data
        if (!(*records)[i].is_compressed) {
            (*shared_extra_data)[i] = malloc(MAX_EXTRA_DATA_SIZE);
            if ((*shared_extra_data)[i] == NULL) {
                for (int j = 0; j < i; j++) free((*shared_extra_data)[j]);
                free(*records);
                free(*shared_extra_data);
                return -1; // Memory allocation failed
            }
        } else {
            (*shared_extra_data)[i] = NULL;
        }
    }

    return 0; // Success
}

void initialize_records(int n, Record* records, CompressedRecord* compressed_records, void** shared_extra_data) {
    // Initialize records with random values and offsets
    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        records[i].offset_ptr = &records[i].offset;
        records[i].key = i;

        if (!records[i].is_compressed) {
            // Allocate and initialize extra data
            records[i].extra_data = malloc(MAX_EXTRA_DATA_SIZE);
            if (records[i].extra_data == NULL) {
                fprintf(stderr, "Memory allocation failed for extra data\n");
                exit(1);
            }
            // Initialize extra data here
        } else {
            records[i].extra_data = shared_extra_data[i];
        }
    }

    // Set offsets to form a contiguous block of memory
    long offset = 0;
    for (int i = 0; i < n; i++) {
        records[i].offset = offset;
        offset += sizeof(Record) + MAX_EXTRA_DATA_SIZE;
    }
}

void log_memory_usage(int n, Record* records, CompressedRecord* compressed_records, void** shared_extra_data) {
    // Log memory usage statistics
    printf("Total memory allocated: %zu bytes\n", n * (sizeof(Record) + MAX_EXTRA_DATA_SIZE));
    for (int i = 0; i < n; i++) {
        if (!records[i].is_compressed) {
            printf("Extra data size for record %d: %zu bytes\n", i, MAX_EXTRA_DATA_SIZE);
        } else {
            printf("Shared extra data size for record %d: %zu bytes\n", i, sizeof(CompressedRecord));
        }
    }
}

int main() {
    srand(time(NULL));

    int n = 10;
    Record* records;
    CompressedRecord* compressed_records;
    void** shared_extra_data;

    if (allocate_records(n, &records, &compressed_records, &shared_extra_data) != 0) {
        fprintf(stderr, "Failed to allocate records\n");
        return 1;
    }

    initialize_records(n, records, compressed_records, shared_extra_data);

    log_memory_usage(n, records, compressed_records, shared_extra_data);

    // Free allocated memory
    for (int i = 0; i < n; i++) {
        if (!records[i].is_compressed) free(records[i].extra_data);
    }
    free(records);
    free(shared_extra_data);

    return 0;
}
