import java.io.*;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class StateInitializer {

    private static final Lock lock = new ReentrantLock();
    private static MoSTState stateObject;
    private static Bitmap themeBitmap;
    private static String defaultThemeDir = "/path/to/default/theme/dir";
    private static Cache<String, Bitmap> themeCache = new LRUCache<>(100);

    public static MoSTState initializeState(String filePath) {
        lock.lock();
        try {
            if (stateObject != null) return stateObject;

            File file = new File(filePath);
            if (!file.exists()) {
                log("File does not exist: " + filePath);
                return null;
            }

            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                Object obj = ois.readObject();
                if (obj instanceof MoSTState) {
                    stateObject = (MoSTState) obj;
                    log("State object loaded successfully.");
                } else {
                    log("Invalid state object in file: " + filePath);
                }
            } catch (IOException | ClassNotFoundException e) {
                log("Error loading state object from file: " + e.getMessage());
            }

            return stateObject;
        } finally {
            lock.unlock();
        }
    }

    public static void recycleThemeBitmap() {
        lock.lock();
        try {
            if (themeBitmap != null) {
                themeBitmap.recycle();
                themeBitmap = null;
                log("Theme bitmap recycled.");
            }
        } finally {
            lock.unlock();
        }
    }

    public static void setDefaultThemeDir(String dirPath) {
        lock.lock();
        try {
            if (defaultThemeDir == null || defaultThemeDir.isEmpty()) {
                defaultThemeDir = dirPath;
                log("Default theme directory set to: " + defaultThemeDir);
            }
        } finally {
            lock.unlock();
        }
    }

    public static Bitmap parsePngFile(String cacheRoot, String fileName) {
        lock.lock();
        try {
            String key = cacheRoot + "/" + fileName;
            if (themeCache.containsKey(key)) {
                log("Cache hit for: " + key);
                return themeCache.get(key);
            } else {
                File file = new File(cacheRoot, fileName);
                if (!file.exists()) {
                    log("File does not exist: " + file.getAbsolutePath());
                    return null;
                }

                try (InputStream is = new FileInputStream(file)) {
                    Bitmap bitmap = BitmapFactory.decodeStream(is);
                    themeCache.put(key, bitmap);
                    log("Cache miss for: " + key);
                    return bitmap;
                } catch (IOException e) {
                    log("Error parsing PNG file: " + e.getMessage());
                    return null;
                }
            }
        } finally {
            lock.unlock();
        }
    }

    private static void log(String message) {
        System.out.println(message); // Replace with actual logging framework
    }
}
