#define MAX_RECORDS 1000000
#define MEMORY_THRESHOLD 0.8

typedef struct {
    int value;
    char message[256];
} record;

int initialize_records(long **offsets, int **keys, record **records, int *record_count, int range_start, int range_end) {
    // Get available memory and calculate threshold
    unsigned long total_memory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
    unsigned long max_allocable_memory = (unsigned long)(total_memory * MEMORY_THRESHOLD);

    // Calculate the size of each record
    size_t record_size = sizeof(record);

    // Calculate the maximum number of records that can be allocated within the threshold
    int max_records = max_allocable_memory / record_size;

    // Set the maximum number of records to initialize based on configuration or available memory
    int num_records_to_init = MAX_RECORDS < max_records ? MAX_RECORDS : max_records;

    // Allocate memory for arrays
    *offsets = (long *)malloc(num_records_to_init * sizeof(long));
    *keys = (int *)malloc(num_records_to_init * sizeof(int));
    *records = (record *)malloc(num_records_to_init * record_size);

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        free(*offsets);
        free(*keys);
        free(*records);
        *record_count = 0;
        return -1;
    }

    // Initialize records with random values and process ID/timestamp
    pid_t pid = getpid();
    time_t now = time(NULL);
    for (int i = 0; i < num_records_to_init; i++) {
        (*offsets)[i] = rand() % (range_end - range_start + 1) + range_start;
        (*keys)[i] = rand();
        snprintf((*records)[i].message, sizeof((*records)[i].message), "PID: %d, Timestamp: %ld", pid, now);
    }

    // Set the record count
    *record_count = num_records_to_init;

    return 0;
}
