const { Queue } = require('queue');

class PacketManager {
  constructor() {
    this.queue = new Queue();
    this.priorityQueue = new Queue();
    this.locked = false;
  }

  enqueue(packet) {
    if (packet.isPriority()) {
      this.priorityQueue.enqueue(packet);
    } else {
      this.queue.enqueue(packet);
    }
  }

  dequeue(count) {
    return this.withLock(() => {
      let result = Buffer.alloc(0);
      for (let i = 0; i < count; i++) {
        const packet = this.priorityQueue.isEmpty() ? this.queue.dequeue() : this.priorityQueue.dequeue();
        if (!packet) break;
        result = Buffer.concat([result, packet.getData()]);
      }
      return result;
    });
  }

  withLock(callback) {
    while (this.locked) {}
    this.locked = true;
    try {
      return callback();
    } finally {
      this.locked = false;
    }
  }
}

class Packet {
  constructor(data, isPriority) {
    this.data = data;
    this.isPriority = isPriority;
  }

  getData() {
    return this.data;
  }

  isPriority() {
    // Implement priority logic based on packet metadata
    return this.data[0] === 1; // Example: Priority packets start with byte 1
  }
}

// Usage example:
const manager = new PacketManager();
manager.enqueue(new Packet(Buffer.from([1, 2, 3]), true));
manager.enqueue(new Packet(Buffer.from([4, 5, 6]), false));
console.log(manager.dequeue(2)); // Output: <Buffer 01 02 03>
