#include <pthread.h>

typedef struct {
    int ResourceID;
    time_t Timestamp;
    double *MetricsData;
    size_t MetricsCount;
} ResourceMetrics;

typedef struct {
    ResourceMetrics **metricsArray;
    size_t currentSize;
    size_t maxSize;
    pthread_mutex_t lock;
    FILE *allocationLog;
    FILE *duplicateLog;
    size_t successfulAllocations;
    size_t failedAllocations;
    size_t uniqueResourceIDs;
} MetricsManager;

void initMetricsManager(MetricsManager *manager, size_t initialSize, size_t maxSize) {
    manager->metricsArray = (ResourceMetrics **)malloc(initialSize * sizeof(ResourceMetrics *));
    manager->currentSize = 0;
    manager->maxSize = maxSize;
    pthread_mutex_init(&manager->lock, NULL);
    manager->allocationLog = fopen("allocation_log.txt", "w");
    manager->duplicateLog = fopen("duplicate_log.txt", "w");
    manager->successfulAllocations = 0;
    manager->failedAllocations = 0;
    manager->uniqueResourceIDs = 0;
}

void destroyMetricsManager(MetricsManager *manager) {
    for (size_t i = 0; i < manager->currentSize; ++i) {
        free(manager->metricsArray[i]->MetricsData);
        free(manager->metricsArray[i]);
    }
    free(manager->metricsArray);
    pthread_mutex_destroy(&manager->lock);
    fclose(manager->allocationLog);
    fclose(manager->duplicateLog);
}

int addResourceMetrics(MetricsManager *manager, ResourceMetrics *newMetric) {
    pthread_mutex_lock(&manager->lock);
    if (manager->currentSize >= manager->maxSize) {
        fprintf(stderr, "Memory limit exceeded.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (size_t i = 0; i < manager->currentSize; ++i) {
        if (manager->metricsArray[i]->ResourceID == newMetric->ResourceID) {
            fprintf(manager->duplicateLog, "Duplicate ResourceID: %d\n", newMetric->ResourceID);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    manager->metricsArray[manager->currentSize] = newMetric;
    ++manager->currentSize;
    ++manager->uniqueResourceIDs;
    ++manager->successfulAllocations;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void logAllocationStatus(MetricsManager *manager) {
    fprintf(manager->allocationLog, "Successful allocations: %zu\n", manager->successfulAllocations);
    fprintf(manager->allocationLog, "Failed allocations: %zu\n", manager->failedAllocations);
}
