typedef struct {
    int value;
    char message[256];
    time_t timestamp;
} record;

typedef struct {
    long offset;
    int key;
    record *data;
    time_t event_timestamp;
} array_info;

int initialize_arrays(array_info *arrays, int max_records) {
    arrays->offset = (long *)malloc(max_records * sizeof(long));
    arrays->key = (int *)malloc(max_records * sizeof(int));
    arrays->data = (record *)malloc(max_records * sizeof(record));
    arrays->event_timestamp = time(NULL);

    if (!arrays->offset || !arrays->key || !arrays->data) {
        fprintf(stderr, "Memory allocation failed\n");
        free(arrays->offset);
        free(arrays->key);
        free(arrays->data);
        return -1;
    }

    int counter = 0;
    srand(time(NULL));

    for (int i = 0; i < max_records; i++) {
        arrays->offset[i] = rand();
        arrays->key[i] = rand() % 100;

        if (getrusage(RUSAGE_SELF, &ru) == -1) {
            fprintf(stderr, "Failed to get resource usage\n");
            free(arrays->offset);
            free(arrays->key);
            free(arrays->data);
            return -1;
        }

        double used_memory = ru.ru_maxrss / 1024.0;
        if (used_memory > MEMORY_THRESHOLD * sysconf(_SC_PHYS_PAGES) * getpagesize()) {
            fprintf(stderr, "Memory usage exceeds threshold\n");
            free(arrays->offset);
            free(arrays->key);
            free(arrays->data);
            return -1;
        }

        arrays->data[i].value = rand() % 1000;
        snprintf(arrays->data[i].message, sizeof(arrays->data[i].message), "PID: %d, Timestamp: %ld", getpid(), time(NULL));
        arrays->data[i].timestamp = time(NULL);

        counter++;
    }

    return counter;
}

int main() {
    array_info arrays;
    int max_records = 1000000;

    int initialized_count = initialize_arrays(&arrays, max_records);
    if (initialized_count == -1) {
        fprintf(stderr, "Failed to initialize arrays\n");
        return EXIT_FAILURE;
    }

    printf("Successfully initialized %d records\n", initialized_count);

    free(arrays.offset);
    free(arrays.key);
    free(arrays.data);

    return EXIT_SUCCESS;
}
