function traverseAndTransformDOM(node, config, pipelines = [], depth = 0) {
    if (!node || !config) return;

    const { tagName, classNames, id, maxDepth } = config;
    const shouldTraverse = (tagName && node.tagName === tagName) ||
                           (classNames && classNames.some(className => node.classList.contains(className))) ||
                           (id && node.id === id) ||
                           depth < maxDepth;

    if (shouldTraverse) {
        pipelines.forEach(pipeline => pipeline(node));
    }

    if (node.nodeType === Node.ELEMENT_NODE && depth < maxDepth) {
        for (let child of node.childNodes) {
            traverseAndTransformDOM(child, config, pipelines, depth + 1);
        }
    }
}

// Example usage:
const config = {
    tagName: 'div',
    classNames: ['example'],
    id: 'uniqueId',
    maxDepth: 5
};

const pipelines = [
    node => node.style.backgroundColor = 'yellow',
    node => console.log(`Transformed ${node.tagName}`)
];

traverseAndTransformDOM(document.body, config, pipelines);
