#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define MAX_RECORDS 1000000
#define MEMORY_POOL_SIZE (8 * 1024 * 1024) // 8MB

typedef struct {
    int value;
    char message[256];
} record;

record* initialize_records(int num_records, int min_value, int max_value, int* counter, bool* success) {
    if (num_records > MAX_RECORDS) {
        *counter = 0;
        *success = false;
        return NULL;
    }

    // Check available memory
    FILE* meminfo = fopen("/proc/meminfo", "r");
    if (!meminfo) {
        perror("Failed to open /proc/meminfo");
        *counter = 0;
        *success = false;
        return NULL;
    }
    char line[256];
    unsigned long total_memory, free_memory;
    while (fgets(line, sizeof(line), meminfo)) {
        if (sscanf(line, "MemTotal: %lu kB", &total_memory) == 1) {
            break;
        }
    }
    fclose(meminfo);

    unsigned long used_memory = total_memory - free_memory;
    if ((used_memory + num_records * sizeof(record)) > (0.8 * total_memory)) {
        *counter = 0;
        *success = false;
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory");
        *counter = 0;
        *success = false;
        return NULL;
    }

    pid_t pid = getpid();
    time_t now = time(NULL);
    char timestamp[256];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        snprintf(records[i].message, sizeof(records[i].message), "PID: %d, Timestamp: %s", pid, timestamp);
    }

    *counter = num_records;
    *success = true;
    return records;
}

int main() {
    srand(time(NULL));
    int num_records = 1000;
    int min_value = 0;
    int max_value = 10000;
    int counter;
    bool success;

    record* records = initialize_records(num_records, min_value, max_value, &counter, &success);
    if (records) {
        for (int i = 0; i < counter; i++) {
            printf("Record %d: Value = %d, Message = %s\n", i, records[i].value, records[i].message);
        }
        free(records);
    } else {
        printf("Failed to initialize records.\n");
    }

    return 0;
}
