#define MAX_RNTI 1024
#define MIN_RECORD_VALUE -100
#define MAX_RECORD_VALUE 100

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *records;
    size_t capacity;
    size_t size;
} DynamicCollection;

DynamicCollection* create_dynamic_collection(size_t initial_capacity) {
    DynamicCollection *collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->records = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    return collection;
}

void destroy_dynamic_collection(DynamicCollection *collection) {
    if (collection) {
        free(collection->records);
        free(collection);
    }
}

int add_record(DynamicCollection *collection, int rx_ue_information_tag, int rnti, int crc_indication_rel8_tag) {
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_records = (NFAPI_CRC_INDICATION_PDU_T*)realloc(collection->records, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_records) return -1; // Memory allocation failed

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T record = {rx_ue_information_tag, rnti, crc_indication_rel8_tag};
    collection->records[collection->size++] = record;

    return 0; // Success
}

int validate_collection(DynamicCollection *collection) {
    for (size_t i = 1; i < collection->size; ++i) {
        if (collection->records[i].rnti == collection->records[i - 1].rnti) {
            return -1; // Consecutive records with the same RNTI
        }
    }

    return 0; // Valid
}

void initialize_records(DynamicCollection *collection, size_t num_records) {
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        int value = MIN_RECORD_VALUE + rand() % (MAX_RECORD_VALUE - MIN_RECORD_VALUE + 1);
        add_record(collection, i, i % MAX_RNTI, value); // Example values
    }
}

int main() {
    DynamicCollection *collection = create_dynamic_collection(10);
    if (!collection) return -1; // Memory allocation failed

    initialize_records(collection, 20);

    if (validate_collection(collection) != 0) {
        destroy_dynamic_collection(collection);
        return -1; // Invalid collection
    }

    destroy_dynamic_collection(collection);
    return 0;
}
