#define MAX_BUFFER_SIZE 1024 * 1024 // 1MB
#define MIN_BUFFER_SIZE 1024       // 1KB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *error_log = fopen("allocation_errors.log", "w");
FILE *duplicate_rnti_log = fopen("duplicate_rntis.log", "w");

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int N, size_t max_size) {
    pthread_mutex_lock(&allocation_lock);
    if (max_size < MIN_BUFFER_SIZE || max_size > MAX_BUFFER_SIZE) {
        fprintf(error_log, "Invalid buffer size: %zu\n", max_size);
        pthread_mutex_unlock(&allocation_lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        fprintf(error_log, "Memory allocation failed for %d elements\n", N);
        pthread_mutex_unlock(&allocation_lock);
        return NULL;
    }

    int rnti_set[1024] = {0}; // Assuming RNTI values are within 0-1023
    int unique_rntis = 0;

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        do {
            array[i].RNTI = rand() % 1024;
        } while (rnti_set[array[i].RNTI] == 1);
        rnti_set[array[i].RNTI] = 1;
        unique_rntis++;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    if (unique_rntis != N) {
        fprintf(duplicate_rnti_log, "Duplicate RNTIs detected: %d\n", N - unique_rntis);
    }

    pthread_mutex_unlock(&allocation_lock);
    return array;
}

void* thread_function(void* arg) {
    int N = *(int*)arg;
    size_t max_size = 1024 * 1024; // 1MB
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_and_populate_array(N, max_size);
    if (array != NULL) {
        // Process the array
        free(array);
    }
    return NULL;
}

int main() {
    pthread_t threads[5];
    int thread_args[] = {100, 200, 300, 400, 500};

    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, thread_function, &thread_args[i]);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    fclose(error_log);
    fclose(duplicate_rnti_log);

    return 0;
}
