typedef struct {
    NetworkElementState *elements;
    int count;
    pthread_mutex_t lock;
} ResourceBundle;

int loadResourceBundle(const char *filePath, ResourceBundle *bundle) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    bundle->count = 0;
    while (fscanf(file, "%d %255s", &bundle->elements[bundle->count].neId, bundle->elements[bundle->count].connectionConfig) == 2) {
        bundle->elements[bundle->count].bandwidthReservations = malloc(sizeof(int));
        if (!bundle->elements[bundle->count].bandwidthReservations) {
            perror("Failed to allocate memory for bandwidth reservations");
            fclose(file);
            return -1;
        }
        *bundle->elements[bundle->count].bandwidthReservations = 0; // Initialize bandwidth reservation
        bundle->count++;
    }

    fclose(file);
    return bundle->count;
}

void initializeResourceBundle(ResourceBundle *bundle) {
    bundle->elements = malloc(MAX_NETWORK_ELEMENTS * sizeof(NetworkElementState));
    if (!bundle->elements) {
        perror("Failed to allocate memory for resource bundle");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&bundle->lock, NULL);
}

void cleanupResourceBundle(ResourceBundle *bundle) {
    for (int i = 0; i < bundle->count; i++) {
        free(bundle->elements[i].bandwidthReservations);
    }
    free(bundle->elements);
    pthread_mutex_destroy(&bundle->lock);
}
