#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 1000

typedef struct {
    time_t timestamp;
    char event_type[50];
    char metadata[256];
} Event;

typedef struct {
    Event events[MAX_EVENTS];
    int head, tail;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} CircularBuffer;

void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    pthread_mutex_init(&buffer->lock, NULL);
    pthread_cond_init(&buffer->not_full, NULL);
    pthread_cond_init(&buffer->not_empty, NULL);
}

int is_full(CircularBuffer *buffer) {
    return (buffer->tail + 1) % MAX_EVENTS == buffer->head;
}

int is_empty(CircularBuffer *buffer) {
    return buffer->head == buffer->tail;
}

void enqueue_event(CircularBuffer *buffer, Event event) {
    pthread_mutex_lock(&buffer->lock);
    while (is_full(buffer)) {
        pthread_cond_wait(&buffer->not_full, &buffer->lock);
    }
    buffer->events[buffer->tail] = event;
    buffer->tail = (buffer->tail + 1) % MAX_EVENTS;
    pthread_cond_signal(&buffer->not_empty);
    pthread_mutex_unlock(&buffer->lock);
}

Event dequeue_event(CircularBuffer *buffer) {
    Event event;
    pthread_mutex_lock(&buffer->lock);
    while (is_empty(buffer)) {
        pthread_cond_wait(&buffer->not_empty, &buffer->lock);
    }
    event = buffer->events[buffer->head];
    buffer->head = (buffer->head + 1) % MAX_EVENTS;
    pthread_cond_signal(&buffer->not_full);
    pthread_mutex_unlock(&buffer->lock);
    return event;
}

void log_event(CircularBuffer *buffer, Event event) {
    enqueue_event(buffer, event);
}

int main() {
    CircularBuffer buffer;
    init_buffer(&buffer);

    // Example usage
    Event event1 = {time(NULL), "INFO", "System started"};
    log_event(&buffer, event1);

    Event received_event = dequeue_event(&buffer);
    printf("Received event: %s at %ld\n", received_event.event_type, received_event.timestamp);

    return 0;
}
