// Define the record structure
typedef struct {
    long offset;
    int key;
    struct record *next;
    void *extra_metadata;
    MAC_TransportChannelInfo channel_info;
} Record;

// Define the memory pool manager structure
typedef struct {
    Record **pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPoolManager;

// Initialize the memory pool manager
void init_memory_pool_manager(MemoryPoolManager *manager, size_t size) {
    manager->pool = (Record **)malloc(size * sizeof(Record *));
    memset(manager->pool, 0, size * sizeof(Record *));
    manager->size = size;
    manager->used = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Allocate a record from the memory pool
Record *allocate_record(MemoryPoolManager *manager) {
    Record *record = NULL;
    pthread_mutex_lock(&manager->lock);
    if (manager->used < manager->size) {
        record = manager->pool[manager->used++];
    }
    pthread_mutex_unlock(&manager->lock);
    return record;
}

// Free a record back to the memory pool
void free_record(MemoryPoolManager *manager, Record *record) {
    pthread_mutex_lock(&manager->lock);
    if (manager->used > 0 && manager->pool[manager->used - 1] == NULL) {
        manager->pool[--manager->used] = record;
    }
    pthread_mutex_unlock(&manager->lock);
}

