#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MIN_VALUE 10
#define MAX_VALUE 100

typedef struct {
    int value;
    long* offset;
    int key;
    char field_name[50];
    char field_value[50];
} record;

record* allocate_records(int n, int min_value, int max_value) {
    static size_t total_allocated = 0;
    record* records = NULL;

    if (n * sizeof(record) > MAX_MEMORY - total_allocated) {
        // Partial allocation
        n = (MAX_MEMORY - total_allocated) / sizeof(record);
    }

    records = malloc(n * sizeof(record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < n; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].offset = malloc(sizeof(long));
        if (!records[i].offset) {
            // Handle memory allocation failure
            free(records);
            return NULL;
        }
        *records[i].offset = i * sizeof(record); // Contiguous block of memory

        // Generate unique field names and values
        do {
            snprintf(records[i].field_name, 50, "Field%d", rand() % 100);
            snprintf(records[i].field_value, 50, "Value%d", rand() % 100);
        } while (i > 0 && strcmp(records[i].field_name, records[i - 1].field_name) == 0);

        total_allocated += sizeof(record) + sizeof(long);
    }

    return records;
}

void free_records(record* records, int n) {
    for (int i = 0; i < n; ++i) {
        free(records[i].offset);
    }
    free(records);
}
