typedef struct {
    int value;
} record;

long* allocateLongArray(int size) {
    return (long*)malloc(size * sizeof(long));
}

int* allocateIntArray(int size) {
    return (int*)malloc(size * sizeof(int));
}

record* allocateRecordArray(int size) {
    return (record*)malloc(size * sizeof(record));
}

void initializeArrays(long* offsets, int* keys, record* records, int maxKey, int minValue, int maxValue) {
    for (int i = 0; i < maxKey; ++i) {
        offsets[i] = i;
        keys[i] = i + 1;
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
        if (i > 0 && records[i].value == records[i - 1].value) {
            records[i].value += 1; // Ensure no two consecutive records share the same value
        }
    }
}

int findMax(int* array, int size) {
    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void processAndFindMax() {
    srand(time(NULL));
    int maxKey, minValue, maxValue;
    printf("Enter max key value: ");
    scanf("%d", &maxKey);
    printf("Enter minimum value for records: ");
    scanf("%d", &minValue);
    printf("Enter maximum value for records: ");
    scanf("%d", &maxValue);

    long* offsets = allocateLongArray(maxKey);
    int* keys = allocateIntArray(maxKey);
    record* records = allocateRecordArray(maxKey);

    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    initializeArrays(offsets, keys, records, maxKey, minValue, maxValue);

    int inputSize;
    printf("Enter number of integers to process: ");
    scanf("%d", &inputSize);
    if (inputSize > 10000) {
        fprintf(stderr, "Input size exceeds maximum limit.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    int* inputArray = allocateIntArray(inputSize);
    if (inputArray == NULL) {
        fprintf(stderr, "Memory allocation failed for input array.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    printf("Enter integers to process:\n");
    for (int i = 0; i < inputSize; ++i) {
        scanf("%d", &inputArray[i]);
    }

    int maxInputValue = findMax(inputArray, inputSize);
    printf("Largest integer in input: %d\n", maxInputValue);

    free(offsets);
    free(keys);
    free(records);
    free(inputArray);
}

int main() {
    processAndFindMax();
    return 0;
}
