#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *key;
    int value;
    time_t last_modified;
} ConfigSetting;

typedef struct {
    ConfigSetting **settings;
    size_t count;
    pthread_mutex_t lock;
} ConfigManager;

ConfigManager* config_manager_create() {
    ConfigManager *manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    manager->settings = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void config_manager_add_or_update(ConfigManager *manager, const char *key, int value) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->settings[i]->key, key) == 0) {
            free(manager->settings[i]->key);
            manager->settings[i]->value = value;
            manager->settings[i]->last_modified = time(NULL);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }
    ConfigSetting *new_setting = (ConfigSetting*)malloc(sizeof(ConfigSetting));
    new_setting->key = strdup(key);
    new_setting->value = value;
    new_setting->last_modified = time(NULL);
    manager->settings = realloc(manager->settings, (manager->count + 1) * sizeof(ConfigSetting*));
    manager->settings[manager->count++] = new_setting;
    pthread_mutex_unlock(&manager->lock);
}

int config_manager_get_value(ConfigManager *manager, const char *key) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->settings[i]->key, key) == 0) {
            int value = manager->settings[i]->value;
            pthread_mutex_unlock(&manager->lock);
            return value;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Key not found
}

void config_manager_destroy(ConfigManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->settings[i]->key);
        free(manager->settings[i]);
    }
    free(manager->settings);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
