#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct dataNode {
    char* identifier;
    int frequency;
    struct dataNode* prev;
    struct dataNode* next;
} dataNode;

typedef struct {
    dataNode* head;
    dataNode* tail;
    pthread_mutex_t lock;
} doublyLinkedList;

void initializeList(doublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

dataNode* createNode(const char* identifier) {
    dataNode* newNode = (dataNode*)malloc(sizeof(dataNode));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    newNode->identifier = strdup(identifier);
    newNode->frequency = 0;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

void insertNode(doublyLinkedList* list, dataNode* node) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->lock);
}

void* processFile(void* arg) {
    doublyLinkedList* list = (doublyLinkedList*)arg;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        // Parse the line and update the frequency count
        // ...
    }
    return NULL;
}

void parseAndAggregateData() {
    doublyLinkedList list;
    initializeList(&list);

    pthread_t threads[10]; // Example: 10 threads for demonstration
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, processFile, &list) != 0) {
            perror("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up resources
    dataNode* current = list.head;
    while (current != NULL) {
        dataNode* next = current->next;
        free(current->identifier);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list.lock);
}

int main() {
    parseAndAggregateData();
    return 0;
}
