void* allocate_and_initialize(void* arg) {
    long offset_size, key_size;
    record** records_ptr = (record**)arg;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Get user input for array sizes
    printf("Enter the number of elements: ");
    scanf("%ld", &offset_size);
    if (offset_size > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Number of elements exceeds maximum limit.\n");
        return NULL;
    }

    key_size = offset_size;

    // Allocate memory for arrays
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    int* keys = (int*)malloc(key_size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    // Initialize arrays
    for (long i = 0; i < offset_size; i++) {
        offsets[i] = i * 10; // Example initialization
    }
    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % 100; // Initialize with random values
    }

    // Allocate memory for records array
    record* records = (record*)malloc(key_size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize records with random values
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < key_size; i++) {
        records[i].value = rand() % 1000; // Random value within range
    }
    *records_ptr = records;
    pthread_mutex_unlock(&mutex);

    // Free allocated memory if exceeding memory threshold
    if ((offset_size + key_size) * sizeof(long) + (key_size * sizeof(record)) > MEMORY_THRESHOLD) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    return records_ptr;
}

int main() {
    record* records = NULL;

    // Seed random number generator
    srand(time(NULL));

    pthread_t thread;
    if (pthread_create(&thread, NULL, allocate_and_initialize, &records) != 0) {
        fprintf(stderr, "Error: Thread creation failed.\n");
        return 1;
    }

    pthread_join(thread, NULL);

    // Use records array...

    // Free allocated memory
    free(records);

    return 0;
}
