import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class ConnectionPoolManager {
    private Selector selector;
    private int maxConnections;
    private long connectionTimeout;
    private long idleTimeout;
    private ConfigurationManager configManager;

    public ConnectionPoolManager(int maxConnections, long connectionTimeout, long idleTimeout, ConfigurationManager configManager) throws IOException {
        this.selector = Selector.open();
        this.maxConnections = maxConnections;
        this.connectionTimeout = connectionTimeout;
        this.idleTimeout = idleTimeout;
        this.configManager = configManager;
    }

    public void start() throws IOException {
        // Initialize connections based on configuration
        Set<InetSocketAddress> endpoints = configManager.getEndpoints();
        for (InetSocketAddress endpoint : endpoints) {
            SocketChannel channel = SocketChannel.open(endpoint);
            channel.configureBlocking(false);
            channel.register(selector, SelectionKey.OP_CONNECT);
        }

        while (true) {
            selector.select();
            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();

                if (key.isConnectable()) {
                    connect(key);
                } else if (key.isReadable()) {
                    read(key);
                } else if (key.isWritable()) {
                    write(key);
                }

                keyIterator.remove();
            }
        }
    }

    private void connect(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        try {
            boolean connected = channel.finishConnect();
            if (connected) {
                channel.register(selector, SelectionKey.OP_READ | SelectionKey.OP_WRITE);
                log("Connected to " + channel.getRemoteAddress());
            }
        } catch (IOException e) {
            channel.close();
            log("Failed to connect to " + channel.getRemoteAddress());
        }
    }

    private void read(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        int bytesRead = channel.read(buffer);

        if (bytesRead == -1) {
            channel.close();
            log("Connection closed by remote peer");
        } else if (bytesRead > 0) {
            buffer.flip();
            byte[] data = new byte[buffer.remaining()];
            buffer.get(data);
            log("Received data: " + new String(data));
        }
    }

    private void write(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.wrap("Hello, Server!".getBytes());
        channel.write(buffer);

        if (!buffer.hasRemaining()) {
            log("Data sent to " + channel.getRemoteAddress());
        }
    }

    private void log(String message) {
        System.out.println(message);
    }

    public static void main(String[] args) throws IOException {
        ConfigurationManager configManager = new ConfigurationManager();
        ConnectionPoolManager manager = new ConnectionPoolManager(10, 5000, 30000, configManager);
        manager.start();
    }
}

interface ConfigurationManager {
    Set<InetSocketAddress> getEndpoints();
}
