    private static final int MAX_CACHE_SIZE = 100 * 1024 * 1024; // 100MB
    private Map<String, Bitmap> cache;
    private File themeDir;

    public ThemeCacheManager(Context context) {
        cache = new HashMap<>();
        themeDir = new File(context.getFilesDir(), DEFAULT_THEME_DIR);
        if (!themeDir.exists()) {
            themeDir.mkdirs();
        }
    }

    public void loadThemeBitmap(String key, String filePath) {
        new LoadBitmapTask(key).execute(filePath);
    }

    private class LoadBitmapTask extends AsyncTask<String, Void, Bitmap> {
        private final String key;

        public LoadBitmapTask(String key) {
            this.key = key;
        }

        @Override
        protected Bitmap doInBackground(String... params) {
            try {
                return Bitmap.createScaledBitmap(BitmapFactory.decodeFile(params[0]), getOptimalWidth(), getOptimalHeight(), true);
            } catch (IOException e) {
                e.printStackTrace();
                return null;
            }
        }

        @Override
        protected void onPostExecute(Bitmap bitmap) {
            if (bitmap != null) {
                cache.put(key, bitmap);
                checkCacheSize();
            }
        }
    }

    private int getOptimalWidth() {
        // Implement logic to determine optimal width based on screen density and resolution
        return 1024; // Example value
    }

    private int getOptimalHeight() {
        // Implement logic to determine optimal height based on screen density and resolution
        return 768; // Example value
    }

    private void checkCacheSize() {
        if (cache.size() * Bitmap.getByteCount(0, 0) > MAX_CACHE_SIZE) {
            cleanupCache();
        }
    }

    private void cleanupCache() {
        // Implement logic to remove unused cache entries and free up resources
    }

    public void invalidateThemeBitmap(String key) {
        cache.remove(key);
    }

    public Bitmap getThemeBitmap(String key) {
        return cache.get(key);
    }
}
