#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1 MB
#define MAX_OFFSET 1000

typedef struct {
    long offset;
    int key;
} offset_key;

typedef struct {
    int data;
} record;

void handleDataManagement(int n) {
    if (n <= 0) {
        fprintf(stderr, "Error: Invalid number of elements.\n");
        return;
    }

    // Allocate memory for offset_key array
    offset_key *offset_keys = malloc(n * sizeof(offset_key));
    if (!offset_keys) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    // Initialize and populate offset_key array
    for (int i = 0; i < n; i++) {
        offset_keys[i].offset = rand() % MAX_OFFSET;
        offset_keys[i].key = i;
    }

    // Allocate memory for record array within the memory limit
    int records_per_block = MAX_MEMORY / sizeof(record);
    record *records = NULL;
    int num_blocks = (n + records_per_block - 1) / records_per_block;

    for (int i = 0; i < num_blocks; i++) {
        record *new_records = realloc(records, (i + 1) * records_per_block * sizeof(record));
        if (!new_records) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            free(records);
            return;
        }
        records = new_records;

        // Initialize random values for each block
        srand(time(NULL) ^ i); // Seed for different blocks
        for (int j = 0; j < records_per_block && (i * records_per_block + j) < n; j++) {
            records[i * records_per_block + j].data = rand() % 201 - 100;
        }
    }

    // Validate offsets and handle errors
    for (int i = 0; i < n; i++) {
        if (offset_keys[i].offset < 0 || offset_keys[i].offset >= MAX_OFFSET) {
            fprintf(stderr, "Error: Invalid offset at index %d.\n", i);
            free(offset_keys);
            free(records);
            return;
        }
    }

    // Free allocated memory
    free(offset_keys);
    free(records);

    printf("Memory management completed successfully.\n");
}

int main() {
    srand(time(NULL));
    handleDataManagement(1000); // Example with 1000 elements
    return 0;
}
