#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define VALUE_RANGE 100

typedef struct {
    int value;
    long offset;
} record;

record records[MAX_RECORDS];
int num_records = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_cache(long target_sum, int min_value, int max_value) {
    pthread_mutex_lock(&cache_lock);
    srand(time(NULL));
    int current_sum = 0;
    for (int i = 0; i < MAX_RECORDS && current_sum <= target_sum; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].offset = i * sizeof(record);
        current_sum += records[i].value;
    }
    num_records = current_sum > target_sum ? i : MAX_RECORDS;
    pthread_mutex_unlock(&cache_lock);
}

void distribute_new_record(int new_value, long offset) {
    pthread_mutex_lock(&cache_lock);
    if (num_records < MAX_RECORDS) {
        records[num_records].value = new_value;
        records[num_records].offset = offset;
        num_records++;
    }
    pthread_mutex_unlock(&cache_lock);
}

void sort_cache() {
    pthread_mutex_lock(&cache_lock);
    qsort(records, num_records, sizeof(record), (int (*)(const void *, const void *))compare_records);
    pthread_mutex_unlock(&cache_lock);
}

int compare_records(const void *a, const void *b) {
    return ((record *)a)->offset - ((record *)b)->offset;
}
