import json
import os
from cryptography.fernet import Fernet

class ConfigManager:
    def __init__(self, config_path):
        self.config_path = config_path
        self.cipher_suite = None

    def load_config(self):
        if not os.path.exists(self.config_path):
            raise FileNotFoundError("Configuration file not found.")
        with open(self.config_path, 'r') as file:
            return json.load(file)

    def save_config(self, config):
        with open(self.config_path, 'w') as file:
            json.dump(config, file, indent=4)

    def encrypt_data(self, data):
        if not self.cipher_suite:
            self.cipher_suite = Fernet.generate_key()
            os.environ['CIPHER_KEY'] = self.cipher_suite.decode('utf-8')
        cipher = Fernet(self.cipher_suite)
        return cipher.encrypt(data.encode('utf-8'))

    def decrypt_data(self, encrypted_data):
        if not self.cipher_suite:
            self.cipher_suite = os.getenv('CIPHER_KEY').encode('utf-8')
        cipher = Fernet(self.cipher_suite)
        return cipher.decrypt(encrypted_data).decode('utf-8')

class ConfigUpdater(ConfigManager):
    def __init__(self, config_path):
        super().__init__(config_path)

    def update_config(self, new_params):
        try:
            current_config = self.load_config()
            for key, value in new_params.items():
                if isinstance(value, int) and 'range' in new_params:
                    min_val, max_val = new_params['range']
                    value = random.randint(min_val, max_val)
                elif isinstance(value, str) and 'encrypt' in new_params:
                    value = self.encrypt_data(value)
                current_config[key] = value
            self.save_config(current_config)
        except Exception as e:
            print(f"Error updating configuration: {e}")

# Example usage
config_path = 'path/to/config.json'
updater = ConfigUpdater(config_path)
new_params = {
    'api_key': {'value': 'sensitive_data', 'encrypt': True},
    'random_value': {'value': (1, 100), 'range': True}
}
updater.update_config(new_params)
