MemoryPool memory_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void init_memory_pool(size_t initial_capacity) {
    memory_pool.capacity = initial_capacity;
    memory_pool.array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memory_pool.array) {
        fprintf(stderr, "Failed to allocate memory for memory pool\n");
        exit(EXIT_FAILURE);
    }
}

void* allocate_memory(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.size + size > memory_pool.capacity) {
        // Double the capacity
        memory_pool.capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(memory_pool.array, memory_pool.capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Failed to reallocate memory for memory pool\n");
            pthread_mutex_unlock(&memory_pool.lock);
            return NULL;
        }
        memory_pool.array = new_array;
    }
    void *ptr = (void *)&memory_pool.array[memory_pool.size];
    memory_pool.size += size;
    pthread_mutex_unlock(&memory_pool.lock);
    return ptr;
}

void free_memory(void *ptr, size_t size) {
    // No-op for simplicity
}

