class NetworkResourcePool {
public:
    NetworkResourcePool(int maxCPU, int memoryLimit, int diskIOPerSecond)
        : maxCPU(maxCPU), memoryLimit(memoryLimit), diskIOPerSecond(diskIOPerSecond) {}

    bool allocateResources(int cpuUsage, int memoryUsage, int diskIO) {
        std::lock_guard<std::mutex> lock(mutex);
        if (cpuUsage + currentCPU > maxCPU || memoryUsage + currentMemory > memoryLimit || diskIO + currentDiskIO > diskIOPerSecond) {
            return false;
        }
        currentCPU += cpuUsage;
        currentMemory += memoryUsage;
        currentDiskIO += diskIO;
        return true;
    }

    void deallocateResources(int cpuUsage, int memoryUsage, int diskIO) {
        std::lock_guard<std::mutex> lock(mutex);
        currentCPU -= cpuUsage;
        currentMemory -= memoryUsage;
        currentDiskIO -= diskIO;
    }

private:
    int maxCPU;
    int memoryLimit;
    int diskIOPerSecond;
    int currentCPU = 0;
    int currentMemory = 0;
    int currentDiskIO = 0;
    std::mutex mutex;
};

class VMManager {
public:
    void addVM(const std::string& vmID, const NetworkResourcePool& pool) {
        std::lock_guard<std::mutex> lock(mutex);
        vmPools[vmID] = pool;
    }

    bool updateVMResources(const std::string& vmID, int cpuUsage, int memoryUsage, int diskIO) {
        std::lock_guard<std::mutex> lock(mutex);
        if (vmPools.find(vmID) == vmPools.end()) {
            return false;
        }
        NetworkResourcePool& pool = vmPools[vmID];
        bool allocated = pool.allocateResources(cpuUsage, memoryUsage, diskIO);
        if (!allocated) {
            std::cout << "Resource allocation failed for VM: " << vmID << std::endl;
        } else {
            std::cout << "Resource allocation successful for VM: " << vmID << std::endl;
        }
        return allocated;
    }

private:
    std::unordered_map<std::string, NetworkResourcePool> vmPools;
    std::mutex mutex;
};

int main() {
    VMManager manager;
    NetworkResourcePool pool1(4, 8192, 100);
    NetworkResourcePool pool2(2, 4096, 50);

    manager.addVM("vm1", pool1);
    manager.addVM("vm2", pool2);

    manager.updateVMResources("vm1", 2, 4096, 50);
    manager.updateVMResources("vm2", 1, 2048, 25);

    return 0;
}
