        while (unique_RNTIs < N) {
            int RNTI = rand() % 1024; // Simulate a valid RNTI
            if (!RNTI_set[RNTI]) {
                PDUs[unique_RNTIs].RX_UE_INFORMATION_TAG = unique_RNTIs;
                PDUs[unique_RNTIs].RNTI = RNTI;
                PDUs[unique_RNTIs].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG
