#define MAX_ITEM_SIZE 1024 // 1 KB
#define MIN_AMOUNT 10.0
#define MAX_AMOUNT 1000.0
#define MIN_TIMESTAMP 1633072800 // January 1, 2022
#define MAX_TIMESTAMP 1664598400 // December 31, 2022

typedef struct Item {
    int productId;
    int quantity;
    double price;
} Item;

typedef struct Transaction {
    int id;
    time_t timestamp;
    double amount;
    Item* items;
    int itemCount;
} Transaction;

Transaction* createTransactions(int n) {
    // Allocate memory for transactions
    Transaction* transactions = (Transaction*)malloc(n * sizeof(Transaction));
    if (!transactions) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize each transaction
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        transactions[i].id = i + 1;
        transactions[i].timestamp = MIN_TIMESTAMP + rand() % (MAX_TIMESTAMP - MIN_TIMESTAMP);
        transactions[i].amount = MIN_AMOUNT + (double)rand() / RAND_MAX * (MAX_AMOUNT - MIN_AMOUNT);
        transactions[i].items = NULL; // Lazy allocation
        transactions[i].itemCount = 0;
    }

    return transactions;
}

void freeTransactions(Transaction* transactions, int n) {
    for (int i = 0; i < n; i++) {
        if (transactions[i].items) {
            free(transactions[i].items);
        }
    }
    free(transactions);
}

int main() {
    int n = 10;
    Transaction* transactions = createTransactions(n);

    if (transactions) {
        // Process transactions
        for (int i = 0; i < n; i++) {
            printf("Transaction %d: ID=%d, Timestamp=%ld, Amount=%.2f\n",
                   i + 1, transactions[i].id, transactions[i].timestamp, transactions[i].amount);
        }

        freeTransactions(transactions, n);
    }

    return 0;
}
