#include <iostream>
#include <unordered_map>
#include <mutex>
#include <atomic>
#include <chrono>
#include <fstream>

class Session {
public:
    std::string sessionId;
    std::string userPreferences;
    std::chrono::system_clock::time_point lastActive;

    Session(std::string id, std::string prefs)
        : sessionId(id), userPreferences(prefs), lastActive(std::chrono::system_clock::now()) {}
};

class SessionManager {
private:
    static const size_t MAX_REGION_SESSIONS = 1000;
    static const size_t GLOBAL_MAX_SESSIONS = 5000;

    std::unordered_map<std::string, Session> sessions;
    std::mutex sessionMutex;
    std::atomic<size_t> globalSessionCount;

    void logError(const std::string& message) {
        std::ofstream errorLog("error_log.txt", std::ios::app);
        if (errorLog.is_open()) {
            errorLog << message << std::endl;
            errorLog.close();
        }
    }

public:
    SessionManager() : globalSessionCount(0) {}

    bool createSession(const std::string& sessionId, const std::string& userPreferences) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        if (sessions.find(sessionId) != sessions.end()) {
            logError("Duplicate session ID: " + sessionId);
            return false;
        }
        if (globalSessionCount >= GLOBAL_MAX_SESSIONS) {
            logError("Global session limit reached");
            return false;
        }
        if (sessions.size() >= MAX_REGION_SESSIONS) {
            logError("Region session limit reached");
            return false;
        }
        sessions[sessionId] = Session(sessionId, userPreferences);
        globalSessionCount++;
        return true;
    }

    void updateLastActive(const std::string& sessionId) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        if (sessions.find(sessionId) != sessions.end()) {
            sessions[sessionId].lastActive = std::chrono::system_clock::now();
        }
    }

    bool removeSession(const std::string& sessionId) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        if (sessions.find(sessionId) != sessions.end()) {
            sessions.erase(sessionId);
            globalSessionCount--;
            return true;
        }
        return false;
    }

    size_t getSessionCount() const {
        return sessions.size();
    }
};

int main() {
    SessionManager manager;
    manager.createSession("session1", "preferences1");
    manager.updateLastActive("session1");
    manager.removeSession("session1");
    std::cout << "Current session count: " << manager.getSessionCount() << std::endl;
    return 0;
}
