#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 256
#define MAX_FILE_NAME_LENGTH 100

void trimWhitespace(char *str) {
    char *end = str + strlen(str) - 1;
    while (end > str && (*end == ' ' || *end == '\t')) end--;
    *(end + 1) = '\0';
}

char** readLinesFromFile(const char* filename, int* lineCount) {
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    char** lines = (char**)malloc(sizeof(char*) * MAX_LINE_LENGTH);
    if (!lines) {
        fclose(file);
        return NULL;
    }

    *lineCount = 0;
    while (*lineCount < MAX_LINE_LENGTH && fgets(lines[*lineCount], MAX_LINE_LENGTH, file)) {
        trimWhitespace(lines[*lineCount]);
        (*lineCount)++;
    }
    fclose(file);

    // Resize array to fit exact number of lines
    char** resizedLines = (char**)realloc(lines, sizeof(char*) * (*lineCount));
    if (!resizedLines) {
        free(lines);
        return NULL;
    }

    return resizedLines;
}

void findAndPrintLongestWord(const char* words[], int count) {
    const char* longestWord = "";
    for (int i = 0; i < count; i++) {
        if (strlen(words[i]) > strlen(longestWord)) {
            longestWord = words[i];
        }
    }
    printf("Longest word: %s\n", longestWord);
}

void modifyFileExtension(const char* originalFilename, int length) {
    char newFilename[MAX_FILE_NAME_LENGTH];
    snprintf(newFilename, MAX_FILE_NAME_LENGTH, "%.*s_%d.txt", (int)strlen(originalFilename) - 4, originalFilename, length);
    printf("New filename: %s\n", newFilename);
}

void processAndModifyFile(const char* filename) {
    int lineCount;
    char** lines = readLinesFromFile(filename, &lineCount);
    if (!lines) {
        fprintf(stderr, "Failed to read file.\n");
        return;
    }

    // Process input from standard input
    const char* endMarker = "END";
    char inputLine[MAX_LINE_LENGTH];
    int inputCount = 0;
    while (fgets(inputLine, MAX_LINE_LENGTH, stdin) && strcmp(inputLine, endMarker) != 0) {
        trimWhitespace(inputLine);
        // Store or process each line
        inputCount++;
    }

    // Find and print the longest word from input lines
    findAndPrintLongestWord((const char**)lines, inputCount);

    // Modify file extension based on longest word length
    modifyFileExtension(filename, strlen(lines[inputCount - 1]));

    // Free allocated memory
    for (int i = 0; i < lineCount; i++) {
        free(lines[i]);
    }
    free(lines);
}

int main() {
    processAndModifyFile("input.txt");
    return 0;
}
