    BearerConfig *config;
    pthread_mutex_t lock;
} CachedBearerConfig;

UserSessionState sessions[MAX_SESSIONS];
CachedBearerConfig cachedConfigs[MAX_SESSIONS];

void initializeSessions() {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        sessions[i].imsi = i + 1; // Assign unique IMSI
        pthread_mutex_init(&cachedConfigs[i].lock, NULL);
        cachedConfigs[i].config = malloc(sizeof(BearerConfig));
        // Initialize bearerConfig with default values or fetch from external service
    }
}

void updateBearerConfig(int imsi, int newQosParameters) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (sessions[i].imsi == imsi) {
            pthread_mutex_lock(&cachedConfigs[i].lock);
            cachedConfigs[i].config->qosParameters = newQosParameters;
            pthread_mutex_unlock(&cachedConfigs[i].lock);
            break;
        }
    }
}

void* handleSession(void *arg) {
    int imsi = *(int*)arg;
    // Simulate session handling logic
    printf("Handling session for IMSI: %d\n", imsi);
    return NULL;
}

