#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    bool status;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    if (manager) {
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

bool validate_records(RecordManager* manager, long min_offset, long max_offset) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i].offset < min_offset || manager->records[i].offset > max_offset) return false;
        for (size_t j = i + 1; j < manager->size; ++j) {
            if (manager->records[j].offset == manager->records[i].offset) return false;
        }
    }
    return true;
}

void expand_capacity(RecordManager* manager, size_t new_capacity) {
    Record* new_records = (Record*)realloc(manager->records, new_capacity * sizeof(Record));
    if (!new_records) return;

    manager->records = new_records;
    manager->capacity = new_capacity;
}

bool initialize_records(RecordManager* manager, int min_key, int max_key, long min_offset, long max_offset) {
    pthread_mutex_lock(&manager->lock);

    while (manager->size < manager->capacity) {
        int key = rand() % (max_key - min_key + 1) + min_key;
        long offset = rand() % (max_offset - min_offset + 1) + min_offset;

        bool is_unique = true;
        for (size_t i = 0; i < manager->size; ++i) {
            if (manager->records[i].key == key || manager->records[i].offset == offset) {
                is_unique = false;
                break;
            }
        }

        if (is_unique) {
            manager->records[manager->size].key = key;
            manager->records[manager->size].offset = offset;
            manager->records[manager->size].status = false;
            ++manager->size;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    if (!validate_records(manager, min_offset, max_offset)) {
        expand_capacity(manager, manager->capacity * 2);
        return initialize_records(manager, min_key, max_key, min_offset, max_offset);
    }

    return true;
}

RecordManager* create_and_initialize_records(size_t initial_capacity, int min_key, int max_key, long min_offset, long max_offset) {
    RecordManager* manager = create_record_manager(initial_capacity);
    if (!manager) return NULL;

    if (initialize_records(manager, min_key, max_key, min_offset, max_offset)) {
        return manager;
    } else {
        destroy_record_manager(manager);
        return NULL;
    }
}
