#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} Severity;

typedef struct {
    time_t timestamp;
    Severity severity;
    char message[256];
} LogEntry;

LogEntry* create_log_entries(int n, time_t start_time, int range) {
    if (n > 1000000 || range <= 0) {
        return NULL;
    }

    LogEntry* log_entries = malloc(n * sizeof(LogEntry));
    if (!log_entries) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < n; ++i) {
        time_t timestamp = start_time + rand() % range;
        Severity severity = (Severity)(rand() % 5);
        snprintf(log_entries[i].message, sizeof(log_entries[i].message), "Log entry %d", i);

        // Check for duplicate timestamps and resolve conflicts
        for (int j = 0; j < i; ++j) {
            if (log_entries[j].timestamp == timestamp) {
                char unique_id[16];
                snprintf(unique_id, sizeof(unique_id), "_%d", j);
                strncat(log_entries[i].message, unique_id, sizeof(log_entries[i].message) - strlen(log_entries[i].message) - 1);
            }
        }

        log_entries[i].timestamp = timestamp;
        log_entries[i].severity = severity;
    }

    return log_entries;
}

int validate_log_entries(LogEntry* entries, int n) {
    for (int i = 0; i < n; ++i) {
        if (entries[i].message[0] == '\0' || strlen(entries[i].message) > 255) {
            return 0;
        }

        for (int j = i + 1; j < n; ++j) {
            if (strcmp(entries[i].message, entries[j].message) == 0) {
                return 0;
            }
        }
    }

    return 1;
}

void free_log_entries(LogEntry* entries, int n) {
    free(entries);
}
