```javascript
const fs = require('fs').promises;
const axios = require('axios');

class ContentItemManager {
    constructor(config) {
        if (!config.metadataPath) {
            throw new Error('Invalid configuration settings');
        }
        this.metadataPath = config.metadataPath;
    }

    async storeContentItem(id, metadata) {
        try {
            await fs.writeFile(`${this.metadataPath}/${id}.json`, JSON.stringify(metadata));
        } catch (error) {
            console.error('Error storing content item:', error);
            throw new Error('Failed to store content item');
        }
    }

    async retrieveContentItem(id) {
        try {
            if (!await fs.exists(`${this.metadataPath}/${id}.json`)) {
                throw new Error('Content item not found');
            }
            return JSON.parse(await fs.readFile(`${this.metadataPath}/${id}.json`, 'utf8'));
        } catch (error) {
            console.error('Error retrieving content item:', error);
            throw new Error('Failed to retrieve content item');
        }
    }

    async getContentItem(id) {
        try {
            const response = await axios.get(`http://php-server/api/content/${id}`);
            return response.data;
        } catch (error) {
            console.error('Error fetching content item:', error);
            throw new Error('Failed to fetch content item');
        }
    }
}
