        $id = (new DynamicContentGenerator(['charset' => 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', 'minEntropy' => 12]))->generateString(16);
        $this->contentItemManager->storeContentItem($id, $metadata);
        return ['id' => $id];
