#include <stdlib.h>
#include <string.h>

#define POOL_SIZE 1024

typedef struct large_data {
    size_t buffer_size;
    char *buffer;
} large_data;

typedef struct metadata {
    // Define metadata fields here
} metadata;

typedef struct node {
    large_data *data;
    void *context; // Additional context information
    struct node *next;
} node;

large_data *pool[POOL_SIZE];
int pool_index = 0;

void initialize_memory_pool() {
    for (int i = 0; i < POOL_SIZE; i++) {
        pool[i] = malloc(sizeof(large_data));
        if (!pool[i]) {
            // Handle memory allocation failure
            exit(1);
        }
    }
}

large_data *allocate_large_data(size_t size) {
    if (pool_index >= POOL_SIZE) {
        // Pool is full, allocate new large_data object
        return malloc(sizeof(large_data));
    }
    large_data *data = pool[pool_index++];
    data->buffer_size = size;
    data->buffer = malloc(size);
    if (!data->buffer) {
        // Handle memory allocation failure
        exit(1);
    }
    return data;
}

void free_large_data(large_data *data) {
    if (data < pool || data >= pool + POOL_SIZE) {
        // Free from heap
        free(data->buffer);
        free(data);
    } else {
        // Return to pool
        data->buffer_size = 0;
        data->buffer = NULL;
        pool_index--;
        memmove(pool + pool_index, pool + pool_index + 1, (POOL_SIZE - pool_index - 1) * sizeof(large_data *));
    }
}

node *create_node(size_t index) {
    node *new_node = malloc(sizeof(node));
    if (!new_node) {
        // Handle memory allocation failure
        exit(1);
    }
    new_node->data = allocate_large_data(index + 1); // Example buffer size based on index
    new_node->context = NULL; // Initialize context as needed
    new_node->next = NULL;
    return new_node;
}

void free_node(node *node) {
    if (node) {
        free_large_data(node->data);
        free(node->context); // Free any additional context
        free(node);
    }
}

void initialize_linked_list(size_t start, size_t end) {
    node *head = NULL;
    node *tail = NULL;

    for (size_t i = start; i <= end; i++) {
        node *new_node = create_node(i);
        if (!head) {
            head = new_node;
        } else {
            tail->next = new_node;
        }
        tail = new_node;
    }

    // Use the linked list as needed
}

void cleanup_linked_list(node **head) {
    while (*head) {
        node *temp = *head;
        *head = (*head)->next;
        free_node(temp);
    }
}
