#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int ResourceID;
    time_t Timestamp;
    double *MetricsData;
    size_t MetricsCount;
} ResourceMetric;

typedef struct {
    ResourceMetric **metricsArray;
    size_t count;
    size_t maxSize;
    pthread_mutex_t lock;
} ResourceMetricsManager;

ResourceMetricsManager* createResourceManager(size_t maxSize) {
    ResourceMetricsManager *manager = (ResourceMetricsManager*)malloc(sizeof(ResourceMetricsManager));
    if (!manager) {
        perror("Failed to allocate memory for manager");
        return NULL;
    }
    manager->metricsArray = (ResourceMetric**)calloc(maxSize, sizeof(ResourceMetric*));
    if (!manager->metricsArray) {
        perror("Failed to allocate memory for metrics array");
        free(manager);
        return NULL;
    }
    manager->count = 0;
    manager->maxSize = maxSize;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroyResourceManager(ResourceMetricsManager *manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->metricsArray[i]->MetricsData);
            free(manager->metricsArray[i]);
        }
        free(manager->metricsArray);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int addResourceMetric(ResourceMetricsManager *manager, int ResourceID, time_t Timestamp, double *MetricsData, size_t MetricsCount) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->maxSize) {
        fprintf(stderr, "Memory limit reached\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->metricsArray[i]->ResourceID == ResourceID) {
            fprintf(stderr, "Duplicate ResourceID: %d\n", ResourceID);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }
    ResourceMetric *newMetric = (ResourceMetric*)malloc(sizeof(ResourceMetric));
    if (!newMetric) {
        perror("Failed to allocate memory for new metric");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    newMetric->ResourceID = ResourceID;
    newMetric->Timestamp = Timestamp;
    newMetric->MetricsData = (double*)malloc(MetricsCount * sizeof(double));
    if (!newMetric->MetricsData) {
        perror("Failed to allocate memory for metrics data");
        free(newMetric);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    memcpy(newMetric->MetricsData, MetricsData, MetricsCount * sizeof(double));
    newMetric->MetricsCount = MetricsCount;
    manager->metricsArray[manager->count++] = newMetric;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Additional functions for batch processing, memory pool management, aggregation, and logging can be implemented here.
