#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    TYPE_INT,
    TYPE_DOUBLE,
    TYPE_STRING
} SettingType;

typedef union {
    int i;
    double d;
    char *s;
} SettingValue;

typedef struct {
    char key[128];
    SettingValue value;
    SettingType type;
} Setting;

typedef struct {
    Setting *settings;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ConfigDB;

ConfigDB* create_config_db(size_t initial_capacity) {
    ConfigDB *db = (ConfigDB*)malloc(sizeof(ConfigDB));
    db->settings = (Setting*)calloc(initial_capacity, sizeof(Setting));
    db->capacity = initial_capacity;
    db->count = 0;
    pthread_mutex_init(&db->lock, NULL);
    return db;
}

void destroy_config_db(ConfigDB *db) {
    for (size_t i = 0; i < db->count; ++i) {
        if (db->settings[i].type == TYPE_STRING && db->settings[i].value.s != NULL) {
            free(db->settings[i].value.s);
        }
    }
    free(db->settings);
    pthread_mutex_destroy(&db->lock);
    free(db);
}

size_t hash_function(const char *key, size_t capacity) {
    size_t hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % capacity;
}

int add_setting(ConfigDB *db, const char *key, SettingValue value, SettingType type) {
    pthread_mutex_lock(&db->lock);
    size_t index = hash_function(key, db->capacity);
    while (index < db->count && strcmp(db->settings[index].key, key) != 0) {
        index = (index + 1) % db->capacity;
    }
    if (index == db->count) {
        // Key not found, add new setting
        if (db->count >= db->capacity) {
            // Reallocate with increased capacity
            size_t new_capacity = db->capacity * 2;
            Setting *new_settings = (Setting*)realloc(db->settings, new_capacity * sizeof(Setting));
            if (new_settings == NULL) {
                pthread_mutex_unlock(&db->lock);
                return -1; // Memory allocation failed
            }
            db->settings = new_settings;
            db->capacity = new_capacity;
        }
        strcpy(db->settings[db->count].key, key);
        db->settings[db->count].value = value;
        db->settings[db->count].type = type;
        ++db->count;
    } else {
        // Key already exists, update value
        if (db->settings[index].type == TYPE_STRING && db->settings[index].value.s != NULL) {
            free(db->settings[index].value.s);
        }
        db->settings[index].value = value;
        db->settings[index].type = type;
    }
    pthread_mutex_unlock(&db->lock);
    return 0;
}

int validate_config_db(ConfigDB *db) {
    for (size_t i = 0; i < db->count; ++i) {
        for (size_t j = i + 1; j < db->count; ++j) {
            if (strcmp(db->settings[i].key, db->settings[j].key) == 0) {
                return -1; // Duplicate key found
            }
        }
    }
    return 0;
}

int load_config_from_file(ConfigDB *db, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return -1; // File not found or unable to open
    }
    // Parse and validate incoming data from file
    // ...
    fclose(file);
    return 0;
}
