#define MAX_RECORD_SIZE 1024 * 1024 // 1 MB
#define NUM_OFFSETS 10000
#define NUM_KEYS 5000

typedef struct {
    int field;
} record;

void allocate_and_initialize_memory(long **offsets, int **keys, record **records) {
    *offsets = (long *)malloc(NUM_OFFSETS * sizeof(long));
    if (*offsets == NULL) {
        // Handle memory allocation failure
        exit(1);
    }

    *keys = (int *)malloc(NUM_KEYS * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        exit(1);
    }

    *records = (record *)malloc(MAX_RECORD_SIZE);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        exit(1);
    }

    srand(time(NULL));

    for (int i = 0; i < NUM_KEYS; ++i) {
        (*keys)[i] = rand() % 201 - 100; // Random value between -100 and 100
    }

    int used_keys[NUM_KEYS];
    for (int i = 0; i < NUM_KEYS; ++i) {
        used_keys[i] = 0;
    }

    for (int i = 0; i < NUM_OFFSETS; ++i) {
        int key;
        do {
            key = rand() % 201 - 100; // Random value between -100 and 100
        } while (used_keys[key + 100] == 1); // Ensure no duplicate values

        used_keys[key + 100] = 1;

        (*records)[i].field = key;
    }
}

void free_memory(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}
