#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_OFFSETS 1000

typedef struct {
    int key;
    long *offsets;
    size_t offset_count;
} Record;

typedef struct {
    Record **records;
    size_t record_count;
    size_t pool_size;
    long *offset_pool;
    size_t next_offset_index;
} Database;

Database* db_create(size_t initial_capacity, size_t pool_size) {
    Database *db = (Database*)malloc(sizeof(Database));
    if (!db) return NULL;

    db->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!db->records) {
        free(db);
        return NULL;
    }

    db->record_count = 0;
    db->pool_size = pool_size;
    db->offset_pool = (long*)malloc(pool_size * sizeof(long));
    if (!db->offset_pool) {
        free(db->records);
        free(db);
        return NULL;
    }

    for (size_t i = 0; i < pool_size; ++i) {
        db->offset_pool[i] = i;
    }
    db->next_offset_index = 0;

    srand(time(NULL));
    return db;
}

void db_destroy(Database *db) {
    if (!db) return;

    for (size_t i = 0; i < db->record_count; ++i) {
        Record *rec = db->records[i];
        free(rec->offsets);
        free(rec);
    }
    free(db->records);
    free(db->offset_pool);
    free(db);
}

Record* db_get_or_create_record(Database *db, int key) {
    for (size_t i = 0; i < db->record_count; ++i) {
        if (db->records[i]->key == key) {
            return db->records[i];
        }
    }

    Record *new_rec = (Record*)malloc(sizeof(Record));
    if (!new_rec) return NULL;

    new_rec->key = key;
    new_rec->offsets = (long*)calloc(MAX_OFFSETS, sizeof(long));
    if (!new_rec->offsets) {
        free(new_rec);
        return NULL;
    }

    new_rec->offset_count = 0;
    db->records[db->record_count++] = new_rec;

    return new_rec;
}

int db_add_offset(Database *db, int key, long offset) {
    Record *rec = db_get_or_create_record(db, key);
    if (!rec) return -1;

    for (size_t i = 0; i < rec->offset_count; ++i) {
        if (rec->offsets[i] == offset) {
            return -2; // Offset already exists
        }
    }

    if (rec->offset_count >= MAX_OFFSETS) {
        return -3; // Record is full
    }

    rec->offsets[rec->offset_count++] = offset;

    // Randomly select an offset from the pool and assign it to the record
    size_t pool_index = rand() % db->pool_size;
    long assigned_offset = db->offset_pool[pool_index];
    db->offset_pool[pool_index] = db->offset_pool[--db->next_offset_index];

    rec->offsets[rec->offset_count++] = assigned_offset;

    return 0;
}

int main() {
    Database *db = db_create(10, 100);
    if (!db) {
        fprintf(stderr, "Failed to create database\n");
        return 1;
    }

    int result = db_add_offset(db, 1, 12345);
    if (result != 0) {
        fprintf(stderr, "Failed to add offset: %d\n", result);
        db_destroy(db);
        return 1;
    }

    // Add more records and offsets as needed

    db_destroy(db);
    return 0;
}
