#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORD_SIZE 950 * 1024 // 950 KB in bytes

typedef struct {
    int value;
} record;

void* allocate_memory() {
    long* offsets = (long*)malloc(10000 * sizeof(long));
    if (!offsets) return NULL;

    int* keys = (int*)malloc(5000 * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    record* records = (record*)malloc(MAX_RECORD_SIZE);
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize records with unique random values
    srand(time(NULL));
    int used_values[201] = {0}; // Array to track used values
    for (int i = 0; i < 5000; ++i) {
        int value;
        do {
            value = rand() % 201 - 100; // Random value between -100 and 100
        } while (used_values[value + 100] == 1);
        used_values[value + 100] = 1;
        records[i].value = value;
    }

    // Initialize keys with unique values
    for (int i = 0; i < 5000; ++i) {
        keys[i] = rand() % 5000; // Unique key between 0 and 4999
    }

    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }
    pthread_mutex_init(mutex, NULL);

    // Return a pointer to the allocated memory structure
    void** memory_structure = (void**)malloc(5 * sizeof(void*));
    memory_structure[0] = offsets;
    memory_structure[1] = keys;
    memory_structure[2] = records;
    memory_structure[3] = mutex;

    return memory_structure;
}

void free_memory(void* memory_structure) {
    void** structure = (void**)memory_structure;
    pthread_mutex_t* mutex = (pthread_mutex_t*)structure[3];
    pthread_mutex_lock(mutex);

    free(structure[0]);
    free(structure[1]);
    free(structure[2]);
    pthread_mutex_unlock(mutex);
    pthread_mutex_destroy(mutex);
    free(mutex);
    free(memory_structure);
}

void reset_memory(void* memory_structure) {
    void** structure = (void**)memory_structure;
    pthread_mutex_t* mutex = (pthread_mutex_t*)structure[3];
    pthread_mutex_lock(mutex);

    // Reset records with new unique random values
    srand(time(NULL));
    int used_values[201] = {0};
    for (int i = 0; i < 5000; ++i) {
        int value;
        do {
            value = rand() % 201 - 100;
        } while (used_values[value + 100] == 1);
        used_values[value + 100] = 1;
        ((record*)structure[2])[i].value = value;
    }

    // Reset keys with new unique values
    for (int i = 0; i < 5000; ++i) {
        structure[1][i] = rand() % 5000;
    }

    pthread_mutex_unlock(mutex);
}

void log_memory_usage(void* memory_structure) {
    void** structure = (void**)memory_structure;
    pthread_mutex_t* mutex = (pthread_mutex_t*)structure[3];
    pthread_mutex_lock(mutex);

    size_t total_size = sizeof(long) * 10000 + sizeof(int) * 5000 + MAX_RECORD_SIZE;
    printf("Total memory usage: %zu bytes\n", total_size);

    pthread_mutex_unlock(mutex);
}
