#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORD_SIZE 1024 * 1024 // 1 MB
#define MAX_KEYS 5000
#define ARRAY_SIZE 10000

typedef struct {
    int value;
} record;

record* records = NULL;
int record_count = 0;
pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;

long offsets[ARRAY_SIZE];
int keys[MAX_KEYS];
int key_count = 0;
pthread_mutex_t keys_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_records() {
    pthread_mutex_lock(&records_lock);
    if (record_count == 0) {
        records = (record*)malloc(MAX_RECORD_SIZE);
        if (!records) {
            perror("Failed to allocate memory for records");
            exit(EXIT_FAILURE);
        }
        srand(time(NULL));
        int values[201]; // -100 to 100
        for (int i = 0; i < 201; ++i) {
            values[i] = i - 100;
        }
        for (int i = 0; i < MAX_RECORD_SIZE / sizeof(record); ++i) {
            int index = rand() % 201;
            records[i].value = values[index];
            values[index] = values[200]; // Swap to avoid duplicates
            --values[200];
        }
    }
    pthread_mutex_unlock(&records_lock);
}

void initialize_keys(int* new_keys, int count) {
    pthread_mutex_lock(&keys_lock);
    if (key_count + count > MAX_KEYS) {
        fprintf(stderr, "Too many keys to allocate\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < count; ++i) {
        keys[key_count++] = new_keys[i];
    }
    pthread_mutex_unlock(&keys_lock);
}

void* manage_memory(void* arg) {
    // Simulate memory management tasks
    initialize_records();
    int new_keys[MAX_KEYS] = { /* Initialize with actual key values */ };
    initialize_keys(new_keys, MAX_KEYS);

    // Log performance metrics and memory usage

    return NULL;
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, manage_memory, NULL) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(records);

    return 0;
}
```

