#define MAX_RECORDS 1000
#define MAX_KEY_VALUE 10000

typedef struct {
    long offset;
    int key;
    struct record *next;
    char extra[256];
    MAC_TransportChannelInfo channel_info;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int last_assigned_offset;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool;

void init_memory_pool() {
    memset(&pool, 0, sizeof(pool));
    pthread_mutex_init(&pool.lock, NULL);
}

Record* allocate_record(int key) {
    pthread_mutex_lock(&pool.lock);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (!pool.records[i].key) {
            pool.records[i].offset = pool.last_assigned_offset++;
            pool.records[i].key = key;
            pthread_mutex_unlock(&pool.lock);
            return &pool.records[i];
        }
    }
    pthread_mutex_unlock(&pool.lock);
    return NULL;
}

void free_record(Record *record) {
    pthread_mutex_lock(&pool.lock);
    record->key = 0;
    pthread_mutex_unlock(&pool.lock);
}

int main() {
    init_memory_pool();

    // Example usage
    Record *record1 = allocate_record(42);
    if (record1) {
        printf("Record allocated with offset: %ld, key: %d\n", record1->offset, record1->key);
        free_record(record1);
    } else {
        printf("Failed to allocate record\n");
    }

    return 0;
}
