        crc_indications[i] = NULL;
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* indication = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (indication == NULL) {
        return NULL;
