    indication->rnti = rnti;
    // Initialize other fields as per NFAPI_CRC_INDICATION_PDU_T structure
    return indication;
}

void add_crc_indication(int rnti, NFAPI_CRC_INDICATION_PDU_T* indication) {
    pthread_mutex_lock(&crc_mutex);
    if (rnti >= 0 && rnti < MAX_RNTI) {
        crc_indications[rnti] = indication;
    }
    pthread_mutex_unlock(&crc_mutex);
}

void update_crc_indication(int rnti, NFAPI_CRC_INDICATION_PDU_T* new_indication) {
    pthread_mutex_lock(&crc_mutex);
    if (rnti >= 0 && rnti < MAX_RNTI && crc_indications[rnti] != NULL) {
        free(crc_indications[rnti]);
        crc_indications[rnti] = new_indication;
    }
    pthread_mutex_unlock(&crc_mutex);
}

void delete_crc_indication(int rnti) {
    pthread_mutex_lock(&crc_mutex);
    if (rnti >= 0 && rnti < MAX_RNTI && crc_indications[rnti] != NULL) {
        free(crc_indications[rnti]);
        crc_indications[rnti] = NULL;
    }
    pthread_mutex_unlock(&crc_mutex);
}

void cleanup_crc_indications() {
    for (int i = 0; i < MAX_RNTI; i++) {
        if (crc_indications[i] != NULL) {
            free(crc_indications[i]);
