#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct {
    int value;
} record;

record* allocate_and_initialize(int offset, int key_range_start, int key_range_end) {
    if (offset <= 0 || key_range_start > key_range_end) {
        return NULL; // Invalid input
    }

    record** offsets = malloc(offset * sizeof(record*));
    if (!offsets) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < offset; ++i) {
        offsets[i] = malloc(MAX_RECORDS * sizeof(record));
        if (!offsets[i]) {
            // Handle partial allocation failure
            for (int j = 0; j < i; ++j) {
                free(offsets[j]);
            }
            free(offsets);
            return NULL;
        }

        for (int j = 0; j < MAX_RECORDS; ++j) {
            offsets[i][j].value = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        }
    }

    return *offsets;
}

void free_memory(record** offsets, int offset) {
    for (int i = 0; i < offset; ++i) {
        free(offsets[i]);
    }
    free(offsets);
}
