#include <stdlib.h>
#include <stdio.h>

#define TABLE_SIZE 1000

typedef struct record {
    int key;
    long offset;
} Record;

typedef struct hash_table {
    Record *table[TABLE_SIZE];
} HashTable;

HashTable* create_hash_table() {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    if (ht == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < TABLE_SIZE; i++) {
        ht->table[i] = NULL;
    }
    return ht;
}

void insert_record(HashTable *ht, int key, long offset) {
    int index = key % TABLE_SIZE;
    while (ht->table[index] != NULL && ht->table[index]->key != key) {
        index = (index + 1) % TABLE_SIZE; // Linear probing
    }
    if (ht->table[index] == NULL) {
        Record *new_record = (Record*)malloc(sizeof(Record));
        if (new_record == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        new_record->key = key;
        new_record->offset = offset;
        ht->table[index] = new_record;
    } else {
        printf("Duplicate key detected and resolved using linear probing\n");
        // Handle duplicate key scenario
    }
}

void free_hash_table(HashTable *ht) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (ht->table[i] != NULL) {
            free(ht->table[i]);
        }
    }
    free(ht);
}

int main() {
    HashTable *ht = create_hash_table();
    insert_record(ht, 123, 456789L);
