void init_mac_transport_channel_array(MAC_TransportChannelArray *array) {
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->channels = (MAC_TransportChannelInfo *)malloc(array->capacity * sizeof(MAC_TransportChannelInfo));
    pthread_mutex_init(&array->lock, NULL);
}

void resize_mac_transport_channel_array(MAC_TransportChannelArray *array) {
    size_t new_capacity = array->capacity * 2;
    MAC_TransportChannelInfo *new_channels = (MAC_TransportChannelInfo *)realloc(array->channels, new_capacity * sizeof(MAC_TransportChannelInfo));
    if (new_channels == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->channels = new_channels;
    array->capacity = new_capacity;
}

void add_mac_transport_channel(MAC_TransportChannelArray *array, int rnti, TransportChannelConfig config) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        resize_mac_transport_channel_array(array);
    }
    array->channels[array->size].rnti = rnti;
    array->channels[array->size].config = config;
    array->size++;
    pthread_mutex_unlock(&array->lock);
}

void validate_mac_transport_channel_config(TransportChannelConfig *config) {
    // Add validation logic here
}

void serialize_mac_transport_channel_array(MAC_TransportChannelArray *array, FILE *file) {
    fwrite(&array->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < array->size; i++) {
        fwrite(&array->channels[i].rnti, sizeof(int), 1, file);
        serialize_transport_channel_config(&array->channels[i].config, file);
    }
}

void deserialize_mac_transport_channel_array(MAC_TransportChannelArray *array, FILE *file) {
    size_t size;
    fread(&size, sizeof(size_t), 1, file);
    if (size > array->capacity) {
        resize_mac_transport_channel_array(array);
    }
    for (size_t i = 0; i < size; i++) {
        fread(&array->channels[i].rnti, sizeof(int), 1, file);
        deserialize_transport_channel_config(&array->channels[i].config, file);
    }
    array->size = size;
}

void free_mac_transport_channel_array(MAC_TransportChannelArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->channels);
}
