    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int allocate_and_populate_pdus(int N, size_t max_size, NFAPI_CRC_INDICATION_PDU_T **pdus) {
    if (N == 0 || max_size < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -1; // Handle edge cases
    }

    *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        return -2; // Allocation failure
    }

    int unique_rntis[MAX_RNTI] = {0};
    int rnti_count = 0;

    for (int i = 0; i < N; i++) {
        while (1) {
            (*pdus)[i].RNTI = rand() % MAX_RNTI;
            if (!unique_rntis[(*pdus)[i].RNTI]) {
                unique_rntis[(*pdus)[i].RNTI] = 1;
                rnti_count++;
                break;
            }
        }

        (*pdus)[i].RX_UE_INFORMATION_TAG = i + 1;
        (*pdus)[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

        if (sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1) > max_size) {
            free(*pdus);
            return -3; // Insufficient memory
        }
    }

    return rnti_count;
}

int main() {
    int N = 1000;
    size_t max_size = 500000;
    NFAPI_CRC_INDICATION_PDU_T *pdus;

    int result = allocate_and_populate_pdus(N, max_size, &pdus);
    if (result < 0) {
        printf("Error: %d\n", result);
    } else {
        printf("Successfully allocated and populated %d PDUs with unique RNTIs.\n", result);
        free(pdus);
    }

    return 0;
}
