void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->elements[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_crc_element(NFAPI_CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (list->count >= MAX_ELEMENTS) return -1;
    NFAPI_CRC_INDICATION_PDU_T *element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) return -1;
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    srand(time(NULL));
    element->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    pthread_mutex_lock(&list->lock);
    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_crc_element(NFAPI_CRC_LIST_T *list, int index) {
    if (index < 0 || index >= list->count) return NULL;
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *element = list->elements[index];
    pthread_mutex_unlock(&list->lock);
    return element;
