#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <atomic>

class TaskManager {
public:
    TaskManager(int gracePeriod) : gracePeriod(gracePeriod), lastExecutionTime(std::chrono::steady_clock::now()), suspended(false) {}

    void startTask() {
        std::unique_lock<std::mutex> lock(mutex);
        if (!suspended) {
            taskThread = std::thread(&TaskManager::processData, this);
        }
    }

    void suspendTask() {
        std::unique_lock<std::mutex> lock(mutex);
        suspended = true;
        condition.notify_all();
    }

    void resumeTask() {
        std::unique_lock<std::mutex> lock(mutex);
        suspended = false;
        condition.notify_all();
    }

private:
    void processData() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            if (suspended) {
                condition.wait(lock, [this] { return !suspended; });
            }
            auto now = std::chrono::steady_clock::now();
            auto timeSinceLastExecution = std::chrono::duration_cast<std::chrono::seconds>(now - lastExecutionTime).count();

            if (timeSinceLastExecution >= gracePeriod) {
                lock.unlock();
                processLargeDatasetFromAPI();
                lock.lock();
                lastExecutionTime = now;
                logProcessingFrequency(timeSinceLastExecution);
            }

            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    }

    void processLargeDatasetFromAPI() {
        // Simulate network latency and API response time
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
        // Process dataset logic here
    }

    void logProcessingFrequency(int frequency) {
        // Log to centralized monitoring service
        std::cout << "Processing frequency: " << frequency << " seconds" << std::endl;
    }

    int gracePeriod;
    std::chrono::time_point<std::chrono::steady_clock> lastExecutionTime;
    bool suspended;
    std::thread taskThread;
    std::mutex mutex;
    std::condition_variable condition;
};

int main() {
    TaskManager manager(10); // Grace period of 10 seconds
    manager.startTask();

    // Simulate user activity to suspend and resume tasks
    std::this_thread::sleep_for(std::chrono::seconds(20));
    manager.suspendTask();
    std::this_thread::sleep_for(std::chrono::seconds(5));
    manager.resumeTask();

    return 0;
}
