#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TASKS 1000
#define MAX_DESCRIPTION_LENGTH 256
#define MAX_WORKERS 50

typedef struct {
    long priority;
    int id;
    char description[MAX_DESCRIPTION_LENGTH];
} Task;

typedef struct {
    Task* task;
    int completed;
} Worker;

Task* tasks = NULL;
Worker workers[MAX_WORKERS];
int num_tasks = 0;
int successful_allocations = 0;
int failed_allocations = 0;
size_t total_memory_usage = 0;
size_t max_memory_size = 1024 * 1024; // 1MB
FILE* duplicate_log = fopen("duplicates.log", "w");

void initialize_tasks() {
    tasks = (Task*)malloc(MAX_TASKS * sizeof(Task));
    if (tasks == NULL) {
        fprintf(stderr, "Failed to allocate memory for tasks\n");
        exit(1);
    }
}

void initialize_workers() {
    for (int i = 0; i < MAX_WORKERS; i++) {
        workers[i].task = NULL;
        workers[i].completed = 0;
    }
}

void set_task_priority(Task* task, long min_priority, long max_priority) {
    task->priority = rand() % (max_priority - min_priority + 1) + min_priority;
}

int add_task(int id, const char* description) {
    if (num_tasks >= MAX_TASKS) {
        fprintf(stderr, "Task limit reached\n");
        return -1;
    }
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i].id == id) {
            fprintf(duplicate_log, "Duplicate task ID: %d\n", id);
            fclose(duplicate_log);
            return -1;
        }
    }
    tasks[num_tasks].id = id;
    strncpy(tasks[num_tasks].description, description, MAX_DESCRIPTION_LENGTH);
    set_task_priority(&tasks[num_tasks], 1, 100);
    num_tasks++;
    return 0;
}

void process_tasks() {
    for (int i = 0; i < num_tasks; i++) {
        // Simulate task processing
        workers[i % MAX_WORKERS].task = &tasks[i];
        workers[i % MAX_WORKERS].completed = 1;
    }
}

void consolidate_results(Task* results, int max_size) {
    int count = 0;
    for (int i = 0; i < num_tasks && count < max_size; i++) {
        if (workers[i % MAX_WORKERS].completed) {
            memcpy(&results[count], &tasks[i], sizeof(Task));
            count++;
        }
    }
}

void log_performance() {
    printf("Successful allocations: %d\n", successful_allocations);
    printf("Failed allocations: %d\n", failed_allocations);
    printf("Total memory usage: %zu bytes\n", total_memory_usage);
}

int main() {
    srand(time(NULL));
    initialize_tasks();
    initialize_workers();

    // Add tasks
    add_task(1, "Task 1");
    add_task(2, "Task 2");

    // Process tasks
    process_tasks();

    // Consolidate results
    Task results[MAX_TASKS];
    consolidate_results(results, MAX_TASKS);

    // Log performance
    log_performance();

    free(tasks);
    fclose(duplicate_log);
    return 0;
}
