        pdus[i].RNTI = rand() % (maxValue - minValue + 1) + minValue;
        while (i > 0 && pdus[i].RNTI == pdus[i - 1].RNTI) {
            pdus[i].RNTI = rand() % (maxValue - minValue + 1) + minValue;
        }
        pdus[i].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    }

    return pdus;
}

int main() {
    int numPDUs = 10; // Example number of PDUs
    int minValue = 100;
    int maxValue = 200;

    NFAPI_RX_PDU_T* pdus = createPDUs(numPDUs, minValue, maxValue);
    if (pdus) {
        // Process PDUs
        free(pdus);
    }

    return 0;
}
```

