        char* result = malloc(strlen(string) + 2);
        strcpy(result, string);
        strcat(result, "/");
        return result;
    } else if (allowTruncation && strlen(string) > sizeLimit - 3) {
        char* result = malloc(sizeLimit);
        strncpy(result, string, sizeLimit - 3);
        strcat(result, "...");
        return result;
    }
    return NULL;
