function selectElements(node, selector, callback) {
    let matches = [];

    function traverse(currentNode) {
        if (currentNode.nodeType === Node.ELEMENT_NODE && callback(currentNode)) {
            matches.push(currentNode);
        }
        for (let child of currentNode.childNodes) {
            traverse(child);
        }
    }

    traverse(node);

    return new Promise((resolve, reject) => {
