    private Record[] _records;
    private Random _random;
    private int _minValue;
    private int _maxValue;
    private int _currentSize;
    private const int MaxSize = 10000;

    public DynamicDataProcessor(int minValue, int maxValue)
    {
        _minValue = minValue;
        _maxValue = maxValue;
        _random = new Random();
        Initialize();
    }

    private void Initialize()
    {
        _offsets = new int[MaxSize];
        _keys = new int[MaxSize][];
        _records = new Record[MaxSize];
        for (int i = 0; i < MaxSize; i++)
        {
            _keys[i] = new int[_random.Next(1, 10)];
            _records[i] = new Record { Value = _random.Next(_minValue, _maxValue + 1) };
        }
        _currentSize = MaxSize;
    }

    public void Reset()
    {
        Initialize();
    }

    public float GetRandomFloat()
    {
        return (float)_random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GetRandomInt()
    {
        return _random.Next(_minValue, _maxValue + 1);
    }

    public override string ToString()
    {
        var summary = $"Current Size: {_currentSize}, Min Value: {_minValue}, Max Value: {_maxValue}\n";
        summary += "Frequency Distribution:\n";
        var distribution = _records.GroupBy(r => r.Value).ToDictionary(g => g.Key, g => g.Count());
        foreach (var item in distribution.OrderBy(kvp => kvp.Key))
        {
            summary += $"{item.Key}: {item.Value}\n";
        }
        return summary;
    }

