void initialize_user_profile_management_system(long** offsets, int** keys, Record** records, char*** string_keys) {
    // Initialize long offsets in ascending order starting from 0
    *offsets = (long*)malloc(MAX_KEYS * sizeof(long));
    for (int i = 0; i < MAX_KEYS; i++) {
        (*offsets)[i] = i;
    }

    // Initialize int keys with unique values and distribute across categories
    *keys = (int*)malloc(MAX_KEYS * sizeof(int));
    srand(time(NULL));
    for (int i = 0; i < MAX_KEYS; i++) {
        (*keys)[i] = rand() % (MAX_KEYS / 10) + (i / (MAX_KEYS / 10)) * (MAX_KEYS / 10);
    }

    // Initialize string keys with unique user identifiers
    *string_keys = (char**)malloc(MAX_KEYS * sizeof(char*));
    char* common_names[] = {"admin", "root"};
    for (int i = 0; i < MAX_KEYS; i++) {
        (*string_keys)[i] = (char*)malloc(20 * sizeof(char));
        do {
            snprintf((*string_keys)[i], 20, "user%d", rand() % 1000);
        } while (strstr(common_names, (*string_keys)[i]) != NULL);
    }

    // Initialize records with random integer values within a given range
    *records = (Record*)malloc(MAX_KEYS * sizeof(Record));
    int last_value = -1;
    for (int i = 0; i < MAX_KEYS; i++) {
        do {
            (*records)[i].value = rand() % RECORD_SIZE + 1;
        } while ((*records)[i].value == last_value);
        last_value = (*records)[i].value;
        (*records)[i].identifier = (*string_keys)[i];
    }
}

void free_user_profile_management_system(long* offsets, int* keys, Record* records, char** string_keys) {
    // Free allocated memory
    free(offsets);
    free(keys);
    for (int i = 0; i < MAX_KEYS; i++) {
        free(string_keys[i]);
    }
    free(string_keys);
    for (int i = 0; i < MAX_KEYS; i++) {
        free(records[i].identifier);
    }
    free(records);
}

int main() {
    long* offsets;
    int* keys;
    Record* records;
    char** string_keys;

    initialize_user_profile_management_system(&offsets, &keys, &records, &string_keys);

    // Use the initialized data structures...

    free_user_profile_management_system(offsets, keys, records, string_keys);

    return 0;
}
