#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int SessionID;
    int UserID;
    time_t LastActiveTime;
    char DeviceType[50];
} UserSession;

typedef struct {
    UserSession *sessions;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} SessionManager;

void init_session_manager(SessionManager *manager, size_t initial_capacity) {
    manager->sessions = malloc(initial_capacity * sizeof(UserSession));
    if (manager->sessions == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_session_manager(SessionManager *manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}

void resize_sessions(SessionManager *manager, size_t new_capacity) {
    UserSession *new_sessions = realloc(manager->sessions, new_capacity * sizeof(UserSession));
    if (new_sessions == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    manager->sessions = new_sessions;
    manager->capacity = new_capacity;
}

void add_session(SessionManager *manager, UserSession session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        resize_sessions(manager, manager->capacity * 2);
    }
    manager->sessions[manager->size++] = session;
    pthread_mutex_unlock(&manager->lock);
}

void update_session(SessionManager *manager, int session_id, UserSession new_session) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->sessions[i].SessionID == session_id) {
            manager->sessions[i] = new_session;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void remove_session(SessionManager *manager, int session_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->sessions[i].SessionID == session_id) {
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->size - i - 1) * sizeof(UserSession));
            --manager->size;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void fetch_and_update_sessions(SessionManager *manager, void (*fetch_session)(int session_id, UserSession *session)) {
    for (int session_id = 0; session_id < MAX_SESSION_ID; ++session_id) {
        UserSession session;
        if (fetch_session(session_id, &session)) {
            update_session(manager, session_id, session);
        } else {
            remove_session(manager, session_id);
        }
    }
}
