    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_nfaapi_crc_list(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }
    list->elements[list->size++] = element;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_from_nfaapi_crc_list(NFAPI_CRC_LIST_T *list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Index out of bounds
    }
    for (size_t i = index; i < list->size - 1; ++i) {
        list->elements[i] = list->elements[i + 1];
    }
    --list->size;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_from_nfaapi_crc_list(NFAPI_CRC_LIST_T *list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return NULL; // Index out of bounds
    }
    NFAPI_CRC_INDICATION_PDU_T *element = &list->elements[index];
    pthread_mutex_unlock(&list->lock);
    return element;
