#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int timestamp;
    char event_type[32];
    void* metadata;
} Event;

typedef struct {
    Event* buffer;
    size_t capacity;
    size_t head;
    size_t tail;
    atomic_int count;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CircularBuffer;

CircularBuffer* create_circular_buffer(size_t capacity) {
    CircularBuffer* cb = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    if (!cb) return NULL;

    cb->buffer = (Event*)calloc(capacity, sizeof(Event));
    if (!cb->buffer) {
        free(cb);
        return NULL;
    }

    cb->capacity = capacity;
    cb->head = 0;
    cb->tail = 0;
    atomic_init(&cb->count, 0);
    pthread_mutex_init(&cb->lock, NULL);
    pthread_cond_init(&cb->not_full, NULL);
    pthread_cond_init(&cb->not_empty, NULL);

    return cb;
}

void destroy_circular_buffer(CircularBuffer* cb) {
    free(cb->buffer);
    pthread_mutex_destroy(&cb->lock);
    pthread_cond_destroy(&cb->not_full);
    pthread_cond_destroy(&cb->not_empty);
    free(cb);
}

int log_event(CircularBuffer* cb, Event event) {
    pthread_mutex_lock(&cb->lock);

    while (atomic_load(&cb->count) == cb->capacity) {
        pthread_cond_wait(&cb->not_full, &cb->lock);
    }

    size_t next_tail = (cb->tail + 1) % cb->capacity;
    cb->buffer[cb->tail] = event;
    cb->tail = next_tail;
    atomic_fetch_add(&cb->count, 1);

    pthread_cond_signal(&cb->not_empty);
    pthread_mutex_unlock(&cb->lock);

    return 0;
}

int read_events(CircularBuffer* cb, Event** events, size_t max_count) {
    pthread_mutex_lock(&cb->lock);

    while (atomic_load(&cb->count) == 0) {
        pthread_cond_wait(&cb->not_empty, &cb->lock);
    }

    size_t count = atomic_load(&cb->count);
    size_t read_count = count < max_count ? count : max_count;
    *events = (Event*)malloc(read_count * sizeof(Event));
    if (!*events) {
        pthread_mutex_unlock(&cb->lock);
        return -1;
    }

    for (size_t i = 0; i < read_count; ++i) {
        (*events)[i] = cb->buffer[cb->head];
        cb->head = (cb->head + 1) % cb->capacity;
    }
    atomic_fetch_sub(&cb->count, read_count);

    pthread_cond_signal(&cb->not_full);
    pthread_mutex_unlock(&cb->lock);

    return read_count;
}

// Additional functions for filtering, metric collection, custom allocator,
// background thread for corrupted event repair, asynchronous processing,
// configurable retention policy, dynamic buffer resizing, and external
// component integration would be implemented here.
