#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MIN_ATTRIBUTE_LENGTH 5
#define MAX_ATTRIBUTE_LENGTH 20

typedef struct Attribute {
    char name[MAX_ATTRIBUTE_LENGTH];
    char value[MAX_ATTRIBUTE_LENGTH];
} Attribute;

typedef struct TableEntry {
    char key[100];
    time_t timestamp;
    Attribute *attributes;
    int num_attributes;
    struct TableEntry *next;
} TableEntry;

TableEntry **table = NULL;
int table_size = 0;
int current_memory_usage = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_table(int n) {
    pthread_mutex_lock(&mutex);
    if (table != NULL) {
        free(table);
    }
    table = (TableEntry **)malloc(n * sizeof(TableEntry *));
    memset(table, 0, n * sizeof(TableEntry *));
    table_size = n;
    current_memory_usage = 0;
    pthread_mutex_unlock(&mutex);
}

void generate_unique_key(char *key, int length) {
    time_t now = time(NULL);
    srand(now ^ getpid());
    snprintf(key, length, "%ld_%d", now, rand() % 1000);
}

TableEntry *create_entry(int num_attributes) {
    TableEntry *entry = (TableEntry *)malloc(sizeof(TableEntry));
    entry->attributes = (Attribute *)malloc(num_attributes * sizeof(Attribute));
    for (int i = 0; i < num_attributes; i++) {
        generate_unique_key(entry->attributes[i].name, MAX_ATTRIBUTE_LENGTH);
        generate_unique_key(entry->attributes[i].value, MAX_ATTRIBUTE_LENGTH);
    }
    entry->num_attributes = num_attributes;
    return entry;
}

void add_entry(TableEntry *entry) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < table_size; i++) {
        if (table[i] == NULL) {
            table[i] = entry;
            current_memory_usage += sizeof(TableEntry) + entry->num_attributes * sizeof(Attribute);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void check_and_add_entry(int num_attributes) {
    TableEntry *entry = create_entry(num_attributes);
    int key_exists = 0;
    for (int i = 0; i < table_size; i++) {
        if (table[i] != NULL && strcmp(table[i]->key, entry->key) == 0) {
            key_exists = 1;
            break;
        }
    }
    if (!key_exists) {
        add_entry(entry);
    } else {
        free(entry->attributes);
        free(entry);
    }
}

void log_memory_usage() {
    printf("Current memory usage: %d bytes\n", current_memory_usage);
}

int main() {
    initialize_table(100);
    check_and_add_entry(5);
    log_memory_usage();
    return 0;
}
