#define MAX_REQUESTS 1000

typedef struct {
    int requestId;
    char resourceType[50];
} ResourceProfile;

typedef struct {
    ResourceProfile profile;
    pthread_mutex_t lock;
} ResourceAllocationRequest;

ResourceAllocationRequest allocationRequests[MAX_REQUESTS];

void initializeResourceAllocations(int numRequests) {
    for (int i = 0; i < numRequests; i++) {
        allocationRequests[i].profile.requestId = i + 1;
        snprintf(allocationRequests[i].profile.resourceType, sizeof(allocationRequests[i].profile.resourceType), "Resource%d", i + 1);
        pthread_mutex_init(&allocationRequests[i].lock, NULL);
    }
}

void allocateResources(int requestId, const char* resourceType) {
    for (int i = 0; i < MAX_REQUESTS; i++) {
        if (pthread_mutex_trylock(&allocationRequests[i].lock) == 0) {
            if (allocationRequests[i].profile.requestId == requestId) {
                snprintf(allocationRequests[i].profile.resourceType, sizeof(allocationRequests[i].profile.resourceType), "%s", resourceType);
                pthread_mutex_unlock(&allocationRequests[i].lock);
                return;
            }
            pthread_mutex_unlock(&allocationRequests[i].lock);
        }
    }
}

void* handleRequest(void* arg) {
    int requestId = *(int*)arg;
    const char* resourceType = "DynamicResource";
    allocateResources(requestId, resourceType);
    free(arg);
    return NULL;
}

int main() {
    initializeResourceAllocations(MAX_REQUESTS);

    pthread_t threads[MAX_REQUESTS];
    for (int i = 0; i < MAX_REQUESTS; i++) {
        int* requestId = malloc(sizeof(int));
        *requestId = i + 1;
        pthread_create(&threads[i], NULL, handleRequest, requestId);
    }

    for (int i = 0; i < MAX_REQUESTS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
