typedef struct {
    int value;
    char* buffer;
} record;

long* allocate_long_array(int size) {
    long* array = (long*)malloc(size * sizeof(long));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for long array\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

int* allocate_int_array(int size) {
    int* array = (int*)malloc(size * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for int array\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

record* allocate_record_array(int size) {
    record* array = (record*)malloc(size * sizeof(record));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for record array\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

void initialize_arrays(long* offsets, int* keys, record* records, int max_key_value, int num_records) {
    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = i * 10L; // Simple ascending order
        keys[i] = rand() % max_key_value + 1;

        records[i].value = rand() % (max_key_value / 2);
        while (i > 0 && records[i].value == records[i - 1].value) {
            records[i].value = rand() % (max_key_value / 2);
        }

        int string_length = rand() % (MAX_STRING_LENGTH - MIN_STRING_LENGTH + 1) + MIN_STRING_LENGTH;
        records[i].buffer = (char*)malloc((string_length + 1) * sizeof(char));
        if (!records[i].buffer) {
            fprintf(stderr, "Memory allocation failed for record buffer\n");
            exit(EXIT_FAILURE);
        }
        for (int j = 0; j < string_length; ++j) {
            records[i].buffer[j] = 'A' + rand() % 26;
        }
        records[i].buffer[string_length] = '\0';
    }
}

void free_arrays(long* offsets, int* keys, record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].buffer);
    }
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long* offsets = allocate_long_array(MAX_RECORDS);
    int* keys = allocate_int_array(MAX_RECORDS);
    record* records = allocate_record_array(MAX_RECORDS);

    initialize_arrays(offsets, keys, records, MAX_KEY_VALUE, MAX_RECORDS);

    // Use the arrays...

    free_arrays(offsets, keys, records, MAX_RECORDS);

    return 0;
}
