using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class UserAccountManager
{
    private readonly int _maxSizeInBytes;
    private readonly ConcurrentDictionary<int, bool> _rntiPool = new ConcurrentDictionary<int, bool>();
    private long _totalMemoryUsage;
    private int _successfulAllocations;
    private int _failedAllocations;
    private int _uniqueRntiCount;

    public UserAccountManager(int maxSizeInBytes)
    {
        _maxSizeInBytes = maxSizeInBytes;
    }

    public void ConfigureValidationLogic()
    {
        // Configure validation logic for user accounts and passwords
    }

    public void SetUserLockoutDefaults()
    {
        // Set default lockout policies for users
    }

    public NFAPI_CRC_INDICATION_PDU_T[] GeneratePduArray(int n, int maxSizeInBytes)
    {
        var pduArray = new NFAPI_CRC_INDICATION_PDU_T[n];
        _totalMemoryUsage = 0;
        _successfulAllocations = 0;
        _failedAllocations = 0;
        _uniqueRntiCount = 0;

        for (int i = 0; i < n; i++)
        {
            if (_totalMemoryUsage + sizeof(NFAPI_CRC_INDICATION_PDU_T) > maxSizeInBytes)
            {
                LogAllocationFailure("Memory limit exceeded");
                break;
            }

            var pdu = new NFAPI_CRC_INDICATION_PDU_T
            {
                RX_UE_INFORMATION_TAG = GenerateUniqueRnti(),
                RNTI = GenerateUniqueRnti(),
                CRC_INDICATION_REL8_TAG = GenerateRandomCrcFlag()
            };

            _totalMemoryUsage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
            pduArray[i] = pdu;
        }

        LogPerformanceMetrics();
        return pduArray;
    }

    private int GenerateUniqueRnti()
    {
        int rnti;
        do
        {
            rnti = RandomNumberGenerator.GetInt32(1, 65535);
        } while (!_rntiPool.TryAdd(rnti, true));
        _uniqueRntiCount++;
        return rnti;
    }

    private bool GenerateRandomCrcFlag()
    {
        return RandomNumberGenerator.GetRandomBytes(1)[0] % 2 == 0;
    }

    private void LogAllocationFailure(string message)
    {
        File.AppendAllText("allocation_failures.log", $"{DateTime.Now}: {message}\n");
        _failedAllocations++;
    }

    private void LogPerformanceMetrics()
