typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *indication_pdu;
    int count;
    int max_count;
} CRCIndicationList;

typedef struct {
    char *pool;
    size_t pool_size;
    size_t used_size;
} MemoryPool;

CRCIndicationList* create_crc_indication_list(int max_count) {
    CRCIndicationList *list = (CRCIndicationList*)malloc(sizeof(CRCIndicationList));
    list->indication_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->max_count = max_count;
    return list;
}

void destroy_crc_indication_list(CRCIndicationList *list) {
    free(list->indication_pdu);
    free(list);
}

MemoryPool* create_memory_pool(size_t pool_size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->pool = (char*)malloc(pool_size);
    pool->pool_size = pool_size;
    pool->used_size = 0;
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    free(pool->pool);
    free(pool);
}

void* allocate_from_pool(MemoryPool *pool, size_t size) {
    if (pool->used_size + size > pool->pool_size) {
        // Handle allocation failure
        return NULL;
    }
    void *ptr = pool->pool + pool->used_size;
    pool->used_size += size;
    return ptr;
}

void populate_crc_indication_list(CRCIndicationList *list, MemoryPool *pool, int max_rnti) {
    srand(time(NULL));
    for (int i = 0; i < list->max_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *indication_pdu = &list->indication_pdu[i];
        indication_pdu->rx_ue_information_tag = allocate_from_pool(pool, sizeof(RX_UE_INFORMATION_TAG));
        indication_pdu->rnti = rand() % max_rnti;
        indication_pdu->crc_indication_rel8_tag.crcflag = (rand() % 2) ? NFAPI_CRC_INDICATION_REL8_FLAG_OK : NFAPI_CRC_INDICATION_REL8_FLAG_ERROR;
    }
}

void populate_records(Record *records, int count, int min_key, int max_key) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].offset = rand();
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        records[i].value = (float)rand() / RAND_MAX;
    }
}

void* thread_function(void *arg) {
    // Thread function implementation
    return NULL;
}

int main() {
    int max_rnti = MAX_RNTI;
    int max_records = MAX_RECORDS;
    MemoryPool *pool = create_memory_pool(max_records * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    CRCIndicationList *list = create_crc_indication_list(max_records);

    populate_crc_indication_list(list, pool, max_rnti);
    Record records[max_records];
