#include <arpa/inet.h>

#define MAX_LINE_LENGTH 1024
#define MAX_HOSTNAMES 1000
#define CACHE_SIZE 100

typedef struct {
    char hostname[MAX_LINE_LENGTH];
    struct in_addr ip_address;
} DNSCacheEntry;

DNSCacheEntry dns_cache[CACHE_SIZE];
int cache_index = 0;

pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* process_csv(void* arg) {
    FILE* file = fopen("data.csv", "r");
    if (!file) {
        perror("Failed to open CSV file");
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        // Process each line here
        // Example: Extract hostname and perform DNS resolution
        char* hostname = strtok(line, ",");
        if (hostname) {
            pthread_mutex_lock(&cache_lock);
            for (int i = 0; i < cache_index; i++) {
                if (strcmp(dns_cache[i].hostname, hostname) == 0) {
                    // Use cached IP address
                    printf("Using cached IP address for %s: %s\n", hostname, inet_ntoa(dns_cache[i].ip_address));
                    pthread_mutex_unlock(&cache_lock);
                    continue;
                }
            }
            if (cache_index < CACHE_SIZE) {
                struct hostent* host = gethostbyname(hostname);
                if (host) {
                    dns_cache[cache_index].ip_address.s_addr = *(unsigned long*)host->h_addr_list[0];
                    strcpy(dns_cache[cache_index].hostname, hostname);
                    cache_index++;
                    printf("Resolved %s to %s\n", hostname, inet_ntoa(dns_cache[cache_index - 1].ip_address));
                } else {
                    printf("Failed to resolve %s\n", hostname);
                }
            } else {
                printf("DNS cache is full\n");
            }
            pthread_mutex_unlock(&cache_lock);
        }
    }

    fclose(file);
    return NULL;
}

int main() {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, process_csv, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    pthread_join(thread_id, NULL);

    return 0;
}
```

This code provides a basic structure for processing a CSV file and performing DNS resolution using multi-threading. It includes a simple caching mechanism to store resolved IP addresses. The actual data processing logic (e.g., extracting hostnames) is left as an exercise for the junior developer.']

