#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RNTI;
    RX_UE_INFORMATION_TAG rx_tag;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

int init_crc_list(NFAPI_CRC_LIST_T *list, size_t initial_capacity) {
    list->pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdu_list) {
        return -1; // Memory allocation failed
    }
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return 0;
}

int add_crc_pdu(NFAPI_CRC_LIST_T *list, int rnti, RX_UE_INFORMATION_TAG rx_tag) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory reallocation failed
        }
        list->pdu_list = new_list;
        list->capacity = new_capacity;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &list->pdu_list[list->size++];
    new_pdu->RNTI = rnti;
    new_pdu->rx_tag = rx_tag;
    new_pdu->crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->pdu_list);
    list->pdu_list = NULL;
    list->capacity = 0;
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
