#include <openssl/evp.h>
#include <openssl/hmac.h>
#include <openssl/rand.h>

typedef struct {
    EVP_CIPHER *cipher;
    int key_size;
    int iv_size;
} CipherInfo;

CipherInfo* get_cipher_info(const char* algorithm, const char* mode) {
    CipherInfo* info = (CipherInfo*)malloc(sizeof(CipherInfo));
    if (!info) return NULL;

    if (strcmp(algorithm, "AES") == 0 && strcmp(mode, "CBC") == 0) {
        info->cipher = EVP_aes_256_cbc();
        info->key_size = 32;
        info->iv_size = 16;
    } else if (strcmp(algorithm, "Blowfish") == 0 && strcmp(mode, "OFB") == 0) {
        info->cipher = EVP_bf_ofb();
        info->key_size = 16;
        info->iv_size = 8;
    } else if (strcmp(algorithm, "RC4") == 0 && strcmp(mode, "CTR") == 0) {
        info->cipher = EVP_rc4_40();
        info->key_size = 5;
        info->iv_size = 0; // RC4 does not use IV
    } else {
        free(info);
        return NULL;
    }

    return info;
}

int encrypt_data(const unsigned char* key, const unsigned char* iv, const unsigned char* plaintext, int plaintext_len, unsigned char** ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (EVP_EncryptInit_ex(ctx, info->cipher, NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int ciphertext_len = len;

    if (EVP_EncryptFinal_ex(ctx, (*ciphertext) + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

int decrypt_data(const unsigned char* key, const unsigned char* iv, const unsigned char* ciphertext, int ciphertext_len, unsigned char** plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (EVP_DecryptInit_ex(ctx, info->cipher, NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int plaintext_len = len;

    if (EVP_DecryptFinal_ex(ctx, (*plaintext) + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

int generate_hmac(const unsigned char* key, const unsigned char* data, int data_len, unsigned char** hmac) {
    HMAC_CTX *ctx = HMAC_CTX_new();
    if (!ctx) return -1;

    if (HMAC_Init_ex(ctx, key, strlen((char*)key), EVP_sha256(), NULL) != 1) {
        HMAC_CTX_free(ctx);
        return -1;
    }

    if (HMAC_Update(ctx, data, data_len) != 1) {
        HMAC_CTX_free(ctx);
        return -1;
    }

    *hmac = (unsigned char*)malloc(HMAC_size(ctx));
    if (!*hmac) {
        HMAC_CTX_free(ctx);
        return -1;
    }

    int hmac_len;
    if (HMAC_Final(ctx, *hmac, &hmac_len) != 1) {
        free(*hmac);
        HMAC_CTX_free(ctx);
        return -1;
    }
    HMAC_CTX_free(ctx);

    return hmac_len;
}

void secure_key_retrieval(const char* key_id, unsigned char** key) {
