#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

void initDynamicList(DynamicList *list) {
    list->entries = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = MAX_ENTRIES;
    pthread_mutex_init(&list->lock, NULL);
}

void addEntry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        fprintf(stderr, "List is full\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (entry.RNTI < 0 || entry.RNTI > 65535) {
        fprintf(stderr, "Invalid RNTI value: %u\n", entry.RNTI);
        pthread_mutex_unlock(&list->lock);
        return;
    }
    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);
}

void serializeList(DynamicList *list, FILE *file) {
    pthread_mutex_lock(&list->lock);
    fwrite(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    pthread_mutex_unlock(&list->lock);
}

void deserializeList(DynamicList *list, FILE *file) {
    pthread_mutex_lock(&list->lock);
    size_t count = fread(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ENTRIES, file);
    if (count > MAX_ENTRIES) {
        fprintf(stderr, "Deserialized more entries than capacity\n");
        list->count = MAX_ENTRIES;
    } else {
        list->count = count;
    }
    pthread_mutex_unlock(&list->lock);
}

void destroyDynamicList(DynamicList *list) {
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
}
