    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    signal(SIGINT, handle_sigint);

    int num_read = 0;
    while (num_read < MAX_INTS && scanf("%d", &array[num_read]) == 1) {
        if (array[num_read] % 2 == 0) {
            sum_even += array[num_read];
            count_even++;
        }
        num_read++;
    }

    printf("Sum of even integers: %lld\n", sum_even);
    printf("Count of even numbers: %d\n", count_even);

    free(array);
}

int main() {
