#include <iostream>
#include <vector>
#include <memory>
#include <mutex>
#include <atomic>
#include <chrono>
#include <unordered_map>

class Session {
public:
    using ID = std::string;
    using Preferences = std::map<std::string, std::string>;

    Session(ID id, Preferences prefs) : id_(id), preferences_(prefs), lastActive_(std::chrono::system_clock::now()) {}

    ID getId() const { return id_; }
    Preferences getPreferences() const { return preferences_; }
    void updatePreferences(const Preferences& newPrefs) {
        std::lock_guard<std::mutex> lock(mutex_);
        preferences_ = newPrefs;
    }
    void touch() {
        lastActive_ = std::chrono::system_clock::now();
    }

private:
    ID id_;
    Preferences preferences_;
    std::chrono::time_point<std::chrono::system_clock> lastActive_;
    mutable std::mutex mutex_;
};

class SessionManager {
public:
    using SessionPtr = std::shared_ptr<Session>;
    using SessionMap = std::unordered_map<Session::ID, SessionPtr>;

    SessionManager(size_t maxMemoryUsage) : maxMemoryUsage_(maxMemoryUsage), currentMemoryUsage_(0) {}

    void addSession(const Session::ID& id, const Session::Preferences& prefs) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (currentMemoryUsage_ + sizeof(Session) > maxMemoryUsage_) {
            // Handle memory pressure
            cleanupInactiveSessions();
        }
        sessions_[id] = std::make_shared<Session>(id, prefs);
        currentMemoryUsage_ += sizeof(Session);
    }

    void updateSession(const Session::ID& id, const Session::Preferences& newPrefs) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (sessions_.find(id) != sessions_.end()) {
            sessions_[id]->updatePreferences(newPrefs);
        }
    }

    void touchSession(const Session::ID& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (sessions_.find(id) != sessions_.end()) {
            sessions_[id]->touch();
        }
    }

private:
    size_t maxMemoryUsage_;
    size_t currentMemoryUsage_;
    SessionMap sessions_;
    mutable std::mutex mutex_;

    void cleanupInactiveSessions() {
        auto now = std::chrono::system_clock::now();
        for (auto it = sessions_.begin(); it != sessions_.end();) {
            if (std::chrono::duration_cast<std::chrono::seconds>(now - it->second->lastActive_).count() > 3600) {
                currentMemoryUsage_ -= sizeof(Session);
                it = sessions_.erase(it);
            } else {
                ++it;
            }
        }
    }
};

int main() {
    SessionManager manager(1024 * 1024); // 1MB memory limit
    manager.addSession("session1", {{"theme", "dark"}, {"language", "en"}});
    manager.updateSession("session1", {{"theme", "light"}});
    manager.touchSession("session1");
    return 0;
}
