    return -1; // Session not found
}

int expire_session(const char *session_id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i].uuid, session_id) == 0) {
            memset(&sessions[i], 0, sizeof(Session));
            memory_usage -= sizeof(Session);
            log_message("Session expired");
            pthread_mutex_unlock(&lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&lock);
    log_message("Session not found for expiration");
    return -1; // Session not found
}

void garbage_collection() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].last_activity == 0) { // Assuming expired sessions have last_activity set to 0
            memset(&sessions[i], 0, sizeof(Session));
            memory_usage -= sizeof(Session);
        }
    }
    pthread_mutex_unlock(&lock);
}

// Example usage in a web API function
int handle_session_request(const char *method, const char *session_id, time_t last_activity, int authenticated) {
    if (strcmp(method, "PUT") == 0) {
        return update_session(session_id, last_activity, authenticated);
    } else if (strcmp(method, "DELETE") == 0) {
        return expire_session(session_id);
    }
    return -1; // Invalid method
}
