#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_EXTRA_DATA_SIZE 1024 // 1KB
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int value;
    long* offset;
    int key;
    void* extra_data;
} record;

void initialize_records(int n, record** records, long** offsets, int** keys, void*** extra_data, int compressed_mode) {
    srand(time(NULL));
    *records = (record*)malloc(n * sizeof(record));
    *offsets = (long*)malloc(n * sizeof(long));
    *keys = (int*)malloc(n * sizeof(int));
    *extra_data = (void**)malloc(n * sizeof(void*));

    long total_memory_used = 0;
    for (int i = 0; i < n; i++) {
        (*records)[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        (*offsets)[i] = i * sizeof(record);
        (*keys)[i] = rand() % n;

        if (compressed_mode) {
            // Share common extra data segments
            (*records)[i].extra_data = (*extra_data)[(*keys)[i]];
        } else {
            // Allocate unique extra data for each record
            size_t extra_size = rand() % MAX_EXTRA_DATA_SIZE + 1;
            void* new_extra_data = malloc(extra_size);
            if (new_extra_data == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(1);
            }
            (*records)[i].extra_data = new_extra_data;
        }

        total_memory_used += sizeof(record) + ((compressed_mode ? 0 : rand() % MAX_EXTRA_DATA_SIZE + 1));
        if (total_memory_used > MAX_MEMORY) {
            fprintf(stderr, "Memory allocation exceeds maximum limit\n");
            exit(1);
        }
    }
}

int main() {
    int n = 10;
    record* records;
    long* offsets;
    int* keys;
    void** extra_data;

    initialize_records(n, &records, &offsets, &keys, &extra_data, 0); // Set compressed_mode to 0 for uncompressed mode

    // Free allocated memory
    for (int i = 0; i < n; i++) {
        if (!compressed_mode) {
            free(extra_data[i]);
        }
    }
    free(records);
    free(offsets);
    free(keys);
    free(extra_data);

    return 0;
}
