typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicCollection;

DynamicCollection* create_collection(size_t initial_capacity) {
    DynamicCollection *collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    collection->records = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_collection(DynamicCollection *collection) {
    pthread_mutex_lock(&collection->mutex);
    free(collection->records);
    pthread_mutex_unlock(&collection->mutex);
    free(collection);
}

int insert_record(DynamicCollection *collection, RX_UE_INFORMATION_TAG ue_info, uint16_t rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_records = (NFAPI_CRC_INDICATION_PDU_T*)realloc(collection->records, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Memory allocation failed
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    while (collection->size > 0 && collection->records[collection->size - 1].rnti == rnti) {
        collection->size--;
    }

    if (collection->size >= MAX_RNTI_THRESHOLD) {
        pthread_mutex_unlock(&collection->mutex);
        return -2; // Maximum RNTI threshold exceeded
    }

    collection->records[collection->size].ue_info = ue_info;
    collection->records[collection->size].rnti = rnti;
    collection->records[collection->size].crc_indication = crc_indication;
    collection->size++;

    pthread_mutex_unlock(&collection->mutex);
    return 0; // Success
}

void purge_unused_records(DynamicCollection *collection) {
    pthread_mutex_lock(&collection->mutex);

    size_t new_size = 0;
    for (size_t i = 0; i < collection->size; i++) {
        if (is_record_used(collection->records[i])) { // Assume is_record_used checks if the record is still relevant
            collection->records[new_size++] = collection->records[i];
        }
    }

    if (new_size != collection->size) {
        NFAPI_CRC_INDICATION_PDU_T *new_records = (NFAPI_CRC_INDICATION_PDU_T*)realloc(collection->records, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_records) {
            collection->records = new_records;
            collection->size = new_size;
        }
    }

    pthread_mutex_unlock(&collection->mutex);
}

