#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char* buffer;
    time_t* timestamp;
    int resource_id;
} record;

int generate_unique_key(int max_value, int* used_keys) {
    int key;
    do {
        key = rand() % (max_value + 1);
    } while (used_keys[key]);
    used_keys[key] = 1;
    return key;
}

void initialize_record(record* rec, int value_range, int resource_id) {
    rec->value = rand() % value_range;
    rec->buffer = malloc(256 * sizeof(char));
    if (rec->buffer == NULL) {
        fprintf(stderr, "Memory allocation failed for buffer\n");
        exit(EXIT_FAILURE);
    }
    size_t length = 1 + rand() % 255;
    for (size_t i = 0; i < length; ++i) {
        rec->buffer[i] = 'A' + rand() % 62;
    }
    rec->buffer[length] = '\0';
    rec->timestamp = malloc(sizeof(time_t));
    if (rec->timestamp == NULL) {
        fprintf(stderr, "Memory allocation failed for timestamp\n");
        exit(EXIT_FAILURE);
    }
    *rec->timestamp = time(NULL);
    rec->resource_id = resource_id;
}

void free_record(record* rec) {
    free(rec->buffer);
    free(rec->timestamp);
}

int fetch_external_timestamp(time_t* timestamp) {
    // Simulate fetching external timestamp with potential delays
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Failed to get current time");
        return 0;
    }
    *timestamp = ts.tv_sec + ts.tv_nsec / 1e9;
    return 1;
}

void initialize_components(long** offsets, int** keys, record*** records, time_t** timestamps, int** resource_ids, int size, int max_key_value, int value_range) {
    *offsets = malloc(size * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(EXIT_FAILURE);
    }
    *keys = malloc(size * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(*offsets);
        exit(EXIT_FAILURE);
    }
    *records = malloc(size * sizeof(record*));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }
    *timestamps = malloc(size * sizeof(time_t));
    if (*timestamps == NULL) {
        fprintf(stderr, "Memory allocation failed for timestamps\n");
        free(*offsets);
        free(*keys);
        free(*records);
        exit(EXIT_FAILURE);
    }
    *resource_ids = malloc(size * sizeof(int));
    if (*resource_ids == NULL) {
        fprintf(stderr, "Memory allocation failed for resource ids\n");
        free(*offsets);
        free(*keys);
        free(*records);
        free(*timestamps);
        exit(EXIT_FAILURE);
    }

    int* used_keys = calloc(max_key_value + 1, sizeof(int));
    if (used_keys == NULL) {
        fprintf(stderr, "Memory allocation failed for used keys\n");
        free(*offsets);
        free(*keys);
        free(*records);
        free(*timestamps);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; ++i) {
        (*offsets)[i] = i;
        (*keys)[i] = generate_unique_key(max_key_value, used_keys);
        (*records)[i] = malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            free(*offsets);
            free(*keys);
            for (int j = 0; j < i; ++j) {
                free_record((*records)[j]);
            }
            free(*records);
            free(*timestamps);
            free(*resource_ids);
            exit(EXIT_FAILURE);
        }
        initialize_record((*records)[i], value_range, (*resource_ids)[i] = rand() % 100); // Assuming max resource id is 99
    }

    for (int i = 0; i < size; ++i) {
        if (!fetch_external_timestamp(&(*timestamps)[i])) {
            fprintf(stderr, "Failed to fetch external timestamp for record %d\n", i);
            free(*offsets);
            free(*keys);
            for (int j = 0; j <= i; ++j) {
                free_record((*records)[j]);
            }
            free(*records);
            free(*timestamps);
            free(*resource_ids);
            exit(EXIT_FAILURE);
        }
    }

    free(used_keys);
}

void cleanup(long* offsets, int* keys, record** records, time_t* timestamps, int* resource_ids, int size) {
    for (int i = 0; i < size; ++i) {
        free_record(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    free(timestamps);
    free(resource_ids);
}

int main() {
    srand(time(NULL));
    const int size = 5;
    const int max_key_value = 100;
    const int value_range = 1000;

    long* offsets;
    int* keys;
    record** records;
    time_t* timestamps;
    int* resource_ids;

    initialize_components(&offsets, &keys, &records, &timestamps, &resource_ids, size, max_key_value, value_range);

    // Use the initialized components...

    cleanup(offsets, keys, records, timestamps, resource_ids, size);

    return 0;
}
