            return;
        }

        (*records)[i]->timestamp = (time_t*)malloc(sizeof(time_t));
        if ((*records)[i]->timestamp == NULL) {
            fprintf(stderr, "Memory allocation failed for timestamp in record %d\n", i);
            free(*offsets);
            free(*keys);
            for (int j = 0; j <= i; j++) {
                free((*records)[j]->buffer);
                free((*records)[j]);
            }
            free(*records);
            return;
        }

        time((*records)[i]->timestamp);
    }

    // Initialize metadata
    for (int i = 0; i < max_keys; i++) {
        (*metadata)[i] = NULL; // Example initialization logic
    }
}

void free_data_structures(long* offsets, int* keys, record** records, void** metadata) {
    if (offsets != NULL) {
        free(offsets);
    }

    if (keys != NULL) {
        free(keys);
    }

    if (records != NULL) {
        for (int i = 0; records[i] != NULL; i++) {
            if (records[i]->buffer != NULL) {
                free(records[i]->buffer);
            }
            if (records[i]->timestamp != NULL) {
                free(records[i]->timestamp);
            }
            free(records[i]);
        }
        free(records);
    }

    if (metadata != NULL) {
        for (int i = 0; metadata[i] != NULL; i++) {
            // Free any additional metadata fields here
        }
        free(metadata);
    }
}

int main() {
    int max_keys = 10;
    long* offsets;
    int* keys;
    record** records;
    void** metadata;

    initialize_data_structures(max_keys, 1, 100, &offsets, &keys, &records, &metadata);

    // Use the data structures here

    free_data_structures(offsets, keys, records, metadata);

    return 0;
}
