    long* offsets = new long[batch.size()];
    int* keys = new int[batch.size()];
    Record* records = new Record[batch.size()];

    for (size_t i = 0; i < batch.size(); ++i) {
        offsets[i] = i * 10;
        keys[i] = rand() % keyRange + 1;
        records[i].value = rand() % keyRange + 1;
    }

