} DataPipeline;

DataPipeline* initialize_data_pipeline(size_t initial_record_count) {
    DataPipeline *pipeline = (DataPipeline*)malloc(sizeof(DataPipeline));
    if (!pipeline) {
        // Log memory allocation failure
        return NULL;
    }

    pipeline->offset = 0;
    pipeline->key = 1;
    pipeline->record_count = initial_record_count;
    pipeline->records = (Record*)calloc(initial_record_count, sizeof(Record));
    if (!pipeline->records) {
        // Log memory allocation failure
        free(pipeline);
        return NULL;
    }

    pthread_mutex_init(&pipeline->lock, NULL);

    return pipeline;
}

void destroy_data_pipeline(DataPipeline *pipeline) {
    if (pipeline) {
        pthread_mutex_lock(&pipeline->lock);
        free(pipeline->records);
        pthread_mutex_unlock(&pipeline->lock);
        pthread_mutex_destroy(&pipeline->lock);
        free(pipeline);
    }
}
