typedef struct {
    int value;
    long* offset;
    int key;
    void* extra_data;
    bool compressed_mode;
} Record;

Record* create_records(int n, bool compressed_mode) {
    // Allocate memory for records and offsets
    Record* records = (Record*)malloc(n * sizeof(Record));
    if (!records) return NULL;

    long* offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) {
        free(records);
        return NULL;
    }

    // Initialize random seed
    srand(time(NULL));

    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        offsets[i] = i * sizeof(Record);
        records[i].offset = &offsets[i];
        records[i].key = i;
        records[i].compressed_mode = compressed_mode;

        if (compressed_mode) {
            // Shared extra data for compressed mode
            records[i].extra_data = malloc(MAX_EXTRA_DATA_SIZE);
            if (!records[i].extra_data) {
                free(offsets);
                free(records);
                return NULL;
            }
        } else {
            // Unique extra data for uncompressed mode
            records[i].extra_data = malloc(rand() % MAX_EXTRA_DATA_SIZE + 1);
            if (!records[i].extra_data) {
                free(offsets);
                free(records);
                return NULL;
            }
        }

        // Set compression mode specific initialization
        if (compressed_mode) {
            // Example: Initialize shared extra data
            memset(records[i].extra_data, 0, MAX_EXTRA_DATA_SIZE);
        } else {
            // Example: Initialize unique extra data
            memset(records[i].extra_data, i % 256, rand() % MAX_EXTRA_DATA_SIZE + 1);
        }
    }

    return records;
}

void free_records(Record* records, int n) {
    for (int i = 0; i < n; i++) {
        free(records[i].extra_data);
    }
    free(records);
}
