        offsets[i] = i * 1024; // Example offset calculation
        keys[i] = rand() % 1000000; // Unique key within a range

        if (i > 0 && keys[i] == keys[i - 1]) {
            keys[i] = (keys[i] + 1) % 1000000; // Ensure uniqueness
        }

        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record at index %zu\n", i);
            exit(EXIT_FAILURE);
        }
        records[i]->value = rand() % 1000; // Random value within a range
        timestamps[i] = time(NULL) + i * 5; // Timestamp with fixed interval

        if (i > 0 && records[i]->value == records[i - 1]->value) {
            records[i]->value = (records[i]->value + 1) % 1000; // Ensure uniqueness
        }
    }
}

void free_arrays(long *offsets, int *keys, record **records, time_t *timestamps, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(timestamps);
}

