typedef struct Node {
    char* uuid;
    int value;
    struct Node* children[5];
} Node;

typedef struct Entry {
    Node* node;
    int key;
} Entry;

typedef struct LinkedListHeader {
    Node** nodes;
    int count;
} LinkedListHeader;

LinkedListHeader* manageMemory(int numEntries, int minValue, int maxValue) {
    srand(time(NULL));
    LinkedListHeader* header = (LinkedListHeader*)malloc(sizeof(LinkedListHeader));
    if (!header) return NULL;

    header->nodes = (Node**)malloc(numEntries * sizeof(Node*));
    if (!header->nodes) {
        free(header);
        return NULL;
    }

    for (int i = 0; i < numEntries; ++i) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            // Clean up previously allocated nodes
            for (int j = 0; j < i; ++j) free(header->nodes[j]);
            free(header->nodes);
            free(header);
            return NULL;
        }

        node->uuid = (char*)malloc(37); // UUID length including null terminator
        if (!node->uuid) {
            free(node);
            // Clean up previously allocated nodes
            for (int j = 0; j < i; ++j) free(header->nodes[j]);
            free(header->nodes);
            free(header);
            return NULL;
        }

        snprintf(node->uuid, 37, "%08lX-%04lX-%04lX-%04lX-%012lX",
                 (unsigned long)rand(), (unsigned long)rand(),
                 (unsigned long)rand(), (unsigned long)rand(),
                 (unsigned long)rand());

        node->value = rand() % (maxValue - minValue + 1) + minValue;

        for (int j = 0; j < 5; ++j) {
            node->children[j] = NULL;
        }

        header->nodes[i] = node;
    }

    return header;
}
