#define DEFAULT_BUFFER_SIZE 10

typedef struct {
    char *buffer;
    int key;
} item;

item* initialize_item_array(int size, const char *default_buffer, int start_key) {
    if (size <= 0) return NULL;

    item *array = malloc(size * sizeof(item));
    if (!array) return NULL;

    for (int i = 0; i < size; ++i) {
        array[i].buffer = malloc(DEFAULT_BUFFER_SIZE);
        if (!array[i].buffer) {
            // Cleanup previously allocated memory
            for (int j = 0; j < i; ++j) free(array[j].buffer);
            free(array);
            return NULL;
        }
        strcpy(array[i].buffer, default_buffer ? default_buffer : "default");
        array[i].key = start_key + i;
    }

    return array;
}

void cleanup_item_array(item *array, int size) {
    if (!array) return;

    for (int i = 0; i < size; ++i) free(array[i].buffer);
    free(array);
}

int main() {
    const char *default_buffer = "example";
    int start_key = 100;
    int array_size = 5;

    item *items = initialize_item_array(array_size, default_buffer, start_key);
    if (!items) {
        fprintf(stderr, "Failed to allocate memory for item array.\n");
        return EXIT_FAILURE;
    }

    // Demonstrate usage
    for (int i = 0; i < array_size; ++i) {
        printf("Item %d: Buffer=%s, Key=%d\n", i, items[i].buffer, items[i].key);
    }

    cleanup_item_array(items, array_size);

    return EXIT_SUCCESS;
}
