#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct item {
    char *buffer;
    int key;
    struct item *next;
} Item;

Item* create_item(const char *str, int key) {
    Item *new_item = (Item *)malloc(sizeof(Item));
    if (new_item == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_item->buffer = strdup(str);
    if (new_item->buffer == NULL) {
        free(new_item);
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_item->key = key;
    new_item->next = NULL;
    return new_item;
}

void add_item(Item **head, const char *str, int key) {
    Item *new_item = create_item(str, key);
    if (*head == NULL) {
        *head = new_item;
    } else {
        Item *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_item;
    }
}

void traverse_list(Item *head) {
    Item *current = head;
    while (current != NULL) {
        printf("Key: %d, Buffer: %.10s\n", current->key, current->buffer);
        current = current->next;
    }
}

void free_list(Item *head) {
    Item *current = head;
    while (current != NULL) {
        Item *temp = current;
        current = current->next;
        free(temp->buffer);
        free(temp);
    }
}
