#include <string.h>
#include <time.h>

typedef struct {
    char *buffer;
    int key;
    time_t timestamp;
} item;

item* initialize_item_array(int size, const char *default_buffer, int min_key, int max_key) {
    if (size <= 0 || min_key >= max_key) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    item *array = malloc(size * sizeof(item));
    if (!array) {
        perror("Failed to allocate memory for item array.");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator
    int keys_used[1000] = {0}; // Assuming max_key - min_key <= 1000

    for (int i = 0; i < size; ++i) {
        array[i].buffer = malloc(strlen(default_buffer) + 1);
        if (!array[i].buffer) {
            perror("Failed to allocate memory for buffer.");
            // Free previously allocated buffers
            for (int j = 0; j < i; ++j) {
                free(array[j].buffer);
            }
            free(array);
            return NULL;
        }
        strcpy(array[i].buffer, default_buffer);

        int key;
        do {
            key = min_key + rand() % (max_key - min_key + 1);
        } while (keys_used[key - min_key]);
        keys_used[key - min_key] = 1;

        array[i].key = key;
        array[i].timestamp = time(NULL);
    }

    return array;
}

void cleanup_item_array(item *array, int size) {
    for (int i = 0; i < size; ++i) {
        free(array[i].buffer);
    }
    free(array);
}

int main() {
    const char *default_buffer = "Default Item";
    int min_key = 1;
    int max_key = 100;
    int array_size = 5;

    item *items = initialize_item_array(array_size, default_buffer, min_key, max_key);
    if (items) {
        for (int i = 0; i < array_size; ++i) {
            printf("Item %d: Buffer=%s, Key=%d, Timestamp=%ld\n", i, items[i].buffer, items[i].key, items[i].timestamp);
        }
        cleanup_item_array(items, array_size);
    }

    return 0;
}
