typedef struct {
    int value;
} record;

void processAndAnalyzeData(int maxKey, int minValue, int maxValue) {
    srand(time(NULL));

    long *longOffsets = (long *)malloc((maxKey + 1) * sizeof(long));
    if (!longOffsets) {
        fprintf(stderr, "Memory allocation failed for long offsets.\n");
        return;
    }

    int *intKeys = (int *)malloc((maxKey + 1) * sizeof(int));
    if (!intKeys) {
        fprintf(stderr, "Memory allocation failed for int keys.\n");
        free(longOffsets);
        return;
    }

    record *records = (record *)malloc((maxValue - minValue + 1) * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(longOffsets);
        free(intKeys);
        return;
    }

    float *weights = (float *)malloc((maxKey + 1) * sizeof(float));
    if (!weights) {
        fprintf(stderr, "Memory allocation failed for weights.\n");
        free(longOffsets);
        free(intKeys);
        free(records);
        return;
    }

    double *cumulativeSums = (double *)malloc((maxValue - minValue + 1) * sizeof(double));
    if (!cumulativeSums) {
        fprintf(stderr, "Memory allocation failed for cumulative sums.\n");
        free(longOffsets);
        free(intKeys);
        free(records);
        free(weights);
        return;
    }

    // Initialize data structures with random values
    for (int i = 0; i <= maxKey; ++i) {
        longOffsets[i] = i * 10L;
        intKeys[i] = rand() % (maxKey + 1);
        weights[i] = ((float)rand()) / RAND_MAX;
    }

    // Normalize weights
    float sumWeights = 0.0f;
    for (int i = 0; i <= maxKey; ++i) {
        sumWeights += weights[i];
    }
    for (int i = 0; i <= maxKey; ++i) {
        weights[i] /= sumWeights;
    }

    // Initialize records with random values within the given range
    int lastValue = minValue - 1;
    for (int i = minValue; i <= maxValue; ++i) {
        do {
            records[i - minValue].value = rand() % (maxValue + 1);
        } while (records[i - minValue].value == lastValue);
        lastValue = records[i - minValue].value;
        cumulativeSums[i - minValue] = 0.0;
    }

    // Read integers from standard input and store them in an auxiliary array
    int *auxArray = NULL;
    int auxSize = 0;
    int input;
    while (scanf("%d", &input) == 1) {
        auxArray = realloc(auxArray, (auxSize + 1) * sizeof(int));
        if (!auxArray) {
            fprintf(stderr, "Memory allocation failed for auxiliary array.\n");
            free(longOffsets);
            free(intKeys);
            free(records);
            free(weights);
            free(cumulativeSums);
            return;
        }
        auxArray[auxSize++] = input;
    }

    // Find and print the largest integer in the auxiliary array
    int maxInt = auxArray[0];
    for (int i = 1; i < auxSize; ++i) {
        if (auxArray[i] > maxInt) {
            maxInt = auxArray[i];
        }
    }
    printf("Largest integer: %d\n", maxInt);

    // Calculate and print the weighted average of the integers in the auxiliary array
    double weightedSum = 0.0;
    for (int i = 0; i < auxSize; ++i) {
        int index = abs(auxArray[i] - minValue);
        if (index >= 0 && index <= maxValue - minValue) {
            weightedSum += records[index].value * weights[index];
        }
    }
    printf("Weighted average: %.2f\n", weightedSum);

    // Free all allocated memory
    free(longOffsets);
    free(intKeys);
    free(records);
    free(weights);
    free(cumulativeSums);
    if (auxArray) {
        free(auxArray);
    }
}
