#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 1024

typedef struct {
    int value;
    char buffer[256];
} record;

int initialize_data(long **offsets, int **keys, record **records, int num_records) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Number of records exceeds maximum limit.\n");
        return -1;
    }

    *offsets = malloc(num_records * sizeof(long));
    *keys = malloc(num_records * sizeof(int));
    *records = malloc(num_records * sizeof(record));

    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    for (int i = 0; i < num_records; i++) {
        (*offsets)[i] = 0;
        (*keys)[i] = i;
        (*records)[i].value = 0;
        memset((*records)[i].buffer, 0, sizeof((*records)[i].buffer));
    }

    return 0;
}

int resize_records(record **records, int *num_records) {
    int new_size = *num_records * 2;
    record *new_records = realloc(*records, new_size * sizeof(record));

    if (!new_records) {
        fprintf(stderr, "Error: Memory reallocation failed.\n");
        return -1;
    }

    for (int i = *num_records; i < new_size; i++) {
        new_records[i].value = 0;
        memset(new_records[i].buffer, 0, sizeof(new_records[i].buffer));
    }

    *records = new_records;
    *num_records = new_size;

    return 0;
}

void free_data(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}
