    MemoryPoolManager* manager = (MemoryPoolManager*)malloc(sizeof(MemoryPoolManager));
    if (!manager) return NULL;

    manager->pool = (ResourceAllocationRequest**)malloc(initialSize * sizeof(ResourceAllocationRequest*));
    if (!manager->pool) {
        free(manager);
        return NULL;
    }

    manager->poolSize = initialSize;
    manager->usedCount = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroyMemoryPool(MemoryPoolManager* manager) {
    for (size_t i = 0; i < manager->usedCount; ++i) {
        free(manager->pool[i]->dataChunk);
        free(manager->pool[i]);
    }
    free(manager->pool);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

ResourceAllocationRequest* allocateFromPool(MemoryPoolManager* manager, int requestId, const char* resourceType, size_t dataSize) {
    pthread_mutex_lock(&manager->lock);

    if (manager->usedCount >= manager->poolSize) {
        // Resize pool
        ResourceAllocationRequest** newPool = (ResourceAllocationRequest**)realloc(manager->pool, manager->poolSize * 2 * sizeof(ResourceAllocationRequest*));
        if (!newPool) {
            pthread_mutex_unlock(&manager->lock);
            return NULL;
        }
        manager->pool = newPool;
        manager->poolSize *= 2;
    }

    ResourceAllocationRequest* request = (ResourceAllocationRequest*)malloc(sizeof(ResourceAllocationRequest));
    if (!request) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    request->requestId = requestId;
    request->profile.resourceType = strdup(resourceType);
    request->dataChunk = (unsigned char*)malloc(dataSize * sizeof(unsigned char));
    if (!request->dataChunk) {
        free(request);
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    request->dataSize = dataSize;
    manager->pool[manager->usedCount++] = request;

    pthread_mutex_unlock(&manager->lock);
    return request;
}

void deallocateToPool(MemoryPoolManager* manager, ResourceAllocationRequest* request) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->usedCount; ++i) {
        if (manager->pool[i] == request) {
            free(request->dataChunk);
            free(request->profile.resourceType);
            free(request);
            manager->pool[i] = manager->pool[--manager->usedCount];
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    MemoryPoolManager* poolManager = createMemoryPool(10);
    if (!poolManager) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

    ResourceAllocationRequest* request = allocateFromPool(poolManager, 1, "CPU", 1024);
    if (request) {
        printf("Allocated resource with ID %d and type %s\n", request->requestId, request->profile.resourceType);
        deallocateToPool(poolManager, request);
    } else {
        fprintf(stderr, "Failed to allocate resource\n");
    }

    destroyMemoryPool(poolManager);
    return 0;
}
