#include <pthread.h>

typedef struct {
    double value;
} TemperatureReading;

typedef struct {
    char *log;
} SensorLog;

typedef struct {
    int id;
    double calibration_factor;
} CalibrationMetadata;

typedef struct {
    TemperatureReading *temperatures;
    SensorLog *logs;
    CalibrationMetadata *metadata;
    size_t count;
    pthread_mutex_t lock;
} DataStore;

DataStore* create_data_store(size_t initial_size) {
    DataStore *store = (DataStore*)malloc(sizeof(DataStore));
    if (!store) return NULL;

    store->temperatures = (TemperatureReading*)calloc(initial_size, sizeof(TemperatureReading));
    store->logs = (SensorLog*)calloc(initial_size, sizeof(SensorLog));
    store->metadata = (CalibrationMetadata*)calloc(initial_size, sizeof(CalibrationMetadata));
    if (!store->temperatures || !store->logs || !store->metadata) {
        free(store);
        return NULL;
    }

    store->count = initial_size;
    pthread_mutex_init(&store->lock, NULL);

    return store;
}

void destroy_data_store(DataStore *store) {
    for (size_t i = 0; i < store->count; ++i) {
        free(store->logs[i].log);
    }
    free(store->temperatures);
    free(store->logs);
    free(store->metadata);
    pthread_mutex_destroy(&store->lock);
    free(store);
}

int add_temperature(DataStore *store, double value) {
    pthread_mutex_lock(&store->lock);
    if (store->count == 0) {
        pthread_mutex_unlock(&store->lock);
        return -1; // Store is empty
    }
    store->temperatures[store->count - 1].value = value;
    pthread_mutex_unlock(&store->lock);
    return 0;
}

int add_sensor_log(DataStore *store, const char *log) {
    pthread_mutex_lock(&store->lock);
    if (store->count == 0) {
        pthread_mutex_unlock(&store->lock);
        return -1; // Store is empty
    }
    store->logs[store->count - 1].log = strdup(log);
    if (!store->logs[store->count - 1].log) {
        pthread_mutex_unlock(&store->lock);
        return -1; // Memory allocation failed
    }
    pthread_mutex_unlock(&store->lock);
    return 0;
}

int add_calibration_metadata(DataStore *store, int id, double calibration_factor) {
    pthread_mutex_lock(&store->lock);
    if (store->count == 0) {
        pthread_mutex_unlock(&store->lock);
        return -1; // Store is empty
    }
    store->metadata[store->count - 1].id = id;
    store->metadata[store->count - 1].calibration_factor = calibration_factor;
    pthread_mutex_unlock(&store->lock);
    return 0;
}
