typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *indicators;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} CRC_Indication_Pool;

CRC_Indication_Pool* create_crc_indication_pool(size_t initial_size) {
    CRC_Indication_Pool *pool = (CRC_Indication_Pool*)malloc(sizeof(CRC_Indication_Pool));
    pool->indicators = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->allocated_size = initial_size;
    pool->used_size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_crc_indication_pool(CRC_Indication_Pool *pool) {
    free(pool->indicators);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_crc_indication(CRC_Indication_Pool *pool, int rnti, const char *rx_ue_information_tag, int crc_flag) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_size >= pool->allocated_size) {
        size_t new_size = pool->allocated_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_indicators = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->indicators, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_indicators) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Allocation failed
        }
        pool->indicators = new_indicators;
        pool->allocated_size = new_size;
    }

    NFAPI_CRC_INDICATION_PDU_T *indicator = &pool->indicators[pool->used_size];
    indicator->rnti = rnti;
    strncpy(indicator->rx_ue_information_tag, rx_ue_information_tag, MAX_STRING_LENGTH);
    indicator->crc_flag = crc_flag;

    pool->used_size++;
    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

