typedef struct {
    double temperature;
    char* serial_number;
    int status_flag;
} data_entry;

void process_sensor_data(int num_entries, double* sensor_readings, char** serial_numbers) {
    if (num_entries <= 0 || !sensor_readings || !serial_numbers) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    // Allocate memory for arrays
    double* double_array = (double*)malloc(num_entries * sizeof(double));
    char** char_array = (char**)malloc(num_entries * sizeof(char*));
    data_entry* struct_array = (data_entry*)malloc(num_entries * sizeof(data_entry));

    if (!double_array || !char_array || !struct_array) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(double_array);
        free(char_array);
        free(struct_array);
        return;
    }

    // Populate arrays with sensor data
    for (int i = 0; i < num_entries; ++i) {
        if (sensor_readings[i] != -999.0 && serial_numbers[i]) { // Assuming -999.0 is an invalid reading
            double_array[i] = sensor_readings[i];
            char_array[i] = strdup(serial_numbers[i]);
            struct_array[i].temperature = sensor_readings[i];
            struct_array[i].serial_number = strdup(serial_numbers[i]);
            struct_array[i].status_flag = (sensor_readings[i] > 100.0) ? 1 : ((sensor_readings[i] < -50.0) ? -1 : 0);
        } else {
            fprintf(stderr, "Invalid sensor reading at index %d.\n", i);
        }
    }

    // Example usage of the arrays
    for (int i = 0; i < num_entries; ++i) {
        if (char_array[i]) {
            printf("Temperature: %.2f, Serial Number: %s, Status Flag: %d\n",
                   struct_array[i].temperature, char_array[i], struct_array[i].status_flag);
            free(char_array[i]);
        }
    }

    // Free allocated memory
    free(double_array);
    free(char_array);
    for (int i = 0; i < num_entries; ++i) {
        if (struct_array[i].serial_number) {
            free(struct_array[i].serial_number);
        }
    }
    free(struct_array);
}

int main() {
    double sensor_readings[] = {23.5, -999.0, 150.0, -40.0};
    char* serial_numbers[] = {"S123", "S456", NULL, "S789"};

    process_sensor_data(4, sensor_readings, serial_numbers);

    return 0;
}
