#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct data_chunk {
    unsigned char buffer[1024];
    int ref_count;
} data_chunk;

typedef struct record {
    int key;
    char* string_buffer;
    data_chunk* chunk;
} record;

typedef struct metadata {
    size_t total_chunk_size;
    double average_string_length;
} metadata;

record* create_record(int key, const char* str) {
    record* rec = (record*)malloc(sizeof(record));
    if (!rec) return NULL;

    rec->key = key;
    rec->string_buffer = strdup(str);
    if (!rec->string_buffer) {
        free(rec);
        return NULL;
    }

    rec->chunk = (data_chunk*)malloc(sizeof(data_chunk));
    if (!rec->chunk) {
        free(rec->string_buffer);
        free(rec);
        return NULL;
    }
    memset(rec->chunk->buffer, 0, sizeof(rec->chunk->buffer));
    rec->chunk->ref_count = 1;

    return rec;
}

void destroy_record(record* rec) {
    if (rec) {
        free(rec->string_buffer);
        if (--rec->chunk->ref_count == 0) {
            free(rec->chunk);
        }
        free(rec);
    }
}

record** resize_records(record** records, int* capacity) {
    *capacity *= GROWTH_FACTOR;
    record** new_records = (record**)realloc(records, *capacity * sizeof(record*));
    if (!new_records) return NULL;
    return new_records;
}

int populate_pipeline(record** records, metadata* meta, int* size, int max_size) {
    srand(time(NULL));

    while (*size < max_size) {
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "Record %d", *size);

        record* rec = create_record(rand() % 1000, buffer);
        if (!rec) return -1;

        records[*size] = rec;
        (*size)++;

        meta->total_chunk_size += sizeof(data_chunk);
        meta->average_string_length = (meta->average_string_length * (*size - 1) + strlen(buffer)) / *size;
    }

    return 0;
}

void free_pipeline(record** records, int size) {
    for (int i = 0; i < size; i++) {
        destroy_record(records[i]);
    }
    free(records);
}

int main() {
    record** records = NULL;
    metadata meta = {0};
    int capacity = INITIAL_CAPACITY;
    int size = 0;

    if (populate_pipeline(&records, &meta, &size, 100) != 0) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    printf("Total chunk size: %zu\n", meta.total_chunk_size);
    printf("Average string length: %.2f\n", meta.average_string_length);

    free_pipeline(records, size);

    return 0;
}
