#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_SIZE 1024

typedef struct {
    int value;
    char buffer[256];
} record;

typedef struct {
    int key;
    size_t offset;
} index_map_entry;

typedef struct {
    index_map_entry *entries;
    size_t size;
    size_t capacity;
} index_map;

index_map* create_index_map() {
    index_map *map = (index_map*)malloc(sizeof(index_map));
    if (!map) return NULL;
    map->entries = (index_map_entry*)calloc(INITIAL_SIZE, sizeof(index_map_entry));
    if (!map->entries) {
        free(map);
        return NULL;
    }
    map->size = 0;
    map->capacity = INITIAL_SIZE;
    return map;
}

void destroy_index_map(index_map *map) {
    free(map->entries);
    free(map);
}

int insert_into_index_map(index_map *map, int key, size_t offset) {
    if (map->size >= map->capacity) {
        index_map_entry *new_entries = (index_map_entry*)realloc(map->entries, map->capacity * 2 * sizeof(index_map_entry));
        if (!new_entries) return -1;
        map->entries = new_entries;
        map->capacity *= 2;
    }
    map->entries[map->size].key = key;
    map->entries[map->size].offset = offset;
    map->size++;
    return 0;
}

size_t find_in_index_map(index_map *map, int key) {
    for (size_t i = 0; i < map->size; i++) {
        if (map->entries[i].key == key) return map->entries[i].offset;
    }
    return -1;
}

record* create_records(size_t count) {
    record *records = (record*)malloc(count * sizeof(record));
    if (!records) return NULL;
    for (size_t i = 0; i < count; i++) {
        records[i].value = 0;
        memset(records[i].buffer, 0, sizeof(records[i].buffer));
    }
    return records;
}

void destroy_records(record *records, size_t count) {
    free(records);
}

int main() {
    index_map *map = create_index_map();
    if (!map) {
        fprintf(stderr, "Failed to create index map\n");
        return 1;
    }

    record *records = create_records(1000);
    if (!records) {
        fprintf(stderr, "Failed to create records\n");
        destroy_index_map(map);
        return 1;
    }

    for (size_t i = 0; i < 1000; i++) {
        insert_into_index_map(map, i, i * sizeof(record));
        snprintf(records[i].buffer, sizeof(records[i].buffer), "Record %zu", i);
    }

    size_t offset = find_in_index_map(map, 500);
    if (offset != -1) {
        printf("Found record at offset: %zu\n", offset);
        printf("Value: %d\n", records[offset / sizeof(record)].value);
        printf("Buffer: %s\n", records[offset / sizeof(record)].buffer);
    } else {
        printf("Record not found\n");
    }

    destroy_records(records, 1000);
    destroy_index_map(map);

    return 0;
}
