    private readonly ILogger _logger;

    public ConfigDecryptor(ILogger logger)
    {
        _logger = logger;
    }

    public void LoadFromDisk(string filePath, byte[] key, byte[] iv)
    {
        using (var reader = new StreamReader(filePath))
        {
            LoadFromStream(reader.BaseStream, key, iv);
        }
    }

