    private void LoadFromStream(Stream stream, byte[] key, byte[] iv)
    {
        using (var reader = new StreamReader(stream))
        {
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                if (line.StartsWith("[") && line.EndsWith("]"))
                {
                    var sectionName = line.Trim('[', ']');
                    var encryptedData = reader.ReadLine();
                    try
                    {
                        var decryptedMessage = Decrypt(encryptedData, key, iv);
                        _decryptedSections[sectionName] = decryptedMessage;
                        _logger.Log($"Decrypted section: {sectionName}");
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError($"Failed to decrypt section {sectionName}: {ex.Message}");
                    }
                }
            }
        }
    }

    public string GetSection(string sectionName, byte[] key, byte[] iv)
    {
        if (_decryptedSections.TryGetValue(sectionName, out var decryptedMessage))
        {
            return decryptedMessage;
        }

        try
        {
            var encryptedData = LoadEncryptedDataFromSource(sectionName);
            var decryptedMessage = Decrypt(encryptedData, key, iv);
            _decryptedSections[sectionName] = decryptedMessage;
            _logger.Log($"Decrypted section: {sectionName}");
            return decryptedMessage;
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to decrypt section {sectionName}: {ex.Message}");
            throw;
        }
    }

    private string LoadEncryptedDataFromSource(string sectionName)
    {
        // Implement logic to load encrypted data from disk or in-memory source
        throw new NotImplementedException();
    }

    private string Decrypt(string base64EncodedData, byte[] key, byte[] iv)
    {
        if (key.Length != 24 || iv.Length != 8)
            throw new ArgumentException("Invalid key or IV length");

        using (var ms = new MemoryStream(Convert.FromBase64String(base64EncodedData)))
        using (var decryptor = TripleDES.Create().CreateDecryptor(key, iv))
        using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
        {
            using (var reader = new StreamReader(cs))
                return reader.ReadToEnd();
        }
    }
}

