#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MAX_VALUE_RANGE 100

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int count;
    int successful_allocations;
    int failed_allocations;
    size_t total_memory_usage;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool;

void init_pool() {
    pool.count = 0;
    pool.successful_allocations = 0;
    pool.failed_allocations = 0;
    pool.total_memory_usage = 0;
    pthread_mutex_init(&pool.lock, NULL);
}

int allocate_record(int key, int value) {
    pthread_mutex_lock(&pool.lock);
    if (pool.count >= MAX_RECORDS || pool.total_memory_usage + sizeof(Record) > MAX_MEMORY_SIZE) {
        pool.failed_allocations++;
        pthread_mutex_unlock(&pool.lock);
        return -1;
    }
    Record *record = &pool.records[pool.count++];
    record->offset = time(NULL);
    record->key = key;
    record->value = value;
    pool.total_memory_usage += sizeof(Record);
    pool.successful_allocations++;
    pthread_mutex_unlock(&pool.lock);
    return 0;
}

void set_random_values() {
    srand(time(NULL));
    for (int i = 0; i < pool.count; i++) {
        pool.records[i].value = rand() % MAX_VALUE_RANGE;
    }
}

void log_performance() {
    printf("Successful allocations: %d\n", pool.successful_allocations);
    printf("Failed allocations: %d\n", pool.failed_allocations);
    printf("Total memory usage: %zu bytes\n", pool.total_memory_usage);
}

int main() {
    init_pool();
    for (int i = 0; i < MAX_RECORDS; i++) {
        allocate_record(i, i * 10);
    }
    set_random_values();
    log_performance();
    return 0;
}
