    if (!set) return NULL;

    set->doubles = (double*)calloc(MAX_ELEMENTS, sizeof(double));
    set->strings = (char**)calloc(MAX_ELEMENTS, sizeof(char*));
    set->data = (Data*)calloc(MAX_ELEMENTS, sizeof(Data));
