    if (!set->doubles || !set->strings || !set->data) {
        free(set);
        return NULL;
    }

    return set;
}

void destroy_measurement_set(MeasurementSet* set) {
    for (int i = 0; i < set->count; i++) {
        free(set->strings[i]);
    }
    free(set->doubles);
    free(set->strings);
    free(set->data);
    pthread_mutex_destroy(&set->lock);
    free(set);
}

void add_measurement(MeasurementSet* set, double value, const char* str) {
    pthread_mutex_lock(&set->lock);
    if (set->count >= MAX_ELEMENTS) {
