typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* nfaapi_crc_list_init(size_t initial_capacity) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void nfaapi_crc_list_add(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        list->elements = realloc(list->elements, 2 * list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->capacity *= 2;
    }
    list->elements[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);
}

void nfaapi_crc_list_remove(NFAPI_CRC_LIST_T *list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index < list->size) {
        for (size_t i = index; i < list->size - 1; ++i) {
            list->elements[i] = list->elements[i + 1];
        }
        --list->size;
    }
    pthread_mutex_unlock(&list->lock);
}

void nfaapi_crc_list_free(NFAPI_CRC_LIST_T *list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
