    SensorLog *sensor_log;
    CalibrationMetadata *calibration_metadata;
    size_t count;
    pthread_mutex_t mutex;
} DataStore;

DataStore* create_data_store(size_t initial_size) {
    DataStore *store = (DataStore*)malloc(sizeof(DataStore));
    if (!store) return NULL;

    store->temperature_data = (TemperatureData*)calloc(initial_size, sizeof(TemperatureData));
    store->sensor_log = (SensorLog*)calloc(initial_size, sizeof(SensorLog));
    store->calibration_metadata = (CalibrationMetadata*)calloc(initial_size, sizeof(CalibrationMetadata));
    if (!store->temperature_data || !store->sensor_log || !store->calibration_metadata) {
        free(store);
        return NULL;
    }

    store->count = initial_size;
    pthread_mutex_init(&store->mutex, NULL);
    return store;
}

void destroy_data_store(DataStore *store) {
    if (store) {
        free(store->temperature_data);
        free(store->sensor_log);
        free(store->calibration_metadata);
        pthread_mutex_destroy(&store->mutex);
        free(store);
    }
}

int add_temperature(DataStore *store, double temperature) {
    pthread_mutex_lock(&store->mutex);
    if (store->count == 0) {
        pthread_mutex_unlock(&store->mutex);
        return -1; // No space left
    }
    store->temperature_data[store->count - 1].temperature = temperature;
    pthread_mutex_unlock(&store->mutex);
    return 0;
}

// Similar functions for sensor_log and calibration_metadata

int main() {
    DataStore *store = create_data_store(100);
    if (!store) {
        fprintf(stderr, "Failed to create data store\n");
        return 1;
    }

    add_temperature(store, 23.5);
    // Add other data entries

    destroy_data_store(store);
    return 0;
}
