#define MAX_MEMORY 1024 * 1024 // 1 MB
#define MAX_ATTRIBUTES 10

typedef struct Attribute {
    char name[50];
    char value[50];
} Attribute;

typedef struct Entry {
    char key[100];
    time_t timestamp;
    Attribute attributes[MAX_ATTRIBUTES];
} Entry;

Entry* createDatabaseTable(int n, int num_attributes) {
    static size_t total_memory_used = 0;
    if (total_memory_used + n * sizeof(Entry) > MAX_MEMORY) {
        fprintf(stderr, "Memory allocation exceeds maximum limit.\n");
        return NULL;
    }

    Entry* table = (Entry*)malloc(n * sizeof(Entry));
    if (!table) {
        fprintf(stderr, "Failed to allocate memory for database table.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < n; ++i) {
        // Generate unique key
        time_t now = time(NULL);
        int random_int = rand();
        unsigned long hash = 5381;
        char* attr_set = "attr_set"; // Placeholder for actual attribute set
        for (int j = 0; attr_set[j]; ++j) {
            hash = ((hash << 5) + hash) + attr_set[j];
        }
        snprintf(table[i].key, sizeof(table[i].key), "%ld_%d_%lu", now, random_int, hash);

        // Check for duplicate keys
        for (int j = 0; j < i; ++j) {
            if (strcmp(table[i].key, table[j].key) == 0) {
                int suffix = 1;
                while (1) {
                    snprintf(table[i].key, sizeof(table[i].key), "%ld_%d_%lu_%d", now, random_int, hash, suffix);
                    int is_duplicate = 0;
                    for (int k = 0; k < i; ++k) {
                        if (strcmp(table[i].key, table[k].key) == 0) {
                            is_duplicate = 1;
                            break;
                        }
                    }
                    if (!is_duplicate) break;
                    suffix++;
                }
            }
        }

        // Set timestamp
        table[i].timestamp = now;

        // Initialize attributes
        for (int j = 0; j < num_attributes; ++j) {
            snprintf(table[i].attributes[j].name, sizeof(table[i].attributes[j].name), "attr%d", j);
            snprintf(table[i].attributes[j].value, sizeof(table[i].attributes[j].value), "%d", rand() % 100);
        }
    }

    total_memory_used += n * sizeof(Entry);
    return table;
}

int main() {
    int n = 5;
    int num_attributes = 3;
    Entry* table = createDatabaseTable(n, num_attributes);
    if (table) {
        printf("Database table created successfully.\n");
        free(table);
    }
    return 0;
}
