#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_NODES 100

typedef struct {
    int nodeId;
    int bandwidth;
    int latency;
} ResourceAllocationPlan;

typedef struct {
    int nodeId;
    ResourceAllocationPlan plan;
    pthread_mutex_t lock;
} NetworkNodeStatus;

NetworkNodeStatus nodeStatus[MAX_NODES];

void initializeNodeStatus(int nodeId, int bandwidth, int latency) {
    if (nodeId < 0 || nodeId >= MAX_NODES) return;
    nodeStatus[nodeId].nodeId = nodeId;
    nodeStatus[nodeId].plan.bandwidth = bandwidth;
    nodeStatus[nodeId].plan.latency = latency;
    pthread_mutex_init(&nodeStatus[nodeId].lock, NULL);
}

void updateNodeStatus(int nodeId, int newBandwidth, int newLatency) {
    if (nodeId < 0 || nodeId >= MAX_NODES) return;
    pthread_mutex_lock(&nodeStatus[nodeId].lock);
    nodeStatus[nodeId].plan.bandwidth = newBandwidth;
    nodeStatus[nodeId].plan.latency = newLatency;
    pthread_mutex_unlock(&nodeStatus[nodeId].lock);
}

void validateAllocationPlan(int nodeId, int maxBandwidth, int maxLatency) {
    if (nodeId < 0 || nodeId >= MAX_NODES) return;
    pthread_mutex_lock(&nodeStatus[nodeId].lock);
    if (nodeStatus[nodeId].plan.bandwidth > maxBandwidth ||
        nodeStatus[nodeId].plan.latency > maxLatency) {
        printf("Allocation plan for node %d exceeds network throughput constraints.\n", nodeId);
    }
    pthread_mutex_unlock(&nodeStatus[nodeId].lock);
}

void* monitorNode(void* arg) {
    int nodeId = *(int*)arg;
    while (1) {
        // Simulate monitoring logic
        updateNodeStatus(nodeId, rand() % 100, rand() % 50);
        validateAllocationPlan(nodeId, 100, 50);
        sleep(1); // Simulate periodic monitoring
    }
    return NULL;
}

int main() {
    for (int i = 0; i < MAX_NODES; i++) {
        initializeNodeStatus(i, rand() % 100, rand() % 50);
    }

    pthread_t threads[MAX_NODES];
    int nodeIds[MAX_NODES];
    for (int i = 0; i < MAX_NODES; i++) {
        nodeIds[i] = i;
        pthread_create(&threads[i], NULL, monitorNode, &nodeIds[i]);
    }

    for (int i = 0; i < MAX_NODES; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
