typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    Node* free_list;
    pthread_mutex_t lock;
    int size;
} LRUList;

void initLRUList(LRUList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->free_list = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
}

Node* allocateNode() {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        // Handle memory allocation failure
    }
    return node;
}

void freeNode(Node* node) {
    free(node);
}

void addToFreeList(LRUList* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    node->next = list->free_list;
    list->free_list = node;
    pthread_mutex_unlock(&list->lock);
}

Node* getFromFreeList(LRUList* list) {
    Node* node = NULL;
    pthread_mutex_lock(&list->lock);
    if (list->free_list) {
        node = list->free_list;
        list->free_list = node->next;
    }
    pthread_mutex_unlock(&list->lock);
    return node;
}

void addToLRUList(LRUList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = getFromFreeList(list);
    if (!newNode) {
        newNode = allocateNode();
        if (!newNode) {
            // Handle memory allocation failure
        }
    }

    pthread_mutex_lock(&list->lock);
    newNode->data = data;
    newNode->prev = list->tail;
    newNode->next = NULL;

    if (list->tail) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;

    if (list->size >= LIST_CAPACITY) {
        Node* lruNode = list->head;
        list->head = list->head->next;
        if (list->head) {
            list->head->prev = NULL;
        } else {
            list->tail = NULL;
        }
        addToFreeList(list, lruNode);
    }

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T removeFromLRUList(LRUList* list) {
    NFAPI_CRC_INDICATION_PDU_T data;
    pthread_mutex_lock(&list->lock);
    if (list->tail) {
        Node* node = list->tail;
        data = node->data;
        list->tail = node->prev;
        if (list->tail) {
            list->tail->next = NULL;
        } else {
            list->head = NULL;
        }
        addToFreeList(list, node);
    } else {
        // Handle empty list case
    }
    pthread_mutex_unlock(&list->lock);
    return data;
}

