#define MAX_PATH_LENGTH 256

typedef struct node {
    int value;
    struct node* next;
    char* filePath;
} Node;

Node* create_node(int value, const char* filePath) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    newNode->value = value;
    newNode->next = NULL;
    newNode->filePath = strdup(filePath);
    if (!newNode->filePath) {
        free(newNode);
        fprintf(stderr, "Memory allocation failed for filePath\n");
        return NULL;
    }
    return newNode;
}

void free_node(Node* node) {
    if (node) {
        free(node->filePath);
        free(node);
    }
}

void free_nodes(Node* head) {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }
}

int transform_value(double cumulativeSum, double maxLimit) {
    return (int)(cumulativeSum * 100 / maxLimit); // Example transformation
}

Node* initialize_file_metadata(double maxCumulativeSum, int numFiles, const char* filePaths[]) {
    Node* head = NULL;
    Node** current = &head;

    for (int i = 0; i < numFiles; ++i) {
        double cumulativeSum = 1.0 + i * 1.0 / numFiles; // Example cumulative sum calculation
        if (cumulativeSum > maxCumulativeSum) break;

        int value = transform_value(cumulativeSum, maxCumulativeSum);
        Node* newNode = create_node(value, filePaths[i]);
        if (!newNode) {
            free_nodes(head);
            return NULL;
        }

        *current = newNode;
        current = &(*current)->next;
    }

    return head;
}

int main() {
    const char* file_paths[] = {"file1.txt", "file2.txt", "file3.txt"};
    int num_files = sizeof(file_paths) / sizeof(file_paths[0]);
    double max_cumulative_sum = 5.0;

    Node* metadata = initialize_file_metadata(max_cumulative_sum, num_files, file_paths);
    if (metadata) {
        // Use the metadata
        free_nodes(metadata);
    }

    return 0;
}
