#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    long offset;
    int key;
    struct record *data;
    char metadata[128];
    double timestamp;
} Record;

typedef struct node {
    Record *record;
    struct node *next;
} Node;

typedef struct hash_table {
    Node **buckets;
    size_t capacity;
    atomic_size_t count;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->capacity = initial_capacity;
    ht->count = 0;
    ht->buckets = (Node**)calloc(initial_capacity, sizeof(Node*));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        Node *node = ht->buckets[i];
        while (node != NULL) {
            Node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

void insert_record(HashTable *ht, Record *record) {
    pthread_mutex_lock(&ht->lock);
    size_t index = record->key % ht->capacity;
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->record = record;
    new_node->next = ht->buckets[index];
    ht->buckets[index] = new_node;
    atomic_fetch_add(&ht->count, 1);
    pthread_mutex_unlock(&ht->lock);
}

Record* find_record(HashTable *ht, int key) {
    size_t index = key % ht->capacity;
    Node *node = ht->buckets[index];
    while (node != NULL) {
        if (node->record->key == key) {
            return node->record;
        }
        node = node->next;
    }
    return NULL;
}

void delete_record(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = key % ht->capacity;
    Node **prev = &ht->buckets[index];
    while (*prev != NULL) {
        if ((*prev)->record->key == key) {
            Node *node = *prev;
            *prev = node->next;
            free(node);
            atomic_fetch_sub(&ht->count, 1);
            break;
        }
        prev = &(*prev)->next;
    }
    pthread_mutex_unlock(&ht->lock);
}

// Additional functions for pluggable storage backend, custom allocator, logging, and unit tests
