    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void initialize_packets(DataPacket *packets, int N) {
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        packets[i].packet_id = rand();
        snprintf(packets[i].source, sizeof(packets[i].source), "Source%d", rand() % 100);
        snprintf(packets[i].destination, sizeof(packets[i].destination), "Destination%d", rand() % 100);
        packets[i].payload_size = rand() % 1024;
    }
}

void initialize_crc_indications(NFAPI_CRC_INDICATION_PDU_T *crcs, int N) {
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        crcs[i].RX_UE_INFORMATION_TAG = rand();
        crcs[i].RNTI = rand() % 1024;
        crcs[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
}

int validate_rntis(NFAPI_CRC_INDICATION_PDU_T *crcs, int N) {
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (crcs[i].RNTI == crcs[j].RNTI) {
                FILE *log_file = fopen("rnti_log.txt", "a");
                fprintf(log_file, "Duplicate RNTI detected: %d\n", crcs[i].RNTI);
                fclose(log_file);
            }
        }
    }
    return 0;
}

int main() {
    int N = 500;
    DataPacket *packets = (DataPacket *)malloc(N * sizeof(DataPacket));
    if (!packets) {
        fprintf(stderr, "Memory allocation failed for packets\n");
        return 1;
    }

    initialize_packets(packets, N);

    NFAPI_CRC_INDICATION_PDU_T *crcs = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcs) {
        fprintf(stderr, "Memory allocation failed for crc indications\n");
        free(packets);
        return 1;
    }

    initialize_crc_indications(crcs, N);

    validate_rntis(crcs, N);

    free(packets);
    free(crcs);

    return 0;
}
