use reqwest::{Client, Error, Method, Url};
use std::fs::File;
use std::io::Write;
use tokio::time::{Duration, Instant};

#[derive(Debug)]
struct HttpClient {
    client: Client,
    timeout: Duration,
    retry_count: u32,
    disable_ssl_verification: bool,
    log_file_path: String,
}

impl HttpClient {
    fn new(timeout: Duration, retry_count: u32, disable_ssl_verification: bool, log_file_path: String) -> Self {
        let client = Client::builder()
            .timeout(timeout)
            .danger_accept_invalid_certs(disable_ssl_verification)
            .build()
            .unwrap();
        HttpClient {
            client,
            timeout,
            retry_count,
            disable_ssl_verification,
            log_file_path,
        }
    }

    async fn request(
        &self,
        method: Method,
        url: Url,
        headers: Option<header::HeaderMap>,
        body: Option<reqwest::Body>,
    ) -> Result<String, Error> {
        let mut response = self
            .client
            .request(method, url)
            .headers(headers.unwrap_or_default())
            .body(body)
            .send()
            .await?;

        if response.status().is_success() {
            let content_type = response.headers().get("content-type").unwrap();
            if content_type.to_str().unwrap().contains("application/json") {
                let json_response = response.json::<serde_json::Value>().await?;
                self.log_request_response(&method, &url, Some(json_response.to_string()));
                Ok(json_response.to_string())
            } else {
                let text_response = response.text().await?;
                self.log_request_response(&method, &url, Some(text_response.clone()));
                Ok(text_response)
            }
        } else {
            self.log_request_response(&method, &url, None);
            Err(Error::new(reqwest::ErrorKind::Other, "Request failed"))
        }
    }

    fn log_request_response(
        &self,
        method: &Method,
        url: &Url,
        response_body: Option<String>,
    ) {
        let mut file = File::options()
            .append(true)
            .create(true)
            .open(&self.log_file_path)
            .unwrap();
        let timestamp = Instant::now().to_string();
        let log_entry = format!(
            "{} - {} - {}\n",
            timestamp,
            method,
            url
        );
        if let Some(body) = response_body {
            file.write_all(log_entry.as_bytes()).unwrap();
            file.write_all(body.as_bytes()).unwrap();
        } else {
            file.write_all(log_entry.as_bytes()).unwrap();
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    let client = HttpClient::new(
        Duration::from_secs(10),
        3,
        true,
        "/path/to/logfile.log".to_string(),
    );

    let url = Url::parse("https://api.example.com/data")?;
    let response = client
        .request(Method::GET, url, None, None)
        .await?;

    println!("Response: {}", response);

    Ok(())
}
