#define MAX_FILENAME_LENGTH 256

typedef struct {
    int id;
    char filename[MAX_FILENAME_LENGTH];
    size_t size;
    time_t last_modified;
} FileMetadata;

typedef struct {
    FileMetadata *files;
    int count;
    int capacity;
    pthread_mutex_t lock;
} FileManager;

FileManager file_manager = {0};

void init_file_manager() {
    file_manager.capacity = 16;
    file_manager.files = (FileMetadata *)malloc(file_manager.capacity * sizeof(FileMetadata));
    pthread_mutex_init(&file_manager.lock, NULL);
}

void destroy_file_manager() {
    free(file_manager.files);
    pthread_mutex_destroy(&file_manager.lock);
}

int add_file(int id, const char *filename, size_t size) {
    pthread_mutex_lock(&file_manager.lock);
    if (id >= file_manager.capacity) {
        FileMetadata *new_files = (FileMetadata *)realloc(file_manager.files, (id + 1) * sizeof(FileMetadata));
        if (!new_files) {
            pthread_mutex_unlock(&file_manager.lock);
            return -1; // Memory allocation failed
        }
        file_manager.files = new_files;
        file_manager.capacity = id + 1;
    }

    for (int i = 0; i < file_manager.count; i++) {
        if (strcmp(file_manager.files[i].filename, filename) == 0) {
            pthread_mutex_unlock(&file_manager.lock);
            return -2; // Duplicate filename
        }
    }

    file_manager.files[file_manager.count].id = id;
    strncpy(file_manager.files[file_manager.count].filename, filename, MAX_FILENAME_LENGTH);
    file_manager.files[file_manager.count].size = size;
    file_manager.files[file_manager.count].last_modified = time(NULL);
    file_manager.count++;
    pthread_mutex_unlock(&file_manager.lock);
    return 0; // Success
}

int update_file_size(int id, size_t new_size) {
    pthread_mutex_lock(&file_manager.lock);
    for (int i = 0; i < file_manager.count; i++) {
        if (file_manager.files[i].id == id) {
            file_manager.files[i].size = new_size;
            file_manager.files[i].last_modified = time(NULL);
            pthread_mutex_unlock(&file_manager.lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&file_manager.lock);
    return -1; // File not found
}

void *metadata_monitor_thread(void *arg) {
    while (1) {
        // Simulate metadata update logic here
        sleep(60); // Update every minute
    }
    return NULL;
}

int main() {
    init_file_manager();
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, metadata_monitor_thread, NULL);

    add_file(1, "example.txt", 1024);
    update_file_size(1, 2048);

    destroy_file_manager();
    return 0;
}
