#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int packet_id;
    char source[50];
    char destination[50];
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} PacketArray;

void init_packet_array(PacketArray* array, size_t initial_capacity) {
    array->packets = (DataPacket*)malloc(initial_capacity * sizeof(DataPacket));
    if (!array->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void resize_packet_array(PacketArray* array, size_t new_capacity) {
    DataPacket* new_packets = (DataPacket*)realloc(array->packets, new_capacity * sizeof(DataPacket));
    if (!new_packets) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->packets = new_packets;
    array->capacity = new_capacity;
}

void add_packet(PacketArray* array, DataPacket packet) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        resize_packet_array(array, array->capacity * 2);
    }
    array->packets[array->size++] = packet;
    pthread_mutex_unlock(&array->mutex);
}

void free_packet_array(PacketArray* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->packets);
    array->packets = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

// Example usage
int main() {
    PacketArray packet_array;
    init_packet_array(&packet_array, 10);

    DataPacket new_packet = {1, "Source1", "Destination1", 1024};
    add_packet(&packet_array, new_packet);

    free_packet_array(&packet_array);
    return 0;
}
```

