#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_OFFSET 1024

typedef struct {
    long offset;
    int key;
} offset_key;

typedef struct {
    int value;
} record;

struct memory_pool {
    void* pool;
    size_t size;
    size_t used;
};

void init_memory_pool(struct memory_pool* pool, size_t size) {
    pool->pool = malloc(size);
    pool->size = size;
    pool->used = 0;
}

void* allocate_from_pool(struct memory_pool* pool, size_t size) {
    if (pool->used + size > pool->size) {
        return NULL; // Out of memory
    }
    void* ptr = (char*)pool->pool + pool->used;
    pool->used += size;
    return ptr;
}

void free_memory_pool(struct memory_pool* pool) {
    free(pool->pool);
    pool->pool = NULL;
    pool->size = 0;
    pool->used = 0;
}

int is_valid_offset(long offset) {
    return offset >= 0 && offset < MAX_OFFSET;
}

record* generate_random_record() {
    record* rec = (record*)malloc(sizeof(record));
    rec->value = rand() % 201 - 100; // Random value between -100 and 100
    return rec;
}

void dataProcessingEngine(int n, struct memory_pool* pool) {
    if (n <= 0) {
        fprintf(stderr, "Invalid number of elements: %d\n", n);
        return;
    }

    offset_key* keys = allocate_from_pool(pool, n * sizeof(offset_key));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        return;
    }

    record** records = allocate_from_pool(pool, n * sizeof(record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(keys);
        return;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < n; i++) {
        long offset = rand() % MAX_OFFSET;
        if (!is_valid_offset(offset)) {
            fprintf(stderr, "Invalid offset: %ld\n", offset);
            continue;
        }
        keys[i].offset = offset;
        keys[i].key = i;

        records[i] = generate_random_record();
    }

    // Process the data...

    for (int i = 0; i < n; i++) {
        free(records[i]);
    }

    free(keys);
}

int main() {
    struct memory_pool pool;
    init_memory_pool(&pool, 1024 * 1024); // 1MB initial pool size

    dataProcessingEngine(1000, &pool);

    free_memory_pool(&pool);

    return 0;
}
