    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} record_manager_t;

record_manager_t* create_record_manager(size_t initial_capacity) {
    record_manager_t *manager = (record_manager_t*)malloc(sizeof(record_manager_t));
    manager->records = (record_t*)calloc(initial_capacity, sizeof(record_t));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_record_manager(record_manager_t *manager) {
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_record(record_manager_t *manager, offset_t off, key_t key, const char *data, size_t data_size) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size == manager->capacity) {
        // Grow the array
        record_t *new_records = (record_t*)realloc(manager->records, manager->capacity * 2 * sizeof(record_t));
        if (new_records == NULL) {
            // Handle allocation failure
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->records = new_records;
        manager->capacity *= 2;
    }
    record_t *record = &manager->records[manager->size++];
    record->off = off;
    record->key = key;
    memcpy(record->data, data, data_size < sizeof(record->data) ? data_size : sizeof(record->data));
    pthread_mutex_unlock(&manager->lock);
}

