void init_mac_transport_channel_array(MAC_TransportChannelArray *array) {
    array->channels = (MAC_TransportChannelInfo *)malloc(MAX_CHANNELS * sizeof(MAC_TransportChannelInfo));
    if (!array->channels) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = MAX_CHANNELS;
    pthread_mutex_init(&array->lock, NULL);
}

void destroy_mac_transport_channel_array(MAC_TransportChannelArray *array) {
    free(array->channels);
    pthread_mutex_destroy(&array->lock);
}

int add_mac_transport_channel(MAC_TransportChannelArray *array, int rnti, TransportChannelConfig config) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        MAC_TransportChannelInfo *new_channels = (MAC_TransportChannelInfo *)realloc(array->channels, new_capacity * sizeof(MAC_TransportChannelInfo));
        if (!new_channels) {
            pthread_mutex_unlock(&array->lock);
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }
        array->channels = new_channels;
        array->capacity = new_capacity;
    }
    array->channels[array->count].rnti = rnti;
    array->channels[array->count].config = config;
    array->count++;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_mac_transport_channel(MAC_TransportChannelArray *array, int rnti, TransportChannelConfig new_config) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; i++) {
        if (array->channels[i].rnti == rnti) {
            array->channels[i].config = new_config;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1;
}
