typedef enum { PENDING, IN_PROGRESS, COMPLETED } TaskStatus;

typedef struct {
    int id;
    TaskStatus status;
    void* data;
} Task;

typedef struct {
    time_t timestamp;
    char summary[256];
} Report;

void updateTaskData(Task* task) {
    // Simulate fetching data from an external source
    static int counter = 0;
    task->data = (void*)counter++;
}

Report* createReport() {
    Report* report = (Report*)malloc(sizeof(Report));
    if (!report) return NULL;
    time_t now = time(NULL);
    report->timestamp = now;
    snprintf(report->summary, sizeof(report->summary), "Task completed at %s", ctime(&now));
    return report;
}

void freeReports(Report** reports, int count) {
    for (int i = 0; i < count; ++i) {
        if (reports[i]) {
            free(reports[i]);
            reports[i] = NULL;
        }
    }
}

void processTasks(Task* tasks, Report** results, int taskCount, int reportCount) {
    for (int i = 0; i < taskCount; ++i) {
        updateTaskData(&tasks[i]);
        if (results[i]) {
            free(results[i]);
        }
        results[i] = createReport();
        if (!results[i]) {
            fprintf(stderr, "Failed to allocate memory for report.\n");
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup(Task* tasks, Report** results, int taskCount) {
    for (int i = 0; i < taskCount; ++i) {
        free(tasks[i].data);
        if (results[i]) {
            free(results[i]);
        }
    }
    free(tasks);
    free(results);
}

int main() {
    const int taskCount = 10;
    const int reportCount = taskCount;

    Task* tasks = (Task*)malloc(taskCount * sizeof(Task));
    Report** results = (Report**)calloc(reportCount, sizeof(Report*));

    if (!tasks || !results) {
        fprintf(stderr, "Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < taskCount; ++i) {
        tasks[i].id = i;
        tasks[i].status = PENDING;
        tasks[i].data = NULL;
    }

    processTasks(tasks, results, taskCount, reportCount);

    // Simulate periodic updates
    for (int i = 0; i < 10; ++i) {
        processTasks(tasks, results, taskCount, reportCount);
        sleep(300); // Sleep for 5 minutes
    }

    cleanup(tasks, results, taskCount);

    return 0;
}
