import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.JsonProcessingException;

public class ConfigProcessor {

    private static final ObjectMapper objectMapper = new ObjectMapper();

    public static <T> T processJson(String json, Class<T> clazz) {
        try {
            return objectMapper.readValue(json, clazz);
        } catch (JsonProcessingException e) {
            handleDeserializationError(e, json, clazz);
            return createDefaultInstance(clazz);
        }
    }

    private static <T> void handleDeserializationError(JsonProcessingException e, String json, Class<T> clazz) {
        // Log detailed error information for debugging
        System.err.println("Failed to deserialize JSON: " + json);
        e.printStackTrace();
    }

    @SuppressWarnings("unchecked")
    private static <T> T createDefaultInstance(Class<T> clazz) {
        try {
            return (T) clazz.getDeclaredConstructor().newInstance();
        } catch (Exception e) {
            // Fallback to a minimal configuration instance
            System.err.println("Failed to create default instance of " + clazz.getName());
            return null;
        }
    }

    public static void main(String[] args) {
        String json = "{\"name\":\"default\", \"version\":1}";
        MyConfig config = processJson(json, MyConfig.class);
        if (config != null) {
            System.out.println("Configuration loaded: " + config);
        } else {
            System.out.println("Failed to load configuration.");
        }
    }
}

class MyConfig {
    private String name;
    private int version;

    // Getters and setters

    @Override
    public String toString() {
        return "MyConfig{" +
                "name='" + name + '\'' +
                ", version=" + version +
                '}';
    }
}
