typedef unsigned long offset_t;
typedef int key_t;

typedef struct {
    offset_t offset;
    key_t key;
    char data[];
} record_t;

typedef struct {
    record_t **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} record_storage_t;

record_storage_t *create_record_storage(size_t initial_capacity) {
    record_storage_t *storage = malloc(sizeof(record_storage_t));
    storage->records = calloc(initial_capacity, sizeof(record_t *));
    storage->capacity = initial_capacity;
    storage->size = 0;
    pthread_mutex_init(&storage->lock, NULL);
    return storage;
}

void destroy_record_storage(record_storage_t *storage) {
    for (size_t i = 0; i < storage->size; ++i) {
        free(storage->records[i]);
    }
    free(storage->records);
    pthread_mutex_destroy(&storage->lock);
    free(storage);
}

record_t *create_record(key_t key, size_t data_size) {
    record_t *record = malloc(sizeof(record_t) + data_size);
    record->offset = (offset_t)((char *)record - (char *)NULL); // Simplified for example
    record->key = key;
    memset(record->data, 0, data_size);
    return record;
}

void insert_record(record_storage_t *storage, record_t *record) {
    pthread_mutex_lock(&storage->lock);
    if (storage->size == storage->capacity) {
        size_t new_capacity = storage->capacity ? storage->capacity * 2 : 16;
        record_t **new_records = realloc(storage->records, new_capacity * sizeof(record_t *));
        if (!new_records) {
            pthread_mutex_unlock(&storage->lock);
            return; // Handle error
        }
        storage->records = new_records;
        storage->capacity = new_capacity;
    }
    storage->records[storage->size++] = record;
    pthread_mutex_unlock(&storage->lock);
}

record_t *find_record(record_storage_t *storage, key_t key) {
    for (size_t i = 0; i < storage->size; ++i) {
        if (storage->records[i]->key == key) {
            return storage->records[i];
        }
    }
    return NULL;
}

void free_records(record_storage_t *storage) {
    pthread_mutex_lock(&storage->lock);
    for (size_t i = 0; i < storage->size; ++i) {
        free(storage->records[i]);
    }
    pthread_mutex_unlock(&storage->lock);
}
