#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef enum {
    ESTABLISHED,
    DISCONNECTED,
    PENDING
} ConnectionStatus;

typedef struct {
    int timestamp;
    char network_id[50];
    ConnectionStatus status;
} NetworkStats;

typedef struct {
    NetworkStats *stats;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NetworkStatsManager;

NetworkStatsManager* create_manager() {
    NetworkStatsManager *manager = (NetworkStatsManager*)malloc(sizeof(NetworkStatsManager));
    if (!manager) return NULL;
    manager->stats = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_manager(NetworkStatsManager *manager) {
    if (manager->stats) free(manager->stats);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_or_update_stats(NetworkStatsManager *manager, NetworkStats new_stat) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        NetworkStats *new_stats = realloc(manager->stats, new_capacity * sizeof(NetworkStats));
        if (!new_stats) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->stats = new_stats;
        manager->capacity = new_capacity;
    }
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->stats[i].network_id, new_stat.network_id) == 0) {
            manager->stats[i] = new_stat;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Updated existing entry
        }
    }
    manager->stats[manager->count++] = new_stat;
    pthread_mutex_unlock(&manager->lock);
    return 1; // Added new entry
}

int get_total_connections(NetworkStatsManager *manager) {
    int total = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        switch (manager->stats[i].status) {
            case ESTABLISHED:
                total++;
                break;
            default:
                break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return total;
}
```

