#define MAX_FILENAME_LENGTH 256

int modify_filename(char *filename, const char *directory_path) {
    // Calculate the number of digits based on directory path length
    int num_digits = strlen(directory_path);

    // Construct new filename with modified extension
    char new_filename[MAX_FILENAME_LENGTH];
    sprintf(new_filename, "%s.%d", filename, num_digits);

    // Check for uniqueness in the specified directory
    DIR *dir;
    struct dirent *entry;
    dir = opendir(directory_path);
    if (dir == NULL) {
        perror("opendir");
        return -1; // Error opening directory
    }

    int unique = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, new_filename) == 0) {
            unique = 0;
            break;
        }
        unique = 1;
    }
    closedir(dir);

    // Append sequential number until uniqueness is achieved
    int count = 1;
    while (!unique) {
        sprintf(new_filename, "%s.%d_%d", filename, num_digits, count);
        dir = opendir(directory_path);
        if (dir == NULL) {
            perror("opendir");
            return -1; // Error opening directory
        }
        unique = 1;
        while ((entry = readdir(dir)) != NULL) {
            if (strcmp(entry->d_name, new_filename) == 0) {
                unique = 0;
                break;
            }
        }
        closedir(dir);
        count++;
    }

    // Copy the new filename to the original buffer
    strncpy(filename, new_filename, MAX_FILENAME_LENGTH);

    return 0; // Success
}
