#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    int priority;
    time_t timestamp;
    struct record *next;
    struct record *prev;
} Record;

Record* create_record(int value, int priority) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_record->value = value;
    new_record->priority = priority;
    new_record->timestamp = time(NULL) + rand() % 60 - 30; // Random timestamp within ±5 minutes
    new_record->next = NULL;
    new_record->prev = NULL;
    return new_record;
}

void insert_record(Record** head, Record* new_record) {
    if (*head == NULL) {
        *head = new_record;
    } else {
        Record* current = *head;
        while (current->next != NULL && current->priority >= new_record->priority) {
            current = current->next;
        }
        if (current->next != NULL) {
            current->next->prev = new_record;
        }
        new_record->next = current->next;
        new_record->prev = current;
        current->next = new_record;
    }
}

void free_records(Record** head) {
    Record* current = *head;
    while (current != NULL) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    srand(time(NULL));

    long offsets[5] = {0, 1024, 2048, 3072, 4096};
    int keys[5] = {1, 2, 3, 4, 5};
    Record* records[5];

    for (int i = 0; i < 5; i++) {
        records[i] = create_record(rand() % 100 + 1, rand() % 5 + 1);
        insert_record(&records[i], records[i]);
    }

    // Demonstrate freeing all allocated memory
    for (int i = 0; i < 5; i++) {
        free_records(&records[i]);
    }

    return 0;
}
