typedef struct {
    int key;
    long offset;
    int value;
    time_t timestamp;
    int priority;
} Record;

typedef struct {
    Record *records;
    int size;
    int capacity;
    pthread_mutex_t lock;
} Dataset;

Dataset* create_dataset(int initial_capacity) {
    Dataset *dataset = (Dataset*)malloc(sizeof(Dataset));
    dataset->records = (Record*)calloc(initial_capacity, sizeof(Record));
    dataset->size = 0;
    dataset->capacity = initial_capacity;
    pthread_mutex_init(&dataset->lock, NULL);
    return dataset;
}

void add_record(Dataset *dataset, int key, int value, int priority) {
    pthread_mutex_lock(&dataset->lock);
    if (dataset->size >= dataset->capacity) {
        dataset->capacity *= 2;
        dataset->records = (Record*)realloc(dataset->records, dataset->capacity * sizeof(Record));
    }
    Record new_record = {key, dataset->size, value, time(NULL), priority};
    dataset->records[dataset->size++] = new_record;
    pthread_mutex_unlock(&dataset->lock);
}

void* retrieve_records(void *arg) {
    Dataset *dataset = (Dataset*)arg;
    time_t start_time = time(NULL) - 3600; // Retrieve records from the last hour
    for (int i = 0; i < dataset->size; i++) {
        if (dataset->records[i].timestamp >= start_time) {
            printf("Key: %d, Value: %d, Timestamp: %ld\n", dataset->records[i].key, dataset->records[i].value, dataset->records[i].timestamp);
        }
    }
    return NULL;
}

void destroy_dataset(Dataset *dataset) {
    pthread_mutex_destroy(&dataset->lock);
    free(dataset->records);
    free(dataset);
}
```

This code provides a basic structure for managing a dynamically growing dataset of records with concurrent access support. It includes functions to create, add records, retrieve records within a time window, and destroy the dataset. The use of mutexes ensures thread safety during record addition and retrieval.']

