#define MAX_LOGICAL_CHANNEL_IDENTITY 100

typedef struct {
    int rnti;
    struct TransportChannelConfig {
        int logicalChannelIdentity;
    } config;
} MAC_TransportChannelInfo;

int generateRandomLogicalChannelIdentity(int lastIdentity) {
    static int previousIdentity = MIN_LOGICAL_CHANNEL_IDENTITY - 1;
    int identity;
    do {
        identity = rand() % (MAX_LOGICAL_CHANNEL_IDENTITY - MIN_LOGICAL_CHANNEL_IDENTITY + 1) + MIN_LOGICAL_CHANNEL_IDENTITY;
    } while (identity == lastIdentity);
    return identity;
}

int initializeTransportChannelInfo(MAC_TransportChannelInfo **info, int count) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        info[i] = (MAC_TransportChannelInfo *)malloc(sizeof(MAC_TransportChannelInfo));
        if (!info[i]) {
            // Handle memory allocation failure
            return -1;
        }
        info[i]->rnti = rand() % MAX_RNTI + 1;
        info[i]->config.logicalChannelIdentity = generateRandomLogicalChannelIdentity(i > 0 ? info[i-1]->config.logicalChannelIdentity : MIN_LOGICAL_CHANNEL_IDENTITY);
    }
    return 0;
}

void freeTransportChannelInfo(MAC_TransportChannelInfo **info, int count) {
    for (int i = 0; i < count; i++) {
        free(info[i]);
    }
}

int main() {
    MAC_TransportChannelInfo *info[10];
    if (initializeTransportChannelInfo(info, 10) == 0) {
        // Use the initialized transport channel information
        for (int i = 0; i < 10; i++) {
            printf("RNTI: %d, Logical Channel Identity: %d\n", info[i]->rnti, info[i]->config.logicalChannelIdentity);
        }
        freeTransportChannelInfo(info, 10);
    } else {
        // Handle memory allocation failure
        printf("Memory allocation failed.\n");
    }
    return 0;
