#define MAX_CONCURRENT_ALLOCATIONS 100

typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    int current_allocations;
} AllocationManager;

AllocationManager allocation_manager = {PTHREAD_MUTEX_INITIALIZER, 0};

NFAPI_CRC_INDICATION_PDU_T* allocate_memory(int N, unsigned long seed) {
    if (pthread_mutex_lock(&allocation_manager.lock) != 0) {
        // Handle error
        return NULL;
    }

    if (allocation_manager.current_allocations >= MAX_CONCURRENT_ALLOCATIONS) {
        pthread_mutex_unlock(&allocation_manager.lock);
        return NULL; // Maximum allocations reached
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        pthread_mutex_unlock(&allocation_manager.lock);
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < N; i++) {
        // Initialize each structure with valid values and custom seed for CRCFLAG
        array[i].RX_UE_INFORMATION_TAG = /* initialize */;
        array[i].RNTI = /* initialize */;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand_r(&seed) % 2);
    }

    allocation_manager.current_allocations++;
    pthread_mutex_unlock(&allocation_manager.lock);

    return array;
}

void free_memory(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (pthread_mutex_lock(&allocation_manager.lock) != 0) {
        // Handle error
        return;
    }

    free(array);
    allocation_manager.current_allocations--;

    pthread_mutex_unlock(&allocation_manager.lock);
}

