#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MIN_VALUE 1
#define MAX_VALUE 100

typedef struct {
    int value;
    long* offset;
} Record;

Record** records = NULL;
long* offsets = NULL;
int record_count = 0;
int max_records = 0;

void init_memory() {
    records = (Record**)malloc(MAX_MEMORY * sizeof(Record*));
    offsets = (long*)malloc(MAX_MEMORY * sizeof(long));
    if (!records || !offsets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void free_memory() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    free(records);
    free(offsets);
}

Record* create_record() {
    if (record_count >= max_records) {
        fprintf(stderr, "Maximum number of records reached\n");
        return NULL;
    }

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    new_record->value = MIN_VALUE + rand() % (MAX_VALUE - MIN_VALUE + 1);
    new_record->offset = &offsets[record_count];
    records[record_count++] = new_record;

    return new_record;
}

void update_record(int id, int value) {
    if (id < 0 || id >= record_count) {
        fprintf(stderr, "Invalid identifier\n");
        return;
    }

    records[id]->value = value;
}

void delete_record(int id) {
    if (id < 0 || id >= record_count) {
        fprintf(stderr, "Invalid identifier\n");
        return;
    }

    free(records[id]);
    for (int i = id; i < record_count - 1; i++) {
        records[i] = records[i + 1];
    }
    record_count--;
}

void handle_put_request(int id, int value) {
    if (id >= record_count) {
        Record* new_record = create_record();
        if (!new_record) return;
        id = record_count - 1;
    }

    update_record(id, value);
}

void handle_delete_request(int id) {
    delete_record(id);
}
