#define MAX_RECORDS 100

typedef struct Record {
    int value;
    int priority;
    time_t timestamp;
    bool backup_flag;
    struct Record *next, *prev;
} Record;

Record* create_record(int value) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_record->value = value;
    new_record->priority = 0;
    new_record->timestamp = 0;
    new_record->backup_flag = false;
    new_record->next = new_record->prev = NULL;
    return new_record;
}

void initialize_records(Record* records[], int num_records) {
    for (int i = 0; i < num_records; ++i) {
        records[i] = create_record(rand() % 1000);
        records[i]->offset = i;
        if (i % 2 == 0) records[i]->priority = records[i - 1]->priority + 1;
    }
}

void free_records(Record* records[], int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i]);
    }
}

int main() {
    srand(time(NULL));
    Record* records[MAX_RECORDS];
    initialize_records(records, MAX_RECORDS);
    // Further processing and cleanup
    free_records(records, MAX_RECORDS);
    return 0;
}
