#include <iostream>
#include <vector>
#include <thread>
#include <chrono>
#include <random>
#include <boost/asio.hpp>

class DataFeedInterface {
public:
    virtual ~DataFeedInterface() {}
    virtual bool FetchNextRecord(long& offset, int& key, record& data) = 0;
};

class MockDataFeed : public DataFeedInterface {
private:
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<record> records;
    size_t currentIndex;

public:
    MockDataFeed(const std::vector<long>& offsets, const std::vector<int>& keys, const std::vector<record>& records)
        : offsets(offsets), keys(keys), records(records), currentIndex(0) {}

    bool FetchNextRecord(long& offset, int& key, record& data) override {
        if (currentIndex >= offsets.size()) return false;
        offset = offsets[currentIndex];
        key = keys[currentIndex];
        data = records[currentIndex++];
        return true;
    }
};

class DataIngestionPipeline {
private:
    boost::asio::io_context ioContext;
    std::unique_ptr<DataFeedInterface> dataFeed;
    std::vector<long> longArray;
    std::vector<int> intArray;
    std::vector<record> recordArray;
    size_t maxRecords;
    size_t successfulIngestions;
    size_t failedAttempts;
    size_t recordsProcessedPerMinute;

public:
    DataIngestionPipeline(std::unique_ptr<DataFeedInterface>& dataFeed, size_t maxRecords)
        : dataFeed(std::move(dataFeed)), maxRecords(maxRecords), successfulIngestions(0), failedAttempts(0), recordsProcessedPerMinute(0) {
        longArray.reserve(maxRecords);
        intArray.reserve(maxRecords);
        recordArray.reserve(maxRecords);
    }

    void Run() {
        while (true) {
            long offset;
            int key;
            record data;
            if (dataFeed->FetchNextRecord(offset, key, data)) {
                successfulIngestions++;
                longArray.push_back(offset);
                intArray.push_back(key);
                recordArray.push_back(data);
                recordsProcessedPerMinute++;
            } else {
                failedAttempts++;
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
            if (recordsProcessedPerMinute >= 60) {
                PrintMetrics();
                recordsProcessedPerMinute = 0;
            }
        }
    }

private:
    void PrintMetrics() {
        std::cout << "Successful Ingestions: " << successfulIngestions << std::endl;
        std::cout << "Failed Attempts: " << failedAttempts << std::endl;
        std::cout << "Records Processed Per Minute: " << recordsProcessedPerMinute << std::endl;
    }
};

int main() {
    // Example usage
    std::vector<long> offsets = {1, 2, 3};
    std::vector<int> keys = {4, 5, 6};
    std::vector<record> records = {{7, "A"}, {8, "B"}, {9, "C"}};
    auto dataFeed = std::make_unique<MockDataFeed>(offsets, keys, records);
    DataIngestionPipeline pipeline(std::move(dataFeed), 100);
    pipeline.Run();
    return 0;
}
