    status_flags = (int*)malloc(MAX_RECORDS * sizeof(int));
    event_types = (char**)malloc(MAX_RECORDS * sizeof(char*));

    if (!long_offsets || !keys || !records || !priorities || !timestamps || !metadata_strings || !source_identifiers || !target_identifiers || !status_flags || !event_types) {
        fprintf(stderr, "Memory allocation failed\n");
