    for (int i = 0; i < MAX_RECORDS; i++) {
        long_offsets[i] = i * 1024L; // Example memory budget
        keys[i] = rand() % (MAX_KEY_VALUE + 1);
        records[i] = (record*)malloc(sizeof(record));
        priorities[i] = rand() % 5 + 1; // Higher priority items first
        timestamps[i] = time(NULL) + (rand() % 60 - 30); // Random offset between -5 and +5 minutes

        metadata_strings[i] = (char*)malloc(MAX_METADATA_LENGTH);
        snprintf(metadata_strings[i], MAX_METADATA_LENGTH, "Metadata_%d", i);

        source_identifiers[i] = (char*)malloc(32);
