#define MAX_RECORD_SIZE 1024

typedef struct {
    char data[MAX_RECORD_SIZE];
    time_t creation_timestamp;
    int access_frequency;
} Record;

typedef struct {
    long offset;
    int key;
    Record *record;
} Component;

typedef struct {
    time_t timestamp;
    Record *record;
    char **tags;
    int tag_count;
} Event;

typedef struct {
    Component *components;
    Event *events;
    int component_count;
    int event_count;
    pthread_mutex_t mutex;
} FlexibleDataStructure;

FlexibleDataStructure* create_flexible_data_structure(int initial_capacity) {
    FlexibleDataStructure *fds = (FlexibleDataStructure*)malloc(sizeof(FlexibleDataStructure));
    if (!fds) return NULL;

    fds->components = (Component*)calloc(initial_capacity, sizeof(Component));
    fds->events = (Event*)calloc(initial_capacity, sizeof(Event));
    if (!fds->components || !fds->events) {
        free(fds);
        return NULL;
    }

    fds->component_count = 0;
    fds->event_count = 0;
    pthread_mutex_init(&fds->mutex, NULL);

    return fds;
}

void destroy_flexible_data_structure(FlexibleDataStructure *fds) {
    for (int i = 0; i < fds->component_count; i++) {
        free(fds->components[i].record);
    }
    for (int i = 0; i < fds->event_count; i++) {
        for (int j = 0; j < fds->events[i].tag_count; j++) {
            free(fds->events[i].tags[j]);
        }
        free(fds->events[i].tags);
    }
    free(fds->components);
    free(fds->events);
    pthread_mutex_destroy(&fds->mutex);
    free(fds);
}

void add_component(FlexibleDataStructure *fds, long offset, int key, const char *record_data) {
    pthread_mutex_lock(&fds->mutex);
    if (fds->component_count >= capacity) {
        // Resize the array
        Component *new_components = (Component*)realloc(fds->components, (capacity + 10) * sizeof(Component));
        if (!new_components) {
            pthread_mutex_unlock(&fds->mutex);
            return;
        }
        fds->components = new_components;
    }

    Component *component = &fds->components[fds->component_count++];
    component->offset = offset;
    component->key = key;
    component->record = (Record*)malloc(sizeof(Record));
    if (!component->record) {
        pthread_mutex_unlock(&fds->mutex);
        return;
    }
    strncpy(component->record->data, record_data, MAX_RECORD_SIZE - 1);
    component->record->data[MAX_RECORD_SIZE - 1] = '\0';
    time_t now = time(NULL);
    component->record->creation_timestamp = now;
    component->record->access_frequency = 0;

    pthread_mutex_unlock(&fds->mutex);
}

void add_event(FlexibleDataStructure *fds, const char *event_data) {
