#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_EXTRA_DATA_SIZE 1024
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    long offset;
    int key;
    float weight;
    void* extra_data;
} record;

typedef struct {
    record* records;
    size_t num_records;
    size_t max_records;
    size_t total_memory_used;
    pthread_mutex_t lock;
} memory_manager;

memory_manager* create_memory_manager(size_t initial_capacity) {
    memory_manager* manager = (memory_manager*)malloc(sizeof(memory_manager));
    if (!manager) return NULL;

    manager->records = (record*)calloc(initial_capacity, sizeof(record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->num_records = 0;
    manager->max_records = initial_capacity;
    manager->total_memory_used = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_memory_manager(memory_manager* manager) {
    if (manager) {
        for (size_t i = 0; i < manager->num_records; ++i) {
            free(manager->records[i].extra_data);
        }
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int insert_record(memory_manager* manager, int key, float weight, void* extra_data, size_t extra_size) {
    pthread_mutex_lock(&manager->lock);

    if (manager->num_records >= manager->max_records || manager->total_memory_used + sizeof(record) + extra_size > MAX_MEMORY) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Not enough space
    }

    record* new_record = &manager->records[manager->num_records];
    new_record->offset = (long)((char*)new_record - (char*)manager->records);
    new_record->key = key;
    new_record->weight = weight;

    if (extra_data) {
        new_record->extra_data = malloc(extra_size);
        if (!new_record->extra_data) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Error: Failed to allocate extra data
        }
        memcpy(new_record->extra_data, extra_data, extra_size);
    } else {
        new_record->extra_data = NULL;
    }

    manager->num_records++;
    manager->total_memory_used += sizeof(record) + extra_size;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Additional functions for retrieval and modification operations can be implemented here

int main() {
    memory_manager* manager = create_memory_manager(100);
    if (!manager) {
        fprintf(stderr, "Failed to create memory manager\n");
        return 1;
    }

    int key = 42;
    float weight = 3.14f;
    void* extra_data = malloc(MAX_EXTRA_DATA_SIZE);
    if (!extra_data) {
        fprintf(stderr, "Failed to allocate extra data\n");
        destroy_memory_manager(manager);
        return 1;
    }
    memset(extra_data, 0, MAX_EXTRA_DATA_SIZE);

    int result = insert_record(manager, key, weight, extra_data, MAX_EXTRA_DATA_SIZE);
    if (result != 0) {
        fprintf(stderr, "Failed to insert record\n");
        free(extra_data);
        destroy_memory_manager(manager);
        return 1;
    }

    // Additional operations can be performed here

    free(extra_data);
    destroy_memory_manager(manager);

    return 0;
}
