#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct Record {
    long offset;
    int key;
    float value;
    struct Record *next;
} Record;

typedef struct HashTable {
    Record **buckets;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable *create_hash_table(size_t size) {
    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    ht->size = size;
    ht->buckets = (Record **)calloc(size, sizeof(Record *));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        Record *current = ht->buckets[i];
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    pthread_mutex_destroy(&ht->lock);
    free(ht->buckets);
    free(ht);
}

size_t hash_function(int key, size_t size) {
    return ((key * 2654435761u) >> (32 - __builtin_clz(size))) % size;
}

void insert_record(HashTable *ht, Record *record) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(record->key, ht->size);
    record->next = ht->buckets[index];
    ht->buckets[index] = record;
    pthread_mutex_unlock(&ht->lock);
}

Record *find_record(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key, ht->size);
    Record *current = ht->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&ht->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

void *populate_list(void *arg) {
    HashTable *ht = (HashTable *)arg;
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; ++i) {
        Record *record = (Record *)malloc(sizeof(Record));
        record->offset = rand();
        record->key = rand() % 10000;
        record->value = (float)(rand()) / RAND_MAX;
        insert_record(ht, record);
    }
    return NULL;
}

int main() {
    HashTable *ht = create_hash_table(1024);
    pthread_t thread;
    if (pthread_create(&thread, NULL, populate_list, ht) != 0) {
        perror("Failed to create thread");
        destroy_hash_table(ht);
        return EXIT_FAILURE;
    }
    pthread_join(thread, NULL);

    // Example usage
    Record *record = find_record(ht, 1234);
    if (record != NULL) {
        printf("Found record: offset=%ld, key=%d, value=%.2f\n", record->offset, record->key, record->value);
    } else {
        printf("Record not found\n");
    }

    destroy_hash_table(ht);
    return EXIT_SUCCESS;
}
