#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RETRIES 10

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    record *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} record_pool;

record_pool* create_record_pool(size_t initial_size) {
    record_pool *pool = (record_pool*)malloc(sizeof(record_pool));
    if (!pool) return NULL;

    pool->pool = (record*)calloc(initial_size, sizeof(record));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pool->pool_size = initial_size;
    pool->used_count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_record_pool(record_pool *pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->pool);
        free(pool);
    }
}

record* allocate_record(record_pool *pool) {
    record *rec = NULL;

    pthread_mutex_lock(&pool->lock);
    if (pool->used_count < pool->pool_size) {
        rec = &pool->pool[pool->used_count++];
    } else {
        // Retry mechanism
        for (int i = 0; i < MAX_RETRIES; ++i) {
            if (pthread_mutex_unlock(&pool->lock) == 0) {
                pthread_mutex_lock(&pool->lock);
                if (pool->used_count < pool->pool_size) {
                    rec = &pool->pool[pool->used_count++];
                    break;
                }
            }
        }
    }
    pthread_mutex_unlock(&pool->lock);

    return rec;
}

void free_record(record_pool *pool, record *rec) {
    pthread_mutex_lock(&pool->lock);
    // Assuming records are freed in the order they were allocated
    if (rec >= pool->pool && rec < &pool->pool[pool->used_count]) {
        --pool->used_count;
    }
    pthread_mutex_unlock(&pool->lock);
}

int main() {
    record_pool *pool = create_record_pool(100);
    if (!pool) {
        fprintf(stderr, "Failed to create record pool\n");
        return 1;
    }

    record *rec = allocate_record(pool);
    if (rec) {
        rec->offset = 42;
        rec->key = 7;

        free_record(pool, rec);
    } else {
        fprintf(stderr, "Failed to allocate record\n");
    }

    destroy_record_pool(pool);
    return 0;
}
