#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Measurement {
    time_t timestamp;
    int cell_id;
    int rssi;
} Measurement;

typedef struct Node {
    Measurement data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (list == NULL) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_measurement(List* list, Measurement new_measurement) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = new_measurement;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

Measurement* get_latest_measurement(List* list, int cell_id) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Measurement* latest = NULL;
    while (current != NULL) {
        if (current->data.cell_id == cell_id && (latest == NULL || current->data.timestamp > latest->timestamp)) {
            latest = &current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return latest;
}

void update_measurement(List* list, Measurement new_measurement) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.cell_id == new_measurement.cell_id) {
            current->data = new_measurement;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_list(List* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
