#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Thumbnail {
    size_t id;
    float quality;
    unsigned char* data;
} Thumbnail;

typedef struct CacheNode {
    Thumbnail thumbnail;
    struct CacheNode* next;
    struct CacheNode* prev;
} CacheNode;

typedef struct Cache {
    CacheNode** table;
    size_t capacity;
    size_t size;
    CacheNode* head;
    CacheNode* tail;
    pthread_mutex_t lock;
} Cache;

Cache* create_cache(size_t initial_capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    if (!cache) return NULL;

    cache->table = (CacheNode**)calloc(initial_capacity, sizeof(CacheNode*));
    if (!cache->table) {
        free(cache);
        return NULL;
    }

    cache->capacity = initial_capacity;
    cache->size = 0;
    cache->head = NULL;
    cache->tail = NULL;
    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

void destroy_cache(Cache* cache) {
    if (!cache) return;

    CacheNode* node = cache->head;
    while (node) {
        CacheNode* next = node->next;
        free(node->thumbnail.data);
        free(node);
        node = next;
    }

    free(cache->table);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void insert_thumbnail(Cache* cache, Thumbnail thumbnail) {
    pthread_mutex_lock(&cache->lock);

    if (cache->size >= cache->capacity) {
        // Implement LRU eviction policy
        CacheNode* lru = cache->tail;
        if (lru) {
            free(lru->thumbnail.data);
            free(lru);
            cache->tail = lru->prev;
            if (cache->tail) cache->tail->next = NULL;
            else cache->head = NULL;
            cache->size--;
        }
    }

    CacheNode* new_node = (CacheNode*)malloc(sizeof(CacheNode));
    if (!new_node) {
        pthread_mutex_unlock(&cache->lock);
        return;
    }

    new_node->thumbnail = thumbnail;
    new_node->next = cache->head;
    new_node->prev = NULL;

    if (cache->head) cache->head->prev = new_node;
    else cache->tail = new_node;
    cache->head = new_node;
    cache->size++;

    pthread_mutex_unlock(&cache->lock);
}

Thumbnail* get_thumbnail(Cache* cache, size_t id) {
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->capacity; i++) {
        CacheNode* node = cache->table[i];
        while (node) {
            if (node->thumbnail.id == id) {
                // Move the accessed node to the front of the LRU list
                if (node != cache->head) {
                    if (node->prev) node->prev->next = node->next;
                    if (node->next) node->next->prev = node->prev;
                    if (cache->tail == node) cache->tail = node->prev;

                    node->next = cache->head;
                    node->prev = NULL;
                    cache->head->prev = node;
                    cache->head = node;
                }
                pthread_mutex_unlock(&cache->lock);
                return &node->thumbnail;
            }
            node = node->next;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

int main() {
    Cache* cache = create_cache(100);
    if (!cache) {
        fprintf(stderr, "Failed to create cache\n");
        return 1;
    }

    Thumbnail thumbnail = {1, 0.8f, (unsigned char*)malloc(1024)};
    insert_thumbnail(cache, thumbnail);

    Thumbnail* retrieved = get_thumbnail(cache, 1);
    if (retrieved) {
        printf("Retrieved thumbnail with ID %zu and quality %.2f\n", retrieved->id, retrieved->quality);
    } else {
        fprintf(stderr, "Failed to retrieve thumbnail\n");
    }

    destroy_cache(cache);
    return 0;
}
