void batch_process_configs(const char *directory) {
    DIR *dir;
    struct dirent *ent;
    if ((dir = opendir(directory)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                continue;

            char filename[256];
            snprintf(filename, sizeof(filename), "%s/%s", directory, ent->d_name);

            pthread_t thread;
            pthread_create(&thread, NULL, process_file, filename);
            pthread_join(thread, NULL);
        }
        closedir(dir);
    } else {
        perror("Failed to open directory");
    }

    apply_config_settings();
}

void update_config_setting(const char *key, const char *value) {
    for (int i = 0; i < config_cache.count; i++) {
        if (strcmp(config_cache.settings[i].key, key) == 0) {
            free(config_cache.settings[i].value);
            config_cache.settings[i].value = strdup(value);
            return;
        }
    }

    // Add new setting
    if (config_cache.count < MAX_FILES) {
        config_cache.settings[config_cache.count].key = strdup(key);
        config_cache.settings[config_cache.count].value = strdup(value);
        config_cache.count++;
    } else {
        fprintf(stderr, "Too many settings\n");
    }
}

void cache_config_settings() {
