#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_SIZE 4096
#define DEFAULT_MAX_LOG_RATE 102400 // 100KB/s
#define MAX_CONCURRENT_THREADS 10000

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_ERROR
} LogLevel;

typedef struct LogMessage {
    char *message;
    size_t length;
    struct LogMessage *next;
} LogMessage;

typedef struct LogQueue {
    LogMessage *head;
    LogMessage *tail;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
    size_t count;
    size_t max_size;
} LogQueue;

LogQueue log_queue;
size_t max_log_rate = DEFAULT_MAX_LOG_RATE;
LogLevel current_log_level = LOG_INFO;

void init_log_queue(size_t max_size) {
    log_queue.head = NULL;
    log_queue.tail = NULL;
    pthread_mutex_init(&log_queue.lock, NULL);
    pthread_cond_init(&log_queue.not_full, NULL);
    pthread_cond_init(&log_queue.not_empty, NULL);
    log_queue.count = 0;
    log_queue.max_size = max_size;
}

void destroy_log_queue() {
    LogMessage *msg;
    while ((msg = log_queue.head) != NULL) {
        log_queue.head = msg->next;
        free(msg->message);
        free(msg);
    }
    pthread_mutex_destroy(&log_queue.lock);
    pthread_cond_destroy(&log_queue.not_full);
    pthread_cond_destroy(&log_queue.not_empty);
}

void enqueue_log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);

    size_t length = vsnprintf(NULL, 0, format, args) + 1;
    if (length > MAX_LOG_SIZE) {
        length = MAX_LOG_SIZE;
    }

    LogMessage *msg = malloc(sizeof(LogMessage));
    msg->message = malloc(length);
    vsnprintf(msg->message, length, format, args);
    msg->length = length;
    msg->next = NULL;

    va_end(args);

    pthread_mutex_lock(&log_queue.lock);
    while (log_queue.count >= log_queue.max_size) {
        pthread_cond_wait(&log_queue.not_full, &log_queue.lock);
    }

    if (log_queue.tail != NULL) {
        log_queue.tail->next = msg;
    } else {
        log_queue.head = msg;
    }
    log_queue.tail = msg;
    log_queue.count++;

    pthread_cond_signal(&log_queue.not_empty);
    pthread_mutex_unlock(&log_queue.lock);
}

void *log_thread(void *arg) {
    while (1) {
        LogMessage *msg;
        pthread_mutex_lock(&log_queue.lock);
        while (log_queue.head == NULL) {
            pthread_cond_wait(&log_queue.not_empty, &log_queue.lock);
        }

        msg = log_queue.head;
        log_queue.head = msg->next;
        if (log_queue.head == NULL) {
            log_queue.tail = NULL;
        }
        log_queue.count--;

        pthread_cond_signal(&log_queue.not_full);
        pthread_mutex_unlock(&log_queue.lock);

        // Process the log message
        printf("%s\n", msg->message);
        free(msg->message);
        free(msg);
    }

    return NULL;
}

void set_max_log_rate(size_t rate) {
    max_log_rate = rate;
}

void set_log_level(LogLevel level) {
    current_log_level = level;
}

int main() {
    init_log_queue(1000);

    pthread_t threads[MAX_CONCURRENT_THREADS];
    for (size_t i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        pthread_create(&threads[i], NULL, log_thread, NULL);
    }

    // Example usage
    enqueue_log_message("This is a debug message");
    enqueue_log_message("This is an info message");
    enqueue_log_message("This is an error message");

    for (size_t i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_log_queue();

    return 0;
}
