#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h>
#include <pthread.h>

#define MAX_HOSTNAME_LENGTH 256
#define VERSION_SCHEMA "v1"

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    int version;
    pthread_mutex_t lock;
} HostnameEntry;

HostnameEntry *hostname_cache = NULL;
int cache_size = 0;

void init_hostname_cache(int size) {
    cache_size = size;
    hostname_cache = (HostnameEntry *)malloc(size * sizeof(HostnameEntry));
    for (int i = 0; i < size; i++) {
        pthread_mutex_init(&hostname_cache[i].lock, NULL);
    }
}

void destroy_hostname_cache() {
    free(hostname_cache);
}

int resolve_hostname(const char *hostname, int version) {
    // Validate hostname against schema
    if (strncmp(hostname, VERSION_SCHEMA, strlen(VERSION_SCHEMA)) != 0) {
        return -1; // Invalid hostname format
    }

    // Check cache for existing entry
    pthread_mutex_lock(&hostname_cache[0].lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(hostname_cache[i].hostname, hostname) == 0 && hostname_cache[i].version == version) {
            pthread_mutex_unlock(&hostname_cache[0].lock);
            return 1; // Hostname already resolved
        }
    }
    pthread_mutex_unlock(&hostname_cache[0].lock);

    // Resolve hostname using standard library functions
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname + strlen(VERSION_SCHEMA), NULL, &hints, &res);
    if (status != 0) {
        return -2; // Failed to resolve hostname
    }

    // Store resolved IP address in cache
    pthread_mutex_lock(&hostname_cache[0].lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(hostname_cache[i].hostname, "") == 0) {
            strcpy(hostname_cache[i].hostname, hostname);
            hostname_cache[i].version = version;
            pthread_mutex_unlock(&hostname_cache[0].lock);
            freeaddrinfo(res);
            return 1; // Hostname resolved and stored
        }
    }
    pthread_mutex_unlock(&hostname_cache[0].lock);

    freeaddrinfo(res);
    return -3; // Cache full, could not store new entry
}

int main() {
    init_hostname_cache(10); // Initialize cache with 10 entries

    int result = resolve_hostname("v1.example.com", 1);
    if (result == 1) {
        printf("Hostname resolved successfully.\n");
    } else if (result == -1) {
        printf("Invalid hostname format.\n");
    } else if (result == -2) {
        printf("Failed to resolve hostname.\n");
    } else if (result == -3) {
        printf("Cache full, could not store new entry.\n");
    }

    destroy_hostname_cache();
    return 0;
}
