using System;
using System.Net.Http;
using System.Threading.Tasks;

public class DocumentManagementSystem
{
    private readonly HttpClient _httpClient;
    private readonly string _backgroundServiceUrl;
    private readonly ICachingStrategy _cachingStrategy;

    public DocumentManagementSystem(HttpClient httpClient, string backgroundServiceUrl, ICachingStrategy cachingStrategy)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _backgroundServiceUrl = backgroundServiceUrl ?? throw new ArgumentNullException(nameof(backgroundServiceUrl));
        _cachingStrategy = cachingStrategy ?? throw new ArgumentNullException(nameof(cachingStrategy));
    }

    public async Task<UpdateResult> UpdateDocumentAsync(string documentId, int versionNumber, Metadata updatedMetadata)
    {
        try
        {
            // Validate current version against background service
            if (!await ValidateVersionAsync(documentId, versionNumber))
                return new UpdateResult { Success = false, Message = "Version conflict detected." };

            // Update document in database asynchronously
            await _cachingStrategy.UpdateDocumentAsync(documentId, updatedMetadata);

            // Invalidate cache for the document
            _cachingStrategy.InvalidateCache(documentId);

            return new UpdateResult { Success = true, Message = "Document updated successfully." };
        }
        catch (Exception ex)
        {
            return new UpdateResult { Success = false, Message = $"An error occurred: {ex.Message}" };
        }
    }

    private async Task<bool> ValidateVersionAsync(string documentId, int versionNumber)
    {
        var response = await _httpClient.GetAsync($"{_backgroundServiceUrl}/validate?documentId={documentId}&versionNumber={versionNumber}");
        if (response.IsSuccessStatusCode)
            return true;
        else
            return false;
    }
}

public class UpdateResult
{
    public bool Success { get; set; }
    public string Message { get; set; }
}

public interface ICachingStrategy
{
    Task UpdateDocumentAsync(string documentId, Metadata updatedMetadata);
    void InvalidateCache(string documentId);
}

public class InMemoryCachingStrategy : ICachingStrategy
{
    private readonly Dictionary<string, Document> _cache = new Dictionary<string, Document>();

    public async Task UpdateDocumentAsync(string documentId, Metadata updatedMetadata)
    {
        // Simulate database update and cache refresh
        await Task.Delay(100); // Simulate network latency
        _cache[documentId] = new Document { Id = documentId, Version = updatedMetadata.Version, Metadata = updatedMetadata };
    }

    public void InvalidateCache(string documentId)
    {
        if (_cache.ContainsKey(documentId))
            _cache.Remove(documentId);
    }
}

public class Document
{
    public string Id { get; set; }
    public int Version { get; set; }
    public Metadata Metadata { get; set; }
}

public class Metadata
{
    public int Version { get; set; }
    // Other metadata properties
}
```

