const require = require('module').createRequire(import.meta.url);
const blueslip = require('blueslip');
const { performance } = require('perf_hooks');

class TestManager {
  constructor() {
    this.moduleCache = {};
    this.testResults = [];
  }

  async loadModule(modulePath) {
    if (!this.moduleCache[modulePath]) {
      const module = await import(modulePath);
      this.moduleCache[modulePath] = module;
    }
    return this.moduleCache[modulePath];
  }

  async runTests(modulePath, testFilter) {
    const module = await this.loadModule(modulePath);
    const tests = Object.keys(module).filter(key => typeof module[key] === 'function');

    for (const test of tests) {
      if (testFilter && !testFilter(test)) continue;

      const startTime = performance.now();
      try {
        await module[test]();
        this.testResults.push({ test, status: 'pass', duration: performance.now() - startTime });
      } catch (error) {
        this.testResults.push({ test, status: 'fail', duration: performance.now() - startTime, error });
      }
    }

    return this.testResults;
  }

  async resetBlueslip() {
    blueslip.reset();
  }

  persistTestState(state) {
    // Implement state persistence logic here
  }

  loadTestState() {
    // Implement state loading logic here
  }

  async runTestsInParallel(modulePath, testFilter, maxConcurrent = 10) {
    const module = await this.loadModule(modulePath);
    const tests = Object.keys(module).filter(key => typeof module[key] === 'function');

    const results = [];
    const runningPromises = [];

    for (const test of tests) {
      if (testFilter && !testFilter(test)) continue;

      const startTime = performance.now();
      const promise = (async () => {
        try {
          await module[test]();
          results.push({ test, status: 'pass', duration: performance.now() - startTime });
        } catch (error) {
          results.push({ test, status: 'fail', duration: performance.now() - startTime, error });
        }
      })();

      runningPromises.push(promise);

      if (runningPromises.length >= maxConcurrent) {
        await Promise.race(runningPromises);
        runningPromises.splice(0, runningPromises.length);
      }
    }

    await Promise.all(runningPromises);
    return results;
  }
}

// Usage example:
const testManager = new TestManager();
testManager.runTests('path/to/module', test => test.startsWith('test_'))
  .then(results => console.log(results))
  .catch(error => console.error(error));
