// Define configurable regular expressions for event extraction
const eventPatterns = {
  battle: /(?:Battle|War) of (?:[A-Za-z\s]+)\b/gi,
  revolution: /\bRevolution\b(?: in (?:[A-Za-z\s]+))?\b/gi,
  conquest: /\bConquest\b(?: of (?:[A-Za-z\s]+))?\b/gi,
  treaty: /\bTreaty\b(?: between (?:[A-Za-z\s]+) and (?:[A-Za-z\s]+))?\b/gi
};

// Function to validate event names using an external API
async function validateEvent(eventName) {
  try {
    const response = await fetch(`https://api.example.com/events?name=${eventName}`);
    const data = await response.json();
    return data.isValid;
  } catch (error) {
    console.error('API error:', error);
    return false;
  }
}

// Main function to process text and extract event mentions
async function extractEvents(text, textsToInclude = ['Old Testament', 'Apocrypha']) {
  const eventsCount = {};

  // Filter text based on the list of texts to include
  if (textsToInclude.length > 0) {
    const filteredText = textsToInclude.reduce((acc, textName) => {
      return acc + ` ${text[textName]}`;
    }, '');
    text = filteredText;
  }

  // Extract events using regular expressions
  for (const [eventName, pattern] of Object.entries(eventPatterns)) {
    let match;
    while ((match = pattern.exec(text)) !== null) {
      const event = match[0].trim();
      if (await validateEvent(event)) {
        eventsCount[event] = (eventsCount[event] || 0) + 1;
      }
    }
  }

  return eventsCount;
}

// Example usage
const texts = {
  'Old Testament': 'The Battle of Jericho and the Exodus from Egypt.',
  'Apocrypha': 'The Maccabean Revolt and the Siege of Jerusalem.'
};

extractEvents(texts).then(events => console.log(events));
```

