// processAndAggregateSensorData.js

const fs = require('fs');
const path = require('path');

function loadScript(filePath) {
    try {
        return require(filePath);
    } catch (error) {
        console.error(`Failed to load script: ${filePath}`);
        return null;
    }
}

function initializeArrays() {
    const humidityReadings = [];
    const sensorIdentifiers = [];
    const readings = [];

    return { humidityReadings, sensorIdentifiers, readings };
}

function parseSensorData(line) {
    try {
        const data = JSON.parse(line);
        if (data && data.timestamp && typeof data.humidity === 'number') {
            return data;
        }
    } catch (error) {
        console.error('Failed to parse sensor data:', error);
    }
    return null;
}

function aggregateHumidityData(humidityReadings) {
    const sortedReadings = humidityReadings.sort((a, b) => a - b);
    const count = sortedReadings.length;

    const median = count % 2 !== 0 ? sortedReadings[Math.floor(count / 2)] : (sortedReadings[count / 2 - 1] + sortedReadings[count / 2]) / 2;
    const min = sortedReadings[0];
    const max = sortedReadings[count - 1];

    return { median, min, max };
}

function processAndAggregateSensorData(config) {
    const scripts = config.scripts.map(loadScript).filter(script => script !== null);
    if (scripts.length < config.dependencies.length) {
        console.error('Not all dependencies are met.');
        return;
    }

    const { humidityReadings, sensorIdentifiers, readings } = initializeArrays();

    fs.createReadStream(config.dataFile)
        .on('data', chunk => {
            chunk.toString().split('\n').forEach(line => {
                const data = parseSensorData(line);
                if (data) {
                    humidityReadings.push(data.humidity);
                    sensorIdentifiers.push(data.sensorId);
                    readings.push({ timestamp: data.timestamp, humidity: data.humidity, sensorId: data.sensorId });
                }
            });
        })
        .on('end', () => {
            const aggregation = aggregateHumidityData(humidityReadings);
            console.log('Aggregation:', aggregation);

            // Free allocated memory
            delete humidityReadings;
            delete sensorIdentifiers;
            delete readings;
        });

    // Handle concurrency and synchronization if necessary
}

// Example usage:
const config = {
    scripts: ['path/to/script1.js', 'path/to/script2.js'],
    dependencies: ['dependency1', 'dependency2'],
    dataFile: 'path/to/sensor_data.txt'
};

processAndAggregateSensorData(config);
```

