import java.util.Random;
import java.util.concurrent.atomic.AtomicInteger;

public class ServiceManager {
    private static final int MAX_RETRIES = 3;
    private static final long MIN_DELAY = 1000; // milliseconds
    private static final long MAX_DELAY = 5000; // milliseconds

    public void manageService() {
        Random random = new Random();
        AtomicInteger retryCount = new AtomicInteger(0);

        while (true) {
            try {
                startService();
                retryCount.set(0);
                Thread.sleep(random.nextLong(MAX_DELAY - MIN_DELAY) + MIN_DELAY);
            } catch (Exception e) {
                if (retryCount.incrementAndGet() > MAX_RETRIES) {
                    sendStopMessage(e.getMessage());
                    break;
                }
                Thread.sleep(random.nextLong(MAX_DELAY - MIN_DELAY) + MIN_DELAY);
            }
        }
    }

    private void startService() throws Exception {
        // Simulate service start
        if (random.nextBoolean()) {
            throw new Exception("Service start failed");
        }
    }

    private void sendStopMessage(String errorMessage) {
        // Send stop message to messaging system
        System.out.println("Service stopped: " + errorMessage);
    }
}
