#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MIN_VALUE 1
#define MAX_VALUE 100

typedef struct {
    int value;
    long offset;
    int key;
    char fieldName[50];
    char fieldValue[50];
} Record;

Record* allocateRecords(int n, int *allocatedSize) {
    static size_t totalAllocated = 0;
    Record *records = NULL;

    if (n <= 0 || n > MAX_MEMORY / sizeof(Record)) {
        return NULL; // Exceeds maximum memory limit
    }

    records = malloc(n * sizeof(Record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        records[i].offset = totalAllocated;
        sprintf(records[i].fieldName, "Field%d", i);
        sprintf(records[i].fieldValue, "Value%d", i);

        totalAllocated += sizeof(Record);
    }

    *allocatedSize = n;
    return records;
}

void freeRecords(Record *records, int size) {
    free(records);
}
