#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int packet_id;
    size_t payload_size;
    time_t timestamp;
} Packet;

typedef struct {
    Packet *buffer;
    size_t capacity;
    size_t front, rear;
    size_t count;
    size_t max_payload;
    int max_payload_id;
    time_t window_start;
    double threshold;
    int retry_count;
    int backpressure_threshold;
} TrafficLogProcessor;

TrafficLogProcessor* create_traffic_log_processor(size_t capacity, double threshold, int backpressure_threshold) {
    TrafficLogProcessor *processor = (TrafficLogProcessor*)malloc(sizeof(TrafficLogProcessor));
    processor->buffer = (Packet*)malloc(capacity * sizeof(Packet));
    processor->capacity = capacity;
    processor->front = 0;
    processor->rear = -1;
    processor->count = 0;
    processor->max_payload = 0;
    processor->max_payload_id = -1;
    processor->window_start = time(NULL);
    processor->threshold = threshold;
    processor->retry_count = 0;
    processor->backpressure_threshold = backpressure_threshold;
    return processor;
}

void destroy_traffic_log_processor(TrafficLogProcessor *processor) {
    free(processor->buffer);
    free(processor);
}

int is_full(TrafficLogProcessor *processor) {
    return processor->count == processor->capacity;
}

int is_empty(TrafficLogProcessor *processor) {
    return processor->count == 0;
}

void enqueue(TrafficLogProcessor *processor, Packet packet) {
    if (is_full(processor)) {
        printf("Queue is full. Dropping packet.\n");
        return;
    }
    processor->rear = (processor->rear + 1) % processor->capacity;
    processor->buffer[processor->rear] = packet;
    processor->count++;
}

Packet dequeue(TrafficLogProcessor *processor) {
    if (is_empty(processor)) {
        Packet empty_packet = {-1, 0, 0};
        return empty_packet;
    }
    Packet packet = processor->buffer[processor->front];
    processor->front = (processor->front + 1) % processor->capacity;
    processor->count--;
    return packet;
}

void process_packet(TrafficLogProcessor *processor, Packet packet) {
    time_t current_time = time(NULL);
    if (current_time - processor->window_start > processor->backpressure_threshold) {
        printf("Backpressure detected. Dropping packet.\n");
        return;
    }
    enqueue(processor, packet);
    while (!is_empty(processor) && processor->buffer[processor->front].timestamp < current_time - processor->backpressure_threshold) {
        dequeue(processor);
    }
    size_t cumulative_payload = 0;
    for (size_t i = processor->front; i != (processor->rear + 1) % processor->capacity; i = (i + 1) % processor->capacity) {
        cumulative_payload += processor->buffer[i].payload_size;
    }
    if (cumulative_payload > processor->max_payload && cumulative_payload <= processor->threshold) {
        processor->max_payload = cumulative_payload;
        processor->max_payload_id = processor->buffer[processor->front].packet_id;
    }
}

void log_processing_metrics(TrafficLogProcessor *processor) {
    printf("Max Payload: %zu, Max Payload ID: %d\n", processor->max_payload, processor->max_payload_id);
}
