async function customAsyncReduce(array, initialValue, asyncCallback, maxTimeout) {
    let accumulator = initialValue;
    let timeoutCount = 0;

    for (let i = 0; i < array.length; i++) {
        try {
            const result = await Promise.race([
                asyncCallback(accumulator, array[i]),
                new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), maxTimeout))
            ]);

            accumulator = result;
        } catch (error) {
            if (error.message === 'Timeout') {
                timeoutCount++;
                console.warn(`Operation timed out at index ${i}`);
            } else {
                console.error(`Error during operation at index ${i}:`, error);
                return `Error: ${error.message}`;
            }
        }
    }

    console.log(`Total timeouts: ${timeoutCount}`);
    return accumulator;
}

// Example usage:
const array = [1, 2, 3, 4, 5];
const initialValue = 0;

async function asyncCallback(accumulator, current) {
    // Simulate an asynchronous operation with a random delay
    const delay = Math.random() * 2000;
    return new Promise((resolve) => setTimeout(() => resolve(accumulator + current), delay));
}

const maxTimeout = 1500; // 1.5 seconds

customAsyncReduce(array, initialValue, asyncCallback, maxTimeout)
    .then(result => console.log('Final result:', result))
    .catch(error => console.error('Error:', error));
