    struct tm *tm_info = localtime(&now);
    strftime(logEntries[logCount].timestamp, sizeof(logEntries[logCount].timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    // Append unique identifier if necessary
    char uniqueId[10];
    sprintf(uniqueId, "_%d", logCount);
    strncpy(logEntries[logCount].message, message, MAX_LINE_LENGTH - strlen(uniqueId) - 1);
    strncat(logEntries[logCount].message, uniqueId, sizeof(uniqueId));

    logCount++;
    return 0;
}

