TIFFMetadata parseTIFF(const char* filename) {
    TIFFMetadata metadata = {0};
    TIFF* tif = TIFFOpen(filename, "r");

    if (!tif) {
        fprintf(stderr, "Failed to open TIFF file: %s\n", filename);
        return metadata;
    }

    uint16 bitsPerSample, samplesPerPixel, compressionType, orientation;
    char* colorProfile;

    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample)) {
        metadata.bitsPerSample = bitsPerSample;
    }

    if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel)) {
        metadata.samplesPerPixel = samplesPerPixel;
    }

    if (TIFFGetField(tif, TIFFTAG_COMPRESSION, &compressionType)) {
        metadata.compressionType = compressionType;
    }

    if (TIFFGetField(tif, TIFFTAG_ORIENTATION, &orientation)) {
        metadata.orientation = orientation;
    }

    // Placeholder for color profile extraction
