    // For simplicity, we'll just allocate memory and set it to a default value
    metadata.colorProfile = (char*)malloc(1024);
    if (metadata.colorProfile) {
        strcpy(metadata.colorProfile, "sRGB");
    }

    TIFFClose(tif);

    return metadata;
}

