#include <signal.h>
#include <time.h>

#define MAX_PROCESSES 5
#define TIMEOUT 60
#define HISTORY_SIZE 10

typedef struct {
    char command[256];
    time_t timestamp;
} CommandHistory;

CommandHistory history[HISTORY_SIZE];
int history_index = 0;

void handle_sigchld(int signum) {
    int status;
    while (waitpid(-1, &status, WNOHANG) > 0);
}

int execute_command(const char *command, const char *env[]) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid == 0) {
        execle("/bin/sh", "sh", "-c", command, NULL, env);
        perror("execle");
        exit(EXIT_FAILURE);
    }

    struct timespec start_time, end_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (1) {
        if (waitpid(pid, NULL, WNOHANG) == 0) {
            clock_gettime(CLOCK_REALTIME, &end_time);
            time_t elapsed = difftime(end_time.tv_sec, start_time.tv_sec);
            if (elapsed > TIMEOUT) {
                kill(pid, SIGKILL);
                return 0;
            }
            sleep(1);
        } else {
            break;
        }
    }

    return 1;
}

void log_command(const char *command) {
    strcpy(history[history_index].command, command);
    history[history_index].timestamp = time(NULL);
    history_index = (history_index + 1) % HISTORY_SIZE;
}

int main() {
    signal(SIGCHLD, handle_sigchld);

    const char *env[] = {"PATH=/usr/bin", NULL};
    int process_count = 0;

    while (process_count < MAX_PROCESSES) {
        if (execute_command("your_command_here", env)) {
            log_command("your_command_here");
            process_count++;
        } else {
            break;
        }
    }

    return 1;
}
