import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class TempResourceManager {
    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private static final String TEMP_DIR_PREFIX = "temp_";
    private static final String LOG_FILE_PATH = "logs/temp_resource_manager.log";

    public static void main(String[] args) {
        // Example usage
        try {
            Path tempDir = createTempDirectory("example");
            System.out.println("Created temporary directory: " + tempDir);
            Future<?> future = executor.submit(() -> executeCommand(tempDir, "ls -la"));
            future.get(); // Wait for command execution to complete
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static Path createTempDirectory(String prefix) throws IOException {
        Path tempDir = Files.createTempDirectory(TEMP_DIR_PREFIX + prefix);
        log("Created temporary directory: " + tempDir);
        return tempDir;
    }

    public static void executeCommand(Path tempDir, String command) {
        try {
            Process process = Runtime.getRuntime().exec(command, null, tempDir.toFile());
            int exitCode = process.waitFor();
            if (exitCode == 0) {
                log("Command executed successfully: " + command);
            } else {
                log("Command failed with exit code: " + exitCode);
            }
        } catch (IOException | InterruptedException e) {
            log("Error executing command: " + command, e);
        }
    }

    public static void cleanupTempResources() {
        try {
            Files.walk(Paths.get(System.getProperty("java.io.tmpdir")))
                 .filter(path -> path.toString().startsWith(TEMP_DIR_PREFIX))
                 .forEach(path -> {
                     try {
                         Files.delete(path);
                         log("Deleted temporary resource: " + path);
                     } catch (IOException e) {
                         log("Error deleting temporary resource: " + path, e);
                     }
                 });
        } catch (IOException e) {
            log("Error cleaning up temporary resources", e);
        }
    }

    private static void log(String message) {
        try {
            Files.write(Paths.get(LOG_FILE_PATH), (message + "\n").getBytes(), java.nio.file.StandardOpenOption.CREATE, java.nio.file.StandardOpenOption.APPEND);
        } catch (IOException e) {
            System.err.println("Error writing to log file: " + LOG_FILE_PATH);
        }
    }

    private static void log(String message, Throwable throwable) {
        try {
            Files.write(Paths.get(LOG_FILE_PATH), (message + "\n" + throwable.toString() + "\n").getBytes(), java.nio.file.StandardOpenOption.CREATE, java.nio.file.StandardOpenOption.APPEND);
        } catch (IOException e) {
            System.err.println("Error writing to log file: " + LOG_FILE_PATH);
        }
    }
