public class ConfigStructure
{
    public string Password { get; set; }
    public string ConnectionTitle { get; set; }
    public IntPtr CallbackFunction { get; set; }
}

public delegate void CallbackDelegate(string message);

public class MemoryPoolManager
{
    private List<byte[]> _pool = new List<byte[]>();
    private int _memoryLimit;

    public MemoryPoolManager(int memoryLimit)
    {
        _memoryLimit = memoryLimit;
    }

    public byte[] Allocate(int size)
    {
        if (_pool.Any(p => p.Length == size))
        {
            var item = _pool.First(p => p.Length == size);
            _pool.Remove(item);
            return item;
        }
        else
        {
            if (_pool.Sum(p => p.Length) + size > _memoryLimit)
                throw new OutOfMemoryException("Memory limit exceeded.");
            byte[] newItem = new byte[size];
            _pool.Add(newItem);
            return newItem;
        }
    }

    public void Free(byte[] item)
    {
        _pool.Add(item);
    }
}

public class NFAPI
{
    [DllImport("nfaapi.dll", CallingConvention = CallingConvention.Cdecl)]
    private static extern int ProcessNFAPIMessages(
        string base64EncodedMessage,
        ConfigStructure config,
        CallbackDelegate callback,
        int memoryLimit);

    public static void ProcessMessages(string base64EncodedMessage, ConfigStructure config, CallbackDelegate callback, int memoryLimit)
    {
        try
        {
            int result = ProcessNFAPIMessages(base64EncodedMessage, config, callback, memoryLimit);
            if (result != 0)
                throw new Exception($"Error processing messages: {result}");
