public class DataPacket
{
    public int PacketId { get; set; }
    public string Source { get; set; }
    public string Destination { get; set; }
    public int PayloadSize { get; set; }
}

public class DataProcessor
{
    private readonly byte[] _encryptionKey;
    private readonly HMACSHA256 _hmac;

    public DataProcessor(byte[] encryptionKey)
    {
        if (encryptionKey == null || !new[] { 16, 24, 32 }.Contains(encryptionKey.Length))
            throw new ArgumentException("Invalid encryption key length.");

        _encryptionKey = encryptionKey;
        _hmac = new HMACSHA256(_encryptionKey);
    }

    public DataPacket ProcessPacket(byte[] encryptedData, byte[] iv, string paddingScheme)
    {
        if (encryptedData == null || iv == null)
            throw new ArgumentNullException("Encrypted data or IV cannot be null.");

        using (Aes aes = Aes.Create())
        {
            aes.Key = _encryptionKey;
            aes.IV = iv;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            byte[] decryptedData = decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);

            if (!ValidateHmac(decryptedData))
                throw new InvalidOperationException("Invalid HMAC.");

            return ParsePacket(decryptedData, paddingScheme);
        }
    }

    private bool ValidateHmac(byte[] data)
    {
        byte[] hmacBytes = _hmac.ComputeHash(data);
        // Compare HMACs securely (constant time comparison)
        return Enumerable.SequenceEqual(hmacBytes, data.Skip(data.Length - 32).ToArray());
    }

    private DataPacket ParsePacket(byte[] data, string paddingScheme)
    {
        // Implement parsing logic based on the provided padding scheme
        throw new NotImplementedException();
    }
}

public class PacketManager
{
    private readonly ConcurrentBag<DataPacket> _packetQueue;
    private readonly int _queueSize;

    public PacketManager(int queueSize)
    {
        if (queueSize <= 0)
            throw new ArgumentException("Queue size must be greater than zero.");

        _queueSize = queueSize;
        _packetQueue = new ConcurrentBag<DataPacket>();
    }

    public void AddPacket(DataPacket packet)
    {
        if (_packetQueue.Count >= _queueSize)
            throw new InvalidOperationException("Packet queue is full.");

        _packetQueue.Add(packet);
    }

    public DataPacket GetNextPacket()
    {
        if (!_packetQueue.TryTake(out var packet))
            throw new InvalidOperationException("No packets available.");

        return packet;
    }
}
