["```typescript
import axios from 'axios';
import { Logger } from './logger'; // Assuming an existing logging framework

interface RequestConfig {
  url: string;
  method?: 'get' | 'post' | 'put' | 'delete';
  data?: any;
  headers?: any;
  cacheKey?: string;
  cacheTtl?: number;
}

class NetworkService {
  private logger: Logger;
  private cache: Map<string, { data: any; expiresAt: number }>;

  constructor(logger: Logger) {
    this.logger = logger;
    this.cache = new Map();
  }

  async request(config: RequestConfig): Promise<any> {
    const { url, method = 'get', data, headers, cacheKey, cacheTtl } = config;

    if (cacheKey && this.isCacheValid(cacheKey)) {
      return this.getCachedData(cacheKey);
    }

    try {
      const response = await axios({
        url,
        method,
        data,
        headers,
      });

      if (cacheKey) {
        this.setCachedData(cacheKey, response.data, cacheTtl || 60000); // Default TTL of 1 minute
      }

      return response.data;
    } catch (error) {
      this.logger.error(`Request failed: ${url}`, { error });
      throw error;
    }
  }

  private isCacheValid(cacheKey: string): boolean {
    const cachedData = this.cache.get(cacheKey);
    if (!cachedData) return false;
    return Date.now() < cachedData.expiresAt;
  }

  private getCachedData(cacheKey: string): any {
    const cachedData = this.cache.get(cacheKey);
    if (cachedData) return cachedData.data;
    throw new Error('Cache miss');
  }

  private setCachedData(cacheKey: string, data: any, ttl: number): void {
    this.cache.set(cacheKey, { data, expiresAt: Date.now() + ttl });
  }
}

// Usage example
const logger = new Logger(); // Assuming an existing logging framework
const networkService = new NetworkService(logger);

async function fetchData() {
  try {
    const response = await networkService.request({
      url: 'https://api.example.com/data',
      method: 'get',
      cacheKey: 'data-cache-key',
      cacheTtl: 30000, // Cache for 30 seconds
    });
    console.log(response);
  } catch (error) {
    console.error('Failed to fetch data:', error);
  }
}

fetchData();
```

This TypeScript code snippet defines a `NetworkService` class that handles asynchronous network requests to an external API endpoint. It includes caching, logging, and error handling mechanisms to ensure efficient resource utilization and reliable data delivery under varying loads. The service is designed to be modular, scalable, and maintainable, with clear separation of concerns and well-defined interfaces."]

['```rust
use tokio::sync::{mpsc, oneshot};
use tokio::time::{self, Duration};
use std::collections::HashMap;
use std::error::Error;

#[derive(Debug)]
enum TaskError {
    Interruption(String),
}

struct Task {
    id: u32,
    interval: Duration,
    priority: u8,
    state: String,
    interrupt_rx: oneshot::Receiver<()>,
}

impl Task {
    fn new(id: u32, interval: Duration, priority: u8) -> Self {
        let (interrupt_tx, interrupt_rx) = oneshot::channel();
        Task {
            id,
            interval,
            priority,
            state: "Running".to_string(),
            interrupt_rx,
        }
    }

    async fn run(&mut self) -> Result<(), TaskError> {
        loop {
            tokio::select! {
                _ = time::sleep(self.interval) => {
                    // Perform task work here
                    println!("Task {} is running", self.id);
                },
                _ = &mut self.interrupt_rx => {
                    return Err(TaskError::Interruption(format!("Task {} interrupted", self.id)));
                }
            }
        }
    }

    fn interrupt(&self) -> Result<(), oneshot::error::SendError<()>> {
        self.interrupt_tx.send(())
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let mut tasks = HashMap::new();
    let (tx, mut rx) = mpsc::channel(10);

    // Parse command-line arguments to create tasks
    for arg in std::env::args().skip(1) {
        let parts: Vec<&str> = arg.split(':').collect();
        if parts.len() == 3 {
            let id = parts[0].parse::<u32>()?;
            let interval = Duration::from_secs(parts[1].parse::<u64>()?);
            let priority = parts[2].parse::<u8>()?;
            tasks.insert(id, Task::new(id, interval, priority));
        }
    }

    // Spawn task runners
    for (_, mut task) in &mut tasks {
        tokio::spawn(async move {
            if let Err(e) = task.run().await {
                println!("Task error: {:?}", e);
            }
        });
    }

    // Handle interruptions
    while let Some(interrupt_id) = rx.recv().await {
        if let Some(task) = tasks.get_mut(&interrupt_id) {
            if let Err(_) = task.interrupt() {
                println!("Failed to interrupt task {}", interrupt_id);
            } else {
                println!("Interrupted task {}", interrupt_id);
            }
        }
    }

    Ok(())
}
