#define MAX_ERROR_LENGTH 256

typedef struct {
    int value;
} record;

int global_error_flag = 0;
char error_message[MAX_ERROR_LENGTH];

void log_error(const char* message) {
    snprintf(error_message, MAX_ERROR_LENGTH, "Error: %s", message);
    global_error_flag = 1;
}

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        log_error("Memory allocation failed");
    }
    return ptr;
}

record* create_records(int num_records, int min_value, int max_value) {
    record* records = (record*)safe_malloc(num_records * sizeof(record));
    if (records == NULL) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return records;
}

void free_records(record* records, int num_records) {
    if (records != NULL) {
        free(records);
    }
}
