use rand::Rng;
use reqwest::{Client, Error};
use std::sync::Arc;

#[derive(Debug)]
struct Record {
    value: i32,
    key: String,
}

fn initialize_records(
    num_records: usize,
    offset_range: (i32, i32),
    url: &str,
    validate_cert: bool,
) -> Result<Vec<Record>, Box<dyn std::error::Error>> {
    let mut rng = rand::thread_rng();
    let offsets: Vec<i32> = (0..num_records).map(|_| rng.gen_range(offset_range.0, offset_range.1)).collect();
    let indices: Vec<usize> = (0..num_records).collect();

    let client = if validate_cert {
        Client::new()
    } else {
        Client::builder().danger_accept_invalid_certs(true).build()?
    };

    let mut records = Vec::with_capacity(num_records);

    for i in 0..num_records {
        let value = offsets[i];
        let key = format!("record_{}", i);
        let response = client.get(url).send().await?;
        if response.status().is_success() {
            records.push(Record { value, key });
        } else {
            return Err(format!("Failed to fetch data for record {}: {}", i, response.status()).into());
        }
    }

    Ok(records)
}
