#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    int cell_id;
    int rssi;
} Measurement;

typedef struct Node {
    Measurement data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

void init_list(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void add_measurement(List* list, int timestamp, int cell_id, int rssi) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data.timestamp = timestamp;
    new_node->data.cell_id = cell_id;
    new_node->data.rssi = rssi;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void update_measurement(List* list, int cell_id, int timestamp, int rssi) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.cell_id == cell_id) {
            current->data.timestamp = timestamp;
            current->data.rssi = rssi;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

Measurement* get_latest_measurement(List* list, int cell_id) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Measurement* latest = NULL;
    while (current != NULL) {
        if (current->data.cell_id == cell_id && (latest == NULL || current->data.timestamp > latest->timestamp)) {
            latest = &current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return latest;
}

void free_list(List* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
