} TransportChannelConfig;

typedef struct {
    int RNTI;
    // Other fields as per the requirement
} NFAPI_CRC_INDICATION_PDU_T;

int rnti_pool[MAX_RNTI_POOL];
int pool_index = 0;
pthread_mutex_t rnti_lock;

void initialize_rnti_pool() {
    pthread_mutex_init(&rnti_lock, NULL);
    for (int i = 0; i < MAX_RNTI_POOL; i++) {
        rnti_pool[i] = -1; // Mark as unused
    }
}

int get_next_rnti() {
    int rnti;
    pthread_mutex_lock(&rnti_lock);
    if (pool_index >= MAX_RNTI_POOL) {
        printf("RNTI pool exhausted\n");
        pthread_mutex_unlock(&rnti_lock);
        return -1; // Error
    }
    rnti = rnti_pool[pool_index++];
    pthread_mutex_unlock(&rnti_lock);
    return rnti;
}

void release_rnti(int rnti) {
    pthread_mutex_lock(&rnti_lock);
    for (int i = 0; i < MAX_RNTI_POOL; i++) {
        if (rnti_pool[i] == rnti) {
            rnti_pool[i] = -1;
            pool_index--;
            break;
        }
    }
    pthread_mutex_unlock(&rnti_lock);
}

void populate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int rnti) {
    pdu->RNTI = rnti;
    // Populate other fields as per the requirement
}

void populate_mac_transport_channel_info(MAC_TransportChannelInfo *info, int rnti) {
    info->rnti = rnti;
    TransportChannelConfig config;
    config.logicalChannelIdentity = rand() % 100; // Example assignment
    // Populate other fields as per the requirement
}

void* manage_resource_pool(void* arg) {
    int thread_id = *(int*)arg;
    srand(time(NULL) + thread_id); // Seed for random number generation

    while (1) {
        int rnti = get_next_rnti();
        if (rnti == -1) break;

        NFAPI_CRC_INDICATION_PDU_T pdu;
        populate_crc_indication_pdu(&pdu, rnti);

        MAC_TransportChannelInfo info;
        populate_mac_transport_channel_info(&info, rnti);

        // Simulate resource allocation and deallocation
        sleep(1); // Example delay

        release_rnti(rnti);
    }

    return NULL;
}

int main() {
    initialize_rnti_pool();

    pthread_t threads[MAX_CONCURRENT_THREADS];
    int thread_ids[MAX_CONCURRENT_THREADS];

    for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, manage_resource_pool, &thread_ids[i]);
    }

    for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
