#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/time.h>

#define MAX_CONCURRENT_QUERIES 500
#define CACHE_SIZE 1000
#define CACHE_EXPIRY_SECONDS 60

typedef struct {
    char hostname[256];
    u_char ip[4];
    time_t expiry;
} CacheEntry;

CacheEntry cache[CACHE_SIZE];
int cache_count = 0;

u_char* resolve_hostname(const char* hostname) {
    // Check cache
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0 && time(NULL) < cache[i].expiry) {
            return cache[i].ip;
        }
    }

    // Perform DNS resolution
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        struct sockaddr_in* ipv4;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            ipv4 = (struct sockaddr_in*)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else {
            continue; // skip over non-IPv4 addresses
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s\n", ipstr);

        // Store in cache
        if (cache_count < CACHE_SIZE) {
            strcpy(cache[cache_count].hostname, hostname);
            memcpy(cache[cache_count].ip, addr, 4);
            cache[cache_count].expiry = time(NULL) + CACHE_EXPIRY_SECONDS;
            cache_count++;
        }
    }

    freeaddrinfo(res); // free the linked list

    return NULL; // Return IP address
}

int main() {
    const char* hostname = "example.com";
    u_char* ip = resolve_hostname(hostname);
    if (ip != NULL) {
        printf("Resolved IP: %d.%d.%d.%d\n", ip[0], ip[1], ip[2], ip[3]);
    } else {
        printf("Failed to resolve hostname.\n");
    }
    return 0;
}
