#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEASUREMENTS 1000

typedef struct {
    time_t timestamp;
    int cell_id;
    int rssi;
} Measurement;

typedef struct {
    Measurement measurements[MAX_MEASUREMENTS];
    int count;
    pthread_mutex_t lock;
} MeasurementList;

void init_measurement_list(MeasurementList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void add_or_update_measurement(MeasurementList *list, int cell_id, int rssi) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->measurements[i].cell_id == cell_id) {
            list->measurements[i].timestamp = time(NULL);
            list->measurements[i].rssi = rssi;
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }
    if (list->count < MAX_MEASUREMENTS) {
        list->measurements[list->count].cell_id = cell_id;
        list->measurements[list->count].timestamp = time(NULL);
        list->measurements[list->count].rssi = rssi;
        list->count++;
    }
    pthread_mutex_unlock(&list->lock);
}

Measurement* get_latest_measurement(MeasurementList *list, int cell_id) {
    Measurement *latest = NULL;
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->measurements[i].cell_id == cell_id && (!latest || list->measurements[i].timestamp > latest->timestamp)) {
            latest = &list->measurements[i];
        }
    }
    pthread_mutex_unlock(&list->lock);
    return latest;
}

void prune_measurements(MeasurementList *list, int max_size) {
    pthread_mutex_lock(&list->lock);
    if (list->count > max_size) {
        qsort(list->measurements, list->count, sizeof(Measurement), [](const void *a, const void *b) {
            return ((Measurement *)b)->timestamp - ((Measurement *)a)->timestamp;
        });
        list->count = max_size;
    }
    pthread_mutex_unlock(&list->lock);
}

void* log_measurements(void *arg) {
    MeasurementList *list = (MeasurementList *)arg;
    while (1) {
        for (int i = 0; i < list->count; i++) {
            // Log the measurement to an external data logging service
            printf("Logging: Cell ID %d, RSSI %d\n", list->measurements[i].cell_id, list->measurements[i].rssi);
        }
        sleep(1); // Simulate periodic logging
    }
    return NULL;
}

int main() {
    MeasurementList list;
    init_measurement_list(&list);

    pthread_t log_thread;
    pthread_create(&log_thread, NULL, log_measurements, &list);

    add_or_update_measurement(&list, 1, -50);
    add_or_update_measurement(&list, 2, -60);
    add_or_update_measurement(&list, 1, -45);

    Measurement *latest = get_latest_measurement(&list, 1);
    if (latest) {
        printf("Latest measurement for cell ID 1: RSSI %d\n", latest->rssi);
    }

    prune_measurements(&list, 100);

    pthread_join(log_thread, NULL);

    return 0;
}
