const char* processStringAndRecords(const char* string, size_t sizeLimit, bool allowTruncation, int numRecords, const Config* config) {
    if (strlen(string) + 1 > sizeLimit) {
        if (!allowTruncation) {
            return NULL;
        }
        // Truncate the string while ensuring semantic meaning
        char* truncatedString = malloc(sizeLimit);
        strncpy(truncatedString, string, sizeLimit - 1);
        truncatedString[sizeLimit - 1] = '/';
        return truncatedString;
    } else {
        char* processedString = strdup(string);
        strncat(processedString, "/", sizeLimit - strlen(processedString) - 1);
        return processedString;
    }
}

void freeRecords(Record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);
}
