function selectElements(rootNode, selector, callback) {
    const matches = [];

    function traverse(node) {
        if (node.nodeType === Node.ELEMENT_NODE && callback(node)) {
            matches.push(node);
        }
        for (let child of node.childNodes) {
            traverse(child);
        }
    }

    traverse(rootNode);
    return Promise.all(matches.map(match => new Promise(resolve => {
        // Simulate asynchronous operation
        setTimeout(() => resolve(match), 0);
    })));
}
