#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    unsigned long imsi;
    int sessionState;
    atomic_int *bearerIdentities;
    size_t bearerCount;
} UserSession;

typedef struct {
    UserSession **sessions;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} SessionManager;

void initSessionManager(SessionManager *manager, size_t initialCapacity) {
    manager->sessions = (UserSession **)malloc(initialCapacity * sizeof(UserSession *));
    manager->capacity = initialCapacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroySessionManager(SessionManager *manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->sessions[i]->bearerIdentities);
        free(manager->sessions[i]);
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}

void addSession(SessionManager *manager, UserSession *session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        manager->sessions = realloc(manager->sessions, manager->capacity * sizeof(UserSession *));
    }
    manager->sessions[manager->size++] = session;
    pthread_mutex_unlock(&manager->lock);
}

void removeSession(SessionManager *manager, unsigned long imsi) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->sessions[i]->imsi == imsi) {
            free(manager->sessions[i]->bearerIdentities);
            free(manager->sessions[i]);
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->sessions[j] = manager->sessions[j + 1];
            }
            --manager->size;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void updateBearerIdentities(SessionManager *manager, unsigned long imsi, int newBearerIdentity) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->sessions[i]->imsi == imsi) {
            atomic_fetch_add(&manager->sessions[i]->bearerIdentities[atomic_load(&manager->sessions[i]->bearerCount)], newBearerIdentity);
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void logMemoryUsage(SessionManager *manager) {
    printf("Current memory usage: %zu bytes\n", manager->size * sizeof(UserSession *));
}
