#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RETRIES 10
#define MEMORY_LIMIT 1024 * 1024 // 1 MB

typedef struct {
    char status;
    int key;
    long offset;
} record;

int hash_function(int key, int size) {
    return abs(key % size);
}

int is_unique(int *array, int size, int value) {
    for (int i = 0; i < size; i++) {
        if (array[i] == value) {
            return 0;
        }
    }
    return 1;
}

void allocate_and_initialize(long **offsets, int *keys, record **records, int num_records, long offset_range, int key_range) {
    srand(time(NULL));
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (*offsets == NULL || *keys == NULL || *records == NULL) {
            free(*offsets);
            free(*keys);
            free(*records);
        }

        *offsets = malloc(num_records * sizeof(long));
        *keys = malloc(num_records * sizeof(int));
        *records = malloc(num_records * sizeof(record));

        if (*offsets == NULL || *keys == NULL || *records == NULL) {
            retries++;
            continue;
        }

        int offset_set[num_records];
        int key_set[num_records];

        for (int i = 0; i < num_records; i++) {
            long offset;
            do {
                offset = rand() % offset_range;
            } while (!is_unique(offset_set, i, offset));

            int key;
            do {
                key = rand() % key_range;
            } while (!is_unique(key_set, i, key));

            (*offsets)[i] = offset;
            (*keys)[i] = key;

            (*records)[i].status = 'A';
            (*records)[i].key = key;
            (*records)[i].offset = offset;
        }

        if (sizeof(record) * num_records <= MEMORY_LIMIT) {
            break;
        } else {
            retries++;
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Memory allocation failed after %d retries.\n", MAX_RETRIES);
        exit(EXIT_FAILURE);
    }
}

void free_memory(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    allocate_and_initialize(&offsets, &keys, &records, 1000, 1000000, 1000);

    // Use the allocated structures...

    free_memory(offsets, keys, records);

    return 0;
}
