        (*keys)[i] = j;
        (*offsets)[i] = fibonacci(i + 1);
        (*records)[i].value = rand() % (max_val - min_val + 1) + min_val;

        char* str = (char*)custom_malloc(MAX_STRING_LENGTH * sizeof(char));
        if (!str) {
            return -1; // Memory allocation failed
        }
        snprintf(str, MAX_STRING_LENGTH, "Key%d", j);
        (*records)[i].str = str;
    }

    return 0; // Success
}

void free_memory(long* offsets, int* keys, Record* records) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        custom_free(records[i].str);
    }
    custom_free(offsets);
    custom_free(keys);
    custom_free(records);
}

// Unit tests
void test_allocate_memory() {
    long* offsets;
    int* keys;
    Record* records;

    if (allocate_memory(&offsets, &keys, &records, 10, 50) == 0) {
        printf("Memory allocation successful.\n");
        free_memory(offsets, keys, records);
    } else {
        printf("Memory allocation failed.\n");
    }
}

int main() {
    test_allocate_memory();
    return 0;
}
