NetworkInterface* create_network_interface(size_t initial_capacity) {
    NetworkInterface *ni = (NetworkInterface*)malloc(sizeof(NetworkInterface));
    ni->sessions = (UserSessionContext*)calloc(initial_capacity, sizeof(UserSessionContext));
    ni->capacity = initial_capacity;
    ni->size = 0;
    pthread_mutex_init(&ni->mutex, NULL);
    return ni;
}

void destroy_network_interface(NetworkInterface *ni) {
    free(ni->sessions);
    pthread_mutex_destroy(&ni->mutex);
    free(ni);
}

int add_user_session(NetworkInterface *ni, unsigned long imsi, int bearerIdentities[], int bearerCount) {
    pthread_mutex_lock(&ni->mutex);
    if (ni->size >= ni->capacity) {
        UserSessionContext *new_sessions = realloc(ni->sessions, ni->capacity * 2 * sizeof(UserSessionContext));
        if (!new_sessions) {
            pthread_mutex_unlock(&ni->mutex);
            return -1; // Memory allocation failed
        }
        ni->sessions = new_sessions;
        ni->capacity *= 2;
    }
    UserSessionContext *session = &ni->sessions[ni->size++];
    session->imsi = imsi;
    for (int i = 0; i < bearerCount && i < MAX_BEARER_IDentities; i++) {
        session->bearerIdentities[i] = bearerIdentities[i];
    }
    session->bearerCount = bearerCount;
    pthread_mutex_unlock(&ni->mutex);
    return 0;
}

void update_bearer_identities(NetworkInterface *ni, unsigned long imsi, int newBearerIdentities[], int newBearerCount) {
    pthread_mutex_lock(&ni->mutex);
    for (size_t i = 0; i < ni->size; i++) {
        if (ni->sessions[i].imsi == imsi) {
            for (int j = 0; j < newBearerCount && j < MAX_BEARER_IDentities; j++) {
                ni->sessions[i].bearerIdentities[j] = newBearerIdentities[j];
            }
            ni->sessions[i].bearerCount = newBearerCount;
            break;
        }
    }
    pthread_mutex_unlock(&ni->mutex);
}

