#define INITIAL_CAPACITY 10
#define RESIZE_THRESHOLD 5
#define API_RATE_LIMIT 10

typedef struct Product {
    float price;
    char name[256];
    struct Product* next;
} Product;

typedef struct ProductCollection {
    Product** products;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ProductCollection;

ProductCollection* create_product_collection(size_t initial_capacity) {
    ProductCollection* collection = (ProductCollection*)malloc(sizeof(ProductCollection));
    if (!collection) {
        perror("Failed to allocate memory for product collection");
        return NULL;
    }
    collection->products = (Product**)calloc(initial_capacity, sizeof(Product*));
    if (!collection->products) {
        perror("Failed to allocate memory for product array");
        free(collection);
        return NULL;
    }
    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_product_collection(ProductCollection* collection) {
    if (collection) {
        for (size_t i = 0; i < collection->count; ++i) {
            Product* product = collection->products[i];
            while (product) {
                Product* next = product->next;
                free(product);
                product = next;
            }
        }
        free(collection->products);
        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
}

int add_product(ProductCollection* collection, float price, const char* name) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity - RESIZE_THRESHOLD) {
        size_t new_capacity = collection->capacity * 2;
        Product** new_products = (Product**)realloc(collection->products, new_capacity * sizeof(Product*));
        if (!new_products) {
            perror("Failed to resize product array");
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->products = new_products;
        collection->capacity = new_capacity;
    }
    Product* new_product = (Product*)malloc(sizeof(Product));
    if (!new_product) {
        perror("Failed to allocate memory for product");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    new_product->price = price;
    strncpy(new_product->name, name, sizeof(new_product->name) - 1);
    new_product->next = NULL;
    collection->products[collection->count++] = new_product;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Additional functions for managing the product collection can be added here
