typedef struct {
    int value;
    long* offset;
    int key;
    void* extra_data;
} record;

record** create_records(int num_records, int extra_size, int compressed_mode, int* error_code) {
    if (num_records <= 0 || extra_size <= 0) {
        *error_code = -1; // Invalid input
        return NULL;
    }

    record** records = (record**)malloc(num_records * sizeof(record*));
    if (!records) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    void* extra_pool = malloc(num_records * extra_size);
    if (!extra_pool) {
        free(records);
        *error_code = -3; // Memory allocation failed
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(extra_pool);
            free(records);
            *error_code = -4; // Memory allocation failed
            return NULL;
        }

        records[i]->value = 0;
        records[i]->offset = (long*)malloc(sizeof(long));
        if (!records[i]->offset) {
            for (int j = 0; j <= i; ++j) {
                free(records[j]);
            }
            free(extra_pool);
            free(records);
            *error_code = -5; // Memory allocation failed
            return NULL;
        }

        records[i]->key = i;
        if (compressed_mode) {
            records[i]->extra_data = extra_pool + i * extra_size;
        } else {
            records[i]->extra_data = malloc(extra_size);
            if (!records[i]->extra_data) {
                for (int j = 0; j <= i; ++j) {
                    free(records[j]);
                }
                free(extra_pool);
                free(records);
                *error_code = -6; // Memory allocation failed
                return NULL;
            }
        }
    }

    *error_code = 0; // Success
    return records;
}

void destroy_records(record** records, int num_records, int compressed_mode) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i]->offset);
        if (!compressed_mode) {
            free(records[i]->extra_data);
        }
        free(records[i]);
    }
    free(records);
}

// Example usage
int main() {
    int error_code;
    record** records = create_records(10, 32, 1, &error_code); // Compressed mode
    if (error_code != 0) {
        printf("Error creating records: %d\n", error_code);
        return 1;
    }

    // Use the records...

    destroy_records(records, 10, 1);
    return 0;
}
