#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000000
#define AGE_THRESHOLD 3600 // 1 hour in seconds

typedef struct {
    int value;
} record;

typedef struct {
    long offset;
    int key;
} index_entry;

record* records[MAX_RECORDS];
index_entry* index[MAX_RECORDS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t last_prune_time;

void initialize_data_structures() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i] = NULL;
        index[i].offset = -1;
        index[i].key = -1;
    }
}

record* get_record(int key) {
    pthread_mutex_lock(&lock);
    int offset = index[key % MAX_RECORDS].offset;
    if (offset != -1 && index[key % MAX_RECORDS].key == key) {
        record* rec = records[offset];
        pthread_mutex_unlock(&lock);
        return rec;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void set_record(int key, int value) {
    pthread_mutex_lock(&lock);
    int offset = index[key % MAX_RECORDS].offset;
    if (offset == -1 || index[key % MAX_RECORDS].key != key) {
        for (int i = 0; i < MAX_RECORDS; i++) {
            if (index[i].offset == -1) {
                records[i] = malloc(sizeof(record));
                records[i]->value = value;
                index[i].offset = i;
                index[i].key = key;
                break;
            }
        }
    } else {
        records[offset]->value = value;
    }
    pthread_mutex_unlock(&lock);
}

void* prune_thread(void* arg) {
    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_prune_time > AGE_THRESHOLD) {
            pthread_mutex_lock(&lock);
            for (int i = 0; i < MAX_RECORDS; i++) {
                if (records[i] != NULL && records[i]->value < current_time - AGE_THRESHOLD) {
                    free(records[i]);
                    records[i] = NULL;
                    index[i].offset = -1;
                    index[i].key = -1;
                }
            }
            last_prune_time = current_time;
            pthread_mutex_unlock(&lock);
        }
        sleep(60); // Prune every minute
    }
}

int main() {
    initialize_data_structures();
    pthread_t prune_tid;
    pthread_create(&prune_tid, NULL, prune_thread, NULL);

    // Example usage
    set_record(12345, time(NULL));
    record* rec = get_record(12345);
    if (rec != NULL) {
        printf("Record value: %d\n", rec->value);
    }

    pthread_join(prune_tid, NULL);
    return 0;
}
