            // Process the packet
            printf("Processing packet with size: %d\n", packet.packetSize);
            packetQueue.head = (packetQueue.head + 1) % SLIDING_WINDOW_SIZE;
            packetQueue.count--;
        }
        pthread_mutex_unlock(&packetQueue.lock);
    }
}

