        packetQueue.tail = (packetQueue.tail + 1) % SLIDING_WINDOW_SIZE;
        packetQueue.count++;
        pthread_mutex_unlock(&packetQueue.lock);
    }

    pthread_join(thread, NULL);
    return 0;
}
```

