#include <chrono>
#include <algorithm>
#include <mutex>

void insertAfterOrAppend(std::forward_list<std::string>& list, const std::string& target, const std::string& value, std::chrono::milliseconds timeout = std::chrono::milliseconds(0)) {
    if (list.empty()) {
        list.push_front(value);
        return;
    }

    auto start = std::chrono::high_resolution_clock::now();
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (std::equal(it->begin(), it->end(), target.begin(), target.end(), [](char a, char b) {
            return tolower(a) == tolower(b);
        })) {
            it = list.insert_after(it, value);
            return;
        }
        if (timeout > std::chrono::milliseconds(0)) {
            auto now = std::chrono::high_resolution_clock::now();
            if (std::chrono::duration_cast<std::chrono::milliseconds>(now - start) >= timeout) {
                break;
            }
        }
    }

    list.push_back(value);
}
