#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define N 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_and_populate_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdus[i].RNTI = rand() % 65536;
        pdus[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0;
    }
}

void encrypt_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, int count) {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32], iv[16];
    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate random bytes\n");
        return;
    }
    ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Failed to initialize encryption context\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    for (int i = 0; i < count; i++) {
        unsigned char plaintext[32], ciphertext[32];
        int len, plen;
        plaintext[0] = pdus[i].RX_UE_INFORMATION_TAG & 0xFF;
        plaintext[1] = (pdus[i].RX_UE_INFORMATION_TAG >> 8) & 0xFF;
        plaintext[2] = pdus[i].RNTI & 0xFF;
        plaintext[3] = (pdus[i].RNTI >> 8) & 0xFF;
        plaintext[4] = pdus[i].CRC_INDICATION_REL8_TAG & 0xFF;
        if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, sizeof(plaintext)) != 1) {
            fprintf(stderr, "Failed to encrypt PDU\n");
            EVP_CIPHER_CTX_free(ctx);
            return;
        }
        plen = len;
        if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) != 1) {
            fprintf(stderr, "Failed to finalize encryption\n");
            EVP_CIPHER_CTX_free(ctx);
            return;
        }
        plen += len;
        // Store the encrypted data in pdus[i]
    }
    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory\n");
        return 1;
    }
    generate_and_populate_pdus(pdus);
    encrypt_pdus(pdus, N);
    free(pdus);
    return 0;
}
