#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 1000
#define SLIDING_WINDOW_SECONDS 3
#define MAX_TRANSACTIONS_PER_SECOND 100

typedef struct {
    int id;
    double value;
    int importance;
    time_t transaction_time;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int front, rear;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} TransactionQueue;

TransactionQueue queue;

void init_queue() {
    queue.front = queue.rear = -1;
    pthread_mutex_init(&queue.lock, NULL);
    pthread_cond_init(&queue.not_full, NULL);
    pthread_cond_init(&queue.not_empty, NULL);
}

int is_full() {
    return (queue.rear + 1) % MAX_TRANSACTIONS == queue.front;
}

int is_empty() {
    return queue.front == -1;
}

void enqueue(Transaction transaction) {
    pthread_mutex_lock(&queue.lock);
    while (is_full()) {
        pthread_cond_wait(&queue.not_full, &queue.lock);
    }
    if (is_empty()) {
        queue.front = queue.rear = 0;
    } else {
        queue.rear = (queue.rear + 1) % MAX_TRANSACTIONS;
    }
    queue.transactions[queue.rear] = transaction;
    pthread_cond_signal(&queue.not_empty);
    pthread_mutex_unlock(&queue.lock);
}

Transaction dequeue() {
    pthread_mutex_lock(&queue.lock);
    while (is_empty()) {
        pthread_cond_wait(&queue.not_empty, &queue.lock);
    }
    Transaction transaction = queue.transactions[queue.front];
    if (queue.front == queue.rear) {
        queue.front = queue.rear = -1;
    } else {
        queue.front = (queue.front + 1) % MAX_TRANSACTIONS;
    }
    pthread_cond_signal(&queue.not_full);
    pthread_mutex_unlock(&queue.lock);
    return transaction;
}

double calculate_weighted_sum(Transaction transaction, time_t current_time) {
    double time_factor = 0.1; // Example factor
    return transaction.value * transaction.importance + time_factor * (current_time - transaction.transaction_time);
}

void* process_transactions(void* arg) {
    while (1) {
        Transaction transaction = dequeue();
        if (transaction.id == -1) break;
        double current_time = time(NULL);
        if (current_time - transaction.transaction_time <= 5) {
            double weighted_sum = calculate_weighted_sum(transaction, current_time);
            // Update global metric counter and store results
        }
    }
    return NULL;
}

int main() {
    init_queue();
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, process_transactions, NULL);
    }

    // Simulate transaction arrival
    time_t current_time = time(NULL);
    while (1) {
        if (time(NULL) - current_time >= SLIDING_WINDOW_SECONDS) break;
        Transaction new_transaction = {rand() % 1000, rand() / 100.0, rand() % 5 + 1, time(NULL)};
        enqueue(new_transaction);
    }

    // Signal threads to exit
    for (int i = 0; i < 10; i++) {
        Transaction exit_signal = {-1, 0, 0, 0};
        enqueue(exit_signal);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
