#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int min;
    int max;
} Range;

Range* CreateRange(int min, int max) {
    Range* range = (Range*)malloc(sizeof(Range));
    range->min = min;
    range->max = max;
    return range;
}

float RandomFloat(Range* range) {
    return ((float)rand() / RAND_MAX) * (range->max - range->min) + range->min;
}

int RandomInt(Range* range) {
    return rand() % (range->max - range->min + 1) + range->min;
}

void DeleteRange(Range* range) {
    free(range);
}

typedef struct {
    int packetId;
    int payloadSize;
    time_t timestamp;
} Packet;

typedef struct {
    Packet** packets;
    int size;
    int capacity;
    time_t windowStart;
    Range* windowTimeRange;
    int maxPayloadSize;
    int threshold;
} NetworkTrafficProcessor;

NetworkTrafficProcessor* CreateNetworkTrafficProcessor(int initialCapacity, int windowTime, int maxPayload, int threshold) {
    NetworkTrafficProcessor* processor = (NetworkTrafficProcessor*)malloc(sizeof(NetworkTrafficProcessor));
    processor->packets = (Packet**)malloc(initialCapacity * sizeof(Packet*));
    processor->size = 0;
    processor->capacity = initialCapacity;
    processor->windowStart = time(NULL);
    processor->windowTimeRange = CreateRange(windowTime, windowTime + 1);
    processor->maxPayloadSize = maxPayload;
    processor->threshold = threshold;
    return processor;
}

void AddPacket(NetworkTrafficProcessor* processor, Packet packet) {
    if (time(NULL) - packet.timestamp > processor->windowTimeRange->min) {
        processor->windowStart = time(NULL);
    }
    while (processor->size > 0 && processor->packets[processor->size - 1]->timestamp < processor->windowStart) {
        processor->size--;
    }
    if (processor->size == processor->capacity) {
        processor->capacity *= 2;
        processor->packets = (Packet**)realloc(processor->packets, processor->capacity * sizeof(Packet*));
    }
    processor->packets[processor->size++] = &packet;
}

int GetMaxPayloadSize(NetworkTrafficProcessor* processor) {
    int maxPayload = 0;
    for (int i = 0; i < processor->size; i++) {
        if (processor->packets[i]->payloadSize > processor->threshold) {
            maxPayload += processor->packets[i]->payloadSize;
        }
    }
    return maxPayload;
}

void DeleteNetworkTrafficProcessor(NetworkTrafficProcessor* processor) {
    for (int i = 0; i < processor->size; i++) {
        free(processor->packets[i]);
    }
    free(processor->packets);
    DeleteRange(processor->windowTimeRange);
    free(processor);
}

int main() {
    srand(time(NULL));
    NetworkTrafficProcessor* processor = CreateNetworkTrafficProcessor(10, 100, 1000, 500);
    Packet packet;
    for (int i = 0; i < 20; i++) {
        packet.packetId = i;
        packet.payloadSize = RandomInt(CreateRange(100, 1000));
        packet.timestamp = time(NULL) - RandomInt(processor->windowTimeRange);
        AddPacket(processor, packet);
    }
    printf("Max Payload Size: %d\n", GetMaxPayloadSize(processor));
    DeleteNetworkTrafficProcessor(processor);
    return 0;
}
