typedef adjacency_list<vecS, vecS, directedS, no_property, property<edge_weight_t, int>> Graph;
typedef graph_traits<Graph>::vertex_descriptor Vertex;
typedef graph_traits<Graph>::edge_descriptor Edge;

void initialize_graph(Graph& g, int num_vertices) {
    add_vertices(num_vertices, g);
}

void add_random_edges(Graph& g, int num_edges) {
    boost::mt19937 gen;
    boost::uniform_int<> dis(0, num_vertices(g) - 1);
    for (int i = 0; i < num_edges; ++i) {
        Vertex u = dis(gen);
        Vertex v = dis(gen);
        while (u == v) {
            v = dis(gen);
        }
        add_edge(u, v, gen(), g);
    }
}

void update_vertex_property(Graph& g, int vertex_id, int new_value) {
    put(vertex_index, g, vertex_id, new_value);
}

void update_edge_property(Graph& g, Edge edge, int new_value) {
    put(edge_weight_t(), g, edge, new_value);
}

int main() {
    Graph g;
    initialize_graph(g, 1000000); // Initialize graph with 1 million vertices
    add_random_edges(g, 5000000); // Add 5 million random edges

    // Example usage of updating properties
    update_vertex_property(g, 0, 42);
    Edge e = edge(0, 1, g).first;
    update_edge_property(g, e, 99);

    return 0;
}
