// Define a structure to represent key-value pairs in the configuration file
struct ConfigPair {
    std::string key;
    std::string value;
};

// Define a class to handle dynamic memory management and error handling
class ConfigManager {
public:
    // Load configuration from a file
    static std::map<std::string, std::string> loadConfig(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open config file");
        }

        std::map<std::string, std::string> config;
        std::string line;
        while (std::getline(file, line)) {
            size_t pos = line.find('=');
            if (pos != std::string::npos) {
                config[line.substr(0, pos)] = line.substr(pos + 1);
            }
        }

        return config;
    }

    // Send a GET request to an external service and verify the response
    static bool sendGetRequest(const std::string& url, const std::map<std::string, std::string>& expected) {
        CURL* curl = curl_easy_init();
        if (!curl) {
            throw std::runtime_error("Failed to initialize libcurl");
        }

        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);

        std::string response;
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void* ptr, size_t size, size_t nmemb, void* userdata) {
            ((std::string*)userdata)->append((char*)ptr, size * nmemb);
            return size * nmemb;
        });
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
            return false;
        }

        curl_easy_cleanup(curl);

        // Verify the response against expected values
        for (const auto& pair : expected) {
            size_t pos = response.find(pair.first);
            if (pos == std::string::npos || response.substr(pos + pair.first.length()) != pair.second) {
                return false;
            }
        }

        return true;
    }
};

// Define a test double for the InterfaceTable class
class MockInterfaceTable {
public:
    static std::string FindVmUuidFromMetadataIp(const std::string& ip) {
        // Simulate behavior under different scenarios
        if (ip == "192.168.1.1") {
            return "vm-uuid-1";
        } else if (ip == "10.0.0.1") {
            throw std::runtime_error("Failed to find VM UUID");
        } else {
            return "";
        }
    }
};

int main() {
    try {
        // Load configuration from a file
        auto config = ConfigManager::loadConfig("config.txt");

        // Send a GET request to an external service and verify the response
        bool success = ConfigManager::sendGetRequest("http://example.com/api", {{"key1", "value1"}, {"key2", "value2"}});

        if (success) {
            std::cout << "GET request successful" << std::endl;
        } else {
            std::cerr << "GET request failed" << std::endl;
        }

