#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct MeasurementReport {
    time_t timeStamp;
    int rSRP;
    int rSINR;
    struct MeasurementReport *next;
} MeasurementReport;

typedef struct UEStatsRecord {
    int ue_id;
    MeasurementReport *reports;
    time_t lastUpdate;
    pthread_mutex_t lock;
} UEStatsRecord;

typedef struct DynamicArray {
    UEStatsRecord **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* dynamic_array_init(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->records = (UEStatsRecord**)calloc(initial_capacity, sizeof(UEStatsRecord*));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void dynamic_array_free(DynamicArray *array) {
    for (size_t i = 0; i < array->size; ++i) {
        UEStatsRecord *record = array->records[i];
        MeasurementReport *report = record->reports;
        while (report != NULL) {
            MeasurementReport *next = report->next;
            free(report);
            report = next;
        }
        pthread_mutex_destroy(&record->lock);
        free(record);
    }
    free(array->records);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void dynamic_array_add(DynamicArray *array, UEStatsRecord *record) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->records = (UEStatsRecord**)realloc(array->records, array->capacity * sizeof(UEStatsRecord*));
    }
    array->records[array->size++] = record;
    pthread_mutex_unlock(&array->lock);
}

UEStatsRecord* dynamic_array_get(DynamicArray *array, int ue_id) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->records[i]->ue_id == ue_id) {
            pthread_mutex_unlock(&array->lock);
            return array->records[i];
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL;
}

void dynamic_array_update(DynamicArray *array, int ue_id, MeasurementReport *new_report) {
    UEStatsRecord *record = dynamic_array_get(array, ue_id);
    if (record != NULL) {
        pthread_mutex_lock(&record->lock);
        // Add or update the report in a thread-safe manner
        // ...
        record->lastUpdate = time(NULL);
        pthread_mutex_unlock(&record->lock);
    }
}
