#define MAX_AGE 65
#define MIN_AGE 18
#define NUM_HOBBIES 20
#define MAX_ACTIVITY_LENGTH 100
#define MAX_TOTAL_ACTIVITY_LENGTH 1000

typedef struct Hobby {
    char name[MAX_ACTIVITY_LENGTH];
    struct Hobby *next;
} Hobby;

typedef struct UserProfile {
    int age;
    Hobby *preferences;
    Hobby *past_activities;
} UserProfile;

int generate_random_age() {
    return MIN_AGE + rand() % (MAX_AGE - MIN_AGE + 1);
}

UserProfile* create_user_profile() {
    UserProfile *profile = (UserProfile*)custom_malloc(sizeof(UserProfile));
    if (!profile) return NULL;

    profile->age = generate_random_age();

    // Initialize preferences
    Hobby *head = NULL, **tail = &head;
    for (int i = 0; i < NUM_HOBBIES; ++i) {
        Hobby *new_hobby = (Hobby*)custom_malloc(sizeof(Hobby));
        if (!new_hobby) {
            free_user_profile(profile);
            return NULL;
        }
        snprintf(new_hobby->name, MAX_ACTIVITY_LENGTH, "Hobby %d", i + 1);
        new_hobby->next = NULL;
        *tail = new_hobby;
        tail = &new_hobby->next;
    }

    profile->preferences = head;

    // Initialize past activities
    profile->past_activities = NULL;

    return profile;
}

void free_user_profile(UserProfile *profile) {
    Hobby *current, *temp;
    for (current = profile->preferences; current != NULL;) {
        temp = current;
        current = current->next;
        custom_free(temp);
    }
    custom_free(profile);
}

int add_past_activity(UserProfile *profile, const char *activity) {
    if (strlen(activity) > MAX_ACTIVITY_LENGTH) return -1;

    Hobby *new_activity = (Hobby*)custom_malloc(sizeof(Hobby));
    if (!new_activity) return -1;
    snprintf(new_activity->name, MAX_ACTIVITY_LENGTH, "%s", activity);
    new_activity->next = NULL;

    Hobby **tail = &profile->past_activities;
    while (*tail != NULL) {
        tail = &(*tail)->next;
    }
    *tail = new_activity;

    return 0;
}

int validate_past_activities(UserProfile *profile, int max_length) {
    int total_length = 0;
    Hobby *current = profile->past_activities;
    while (current != NULL) {
        total_length += strlen(current->name);
        if (total_length > max_length) return -1;
        current = current->next;
    }
    return 0;
}

int main() {
    srand(time(NULL));
    UserProfile *profile = create_user_profile();
    if (!profile) {
        fprintf(stderr, "Failed to create user profile\n");
        return 1;
    }

    add_past_activity(profile, "Reading a book");
    add_past_activity(profile, "Playing chess");

    int result = validate_past_activities(profile, MAX_TOTAL_ACTIVITY_LENGTH);
    if (result != 0) {
        fprintf(stderr, "Past activities exceed maximum length\n");
        free_user_profile(profile);
        return 1;
    }

    free_user_profile(profile);
    return 0;
}
