#define MAX_LOG_ENTRIES 1000
#define NUM_LOG_MESSAGES 100

typedef struct {
    int offset;
    int key;
    int value;
    char status;
    char* message;
} LogRecord;

int initializeLoggingSystem(LogRecord** records, int* offsets, int* keys, char* messages[], int* status) {
    srand(time(NULL));

    *records = (LogRecord*)malloc(MAX_LOG_ENTRIES * sizeof(LogRecord));
    *offsets = (int*)malloc(MAX_LOG_ENTRIES * sizeof(int));
    *keys = (int*)malloc(MAX_LOG_ENTRIES * sizeof(int));
    *status = (char*)malloc(MAX_LOG_ENTRIES * sizeof(char));

    if (*records == NULL || *offsets == NULL || *keys == NULL || *status == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 0;
    }

    for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
        (*offsets)[i] = i;
        (*keys)[i] = i;

        (*records)[i].offset = i;
        (*records)[i].key = i;
        (*records)[i].value = rand() % 2001 - 1000; // Random value between -1000 and 1000
        (*records)[i].status = 'A';

        int messageIndex = rand() % NUM_LOG_MESSAGES;
        (*records)[i].message = strdup(messages[messageIndex]);

        if ((*records)[i].message == NULL) {
            fprintf(stderr, "Memory allocation failed for log message at index %d.\n", i);
            *status[i] = 'F'; // Failure
        } else {
            *status[i] = 'S'; // Success
        }
    }

    return MAX_LOG_ENTRIES;
}

int main() {
    LogRecord* records;
    int* offsets;
    int* keys;
    char* messages[NUM_LOG_MESSAGES] = { /* Predefined log messages */ };
    char* status;

    int totalInitialized = initializeLoggingSystem(&records, &offsets, &keys, messages, &status);

    if (totalInitialized > 0) {
        printf("Successfully initialized %d log entries.\n", totalInitialized);

        // Free allocated memory
        for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
            free(records[i].message);
        }
        free(records);
        free(offsets);
        free(keys);
        free(status);
    } else {
        printf("Failed to initialize any log entries.\n");
    }

    return 0;
}
