#define BUFFER_SIZE 4096

void handle_error(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

int main() {
    int client_socket;
    struct sockaddr_in server_address;
    char buffer[BUFFER_SIZE];
    json_object *parsed_json, *config_data;

    // Create socket
    if ((client_socket = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        handle_error("Socket creation failed");
    }

    // Set up server address
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(SERVER_PORT);

    // Convert IP address from text to binary form
    if (inet_pton(AF_INET, SERVER_IP, &server_address.sin_addr) <= 0) {
        handle_error("Invalid address/ Address not supported");
    }

    // Connect to the server
    if (connect(client_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        handle_error("Connection failed");
    }

    // Receive JSON data from the server
    int bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        handle_error("Receive failed");
    }
    buffer[bytes_received] = '\0';

    // Parse the received JSON data
    parsed_json = json_tokener_parse(buffer);
    if (!parsed_json) {
        handle_error("JSON parsing failed");
    }

    // Extract configuration data from the JSON object
    config_data = json_object_object_get_ex(parsed_json, "config", &config_data);
    if (!config_data || !json_object_is_type(config_data, json_type_object)) {
        handle_error("Invalid JSON structure");
    }

    // Update local configuration files based on the parsed JSON data
    // (This part would involve file I/O operations and is not shown here)

    // Free allocated memory
    json_object_put(parsed_json);

    // Close the socket
    close(client_socket);

    return 0;
}
