#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1 MB
#define MAX_EXTRA_DATA_SIZE 1024
#define MIN_VALUE 1
#define MAX_VALUE 100

typedef struct {
    int value;
    long offset;
    int key;
    void* extra_data;
} Record;

typedef struct {
    Record* records;
    int count;
    int max_count;
    size_t total_memory_used;
    size_t max_memory_used;
} MemoryManager;

MemoryManager* create_memory_manager(int initial_capacity) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->max_count = initial_capacity;
    manager->total_memory_used = 0;
    manager->max_memory_used = 0;

    return manager;
}

void destroy_memory_manager(MemoryManager* manager) {
    for (int i = 0; i < manager->count; ++i) {
        free(manager->records[i].extra_data);
    }
    free(manager->records);
    free(manager);
}

int add_record(MemoryManager* manager, int value, long offset, int key, void* extra_data, size_t extra_data_size) {
    if (manager->total_memory_used + sizeof(Record) + extra_data_size > MAX_MEMORY) return -1;
    if (manager->count >= manager->max_count) {
        Record* new_records = (Record*)realloc(manager->records, manager->max_count * 2 * sizeof(Record));
        if (!new_records) return -1;
        manager->records = new_records;
        manager->max_count *= 2;
    }

    manager->records[manager->count].value = value;
    manager->records[manager->count].offset = offset;
    manager->records[manager->count].key = key;

    if (extra_data_size > 0) {
        manager->records[manager->count].extra_data = malloc(extra_data_size);
        if (!manager->records[manager->count].extra_data) return -1;
        memcpy(manager->records[manager->count].extra_data, extra_data, extra_data_size);
    } else {
        manager->records[manager->count].extra_data = NULL;
    }

    manager->total_memory_used += sizeof(Record) + extra_data_size;
    if (manager->total_memory_used > manager->max_memory_used) {
        manager->max_memory_used = manager->total_memory_used;
    }

    ++manager->count;
    return 0;
}

// Additional functions for managing transactions, integrating with financial data feed API, and handling concurrency would go here.
