    private int _maxValue;
    private Random _random;

    public DynamicValueGenerator(int minValue, int maxValue)
    {
        _minValue = minValue;
        _maxValue = maxValue;
        _random = new Random();
    }

    public void UpdateRange(int minValue, int maxValue)
    {
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public int GetRandomInteger()
    {
        return _random.Next(_minValue, _maxValue + 1);
    }

    public float GetRandomFloat()
    {
        return (float)_random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public decimal GetRandomDecimal()
    {
        return (decimal)_random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public List<int> GenerateSequence(int count)
    {
        var sequence = new List<int>();
        for (int i = 0; i < count; i++)
        {
            sequence.Add(GetRandomInteger());
        }
        return sequence;
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}";
    }
}
