        perror("Failed to open file");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(maxEntries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    size_t entriesRead = fread(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), maxEntries, file);
    if (entriesRead != maxEntries && ferror(file)) {
        perror("Failed to read from file");
        free(pdus);
        fclose(file);
        return NULL;
    }

    for (size_t i = 0; i < entriesRead; ++i) {
        pdus[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    fclose(file);
    return pdus;
}

char* appendSlashIfWithinLimit(const char* input, size_t maxLen) {
    if (strlen(input) < maxLen - 1) {
        char* result = (char*)malloc((maxLen + 1) * sizeof(char));
        if (!result) {
            perror("Memory allocation failed");
            return NULL;
        }
        strcpy(result, input);
        strcat(result, "/");
        return result;
    } else {
        return NULL;
    }
