DynamicList* create_dynamic_list(size_t M) {
    if (M == 0 || M > MAX_ELEMENTS) {
        return NULL; // Handle edge case where M is zero or exceeds max elements
    }

    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) {
        perror("Memory allocation failed");
        return NULL;
    }

    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    for (size_t i = 0; i < M; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!element) {
            perror("Memory allocation failed");
            // Free previously allocated elements
            for (size_t j = 0; j < i; ++j) {
                free(list->list[j]);
            }
            free(list);
            return NULL;
        }
        list->list[i] = element;
    }

    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    if (!list) {
        return;
    }

    for (size_t i = 0; i < list->count; ++i) {
