using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;

public class JsonProcessor
{
    private readonly ConcurrentDictionary<string, (JToken value, DateTime expiration)> _cache = new ConcurrentDictionary<string, (JToken value, DateTime expiration)>();
    private readonly string _jsonPathQuery;
    private readonly TimeSpan _cacheTtl;
    private readonly Func<Task<JObject>> _externalDataSource;

    public JsonProcessor(string jsonPathQuery, TimeSpan cacheTtl, Func<Task<JObject>> externalDataSource)
    {
        _jsonPathQuery = jsonPathQuery;
        _cacheTtl = cacheTtl;
        _externalDataSource = externalDataSource;
    }

    public async Task<JToken> GetFirstMatchingValueAsync()
    {
        string key = "first_matching_value";
        if (!_cache.TryGetValue(key, out var cachedItem) || DateTime.Now > cachedItem.expiration)
        {
            try
            {
                JObject jsonDocument = await _externalDataSource();
                JToken value = jsonDocument.SelectToken(_jsonPathQuery);
                if (value != null)
                {
                    _cache.TryAddOrUpdate(key, (value, DateTime.Now + _cacheTtl), (k, v) => (value, DateTime.Now + _cacheTtl));
                }
            }
            catch
            {
                // Fallback mechanism: return a default value or handle the error as needed
                return JToken.FromObject(null);
            }
        }

        return cachedItem.value;
    }
}
