    size_t total_size = sizeof(CustomStruct) * num_structs;
    if (total_size > MAX_MEMORY_SIZE) {
        fprintf(stderr, "Memory allocation exceeds maximum limit.\n");
        return -1;
    }

    *structs = (CustomStruct*)malloc(total_size);
    if (*structs == NULL) {
        fprintf(stderr, "Failed to allocate memory for custom structs.\n");
        return -2;
    }

    srand(time(NULL));
    int* rnti_set = (int*)calloc(num_structs, sizeof(int));
    if (rnti_set == NULL) {
        free(*structs);
        fprintf(stderr, "Failed to allocate memory for RNTI set.\n");
        return -3;
    }

    for (int i = 0; i < num_structs; ++i) {
        (*structs)[i].value = (float)i * 1.1f;
        do {
            (*structs)[i].pdu.RNTI = rand() % 65536; // Random RNTI
        } while (rnti_set[(*structs)[i].pdu.RNTI]++ > 0);
        snprintf((*structs)[i].name, 20, "Struct_%d", i);

        // Initialize NFAPI_CRC_INDICATION_PDU_T structure
        (*structs)[i].pdu.valid = 1;
        (*structs)[i].pdu.RX_UE_INFORMATION_TAG = 1;
        (*structs)[i].pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        // Allocate memory for the string
        (*structs)[i].name = (char*)malloc(strlen((*structs)[i].name) + 1);
        if ((*structs)[i].name == NULL) {
            fprintf(stderr, "Failed to allocate memory for string.\n");
            free(*structs);
            free(rnti_set);
            return -4;
        }
    }

    free(rnti_set);
    return 0;
}

void free_custom_structs(int num_structs, CustomStruct* structs) {
    for (int i = 0; i < num_structs; ++i) {
        free(structs[i].name);
    }
    free(structs);
}
