typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t max_size;
    void (*validate_tag)(uint32_t tag);
    void (*log_failure)(const char* message);
} ConfigStruct;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t max_size;
    void (*validate_tag)(uint32_t tag);
    void (*log_failure)(const char* message);
} List;

void init_list(List* list, ConfigStruct config) {
    list->head = NULL;
    list->count = 0;
    list->max_size = config.max_size;
    list->validate_tag = config.validate_tag;
    list->log_failure = config.log_failure;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        return NULL; // Handle memory allocation failure
    }
    node->data = data;
    node->next = NULL;
    return node;
}

void insert_node(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->count >= list->max_size) {
        list->log_failure("List size limit reached");
        return;
    }

    if (list->validate_tag != NULL) {
        list->validate_tag(data.RX_UE_INFORMATION_TAG);
    }

    Node* new_node = create_node(data);
    if (new_node == NULL) {
        list->log_failure("Failed to allocate memory for new node");
        return;
    }

    new_node->next = list->head;
    list->head = new_node;
    list->count++;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}
