#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOG_ENTRIES 100000
#define INITIAL_CAPACITY 1000

typedef struct {
    int year, month, day, hour, minute, second;
} Timestamp;

typedef enum {
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} Priority;

typedef struct LogEntry {
    Timestamp timestamp;
    char *message;
    Priority priority;
    char *source;
} LogEntry;

typedef struct {
    LogEntry *entries;
    int count;
    int capacity;
    size_t totalMemoryUsed;
    size_t memoryThreshold;
} LogSystem;

LogSystem* log_system_init(int initialCapacity, size_t memoryThreshold) {
    LogSystem *logSys = (LogSystem*)malloc(sizeof(LogSystem));
    if (!logSys) return NULL;

    logSys->entries = (LogEntry*)calloc(initialCapacity, sizeof(LogEntry));
    if (!logSys->entries) {
        free(logSys);
        return NULL;
    }

    logSys->count = 0;
    logSys->capacity = initialCapacity;
    logSys->totalMemoryUsed = 0;
    logSys->memoryThreshold = memoryThreshold;

    return logSys;
}

void log_system_append(LogSystem *logSys, Timestamp timestamp, const char *message, Priority priority, const char *source) {
    if (logSys->count >= logSys->capacity || logSys->totalMemoryUsed + strlen(message) > logSys->memoryThreshold) return;

    LogEntry *entry = &logSys->entries[logSys->count++];
    entry->timestamp = timestamp;
    entry->message = strdup(message);
    entry->priority = priority;
    entry->source = strdup(source);

    logSys->totalMemoryUsed += strlen(entry->message) + strlen(entry->source);
}

LogEntry** log_system_filter_by_priority(LogSystem *logSys, Priority minPriority, int *resultCount) {
    *resultCount = 0;
    for (int i = 0; i < logSys->count; i++) {
        if (logSys->entries[i].priority >= minPriority) (*resultCount)++;
    }

    LogEntry **filteredEntries = (LogEntry**)malloc((*resultCount) * sizeof(LogEntry*));
    if (!filteredEntries) return NULL;

    int j = 0;
    for (int i = 0; i < logSys->count; i++) {
        if (logSys->entries[i].priority >= minPriority) {
            filteredEntries[j++] = &logSys->entries[i];
        }
    }

    return filteredEntries;
}

void log_system_free(LogSystem *logSys) {
    for (int i = 0; i < logSys->count; i++) {
        free(logSys->entries[i].message);
        free(logSys->entries[i].source);
    }
    free(logSys->entries);
    free(logSys);
}
