typedef enum {
    ACTIVE,
    INACTIVE,
    PENDING
} Status;

typedef struct Item {
    char *name;
    unsigned int value;
    Status status;
} Item;

typedef struct Collection {
    Item **items;
    size_t count;
    size_t capacity;
} Collection;

Collection* create_collection(size_t initial_capacity) {
    Collection *collection = (Collection*)malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->items = (Item**)malloc(initial_capacity * sizeof(Item*));
    if (!collection->items) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;

    for (size_t i = 0; i < initial_capacity; ++i) {
        collection->items[i] = (Item*)malloc(sizeof(Item));
        if (!collection->items[i]) {
            // Clean up previously allocated items
            for (size_t j = 0; j < i; ++j) free(collection->items[j]);
            free(collection->items);
            free(collection);
            return NULL;
        }
        collection->items[i]->name = (char*)malloc(256); // Assuming max name length of 255
        if (!collection->items[i]->name) {
            // Clean up previously allocated items and names
            for (size_t j = 0; j <= i; ++j) {
                free(collection->items[j]->name);
                free(collection->items[j]);
            }
            free(collection->items);
            free(collection);
            return NULL;
        }
        collection->items[i]->value = 0;
        collection->items[i]->status = INACTIVE;
    }

    return collection;
}

void destroy_collection(Collection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->items[i]->name);
        free(collection->items[i]);
    }
    free(collection->items);
    free(collection);
}

int update_item_value(Collection *collection, size_t index, unsigned int new_value) {
    if (index >= collection->count) return -1;

    collection->items[index]->value = new_value;
    if (new_value > 1000) { // Example threshold
        collection->items[index]->status = PENDING;
    }

    return 0;
}

int main() {
    Collection *collection = create_collection(10);
    if (!collection) {
        fprintf(stderr, "Failed to create collection\n");
        return 1;
    }

    update_item_value(collection, 0, 500);
    update_item_value(collection, 0, 1200);

    destroy_collection(collection);
    return 0;
}
