#include <stdlib.h>
#include <string.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct Config {
    size_t max_size;
    void (*log_callback)(const char*);
    int log_threshold;
    int enable_tracing;
} Config;

void validate_node(Node* node, const Config* config) {
    if (node->data.RX_UE_INFORMATION_TAG < 0 || node->data.RX_UE_INFORMATION_TAG > 1000) {
        config->log_callback("Invalid RX_UE_INFORMATION_TAG");
    }
    if (node->data.RNTI <= 0) {
        config->log_callback("Invalid RNTI value");
    }
    if (node->data.CRCFLAG != 0 && node->data.CRCFLAG != 1) {
        config->log_callback("Invalid CRCFLAG value");
    }
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        return NULL;
    }
    memcpy(&new_node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = NULL;
    return new_node;
}

void add_to_list(Node** head, Node* new_node, Config* config) {
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    if (config->enable_tracing) {
        validate_node(new_node, config);
    }

    if (list_size(*head) > config->max_size) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

size_t list_size(Node* head) {
    size_t count = 0;
    while (head != NULL) {
        count++;
        head = head->next;
    }
    return count;
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}
