import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;

public class RecordManager {
    private ConcurrentHashMap<Integer, Record> records;
    private MessageDigest md;

    public RecordManager(int size, int range, long seed) throws NoSuchAlgorithmException {
        this.records = new ConcurrentHashMap<>(size);
        this.md = MessageDigest.getInstance("MD5");
        initializeRecords(size, range, seed);
    }

    private void initializeRecords(int size, int range, long seed) {
        java.util.Random random = new java.util.Random(seed);
        for (int i = 0; i < size; i++) {
            int key = random.nextInt(range);
            long offset = random.nextLong();
            int value = random.nextInt(range);
            records.put(key, new Record(key, offset, value));
        }
    }

    public void verifyDataIntegrity() throws NoSuchAlgorithmException {
        for (Record record : records.values()) {
            byte[] hash = md.digest((record.getKey() + ":" + record.getOffset() + ":" + record.getValue()).getBytes());
            if (!hash.equals(record.getHash())) {
                throw new IllegalStateException("Data integrity check failed.");
            }
        }
    }

    public static void main(String[] args) {
        try {
            RecordManager manager = new RecordManager(1000, 10000, System.currentTimeMillis());
            manager.verifyDataIntegrity();
            System.out.println("Data integrity verified successfully.");
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }

    static class Record {
        private int key;
        private long offset;
        private int value;
        private byte[] hash;

        public Record(int key, long offset, int value) throws NoSuchAlgorithmException {
            this.key = key;
            this.offset = offset;
            this.value = value;
            this.hash = calculateHash();
        }

        private byte[] calculateHash() throws NoSuchAlgorithmException {
            MessageDigest md = MessageDigest.getInstance("MD5");
            return md.digest((key + ":" + offset + ":" + value).getBytes());
        }

        public int getKey() {
            return key;
        }

        public long getOffset() {
            return offset;
        }

        public int getValue() {
            return value;
        }

        public byte[] getHash() {
            return hash;
        }
    }
}
