    void (*log_callback)(const char* message);
} ConfigStruct;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct DynamicList {
    Node* head;
    size_t size;
    size_t max_size;
    void (*validation_rule)(NFAPI_CRC_INDICATION_PDU_T*);
    void (*log_callback)(const char* message);
} DynamicList;

DynamicList* create_dynamic_list(size_t max_size, void (*validation_rule)(NFAPI_CRC_INDICATION_PDU_T*), void (*log_callback)(const char*)) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    list->max_size = max_size;
    list->validation_rule = validation_rule;
    list->log_callback = log_callback;
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int insert_into_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= list->max_size) {
        list->log_callback("Maximum size limit reached");
        return -1; // Error: Max size limit exceeded
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2; // Error: Memory allocation failed

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    list->validation_rule(&new_node->data);
    if (errno != 0) {
        list->log_callback("Validation failed");
        free(new_node);
        return -3; // Error: Validation failed
    }

    return 0; // Success
