    for (size_t i = 0; i < size; ++i) {
        // Initialize long offsets
        offsets[i] = i * (1000000 / size); // Evenly distributed across a large dataset

        // Initialize int keys with unique values and avoid collision
        do {
            keys[i] = rand() % max_key_value;
