typedef struct {
    int id;
    char* data;
} Record;

typedef struct {
    Record** records;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->data);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void add_record(RecordCollection* collection, int id, const char* data) {
    pthread_mutex_lock(&collection->lock);

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        perror("Failed to allocate memory for record");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    new_record->id = id;
    new_record->data = strdup(data);
    if (!new_record->data) {
        perror("Failed to allocate memory for data string");
        free(new_record);
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    collection->records = (Record**)realloc(collection->records, (collection->count + 1) * sizeof(Record*));
    if (!collection->records) {
        perror("Failed to reallocate memory for records array");
        free(new_record->data);
        free(new_record);
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    collection->records[collection->count++] = new_record;

    pthread_mutex_unlock(&collection->lock);
}

Record* get_record_by_id(RecordCollection* collection, int id) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]->id == id) {
            Record* record = collection->records[i];
            pthread_mutex_unlock(&collection->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void synchronize_with_database(RecordCollection* collection) {
    // Implement database synchronization logic here
    // This could involve fetching new data and updating the records
}

int main() {
    RecordCollection* collection = create_record_collection();

    add_record(collection, 1, "Data for record 1");
    add_record(collection, 2, "Data for record 2");

    Record* record = get_record_by_id(collection, 1);
    if (record) {
        printf("Record found: ID=%d, Data=%s\n", record->id, record->data);
    } else {
        printf("Record not found.\n");
    }

    destroy_record_collection(collection);

    return 0;
}
