#include <string.h>

#define STRING_POOL "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
#define NUM_ELEMENTS 1000

typedef struct {
    double value;
    char str[256];
    int index;
} Node;

unsigned long calculateChecksum(double d, const char* str, int i) {
    unsigned long checksum = 0;
    checksum += (unsigned long)d;
    for (int j = 0; j < strlen(str); j++) {
        checksum += (unsigned long)str[j];
    }
    checksum += (unsigned long)i;
    return checksum;
}

void initializeArrays(double** doubleArray, char*** stringArray, Node*** nodeArray) {
    *doubleArray = (double*)malloc(NUM_ELEMENTS * sizeof(double));
    *stringArray = (char**)malloc(NUM_ELEMENTS * sizeof(char*));
    *nodeArray = (Node**)malloc(NUM_ELEMENTS * sizeof(Node*));

    if (*doubleArray == NULL || *stringArray == NULL || *nodeArray == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }

    for (int i = 0; i < NUM_ELEMENTS; i++) {
        (*stringArray)[i] = (char*)malloc(256 * sizeof(char));
        if ((*stringArray)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(1);
        }
        snprintf((*stringArray)[i], 256, "%.*s", i % strlen(STRING_POOL), STRING_POOL);

        (*nodeArray)[i] = (Node*)malloc(sizeof(Node));
        if ((*nodeArray)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(1);
        }
        (*nodeArray)[i]->value = (double)i;
        strcpy((*nodeArray)[i]->str, (*stringArray)[i]);
        (*nodeArray)[i]->index = i;

        (*nodeArray)[i]->checksum = calculateChecksum((*nodeArray)[i]->value, (*nodeArray)[i]->str, (*nodeArray)[i]->index);
    }
}

int main() {
    double* doubleArray;
    char** stringArray;
    Node** nodeArray;

    initializeArrays(&doubleArray, &stringArray, &nodeArray);

    // Use the arrays and nodes as needed...

    for (int i = 0; i < NUM_ELEMENTS; i++) {
        free(stringArray[i]);
        free(nodeArray[i]);
    }
    free(doubleArray);
    free(stringArray);
    free(nodeArray);

    return 0;
}
