typedef struct Point {
    int x;
    int y;
    double distance;
} Point;

typedef struct TreeNode {
    Point data;
    struct TreeNode *left, *right;
} TreeNode;

typedef struct BST {
    TreeNode *root;
    int size;
} BST;

// Function to create a new point
Point* createPoint(int x, int y) {
    Point* p = (Point*)malloc(sizeof(Point));
    if (p == NULL) {
        fprintf(stderr, "Memory allocation failed for point\n");
        exit(1);
    }
    p->x = x;
    p->y = y;
    p->distance = sqrt(x * x + y * y);
    return p;
}

// Function to create a new tree node
TreeNode* createNode(Point data) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed for tree node\n");
        exit(1);
    }
    node->data = data;
    node->left = node->right = NULL;
    return node;
}

// Function to insert a point into the BST
void insert(BST* bst, Point data) {
    TreeNode** root = &(bst->root);
    while (*root != NULL) {
        if (data.distance < (*root)->data.distance)
            root = &((*root)->left);
        else
            root = &((*root)->right);
    }
    *root = createNode(data);
    bst->size++;
}

// Function to retrieve a point by index
Point* getByIndex(BST* bst, int index) {
    if (index < 0 || index >= bst->size) {
        fprintf(stderr, "Invalid index\n");
        return NULL;
    }
    TreeNode* current = bst->root;
    while (current != NULL) {
        int leftSize = (current->left != NULL) ? current->left->size : 0;
        if (index == leftSize)
            return &(current->data);
        else if (index < leftSize)
            current = current->left;
        else {
            index -= leftSize + 1;
            current = current->right;
        }
    }
    return NULL;
}

// Function to find the closest point to a given coordinate
Point* findClosest(BST* bst, int x, int y) {
    double minDistance = INFINITY;
    Point* closestPoint = NULL;
    TreeNode* current = bst->root;
    while (current != NULL) {
        double distance = sqrt((x - current->data.x) * (x - current->data.x) + (y - current->data.y) * (y - current->data.y));
        if (distance < minDistance) {
            minDistance = distance;
            closestPoint = &(current->data);
        }
        if (x < current->data.x)
            current = current->left;
        else
            current = current->right;
    }
    return closestPoint;
}

// Function to free the memory allocated for the BST
void freeBST(BST* bst) {
