    size_t log_size;
    size_t max_log_size;
} CRC_Manager;

void init_crc_manager(CRC_Manager* manager, size_t initial_capacity, const char* log_filename) {
    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        perror("Failed to allocate memory for CRC array");
        exit(EXIT_FAILURE);
    }
    manager->size = 0;
    manager->capacity = initial_capacity;
    manager->log_file = fopen(log_filename, "a");
    if (!manager->log_file) {
        perror("Failed to open log file");
        free(manager->array);
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&manager->mutex, NULL);
    manager->log_size = 0;
    manager->max_log_size = MAX_LOG_SIZE;
}

void destroy_crc_manager(CRC_Manager* manager) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->array);
    fclose(manager->log_file);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

void add_crc_indication(CRC_Manager* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory for CRC array");
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }
    manager->array[manager->size++] = pdu;
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "Added CRC indication: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n", pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG);
    fwrite(log_entry, 1, strlen(log_entry), manager->log_file);
    fflush(manager->log_file);
    manager->log_size += strlen(log_entry);
    if (manager->log_size > manager->max_log_size) {
        // Implement log rotation or truncation strategy here
    }
    pthread_mutex_unlock(&manager->mutex);
}

void reset_crc_manager(CRC_Manager* manager, const char* new_log_filename) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->array);
    fclose(manager->log_file);
    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(10 * sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Example initial capacity
    if (!manager->array) {
        perror("Failed to allocate memory for CRC array");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    manager->size = 0;
    manager->capacity = 10;
    manager->log_file = fopen(new_log_filename, "w"); // Open in write mode to truncate
    if (!manager->log_file) {
        perror("Failed to open log file");
        free(manager->array);
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    manager->log_size = 0;
    pthread_mutex_unlock(&manager->mutex);
}

