#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
    char* str;
    int rnti;
    int crcFlag;
} Record;

typedef struct {
    int parent[MAX_RECORDS];
    int rank[MAX_RECORDS];
} UnionFind;

void initUnionFind(UnionFind *uf, int n) {
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf, uf->parent[x]);
    return uf->parent[x];
}

void unionSet(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int countDisjointPairs(Record records[], int n) {
    UnionFind uf;
    initUnionFind(&uf, n);

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (records[i].rnti != records[j].rnti) {
                unionSet(&uf, i, j);
            }
        }
    }

    int disjointPairs = 0;
    for (int i = 0; i < n; i++) {
        if (find(&uf, i) == i)
            disjointPairs++;
    }

    return disjointPairs;
}

int main() {
    srand(time(NULL));
    Record records[MAX_RECORDS];
    int n = 10;

    // Initialize records with random data
    for (int i = 0; i < n; i++) {
        records[i].value = rand();
        records[i].str = (char*)malloc(20 * sizeof(char));
        sprintf(records[i].str, "Record%d", i);
        records[i].rnti = rand() % 100;
        records[i].crcFlag = rand() % 2;
    }

    int disjointPairs = countDisjointPairs(records, n);

    printf("Number of disjoint pairs: %d\n", disjointPairs);

    // Free allocated memory
    for (int i = 0; i < n; i++) {
        free(records[i].str);
    }

    return 0;
}
