RecordCollection* create_record_collection(size_t initial_capacity, size_t max_size) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->max_size = max_size;

    for (size_t i = 0; i < initial_capacity; ++i) {
        collection->records[i] = NULL;
    }

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->message);
        free(collection->records[i]);
    }
    free(collection->records);
    free(collection);
}

int add_record(RecordCollection* collection, long offset, int key) {
    if (collection->count >= collection->capacity || collection->count * sizeof(Record*) > collection->max_size) return -1;

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return -1;

    record->offset = offset;
    record->key = key;
    record->message = strdup("Constant message");
    if (!record->message) {
        free(record);
        return -1;
    }

    collection->records[collection->count++] = record;
    return 0;
}

int filter_records(RecordCollection* collection, int (*filter_func)(const Record*)) {
    size_t new_count = 0;

    for (size_t i = 0; i < collection->count; ++i) {
        if (filter_func(collection->records[i])) {
            collection->records[new_count++] = collection->records[i];
        } else {
            free(collection->records[i]->message);
            free(collection->records[i]);
        }
    }

    while (collection->count > new_count) {
        Record* record = collection->records[--collection->count];
        free(record->message);
        free(record);
    }

    return 0;
}

int filter_func(const Record* record) {
    // Example filter: keep records with key greater than 10
    return record->key > 10;
}
