public class DynamicRangeGenerator
{
    private Dictionary<Type, object> ranges = new Dictionary<Type, object>();
    private Random random = new Random();

    public void SetRange<T>(T min, T max) where T : IComparable
    {
        if (min.CompareTo(max) > 0)
            throw new ArgumentException("Min value must be less than or equal to max value.");

        ranges[typeof(T)] = new Tuple<T, T>(min, max);
    }

    public T GenerateRandomValue<T>() where T : IComparable
    {
        var range = GetRange<T>();
        if (range == null)
            throw new InvalidOperationException("No range set for type " + typeof(T).Name);

        return GenerateRandomValueInRange(range.Item1, range.Item2);
    }

    private T GenerateRandomValueInRange<T>(T min, T max) where T : IComparable
    {
        // Implementation of random value generation logic here
        throw new NotImplementedException();
    }

    public string SerializeToJson()
    {
        return JsonConvert.SerializeObject(ranges);
    }

    public void DeserializeFromJson(string json)
    {
        ranges = JsonConvert.DeserializeObject<Dictionary<Type, object>>(json);
    }

    public override string ToString()
    {
        var sb = new System.Text.StringBuilder();
        foreach (var range in ranges)
        {
            sb.AppendLine($"{range.Key.Name}: {range.Value}");
        }
        return sb.ToString();
    }

    private Tuple<T, T> GetRange<T>()
    {
        if (ranges.ContainsKey(typeof(T)))
            return (Tuple<T, T>)ranges[typeof(T)];
        return null;
    }
}
