['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    double value;
    unsigned int key;
    const char* str;
    struct Record* next;
} Record;

typedef struct LinkedList {
    Record* head;
    size_t count;
    size_t memoryUsage;
    size_t maxCapacity;
    size_t maxMemory;
} LinkedList;

LinkedList* createLinkedList(size_t maxCapacity, size_t maxMemory) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    list->memoryUsage = 0;
    list->maxCapacity = maxCapacity;
    list->maxMemory = maxMemory;
    return list;
}

void freeRecord(Record* record) {
    free((char*)record->str); // Free the string memory
    free(record);
}

void freeLinkedList(LinkedList* list) {
    Record* current = list->head;
    while (current != NULL) {
        Record* next = current->next;
        freeRecord(current);
        current = next;
    }
    free(list);
}

int insertRecord(LinkedList* list, double value, unsigned int key, const char* str) {
    if (list->count >= list->maxCapacity || list->memoryUsage + strlen(str) > list->maxMemory) return -1;
    Record* newRecord = (Record*)malloc(sizeof(Record));
    if (!newRecord) return -1;
    newRecord->value = value;
    newRecord->key = key;
    newRecord->str = strdup(str); // Duplicate the string
    if (!newRecord->str) {
        free(newRecord);
        return -1;
    }
    newRecord->next = list->head;
    list->head = newRecord;
    list->count++;
    list->memoryUsage += strlen(str);
    return 0;
}

int deleteRecord(LinkedList* list, unsigned int key) {
    Record** current = &list->head;
    while (*current != NULL) {
        if ((*current)->key == key) {
            Record* temp = *current;
            *current = (*current)->next;
            freeRecord(temp);
            list->count--;
            list->memoryUsage -= strlen(temp->str);
            return 0;
        }
        current = &(*current)->next;
    }
    return -1;
}

void filterRecords(LinkedList* list, int (*filterFunc)(unsigned int)) {
    Record** current = &list->head;
    while (*current != NULL) {
        if (!filterFunc((*current)->key)) {
            Record* temp = *current;
            *current = (*current)->next;
            freeRecord(temp);
            list->count--;
            list->memoryUsage -= strlen(temp->str);
        } else {
            current = &(*current)->next;
        }
    }
}

int filterFunc(unsigned int key) {
    // Example filter function
    return (key % 2 == 0); // Retain records with even keys
}
