#define MAX_RECORDS 1000
#define MAX_ALLOCATION_SIZE 1024 * 1024 // 1MB

typedef struct {
    long offset;
    int key;
    char* message;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int count;
    size_t total_size;
    pthread_mutex_t lock;
} RecordCollection;

void init_record_collection(RecordCollection* collection) {
    memset(collection, 0, sizeof(*collection));
    pthread_mutex_init(&collection->lock, NULL);
}

int add_record(RecordCollection* collection, long offset, int key) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= MAX_RECORDS || collection->total_size + sizeof(Record) > MAX_ALLOCATION_SIZE) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    Record* new_record = &collection->records[collection->count++];
    new_record->offset = offset;
    new_record->key = key;
    new_record->message = strdup("Default Message");
    collection->total_size += sizeof(Record) + strlen(new_record->message);
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void filter_records(RecordCollection* collection, int (*filter_func)(int)) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; ) {
        if (!filter_func(collection->records[i].key)) {
            free(collection->records[i].message);
            memmove(&collection->records[i], &collection->records[i + 1], sizeof(Record) * (collection->count - i - 1));
            collection->total_size -= sizeof(Record) + strlen(collection->records[i].message);
            collection->count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

void free_record_collection(RecordCollection* collection) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; i++) {
        free(collection->records[i].message);
    }
    memset(collection, 0, sizeof(*collection));
    pthread_mutex_unlock(&collection->lock);
}

