typedef struct log_entry {
    unsigned int sequence_number;
    const char* message;
} log_entry;

void* background_task(void* arg) {
    // Simulate a background task
    printf("Background task running\n");
    return NULL;
}

int initialize_logging_system(double start_time, double interval, int num_threads) {
    double* timestamps = (double*)malloc(num_threads * sizeof(double));
    if (!timestamps) {
        fprintf(stderr, "Failed to allocate memory for timestamps\n");
        return -1;
    }

    log_entry** log_entries = (log_entry**)malloc(num_threads * sizeof(log_entry*));
    if (!log_entries) {
        free(timestamps);
        fprintf(stderr, "Failed to allocate memory for log entries\n");
        return -1;
    }

    pthread_t* threads = (pthread_t*)malloc(num_threads * sizeof(pthread_t));
    if (!threads) {
        free(timestamps);
        free(log_entries);
        fprintf(stderr, "Failed to allocate memory for threads\n");
        return -1;
    }

    const char* messages[] = {"INFO", "WARNING", "ERROR"};
    int message_count = sizeof(messages) / sizeof(messages[0]);

    srand(time(NULL));
    for (int i = 0; i < num_threads; i++) {
        timestamps[i] = start_time + i * interval;
        log_entries[i] = (log_entry*)malloc(sizeof(log_entry));
        if (!log_entries[i]) {
            fprintf(stderr, "Failed to allocate memory for log entry %d\n", i);
            return -1;
        }

        int message_index;
        do {
            message_index = rand() % message_count;
        } while (i > 0 && strcmp(messages[message_index], log_entries[i-1]->message) == 0);

        log_entries[i]->sequence_number = i + 1;
        log_entries[i]->message = messages[message_index];

        if (pthread_create(&threads[i], NULL, background_task, NULL) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return -1;
        }
    }

    // Simulate logging
    for (int i = 0; i < num_threads; i++) {
        printf("Timestamp: %.2f, Sequence Number: %u, Message: %s\n",
               timestamps[i], log_entries[i]->sequence_number, log_entries[i]->message);
    }

    // Join threads and free resources
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
        free(log_entries[i]);
    }
    free(timestamps);
    free(log_entries);
    free(threads);

    return 0;
}

int main() {
    double start_time = time(NULL);
    double interval = 1.0; // second
    int num_threads = 5;

    if (initialize_logging_system(start_time, interval, num_threads) != 0) {
        fprintf(stderr, "Failed to initialize logging system\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
