#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEY_VALUE 1000
#define MAX_RECORDS 10000
#define SLIDING_WINDOW_SIZE 3
#define MAX_TRANSACTIONS_PER_SECOND 100

typedef struct {
    int value;
} record;

long offsets[MAX_RECORDS];
int keys[MAX_RECORDS];
record records[MAX_RECORDS];

pthread_mutex_t metric_counter_lock = PTHREAD_MUTEX_INITIALIZER;
int processed_transactions = 0;

void* process_transaction(void* arg) {
    // Simulate transaction processing logic here
    pthread_mutex_lock(&metric_counter_lock);
    processed_transactions++;
    pthread_mutex_unlock(&metric_counter_lock);
    return NULL;
}

long calculate_weighted_sum(int value, int importance, time_t current_time, time_t transaction_time) {
    return (long)value * importance + (current_time - transaction_time);
}

int main() {
    srand(time(NULL));

    // Allocate and initialize arrays
    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = i;
        keys[i] = rand() % MAX_KEY_VALUE;
        records[i].value = rand() % 100;
    }

    // Filter and process transactions
    time_t current_time = time(NULL);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (current_time - offsets[i] <= 5) {
            pthread_t thread_id;
            pthread_create(&thread_id, NULL, process_transaction, NULL);
            pthread_join(thread_id, NULL);
        }
    }

    // Calculate weighted sum and track transactions
    long max_weighted_sum = 0;
    int max_transaction_id = -1;
    for (int i = 0; i < MAX_RECORDS; i++) {
        time_t transaction_time = current_time - offsets[i];
        if ((current_time - transaction_time) <= SLIDING_WINDOW_SIZE && processed_transactions <= MAX_TRANSACTIONS_PER_SECOND) {
            long weighted_sum = calculate_weighted_sum(records[i].value, keys[i], current_time, transaction_time);
            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                max_transaction_id = i;
            }
        }
    }

    printf("Max Weighted Sum: %ld\n", max_weighted_sum);
    printf("Corresponding Transaction ID: %d\n", max_transaction_id);

    return 0;
}
