Event* createEvents(int maxEvents, time_t epochTime) {
    if (maxEvents <= 0 || epochTime == 0) {
        return NULL;
    }

    Event* events = (Event*)malloc(maxEvents * sizeof(Event));
    if (!events) {
        perror("Failed to allocate memory for events");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    int currentPacketID = 1;
    time_t currentTime = epochTime;

    for (int i = 0; i < maxEvents; ++i) {
        events[i].timestamp = currentTime++;
        events[i].packetID = currentPacketID++;

        if (currentPacketID > MAX_PACKET_ID) {
            currentPacketID = 1;
        }

        int payloadSize;
        do {
            payloadSize = MIN_PAYLOAD_SIZE + rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE);
        } while (i > 0 && events[i - 1].payloadSize == payloadSize);

        events[i].payloadSize = payloadSize;

        // Generate a random IP address avoiding common private ranges
        snprintf(events[i].sourceIP, sizeof(events[i].sourceIP), "%d.%d.%d.%d",
                 rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    }

    return events;
}

void freeEvents(Event* events) {
    if (events) {
        free(events);
    }
}

int main() {
    time_t epochTime = time(NULL); // Get the current time as the epoch
    int maxEvents = 10;

    Event* events = createEvents(maxEvents, epochTime);
    if (!events) {
        return EXIT_FAILURE;
    }

    for (int i = 0; i < maxEvents; ++i) {
        printf("Event %d: Timestamp=%ld, PacketID=%d, PayloadSize=%d, SourceIP=%s\n",
               i + 1, events[i].timestamp, events[i].packetID, events[i].payloadSize, events[i].sourceIP);
    }

    freeEvents(events);

    return EXIT_SUCCESS;
}
