#define MAX_MEMORY 1024 * 1024 // 1 MB
#define MAX_METADATA_SIZE 256

typedef struct Metadata {
    char type; // 's' for string, 'i' for integer
    union {
        char str[MAX_METADATA_SIZE];
        int num;
    } data;
} Metadata;

typedef struct ConfigSetting {
    char name[256];
    void* value; // Pointer to the actual value (string or integer)
    Metadata** metadata; // Array of pointers to metadata segments
    int metadata_count;
} ConfigSetting;

ConfigSetting* create_config_settings(int n) {
    if (n * sizeof(ConfigSetting) > MAX_MEMORY) {
        fprintf(stderr, "Error: Exceeds maximum memory limit.\n");
        return NULL;
    }

    ConfigSetting* settings = (ConfigSetting*)malloc(n * sizeof(ConfigSetting));
    if (!settings) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        memset(&settings[i], 0, sizeof(ConfigSetting));
    }

    return settings;
}

void initialize_settings(ConfigSetting* settings, int n) {
    // Initialize each setting's value and metadata
    for (int i = 0; i < n; i++) {
        // Example initialization logic
        snprintf(settings[i].name, sizeof(settings[i].name), "setting%d", i);
        settings[i].value = malloc(sizeof(int)); // Allocate memory for integer value
        *((int*)settings[i].value) = 42; // Set default value

        // Allocate metadata segments (example)
        settings[i].metadata_count = 1;
        settings[i].metadata = (Metadata**)malloc(settings[i].metadata_count * sizeof(Metadata*));
        settings[i].metadata[0] = (Metadata*)malloc(sizeof(Metadata));
        snprintf(settings[i].metadata[0]->str, MAX_METADATA_SIZE, "tag%d", i);
    }
}

void set_config_value(ConfigSetting* setting, const char* name, void* value) {
    if (strcmp(setting->name, name) != 0) {
        fprintf(stderr, "Error: Invalid setting name.\n");
        return;
    }

    // Update the value
    free(setting->value);
    setting->value = malloc(sizeof(int)); // Allocate memory for integer value
    *((int*)setting->value) = *(int*)value; // Set new value
}

void log_memory_usage(ConfigSetting* settings, int n) {
    // Log memory usage statistics (example)
    printf("Total memory used: %zu bytes\n", n * sizeof(ConfigSetting));
    for (int i = 0; i < n; i++) {
        printf("Setting %s: Value size - %zu bytes, Metadata count - %d\n",
               settings[i].name, sizeof(int), settings[i].metadata_count);
    }
}

void free_config_settings(ConfigSetting* settings, int n) {
    for (int i = 0; i < n; i++) {
        free(settings[i].value);
        for (int j = 0; j < settings[i].metadata_count; j++) {
            free(settings[i].metadata[j]);
        }
        free(settings[i].metadata);
    }
    free(settings);
}
