// JavaScript code to asynchronously read multiple files from a specified directory,
// filter them based on a specified extension, and return an object containing
// the file names and their respective contents as strings.

const fs = require('fs').promises;
const path = require('path');
const { Worker } = require('worker_threads');

async function readFilesAsync(directory, extension) {
  const files = await fs.readdir(directory);
  const filteredFiles = files.filter(file => path.extname(file).toLowerCase() === `.${extension}`);

  const results = {};
  const workers = [];

  for (let i = 0; i < filteredFiles.length; i++) {
    const worker = new Worker('./worker.js', { workerData: { filePath: path.join(directory, filteredFiles[i]) } });
    workers.push(worker);

    worker.on('message', data => {
      results[data.fileName] = data.fileContent;
      if (Object.keys(results).length === filteredFiles.length) {
        workers.forEach(w => w.terminate());
        console.log('All files read successfully.');
        return results;
      }
    });

    worker.on('error', error => {
      console.error(`Error reading file: ${error}`);
      workers.forEach(w => w.terminate());
      throw error;
    });
  }

  // Limit concurrent requests to 1000
  if (workers.length > 1000) {
    await Promise.all(workers.map(worker => new Promise(resolve => worker.on('exit', resolve))));
  }
}

// Example usage:
readFilesAsync('/path/to/directory', 'txt')
  .then(files => console.log(files))
  .catch(error => console.error(error));
