#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char timestamp[21];
    int packetID;
    int payloadSize;
} Packet;

Packet* create_packets(int numPackets, int maxPacketID, int bandwidthLimit, time_t epochTime) {
    Packet* packets = (Packet*)malloc(numPackets * sizeof(Packet));
    if (!packets) {
        perror("Failed to allocate memory for packets");
        return NULL;
    }

    pthread_mutex_t idMutex = PTHREAD_MUTEX_INITIALIZER;
    int currentID = 1;

    srand(time(NULL));

    for (int i = 0; i < numPackets; ++i) {
        // Generate timestamp
        time_t packetTime = epochTime + i * 2; // Example: 2-second interval
        strftime(packets[i].timestamp, sizeof(packets[i].timestamp), "%Y-%m-%d %H:%M:%S", localtime(&packetTime));

        // Generate unique packet ID
        pthread_mutex_lock(&idMutex);
        packets[i].packetID = currentID++;
        if (currentID > maxPacketID) {
            currentID = 1; // Reset to start of range
        }
        pthread_mutex_unlock(&idMutex);

        // Generate payload size ensuring no two consecutive packets have the same size and bandwidth constraint
        int payloadSize;
        do {
            payloadSize = rand() % (bandwidthLimit / numPackets) + 1;
        } while (i > 0 && packets[i - 1].payloadSize == payloadSize);
        packets[i].payloadSize = payloadSize;

        // Log packet creation
        printf("Packet created: ID=%d, Timestamp=%s, Payload Size=%d\n", packets[i].packetID, packets[i].timestamp, packets[i].payloadSize);
    }

    pthread_mutex_destroy(&idMutex);

    return packets;
}

void free_packets(Packet* packets, int numPackets) {
    if (packets) {
        free(packets);
    }
}

int main() {
    time_t epochTime = time(NULL);
    Packet* packets = create_packets(10, 100, 1024, epochTime);

    if (packets) {
        // Sort packets by timestamp in descending order
        qsort(packets, 10, sizeof(Packet), [](const void* a, const void* b) {
            return strcmp(((Packet*)b)->timestamp, ((Packet*)a)->timestamp);
        });

        for (int i = 0; i < 10; ++i) {
            printf("Sorted Packet: ID=%d, Timestamp=%s, Payload Size=%d\n", packets[i].packetID, packets[i].timestamp, packets[i].payloadSize);
        }

        free_packets(packets, 10);
    }

    return 0;
}
