weather_record* create_weather_array(int num_records, int precip_min, int precip_max, double wind_min, double wind_max) {
    if (num_records <= 0 || precip_min > precip_max || wind_min >= wind_max) {
        return NULL; // Invalid input
    }

    weather_record* array = malloc(num_records * sizeof(weather_record));
    if (array == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < num_records; i++) {
        array[i].precipitation = rand() % (precip_max - precip_min + 1) + precip_min;
        array[i].wind_speed = ((double)rand() / RAND_MAX) * (wind_max - wind_min) + wind_min;
    }

    return array;
}

void free_weather_array(weather_record* array) {
    if (array != NULL) {
        free(array);
    }
}

int main() {
    int num_records = 10;
    int precip_min = 0, precip_max = 50;
    double wind_min = 0.0, wind_max = 20.0;

    weather_record* weather_data = create_weather_array(num_records, precip_min, precip_max, wind_min, wind_max);
    if (weather_data != NULL) {
        // Process the weather data
        free_weather_array(weather_data);
    }

    return 0;
}
