#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SENSORS 1024

typedef struct SensorData {
    long timestamp;
    double measurement;
    char metadata[256];
} SensorData;

typedef struct SensorManager {
    SensorData *data[MAX_SENSORS];
    int count;
} SensorManager;

void sensor_manager_init(SensorManager *manager) {
    manager->count = 0;
}

int sensor_manager_add_data(SensorManager *manager, long timestamp, double measurement, const char *metadata) {
    if (manager->count >= MAX_SENSORS) {
        fprintf(stderr, "SensorManager is full\n");
        return -1;
    }
    SensorData *new_data = malloc(sizeof(SensorData));
    if (!new_data) {
        perror("Failed to allocate memory for sensor data");
        return -1;
    }
    new_data->timestamp = timestamp;
    new_data->measurement = measurement;
    strncpy(new_data->metadata, metadata, sizeof(new_data->metadata) - 1);
    new_data->metadata[sizeof(new_data->metadata) - 1] = '\0';
    manager->data[manager->count++] = new_data;
    return 0;
}

void sensor_manager_remove_data(SensorManager *manager, int index) {
    if (index < 0 || index >= manager->count) {
        fprintf(stderr, "Invalid index for removing sensor data\n");
        return;
    }
    free(manager->data[index]);
    for (int i = index; i < manager->count - 1; i++) {
        manager->data[i] = manager->data[i + 1];
    }
    manager->count--;
}

void sensor_manager_free(SensorManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->data[i]);
    }
    manager->count = 0;
}

// Example usage
int main() {
    SensorManager manager;
    sensor_manager_init(&manager);

    // Add some data
    sensor_manager_add_data(&manager, 1633072800, 23.5, "Temperature");
    sensor_manager_add_data(&manager, 1633072801, 45.0, "Humidity");

    // Remove some data
    sensor_manager_remove_data(&manager, 0);

    // Clean up
    sensor_manager_free(&manager);

    return 0;
}
```

This code provides a basic implementation of a `SensorManager` structure to manage sensor data in a networked environment. It includes functions to initialize the manager, add and remove sensor data entries, and free all allocated memory when done. The example usage demonstrates how to use these functions to manage sensor data.']

