void allocate_memory() {
    pthread_mutex_lock(&mutex);
    if (temperature_readings == NULL) {
        temperature_readings = (float*)malloc(sizeof(float) * max_records);
        identifiers = (char*)malloc(sizeof(char) * max_records);
        weather_records = (weather_record*)malloc(sizeof(weather_record) * max_records);
        if (temperature_readings == NULL || identifiers == NULL || weather_records == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
    pthread_mutex_unlock(&mutex);
}

void initialize_data() {
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        temperature_readings[i] = (float)(rand() % 100) / 10.0;
        identifiers[i] = 'A' + rand() % 26;
        weather_records[i].precipitation = rand() % 50;
        weather_records[i].wind_speed = (double)(rand() % 100) / 10.0;
    }
}

void* update_weather_data(void* arg) {
    int new_record = *(int*)arg;
    pthread_mutex_lock(&mutex);
    if (new_record >= max_records) {
        weather_record* new_records = realloc(weather_records, sizeof(weather_record) * max_records * 2);
        if (new_records == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
        weather_records = new_records;
        max_records *= 2;
    }
    weather_records[new_record].precipitation = rand() % 50;
    weather_records[new_record].wind_speed = (double)(rand() % 100) / 10.0;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void flush_memory() {
    pthread_mutex_lock(&mutex);
    if (num_records < max_records / 2) {
        weather_record* new_records = realloc(weather_records, sizeof(weather_record) * num_records);
        if (new_records == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
        weather_records = new_records;
        max_records = num_records;
    }
    pthread_mutex_unlock(&mutex);
}

void log_memory_usage() {
    printf("Current memory usage: %zu bytes\n", sizeof(float) * num_records + sizeof(char) * num_records + sizeof(weather_record) * num_records);
}
