    for (int i = 0; i < count; i++) {
        offsets[i] = i;
    }
    return offsets;
}

int* initializeKeys(int maxKey, int count) {
    if (count > maxKey) {
        fprintf(stderr, "Too many keys requested\n");
        exit(EXIT_FAILURE);
    }
    int* keys = customAllocator(count * sizeof(int));
    for (int i = 0; i < count; i++) {
        keys[i] = i + 1;
    }
    return keys;
}

record* initializeRecords(int count, int minValue, int maxValue) {
    record* records = customAllocator(count * sizeof(record));
    srand(time(NULL));
    int lastValue = minValue - 1;
    for (int i = 0; i < count; i++) {
        do {
            records[i].value = rand() % (maxValue - minValue + 1) + minValue;
        } while (records[i].value == lastValue);
        lastValue = records[i].value;
    }
    return records;
}

void logMemoryAllocation(size_t size) {
    // Log allocation details
}

void logMemoryDeallocation(size_t size) {
    // Log deallocation details
}

int findMax(int* array, int count) {
    int max = array[0];
    for (int i = 1; i < count; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void processAndFindMax() {
    int count = 1000; // Example size
    long* offsets = initializeOffsets(count);
    int* keys = initializeKeys(100, count);
    record* records = initializeRecords(count, 1, 1000);

    logMemoryAllocation(count * sizeof(long));
    logMemoryAllocation(count * sizeof(int));
    logMemoryAllocation(count * sizeof(record));

    // Process data and find max
    int* inputArray = customAllocator(count * sizeof(int));
    for (int i = 0; i < count; i++) {
        scanf("%d", &inputArray[i]);
    }

    int maxInput = findMax(inputArray, count);
    printf("Largest integer in input: %d\n", maxInput);

    logMemoryDeallocation(count * sizeof(int));

    freeCustomAllocator(offsets);
    freeCustomAllocator(keys);
    freeCustomAllocator(records);
    freeCustomAllocator(inputArray);
}

int main() {
    processAndFindMax();
    return 0;
}
