#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1 MB
#define MAX_EXTRA_DATA_SIZE 1024 // 1 KB
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int value;
    long* offset;
    int key;
    void* extra_data;
    void* metadata;
} record;

int allocate_records(int n, record** records, long** offsets, int** keys) {
    if (n * sizeof(record) + n * MAX_EXTRA_DATA_SIZE > MAX_MEMORY) {
        return -1; // Exceeds maximum memory
    }

    *records = malloc(n * sizeof(record));
    *offsets = malloc(n * sizeof(long));
    *keys = malloc(n * sizeof(int));

    if (!*records || !*offsets || !*keys) {
        free(*records);
        free(*offsets);
        free(*keys);
        return -2; // Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        (*records)[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        (*offsets)[i] = (long)((char*)*records + sizeof(record) * n + i * MAX_EXTRA_DATA_SIZE);
        (*keys)[i] = rand() % 256; // Random key for demonstration
        (*records)[i].extra_data = NULL;
        (*records)[i].metadata = malloc(sizeof(void*)); // Placeholder for metadata
    }

    return 0; // Success
}

void free_records(int n, record** records, long** offsets, int** keys) {
    for (int i = 0; i < n; i++) {
        if ((*records)[i].extra_data != NULL) {
            free((*records)[i].extra_data);
        }
        free((*records)[i].metadata);
    }

    free(*records);
    free(*offsets);
    free(*keys);
}
