#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024
#define MAX_TRANSACTION_AMOUNT 1000.00
#define MIN_TRANSACTION_AMOUNT 0.01

typedef struct {
    uint64_t id;
    int timestamp;
    double amount;
} Transaction;

typedef struct {
    Transaction* transactions;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} TransactionList;

void init_transaction_list(TransactionList* list) {
    list->transactions = (Transaction*)malloc(INITIAL_CAPACITY * sizeof(Transaction));
    if (!list->transactions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void resize_transaction_list(TransactionList* list) {
    size_t new_capacity = list->capacity * 2;
    Transaction* new_transactions = (Transaction*)realloc(list->transactions, new_capacity * sizeof(Transaction));
    if (!new_transactions) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->transactions = new_transactions;
    list->capacity = new_capacity;
}

void insert_transaction(TransactionList* list, Transaction transaction) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        resize_transaction_list(list);
    }
    list->transactions[list->size++] = transaction;
    pthread_mutex_unlock(&list->mutex);
}

Transaction* get_transaction_by_id(TransactionList* list, uint64_t id) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->transactions[i].id == id) {
            return &list->transactions[i];
        }
    }
    return NULL;
}

void update_transaction_amount(TransactionList* list, uint64_t id, double new_amount) {
    pthread_mutex_lock(&list->mutex);
    Transaction* transaction = get_transaction_by_id(list, id);
    if (transaction && new_amount >= MIN_TRANSACTION_AMOUNT && new_amount <= MAX_TRANSACTION_AMOUNT) {
        transaction->amount = new_amount;
    }
    pthread_mutex_unlock(&list->mutex);
}

void remove_transaction(TransactionList* list, uint64_t id) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->transactions[i].id == id) {
            memmove(&list->transactions[i], &list->transactions[i + 1], (list->size - i - 1) * sizeof(Transaction));
            --list->size;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_transaction_list(TransactionList* list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->transactions);
}

int main() {
    TransactionList list;
    init_transaction_list(&list);

    // Example usage
    Transaction transaction = {1234567890, 1633072800, 100.0};
    insert_transaction(&list, transaction);

    Transaction* retrieved_transaction = get_transaction_by_id(&list, 1234567890);
    if (retrieved_transaction) {
        printf("Transaction ID: %llu, Amount: %.2f\n", retrieved_transaction->id, retrieved_transaction->amount);
    }

    update_transaction_amount(&list, 1234567890, 200.0);

    remove_transaction(&list, 1234567890);

    free_transaction_list(&list);

    return 0;
}
