#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEY_VALUE 1000
#define INITIAL_ARRAY_SIZE 10

typedef struct {
    long offset;
    int key;
    struct {
        int value;
    } record;
} Record;

typedef struct {
    int rnti;
    struct TransportChannelConfig {
        int logicalChannelIdentity;
    } config;
} MAC_TransportChannelInfo;

Record* createDynamicArray(int initialSize) {
    return (Record*)malloc(initialSize * sizeof(Record));
}

void freeDynamicArray(Record* array, int size) {
    free(array);
}

int compareRecords(const void* a, const void* b) {
    Record* recA = (Record*)a;
    Record* recB = (Record*)b;
    return recA->key - recB->key;
}

void initializeDynamicArray(Record* array, int size, int maxKeyValue) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        array[i].offset = i * sizeof(Record);
        array[i].key = rand() % maxKeyValue + 1;
        while (i > 0 && array[i].key == array[i - 1].key) {
            array[i].key = rand() % maxKeyValue + 1;
        }
        array[i].record.value = rand();
    }
}

void* manageTransportChannels(void* arg) {
    MAC_TransportChannelInfo* channels = (MAC_TransportChannelInfo*)arg;
    int numChannels = sizeof(channels) / sizeof(MAC_TransportChannelInfo);

    Record* records = createDynamicArray(INITIAL_ARRAY_SIZE);
    initializeDynamicArray(records, INITIAL_ARRAY_SIZE, MAX_KEY_VALUE);

    qsort(records, INITIAL_ARRAY_SIZE, sizeof(Record), compareRecords);

    // Simulate network configuration validation and DNS resolution
    for (int i = 0; i < numChannels; i++) {
        if (channels[i].config.logicalChannelIdentity == -1) {
            channels[i].config.logicalChannelIdentity = rand() % MAX_KEY_VALUE + 1;
        }
        // Placeholder for DNS resolution logic
        printf("Resolved hostname for rnti: %d\n", channels[i].rnti);
    }

    freeDynamicArray(records, INITIAL_ARRAY_SIZE);
    return NULL;
}

int main() {
    MAC_TransportChannelInfo channels[] = {
        {1, {0}},
        {2, {0}},
        {3, {0}}
    };

    pthread_t thread;
    if (pthread_create(&thread, NULL, manageTransportChannels, channels) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    return EXIT_SUCCESS;
}
```

This code snippet provides a basic structure for managing and initializing a dynamic array of structured records in C. It includes functions for creating and freeing the dynamic array, initializing it with random values, sorting the records by key, and simulating network configuration validation and DNS resolution. The `manageTransportChannels` function demonstrates how to handle concurrent access using pthreads and manage resources safely.']

