// Define a structure for linked list nodes
typedef struct Node {
    char* word;
    struct Node* next;
} Node;

// Function to allocate memory and initialize an array of strings
char** allocateAndInitializeArray(int size) {
    char** array = (char**)malloc(size * sizeof(char*));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    for (int i = 0; i < size; i++) {
        array[i] = (char*)malloc(256 * sizeof(char)); // Assuming max word length
        if (array[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
    return array;
}

// Function to tokenize text into words and store in linked list
Node* tokenizeAndStore(const char* text) {
    Node* head = NULL;
    Node** current = &head;
    char* token = strtok((char*)text, " ,.!?;:");
    while (token != NULL) {
        *current = (Node*)malloc(sizeof(Node));
        if (*current == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        (*current)->word = strdup(token);
        (*current)->next = NULL;
        current = &(*current)->next;
        token = strtok(NULL, " ,.!?;:");
    }
    return head;
}

// Nested function to generate a random string
char* generateRandomString(int length, const char* charset) {
    int charsetLength = strlen(charset);
    char* result = (char*)malloc((length + 1) * sizeof(char));
    if (result == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    for (int i = 0; i < length; i++) {
        int index = rand() % charsetLength;
        result[i] = charset[index];
    }
    result[length] = '\0';
    return result;
}

// Function to hash a password
unsigned long hashPassword(const char* password) {
    unsigned long hash = 5381;
    int c;
    while ((c = *password++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}

// Helper function to calculate linguistic metrics
void calculateMetrics(Node* head, char** array, int size) {
    // Implement linguistic metrics calculation here
}

