    char** documents = allocateAndInitializeArray(size);

    // Populate documents with text from file or other source

    Node* wordList = tokenizeAndStore(documents[0]);

    // Read lines from standard input until end-of-input marker

    const char* charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char* randomString = generateRandomString(10, charset);

    unsigned long passwordHash = hashPassword("examplePassword");

    calculateMetrics(wordList, documents, size);

    // Free allocated memory
    Node* current = wordList;
    while (current != NULL) {
        Node* next = current->next;
        free(current->word);
        free(current);
        current = next;
    }
    for (int i = 0; i < size; i++) {
        free(documents[i]);
    }
    free(documents);
