#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    double x;
    double y;
    double z;
} Point;

enum Status {
    STATUS_OK,
    STATUS_WARNING,
    STATUS_ERROR
};

uint64_t generate_unique_id() {
    static uint64_t id = 0;
    return ++id;
}

double generate_double(double min, double max) {
    return min + (max - min) * ((double)rand() / RAND_MAX);
}

char* generate_string(size_t length) {
    char* str = malloc(length + 1);
    if (!str) return NULL;
    for (size_t i = 0; i < length; ++i) {
        str[i] = 'a' + rand() % 26;
    }
    str[length] = '\0';
    return str;
}

Point generate_point(double plane_eq[4]) {
    Point p;
    do {
        p.x = generate_double(-100, 100);
        p.y = generate_double(-100, 100);
        p.z = (plane_eq[0] * p.x + plane_eq[1] * p.y + plane_eq[2]) / -plane_eq[3];
    } while (p.x * p.x + p.y * p.y + p.z * p.z > 10000); // Sphere constraint
    return p;
}

enum Status generate_status(double value) {
    if (value < 0.5) return STATUS_OK;
    else if (value < 0.9) return STATUS_WARNING;
    else return STATUS_ERROR;
}

void initialize_data_structures() {
    srand(time(NULL));

    double* doubles = malloc(5 * sizeof(double));
    char** strings = malloc(5 * sizeof(char*));
    Point* points = malloc(5 * sizeof(Point));
    enum Status* statuses = malloc(5 * sizeof(enum Status));
    uint64_t* ids = malloc(5 * sizeof(uint64_t));

    if (!doubles || !strings || !points || !statuses || !ids) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    double plane_eq[4] = {1, 2, 3, -10}; // Example plane equation

    for (int i = 0; i < 5; ++i) {
        doubles[i] = generate_double(-1e9, 1e9);
        strings[i] = generate_string(10);
        points[i] = generate_point(plane_eq);
        statuses[i] = generate_status(generate_double(0, 1));
        ids[i] = generate_unique_id();
    }

    // Simulate usage
    for (int i = 0; i < 5; ++i) {
        printf("Double: %f\n", doubles[i]);
        printf("String: %s\n", strings[i]);
        printf("Point: (%f, %f, %f)\n", points[i].x, points[i].y, points[i].z);
        printf("Status: %d\n", statuses[i]);
        printf("ID: %" PRIu64 "\n", ids[i]);
    }

    // Free allocated memory
    for (int i = 0; i < 5; ++i) {
        free(strings[i]);
    }
    free(doubles);
    free(strings);
    free(points);
    free(statuses);
    free(ids);
}

int main() {
    initialize_data_structures();
    return 0;
}
