#define MAX_EXTRA_DATA_SIZE 1024 // 1KB
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int value;
    long* offset;
    int key;
    void* extra_data;
} record;

int allocate_records(int n, record** records, long** offsets, void*** extra_data, int mode) {
    if (n > MAX_MEMORY / sizeof(record)) {
        return -1; // Exceeds maximum memory limit
    }

    *records = malloc(n * sizeof(record));
    *offsets = malloc(n * sizeof(long));
    *extra_data = malloc(n * sizeof(void*));

    if (!(*records) || !(*offsets) || !(*extra_data)) {
        free(*records);
        free(*offsets);
        free(*extra_data);
        return -2; // Memory allocation failed
    }

    srand(time(NULL));
    long total_memory_used = 0;

    for (int i = 0; i < n; i++) {
        (*records)[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        (*offsets)[i] = (long)((char*)*records + sizeof(record) * i);

        if (mode == 0) { // Compressed mode
            int extra_size = rand() % MAX_EXTRA_DATA_SIZE;
            if (total_memory_used + sizeof(record) + extra_size > MAX_MEMORY) {
                free(*records);
                free(*offsets);
                free(*extra_data);
                return -3; // Exceeds maximum memory limit for a single record
            }
            (*records)[i].extra_data = malloc(extra_size);
            if (!(*records)[i].extra_data) {
                free(*records);
                free(*offsets);
                free(*extra_data);
                return -4; // Memory allocation failed for extra data
            }
            total_memory_used += sizeof(record) + extra_size;
        } else { // Uncompressed mode
            int extra_size = rand() % MAX_EXTRA_DATA_SIZE;
            if (total_memory_used + sizeof(record) + extra_size > MAX_MEMORY) {
                free(*records);
                free(*offsets);
                free(*extra_data);
                return -5; // Exceeds maximum memory limit for a single record
            }
            (*records)[i].extra_data = malloc(extra_size);
            if (!(*records)[i].extra_data) {
                free(*records);
                free(*offsets);
                free(*extra_data);
                return -6; // Memory allocation failed for extra data
            }
            total_memory_used += sizeof(record) + extra_size;
        }
    }

    return 0; // Success
}

void free_records(int n, record* records, long* offsets, void** extra_data) {
    for (int i = 0; i < n; i++) {
        free(extra_data[i]);
    }
    free(records);
    free(offsets);
    free(extra_data);
}
