NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_data_structures(size_t max_keys, size_t n_pdus, size_t memory_limit, int relax_rnti_uniqueness) {
    if (memory_limit < sizeof(NFAPI_CRC_INDICATION_PDU_T) * n_pdus) {
        fprintf(stderr, "Insufficient memory for NFAPI CRC PDUs\n");
        return NULL;
    }

    long *offsets = malloc(sizeof(long) * max_keys);
    int *keys_array = malloc(sizeof(int) * max_keys);
    Record *records = malloc(sizeof(Record) * max_keys);

    if (!offsets || !keys_array || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys_array);
        free(records);
        return NULL;
    }

    for (size_t i = 0; i < max_keys; ++i) {
        offsets[i] = i * sizeof(long);
        keys_array[i] = i + 1;
        records[i].value = i % 256;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n_pdus);
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed for PDUs\n");
        free(offsets);
        free(keys_array);
        free(records);
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    size_t rnti_count = 0;
    int last_rnti = -1;

    for (size_t i = 0; i < n_pdus; ++i) {
        if (!relax_rnti_uniqueness && i > 0 && pdus[i-1].rnti == pdus[i].rnti) {
            fprintf(stderr, "Duplicate RNTI detected: %d\n", pdus[i].rnti);
        } else {
            pdus[i].rx_tag = RX_UE_INFORMATION_TAG;
            pdus[i].rnti = last_rnti + 1;
            pdus[i].crc_tag = CRC_INDICATION_REL8_TAG;
            pdus[i].crcflag = rand() % 256;
            last_rnti = pdus[i].rnti;
        }
    }

    pthread_mutex_unlock(&mutex);

    log_largest_int_key(keys_array, max_keys);
    return pdus;
}
