import java.io.File;
import java.util.HashMap;
import java.util.Map;

public class MicroserviceOrchestrator {
    private Map<String, Service> services = new HashMap<>();
    private ConfigurationService configService;
    private NotificationService notificationService;
    private HealthMonitor healthMonitor;

    public MicroserviceOrchestrator(ConfigurationService configService, NotificationService notificationService) {
        this.configService = configService;
        this.notificationService = notificationService;
        this.healthMonitor = new HealthMonitor();
    }

    public void loadServices(String directoryPath) {
        File directory = new File(directoryPath);
        if (directory.exists() && directory.isDirectory()) {
            for (File file : directory.listFiles()) {
                if (file.isDirectory()) {
                    String serviceName = file.getName();
                    Service service = new Service(serviceName, configService.getServiceConfig(serviceName));
                    services.put(serviceName, service);
                    startService(serviceName);
                }
            }
        }
    }

    public void startService(String serviceName) {
        Service service = services.get(serviceName);
        if (service != null && !service.isRunning()) {
            try {
                service.start();
                healthMonitor.register(service);
                log("Service started: " + serviceName);
                sendNotification("Service started: " + serviceName);
            } catch (Exception e) {
                log("Failed to start service: " + serviceName, e);
                sendNotification("Failed to start service: " + serviceName);
            }
        }
    }

    public void stopService(String serviceName) {
        Service service = services.get(serviceName);
        if (service != null && service.isRunning()) {
            try {
                service.stop();
                healthMonitor.deregister(service);
                log("Service stopped: " + serviceName);
                sendNotification("Service stopped: " + serviceName);
            } catch (Exception e) {
                log("Failed to stop service: " + serviceName, e);
                sendNotification("Failed to stop service: " + serviceName);
            }
        }
    }

    public void monitorServices() {
        for (Service service : services.values()) {
            if (!service.isHealthy()) {
                try {
                    restartService(service.getName());
                } catch (Exception e) {
                    log("Failed to restart service: " + service.getName(), e);
                    sendNotification("Failed to restart service: " + service.getName());
                }
            }
        }
    }

    public void restartService(String serviceName) throws Exception {
        stopService(serviceName);
        Thread.sleep(configService.getRestartDelay(serviceName));
        startService(serviceName);
    }

    private void log(String message, Exception e) {
        System.err.println(message);
        if (e != null) {
            e.printStackTrace();
        }
    }

    private void sendNotification(String message) {
        notificationService.send(message);
    }

    public static void main(String[] args) {
        ConfigurationService configService = new ConfigurationService("config");
        NotificationService notificationService = new NotificationService("broker");
        MicroserviceOrchestrator orchestrator = new MicroserviceOrchestrator(configService, notificationService);
        orchestrator.loadServices("services");
        while (true) {
            orchestrator.monitorServices();
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
}

