#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024
#define MAX_RETRIES 10

typedef struct {
    int key;
    long offset;
    bool status;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordArray;

RecordArray* create_record_array() {
    RecordArray* array = (RecordArray*)malloc(sizeof(RecordArray));
    if (!array) return NULL;
    array->records = (Record*)calloc(INITIAL_CAPACITY, sizeof(Record));
    if (!array->records) {
        free(array);
        return NULL;
    }
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_record_array(RecordArray* array) {
    if (array) {
        pthread_mutex_lock(&array->lock);
        free(array->records);
        pthread_mutex_unlock(&array->lock);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

bool add_record(RecordArray* array, int key, long offset) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Record* new_records = (Record*)realloc(array->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&array->lock);
            return false;
        }
        array->records = new_records;
        array->capacity = new_capacity;
    }

    for (size_t i = 0; i < array->size; ++i) {
        if (array->records[i].key == key || array->records[i].offset == offset) {
            pthread_mutex_unlock(&array->lock);
            return false;
        }
    }

    array->records[array->size].key = key;
    array->records[array->size].offset = offset;
    array->records[array->size].status = true;
    ++array->size;
    pthread_mutex_unlock(&array->lock);
    return true;
}

int main() {
    RecordArray* array = create_record_array();
    if (!array) {
        fprintf(stderr, "Failed to create record array\n");
        return 1;
    }

    for (int i = 0; i < 10000; ++i) {
        int key = rand() % 100000;
        long offset = rand() % 1000000000L;
        if (!add_record(array, key, offset)) {
            fprintf(stderr, "Failed to add record with key %d and offset %ld\n", key, offset);
        }
    }

    destroy_record_array(array);
    return 0;
}
