#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int offset;
    char key[256];
    void* record;
} Record;

typedef struct {
    size_t capacity;
    size_t size;
    Record* records;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->size = 0;
    pool->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    if (pool) {
        for (size_t i = 0; i < pool->size; ++i) {
            free(pool->records[i].record);
        }
        free(pool->records);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

Record* allocate_record(MemoryPool* pool, int offset, const char* key, size_t record_size) {
    if (!pool || !key || record_size == 0) return NULL;

    pthread_mutex_lock(&pool->lock);

    if (pool->size >= pool->capacity) {
        Record* new_records = (Record*)realloc(pool->records, pool->capacity * 2 * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->records = new_records;
        pool->capacity *= 2;
    }

    Record* record = &pool->records[pool->size++];
    record->offset = offset;
    strncpy(record->key, key, sizeof(record->key) - 1);
    record->record = malloc(record_size);
    if (!record->record) {
        pool->size--;
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    pthread_mutex_unlock(&pool->lock);
    return record;
}

void free_record(MemoryPool* pool, Record* record) {
    if (!pool || !record) return;

    pthread_mutex_lock(&pool->lock);

    size_t index = (size_t)(record - pool->records);
    if (index < pool->size) {
        free(record->record);
        record->record = NULL;
        // Optionally, mark the slot as free for reuse
    }

    pthread_mutex_unlock(&pool->lock);
}
