typedef struct {
    time_t timestamp;
    int log_id;
    char message[256];
} LogEntry;

LogEntry* init_log_entries(int n, int min_timestamp, int max_timestamp, int min_log_id, int max_log_id) {
    if (n <= 0 || min_timestamp >= max_timestamp || min_log_id >= max_log_id) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    LogEntry* log_entries = malloc(n * sizeof(LogEntry));
    if (!log_entries) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < n; ) {
        time_t timestamp = min_timestamp + rand() % (max_timestamp - min_timestamp);
        int log_id = min_log_id + rand() % (max_log_id - min_log_id);

        // Check for uniqueness and validity
        int is_unique = 1;
        for (int j = 0; j < i; j++) {
            if (log_entries[j].timestamp == timestamp || log_entries[j].log_id == log_id) {
                is_unique = 0;
                break;
            }
        }

        if (is_unique) {
            log_entries[i].timestamp = timestamp;
            log_entries[i].log_id = log_id;
            snprintf(log_entries[i].message, sizeof(log_entries[i].message), "Log entry %d", i + 1);
            i++;
        }
    }

    return log_entries;
}

void free_log_entries(LogEntry* log_entries, int n) {
    if (log_entries) {
        free(log_entries);
    }
}
