#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* name;
    int quantity;
    float price;
} Product;

typedef struct Node {
    Product product;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} ProductCollection;

ProductCollection* create_product_collection() {
    ProductCollection* collection = (ProductCollection*)malloc(sizeof(ProductCollection));
    if (!collection) return NULL;
    collection->head = NULL;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void destroy_product_collection(ProductCollection* collection) {
    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        free(current->product.name);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_product(ProductCollection* collection, const char* name, int quantity, float price) {
    if (!collection || !name) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->product.name = strdup(name);
    new_node->product.quantity = quantity;
    new_node->product.price = price;
    new_node->next = NULL;

    pthread_mutex_lock(&collection->mutex);
    new_node->next = collection->head;
    collection->head = new_node;
    pthread_mutex_unlock(&collection->mutex);

    return 0;
}

int update_quantity(ProductCollection* collection, const char* name, int quantity) {
    if (!collection || !name) return -1;

    pthread_mutex_lock(&collection->mutex);
    Node* current = collection->head;
    while (current) {
        if (strcmp(current->product.name, name) == 0) {
            current->product.quantity += quantity;
            pthread_mutex_unlock(&collection->mutex);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->mutex);
    return -1;
}

float calculate_total_value(ProductCollection* collection) {
    if (!collection) return -1.0;

    float total = 0.0;
    pthread_mutex_lock(&collection->mutex);
    Node* current = collection->head;
    while (current) {
        total += current->product.quantity * current->product.price;
        current = current->next;
    }
    pthread_mutex_unlock(&collection->mutex);
    return total;
}
