#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1024

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int head;
    int tail;
    int count;
    pthread_mutex_t lock;
} CircularBuffer;

void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->lock, NULL);
}

int is_full(CircularBuffer *buffer) {
    return (buffer->count == MAX_RECORDS);
}

int is_empty(CircularBuffer *buffer) {
    return (buffer->count == 0);
}

void enqueue(CircularBuffer *buffer, Record record) {
    pthread_mutex_lock(&buffer->lock);
    if (!is_full(buffer)) {
        buffer->records[buffer->tail] = record;
        buffer->tail = (buffer->tail + 1) % MAX_RECORDS;
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->lock);
}

Record dequeue(CircularBuffer *buffer) {
    Record record;
    pthread_mutex_lock(&buffer->lock);
    if (!is_empty(buffer)) {
        record = buffer->records[buffer->head];
        buffer->head = (buffer->head + 1) % MAX_RECORDS;
        buffer->count--;
    } else {
        record.value = -1; // Indicate empty
    }
    pthread_mutex_unlock(&buffer->lock);
    return record;
}

void *log_thread(void *arg) {
    CircularBuffer *buffer = (CircularBuffer *)arg;
    while (1) {
        Record record = dequeue(buffer);
        if (record.value != -1) {
            // Log to file and console
            printf("Logged: Offset=%ld, Key=%d, Value=%d\n", record.offset, record.key, record.value);
            // Simulate logging to a file
            FILE *file = fopen("log.txt", "a");
            fprintf(file, "Offset=%ld, Key=%d, Value=%d\n", record.offset, record.key, record.value);
            fclose(file);
        }
    }
    return NULL;
}

void *repair_thread(void *arg) {
    CircularBuffer *buffer = (CircularBuffer *)arg;
    while (1) {
        // Check for and repair corrupted records
        pthread_mutex_lock(&buffer->lock);
        if (!is_empty(buffer)) {
            Record record = buffer->records[buffer->head];
            if (record.value == -2) { // Example of a corrupted value
                record.value = 0; // Repair
                buffer->records[buffer->head] = record;
            }
        }
        pthread_mutex_unlock(&buffer->lock);
    }
    return NULL;
}

int main() {
    CircularBuffer buffer;
    init_buffer(&buffer);

    pthread_t log_tid, repair_tid;
    pthread_create(&log_tid, NULL, log_thread, &buffer);
    pthread_create(&repair_tid, NULL, repair_thread, &buffer);

    // Example usage
    Record record = {12345, 67890, rand() % 100};
    enqueue(&buffer, record);

    pthread_join(log_tid, NULL);
    pthread_join(repair_tid, NULL);

    return 0;
}
