typedef struct {
    char* name;
    int stock_quantity;
    float price;
    double discount_percentage;
} Product;

typedef struct {
    Product** products;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} ProductCollection;

ProductCollection* create_product_collection() {
    ProductCollection* collection = (ProductCollection*)malloc(sizeof(ProductCollection));
    if (!collection) return NULL;
    collection->products = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void destroy_product_collection(ProductCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->products[i]->name);
        free(collection->products[i]);
    }
    free(collection->products);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

void add_product(ProductCollection* collection, const char* name, int stock_quantity, float price, double discount_percentage) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        Product** new_products = (Product**)realloc(collection->products, new_capacity * sizeof(Product*));
        if (!new_products) {
            pthread_mutex_unlock(&collection->mutex);
            return;
        }
        collection->products = new_products;
        collection->capacity = new_capacity;
    }
    Product* product = (Product*)malloc(sizeof(Product));
    if (!product) {
        pthread_mutex_unlock(&collection->mutex);
        return;
    }
    product->name = strdup(name);
    product->stock_quantity = stock_quantity;
    product->price = price;
    product->discount_percentage = discount_percentage;
    collection->products[collection->count++] = product;
    pthread_mutex_unlock(&collection->mutex);
}

// Additional functions for updating stock, calculating revenue, retrieving products, filtering, and removing products would be implemented here.

