#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_EXTRA_DATA_SIZE 1024
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int rnti;
    TransportChannelConfig config;
} MAC_TransportChannelInfo;

typedef struct {
    int logicalChannelIdentity;
    char* extraData;
} TransportChannelConfig;

void initializeTransportChannels(MAC_TransportChannelInfo** channels, int n, const char* mode) {
    srand(time(NULL));
    int totalMemory = 0;
    int offsetArraySize = n * sizeof(int);
    int sharedExtraDataSize = 0;
    int extraDataOffset = offsetArraySize;

    // Allocate memory for the array of offsets
    channels[0] = (MAC_TransportChannelInfo*)malloc(offsetArraySize + MAX_MEMORY);
    if (!channels[0]) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    int* offsets = (int*)((char*)channels[0] + offsetArraySize);

    for (int i = 0; i < n; i++) {
        offsets[i] = extraDataOffset;
        channels[0][i].rnti = MIN_VALUE + rand() % (MAX_VALUE - MIN_VALUE + 1);
        channels[0][i].config.logicalChannelIdentity = i;

        if (strcmp(mode, "compressed") == 0) {
            // Share common extra data segments
            if (i == 0) {
                sharedExtraDataSize = MAX_EXTRA_DATA_SIZE;
                channels[0][i].config.extraData = (char*)((char*)channels[0] + offsetArraySize + n * sizeof(int));
            } else {
                channels[0][i].config.extraData = channels[0][0].config.extraData;
            }
        } else {
            // Allocate unique extra data for each record
            channels[0][i].config.extraData = (char*)((char*)channels[0] + offsetArraySize + n * sizeof(int) + i * MAX_EXTRA_DATA_SIZE);
        }

        totalMemory += sizeof(MAC_TransportChannelInfo) + sharedExtraDataSize;
    }

    // Set the 'long' pointer in each record to point to the corresponding offset in the offset array
    for (int i = 0; i < n; i++) {
        channels[0][i].config.extraData = (char*)((char*)channels[0] + offsets[i]);
    }
}
