int process_large_list(const char* filename, int N) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    // Dynamically allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory");
        fclose(file);
        return -1;
    }

    // Populate the array with random data
    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 1000;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    // Process the file and calculate the sum of even integers
    int sum_of_evens = 0;
    while (!feof(file)) {
        int num;
        if (fscanf(file, "%d", &num) == 1) {
            if (num % 2 == 0) {
                sum_of_evens += num;
            }
        }
    }

    // Free the allocated memory
    free(array);
    fclose(file);

    return sum_of_evens;
}
