public function processBatchOfStrings($strings) {
    $hashes = [];
    $maxHashesPerRequest = 100;

    foreach ($strings as $string) {
        if (strlen($string) > 1000) {
            throw new Exception('String length exceeds limit');
        }

        try {
            $md5Hash = md5($string);
            if (!in_array($md5Hash, $hashes)) {
                $hashes[] = $md5Hash;
            }

            if (count($hashes) >= $maxHashesPerRequest) {
                break;
            }
        } catch (Exception $e) {
            // Handle exceptions gracefully
            error_log('Error processing string: ' . $e->getMessage());
        }
    }

    return $hashes;
}

