#define MAX_LINE_LENGTH 1024
#define MAX_WORD_LENGTH 256

typedef struct Node {
    char word[MAX_WORD_LENGTH];
    int frequency;
    struct Node* next;
} Node;

Node* createNode(const char* word) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    strncpy(newNode->word, word, MAX_WORD_LENGTH - 1);
    newNode->frequency = 1;
    newNode->next = NULL;
    return newNode;
}

void insertWord(Node** hashTable, const char* word) {
    int index = hashFunction(word); // Assume hashFunction is defined elsewhere
    Node* newNode = createNode(word);
    if (hashTable[index] == NULL) {
        hashTable[index] = newNode;
    } else {
        Node* current = hashTable[index];
        while (current->next != NULL && strcmp(current->word, word) != 0) {
            current = current->next;
        }
        if (strcmp(current->word, word) == 0) {
            current->frequency++;
        } else {
            current->next = newNode;
        }
    }
}

void freeHashTable(Node** hashTable, int size) {
    for (int i = 0; i < size; i++) {
        Node* current = hashTable[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(hashTable);
}

void processAndAnalyzeText() {
    char** lines = (char**)malloc(MAX_LINE_LENGTH * sizeof(char*));
    if (lines == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int lineCount = 0;
    while ((lines[lineCount] = fgets(lines[lineCount], MAX_LINE_LENGTH, stdin)) != NULL) {
        // Trim leading and trailing whitespace
        lines[lineCount][strcspn(lines[lineCount], "\r\n")] = '\0';
        if (strlen(lines[lineCount]) == 0) break;
        lineCount++;
    }

    Node** hashTable = (Node**)calloc(100, sizeof(Node*)); // Assuming a simple hash table size
    if (hashTable == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < lineCount; i++) {
        char* token = strtok(lines[i], " ,.!?");
        while (token != NULL) {
            insertWord(hashTable, token);
            token = strtok(NULL, " ,.!?");
        }
    }

    // Calculate and output average word length, longest word, and its frequency
    // ...

    freeHashTable(hashTable, 100); // Assuming a simple hash table size
    for (int i = 0; i < lineCount; i++) {
        free(lines[i]);
    }
    free(lines);
}

int main() {
    processAndAnalyzeText();
    return 0;
}
