    char connectionConfig[256];
    int bandwidthReservations[BANDWIDTH_RESERVATIONS];
} NetworkElementState;

typedef struct {
    char hexdigest[33];
    double processingTime;
} Result;

Result initializeAndPopulateNetworkElements() {
    NetworkElementState networkElements[MAX_NETWORK_ELEMENTS];
    Result result;
    clock_t start, end;
    double cpu_time_used;

    start = clock();

    for (int i = 0; i < MAX_NETWORK_ELEMENTS; i++) {
        networkElements[i].neId = i + 1;
        snprintf(networkElements[i].connectionConfig, sizeof(networkElements[i].connectionConfig), "Config_%d", i);

        // Simulate bandwidth reservations
        for (int j = 0; j < BANDWIDTH_RESERVATIONS; j++) {
            networkElements[i].bandwidthReservations[j] = rand() % 100;
        }

        // Simulate policy validation and contention handling
        if (i % 10 == 0) {
            printf("Processing element %d\n", i);
        }
    }

    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;

    result.processingTime = cpu_time_used;
    // Simulate hash generation
    snprintf(result.hexdigest, sizeof(result.hexdigest), "%x", rand());

    return result;
}

int main() {
    Result result = initializeAndPopulateNetworkElements();
    printf("Hex Digest: %s\nProcessing Time: %.2f seconds\n", result.hexdigest, result.processingTime);
    return 0;
}
