#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define N 100

typedef struct {
    int value;
    int priority;
    time_t timestamp;
    bool backup_flag;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

void initList(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insertNode(DoublyLinkedList* list, Record data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->data = data;
    newNode->next = NULL;
    newNode->prev = list->tail;

    if (list->tail) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;

    pthread_mutex_lock(&list->lock);
    // Perform any necessary synchronization here
    pthread_mutex_unlock(&list->lock);
}

void deleteNode(DoublyLinkedList* list, Node* node) {
    if (!node) return;

    if (node->prev) {
        node->prev->next = node->next;
    } else {
        list->head = node->next;
    }

    if (node->next) {
        node->next->prev = node->prev;
    } else {
        list->tail = node->prev;
    }

    free(node);

    pthread_mutex_lock(&list->lock);
    // Perform any necessary synchronization here
    pthread_mutex_unlock(&list->lock);
}

void* manageCRCIndications(void* arg) {
    DoublyLinkedList list;
    initList(&list);

    for (int i = 0; i < N; i++) {
        Record record;
        record.value = rand() % 1000;
        record.priority = (i % 2 == 0) ? (rand() % 5 + 1) : (rand() % 5);
        time_t now = time(NULL);
        record.timestamp = now + (rand() % 60 - 30) * 60;
        record.backup_flag = (i % 2 == 0);

        insertNode(&list, record);
    }

    // Simulate real-time updates
    for (int i = 0; i < N / 10; i++) {
        Node* node = list.head;
        while (node) {
            if (rand() % 2 == 0) {
                deleteNode(&list, node);
                break;
            }
            node = node->next;
        }
    }

    // Clean up
    Node* current = list.head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list.lock);
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t thread;
    pthread_create(&thread, NULL, manageCRCIndications, NULL);
    pthread_join(thread, NULL);
    return 0;
}
