        $transaction = $db->beginTransaction();

        try {
            $stmt = $db->prepare("UPDATE users SET password = :password WHERE id = :id");
            $stmt->execute([':password' => hash('sha256', $newPassword), ':id' => $userId]);
            $transaction->commit();
        } catch (Exception $e) {
            $transaction->rollBack();
            throw $e;
        }

        logUpdateAttempt($userId, true);
    }
