#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define END "END"

typedef struct {
    char **lines;
    size_t count;
    size_t capacity;
} TextStream;

void initTextStream(TextStream *stream) {
    stream->lines = NULL;
    stream->count = 0;
    stream->capacity = 0;
}

void freeTextStream(TextStream *stream) {
    for (size_t i = 0; i < stream->count; ++i) {
        free(stream->lines[i]);
    }
    free(stream->lines);
    initTextStream(stream);
}

int addLineToStream(TextStream *stream, const char *line) {
    if (stream->count >= stream->capacity) {
        size_t new_capacity = (stream->capacity == 0) ? 1 : stream->capacity * 2;
        char **new_lines = realloc(stream->lines, new_capacity * sizeof(char *));
        if (!new_lines) return -1;
        stream->lines = new_lines;
        stream->capacity = new_capacity;
    }
    size_t line_length = strlen(line);
    if (line_length > MAX_LINE_LENGTH) {
        line_length = MAX_LINE_LENGTH;
    }
    char *new_line = malloc((line_length + 1) * sizeof(char));
    if (!new_line) return -1;
    strncpy(new_line, line, line_length);
    new_line[line_length] = '\0';
    stream->lines[stream->count++] = new_line;
    return 0;
}

void* processStream(void *arg) {
    int fd = *(int*)arg;
    TextStream *stream = malloc(sizeof(TextStream));
    initTextStream(stream);

    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, sizeof(buffer), fd)) {
        // Trim leading and trailing whitespace
        size_t len = strlen(buffer);
        while (len > 0 && isspace((unsigned char)buffer[len - 1])) {
            buffer[--len] = '\0';
        }
        if (len == 0 || strchr(buffer, '\0') != &buffer[len]) continue;

        // Check for null characters
        if (strchr(buffer, '\0') != &buffer[len]) continue;

        addLineToStream(stream, buffer);
    }

    close(fd);
    free(arg);
    return stream;
}

void analyzeAndReport(TextStream *streams[], size_t num_streams) {
    // Implement analysis and reporting logic here
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return 1;
    }

    pthread_t threads[argc - 1];
    TextStream *streams[argc - 1];

    for (int i = 1; i < argc; ++i) {
        int fd = open(argv[i], O_RDONLY);
        if (fd == -1) {
            perror("Failed to open file");
            return 1;
        }

        int *arg = malloc(sizeof(int));
        *arg = fd;

        if (pthread_create(&threads[i - 1], NULL, processStream, arg) != 0) {
            perror("Failed to create thread");
            close(fd);
            free(arg);
            return 1;
        }
    }

    for (int i = 0; i < argc - 1; ++i) {
        if (pthread_join(threads[i], (void **)&streams[i]) != 0) {
            perror("Failed to join thread");
            freeTextStream(streams[i]);
            return 1;
        }
    }

    analyzeAndReport(streams, argc - 1);

    for (int i = 0; i < argc - 1; ++i) {
        freeTextStream(streams[i]);
    }

    return 0;
}
