void initialize_data_structures(long size_limit, int max_key, int key_reservations[], int record_count, double start_time, double end_time, char **labels, int label_count) {
    long *offsets = (long *)malloc(size_limit * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return;
    }

    int *keys = (int *)malloc(max_key * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        free(offsets);
        return;
    }

    record *records = (record *)malloc(record_count * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(offsets);
        free(keys);
        return;
    }

    double *timestamps = (double *)malloc(record_count * sizeof(double));
    if (!timestamps) {
        fprintf(stderr, "Memory allocation failed for timestamps.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    char **labels_used = (char **)malloc(label_count * sizeof(char *));
    if (!labels_used) {
        fprintf(stderr, "Memory allocation failed for labels used.\n");
        free(offsets);
        free(keys);
        free(records);
        free(timestamps);
        return;
    }

    // Initialize offsets
    for (long i = 0; i < size_limit; ++i) {
        offsets[i] = i * 1024; // Example initialization logic
    }

    // Populate keys with unique values, reserving certain keys
    int key_index = 0;
    while (key_index < max_key) {
        if (!is_reserved(key_reservations, key_index)) {
            keys[key_index] = key_index;
            ++key_index;
        }
    }

    // Populate records with random numbers and unique labels
    srand(time(NULL));
    for (int i = 0; i < record_count; ++i) {
        int value;
        do {
            value = rand() % max_key;
        } while (i > 0 && records[i - 1].value == value);
        records[i].value = value;

        char *label;
        do {
            label = select_label(labels, label_count, labels_used);
        } while (i > 0 && strcmp(records[i - 1].label, label) == 0);
        records[i].label = strdup(label);
    }

    // Generate timestamps
    double time_step = (end_time - start_time) / record_count;
    for (int i = 0; i < record_count; ++i) {
        timestamps[i] = start_time + i * time_step;
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    for (int i = 0; i < record_count; ++i) {
        free(records[i].label);
    }
    free(records);
    free(timestamps);
    free(labels_used);

    printf("Data structures initialized successfully.\n");
}

// Helper functions
int is_reserved(int *reservations, int key) {
    for (int i = 0; reservations[i] != -1; ++i) {
        if (reservations[i] == key) {
            return 1;
        }
    }
    return 0;
}

char *select_label(char **labels, int label_count, char **labels_used) {
    // Efficiently select a unique label
    // Implementation details depend on the specific requirements and constraints
    return labels[rand() % label_count];
}
