void initialize_data(long** offsets, int** keys, record** records, double** timestamps, char*** labels,
                     int* key_usage, double* total_duration, int max_keys) {
    // Initialize offsets
    *offsets = (long*)malloc(5 * sizeof(long));
    for (int i = 0; i < 5; i++) {
        (*offsets)[i] = i;
    }

    // Initialize keys
    *keys = (int*)malloc(max_keys * sizeof(int));
    srand(time(NULL));
    int used_keys = 0;
    while (used_keys < max_keys) {
        int key = rand() % max_keys;
        if (!key_usage[key]) {
            (*keys)[used_keys++] = key;
            key_usage[key]++;
        }
    }

    // Initialize records
    *records = (record*)malloc(5 * sizeof(record));
    for (int i = 0; i < 5; i++) {
        (*records)[i].value = rand() % VALUE_RANGE;
        while (i > 0 && (*records)[i].value == (*records)[i - 1].value) {
            (*records)[i].value = rand() % VALUE_RANGE;
        }
        char* label = labels[rand() % LABEL_POOL_SIZE];
        while (i > 0 && strcmp((*records)[i].label, label) == 0) {
            label = labels[rand() % LABEL_POOL_SIZE];
        }
        (*records)[i].label = label;
    }

    // Initialize timestamps
    *timestamps = (double*)malloc(5 * sizeof(double));
    double start_time = time(NULL);
    double end_time = start_time + 10; // Example duration of 10 seconds
    for (int i = 0; i < 5; i++) {
        (*timestamps)[i] = start_time + (end_time - start_time) * i / 4;
        total_duration += (*timestamps)[i] - (*timestamps)[i - 1];
    }

    // Initialize labels
    *labels = (char**)malloc(LABEL_POOL_SIZE * sizeof(char*));
    char* label_pool[LABEL_POOL_SIZE] = {"Label1", "Label2", "Label3", /* ... */};
    for (int i = 0; i < LABEL_POOL_SIZE; i++) {
        (*labels)[i] = label_pool[i];
    }
}

void free_data(long* offsets, int* keys, record* records, double* timestamps, char** labels) {
    free(offsets);
    free(keys);
    for (int i = 0; i < 5; i++) {
        free(records[i].label);
    }
    free(records);
    free(timestamps);
    for (int i = 0; i < LABEL_POOL_SIZE; i++) {
        free(labels[i]);
    }
    free(labels);
}

int main() {
    long* offsets;
    int* keys;
    record* records;
    double* timestamps;
    char** labels;
    int key_usage[MAX_KEYS] = {0};
    double total_duration = 0;

    initialize_data(&offsets, &keys, &records, &timestamps, &labels, key_usage, &total_duration, MAX_KEYS);

    // Use the data...

    free_data(offsets, keys, records, timestamps, labels);

    return 0;
}
