#include <time.h>
#include <string.h>

#define MAX_MEMORY 1024 * 1024 // 1 MB
#define MIN_ID 1000
#define MAX_ID 9999
#define MIN_PAYLOAD 64
#define MAX_PAYLOAD 1500

typedef struct {
    int id;
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int payload_length;
    void* payload;
} Packet;

Packet* create_packets(int n, int max_payload_size) {
    static size_t total_memory_used = 0;
    if (total_memory_used + n * sizeof(Packet) > MAX_MEMORY) {
        fprintf(stderr, "Memory limit exceeded\n");
        return NULL;
    }

    Packet* packets = malloc(n * sizeof(Packet));
    if (!packets) {
        fprintf(stderr, "Failed to allocate memory for packets\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < n; i++) {
        packets[i].id = MIN_ID + rand() % (MAX_ID - MIN_ID + 1);
        time(&packets[i].timestamp);

        // Generate valid source and destination IPs
        while (1) {
            snprintf(packets[i].source_ip, sizeof(packets[i].source_ip), "%d.%d.%d.%d",
                     rand() % 256, rand() % 256, rand() % 256, rand() % 256);
            snprintf(packets[i].destination_ip, sizeof(packets[i].destination_ip), "%d.%d.%d.%d",
                     rand() % 256, rand() % 256, rand() % 256, rand() % 256);
            if (strcmp(packets[i].source_ip, packets[i].destination_ip) != 0) {
                break;
            }
        }

        packets[i].payload_length = MIN_PAYLOAD + rand() % (max_payload_size - MIN_PAYLOAD + 1);
        if (total_memory_used + n * sizeof(Packet) + packets[i].payload_length > MAX_MEMORY) {
            fprintf(stderr, "Memory limit exceeded for payload\n");
            free(packets);
            return NULL;
        }

        packets[i].payload = malloc(packets[i].payload_length);
        if (!packets[i].payload) {
            fprintf(stderr, "Failed to allocate memory for payload\n");
            free(packets);
            return NULL;
        }
        total_memory_used += sizeof(Packet) + packets[i].payload_length;

        // Initialize payload with random data
        for (int j = 0; j < packets[i].payload_length; j++) {
            ((char*)packets[i].payload)[j] = rand() % 256;
        }
    }

    return packets;
}

void free_packets(Packet* packets, int n) {
    for (int i = 0; i < n; i++) {
        free(packets[i].payload);
    }
    free(packets);
}
