    TransportChannelManager *manager = (TransportChannelManager*)malloc(sizeof(TransportChannelManager));
    manager->channels = (MAC_TransportChannelInfo*)calloc(initial_capacity, sizeof(MAC_TransportChannelInfo));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_manager(TransportChannelManager *manager) {
    free(manager->channels);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_channel(TransportChannelManager *manager, MAC_TransportChannelInfo channel) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        manager->channels = (MAC_TransportChannelInfo*)realloc(manager->channels, new_capacity * sizeof(MAC_TransportChannelInfo));
        manager->capacity = new_capacity;
    }
    manager->channels[manager->size++] = channel;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

