#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct event {
    char identifier[256];
    double timestamp;
    int priority;
    char buffer[1024];
    struct event* next;
} Event;

Event** initialize_events(double end_time, double interval, int max_ident_len, const char* message, int num_events) {
    if (num_events <= 0 || interval <= 0 || max_ident_len <= 0 || message == NULL) {
        return NULL; // Invalid input
    }

    Event** event_array = (Event**)malloc(num_events * sizeof(Event*));
    if (event_array == NULL) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < num_events; ++i) {
        event_array[i] = (Event*)malloc(sizeof(Event));
        if (event_array[i] == NULL) {
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(event_array[j]);
            }
            free(event_array);
            pthread_mutex_destroy(&mutex);
            return NULL; // Memory allocation failed
        }

        event_array[i]->timestamp = end_time - i * interval;
        snprintf(event_array[i]->identifier, max_ident_len + 1, "ID%d", i);
        strcpy(event_array[i]->buffer, message);
        event_array[i]->priority = num_events - i; // Higher priority for later events
        event_array[i]->next = NULL;

        pthread_mutex_lock(&mutex);
        if (i > 0) {
            event_array[i-1]->next = event_array[i];
        }
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);
    return event_array;
}

void free_events(Event** events, int num_events) {
    for (int i = 0; i < num_events; ++i) {
        free(events[i]);
    }
    free(events);
}
