#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double value;
    char buffer[100];
} Node;

typedef struct {
    long timestamp;
    char command[50];
    int priority;
} Command;

typedef struct Task {
    float duration;
    bool status;
    struct Task* next;
} Task;

void logAllocation(const char* description) {
    time_t now = time(NULL);
    printf("Allocated at %s: %s\n", ctime(&now), description);
}

Node** allocateNodes(int count) {
    Node** nodes = (Node**)malloc(count * sizeof(Node*));
    if (!nodes) {
        fprintf(stderr, "Failed to allocate memory for node pointers.\n");
        exit(EXIT_FAILURE);
    }
    logAllocation("Node pointers array");
    return nodes;
}

void initializeNodes(Node** nodes, int count) {
    for (int i = 0; i < count; ++i) {
        nodes[i] = (Node*)malloc(sizeof(Node));
        if (!nodes[i]) {
            fprintf(stderr, "Failed to allocate memory for node %d.\n", i);
            exit(EXIT_FAILURE);
        }
        logAllocation("Single Node");
    }
}

Command* allocateCommands(int count) {
    Command* commands = (Command*)calloc(count, sizeof(Command));
    if (!commands) {
        fprintf(stderr, "Failed to allocate memory for commands array.\n");
        exit(EXIT_FAILURE);
    }
    logAllocation("Commands array");
    return commands;
}

Task* createTask(float duration, bool status) {
    Task* task = (Task*)malloc(sizeof(Task));
    if (!task) {
        fprintf(stderr, "Failed to allocate memory for task.\n");
        exit(EXIT_FAILURE);
    }
    task->duration = duration;
    task->status = status;
    task->next = NULL;
    logAllocation("Single Task");
    return task;
}

void freeNodes(Node** nodes, int count) {
    for (int i = 0; i < count; ++i) {
        if (nodes[i]) {
            free(nodes[i]);
            logAllocation("Freed Node");
        }
    }
    free(nodes);
    logAllocation("Freed Node pointers array");
}

void freeCommands(Command* commands, int count) {
    free(commands);
    logAllocation("Freed Commands array");
}

void freeTasks(Task* head) {
    Task* current = head;
    while (current) {
        Task* next = current->next;
        free(current);
        logAllocation("Freed Task");
        current = next;
    }
}

int main() {
    int nodeCount = 10;
    Node** nodes = allocateNodes(nodeCount);
    initializeNodes(nodes, nodeCount);

    int commandCount = 5;
    Command* commands = allocateCommands(commandCount);

    Task* taskList = createTask(3.5, true);
    taskList->next = createTask(2.0, false);

    // Use the allocated resources...

    freeTasks(taskList);
    freeCommands(commands, commandCount);
    freeNodes(nodes, nodeCount);

    return 0;
}
