#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_PACKET_ID 10000
#define PAYLOAD_SIZE_RANGE (1024, 65536)
#define PRIVATE_IP_RANGES {{"10.0.0.0", "10.255.255.255"}, {"172.16.0.0", "172.31.255.255"}, {"192.168.0.0", "192.168.255.255"}}
#define IP_POOL_SIZE 100

typedef struct {
    time_t timestamp;
    int packet_id;
    int payload_size;
    char source_ip[16];
} NetworkEvent;

NetworkEvent* create_network_events(time_t start_time, int num_events, int max_packet_id) {
    NetworkEvent* events = (NetworkEvent*)malloc(num_events * sizeof(NetworkEvent));
    if (!events) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    time_t current_time = start_time;
    int packet_id = 1;
    char ip_pool[IP_POOL_SIZE][16];
    int ip_count = IP_POOL_SIZE;

    for (int i = 0; i < num_events; i++) {
        events[i].timestamp = current_time;
        events[i].packet_id = packet_id++;
        if (packet_id > max_packet_id) {
            packet_id = 1;
        }

        int payload_size;
        do {
            payload_size = rand() % (PAYLOAD_SIZE_RANGE[1] - PAYLOAD_SIZE_RANGE[0] + 1) + PAYLOAD_SIZE_RANGE[0];
        } while (i > 0 && events[i-1].payload_size == payload_size);
        events[i].payload_size = payload_size;

        if (ip_count == 0) {
            // Refresh IP pool
            ip_count = IP_POOL_SIZE;
            for (int j = 0; j < IP_POOL_SIZE; j++) {
                snprintf(ip_pool[j], sizeof(ip_pool[j]), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
            }
        }

        int ip_index = rand() % ip_count;
        strcpy(events[i].source_ip, ip_pool[ip_index]);
        ip_count--;
    }

    return events;
}

void free_network_events(NetworkEvent* events) {
    free(events);
}

int main() {
    time_t start_time = time(NULL);
    NetworkEvent* events = create_network_events(start_time, 10, MAX_PACKET_ID);
    if (events) {
        for (int i = 0; i < 10; i++) {
            printf("Event %d: Timestamp=%ld, Packet ID=%d, Payload Size=%d, Source IP=%s\n",
                   i, events[i].timestamp, events[i].packet_id, events[i].payload_size, events[i].source_ip);
        }
        free_network_events(events);
    }

    return 0;
}
