#define MAX_RECORDS 1000
#define MIN_KEY 1
#define MAX_KEY 1000
#define MIN_VALUE 1
#define MAX_VALUE 1000

typedef struct {
    long offset;
    int key;
    struct {
        int value;
    } record;
} Record;

typedef struct {
    int rnti;
    // TransportChannelConfig config;
} MAC_TransportChannelInfo;

Record* dynamic_array = NULL;
int array_size = 0;
int max_records = MAX_RECORDS;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

void init_dynamic_array() {
    dynamic_array = (Record*)malloc(max_records * sizeof(Record));
    if (!dynamic_array) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
}

void resize_dynamic_array(int new_size) {
    Record* new_array = (Record*)realloc(dynamic_array, new_size * sizeof(Record));
    if (!new_array) {
        perror("Failed to reallocate memory for dynamic array");
        free(dynamic_array);
        exit(EXIT_FAILURE);
    }
    dynamic_array = new_array;
    max_records = new_size;
}

void add_record(int key, int value) {
    pthread_rwlock_wrlock(&rwlock);
    if (array_size >= max_records) {
        resize_dynamic_array(max_records * 2);
    }
    dynamic_array[array_size].offset = array_size * sizeof(Record);
    dynamic_array[array_size].key = key;
    dynamic_array[array_size].record.value = value;
    array_size++;
    pthread_rwlock_unlock(&rwlock);
}

void* thread_function(void* arg) {
    int key = *(int*)arg;
    int value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    add_record(key, value);
    free(arg);
    return NULL;
}

int main() {
    srand(time(NULL));
    init_dynamic_array();

    pthread_t threads[MAX_KEY];
    for (int i = MIN_KEY; i <= MAX_KEY; i++) {
        int* key_ptr = (int*)malloc(sizeof(int));
        *key_ptr = i;
        if (pthread_create(&threads[i - MIN_KEY], NULL, thread_function, key_ptr) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_KEY - MIN_KEY + 1; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print the dynamic array
    for (int i = 0; i < array_size; i++) {
        printf("Offset: %ld, Key: %d, Value: %d\n", dynamic_array[i].offset, dynamic_array[i].key, dynamic_array[i].record.value);
    }

    free(dynamic_array);
    return 0;
}
