#define MAX_VALUE 100

typedef struct {
    int rnti;
    TransportChannelConfig config;
} MAC_TransportChannelInfo;

void initialize_and_populate_array(MAC_TransportChannelInfo *array, int n) {
    if (n <= 0 || n > MAX_MEMORY / sizeof(MAC_TransportChannelInfo)) {
        return; // Handle edge cases
    }

    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_128_ecb());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest_alias("sha", "sha1");

    for (int i = 0; i < n; i++) {
        array[i].rnti = i + 1;
        array[i].config.logicalChannelIdentity = i * 2;

        // Initialize random integer value
        int random_value;
        if (!RAND_range(MIN_VALUE, MAX_VALUE + 1, &random_value)) {
            // Handle error
        }
        array[i].config.integerValue = random_value;

        // Allocate extra data based on mode
        if (i == 0) {
            // Allocate common extra data for the first record
            array[i].config.extraData = malloc(MAX_EXTRA_DATA_SIZE);
            if (!array[i].config.extraData) {
                // Handle memory allocation failure
            }
        } else {
            // Share common extra data with previous records
            array[i].config.extraData = array[0].config.extraData;
        }

        // Set encryption key based on rnti
        unsigned char key[EVP_MAX_KEY_LENGTH];
        if (!RAND_bytes(key, sizeof(key))) {
            // Handle error
        }
        memcpy(array[i].config.encryptionKey, key, sizeof(key));
    }
}
