#include <time.h>

#define MAX_STRING_LENGTH 100

typedef struct CustomObject {
    double value;
    char* identifier;
    struct CustomObject* next;
} CustomObject;

CustomObject** create_custom_objects(int count, double min_value, double max_value, const char* charset) {
    if (count <= 0 || min_value >= max_value) {
        return NULL;
    }

    CustomObject** array = (CustomObject**)malloc(count * sizeof(CustomObject*));
    if (!array) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        array[i] = (CustomObject*)malloc(sizeof(CustomObject));
        if (!array[i]) {
            // Free previously allocated objects
            for (int j = 0; j < i; ++j) {
                free(array[j]->identifier);
                free(array[j]);
            }
            free(array);
            return NULL;
        }

        array[i]->value = min_value + (max_value - min_value) * ((double)rand() / RAND_MAX);
        while (i > 0 && array[i]->value == array[i - 1]->value) {
            array[i]->value = min_value + (max_value - min_value) * ((double)rand() / RAND_MAX);
        }

        int string_length = rand() % MAX_STRING_LENGTH + 1;
        array[i]->identifier = (char*)malloc(string_length * sizeof(char));
        if (!array[i]->identifier) {
            // Free previously allocated objects
            for (int j = 0; j <= i; ++j) {
                free(array[j]->identifier);
                free(array[j]);
            }
            free(array);
            return NULL;
        }

        snprintf(array[i]->identifier, string_length, "%s%d", charset, rand() % 100);

        array[i]->next = (i < count - 1) ? array[i + 1] : NULL;
    }

    return array;
}

void free_custom_objects(CustomObject** array, int count) {
    for (int i = 0; i < count; ++i) {
        free(array[i]->identifier);
        free(array[i]);
    }
    free(array);
}

int main() {
    int count = 10;
    double min_value = 0.0;
    double max_value = 100.0;
    const char* charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

    CustomObject** objects = create_custom_objects(count, min_value, max_value, charset);
    if (objects) {
        for (int i = 0; i < count; ++i) {
            printf("Value: %f, Identifier: %s\n", objects[i]->value, objects[i]->identifier);
        }
        free_custom_objects(objects, count);
    } else {
        printf("Failed to create custom objects.\n");
    }

    return 0;
}
