#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <openssl/evp.h>

#define MAX_MEMORY 1024 * 1024 // 1MB

typedef struct record {
    long offset;
    int key;
    int value;
    int priority;
    time_t timestamp;
    int backup_flag;
    struct record* next;
} Record;

Record* pool[MAX_MEMORY / sizeof(Record)];
int pool_index = 0;

Record* allocate_record() {
    if (pool_index >= MAX_MEMORY / sizeof(Record)) {
        return NULL; // Out of memory
    }
    return &pool[pool_index++];
}

void free_record(Record* record) {
    int index = (record - pool) / sizeof(Record);
    if (index < 0 || index >= MAX_MEMORY / sizeof(Record)) {
        return; // Invalid pointer
    }
    pool[index] = NULL;
}

Record* create_record(int key, int value, int priority, time_t timestamp, int backup_flag) {
    Record* record = allocate_record();
    if (record == NULL) {
        return NULL; // Memory allocation failed
    }
    record->offset = (long)((char*)record - (char*)pool);
    record->key = key;
    record->value = value;
    record->priority = priority;
    record->timestamp = timestamp;
    record->backup_flag = backup_flag;
    record->next = NULL;
    return record;
}

void free_all_records() {
    for (int i = 0; i < MAX_MEMORY / sizeof(Record); i++) {
        if (pool[i] != NULL) {
            free_record(pool[i]);
        }
    }
}

int main() {
    srand(time(NULL));
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_sha256());

    Record* records[200];
    for (int i = 0; i < 200; i++) {
        int key = rand() % 1000;
        int value = rand();
        int priority = rand() % 10 + 1;
        time_t timestamp = time(NULL) + (rand() % 60 - 30);
        int backup_flag = i % 2;

        records[i] = create_record(key, value, priority, timestamp, backup_flag);
        if (records[i] == NULL) {
            printf("Memory allocation failed\n");
            return 1;
        }
    }

    // Process records...

    free_all_records();
    EVP_cleanup();

    return 0;
}
