#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char *itemKey;
    time_t timestamp;
    int usageCounter;
} ContentItem;

typedef struct {
    ContentItem **items;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Cache;

Cache* create_cache(size_t initial_capacity) {
    Cache *cache = (Cache*)malloc(sizeof(Cache));
    cache->items = (ContentItem**)calloc(initial_capacity, sizeof(ContentItem*));
    cache->capacity = initial_capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(Cache *cache) {
    for (size_t i = 0; i < cache->size; ++i) {
        free(cache->items[i]->itemKey);
        free(cache->items[i]);
    }
    free(cache->items);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void* get_item(Cache *cache, const char *key) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->size; ++i) {
        if (strcmp(cache->items[i]->itemKey, key) == 0) {
            cache->items[i]->usageCounter++;
            pthread_mutex_unlock(&cache->lock);
            return cache->items[i];
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void put_item(Cache *cache, const char *key) {
    pthread_mutex_lock(&cache->lock);
    if (cache->size >= cache->capacity) {
        // Implement LRU eviction policy
        size_t lru_index = 0;
        time_t min_timestamp = cache->items[0]->timestamp;
        for (size_t i = 1; i < cache->size; ++i) {
            if (cache->items[i]->timestamp < min_timestamp) {
                min_timestamp = cache->items[i]->timestamp;
                lru_index = i;
            }
        }
        free(cache->items[lru_index]->itemKey);
        free(cache->items[lru_index]);
        cache->size--;
    }
    ContentItem *new_item = (ContentItem*)malloc(sizeof(ContentItem));
    new_item->itemKey = strdup(key);
    new_item->timestamp = time(NULL);
    new_item->usageCounter = 1;
    cache->items[cache->size++] = new_item;
    pthread_mutex_unlock(&cache->lock);
}

int main() {
    Cache *cache = create_cache(100);
    put_item(cache, "item1");
    ContentItem *item = get_item(cache, "item1");
    if (item) {
        printf("Item found: %s\n", item->itemKey);
    } else {
        printf("Item not found.\n");
    }
    destroy_cache(cache);
    return 0;
}
```

This code provides a basic structure for a scalable cache system using the Least Recently Used (LRU) eviction policy. It includes functions to create and destroy the cache, as well as to get and put items into the cache. The `get_item` function handles cache hits and updates the usage counter, while the `put_item` function handles cache misses and evicts the least recently used item when necessary.

The code uses a mutex to ensure thread safety during read and write operations, preventing contention issues in a high-concurrency environment. The cache size is dynamically adjusted based on observed usage patterns, but this functionality is not fully implemented in the provided code block.

To fully implement the required features, additional code would be needed to load cache parameters from a configuration file, dynamically adjust cache size, and handle unexpected load increases. Additionally, more sophisticated locking mechanisms and error handling could be added for robustness under heavy load conditions.']

