#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MAX_COMMANDS 50

typedef struct {
    int value;
} record;

typedef struct {
    long offset;
    int key;
    record data;
} task_data;

typedef struct {
    task_data *tasks;
    int size;
    int capacity;
    pthread_mutex_t lock;
} task_pool;

task_pool *create_task_pool(int initial_capacity) {
    task_pool *pool = (task_pool *)malloc(sizeof(task_pool));
    pool->tasks = (task_data *)calloc(initial_capacity, sizeof(task_data));
    pool->size = 0;
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_task_pool(task_pool *pool) {
    free(pool->tasks);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_task(task_pool *pool, long offset, int key, record data) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        pool->capacity *= 2;
        pool->tasks = (task_data *)realloc(pool->tasks, pool->capacity * sizeof(task_data));
    }
    pool->tasks[pool->size].offset = offset;
    pool->tasks[pool->size].key = key;
    pool->tasks[pool->size].data = data;
    pool->size++;
    pthread_mutex_unlock(&pool->lock);
    return 1;
}

int execute_tasks(task_pool *pool) {
    for (int i = 0; i < pool->size; i++) {
        pid_t pid = fork();
        if (pid == -1) {
            perror("fork");
            return 0;
        } else if (pid == 0) {
            // Child process
            printf("Executing task with offset %ld and key %d\n", pool->tasks[i].offset, pool->tasks[i].key);
            exit(0);
        }
    }

    for (int i = 0; i < pool->size; i++) {
        int status;
        waitpid(-1, &status, 0);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            return 0;
        }
    }

    return 1;
}

int main() {
    task_pool *pool = create_task_pool(10);

    record data = {42};
    add_task(pool, 0, 1, data);
    add_task(pool, 1, 2, data);

    if (execute_tasks(pool)) {
        printf("All tasks executed successfully\n");
    } else {
        printf("Failed to execute some tasks\n");
    }

    destroy_task_pool(pool);
    return 0;
}
