public class DynamicRangeGenerator
{
    private Random _random;
    private long _minLongValue, _maxLongValue;
    private int _minIntValue, _maxIntValue;
    private record MyRecord(int Value);
    private List<MyRecord> _records;
    private object _lockObject = new object();

    public DynamicRangeGenerator()
    {
        _random = new Random();
        InitializeRanges();
    }

    private void InitializeRanges()
    {
        // Initialize ranges with default values
        _minLongValue = 0;
        _maxLongValue = 100;
        _minIntValue = 0;
        _maxIntValue = 100;
        _records = new List<MyRecord>();
    }

    public void SetLongRange(long min, long max)
    {
        lock (_lockObject)
        {
            if (min < max && max > 0)
            {
                _minLongValue = min;
                _maxLongValue = max;
                Log("Long range set to: " + min + " to " + max);
            }
            else
            {
                throw new ArgumentException("Invalid long range");
            }
        }
    }

    public void SetIntRange(int min, int max)
    {
        lock (_lockObject)
        {
            if (min < max && max > 0)
            {
                _minIntValue = min;
                _maxIntValue = max;
                Log("Int range set to: " + min + " to " + max);
            }
            else
            {
                throw new ArgumentException("Invalid int range");
            }
        }
    }

    public long GenerateRandomLong(bool inclusive)
    {
        lock (_lockObject)
        {
            return _random.Next(_minLongValue, inclusive ? _maxLongValue + 1 : _maxLongValue);
        }
    }

    public int GenerateRandomInt(bool inclusive)
    {
        lock (_lockObject)
        {
            return _random.Next(_minIntValue, inclusive ? _maxIntValue + 1 : _maxIntValue);
        }
    }

    public MyRecord GenerateRandomRecord()
    {
        lock (_lockObject)
        {
            int value;
            do
            {
                value = _random.Next(_minIntValue, _maxIntValue + 1);
            } while (_records.Any(r => r.Value == value));
            var record = new MyRecord(value);
            _records.Add(record);
            Log("Generated record: " + record.Value);
            return record;
        }
    }

    private void Log(string message)
    {
        // Implement logging logic here
        Console.WriteLine(message);
    }

    public void SerializeToFile(string filePath)
    {
        try
        {
            // Implement serialization logic here
            System.IO.File.WriteAllText(filePath, "Serialized data");
        }
        catch (Exception ex)
        {
            Log("Serialization error: " + ex.Message);
        }
    }

    public void DeserializeFromFile(string filePath)
    {
        try
        {
            // Implement deserialization logic here
            var data = System.IO.File.ReadAllText(filePath);
            if (data == "Serialized data")
            {
                InitializeRanges();
                Log("Deserialized data successfully");
            }
            else
            {
                throw new InvalidOperationException("Invalid serialized data");
            }
        }
        catch (Exception ex)
        {
            Log("Deserialization error: " + ex.Message);
        }
    }

    public void UpdateFromExternalDataSource()
    {
        // Implement logic to update ranges from external data source here
        try
        {
            var newData = FetchDataFromExternalSource();
            SetLongRange(newData.LongMin, newData.LongMax);
            SetIntRange(newData.IntMin, newData.IntMax);
            Log("Updated ranges from external data source");
        }
        catch (Exception ex)
        {
            Log("Error updating from external data source: " + ex.Message);
        }
    }

    private ExternalDataSourceData FetchDataFromExternalSource()
    {
        // Implement logic to fetch data from external data source here
        return new ExternalDataSourceData { LongMin = 0, LongMax = 100, IntMin = 0, IntMax = 100 };
    }
}

public class ExternalDataSourceData
{
    public long LongMin { get; set; }
    public long LongMax { get; set; }
    public int IntMin { get; set; }
    public int IntMax { get; set; }
}
