void processAndAnalyzeText() {
    DocumentSet docSet;
    docSet.documents = (char**)malloc(MAX_DOCS * sizeof(char*));
    docSet.numDocuments = 0;

    // Populate documents from file input
    // ...

    ThreadData threadData[MAX_DOCS];
    pthread_t threads[MAX_DOCS];

    for (int i = 0; i < docSet.numDocuments; i++) {
        threadData[i].documentSet = &docSet;
        threadData[i].docIndex = i;

        if (pthread_create(&threads[i], NULL, processDocument, &threadData[i]) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < docSet.numDocuments; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    for (int i = 0; i < docSet.numDocuments; i++) {
        free(docSet.documents[i]);
    }
    free(docSet.documents);

    printf("All documents processed and memory freed.\n");
}

