#define MAX_RECORDS 10000
#define BUFFER_SIZE 1024

typedef struct {
    int* data;
} record;

int generate_unique_random(int* buffer, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        int num;
        do {
            num = rand() % 10000; // Adjust range as needed
        } while (buffer[num / 32] & (1 << (num % 32)));
        buffer[num / 32] |= (1 << (num % 32));
    }
    return 0;
}

record* allocate_records(int num_records) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Number of records exceeds maximum limit.\n");
        return NULL;
    }

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        return NULL;
    }

    int** buffers = malloc(num_records * sizeof(int*));
    if (!buffers) {
        fprintf(stderr, "Error: Failed to allocate memory for buffer pointers.\n");
        free(records);
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        buffers[i] = malloc(BUFFER_SIZE * sizeof(int));
        if (!buffers[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for buffer %d.\n", i);
            for (int j = 0; j < i; ++j) {
                free(buffers[j]);
            }
            free(buffers);
            free(records);
            return NULL;
        }

        if (generate_unique_random(buffers[i], BUFFER_SIZE)) {
            fprintf(stderr, "Error: Failed to generate unique random numbers for buffer %d.\n", i);
            for (int j = 0; j <= i; ++j) {
                free(buffers[j]);
            }
            free(buffers);
            free(records);
            return NULL;
        }
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].data = buffers[i];
    }

    return records;
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].data);
    }
    free(records);
}
