        keys[i] = (seed + i * 7) % divisor;
    }

    // Initialize records with random values
    for (int i = 0; i < MAX_INTS; i++) {
        do {
            records[i].value = rand() % 1000;
        } while (i > 0 && records[i - 1].value == records[i].value);
    }

    // Initialize status array
    for (int i = 0; i < MAX_INTS; i++) {
        status[i] = 1; // Assuming all initializations are successful
    }

    // Log initialization times
    for (int i = 0; i < MAX_INTS; i++) {
        timestamps[i] = time(NULL);
    }

    // Find and print the largest integer
    long largest = find_largest(records, MAX_INTS);
    printf("Largest integer: %ld\n", largest);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(status);
    free(timestamps);
}

