#include <time.h>

#define MAX_KEY 1000
#define MIN_VALUE 1
#define MAX_VALUE 10000

typedef struct {
    long offset;
    int key;
    int value;
} Record;

Record* processAndFindMax(int *maxValue) {
    int initialSize = 100;
    Record *records = (Record *)malloc(initialSize * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    long offset = 0;
    int keyCount = 0;
    int valueRange = MAX_VALUE - MIN_VALUE + 1;
    srand(time(NULL));

    while (1) {
        int input;
        if (scanf("%d", &input) != 1 || input < MIN_VALUE || input > MAX_KEY) {
            break; // End of input or invalid data
        }

        if (keyCount >= keyCount) {
            initialSize *= 2;
            Record *newRecords = realloc(records, initialSize * sizeof(Record));
            if (!newRecords) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(records);
                exit(EXIT_FAILURE);
            }
            records = newRecords;
        }

        records[keyCount].offset = offset++;
        records[keyCount].key = input;
        records[keyCount].value = MIN_VALUE + rand() % valueRange;

        if (keyCount > 0 && records[keyCount].value == records[keyCount - 1].value) {
            records[keyCount].value = (records[keyCount].value + 1) % valueRange;
        }

        *maxValue = (*maxValue > records[keyCount].value) ? *maxValue : records[keyCount].value;

        keyCount++;
    }

    return records;
}

int main() {
    int maxValue = MIN_VALUE - 1;
    Record *records = processAndFindMax(&maxValue);

    printf("Maximum value processed: %d\n", maxValue);

    // Free allocated memory
    free(records);

    return 0;
}
