#include <random>
#include <sstream>
#include <arpa/inet.h>

namespace NetworkUtil {

class RandomDNSProcessor {
public:
    static std::mt19937 rng;

    RandomDNSProcessor() {}
    ~RandomDNSProcessor() {}

    static uint64_t generateRandomNumber() {
        return rng();
    }

    static std::string resolveDNS(const std::string& hostname) {
        struct addrinfo hints, *res;
        int status;
        char ipstr[INET6_ADDRSTRLEN];

        memset(&hints, 0, sizeof hints);
        hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
        hints.ai_socktype = SOCK_STREAM;

        if ((status = getaddrinfo(hostname.c_str(), NULL, &hints, &res)) != 0) {
            std::cerr << "getaddrinfo: " << gai_strerror(status) << std::endl;
            return "";
        }

        void *addr;
        char *ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (res->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)res->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(res->ai_family, addr, ipstr, sizeof ipstr);
        freeaddrinfo(res); // all done with this structure

        return std::string(ipstr);
    }
};

std::mt19937 RandomDNSProcessor::rng(std::random_device{}());

class FileProcessor {
public:
    static void processFile(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            std::cerr << "Failed to open file: " << filename << std::endl;
            return;
        }

        std::vector<std::thread> threads;
        std::mutex mtx;

        for (std::string line; std::getline(file, line);) {
            threads.emplace_back([&line, &mtx]() {
                processLine(line, mtx);
            });
        }

        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }

        file.close();
    }

private:
    static void processLine(const std::string& line, std::mutex& mtx) {
        std::istringstream iss(line);
        std::vector<std::string> fields;
        std::string field;

        while (std::getline(iss, field, ',')) {
            fields.push_back(field);
        }

        if (fields.size() < 2) {
            return;
        }

        try {
            double sum = std::stod(fields[fields.size() - 1]) + std::stod(fields[fields.size() - 2]);
            double average = sum / 2.0;

            std::lock_guard<std::mutex> lock(mtx);
            std::cout << line << "," << average << std::endl;
        } catch (const std::invalid_argument& e) {
            // Handle invalid number format
        }
    }
};

} // namespace NetworkUtil

int main() {
    NetworkUtil::FileProcessor::processFile("config.txt");
    return 0;
}
