#define MAX_STRING_LENGTH 256

typedef struct {
    double *double_values;
    char **char_strings;
    struct item *items;
} MemoryManager;

typedef struct {
    float value;
    char *str_ref;
} Item;

MemoryManager* create_memory_manager(size_t initial_size) {
    MemoryManager *mm = (MemoryManager*)malloc(sizeof(MemoryManager));
    mm->double_values = (double*)calloc(initial_size, sizeof(double));
    mm->char_strings = (char**)calloc(initial_size, sizeof(char*));
    mm->items = (Item*)calloc(initial_size, sizeof(Item));
    return mm;
}

void free_memory_manager(MemoryManager *mm) {
    for (size_t i = 0; i < mm->double_values; ++i) {
        free(mm->char_strings[i]);
    }
    free(mm->double_values);
    free(mm->char_strings);
    free(mm->items);
    free(mm);
}

void populate_memory_manager(MemoryManager *mm, size_t count, const char *csv_file) {
    FILE *file = fopen(csv_file, "r");
    if (!file) {
        perror("Failed to open CSV file");
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        double random_double = ((double)rand() / RAND_MAX) * 100.0 - 50.0;
        mm->double_values[i] = random_double;

        char line[MAX_STRING_LENGTH];
        if (fgets(line, sizeof(line), file)) {
            size_t len = strlen(line);
            if (len > 0 && line[len - 1] == '\n') {
                line[len - 1] = '\0';
            }
            mm->char_strings[i] = strdup(line);
        } else {
            mm->char_strings[i] = NULL;
        }

        float random_float = ((float)rand() / RAND_MAX) * 10.0 - 5.0;
        mm->items[i].value = random_float;
        mm->items[i].str_ref = mm->char_strings[i];
    }
    fclose(file);
}

void verify_memory_manager(MemoryManager *mm, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (!mm->char_strings[i]) {
            printf("Error: Null string reference at index %zu\n", i);
            continue;
        }
        if (strlen(mm->char_strings[i]) >= MAX_STRING_LENGTH) {
            printf("Error: String too long at index %zu\n", i);
            continue;
        }
    }
}

int main() {
    MemoryManager *mm = create_memory_manager(100);
    populate_memory_manager(mm, 100, "data.csv");
    verify_memory_manager(mm, 100);
    free_memory_manager(mm);
    return 0;
}
