        keys[i] = rand() % num_records;

        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            for (int j = 0; j < i; ++j) {
                free(records[j]->str);
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        records[i]->value = rand() % 1000;
        records[i]->str = malloc(65 * sizeof(char));
        if (!records[i]->str) {
            fprintf(stderr, "Memory allocation failed\n");
            for (int j = 0; j <= i; ++j) {
                free(records[j]->str);
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        snprintf(records[i]->str, 65, "Record %d", i);
