#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ITEMS 10000

typedef struct {
    float value;
    char* str;
} Item;

typedef struct {
    double* doubles;
    char** strings;
    Item* items;
    size_t count;
    size_t capacity;
} DataStructures;

int initialize_data_structures(DataStructures* ds, size_t initial_capacity) {
    if (initial_capacity > MAX_ITEMS) {
        fprintf(stderr, "Initial capacity exceeds maximum allowed.\n");
        return -1;
    }

    ds->doubles = malloc(initial_capacity * sizeof(double));
    ds->strings = malloc(initial_capacity * sizeof(char*));
    ds->items = malloc(initial_capacity * sizeof(Item));
    ds->count = 0;
    ds->capacity = initial_capacity;

    if (!ds->doubles || !ds->strings || !ds->items) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(ds->doubles);
        free(ds->strings);
        free(ds->items);
        return -1;
    }

    srand(time(NULL));
    for (size_t i = 0; i < initial_capacity; ++i) {
        ds->doubles[i] = ((double)rand() / RAND_MAX) * 2.0 - 1.0;
        char* str = malloc(16); // Assuming strings are up to 15 characters long
        snprintf(str, 16, "String%d", i);
        ds->strings[i] = str;
        ds->items[i].value = ds->doubles[i];
        ds->items[i].str = ds->strings[i];
    }

    return 0;
}

void free_data_structures(DataStructures* ds) {
    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->strings[i]);
    }
    free(ds->doubles);
    free(ds->strings);
    free(ds->items);
}

int serialize_data_structures(const DataStructures* ds, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing.\n");
        return -1;
    }

    size_t written = fwrite(ds->doubles, sizeof(double), ds->count, file);
    if (written != ds->count) {
        fprintf(stderr, "Error writing doubles to file.\n");
        fclose(file);
        return -1;
    }

    written = fwrite(ds->strings, sizeof(char*), ds->count, file);
    if (written != ds->count) {
        fprintf(stderr, "Error writing strings pointers to file.\n");
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < ds->count; ++i) {
        size_t str_len = strlen(ds->strings[i]) + 1;
        written = fwrite(&str_len, sizeof(size_t), 1, file);
        if (written != 1) {
            fprintf(stderr, "Error writing string length to file.\n");
            fclose(file);
            return -1;
        }
        written = fwrite(ds->strings[i], str_len, 1, file);
        if (written != 1) {
            fprintf(stderr, "Error writing string to file.\n");
            fclose(file);
            return -1;
        }
    }

    fclose(file);
    return 0;
}

int deserialize_data_structures(DataStructures* ds, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading.\n");
        return -1;
    }

    size_t read_doubles = fread(ds->doubles, sizeof(double), ds->capacity, file);
    if (read_doubles != ds->count) {
        fprintf(stderr, "Error reading doubles from file.\n");
        fclose(file);
        return -1;
    }

    size_t read_strings = fread(ds->strings, sizeof(char*), ds->capacity, file);
    if (read_strings != ds->count) {
        fprintf(stderr, "Error reading strings pointers from file.\n");
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < ds->count; ++i) {
        size_t str_len;
        fread(&str_len, sizeof(size_t), 1, file);
        if (str_len > 16) {
            fprintf(stderr, "String length exceeds expected maximum.\n");
            fclose(file);
            return -1;
        }
        ds->strings[i] = malloc(str_len);
        size_t read_str = fread(ds->strings[i], str_len, 1, file);
        if (read_str != 1) {
            fprintf(stderr, "Error reading string from file.\n");
            fclose(file);
            return -1;
        }
    }

    fclose(file);
    return 0;
}
