#define MAX_CHANNELS 100

typedef struct {
    int rnti;
    TransportChannelConfig config;
} MAC_TransportChannelInfo;

typedef struct {
    int logicalChannelIdentity;
    time_t timestamp;
    int activeFlag;
} TransportChannelConfig;

MAC_TransportChannelInfo* channelArray = NULL;
int currentSize = 0;
int maxSize = MAX_CHANNELS;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initializeChannelArray() {
    channelArray = (MAC_TransportChannelInfo*)malloc(maxSize * sizeof(MAC_TransportChannelInfo));
}

void resizeChannelArray(int newSize) {
    pthread_mutex_lock(&mutex);
    if (newSize > maxSize) {
        channelArray = realloc(channelArray, newSize * sizeof(MAC_TransportChannelInfo));
        if (channelArray == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        for (int i = currentSize; i < newSize; i++) {
            channelArray[i].rnti = -1;
            channelArray[i].config.logicalChannelIdentity = -1;
            channelArray[i].config.timestamp = 0;
            channelArray[i].config.activeFlag = 0;
        }
    } else if (newSize < currentSize) {
        for (int i = newSize; i < currentSize; i++) {
            channelArray[i].rnti = -1;
            channelArray[i].config.logicalChannelIdentity = -1;
            channelArray[i].config.timestamp = 0;
            channelArray[i].config.activeFlag = 0;
        }
    }
    maxSize = newSize;
    pthread_mutex_unlock(&mutex);
}

void addChannel(int rnti, TransportChannelConfig config) {
    pthread_mutex_lock(&mutex);
    if (currentSize >= maxSize) {
        resizeChannelArray(maxSize * 2);
    }
    channelArray[currentSize].rnti = rnti;
    channelArray[currentSize].config = config;
    currentSize++;
    pthread_mutex_unlock(&mutex);
}

void updateChannelConfig(int rnti, TransportChannelConfig newConfig) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < currentSize; i++) {
        if (channelArray[i].rnti == rnti) {
            channelArray[i].config = newConfig;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void logConfiguration(int severity, const char* message) {
    // Asynchronous logging implementation
    printf("[%s] %s\n", getSeverityString(severity), message);
}

const char* getSeverityString(int severity) {
    switch (severity) {
        case DEBUG: return "DEBUG";
        case INFO: return "INFO";
        case WARNING: return "WARNING";
        case ERROR: return "ERROR";
        default: return "UNKNOWN";
    }
}

void monitorConfiguration() {
    // Monitoring implementation
    for (int i = 0; i < currentSize; i++) {
        if (channelArray[i].config.activeFlag == 0) {
            logConfiguration(WARNING, "Inactive transport channel detected");
        }
    }
}
