#include <arpa/inet.h>
#include <pthread.h>
#include <json-c/json.h>

#define MAX_CONNECTIONS 100
#define BUFFER_SIZE 4096

typedef enum {
    PROTOCOL_TCP,
    PROTOCOL_UDP
} Protocol;

typedef struct {
    int fd;
    Protocol protocol;
    pthread_mutex_t lock;
} Connection;

Connection connections[MAX_CONNECTIONS];
int connection_count = 0;

void* handle_client(void* arg) {
    int client_fd = *(int*)arg;
    free(arg);

    while (1) {
        char buffer[BUFFER_SIZE];
        ssize_t bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received <= 0) break;

        buffer[bytes_received] = '\0';
        json_object* received_json = json_tokener_parse(buffer);
        if (!received_json) {
            printf("Malformed JSON received\n");
            continue;
        }

        // Process the JSON data
        // ...

        json_object_put(received_json);
    }

    close(client_fd);
    return NULL;
}

void add_connection(int fd, Protocol protocol) {
    pthread_mutex_lock(&connections[connection_count].lock);
    connections[connection_count].fd = fd;
    connections[connection_count].protocol = protocol;
    connection_count++;
    pthread_mutex_unlock(&connections[connection_count].lock);
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Bind the socket to an IP and port
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8080);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int* new_socket_ptr = malloc(sizeof(int));
        *new_socket_ptr = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
        if (*new_socket_ptr < 0) {
            perror("accept");
            free(new_socket_ptr);
            continue;
        }

        pthread_t thread_id;
