#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    time_t timestamp;
    int flag;
    int priority;
    int backup_flag;
    struct record *next;
    struct record *prev;
} Record;

Record* create_record(int value, time_t timestamp, int flag, int priority) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_record->value = value;
    new_record->timestamp = timestamp;
    new_record->flag = flag;
    new_record->priority = priority;
    new_record->backup_flag = (priority % 2 == 0) ? 1 : 0;
    new_record->next = NULL;
    new_record->prev = NULL;
    return new_record;
}

void insert_record(Record** head, Record* new_record) {
    if (*head == NULL) {
        *head = new_record;
    } else {
        Record* temp = *head;
        while (temp->next != NULL && temp->priority >= new_record->priority) {
            temp = temp->next;
        }
        if (temp->next == NULL) {
            temp->next = new_record;
            new_record->prev = temp;
        } else {
            new_record->next = temp->next;
            new_record->prev = temp;
            temp->next->prev = new_record;
            temp->next = new_record;
        }
    }
}

void processAndFindMax() {
    // Initialize arrays and variables
    long* offset_values = (long*)malloc(100 * sizeof(long));
    int* keys = (int*)malloc(50 * sizeof(int));
    Record** records = (Record**)malloc(50 * sizeof(Record*));

    if (offset_values == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Populate arrays with unique values and timestamps
    srand(time(NULL));
    for (int i = 0; i < 50; i++) {
        keys[i] = rand() % 100;
        time_t current_time = time(NULL);
        offset_values[i] = current_time + (rand() % 6 - 3) * 60;
        records[i] = create_record(rand() % 200, offset_values[i], i % 2, i);
    }

    // Insert records into a doubly linked list based on priority
    Record* head = NULL;
    for (int i = 0; i < 50; i++) {
        insert_record(&head, records[i]);
    }

    // Free allocated memory
    Record* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
    free(offset_values);
    free(keys);
    for (int i = 0; i < 50; i++) {
        free(records[i]);
    }
    free(records);

    // Log and monitor performance
    printf("Memory allocation and deallocation completed successfully\n");
}

int main() {
    processAndFindMax();
    return 0;
}
