    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record* allocate_records(int count) {
    return (record*)safe_malloc(count * sizeof(record));
}

void initialize_records(record* records, int count, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        memset(records[i].buffer, 0, RECORD_SIZE);
    }
}

void free_records(record* records, int count) {
    free(records);
}

