#include <iostream>
#include <vector>
#include <random>
#include <chrono>
#include <fstream>
#include <memory>

// Configuration Management
class SimulationConfig {
public:
    enum class SeedingMethod { TimeBased, FileBased, UserProvided };
    enum class DistributionType { Uniform, Normal };

    SeedingMethod seedingMethod;
    unsigned int seed;
    DistributionType distributionType;

    SimulationConfig(SeedingMethod method, unsigned int s = 0, DistributionType dist = DistributionType::Uniform)
        : seedingMethod(method), seed(s), distributionType(dist) {}
};

// PRNG Manager
class PRNGManager {
private:
    std::vector<std::unique_ptr<std::mt19937>> generators;
    std::vector<SimulationConfig> configs;

public:
    void addGenerator(const SimulationConfig& config) {
        generators.emplace_back(std::make_unique<std::mt19937>(config.seed));
        configs.push_back(config);
    }

    void removeGenerator(size_t index) {
        if (index < generators.size()) {
            generators.erase(generators.begin() + index);
            configs.erase(configs.begin() + index);
        }
    }

    void resetGenerators() {
        for (auto& gen : generators) {
            gen->seed(configs[&gen - &generators.front()].seed);
        }
    }

    double getRandomNumber(size_t index) {
        if (index < generators.size()) {
            switch (configs[index].distributionType) {
                case SimulationConfig::DistributionType::Uniform:
                    return std::uniform_real_distribution<>(0.0, 1.0)(*generators[index]);
                case SimulationConfig::DistributionType::Normal:
                    return std::normal_distribution<>(0.0, 1.0)(*generators[index]);
            }
        }
        throw std::runtime_error("Invalid generator index");
    }
};

// Generator Factory
class RandomGeneratorFactory {
public:
    static std::mt19937 createGenerator(const SimulationConfig& config) {
        switch (config.seedingMethod) {
            case SimulationConfig::SeedingMethod::TimeBased:
                return std::mt19937(std::chrono::system_clock::now().time_since_epoch().count());
            case SimulationConfig::SeedingMethod::FileBased: {
                std::ifstream file("seed.txt");
                unsigned int seed;
                if (file >> seed) {
                    return std::mt19937(seed);
                } else {
                    throw std::runtime_error("Failed to read seed from file");
                }
            }
            case SimulationConfig::SeedingMethod::UserProvided:
                return std::mt19937(config.seed);
        }
    }
};

int main() {
    PRNGManager manager;
    SimulationConfig config(SimulationConfig::SeedingMethod::TimeBased, 0, SimulationConfig::DistributionType::Uniform);

    manager.addGenerator(config);
    for (size_t i = 0; i < 10; ++i) {
        std::cout << "Random Number: " << manager.getRandomNumber(0) << std::endl;
    }

    return 0;
}
