using System;
using System.Collections.Concurrent;
using System.Threading;

public class ConfigurableRandomNumberGenerator
{
    private Random _random;
    private int _minValue;
    private int _maxValue;
    private object _lock = new object();

    public ConfigurableRandomNumberGenerator(int minValue, int maxValue)
    {
        if (minValue >= maxValue) throw new ArgumentException("Min value must be less than max value.");
        _minValue = minValue;
        _maxValue = maxValue;
        _random = new Random();
    }

    public void Reset()
    {
        lock (_lock)
        {
            _random = new Random();
        }
    }

    public int GenerateRandomInt()
    {
        lock (_lock)
        {
            return _random.Next(_minValue, _maxValue + 1);
        }
    }

    public float GenerateRandomFloat()
    {
        lock (_lock)
        {
            return (float)_random.NextDouble() * (_maxValue - _minValue) + _minValue;
        }
    }

    public void Recalibrate(int minValue, int maxValue)
    {
        if (minValue >= maxValue) throw new ArgumentException("Min value must be less than max value.");
        lock (_lock)
        {
            _minValue = minValue;
            _maxValue = maxValue;
            _random = new Random();
        }
    }
}

public struct MAC_TransportChannelInfo
{
    public int rnti;
    public TransportChannelConfig config;
}

public class TransportChannelConfig
{
    public int logicalChannelIdentity { get; set; }
    public DateTime timestamp { get; set; }
    public bool isActive { get; set; }
}

public class NetworkManager
{
    private ConfigurableRandomNumberGenerator _rng;
    private ConcurrentBag<MAC_TransportChannelInfo> _channels = new ConcurrentBag<MAC_TransportChannelInfo>();
    private readonly object _logLock = new object();
    private static readonly log4net.ILog Log = log4net.LogManager.GetLogger(typeof(NetworkManager));

    public NetworkManager(int minValue, int maxValue)
    {
        _rng = new ConfigurableRandomNumberGenerator(minValue, maxValue);
    }

    public void AddChannel()
    {
        var channelInfo = new MAC_TransportChannelInfo
        {
            rnti = _rng.GenerateRandomInt(),
            config = new TransportChannelConfig
            {
                logicalChannelIdentity = _rng.GenerateRandomInt(),
                timestamp = DateTime.Now,
                isActive = true
            }
        };
        _channels.Add(channelInfo);
    }

    public void LogConfigurationChange(string message, log4net.Core.Level level)
    {
        lock (_logLock)
        {
            if (Log.IsLogging(level))
            {
                Log.Log(level, message);
            }
        }
    }
}
