public class MoSTStateLoader {

    private static final ConcurrentHashMap<String, MoSTState> cache = new ConcurrentHashMap<>();
    private static final AtomicInteger cacheHitCount = new AtomicInteger(0);
    private static final AtomicInteger cacheMissCount = new AtomicInteger(0);

    public static MoSTState loadMoSTState(String filePath) {
        String key = filePath;
        MoSTState cachedState = cache.get(key);
        if (cachedState != null) {
            cacheHitCount.incrementAndGet();
            return cachedState;
        }

        cacheMissCount.incrementAndGet();

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            MoSTState state = (MoSTState) ois.readObject();
            if (isValidVersion(state)) {
                cache.putIfAbsent(key, state);
                return state;
            } else {
                System.err.println("Version mismatch for file: " + filePath);
                return null;
            }
        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Error loading MoSTState from file: " + filePath + ", error: " + e.getMessage());
