#include <stdlib.h>
#include <string.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_EXTRA_DATA_SIZE 1024

typedef struct Record {
    int value;
    long offset;
    int key;
    void* extra_data;
} Record;

typedef struct MemoryManager {
    Record** records;
    size_t record_count;
    size_t max_records;
    void* shared_extra_data;
    size_t shared_extra_data_size;
    size_t used_memory;
} MemoryManager;

MemoryManager* create_memory_manager(size_t initial_capacity) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->record_count = 0;
    manager->max_records = initial_capacity;
    manager->shared_extra_data = NULL;
    manager->shared_extra_data_size = 0;
    manager->used_memory = 0;

    return manager;
}

void destroy_memory_manager(MemoryManager* manager) {
    for (size_t i = 0; i < manager->record_count; ++i) {
        free(manager->records[i]->extra_data);
        free(manager->records[i]);
    }
    free(manager->records);
    if (manager->shared_extra_data) {
        free(manager->shared_extra_data);
    }
    free(manager);
}

int add_record(MemoryManager* manager, int value, long offset, int key, void* extra_data, size_t extra_data_size, int compression_mode) {
    if (manager->record_count >= manager->max_records || manager->used_memory + sizeof(Record) + extra_data_size > MAX_MEMORY) {
        return -1; // Error: Not enough memory
