int poolSize = 0;

dataNode* getFromMemoryPool() {
    if (memoryPool == NULL || poolSize == 0) {
        return createDataNode("default");
    }
    dataNode* node = memoryPool[--poolSize];
    node->identifier = NULL;
    node->frequency = 0;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void addToMemoryPool(dataNode* node) {
    if (memoryPool == NULL) {
        memoryPool = (dataNode**)malloc(sizeof(dataNode*) * 10);
        poolSize = 0;
    }
    if (poolSize >= 10) {
        dataNode** newPool = (dataNode**)realloc(memoryPool, sizeof(dataNode*) * (poolSize + 10));
        if (newPool == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        memoryPool = newPool;
    }
