typedef struct {
    double value;
    char status;
} item;

item* load_items_from_csv(const char* filename, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open CSV file");
        return NULL;
    }

    // Estimate initial size based on file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    *count = file_size / 256; // Simplified estimation
    item* items = (item*)malloc(*count * sizeof(item));
    if (!items) {
        perror("Failed to allocate memory for items");
        fclose(file);
        return NULL;
    }

    char buffer[1024];
    int i = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        if (i >= *count) {
            // Reallocate more memory
            *count *= 2;
            item* new_items = realloc(items, *count * sizeof(item));
            if (!new_items) {
                perror("Failed to reallocate memory for items");
                free(items);
                fclose(file);
                return NULL;
            }
            items = new_items;
        }

        char* value_str = strtok(buffer, ",");
        char* status_str = strtok(NULL, "\n");

        if (value_str && status_str) {
            items[i].value = atof(value_str);
            items[i].status = *status_str;
            i++;
        }
    }

    fclose(file);
    return items;
}

void persist_items_to_database(item* items, int count) {
    // Simulate database persistence
    for (int i = 0; i < count; i++) {
        printf("Persisting item %d: value=%.2f, status=%c\n", i, items[i].value, items[i].status);
    }
}

void* manage_items(void* arg) {
    const char* filename = "items.csv";
    int count;
    item* items = load_items_from_csv(filename, &count);
    if (!items) {
        return NULL;
    }

    // Simulate modifications to items
    for (int i = 0; i < count; i++) {
        items[i].value += 1.0;
        items[i].status = 'M';
    }

    persist_items_to_database(items, count);

    free(items);
    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, manage_items, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
