#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double amount;
    int id;
    char status;
} Transaction;

typedef struct {
    Transaction* transactions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TransactionManager;

void initTransactionManager(TransactionManager* manager, size_t initialCapacity) {
    manager->transactions = (Transaction*)malloc(initialCapacity * sizeof(Transaction));
    if (!manager->transactions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = initialCapacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void freeTransactionManager(TransactionManager* manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->transactions);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

int loadTransactionsFromCSV(TransactionManager* manager, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open CSV file");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    // Resize the array if necessary
    while (manager->count >= manager->capacity) {
        manager->capacity *= 2;
        manager->transactions = (Transaction*)realloc(manager->transactions, manager->capacity * sizeof(Transaction));
        if (!manager->transactions) {
            fprintf(stderr, "Memory reallocation failed\n");
            fclose(file);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        Transaction* transaction = &manager->transactions[manager->count++];
        sscanf(line, "%lf,%d,%c", &transaction->amount, &transaction->id, &transaction->status);
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
    return 0;
}

Transaction* filterTransactions(TransactionManager* manager, double minAmount, char status) {
    pthread_mutex_lock(&manager->lock);

    // Create a temporary array to hold filtered transactions
    Transaction* filtered = (Transaction*)malloc(manager->count * sizeof(Transaction));
    if (!filtered) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    size_t filterCount = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->transactions[i].amount >= minAmount && manager->transactions[i].status == status) {
            filtered[filterCount++] = manager->transactions[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return filtered;
}

int main() {
    TransactionManager manager;
    initTransactionManager(&manager, 100);

    if (loadTransactionsFromCSV(&manager, "transactions.csv") != 0) {
        freeTransactionManager(&manager);
        return EXIT_FAILURE;
    }

    Transaction* filtered = filterTransactions(&manager, 100.0, 'A');
    if (filtered) {
        for (size_t i = 0; i < manager.count; ++i) {
            printf("Amount: %.2f, ID: %d, Status: %c\n", filtered[i].amount, filtered[i].id, filtered[i].status);
        }
        free(filtered);
    }

    freeTransactionManager(&manager);
    return EXIT_SUCCESS;
}
