#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 256
#define END_OF_INPUT "exit"

typedef struct {
    char **lines;
    int count;
} StringArray;

void trimWhitespace(char *str) {
    // Trim leading whitespace
    while (*str && isspace((unsigned char)*str)) str++;
    if (*str == '\0') return;

    // Trim trailing whitespace
    char *end = str + strlen(str) - 1;
    while (end > str && isspace((unsigned char)*end)) end--;
    *(end + 1) = '\0';
}

void* processFile(void* arg) {
    StringArray *array = (StringArray*)arg;
    FILE *file = fopen("input.txt", "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        trimWhitespace(line);
        if (*line == '\0') continue;

        array->lines = realloc(array->lines, (array->count + 1) * sizeof(char*));
        if (!array->lines) {
            perror("Failed to allocate memory");
            fclose(file);
            return NULL;
        }
        array->lines[array->count] = strdup(line);
        array->count++;
    }

    fclose(file);
    return NULL;
}

void findAndPrintLongestWord(StringArray *array) {
    if (array->count == 0) {
        printf("No lines to process.\n");
        return;
    }

    int maxLength = 0;
    char *longestWord = array->lines[0];
    for (int i = 1; i < array->count; i++) {
        if (strlen(array->lines[i]) > maxLength) {
            maxLength = strlen(array->lines[i]);
            longestWord = array->lines[i];
        }
    }

    printf("Longest word: %s\n", longestWord);
}

void freeStringArray(StringArray *array) {
    for (int i = 0; i < array->count; i++) {
        free(array->lines[i]);
    }
    free(array->lines);
    array->lines = NULL;
    array->count = 0;
}

int main() {
    StringArray array = {NULL, 0};
    pthread_t thread;

    if (pthread_create(&thread, NULL, processFile, &array) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        freeStringArray(&array);
        return EXIT_FAILURE;
    }

    printf("Enter lines of text. Type '%s' to end input:\n", END_OF_INPUT);
    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), stdin)) {
        trimWhitespace(line);
        if (strcmp(line, END_OF_INPUT) == 0) break;

        array.lines = realloc(array.lines, (array.count + 1) * sizeof(char*));
        if (!array.lines) {
            perror("Failed to allocate memory");
            freeStringArray(&array);
            return EXIT_FAILURE;
        }
        array.lines[array.count] = strdup(line);
        array.count++;
    }

    findAndPrintLongestWord(&array);

    freeStringArray(&array);
    return EXIT_SUCCESS;
}
