<?php

class UserDAO {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function updatePassword($userId, $newPassword) {
        // Enforce password complexity rules
        if (strlen($newPassword) < 8 || !preg_match('/[a-z]/', $newPassword) || !preg_match('/[A-Z]/', $newPassword) || !preg_match('/\d/', $newPassword)) {
            throw new Exception("Password must be at least 8 characters long and include a mix of uppercase, lowercase, and digits.");
        }

        // Hash the password
        $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);

        // Log password change attempt
        log_password_change_attempt($userId, 'success');

        // Update the user's password in the database
        $stmt = $this->db->prepare("UPDATE users SET password = ? WHERE id = ?");
        $stmt->bind_param('si', $hashedPassword, $userId);
        $stmt->execute();
    }
}

function log_password_change_attempt($userId, $status) {
    // Log detailed information about each change attempt
    echo "User ID: $userId, Status: $status\n";
}
