#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct metricNode {
    double value;
    time_t timestamp;
    int frequency;
} metricNode;

typedef struct hashTable {
    metricNode** buckets;
    size_t size;
    size_t count;
} hashTable;

hashTable* createHashTable(size_t size) {
    hashTable* table = (hashTable*)malloc(sizeof(hashTable));
    if (!table) return NULL;
    table->buckets = (metricNode**)calloc(size, sizeof(metricNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->size = size;
    table->count = 0;
    return table;
}

void destroyHashTable(hashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        metricNode* node = table->buckets[i];
        while (node) {
            metricNode* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    free(table);
}

void insertMetric(hashTable* table, double value, time_t timestamp) {
    size_t index = hashFunction(value, table->size);
    metricNode* newNode = (metricNode*)malloc(sizeof(metricNode));
    if (!newNode) return;
    newNode->value = value;
    newNode->timestamp = timestamp;
    newNode->frequency = 1;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    ++table->count;
}

double calculateAverageMetric(hashTable* table) {
    double sum = 0.0;
    for (size_t i = 0; i < table->size; ++i) {
        metricNode* node = table->buckets[i];
        while (node) {
            sum += node->value * node->frequency;
            node = node->next;
        }
    }
    return sum / table->count;
}

void garbageCollect(hashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        metricNode* node = table->buckets[i];
        while (node) {
            if (isUnused(node)) {
                metricNode* next = node->next;
                free(node);
                node = next;
            } else {
                node = node->next;
            }
        }
    }
}

int main() {
    hashTable* table = createHashTable(1024);
    if (!table) {
        fprintf(stderr, "Failed to allocate memory for hash table\n");
        return 1;
    }

    // Simulate inserting metrics
    insertMetric(table, 3.14, time(NULL));
    insertMetric(table, 2.71, time(NULL));

    double average = calculateAverageMetric(table);
    printf("Average Metric: %f\n", average);

    destroyHashTable(table);
    return 0;
}
