#define NUM_RECORDS 5

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
    int status;
    int retries;
} Metadata;

Metadata* initialize_data_structures(size_t alignment, int seed, int min_value, int max_value, double max_time) {
    Metadata* metadata = (Metadata*)aligned_alloc(alignment, NUM_RECORDS * sizeof(Metadata));
    if (!metadata) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < NUM_RECORDS; ++i) {
        metadata[i].offset = i * alignment;
        metadata[i].key = rand() % (max_value - min_value + 1) + min_value;
        do {
            metadata[i].record.value = rand() % (max_value - min_value + 1) + min_value;
        } while (i > 0 && metadata[i].record.value == metadata[i - 1].record.value);
        metadata[i].status = 1; // Assuming all records are initialized successfully
        metadata[i].retries = 0;
    }

    clock_t start_time = clock();
    while ((clock() - start_time) / CLOCKS_PER_SEC < max_time && !all_initialized(metadata)) {
        for (int i = 0; i < NUM_RECORDS; ++i) {
            if (!metadata[i].status) {
                // Attempt to initialize the record
                metadata[i].record.value = rand() % (max_value - min_value + 1) + min_value;
                metadata[i].status = 1;
                metadata[i].retries++;
            }
        }
    }

    return metadata;
}

int all_initialized(Metadata* metadata) {
    for (int i = 0; i < NUM_RECORDS; ++i) {
        if (!metadata[i].status) {
            return 0;
        }
    }
    return 1;
}

void free_metadata(Metadata* metadata) {
    free(metadata);
}
