MemoryPool memory_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void init_memory_pool(size_t initial_size) {
    memory_pool.pool = (ResourceMetrics*)malloc(initial_size * sizeof(ResourceMetrics));
    if (!memory_pool.pool) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        exit(EXIT_FAILURE);
    }
    memory_pool.pool_size = initial_size;
    memory_pool.used_size = 0;
}

void* allocate_resource_metrics() {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.used_size >= memory_pool.pool_size) {
        size_t new_size = memory_pool.pool_size * 2;
        ResourceMetrics* new_pool = realloc(memory_pool.pool, new_size * sizeof(ResourceMetrics));
        if (!new_pool) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&memory_pool.lock);
            return NULL;
        }
        memory_pool.pool = new_pool;
        memory_pool.pool_size = new_size;
    }
    ResourceMetrics* metrics = &memory_pool.pool[memory_pool.used_size++];
    pthread_mutex_unlock(&memory_pool.lock);
    return metrics;
}

void free_memory_pool() {
    pthread_mutex_lock(&memory_pool.lock);
    free(memory_pool.pool);
    memory_pool.pool = NULL;
    memory_pool.pool_size = 0;
