    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    int count;
    pthread_mutex_t mutex;
} CRC_LIST_T;

CRC_LIST_T crc_list;

void initialize_crc_list() {
    pthread_mutex_init(&crc_list.mutex, NULL);
    crc_list.count = 0;
}

int create_and_populate_crc_pdu(int N) {
    if (N > MAX_ELEMENTS) {
        return -1; // Error: Exceeds maximum elements
    }

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&crc_list.mutex);
        if (crc_list.count >= MAX_ELEMENTS) {
            pthread_mutex_unlock(&crc_list.mutex);
            return -2; // Error: List is full
        }
        crc_list.elements[crc_list.count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_list.elements[crc_list.count]) {
            pthread_mutex_unlock(&crc_list.mutex);
            return -3; // Error: Memory allocation failed
        }

        NFAPI_CRC_INDICATION_PDU_T *pdu = crc_list.elements[crc_list.count];
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->RNTI = rand() % 256;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 2;
        pdu->CRCFLAG = rand() % 2;

        crc_list.count++;
        pthread_mutex_unlock(&crc_list.mutex);
    }

    return crc_list.count; // Return number of successfully created elements
}

int get_crc_list_count() {
    int count;
    pthread_mutex_lock(&crc_list.mutex);
    count = crc_list.count;
    pthread_mutex_unlock(&crc_list.mutex);
    return count;
}
