    long current_offset = 0;
    for (int i = 0; i < n; i++) {
        (*records)[i].value = MIN_VALUE + rand() % (MAX_VALUE - MIN_VALUE + 1);
        (*records)[i].offset = *offsets + i;
        (*records)[i].key = i;

        current_offset += sizeof(record);
    }

    return 0; // Success
