void insert_element(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&mutex);
    if (count >= MAX_ELEMENTS) {
        printf("Error: List is full\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    for (int i = 0; i < count; i++) {
        if (list[i]->RNTI == RNTI) {
            printf("Error: Duplicate RNTI\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    NFAPI_CRC_INDICATION_PDU_T *new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_element->RNTI = RNTI;
    new_element->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    list[count++] = new_element;
    pthread_mutex_unlock(&mutex);
}

void *export_data(void *arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        if (count == 0) {
            pthread_mutex_unlock(&mutex);
            break;
        }
        NFAPI_CRC_INDICATION_PDU_T *element = list[0];
        for (int i = 1; i < count; i++) {
            list[i - 1] = list[i];
        }
        count--;
        pthread_mutex_unlock(&mutex);

        // Simulate export to another module
        printf("Exporting data: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
               element->RX_UE_INFORMATION_TAG, element->RNTI, element->CRC_INDICATION_REL8_TAG);
        free(element);

        // Backoff strategy
        usleep(1000); // Sleep for 1ms
    }
    return NULL;
}

int main() {
