typedef struct {
    SSL_CTX *ctx;
    pthread_mutex_t session_cache_lock;
    // Other necessary fields
} WebSocketServer;

void init_websocket_server(WebSocketServer *server, int port, const char *cert_dir, const char *key_file, const char *passphrase) {
    server->ctx = SSL_CTX_new(TLS_server_method());
    if (!server->ctx) {
        fprintf(stderr, "Failed to create SSL context\n");
        return;
    }

    // Load certificates and private key
    if (SSL_CTX_use_certificate_chain_file(server->ctx, cert_dir) != 1 ||
        SSL_CTX_use_PrivateKey_file(server->ctx, key_file, SSL_FILETYPE_PEM) != 1) {
        fprintf(stderr, "Failed to load certificates or private key\n");
        SSL_CTX_free(server->ctx);
        return;
    }

    // Set up passphrase callback
    SSL_CTX_set_default_passwd_cb(server->ctx, [](char *buf, int size, int rwflag, void *userdata) -> int {
        strcpy(buf, (const char *)userdata);
        return strlen(passphrase);
    });
    SSL_CTX_set_default_passwd_cb_userdata(server->ctx, (void *)passphrase);

    // Enable session caching
    SSL_CTX_set_session_cache_mode(server->ctx, SSL_SESS_CACHE_SERVER | SSL_SESS_CACHE_NO_INTERNAL_LOOKUP);
    pthread_mutex_init(&server->session_cache_lock, NULL);

    // Load configuration file
    if (!load_config_file(CONFIG_FILE)) {
        fprintf(stderr, "Failed to load configuration file\n");
        SSL_CTX_free(server->ctx);
        return;
    }

    // Initialize server socket and start listening
    // ...
}

int main() {
    WebSocketServer server;
    init_websocket_server(&server, 8443, DEFAULT_CERT_DIR, "server.key", "password123");

    if (!server.ctx) {
        fprintf(stderr, "Failed to initialize WebSocket server\n");
        return EXIT_FAILURE;
    }

    // Start accepting client connections
    // ...

    SSL_CTX_free(server.ctx);
    pthread_mutex_destroy(&server.session_cache_lock);

    return EXIT_SUCCESS;
}
