#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_KEYS 1000
#define MAX_RECORDS 500
#define MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    pthread_mutex_t lock;
} Database;

Database* db_init(int max_keys, int max_records) {
    if (max_keys > MAX_KEYS || max_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Maximum key or record limit exceeded.\n");
        return NULL;
    }

    Database* db = malloc(sizeof(Database));
    if (!db) {
        fprintf(stderr, "Error: Memory allocation failed for database structure.\n");
        return NULL;
    }

    db->offsets = malloc(max_keys * sizeof(long));
    if (!db->offsets) {
        fprintf(stderr, "Error: Memory allocation failed for offsets array.\n");
        free(db);
        return NULL;
    }

    db->keys = malloc(max_keys * sizeof(int));
    if (!db->keys) {
        fprintf(stderr, "Error: Memory allocation failed for keys array.\n");
        free(db->offsets);
        free(db);
        return NULL;
    }

    db->records = malloc(max_records * sizeof(Record*));
    if (!db->records) {
        fprintf(stderr, "Error: Memory allocation failed for records array.\n");
        free(db->keys);
        free(db->offsets);
        free(db);
        return NULL;
    }

    pthread_mutex_init(&db->lock, NULL);

    // Initialize offsets and keys
    for (int i = 0; i < max_keys; i++) {
        db->offsets[i] = i * sizeof(Record);
        db->keys[i] = i + 1;
    }

    return db;
}

void db_insert(Database* db, int key, Record record) {
    pthread_mutex_lock(&db->lock);

    // Check if key is unique and within range
    for (int i = 0; i < MAX_KEYS; i++) {
        if (db->keys[i] == key) {
            fprintf(stderr, "Error: Key already exists in the database.\n");
            pthread_mutex_unlock(&db->lock);
            return;
        }
    }

    // Find an empty slot for the record
    int index = -1;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (!db->records[i]) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        fprintf(stderr, "Error: No space available in the database.\n");
        pthread_mutex_unlock(&db->lock);
        return;
    }

    // Allocate memory for the record
    db->records[index] = malloc(sizeof(Record));
    if (!db->records[index]) {
        fprintf(stderr, "Error: Memory allocation failed for new record.\n");
        pthread_mutex_unlock(&db->lock);
        return;
    }

    *db->records[index] = record;

    // Update the key
    db->keys[index] = key;

    pthread_mutex_unlock(&db->lock);
}

Record* db_search(Database* db, int key) {
    pthread_mutex_lock(&db->lock);

    for (int i = 0; i < MAX_KEYS; i++) {
        if (db->keys[i] == key) {
            Record* record = db->records[i];
            pthread_mutex_unlock(&db->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&db->lock);
    return NULL;
}

void db_free(Database* db) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (db->records[i]) {
            free(db->records[i]);
        }
    }

    free(db->offsets);
    free(db->keys);
    free(db->records);
    pthread_mutex_destroy(&db->lock);
    free(db);
}
