Record* init_records(int size, int range) {
    if (size > MAX_DATA_SIZE || range <= 0) return NULL;

    Record* records = malloc(size * sizeof(Record));
    if (!records) return NULL;

    srand(time(NULL));

    for (int i = 0; i < size; ++i) {
        records[i].key = -1000 + i;
        records[i].offset = i;
        records[i].value = rand() % range + 1;

        // Ensure unique values
        while (i > 0 && records[i].value == records[i-1].value) {
            records[i].value = rand() % range + 1;
        }

        int str_len = rand() % 17; // Random length from 0 to 16
        records[i].str = malloc((str_len + 1) * sizeof(char));
        if (!records[i].str) {
            free_records(records, i);
            return NULL;
        }
        for (int j = 0; j < str_len; ++j) {
            records[i].str[j] = 'a' + rand() % 26;
        }
        records[i].str[str_len] = '\0';
    }

    return records;
}

void free_records(Record* records, int size) {
    for (int i = 0; i < size; ++i) {
        free(records[i].str);
    }
    free(records);
}

void print_records(Record* records, int size) {
    for (int i = 0; i < size; ++i) {
        printf("Key: %d, Offset: %ld, Value: %d, String: %s\n",
               records[i].key, records[i].offset, records[i].value, records[i].str);
    }
}

int main() {
    int size = 5;
    int range = 100;

    Record* records = init_records(size, range);
    if (records) {
        print_records(records, size);
        free_records(records, size);
    } else {
        printf("Failed to initialize records.\n");
    }

    return 0;
}
