#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024
#define NUM_THREADS 4

typedef struct {
    char *line;
    int line_number;
} LineData;

typedef struct {
    pthread_t thread_id;
    LineData *data;
    int result_index;
} ThreadInfo;

void *process_line(void *arg) {
    ThreadInfo *info = (ThreadInfo *)arg;
    LineData *data = info->data;
    char *token = strtok(data->line, ",");
    double sum = 0.0;
    int count = 0;

    while (token != NULL) {
        if (count >= 2) {
            sum += atof(token);
        }
        token = strtok(NULL, ",");
        count++;
    }

    if (count < 2) {
        printf("Error: Line %d has insufficient numerical fields.\n", data->line_number);
        return NULL;
    }

    double average = sum / 2.0;

    // Append the average to the line
    char *new_line = realloc(data->line, strlen(data->line) + 50);
    if (new_line == NULL) {
        printf("Error: Failed to reallocate memory for line %d.\n", data->line_number);
        return NULL;
    }
    data->line = new_line;

    sprintf(new_line + strlen(new_line), ",%.2f", average);

    // Store the result
    info->result_index = data->line_number - 1; // Assuming results are stored in an array

    return NULL;
}

void *resolve_dns(void *arg) {
    ThreadInfo *info = (ThreadInfo *)arg;
    LineData *data = info->data;

    struct hostent *host_info = gethostbyname(data->line);
    if (host_info == NULL) {
        printf("Error: Failed to resolve DNS for %s.\n", data->line);
        return NULL;
    }

    // Store the IP address
    char ip_address[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, host_info->h_addr_list[0], ip_address, INET_ADDRSTRLEN);

    printf("DNS resolved: %s -> %s\n", data->line, ip_address);

    return NULL;
}

int main() {
    FILE *file = fopen("data.csv", "r");
    if (file == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    LineData lines[MAX_LINE_LENGTH];
    ThreadInfo thread_info[NUM_THREADS];

    int line_count = 0;

    while (fgets(lines[line_count].line, MAX_LINE_LENGTH, file)) {
        lines[line_count].line_number = line_count + 1;
        line_count++;
    }

    fclose(file);

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; i++) {
        thread_info[i].thread_id = pthread_self();
        thread_info[i].data = &lines[i * (line_count / NUM_THREADS)];
        if (i == NUM_THREADS - 1) {
            thread_info[i].data += line_count % NUM_THREADS;
        }
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, process_line, &thread_info[i]);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // DNS resolution
    for (int i = 0; i < line_count; i++) {
        pthread_create(&threads[i % NUM_THREADS], NULL, resolve_dns, &thread_info[i % NUM_THREADS]);
    }

    for (int i = 0; i < line_count; i++) {
        pthread_join(threads[i % NUM_THREADS], NULL);
    }

    return EXIT_SUCCESS;
}
