status_t initialize_sensor_data(double **temperature, float **humidity, char ***sensor_ids, time_t **timestamps, status_struct **states, int num_sensors) {
    *temperature = (double *)malloc(num_sensors * sizeof(double));
    *humidity = (float *)malloc(num_sensors * sizeof(float));
    *sensor_ids = (char **)malloc(num_sensors * sizeof(char *));
    *timestamps = (time_t *)malloc(num_sensors * sizeof(time_t));
    *states = (status_struct *)malloc(num_sensors * sizeof(status_struct));

    if (!*temperature || !*humidity || !*sensor_ids || !*timestamps || !*states) {
        printf("Memory allocation failed\n");
        return ERROR;
    }

    for (int i = 0; i < num_sensors; i++) {
        (*temperature)[i] = 20.0 + i * 0.5;
        (*humidity)[i] = 40.0 + i * 1.0;
        (*sensor_ids)[i] = (char *)malloc(9 * sizeof(char));
        snprintf((*sensor_ids)[i], 9, "Sensor%03d", i);
        (*timestamps)[i] = time(NULL);

        if (!(*sensor_ids)[i]) {
            printf("Memory allocation failed for sensor ID\n");
            return ERROR;
        }

        static enum status current_status = OK;
        do {
            (*states)[i].value = current_status;
            snprintf((*states)[i].description, 32, "Status %d", (int)current_status);
            current_status = (current_status == OK) ? ERROR : OK;
        } while (i > 0 && (*states)[i].value == (*states)[i - 1].value);
    }

    return OK;
}

void free_sensor_data(double *temperature, float *humidity, char **sensor_ids, time_t *timestamps, status_struct *states, int num_sensors) {
    for (int i = 0; i < num_sensors; i++) {
        free(sensor_ids[i]);
    }
    free(temperature);
    free(humidity);
    free(sensor_ids);
    free(timestamps);
    free(states);
}

int main() {
    double *temperature;
    float *humidity;
    char **sensor_ids;
    time_t *timestamps;
    status_struct *states;

    int num_sensors = 50;
    if (initialize_sensor_data(&temperature, &humidity, &sensor_ids, &timestamps, &states, num_sensors) == OK) {
        // Process sensor data
        free_sensor_data(temperature, humidity, sensor_ids, timestamps, states, num_sensors);
    }

    return 0;
}
