#define MAX_FLOATS 1000
#define MAX_IDS 1000
#define MAX_STRINGS 1000
#define MAX_STATUS_INDICATORS 5

typedef enum {
    STATUS_OK,
    STATUS_WARNING,
    STATUS_ERROR
} Status;

typedef struct {
    float value;
    unsigned short id;
    char data[256];
    Status status;
    time_t timestamp;
} Metric;

Metric* allocate_and_initialize_metrics(int max_floats, int max_ids, int max_strings, int max_status_indicators) {
    Metric* metrics = (Metric*)malloc(max_floats * sizeof(Metric));
    if (!metrics) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < max_floats; ++i) {
        metrics[i].value = exp(i / 10.0); // Logarithmic sequence
        metrics[i].id = rand() % max_ids + 1;
        snprintf(metrics[i].data, sizeof(metrics[i].data), "Data_%d", i);
        metrics[i].status = (Status)(rand() % MAX_STATUS_INDICATORS);
        metrics[i].timestamp = time(NULL) + (rand() % 201 - 100); // Adjusted by random offset
    }

    return metrics;
}

void free_metrics(Metric* metrics, int max_floats) {
    if (metrics) {
        free(metrics);
    }
}

int main() {
    Metric* metrics = allocate_and_initialize_metrics(MAX_FLOATS, MAX_IDS, MAX_STRINGS, MAX_STATUS_INDICATORS);
    if (metrics) {
        // Use the metrics array here
        free_metrics(metrics, MAX_FLOATS);
    }

    return 0;
}
