#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_KEY_VALUE 1000000
#define MEMORY_LIMIT 1024 * 1024 * 1024 // 1GB

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    pthread_mutex_t lock;
    size_t allocated_size;
    size_t used_size;
} InMemoryDB;

InMemoryDB* init_db(size_t initial_size) {
    InMemoryDB* db = (InMemoryDB*)malloc(sizeof(InMemoryDB));
    if (!db) return NULL;

    db->offsets = (long*)calloc(initial_size, sizeof(long));
    db->keys = (int*)calloc(initial_size, sizeof(int));
    db->records = (Record**)calloc(initial_size, sizeof(Record*));
    pthread_mutex_init(&db->lock, NULL);
    db->allocated_size = initial_size;
    db->used_size = 0;

    if (!db->offsets || !db->keys || !db->records) {
        free(db->offsets);
        free(db->keys);
        free(db->records);
        pthread_mutex_destroy(&db->lock);
        free(db);
        return NULL;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        db->offsets[i] = i * sizeof(Record);
    }

    return db;
}

void destroy_db(InMemoryDB* db) {
    if (!db) return;

    for (size_t i = 0; i < db->used_size; ++i) {
        free(db->records[i]);
    }

    free(db->offsets);
    free(db->keys);
    free(db->records);
    pthread_mutex_destroy(&db->lock);
    free(db);
}

int insert_record(InMemoryDB* db, int key, int value) {
    if (!db || key < 0 || key >= MAX_KEY_VALUE) return -1;

    pthread_mutex_lock(&db->lock);

    if (db->used_size == db->allocated_size) {
        size_t new_size = db->allocated_size * 2;
        long* new_offsets = (long*)realloc(db->offsets, new_size * sizeof(long));
        int* new_keys = (int*)realloc(db->keys, new_size * sizeof(int));
        Record** new_records = (Record**)realloc(db->records, new_size * sizeof(Record*));

        if (!new_offsets || !new_keys || !new_records) {
            pthread_mutex_unlock(&db->lock);
            return -1;
        }

        db->offsets = new_offsets;
        db->keys = new_keys;
        db->records = new_records;
        for (size_t i = db->allocated_size; i < new_size; ++i) {
            db->offsets[i] = i * sizeof(Record);
        }
        db->allocated_size = new_size;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&db->lock);
        return -1;
    }

    record->value = value;
    db->keys[db->used_size] = key;
    db->records[db->used_size++] = record;

    pthread_mutex_unlock(&db->lock);
    return 0;
}

Record* search_record(InMemoryDB* db, int key) {
    if (!db || key < 0 || key >= MAX_KEY_VALUE) return NULL;

    for (size_t i = 0; i < db->used_size; ++i) {
        if (db->keys[i] == key) {
            return db->records[i];
        }
    }

    return NULL;
}
