typedef struct task {
    char description[256];
    struct task* next;
} Task;

typedef struct project {
    double budget;
    char description[256];
    Task* tasks;
} Project;

typedef struct worker {
    float salary;
    char name[100];
    Project* project;
} Worker;

typedef struct department {
    float budget;
    char name[50];
    struct department* next;
} Department;

void log_allocation(const char* type, size_t size) {
    time_t now = time(NULL);
    printf("Allocated %zu bytes for %s at %s\n", size, type, ctime(&now));
}

Worker** allocate_workers(int count) {
    Worker** workers = (Worker**)malloc(count * sizeof(Worker*));
    if (!workers) {
        fprintf(stderr, "Failed to allocate memory for workers\n");
        exit(EXIT_FAILURE);
    }
    log_allocation("worker pointers", count * sizeof(Worker*));
    return workers;
}

Project* allocate_project() {
    Project* project = (Project*)malloc(sizeof(Project));
    if (!project) {
        fprintf(stderr, "Failed to allocate memory for project\n");
        exit(EXIT_FAILURE);
    }
    log_allocation("project", sizeof(Project));
    memset(project, 0, sizeof(Project));
    return project;
}

Task* allocate_task() {
    Task* task = (Task*)malloc(sizeof(Task));
    if (!task) {
        fprintf(stderr, "Failed to allocate memory for task\n");
        exit(EXIT_FAILURE);
    }
    log_allocation("task", sizeof(Task));
    memset(task, 0, sizeof(Task));
    return task;
}

Department* allocate_department() {
    Department* department = (Department*)malloc(sizeof(Department));
    if (!department) {
        fprintf(stderr, "Failed to allocate memory for department\n");
        exit(EXIT_FAILURE);
    }
    log_allocation("department", sizeof(Department));
    memset(department, 0, sizeof(Department));
    return department;
}

void free_worker(Worker* worker) {
    if (worker->project) {
        Project* project = worker->project;
        while (project->tasks) {
            Task* task = project->tasks;
            project->tasks = task->next;
            free(task);
        }
        free(project);
    }
    free(worker);
}

void free_workers(Worker** workers, int count) {
    for (int i = 0; i < count; ++i) {
        if (workers[i]) {
            free_worker(workers[i]);
        }
    }
    free(workers);
}

void free_project(Project* project) {
    while (project->tasks) {
        Task* task = project->tasks;
        project->tasks = task->next;
        free(task);
    }
    free(project);
}

void free_department(Department* department) {
    Department* current = department;
    while (current) {
        Department* next = current->next;
        free_project(current->project);
        free(current);
        current = next;
    }
}
