#define MAX_NAME_LENGTH 256

typedef struct FileSystemObject {
    char name[MAX_NAME_LENGTH];
    int size;
    struct FileSystemObject** children;
    int numChildren;
    int maxChildren;
} FileSystemObject;

FileSystemObject* createFileSystemObject(const char* name, int size) {
    FileSystemObject* obj = (FileSystemObject*)malloc(sizeof(FileSystemObject));
    if (!obj) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    strncpy(obj->name, name, MAX_NAME_LENGTH - 1);
    obj->size = size;
    obj->children = NULL;
    obj->numChildren = 0;
    obj->maxChildren = 0;
    return obj;
}

void addChild(FileSystemObject* parent, FileSystemObject* child) {
    if (parent->numChildren >= parent->maxChildren) {
        parent->maxChildren += 10;
        parent->children = realloc(parent->children, parent->maxChildren * sizeof(FileSystemObject*));
        if (!parent->children) {
            fprintf(stderr, "Memory reallocation failed\n");
            return;
        }
    }
    parent->children[parent->numChildren++] = child;
}

void printFileSystem(const FileSystemObject* obj, int depth) {
    for (int i = 0; i < depth; ++i) printf("  ");
    printf("%s (%d)\n", obj->name, obj->size);
    for (int i = 0; i < obj->numChildren; ++i) {
        printFileSystem(obj->children[i], depth + 1);
    }
}

void freeFileSystem(FileSystemObject* obj) {
    for (int i = 0; i < obj->numChildren; ++i) {
        freeFileSystem(obj->children[i]);
    }
    if (obj->children) {
        free(obj->children);
    }
    free(obj);
}
