        unsigned short rnti;
        do {
            rnti = rand() % (MAX_RNTI + 1); // Generate a random RNTI
        } while (!is_unique_rnti(array, i, rnti));
        array[i].RNTI = rnti;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        pthread_mutex_unlock(&mutex);
    }

    return array;
}

int main() {
    int N = 1000;
    int max_size = 10 * 1024 * 1024; // 10 MB
    ProcessingMode mode = SYNCHRONOUS;

    NFAPI_CRC_INDICATION_PDU_T* array = allocate_and_populate_array(N, max_size, mode);
    if (array != NULL) {
        free(array);
    }

    return 0;
}
