#define MAX_MEMORY 1024 * 1024 // 1 MB

typedef struct Record {
    int value;
    long* offset;
    int key;
} Record;

typedef struct Node {
    char name[256];
    size_t size;
    struct Node** children;
    int num_children;
    int max_children;
} Node;

Node* create_node(const char* name, size_t size) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    strcpy(node->name, name);
    node->size = size;
    node->children = (Node**)malloc(size * sizeof(Node*));
    if (!node->children) {
        free(node);
        return NULL;
    }
    node->num_children = 0;
    node->max_children = size;
    return node;
}

void add_child(Node* parent, Node* child) {
    if (parent->num_children >= parent->max_children) {
        parent->max_children *= 2;
        parent->children = (Node**)realloc(parent->children, parent->max_children * sizeof(Node*));
    }
    parent->children[parent->num_children++] = child;
}

void traverse_depth_first(Node* node) {
    if (!node) return;
    printf("Node: %s\n", node->name);
    for (int i = 0; i < node->num_children; i++) {
        traverse_depth_first(node->children[i]);
    }
}

void traverse_breadth_first(Node* root) {
    Node** queue = (Node**)malloc(root->max_children * sizeof(Node*));
    int front = 0, rear = 0;
    queue[rear++] = root;

    while (front < rear) {
        Node* current = queue[front++];
        printf("Node: %s\n", current->name);
        for (int i = 0; i < current->num_children; i++) {
            queue[rear++] = current->children[i];
        }
    }

    free(queue);
}

void free_node(Node* node) {
    if (!node) return;
    for (int i = 0; i < node->num_children; i++) {
        free_node(node->children[i]);
    }
    free(node->children);
    free(node);
}

int main() {
    Node* root = create_node("root", 10);
    if (!root) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    Node* child1 = create_node("child1", 5);
    if (!child1) {
        free_node(root);
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }
    add_child(root, child1);

    Node* child2 = create_node("child2", 3);
    if (!child2) {
        free_node(root);
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }
    add_child(root, child2);

    traverse_depth_first(root);
    printf("\n");
    traverse_breadth_first(root);

    free_node(root);
    return 0;
}
