#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int ResourceID;
    time_t Timestamp;
    double *MetricsData;
    size_t MetricsCount;
} ResourceMetric;

typedef struct {
    ResourceMetric **metricsArray;
    size_t allocatedSize;
    size_t usedSize;
    pthread_mutex_t lock;
} MetricPool;

void initMetricPool(MetricPool *pool, size_t initialSize) {
    pool->allocatedSize = initialSize;
    pool->usedSize = 0;
    pool->metricsArray = (ResourceMetric **)malloc(initialSize * sizeof(ResourceMetric *));
    pthread_mutex_init(&pool->lock, NULL);
}

void destroyMetricPool(MetricPool *pool) {
    for (size_t i = 0; i < pool->usedSize; ++i) {
        free(pool->metricsArray[i]->MetricsData);
        free(pool->metricsArray[i]);
    }
    free(pool->metricsArray);
    pthread_mutex_destroy(&pool->lock);
}

int addResourceMetric(MetricPool *pool, ResourceMetric *metric) {
    pthread_mutex_lock(&pool->lock);
    if (pool->usedSize >= pool->allocatedSize) {
        size_t newSize = pool->allocatedSize * 2;
        ResourceMetric **newArray = (ResourceMetric **)realloc(pool->metricsArray, newSize * sizeof(ResourceMetric *));
        if (!newArray) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Memory allocation failed
        }
        pool->metricsArray = newArray;
        pool->allocatedSize = newSize;
    }
    pool->metricsArray[pool->usedSize++] = metric;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Additional functions for batch processing, aggregation, performance optimization, and logging would be implemented here
