#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NAME_LENGTH 100

typedef struct User {
    char name[MAX_NAME_LENGTH];
    int age;
    struct User** friends;
    int numFriends;
} User;

User* createGraph(int totalUsers, int avgFriendsPerUser) {
    // Allocate memory for the root user
    User* root = (User*)malloc(sizeof(User));
    if (!root) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize the root user's name and age
    strcpy(root->name, "Root");
    root->age = 25;

    // Allocate memory for friends
    root->friends = (User**)malloc(avgFriendsPerUser * sizeof(User*));
    if (!root->friends) {
        fprintf(stderr, "Memory allocation failed\n");
        free(root);
        return NULL;
    }
    root->numFriends = 0;

    // Initialize other users and friendships
    for (int i = 1; i < totalUsers; i++) {
        User* newUser = (User*)malloc(sizeof(User));
        if (!newUser) {
            fprintf(stderr, "Memory allocation failed\n");
            freeGraph(root);
            return NULL;
        }

        // Initialize user's name and age
        snprintf(newUser->name, MAX_NAME_LENGTH, "User%d", i);
        newUser->age = (i % 10) + 25; // Ensure unique ages

        // Allocate memory for friends
        newUser->friends = (User**)malloc(avgFriendsPerUser * sizeof(User*));
        if (!newUser->friends) {
            fprintf(stderr, "Memory allocation failed\n");
            freeGraph(newUser);
            freeGraph(root);
            return NULL;
        }
        newUser->numFriends = 0;

        // Add friends to the new user
        for (int j = 0; j < avgFriendsPerUser && root->numFriends > 0; j++) {
            if (rand() % 2 == 0) { // Randomly add a friend from existing users
                newUser->friends[j] = root;
                newUser->numFriends++;
                root->friends[root->numFriends - 1] = newUser;
                root->numFriends++;
            }
        }

        // Add the new user to the graph
        root->friends[i - 1] = newUser;
        root->numFriends++;
    }

    return root;
}

void freeGraph(User* root) {
    if (root) {
        for (int i = 0; i < root->numFriends; i++) {
            freeGraph(root->friends[i]);
        }
        free(root->friends);
        free(root);
    }
}

void printGraph(User* root, int depth) {
    if (!root) return;

    for (int i = 0; i < depth; i++) printf("  ");
    printf("%s (%d)\n", root->name, root->age);

    for (int i = 0; i < root->numFriends; i++) {
        printGraph(root->friends[i], depth + 1);
    }
}

int main() {
    int totalUsers = 10;
    int avgFriendsPerUser = 3;

    User* graph = createGraph(totalUsers, avgFriendsPerUser);
    if (graph) {
        printGraph(graph, 0);
        freeGraph(graph);
    }

    return 0;
}
