#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SETTINGS 100
#define CACHE_SIZE 50

typedef struct {
    char *key;
    char *value;
} Setting;

Setting cache[CACHE_SIZE];
int cache_count = 0;

int load_config(const char *filename, Setting **settings) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1; // Error code for missing or malformed files
    }

    int setting_count = 0;
    while (setting_count < MAX_SETTINGS && fgets(settings[setting_count], sizeof(Setting), file)) {
        settings[setting_count]->key = strtok(settings[setting_count], "=");
        if (!settings[setting_count]->key) {
            fprintf(stderr, "Malformed line in configuration file\n");
            fclose(file);
            return -1; // Error code for malformed lines
        }
        settings[setting_count]->value = strtok(NULL, "\n");
        setting_count++;
    }

    fclose(file);
    return setting_count;
}

int get_setting(const char *filename, const char *key) {
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(cache[i].key, key) == 0) {
            return atoi(cache[i].value);
        }
    }

    Setting settings[MAX_SETTINGS];
    int setting_count = load_config(filename, settings);
    if (setting_count <= 0) {
        return -1; // Error code for missing or malformed files
    }

    for (int i = 0; i < setting_count; i++) {
        if (strcmp(settings[i].key, key) == 0) {
            cache[cache_count++] = settings[i];
            return atoi(cache[i].value);
        }
    }

    fprintf(stderr, "Setting not found in configuration file\n");
    return -1;
}

int main() {
    const char *filename = "config.txt";
    Setting *settings = (Setting *)malloc(MAX_SETTINGS * sizeof(Setting));
    if (!settings) {
        perror("Failed to allocate memory for settings");
        return 1;
    }

    int setting_count = load_config(filename, settings);
    if (setting_count <= 0) {
        free(settings);
        return 1;
    }

    printf("Number of settings: %d\n", setting_count);

    // Example usage
    int value = get_setting(filename, "example_key");
    if (value != -1) {
        printf("Value for example_key: %d\n", value);
    } else {
        printf("Failed to retrieve value for example_key\n");
    }

    free(settings);
    return 0;
}
