sensorData *sensorArray[MAX_DEVICES];
int deviceCount = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* initializeSensorData(void* arg) {
    int id = *(int*)arg;
    pthread_mutex_lock(&mutex);
    if (deviceCount >= MAX_DEVICES) {
        printf("Device limit reached\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    sensorArray[deviceCount] = malloc(sizeof(sensorData));
    if (!sensorArray[deviceCount]) {
        printf("Memory allocation failed for device %d\n", id);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    sensorArray[deviceCount]->timestamp = time(NULL);
    sensorArray[deviceCount]->reading = 0.0; // Default reading
    snprintf(sensorArray[deviceCount]->identifier, sizeof(sensorArray[deviceCount]->identifier), "dev%d", id);
    deviceCount++;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void populateSensorReadings(float mean, float stddev) {
    for (int i = 0; i < deviceCount; i++) {
        sensorArray[i]->reading = mean + stddev * ((float)rand() / RAND_MAX * 2 - 1);
    }
}

void* reclaimMemory(void* arg) {
    pthread_mutex_lock(&mutex);
    if (deviceCount > THRESHOLD) {
        for (int i = deviceCount - 1; i >= THRESHOLD; i--) {
            free(sensorArray[i]);
            sensorArray[i] = NULL;
        }
        deviceCount = THRESHOLD;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void serializeSensorData() {
    // Implement serialization logic here
}

void deserializeSensorData() {
    // Implement deserialization logic here
}

int main() {
    int ids[MAX_DEVICES];
    for (int i = 0; i < MAX_DEVICES; i++) {
        ids[i] = i;
        pthread_t thread;
        pthread_create(&thread, NULL, initializeSensorData, &ids[i]);
        pthread_join(thread, NULL);
    }
    populateSensorReadings(10.0, 2.0);
    pthread_t reclaimThread;
    pthread_create(&reclaimThread, NULL, reclaimMemory, NULL);
    pthread_join(reclaimThread, NULL);
    serializeSensorData();
    deserializeSensorData();
    return 0;
}
