#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_MEMORY 1024 * 1024 // 1MB

typedef struct node {
    char* str;
    struct node* next;
} Node;

Node* create_node(const char* str) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->str = strdup(str);
    new_node->next = NULL;
    return new_node;
}

void free_node(Node* node) {
    free(node->str);
    free(node);
}

Node* insert_node(Node** head, const char* str) {
    Node* new_node = create_node(str);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    return new_node;
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free_node(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    double measurements[10];
    char identifiers[10][256];
    Node* head = NULL;
    bool status_flags[10];

    // Initialize data structures
    for (int i = 0; i < 10; i++) {
        measurements[i] = (double)i * 1.1;
        snprintf(identifiers[i], sizeof(identifiers[i]), "ID%d", i);
        insert_node(&head, identifiers[i]);
        status_flags[i] = (i % 2 == 0) ? true : false;
    }

    // Free allocated memory
    free_list(&head);

    return 0;
}
