} RoundData;

RoundData* create_round(int num_records, int max_key) {
    RoundData* round = (RoundData*)malloc(sizeof(RoundData));
    if (!round) {
        return NULL; // Memory allocation failed
    }

    round->records = (Record*)calloc(num_records, sizeof(Record));
    if (!round->records) {
        free(round);
        return NULL; // Memory allocation failed
    }

    round->count = num_records;
    round->status = 0;

    for (int i = 0; i < num_records; ++i) {
        round->records[i].offset = i * 100L; // Example offset calculation
        if (max_key > 0 && i >= max_key) {
            round->status = -1; // Exceeded maximum key value
            break;
        }
        round->records[i].key = i % max_key; // Ensure unique and within range
        // Initialize other fields as needed, considering dependency on previous record
    }

    return round;
}

void free_round(RoundData* round) {
    if (round) {
        free(round->records);
        free(round);
    }
}

int main() {
    int num_rounds = 5;
    int max_key_per_round = 10;

    for (int i = 0; i < num_rounds; ++i) {
        RoundData* round = create_round(10, max_key_per_round);
        if (!round || round->status == -1) {
            printf("Failed to create round %d\n", i + 1);
            // Handle error or fallback mechanism
        } else {
            // Process the round data
            free_round(round); // Free allocated memory for this round
        }
    }

    return 0;
}
