#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MIN_KEY 1
#define MAX_KEY 1000
#define MIN_DATA_SIZE 16
#define MAX_DATA_SIZE 4096

typedef struct {
    int key;
    void* data;
} Record;

typedef struct MemoryPool {
    size_t blockSize;
    size_t poolSize;
    void* memory;
    size_t usedMemory;
} MemoryPool;

int initRecords(Record** records, int numRecords, int minKey, int maxKey, size_t dataSize, unsigned seed) {
    if (numRecords <= 0 || minKey < MIN_KEY || maxKey > MAX_KEY || dataSize < MIN_DATA_SIZE || dataSize > MAX_DATA_SIZE) {
        return -1; // Invalid input
    }

    *records = (Record*)malloc(numRecords * sizeof(Record));
    if (*records == NULL) {
        return -2; // Memory allocation failed
    }

    srand(seed);
    for (int i = 0; i < numRecords; ++i) {
        (*records)[i].key = rand() % (maxKey - minKey + 1) + minKey;
        (*records)[i].data = malloc(dataSize);
        if ((*records)[i].data == NULL) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) {
                free((*records)[j].data);
            }
            free(*records);
            return -2;
        }
    }

    return 0; // Success
}

void clearRecords(Record* records, int numRecords) {
    if (records != NULL) {
        for (int i = 0; i < numRecords; ++i) {
            free(records[i].data);
        }
        free(records);
    }
}

int main() {
    Record* records;
    int result = initRecords(&records, 100, MIN_KEY, MAX_KEY, 256, time(NULL));
    if (result == 0) {
        // Use the records
        clearRecords(records, 100);
    } else {
        printf("Error initializing records: %d\n", result);
    }
    return 0;
}
