Record** manageRecords(int n, long* offsets, int* keys, double (*weightFunc)(int, long)) {
    if (n <= 0) return NULL;

    Record** records = (Record**)malloc(n * sizeof(Record*));
    if (!records) return NULL;

    for (int i = 0; i < n; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            // Free previously allocated memory on error
            for (int j = 0; j < i; ++j) free(records[j]);
            free(records);
            return NULL;
        }

        records[i]->offset = offsets[i];
        records[i]->key = keys[i];
        records[i]->message = strdup("Constant Message");
        if (!records[i]->message) {
            // Free previously allocated memory on error
            for (int j = 0; j <= i; ++j) free(records[j]);
            free(records);
            return NULL;
        }

        records[i]->key = (int)(weightFunc(keys[i], offsets[i]));
    }

    return records;
}

double weightedAverage(int key, long offset) {
    // Example weight function: simple average
    return (double)(key + offset) / 2.0;
}

void freeRecords(Record** records, int n) {
    for (int i = 0; i < n; ++i) {
        free(records[i]->message);
        free(records[i]);
    }
    free(records);
}

int main() {
    long offsets[] = {100, 200, 300};
    int keys[] = {5, 10, 15};
    int n = sizeof(offsets) / sizeof(offsets[0]);

    Record** records = manageRecords(n, offsets, keys, weightedAverage);
    if (records) {
        // Use the records
        freeRecords(records, n);
    }

    return 0;
}
