#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define resourceNode structure
typedef struct resourceNode {
    char* id;
    int frequency;
    struct resourceNode* prev;
    struct resourceNode* next;
} resourceNode;

// Function to create a new resourceNode
resourceNode* createResourceNode(const char* id) {
    resourceNode* newNode = (resourceNode*)malloc(sizeof(resourceNode));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->id = strdup(id);
    newNode->frequency = 0;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a new resourceNode into the doubly linked list
void insertResourceNode(resourceNode** head, const char* id) {
    if (*head == NULL) {
        *head = createResourceNode(id);
    } else {
        resourceNode* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = createResourceNode(id);
        current->next->prev = current;
    }
}

// Function to update the frequency of a resourceNode
void updateFrequency(resourceNode** head, const char* id) {
    resourceNode* current = *head;
    while (current != NULL) {
        if (strcmp(current->id, id) == 0) {
            current->frequency++;
            return;
        }
        current = current->next;
    }
    insertResourceNode(head, id);
}

// Function to handle HTTP PUT request
void handlePUTRequest(resourceNode** head, const char* id) {
    updateFrequency(head, id);
}

// Function to handle HTTP DELETE request
void handleDELETERequest(resourceNode** head, const char* id) {
    resourceNode* current = *head;
    while (current != NULL) {
        if (strcmp(current->id, id) == 0) {
            free(current->id);
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                *head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            }
            free(current);
            insertResourceNode(head, "DELETED");
            return;
        }
        current = current->next;
    }
}

// Function to process resource data
void processResourceData() {
    resourceNode* head = NULL;
    char line[1024];
    clock_t start, end;

    // Read from standard input and update frequency
    while (fgets(line, sizeof(line), stdin) != NULL) {
        char id[1024];
        if (sscanf(line, "%s", id) == 1) {
            start = clock();
            handlePUTRequest(&head, id);
            end = clock();
            printf("Update time: %ld ms\n", (end - start) * 1000 / CLOCKS_PER_SEC);
        } else {
            fprintf(stderr, "Malformed line: %s", line);
        }
    }

    // Handle DELETE request
    handleDELETERequest(&head, "exampleId");

    // Free all allocated resources
    resourceNode* current = head;
    while (current != NULL) {
        resourceNode* next = current->next;
        free(current->id);
        free(current);
        current = next;
    }
}

int main() {
    processResourceData();
    return 0;
}
