#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    double value;
    struct node* next;
} Node;

Node* create_node(double value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, int position, double value) {
    Node* new_node = create_node(value);
    if (position == 0) {
        new_node->next = *head;
        *head = new_node;
        return;
    }
    Node* current = *head;
    for (int i = 0; current != NULL && i < position - 1; i++) {
        current = current->next;
    }
    if (current == NULL) {
        fprintf(stderr, "Invalid insertion position\n");
        free(new_node);
        return;
    }
    new_node->next = current->next;
    current->next = new_node;
}

void traverse_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%.2f -> ", current->value);
        current = current->next;
    }
    printf("NULL\n");
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    Node* head = NULL;

    insert_node(&head, 0, 3.14);
    insert_node(&head, 1, 2.71);
    insert_node(&head, 2, 1.61);

    traverse_list(head);

    free_list(&head);

    return 0;
}
