#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t mutex;
} DynamicArray;

void log_event(const char *filename, const char *message) {
    FILE *file = fopen(filename, "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

int is_rnti_unique(DynamicArray *array, int rnti) {
    for (size_t i = 0; i < array->used_size; ++i) {
        if (array->array[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

void resize_array(DynamicArray *array, size_t new_size) {
    pthread_mutex_lock(&array->mutex);
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) {
        log_event("allocation_failures.log", "Failed to resize array");
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    array->array = new_array;
    array->allocated_size = new_size;
    pthread_mutex_unlock(&array->mutex);
}

DynamicArray* create_dynamic_array(size_t initial_size) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (array == NULL) {
        log_event("allocation_failures.log", "Failed to allocate memory for array");
        return NULL;
    }
    array->array = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->array == NULL) {
        free(array);
        log_event("allocation_failures.log", "Failed to allocate initial memory for array elements");
        return NULL;
    }
    array->allocated_size = initial_size;
    array->used_size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->array);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_element_to_array(DynamicArray *array, int rx_tag, int rnti, int crc_flag) {
    if (array->used_size >= array->allocated_size - 1) {
        size_t new_size = array->allocated_size == 0 ? 1 : array->allocated_size * 2;
        resize_array(array, new_size);
    }
    pthread_mutex_lock(&array->mutex);
    if (!is_rnti_unique(array, rnti)) {
        log_event("rnti_duplicates.log", "Duplicate RNTI detected");
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    array->array[array->used_size].RX_UE_INFORMATION_TAG = rx_tag;
    array->array[array->used_size].RNTI = rnti;
    array->array[array->used_size].CRC_INDICATION_REL8_TAG = crc_flag;
    ++array->used_size;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// Example usage
int main() {
    srand(time(NULL));
    DynamicArray *array = create_dynamic_array(10);
    if (array == NULL) {
        return -1;
    }
    for (int i = 0; i < 20; ++i) {
        int rx_tag = rand();
        int rnti = rand() % MAX_RNTI;
        int crc_flag = rand() % 2;
        if (add_element_to_array(array, rx_tag, rnti, crc_flag) != 0) {
            printf("Failed to add element\n");
        }
    }
    destroy_dynamic_array(array);
    return 0;
}
