#include <stdlib.h>
#include <stdio.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_EXTRA_DATA_SIZE 1024

typedef struct {
    int rnti;
    struct TransportChannelConfig {
        int logicalChannelIdentity;
    } config;
} MAC_TransportChannelInfo;

int allocateMACTransportChannelInfo(int n, MAC_TransportChannelInfo **info, char mode) {
    if (n > MAX_MEMORY / sizeof(MAC_TransportChannelInfo)) {
        return -1; // Exceeds maximum memory limit
    }

    *info = malloc(n * sizeof(MAC_TransportChannelInfo));
    if (!*info) {
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < n; ++i) {
        (*info)[i].rnti = i + 1;
        (*info)[i].config.logicalChannelIdentity = i * 10;

        if (mode == 'c') {
            // Compressed mode: Share common extra data
            static int sharedExtraData = 0;
            (*info)[i].extraData = &sharedExtraData;
        } else if (mode == 'u') {
            // Uncompressed mode: Allocate unique extra data
            void *extraData = malloc(MAX_EXTRA_DATA_SIZE);
            if (!extraData) {
                free(*info);
                return -3; // Memory allocation failed for extra data
            }
            (*info)[i].extraData = extraData;
        } else {
            free(*info);
            return -4; // Invalid mode
        }
    }

    return 0; // Success
}

void freeMACTransportChannelInfo(int n, MAC_TransportChannelInfo *info) {
    for (int i = 0; i < n; ++i) {
        if (mode == 'u') {
            free(info[i].extraData);
        }
    }
    free(info);
}

// Example usage
int main() {
    int n = 10;
    MAC_TransportChannelInfo *info;
    char mode = 'c'; // 'c' for compressed, 'u' for uncompressed

    int result = allocateMACTransportChannelInfo(n, &info, mode);
    if (result != 0) {
        printf("Error allocating memory: %d\n", result);
        return 1;
    }

    // Use the allocated structures...

    freeMACTransportChannelInfo(n, info);

    return 0;
}
```

