#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY 1024 * 1024 // 1MB

typedef struct node {
    int value;
    long offset;
    struct node* next;
} Record;

Record* records = NULL;
size_t current_memory_usage = 0;
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void log_memory_usage() {
    printf("Current Memory Usage: %zu bytes\n", current_memory_usage);
}

int allocate_record(int value, long offset) {
    pthread_mutex_lock(&memory_lock);
    if (current_memory_usage + sizeof(Record) > MAX_MEMORY) {
        pthread_mutex_unlock(&memory_lock);
        return -1; // Memory limit exceeded
    }
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&memory_lock);
        return -2; // Allocation failed
    }
    new_record->value = value;
    new_record->offset = offset;
    new_record->next = records;
    records = new_record;
    current_memory_usage += sizeof(Record);
    if (current_memory_usage > MAX_MEMORY) {
        log_memory_usage();
    }
    pthread_mutex_unlock(&memory_lock);
    return 0; // Success
}

int update_record(int identifier, int value, long offset) {
    pthread_mutex_lock(&memory_lock);
    Record* current = records;
    while (current != NULL) {
        if (current->offset == identifier) {
            current->value = value;
            current->offset = offset;
            pthread_mutex_unlock(&memory_lock);
            return 0; // Success
        }
        current = current->next;
    }
    pthread_mutex_unlock(&memory_lock);
    return -1; // Identifier not found
}

int delete_record(int identifier) {
    pthread_mutex_lock(&memory_lock);
    Record* current = records;
    Record* previous = NULL;
    while (current != NULL) {
        if (current->offset == identifier) {
            if (previous == NULL) {
                records = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            current_memory_usage -= sizeof(Record);
            log_memory_usage();
            pthread_mutex_unlock(&memory_lock);
            return 0; // Success
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&memory_lock);
    return -1; // Identifier not found
}

void cleanup_records() {
    pthread_mutex_lock(&memory_lock);
    Record* current = records;
    while (current != NULL) {
        Record* next = current->next;
        free(current);
        current_memory_usage -= sizeof(Record);
        current = next;
    }
    records = NULL;
    pthread_mutex_unlock(&memory_lock);
}
