#define MAX_RECORDS 1000000
#define MAX_SIZE 1024 * 1024 * 1024 // 1GB

typedef struct {
    long TransactionID;
    time_t Timestamp;
    unsigned char* DataChunk;
    size_t DataSize;
} TransactionRecord;

TransactionRecord* readTransactions(const char* filename, size_t data_size, size_t max_size, FILE** log_file) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    TransactionRecord* records = (TransactionRecord*)malloc(MAX_RECORDS * sizeof(TransactionRecord));
    if (!records) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    size_t total_size = 0;
    size_t record_count = 0;

    while (record_count < MAX_RECORDS && total_size + data_size <= max_size) {
        records[record_count].TransactionID = rand();
        records[record_count].Timestamp = time(NULL);
        records[record_count].DataChunk = (unsigned char*)malloc(data_size);
        if (!records[record_count].DataChunk) {
            fprintf(*log_file, "Memory allocation failed for record %zu\n", record_count);
            free(records);
            fclose(file);
            return NULL;
        }

        size_t bytes_read = fread(records[record_count].DataChunk, 1, data_size, file);
        if (bytes_read != data_size) {
            fprintf(*log_file, "Failed to read data for record %zu\n", record_count);
            free(records[record_count].DataChunk);
            free(records);
            fclose(file);
            return NULL;
        }

        records[record_count].DataSize = bytes_read;
        total_size += sizeof(TransactionRecord) + bytes_read;
        record_count++;
    }

    fclose(file);
    return records;
}

int sumEvenIntegers(TransactionRecord* records, size_t count) {
    int sum = 0;
    for (size_t i = 0; i < count; i++) {
        if (records[i].DataSize % 4 == 0) { // Assuming DataChunk contains integers
            int* data = (int*)records[i].DataChunk;
            for (size_t j = 0; j < records[i].DataSize / 4; j++) {
                if (data[j] % 2 == 0) {
                    sum += data[j];
                }
            }
        }
    }
    return sum;
}

void freeRecords(TransactionRecord* records, size_t count) {
    for (size_t i = 0; i < count; i++) {
        free(records[i].DataChunk);
    }
    free(records);
}
