#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define INITIAL_CAPACITY 10
#define MAX_LINE_LENGTH 256

void trimWhitespace(char *str) {
    char *end;

    // Trim leading spaces
    while(isspace((unsigned char)*str)) str++;

    if(*str == 0) return; // All spaces?

    // Trim trailing whitespace
    end = str + strlen(str) - 1;
    while(end > str && isspace((unsigned char)*end)) end--;

    // Write new null terminator character
    end[1] = '\0';
}

char** processAndFindLongestWord() {
    char **lines = NULL;
    int capacity = INITIAL_CAPACITY;
    int count = 0;

    lines = (char **)malloc(capacity * sizeof(char *));
    if (!lines) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    while (1) {
        char line[MAX_LINE_LENGTH];
        if (fgets(line, MAX_LINE_LENGTH, stdin) == NULL) break;

        trimWhitespace(line);

        if (strlen(line) > 0) {
            lines[count] = strdup(line);
            if (!lines[count]) {
                fprintf(stderr, "Memory allocation failed\n");
                for (int i = 0; i < count; i++) free(lines[i]);
                free(lines);
                return NULL;
            }
            count++;

            // Resize array if needed
            if (count >= capacity) {
                capacity *= 2;
                lines = realloc(lines, capacity * sizeof(char *));
                if (!lines) {
                    fprintf(stderr, "Memory reallocation failed\n");
                    for (int i = 0; i < count; i++) free(lines[i]);
                    return NULL;
                }
            }
        }
    }

    // Find and print the longest word
    char *longestWord = NULL;
    size_t maxLength = 0;
    for (int i = 0; i < count; i++) {
        char *word = strtok(lines[i], " \t\n");
        while (word != NULL) {
            if (strlen(word) > maxLength) {
                maxLength = strlen(word);
                longestWord = strdup(word);
            }
            word = strtok(NULL, " \t\n");
        }
    }

    printf("Longest word: %s\n", longestWord ? longestWord : "");

    // Free allocated memory
    for (int i = 0; i < count; i++) free(lines[i]);
    free(lines);

    return NULL;
}

int main() {
    processAndFindLongestWord();
    return 0;
}
