typedef struct {
    long offset;
    int key;
    int value;
} record;

int allocate_records(record **records, size_t size) {
    *records = (record *)malloc(size * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    for (size_t i = 0; i < size; ++i) {
        (*records)[i].offset = i;
        (*records)[i].key = 0;
        (*records)[i].value = 0;
    }
    return 0;
}

int set_random_values(record *records, size_t size, int min_value, int max_value) {
    if (size > (size_t)(max_value - min_value + 1)) {
        fprintf(stderr, "Too many records for the given value range\n");
        return -1;
    }
    srand(time(NULL));
    int values[size];
    for (size_t i = 0; i < size; ++i) {
        do {
            values[i] = rand() % (max_value - min_value + 1) + min_value;
        } while (i > 0 && values[i] == values[i - 1]);
        records[i].value = values[i];
    }
    return 0;
}

void log_operation(const char *operation, time_t timestamp) {
    printf("%s at %ld\n", operation, timestamp);
}

int initialize_records(record **records, size_t size, int min_value, int max_value) {
    if (allocate_records(records, size) != 0) {
        return -1;
    }
    log_operation("Allocated records", time(NULL));
    if (set_random_values(*records, size, min_value, max_value) != 0) {
        free(*records);
        *records = NULL;
        return -1;
    }
    log_operation("Set random values", time(NULL));
    return 0;
}

void free_records(record **records) {
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}
