typedef struct {
    int value;
    long* offset;
    int* key;
} record;

record* create_records(int num_records, int array_size) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    long* offsets = (long*)calloc(array_size, sizeof(long));
    if (!offsets) {
        free(records);
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    int* keys = (int*)calloc(array_size, sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % array_size;
        records[i].offset = &offsets[records[i].value];
        records[i].key = &keys[records[i].value];
    }

    return records;
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = NULL;
        records[i].key = NULL;
    }
    free(records);
}
