#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

typedef struct List {
    Node *head;
    Node *tail;
    pthread_mutex_t mutex;
} List;

List* list_create() {
    List *list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void list_destroy(List *list) {
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int list_append(List *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->mutex);
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Out of memory
    }
    new_node->data = data;
    new_node->next = NULL;

    if (!list->head) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int list_delete(List *list, uint16_t RNTI) {
    pthread_mutex_lock(&list->mutex);
    Node *current = list->head;
    Node *prev = NULL;

    while (current) {
        if (current->data->RNTI == RNTI) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (!current->next) {
                list->tail = prev;
            }
            free(current->data);
            free(current);
            pthread_mutex_unlock(&list->mutex);
            return 0; // Successfully deleted
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return -1; // RNTI not found
}

void list_traverse(List *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->mutex);
    Node *current = list->head;
    while (current) {
        callback(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}
