#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_EXTRA_DATA_SIZE 1024
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int value;
    long offset;
    int key;
    void* extra_data;
    char* metadata;
} Record;

typedef struct {
    size_t total_size;
    size_t used_size;
    char* memory_pool;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->memory_pool = (char*)malloc(initial_size);
    if (!pool->memory_pool) {
        free(pool);
        return NULL;
    }
    pool->total_size = initial_size;
    pool->used_size = 0;
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->memory_pool);
    free(pool);
}

int allocate_record(MemoryPool* pool, Record** record, size_t extra_data_size, const char* metadata) {
    if (pool->used_size + sizeof(Record) + extra_data_size + strlen(metadata) > pool->total_size) {
        return -1; // Not enough memory
    }

    *record = (Record*)(pool->memory_pool + pool->used_size);
    pool->used_size += sizeof(Record);

    (*record)->value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    (*record)->offset = pool->used_size;
    (*record)->key = rand();
    (*record)->extra_data = malloc(extra_data_size);
    if (!(*record)->extra_data) return -2; // Failed to allocate extra data
    memcpy((*record)->extra_data, metadata, strlen(metadata));
    (*record)->metadata = strdup(metadata);

    pool->used_size += extra_data_size + strlen(metadata) + 1;

    return 0;
}

void free_record(MemoryPool* pool, Record* record) {
    if (record->extra_data) {
        free(record->extra_data);
        record->extra_data = NULL;
    }
    if (record->metadata) {
        free(record->metadata);
        record->metadata = NULL;
    }
}
