#define MAX_SESSIONS 10000

typedef struct {
    char uuid[37]; // UUID string format
    char username[256];
    time_t expiry_time;
    int activity_level;
    char ip_address[16];
    int port;
} UserSession;

UserSession sessions[MAX_SESSIONS];
int session_count = 0;
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

void generate_uuid(char *uuid) {
    // Simulated UUID generation
    snprintf(uuid, sizeof(uuid), "%08x-%04x-4%03x-a%01x%03x-%012x",
             rand(), rand() & 0xFFFF, rand() & 0x0FFF,
             (rand() & 0x0F) | 0x40, rand() & 0x3FF,
             rand());
}

void generate_username(char *username) {
    // Simulated username generation
    snprintf(username, sizeof(username), "user%d", rand() % 1000);
}

int validate_ip_address(const char *ip) {
    // Simple IP validation (not comprehensive)
    return strlen(ip) <= 15;
}

int validate_port(int port) {
    // Port range validation
    return port >= 1 && port <= 65535;
}

void initialize_session(UserSession *session, const char *uuid, const char *username,
                        time_t expiry_time, int activity_level, const char *ip, int port) {
    strncpy(session->uuid, uuid, sizeof(session->uuid));
    strncpy(session->username, username, sizeof(session->username));
    session->expiry_time = expiry_time;
    session->activity_level = activity_level;
    strncpy(session->ip_address, ip, sizeof(session->ip_address));
    session->port = port;
}

int add_session(const char *external_uuid, const char *external_username,
                time_t expiry_time, int activity_level, const char *ip, int port) {
    pthread_mutex_lock(&session_lock);
    if (session_count >= MAX_SESSIONS) {
        printf("Session limit reached\n");
        pthread_mutex_unlock(&session_lock);
        return -1;
    }

    UserSession new_session;
    generate_uuid(new_session.uuid);
    while (strcmp(external_uuid, new_session.uuid) == 0) {
        generate_uuid(new_session.uuid); // Ensure unique UUID
    }
    strncpy(new_session.username, external_username, sizeof(new_session.username));
    new_session.expiry_time = expiry_time;
    new_session.activity_level = activity_level;

    if (!validate_ip_address(ip) || !validate_port(port)) {
        printf("Invalid IP address or port\n");
        pthread_mutex_unlock(&session_lock);
        return -1;
    }
    strncpy(new_session.ip_address, ip, sizeof(new_session.ip_address));
    new_session.port = port;

    initialize_session(&sessions[session_count], new_session.uuid, new_session.username,
                        new_session.expiry_time, new_session.activity_level,
                        new_session.ip_address, new_session.port);
    session_count++;
    pthread_mutex_unlock(&session_lock);
    return 0;
}

int main() {
    // Example usage
    time_t current_time = time(NULL);
    add_session("123e4567-e89b-12d3-a456-426614174000", "john_doe",
                current_time + 3600, 5, "192.168.1.1", 8080);
    return 0;
}
```

This code provides a basic structure for managing user sessions with concurrency handling using pthreads. It includes functions to generate UUIDs and usernames, validate IP addresses and ports, and add sessions to the list. The main function demonstrates how to use these functions.']

