typedef struct Sensor {
    float reading;
    char type;
    struct Sensor* next;
    int status;
    void* config_data;
} Sensor;

typedef struct NetworkEntity {
    unsigned int RNTI;
    unsigned long SUPI;
    unsigned short PCI;
    unsigned char Band;
    Sensor* sensors;
    int sensor_count;
} NetworkEntity;

NetworkEntity* create_network_entity(unsigned int RNTI, unsigned long SUPI, unsigned short PCI, unsigned char Band) {
    NetworkEntity* entity = (NetworkEntity*)malloc(sizeof(NetworkEntity));
    if (!entity) return NULL;

    entity->RNTI = RNTI;
    entity->SUPI = SUPI;
    entity->PCI = PCI;
    entity->Band = Band;
    entity->sensors = NULL;
    entity->sensor_count = 0;

    return entity;
}

Sensor* create_sensor(char type, void* config_data) {
    Sensor* sensor = (Sensor*)malloc(sizeof(Sensor));
    if (!sensor) return NULL;

    sensor->reading = 0.0f;
    sensor->type = type;
    sensor->next = NULL;
    sensor->status = 1; // Assuming all sensors are active initially
    sensor->config_data = config_data;

    return sensor;
}

void add_sensor_to_entity(NetworkEntity* entity, Sensor* sensor) {
    if (entity->sensor_count >= MAX_MEMORY / sizeof(Sensor)) {
        printf("Memory limit reached for sensors.\n");
        free(sensor);
        return;
    }

    sensor->next = entity->sensors;
    entity->sensors = sensor;
    entity->sensor_count++;
}

void initialize_network_entities(int num_entities, NetworkEntity** entities) {
    unsigned int RNTI = 1000;
    unsigned long SUPI = 2000000000;

    for (int i = 0; i < num_entities; i++) {
        entities[i] = create_network_entity(RNTI + i, SUPI + i * 1000000, i % 1024, i % 64);
        if (!entities[i]) {
            printf("Failed to allocate memory for entity %d.\n", i);
            return;
        }

        // Add sensors to each entity
        for (int j = 0; j < 5; j++) { // Assuming each entity has up to 5 sensors
            Sensor* sensor = create_sensor('A' + j, NULL); // Lazy allocation of config_data
            if (!sensor) {
                printf("Failed to allocate memory for sensor %d in entity %d.\n", j, i);
                return;
            }
            add_sensor_to_entity(entities[i], sensor);
        }
    }
}

void update_sensor_readings(NetworkEntity* entities, int num_entities) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_entities; i++) {
        Sensor* sensor = entities[i]->sensors;
        while (sensor) {
            pthread_mutex_lock(&mutex);
            // Update sensor reading based on type
            if (sensor->type == 'A') {
                sensor->reading = rand() % 100 / 10.0f; // Example update logic
            } else if (sensor->type == 'B') {
                sensor->reading = rand() % 50 / 10.0f;
            }
            pthread_mutex_unlock(&mutex);
            sensor = sensor->next;
        }
    }
}

void free_network_entities(NetworkEntity** entities, int num_entities) {
    for (int i = 0; i < num_entities; i++) {
        Sensor* sensor = entities[i]->sensors;
        while (sensor) {
            Sensor* next_sensor = sensor->next;
            free(sensor);
            sensor = next_sensor;
        }
        free(entities[i]);
    }
    free(entities);
}

int main() {
    int num_entities = 10;
    NetworkEntity** entities = (NetworkEntity**)malloc(num_entities * sizeof(NetworkEntity*));

    initialize_network_entities(num_entities, entities);

    // Simulate real-time updates
    for (int i = 0; i < 5; i++) {
        update_sensor_readings(entities, num_entities);
        sleep(1); // Simulating time passing
    }

    free_network_entities(entities, num_entities);

    return 0;
}
