#define MAX_DATA_SIZE 1024 * 1024 // 1MB

typedef struct {
    int value;
    char* str;
} record;

int initialize_pipeline(long** offsets, int** keys, record** records, char** buffer, size_t* total_size) {
    srand(time(NULL));

    *offsets = (long*)malloc(MAX_DATA_SIZE);
    *keys = (int*)malloc(MAX_DATA_SIZE);
    *records = (record*)malloc(MAX_DATA_SIZE * sizeof(record));
    *buffer = (char*)malloc(MAX_DATA_SIZE);

    if (!*offsets || !*keys || !*records || !*buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    size_t current_size = 0;

    for (size_t i = 0; i < MAX_DATA_SIZE / sizeof(long); ++i) {
        (*offsets)[i] = i;
        (*keys)[i] = -1000 + i;

        int random_value;
        do {
            random_value = rand() % 10000;
        } while (i > 0 && (*records)[i-1].value == random_value);

        (*records)[i].value = random_value;
        (*records)[i].str = (char*)malloc(17);
        if (!(*records)[i].str) {
            fprintf(stderr, "Memory allocation failed for record string\n");
            return -1;
        }
        snprintf((*records)[i].str, 17, "%d", random_value);

        current_size += sizeof(long) + sizeof(int) + 16;

        if (current_size > MAX_DATA_SIZE) {
            fprintf(stderr, "Exceeded maximum data size\n");
            return -1;
        }
    }

    *total_size = current_size;
    return 0;
}

void free_pipeline(long* offsets, int* keys, record* records, char* buffer) {
    for (size_t i = 0; i < MAX_DATA_SIZE / sizeof(record); ++i) {
        free(records[i].str);
    }
    free(offsets);
    free(keys);
    free(records);
    free(buffer);
}

int main() {
    long* offsets;
    int* keys;
    record* records;
    char* buffer;
    size_t total_size;

    if (initialize_pipeline(&offsets, &keys, &records, &buffer, &total_size) == 0) {
        printf("Pipeline initialized successfully with total size: %zu\n", total_size);
        free_pipeline(offsets, keys, records, buffer);
    }

    return 0;
}
