        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i].key = rand() % max_key + 1;
        records[i].measurement = min_measurement + (double)rand() / RAND_MAX * (max_measurement - min_measurement);

        records[i].offsets = (long*)malloc(num_offsets * sizeof(long));
        if (!records[i].offsets) {
            fprintf(stderr, "Memory allocation failed for offsets.\n");
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(records[j].offsets);
            }
            free(records);
            return NULL;
        }

        for (int j = 0; j < num_offsets; ++j) {
            records[i].offsets[j] = rand() % 1000L; // Example range
        }
    }

    return records;
}

void print_records(record* records, int num_records) {
    if (!records || num_records <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    double total_measurement = 0.0;

    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: Key=%d, Measurement=%.2f\n", i, records[i].key, records[i].measurement);
        total_measurement += records[i].measurement;
        free(records[i].offsets); // Free offsets to avoid memory leaks
    }

    printf("Total number of records: %d\n", num_records);
    printf("Average measurement value: %.2f\n", total_measurement / num_records);

    free(records); // Free main record array
}

int main() {
    int num_records = 5;
    int max_key = 100;
    double min_measurement = 0.0, max_measurement = 100.0;
    int num_offsets = 3;

    record* records = create_records(num_records, max_key, min_measurement, max_measurement, num_offsets);
    if (records) {
        print_records(records, num_records);
    }

    return 0;
}
