#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_IP_LENGTH 16
#define MAX_PROTOCOL_LENGTH 32

typedef struct {
    char ipAddress[MAX_IP_LENGTH];
    time_t timestamp;
    size_t trafficVolume;
    char protocolType[MAX_PROTOCOL_LENGTH];
} NetworkTrafficEvent;

typedef struct {
    NetworkTrafficEvent *events;
    size_t count;
    size_t capacity;
    size_t maxMemorySize;
    FILE *allocationFailureLog;
    FILE *duplicateEntryLog;
    pthread_mutex_t lock;
    size_t successfulAllocations;
    size_t failedAllocations;
    size_t uniqueIPCount;
} TrafficManager;

TrafficManager* createTrafficManager(size_t initialCapacity, size_t maxMemorySize) {
    TrafficManager *manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    if (!manager) return NULL;

    manager->events = (NetworkTrafficEvent*)calloc(initialCapacity, sizeof(NetworkTrafficEvent));
    if (!manager->events) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initialCapacity;
    manager->maxMemorySize = maxMemorySize;
    manager->allocationFailureLog = fopen("allocation_failures.log", "w");
    manager->duplicateEntryLog = fopen("duplicate_entries.log", "w");
    pthread_mutex_init(&manager->lock, NULL);
    manager->successfulAllocations = 0;
    manager->failedAllocations = 0;
    manager->uniqueIPCount = 0;

    return manager;
}

void destroyTrafficManager(TrafficManager *manager) {
    if (manager->events) free(manager->events);
    if (manager->allocationFailureLog) fclose(manager->allocationFailureLog);
    if (manager->duplicateEntryLog) fclose(manager->duplicateEntryLog);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int addTrafficEvent(TrafficManager *manager, NetworkTrafficEvent event) {
    pthread_mutex_lock(&manager->lock);

    // Check for duplicate IP
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->events[i].ipAddress, event.ipAddress) == 0) {
            fprintf(manager->duplicateEntryLog, "Duplicate entry: %s\n", event.ipAddress);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    // Check memory usage
    size_t newMemoryUsage = manager->count * sizeof(NetworkTrafficEvent) + sizeof(NetworkTrafficEvent);
    if (newMemoryUsage > manager->maxMemorySize) {
        fprintf(manager->allocationFailureLog, "Memory allocation failure: %zu bytes requested\n", newMemoryUsage);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    // Add event
    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        NetworkTrafficEvent *newEvents = (NetworkTrafficEvent*)realloc(manager->events, newCapacity * sizeof(NetworkTrafficEvent));
        if (!newEvents) {
            fprintf(manager->allocationFailureLog, "Memory reallocation failure: %zu bytes requested\n", newCapacity * sizeof(NetworkTrafficEvent));
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->events = newEvents;
        manager->capacity = newCapacity;
    }

    manager->events[manager->count++] = event;
    manager->uniqueIPCount++;
    manager->successfulAllocations++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Additional functions for batch processing, memory pool management, and thread safety can be implemented here.
