import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class StringHasher {

    private static final int MAX_DATA_SIZE = 1024 * 1024; // 1MB
    private static final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private static final Map<String, String> cache = new HashMap<>();

    public static Map<String, String> hashStrings(List<String> strings) {
        if (strings.stream().mapToInt(String::length).sum() > MAX_DATA_SIZE) {
            System.err.println("Input data exceeds maximum size limit.");
            return Collections.emptyMap();
        }

        Map<String, CompletableFuture<String>> futures = new HashMap<>();
        for (String str : strings) {
            futures.put(str, CompletableFuture.supplyAsync(() -> hashString(str), executorService));
        }

        Map<String, String> result = new HashMap<>();
        for (Map.Entry<String, CompletableFuture<String>> entry : futures.entrySet()) {
            try {
                result.put(entry.getKey(), entry.getValue().get());
            } catch (Exception e) {
                System.err.println("Error hashing string: " + entry.getKey() + ". Error: " + e.getMessage());
            }
        }

        return result;
    }

    private static String hashString(String str) {
        if (cache.containsKey(str)) {
            return cache.get(str);
        }

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(str.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            cache.put(str, hexString.toString());
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    public static void main(String[] args) {
        List<String> strings = Arrays.asList("example string 1", "example string 2");
        Map<String, String> hashes = hashStrings(strings);
        System.out.println(hashes);
    }
}
