#define MAX_RECORDS 1000000

typedef struct {
    long offset;
    int key;
    int value;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_records(int size, int min_value, int max_value) {
    pthread_mutex_lock(&mutex);
    if (record_count + size > MAX_RECORDS) {
        printf("Memory allocation failed. Fallback strategy in place.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    for (int i = 0; i < size; i++) {
        records[record_count + i].offset = record_count + i;
        records[record_count + i].key = rand() % max_value + min_value;
        records[record_count + i].value = rand() % max_value + min_value;
    }
    record_count += size;
    printf("Records initialized. Total records: %d\n", record_count);
    pthread_mutex_unlock(&mutex);
}

void update_record(int index, int new_value) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < record_count) {
        records[index].value = new_value;
        printf("Record updated at index %d. New value: %d\n", index, new_value);
    } else {
        printf("Invalid index for update.\n");
    }
    pthread_mutex_unlock(&mutex);
}

void* transaction_thread(void* arg) {
    int thread_id = *(int*)arg;
    srand(time(NULL) + thread_id); // Seed for random number generation
    for (int i = 0; i < 1000; i++) {
        int index = rand() % record_count;
        update_record(index, rand() % 100);
    }
    pthread_exit(NULL);
}

void run_transactions(int num_threads) {
    pthread_t threads[num_threads];
    int thread_ids[num_threads];

    for (int i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, transaction_thread, &thread_ids[i]);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    srand(time(NULL));
    initialize_records(100000, 0, 1000);

    int num_threads = 4;
    run_transactions(num_threads);

    return 0;
}
