        records[i].offset = (long)i * sizeof(Record);
        records[i].key = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;

