        char fieldName[20];
        char fieldValue[50];
        sprintf(fieldName, "Field%d", i);
        sprintf(fieldValue, "Value%d", i);

        records[i].fieldName = strdup(fieldName);
        records[i].fieldValue = strdup(fieldValue);
    }

    // Log successful initialization
    printf("Data structure initialized with %d records\n", size);

    return records;
