#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char ipAddress[16];
    int interfaceState;
    int bandwidthLimit;
} NetworkInterfaceConfig;

typedef struct Node {
    NetworkInterfaceConfig config;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NetworkList;

void initNetworkList(NetworkList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addNetworkInterface(NetworkList* list, const char* ipAddress, int interfaceState, int bandwidthLimit) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure
        return;
    }
    strcpy(newNode->config.ipAddress, ipAddress);
    newNode->config.interfaceState = interfaceState;
    newNode->config.bandwidthLimit = bandwidthLimit;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

void removeNetworkInterface(NetworkList* list, const char* ipAddress) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (strcmp(current->config.ipAddress, ipAddress) == 0) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void updateNetworkInterface(NetworkList* list, const char* ipAddress, int interfaceState, int bandwidthLimit) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current != NULL) {
        if (strcmp(current->config.ipAddress, ipAddress) == 0) {
            strcpy(current->config.ipAddress, ipAddress);
            current->config.interfaceState = interfaceState;
            current->config.bandwidthLimit = bandwidthLimit;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void freeNetworkList(NetworkList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
