record* create_records(int num_records) {
    srand(time(NULL));
    record* records = (record*)malloc(num_records * sizeof(record));
    if (records == NULL) {
        return NULL;
    }
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 1001;
    }
    return records;
}

void* allocate_memory(int num_offsets, int num_keys, record** records) {
    *records = create_records(num_records);
    if (*records == NULL) {
        return NULL;
    }

    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    if (offsets == NULL) {
        free(*records);
        return NULL;
    }

    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        free(*records);
        return NULL;
    }

    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % num_offsets;
        int key = offsets[i] % num_keys;
        while (key >= num_keys || (*records)[key].value != -1) {
            if (num_keys * sizeof(int) + num_records * sizeof(record) > 0.5 * num_offsets * sizeof(long)) {
                free(offsets);
                free(keys);
                free(*records);
                return NULL;
            }
            key = rand() % num_keys;
        }
        keys[key] = offsets[i];
    }

    return offsets;
}

void free_memory(void* offsets, int num_keys, record* records) {
    free((long*)offsets);
    free(keys);
    free(records);
}
