#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define VALUE_RANGE 1000

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int size;
    pthread_mutex_t lock;
    int* key_frequency;
    double* key_average_value;
} TransactionalDataStructure;

void initialize_data_structure(TransactionalDataStructure* tds, int size) {
    tds->size = size;
    tds->key_frequency = (int*)calloc(size, sizeof(int));
    tds->key_average_value = (double*)calloc(size, sizeof(double));
    pthread_mutex_init(&tds->lock, NULL);
}

void initialize_records(TransactionalDataStructure* tds) {
    srand(time(NULL));
    for (int i = 0; i < tds->size; i++) {
        tds->records[i].offset = i;
        tds->records[i].key = rand() % tds->size;
        tds->records[i].value = rand() % VALUE_RANGE;
        pthread_mutex_lock(&tds->lock);
        tds->key_frequency[tds->records[i].key]++;
        tds->key_average_value[tds->records[i].key] += tds->records[i].value;
        pthread_mutex_unlock(&tds->lock);
    }
}

void update_record(TransactionalDataStructure* tds, int index, int new_value) {
    pthread_mutex_lock(&tds->lock);
    tds->records[index].value = new_value;
    tds->key_average_value[tds->records[index].key] -= tds->records[index].value;
    tds->records[index].value = new_value;
    tds->key_average_value[tds->records[index].key] += tds->records[index].value;
    pthread_mutex_unlock(&tds->lock);
}

void print_summary_report(TransactionalDataStructure* tds) {
    for (int i = 0; i < tds->size; i++) {
        if (tds->key_frequency[i] > 0) {
