#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Node {
    int key;
    int data;
    struct Node* next;
} Node;

Node* createNode(int key, int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->key = key;
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertNode(Node** head, int key, int data) {
    Node* newNode = createNode(key, data);
    if (*head == NULL || (*head)->key > key) {
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next != NULL && current->next->key < key) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

void traverseNodes(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("Key: %d, Data: %d\n", current->key, current->data);
        current = current->next;
    }
}

void freeNodes(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    srand(time(NULL));
    Node* head = NULL;

    // Insert nodes with unique keys and random data
    for (int i = 0; i < 10; i++) {
        int key = rand() % 100;
        int data = rand() % 100;
        insertNode(&head, key, data);
    }

    // Traverse the nodes
    traverseNodes(head);

    // Free the allocated memory
    freeNodes(&head);

    return 0;
}
