    if (num_records <= 0 || key_range_start >= key_range_end || measurement_range_start >= measurement_range_end) {
        return NULL; // Invalid input
    }

    Record** records = (Record**)malloc(num_records * sizeof(Record*));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < num_records; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; ++j) {
                free(records[j]->identifier);
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->key = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        records[i]->measurement = ((float)rand() / RAND_MAX) * (measurement_range_end - measurement_range_start) + measurement_range_start;

        // Generate a unique identifier
        char* id = (char*)malloc(10 * sizeof(char));
        if (!id) {
            free(records[i]);
            for (int j = 0; j < i; ++j) {
                free(records[j]->identifier);
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        sprintf(id, "%d_%d", records[i]->key, rand() % 1000); // Simple unique identifier
        records[i]->identifier = id;
    }

    return records;
}

void free_records(Record** records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i]->identifier);
        free(records[i]);
    }
    free(records);
