#define MAX_RNTI 65535

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    FILE *log_file;
    FILE *duplicate_log_file;
} RNTI_STORAGE_T;

RNTI_STORAGE_T rnti_storage = { .mutex = PTHREAD_MUTEX_INITIALIZER };

int is_rnti_unique(uint16_t rnti) {
    pthread_mutex_lock(&rnti_storage.mutex);
    for (size_t i = 0; i < rnti_storage.size; ++i) {
        if (rnti_storage.array[i].rnti == rnti) {
            pthread_mutex_unlock(&rnti_storage.mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&rnti_storage.mutex);
    return 1;
}

void log_rnti_duplicate(uint16_t rnti) {
    fprintf(rnti_storage.duplicate_log_file, "Duplicate RNTI: %u\n", rnti);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_pdu(size_t n, size_t max_size) {
    if (n * sizeof(NFAPI_CRC_INDICATION_PDU_T) > max_size) {
        fprintf(rnti_storage.log_file, "Memory allocation failed: requested %zu bytes, limit is %zu bytes\n", n * sizeof(NFAPI_CRC_INDICATION_PDU_T), max_size);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(rnti_storage.array, (rnti_storage.size + n) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fprintf(rnti_storage.log_file, "Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }

    rnti_storage.array = new_array;
    rnti_storage.capacity += n;

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &rnti_storage.array[rnti_storage.size + i];
        pdu->ue_info = generate_rx_ue_information_tag(); // Assume this function is defined elsewhere
        do {
            pdu->rnti = (uint16_t)rand() % MAX_RNTI;
        } while (!is_rnti_unique(pdu->rnti));
        log_rnti_duplicate(pdu->rnti);
        pdu->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG
    }

    rnti_storage.size += n;

    return &rnti_storage.array[rnti_storage.size - n];
}

void free_nfaapi_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, size_t n) {
    pthread_mutex_lock(&rnti_storage.mutex);
    for (size_t i = 0; i < n; ++i) {
        uint16_t rnti_to_remove = pdu[i].rnti;
        for (size_t j = 0; j < rnti_storage.size; ++j) {
            if (rnti_storage.array[j].rnti == rnti_to_remove) {
                memmove(&rnti_storage.array[j], &rnti_storage.array[j + 1], (rnti_storage.size - j - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                --rnti_storage.size;
                break;
            }
        }
    }
    pthread_mutex_unlock(&rnti_storage.mutex);
}

void init_rnti_storage(size_t initial_capacity, size_t max_size) {
    rnti_storage.array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!rnti_storage.array) {
        fprintf(stderr, "Failed to allocate initial memory: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    rnti_storage.capacity = initial_capacity;
    rnti_storage.size = 0;
    rnti_storage.max_size = max_size;
    rnti_storage.log_file = fopen("allocation_log.txt", "w");
    if (!rnti_storage.log_file) {
        fprintf(stderr, "Failed to open allocation log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    rnti_storage.duplicate_log_file = fopen("duplicate_rnti_log.txt", "w");
    if (!rnti_storage.duplicate_log_file) {
        fprintf(stderr, "Failed to open duplicate RNTI log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_rnti_storage() {
    free(rnti_storage.array);
    fclose(rnti_storage.log_file);
    fclose(rnti_storage.duplicate_log_file);
}
