// Function to initialize records with random values and unique identifiers
void initializeRecords(int numOffsets, const std::vector<std::string>& validKeys, Record** records) {
    if (numOffsets <= 0 || validKeys.empty()) {
        throw std::invalid_argument("Invalid input parameters");
    }

    // Allocate memory for the records
    *records = new Record[numOffsets];
    if (!*records) {
        throw std::bad_alloc();
    }

    // Initialize random number generator
    std::srand(std::time(0));

    // Set unique identifiers and random values for each record
    for (int i = 0; i < numOffsets; ++i) {
        (*records)[i].intValue = rand() % 1000; // Random int value between 0 and 999
        (*records)[i].doubleValue = static_cast<double>(rand()) / RAND_MAX * 100.0; // Random double value between 0 and 100

        // Allocate memory for the string identifier
        (*records)[i].identifier = new std::string(validKeys[i % validKeys.size()]);
    }
}

// Function to clean up allocated resources
void cleanupRecords(int numOffsets, Record* records) {
    if (records) {
        for (int i = 0; i < numOffsets; ++i) {
            delete records[i].identifier;
        }
        delete[] records;
    }
}

int main() {
    try {
        int numOffsets = 1000;
        std::vector<std::string> validKeys = {"key1", "key2", "key3"};

        Record* records;
        initializeRecords(numOffsets, validKeys, &records);

        // Use the records...

        cleanupRecords(numOffsets, records);
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
