['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <pthread.h>

#define MAX_MEMORY 1024 * 1024 * 1024 // 1GB

typedef struct Record {
    long offset;
    int key;
    char* identifier;
    void* record_data;
    void* extra_metadata;
    EVP_CIPHER_CTX* cipher_ctx;
    EVP_MD_CTX* digest_ctx;
    RSA* rsa_key;
} Record;

typedef struct Pool {
    size_t block_size;
    size_t pool_size;
    void* memory;
    size_t used_memory;
    pthread_mutex_t lock;
} Pool;

Pool* create_pool(size_t block_size, size_t pool_size) {
    Pool* pool = (Pool*)malloc(sizeof(Pool));
    pool->block_size = block_size;
    pool->pool_size = pool_size;
    pool->memory = malloc(block_size * pool_size);
    pool->used_memory = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(Pool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_memory + pool->block_size > pool->pool_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }
    void* block = ((char*)pool->memory) + pool->used_memory;
    pool->used_memory += pool->block_size;
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void free_to_pool(Pool* pool, void* block) {
    // In a real implementation, you would need to track which blocks are in use
    // and handle deallocation properly.
}

Record* create_record(Pool* pool) {
    Record* record = (Record*)allocate_from_pool(pool);
    if (!record) return NULL;

    record->offset = 0;
    record->key = rand() % 1000; // Example range, adjust as needed
    record->identifier = (char*)malloc(256); // Adjust size as needed
    snprintf(record->identifier, 256, "ID_%d", record->key);
    record->record_data = allocate_from_pool(pool);
    if (!record->record_data) {
        free(record->identifier);
        free_to_pool(pool, record);
        return NULL;
    }
    record->extra_metadata = allocate_from_pool(pool);
    if (!record->extra_metadata) {
        free(record->identifier);
        free(record->record_data);
        free_to_pool(pool, record);
        return NULL;
    }

    EVP_CIPHER_CTX_init(&record->cipher_ctx);
    EVP_MD_CTX_init(&record->digest_ctx);

    RSA_generate_key_ex(&record->rsa_key, 2048, RSA_F4, NULL);

    return record;
}

void destroy_record(Record* record, Pool* pool) {
    free(record->identifier);
    free(record->record_data);
    free(record->extra_metadata);
    EVP_CIPHER_CTX_cleanup(&record->cipher_ctx);
    EVP_MD_CTX_cleanup(&record->digest_ctx);
    RSA_free(record->rsa_key);
    free_to_pool(pool, record);
}

int main() {
    Pool* pool = create_pool(sizeof(Record), 100); // Adjust size as needed
    Record* record = create_record(pool);
    if (record) {
        printf("Record created successfully.\n");
        destroy_record(record, pool);
    } else {
        printf("Failed to create record.\n");
    }
    free_pool(pool);
    return 0;
}
