#define MAX_INTERFACES 1024

typedef struct {
    char interface_name[50];
    double throughput;
    double latency;
    double error_rate;
} NetworkStats;

NetworkStats *network_stats_array = NULL;
int current_size = 0;
int max_size = MAX_INTERFACES;

void initialize_network_stats() {
    network_stats_array = (NetworkStats *)malloc(max_size * sizeof(NetworkStats));
    if (network_stats_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
}

void add_network_interface(const char *interface_name, double throughput, double latency, double error_rate) {
    if (current_size >= max_size) {
        max_size *= 2;
        network_stats_array = (NetworkStats *)realloc(network_stats_array, max_size * sizeof(NetworkStats));
        if (network_stats_array == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
    }
    strcpy(network_stats_array[current_size].interface_name, interface_name);
    network_stats_array[current_size].throughput = throughput;
    network_stats_array[current_size].latency = latency;
    network_stats_array[current_size].error_rate = error_rate;
    current_size++;
}

void update_network_interface(const char *interface_name, double throughput, double latency, double error_rate) {
    for (int i = 0; i < current_size; i++) {
        if (strcmp(network_stats_array[i].interface_name, interface_name) == 0) {
            network_stats_array[i].throughput = throughput;
            network_stats_array[i].latency = latency;
            network_stats_array[i].error_rate = error_rate;
            return;
        }
    }
    fprintf(stderr, "Interface not found\n");
}

void log_network_stats() {
    FILE *log_file = fopen("network_stats.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    for (int i = 0; i < current_size; i++) {
        fprintf(log_file, "Interface: %s, Throughput: %.2f, Latency: %.2f, Error Rate: %.2f\n",
                network_stats_array[i].interface_name,
                network_stats_array[i].throughput,
                network_stats_array[i].latency,
                network_stats_array[i].error_rate);
    }
    fclose(log_file);
}

