#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_EXTRA_DATA_SIZE 1024 // 1KB
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct Record {
    int value;
    long* offset;
    int key;
    void* extra;
    bool compressed;
    int fragmentation_level;
} Record;

Record* create_records(int n, bool compressed) {
    if (n * sizeof(Record) + n * MAX_EXTRA_DATA_SIZE > MAX_MEMORY) {
        return NULL; // Exceeds maximum memory
    }

    Record* records = malloc(n * sizeof(Record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    void* extra_data_pool = malloc(n * MAX_EXTRA_DATA_SIZE);
    if (!extra_data_pool) {
        free(records);
        return NULL; // Memory allocation failed
    }

    long offset = (long)extra_data_pool;
    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        records[i].offset = (long*)malloc(sizeof(long));
        *records[i].offset = offset;

        if (compressed) {
            records[i].extra = extra_data_pool;
            records[i].fragmentation_level = i % 2; // Simulate fragmentation
        } else {
            records[i].extra = malloc(MAX_EXTRA_DATA_SIZE);
            if (!records[i].extra) {
                free(extra_data_pool);
                for (int j = 0; j < i; j++) {
                    free(records[j].offset);
                    if (!compressed || records[j].extra != extra_data_pool) {
                        free(records[j].extra);
                    }
                }
                free(records);
                return NULL; // Memory allocation failed
            }
        }

        records[i].key = i;
        records[i].compressed = compressed;
    }

    return records;
}

void destroy_records(Record* records, int n, bool compressed) {
    for (int i = 0; i < n; i++) {
        free(records[i].offset);
        if (!compressed || records[i].extra != records[0].extra) {
            free(records[i].extra);
        }
    }
    free(records);
}

void print_memory_usage(Record* records, int n) {
    size_t total_used = 0;
    for (int i = 0; i < n; i++) {
        total_used += sizeof(Record) + MAX_EXTRA_DATA_SIZE;
    }

    printf("Total memory used: %zu bytes\n", total_used);
    printf("Memory usage per record: %zu bytes\n", total_used / n);
}
```

This code snippet defines a `Record` structure and provides functions to create, destroy, and print the memory usage of an array of records. The `create_records` function dynamically allocates memory for the records and extra data, ensuring that the total memory allocation does not exceed the maximum allowed size (`MAX_MEMORY`). It also handles lazy allocation of 'extra' data and manages shared segments in compressed mode. The `destroy_records` function cleans up allocated resources when they are no longer needed. The `print_memory_usage` function provides a detailed report on the memory usage, including fragmentation levels.']

