typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

void init_dynamic_array(DynamicArray *da) {
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_CLIENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    da->size = 0;
    da->capacity = MAX_CLIENTS;
    pthread_mutex_init(&da->mutex, NULL);
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    free(da->array);
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
}

bool add_to_dynamic_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->mutex);
    if (da->size >= da->capacity) {
        // Handle capacity exceeded
        pthread_mutex_unlock(&da->mutex);
        return false;
    }
    da->array[da->size++] = pdu;
    pthread_mutex_unlock(&da->mutex);
    return true;
}

