#define MAX_INTERFACES 1000

typedef struct {
    int interface_id;
    float load_percentage;
    float packet_loss_rate;
    float latency;
} NetworkStats;

NetworkStats *network_stats_array = NULL;
int current_size = 0;
int max_size = 0;
pthread_mutex_t stats_lock;

void initialize_network_stats(int initial_size) {
    if (initial_size > MAX_INTERFACES) {
        printf("Error: Initial size exceeds maximum allowed interfaces.\n");
        return;
    }
    network_stats_array = (NetworkStats *)malloc(initial_size * sizeof(NetworkStats));
    if (!network_stats_array) {
        printf("Error: Memory allocation failed.\n");
        return;
    }
    current_size = initial_size;
    max_size = initial_size;
    pthread_mutex_init(&stats_lock, NULL);
}

void add_interface(int interface_id) {
    if (current_size >= max_size) {
        NetworkStats *new_array = (NetworkStats *)realloc(network_stats_array, (max_size + 100) * sizeof(NetworkStats));
        if (!new_array) {
            printf("Error: Memory reallocation failed.\n");
            return;
        }
        network_stats_array = new_array;
        max_size += 100;
    }
    network_stats_array[current_size].interface_id = interface_id;
    network_stats_array[current_size].load_percentage = 0.0;
    network_stats_array[current_size].packet_loss_rate = 0.0;
    network_stats_array[current_size].latency = 0.0;
    current_size++;
}

void update_network_stats(int interface_id, float load_percentage, float packet_loss_rate, float latency) {
    pthread_mutex_lock(&stats_lock);
    for (int i = 0; i < current_size; i++) {
        if (network_stats_array[i].interface_id == interface_id) {
            network_stats_array[i].load_percentage = load_percentage;
            network_stats_array[i].packet_loss_rate = packet_loss_rate;
            network_stats_array[i].latency = latency;
            break;
        }
    }
    pthread_mutex_unlock(&stats_lock);
}

void log_network_stats() {
    // Implement logging mechanism here
}

void *monitor_thread(void *arg) {
    while (1) {
        for (int i = 0; i < current_size; i++) {
            // Simulate data sampling and aggregation
            update_network_stats(network_stats_array[i].interface_id, 
                                 rand() % 100 / 10.0, 
                                 rand() % 100 / 1000.0, 
                                 rand() % 100);
        }
        log_network_stats();
        sleep(1); // Simulate periodic data sampling
    }
    return NULL;
}

int main() {
    initialize_network_stats(500);
    pthread_t monitor_tid;
    pthread_create(&monitor_tid, NULL, monitor_thread, NULL);

    // Add more interfaces as needed
    for (int i = 1; i <= 500; i++) {
        add_interface(i);
    }

    pthread_join(monitor_tid, NULL);
    free(network_stats_array);
    pthread_mutex_destroy(&stats_lock);
    return 0;
}
