#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1 MB
#define MIN_VALUE 10
#define MAX_VALUE 100

typedef struct {
    int key;
    long offset;
    int value;
} Record;

int allocate_records(int n, Record **records) {
    size_t record_size = sizeof(Record);
    size_t total_size = n * record_size;

    if (total_size > MAX_MEMORY) {
        fprintf(stderr, "Error: Requested memory exceeds maximum limit.\n");
        return -1;
    }

    *records = (Record *)malloc(total_size);
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory.\n");
        return -2;
    }

    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        (*records)[i].key = i;
        (*records)[i].offset = (long)((char *)&(*records)[i] - (char *)*records);
        (*records)[i].value = MIN_VALUE + rand() % (MAX_VALUE - MIN_VALUE + 1);
    }

    return n;
}

void free_records(Record *records) {
    if (records != NULL) {
        free(records);
    }
}

int main() {
    int n = 100;
    Record *records;

    int result = allocate_records(n, &records);
    if (result >= 0) {
        printf("Successfully allocated %d records.\n", result);

        // Use the records...

        free_records(records);
    }

    return 0;
}
