        new_record.field = rand() % 201 - 100;
        int duplicate = 0;
        for (int i = 0; i < used_records; i++) {
            if (data->records[i].field == new_record.field) {
                duplicate = 1;
                break;
            }
        }
        if (!duplicate) {
            data->records[used_records++] = new_record;
        }
    }

    for (int i = 0; i < OFFSET_SIZE; i++) {
        data->offsets[i] = rand() % used_records * sizeof(record);
    }

    pthread_mutex_unlock(&mutex);
}

void reset_data() {
    pthread_mutex_lock(&mutex);
    if (data != NULL) {
        free(data);
        data = NULL;
    }
    pthread_mutex_unlock(&mutex);
}

