#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int UE_ID;
    int RRC_STATE;
    int SRS_CONFIG;
} UEContext;

typedef struct {
    UEContext *contexts;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} UEContextManager;

UEContextManager* create_manager() {
    UEContextManager *manager = (UEContextManager*)malloc(sizeof(UEContextManager));
    manager->contexts = NULL;
    manager->capacity = 0;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_manager(UEContextManager *manager) {
    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_context(UEContextManager *manager, UEContext context) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        UEContext *new_contexts = realloc(manager->contexts, new_capacity * sizeof(UEContext));
        if (!new_contexts) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }
    manager->contexts[manager->size++] = context;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_context(UEContextManager *manager, int UE_ID) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].UE_ID == UE_ID) {
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->contexts[j] = manager->contexts[j + 1];
            }
            --manager->size;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Context not found
}

int update_srs_config(UEContextManager *manager, int UE_ID, int new_config) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].UE_ID == UE_ID) {
            manager->contexts[i].SRS_CONFIG = new_config;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Context not found
}
