#define MAX_ENTRIES 10000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries[MAX_ENTRIES];
    pthread_mutex_t lock;
    int count;
} DynamicList;

DynamicList* dynamic_list_init() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        list->entries[i] = NULL;
    }
    return list;
}

void dynamic_list_add(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (!list->entries[i]) {
            list->entries[i] = pdu;
            list->count++;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* dynamic_list_get(DynamicList *list, RNTI rnti) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (list->entries[i] && list->entries[i]->rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = list->entries[i];
            list->entries[i] = NULL;
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return pdu;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void dynamic_list_free(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (list->entries[i]) {
            free(list->entries[i]);
        }
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
