#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <boost/asio.hpp>

class CacheManager {
public:
    void set(const std::string& key, const std::string& value, int expiration) {}
    std::optional<std::string> get(const std::string& key) { return {}; }
};

class MockCacheManager : public CacheManager {
private:
    std::unordered_map<std::string, std::pair<std::string, int>> cache;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void set(const std::string& key, const std::string& value, int expiration) override {
        std::lock_guard<std::mutex> lock(mtx);
        cache[key] = {value, expiration};
        cv.notify_all();
    }

    std::optional<std::string> get(const std::string& key) override {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, &key]{ return cache.find(key) != cache.end(); });
        auto& entry = cache[key];
        if (entry.second > 0) {
            --entry.second;
            return entry.first;
        }
        return {};
    }
};

void processInput(MockCacheManager& cacheManager) {
    std::string line;
    while (std::getline(std::cin, line)) {
        // Trim leading and trailing whitespace
        line.erase(0, line.find_first_not_of(" \t\n\r\f\v"));
        line.erase(line.find_last_not_of(" \t\n\r\f\v") + 1);

        if (line.empty()) continue;

        // Check for null characters
        if (line.find('\0') != std::string::npos) {
            std::cerr << "Null character detected in input." << std::endl;
            continue;
        }

        // Simulate cache operations with random key-value pairs and expiration times
        std::string key = "key" + std::to_string(rand() % 100);
        std::string value = "value" + std::to_string(rand() % 100);
        int expiration = rand() % 60; // Random expiration time between 0 and 59 seconds

        cacheManager.set(key, value, expiration);

        // Simulate concurrent GET operations
        if (rand() % 2 == 0) {
            auto result = cacheManager.get(key);
            if (result.has_value()) {
                std::cout << "Cache hit: " << key << " -> " << result.value() << std::endl;
            } else {
                std::cout << "Cache miss for key: " << key << std::endl;
            }
        }
    }
}

void findLongestWord(const std::vector<std::string>& lines) {
    std::string longestWord = "";
    std::unordered_map<std::string, int> wordCount;

    for (const auto& line : lines) {
        std::istringstream iss(line);
        std::string word;
        while (iss >> word) {
            if (word.length() > longestWord.length()) {
                longestWord = word;
            }
            ++wordCount[word];
        }
    }

    std::cout << "Longest word: " << longestWord << std::endl;

    for (const auto& pair : wordCount) {
        if (pair.second > 1) {
            std::cout << "Duplicate word: " << pair.first << ", Count: " << pair.second << std::endl;
        }
    }
}

int main() {
    MockCacheManager cacheManager;
    std::vector<std::string> lines;

    // Process input from standard input
    processInput(cacheManager);

    // Find and print the longest word in the auxiliary array
    findLongestWord(lines);

    return 0;
}
