Record* parseAndAnalyzeUEData(const char *filename, const char *delimiter, int max_field_length) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Estimate initial memory allocation based on file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    Record *records = (Record *)malloc(sizeof(Record) * (file_size / MAX_LINE_LENGTH));
    if (!records) {
        perror("Failed to allocate initial memory");
        fclose(file);
        return NULL;
    }

    int record_count = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        Record record;
        record.fields = (char **)malloc(sizeof(char *) * MAX_FIELDS);
        if (!record.fields) {
            perror("Failed to allocate memory for fields");
            free(records);
            fclose(file);
            return NULL;
        }
        record.field_count = 0;

        char *token = strtok(line, delimiter);
        while (token && record.field_count < MAX_FIELDS) {
            // Trim leading and trailing whitespace
            token[strcspn(token, " \t\n")] = '\0';
            if (*token != '\0') {
                // Truncate fields exceeding max_field_length
                if (strlen(token) > max_field_length) {
                    token[max_field_length] = '\0';
                }
                record.fields[record.field_count++] = strdup(token);
            }
            token = strtok(NULL, delimiter);
        }

        records[record_count++] = record;
    }

    fclose(file);

    // Process input from standard input until "END" is encountered
    while (1) {
        printf("Enter a line or type 'END' to finish:\n");
