#include <sys/socket.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024
#define PORT_RANGE_START 8000
#define PORT_RANGE_END 9000

typedef struct {
    int client_socket;
    char ip[INET_ADDRSTRLEN];
    int port;
    enum { ESTABLISHED, CLOSING } state;
} Connection;

Connection connections[MAX_CONNECTIONS];
int last_used_port = PORT_RANGE_START - 1;

void* handle_client(void* arg) {
    // Client handling logic here
    return NULL;
}

int allocate_connection(int client_socket, const char* ip, int port) {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i].state == CLOSING) {
            connections[i] = (Connection){client_socket, ip, port, ESTABLISHED};
            return i;
        }
    }
    return -1;
}

void initialize_memory_pool() {
    // Memory pool initialization logic here
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT_RANGE_START);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &address.sin_addr, ip, INET_ADDRSTRLEN);

        int port = ntohs(address.sin_port);
        if (port >= PORT_RANGE_START && port <= PORT_RANGE_END) {
            int connection_index = allocate_connection(new_socket, ip, port);
            if (connection_index != -1) {
                pthread_t thread_id;
                pthread_create(&thread_id, NULL, handle_client, &connections[connection_index]);
                pthread_detach(thread_id);
            } else {
                close(new_socket);
            }
        } else {
            close(new_socket);
        }
    }

    close(server_fd);
    return 0;
}
