Record* parseAndAggregateData(char **csvFiles, int fileCount, char *liveDataStream) {
    Record *records = (Record *)malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    int recordCount = 0;

    // Process CSV files
    for (int i = 0; i < fileCount; i++) {
        FILE *file = fopen(csvFiles[i], "r");
        if (!file) {
            fprintf(stderr, "Failed to open file: %s\n", csvFiles[i]);
            continue;
        }

        char line[1024];
        while (fgets(line, sizeof(line), file)) {
            // Trim leading and trailing whitespace
            line[strcspn(line, "\r\n")] = 0;
            records[recordCount].data = strdup(line);
            if (!records[recordCount].data) {
                fprintf(stderr, "Memory allocation failed for record %d\n", recordCount);
                free(records);
                return NULL;
            }
            recordCount++;
        }

        fclose(file);
    }

    // Process live data stream
    if (liveDataStream) {
        records[recordCount].data = strdup(liveDataStream);
        if (!records[recordCount].data) {
            fprintf(stderr, "Memory allocation failed for record %d\n", recordCount);
            free(records);
            return NULL;
        }
        recordCount++;
    }

    // Resize array to fit actual number of records
    Record *resizedRecords = (Record *)realloc(records, recordCount * sizeof(Record));
    if (!resizedRecords) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(records);
        return NULL;
    }
    records = resizedRecords;

    return records;
}

void freeRecords(Record *records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i].data);
    }
    free(records);
