#define MAX_MEMORY 1024 * 1024 // 1 MB
#define MAX_METADATA_SIZE 256
#define MAX_SEGMENTS 100
#define FRAGMENTATION_THRESHOLD 0.3

typedef struct Metadata {
    char tag[MAX_METADATA_SIZE];
} Metadata;

typedef union ConfigValue {
    int intValue;
    char stringValue[256];
} ConfigValue;

typedef struct ConfigSetting {
    char name[256];
    ConfigValue value;
    Metadata *metadata;
    int metadataCount;
} ConfigSetting;

ConfigSetting *configPool = NULL;
int configCount = 0;
int segmentCount = 0;

int allocateConfig(int n) {
    if (n > MAX_SEGMENTS) {
        return -1; // Exceeds maximum segments
    }

    size_t totalSize = n * sizeof(ConfigSetting);
    for (int i = 0; i < n; i++) {
        configPool[i].metadata = malloc(MAX_METADATA_SIZE * sizeof(Metadata));
        if (!configPool[i].metadata) {
            return -1; // Memory allocation failed
        }
    }

    configCount += n;
    segmentCount += n;

    return 0;
}

void initializeConfig(int n, ConfigValue defaultValue) {
    for (int i = 0; i < n; i++) {
        strcpy(configPool[i].name, "default_name");
        configPool[i].value = defaultValue;
        configPool[i].metadataCount = 0;
    }
}

void setConfigNameAndValue(int index, const char *name, ConfigValue value) {
    if (index >= configCount) {
        return; // Invalid index
    }

    strcpy(configPool[index].name, name);
    configPool[index].value = value;
}

void logMemoryUsage() {
    printf("Total Memory: %zu bytes\n", MAX_MEMORY);
    printf("Used Memory: %zu bytes\n", configCount * sizeof(ConfigSetting) + segmentCount * MAX_METADATA_SIZE * sizeof(Metadata));
    printf("Fragmentation: %.2f%%\n", (float)(segmentCount - configCount) / configCount * 100);
}

int main() {
    ConfigValue defaultValue = { .intValue = 0 };
    if (allocateConfig(50) == 0) {
        initializeConfig(50, defaultValue);

        setConfigNameAndValue(0, "setting1", (ConfigValue){ .intValue = 42 });
        setConfigNameAndValue(1, "setting2", (ConfigValue){ .stringValue = "example" });

        logMemoryUsage();
    } else {
        printf("Failed to allocate configuration pool\n");
    }

    return 0;
}
