#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct logEntry {
    char* timestamp;
    char* message;
    int severity;
} logEntry;

typedef struct hashTable {
    size_t size;
    logEntry** entries;
} hashTable;

hashTable* createHashTable(size_t size) {
    hashTable* table = (hashTable*)malloc(sizeof(hashTable));
    if (!table) return NULL;
    table->size = size;
    table->entries = (logEntry**)calloc(size, sizeof(logEntry*));
    if (!table->entries) {
        free(table);
        return NULL;
    }
    return table;
}

void destroyHashTable(hashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        logEntry* entry = table->entries[i];
        if (entry) {
            free(entry->timestamp);
            free(entry->message);
            free(entry);
        }
    }
    free(table->entries);
    free(table);
}

logEntry* createLogEntry(const char* timestamp, const char* message, int severity) {
    logEntry* entry = (logEntry*)malloc(sizeof(logEntry));
    if (!entry) return NULL;
    entry->timestamp = strdup(timestamp);
    entry->message = strdup(message);
    entry->severity = severity;
    return entry;
}

void destroyLogEntry(logEntry* entry) {
    free(entry->timestamp);
    free(entry->message);
    free(entry);
}

size_t hashFunction(const char* key, size_t size) {
    size_t hash = 0;
    for (const char* p = key; *p != '\0'; ++p) {
        hash = (hash * 31) + *p;
    }
    return hash % size;
}

void insertLogEntry(hashTable* table, const char* timestamp, const char* message, int severity) {
    size_t index = hashFunction(timestamp, table->size);
    logEntry* entry = createLogEntry(timestamp, message, severity);
    if (entry) {
        while (table->entries[index]) ++index;
        table->entries[index] = entry;
    }
}

void filterLogs(hashTable* table, int minSeverity) {
    for (size_t i = 0; i < table->size; ++i) {
        logEntry* entry = table->entries[i];
        if (entry && entry->severity >= minSeverity) {
            printf("Timestamp: %s, Message: %s, Severity: %d\n", entry->timestamp, entry->message, entry->severity);
        }
    }
}

int main() {
    hashTable* logTable = createHashTable(1024);
    if (!logTable) return 1;

    // Example usage
    insertLogEntry(logTable, "2023-04-01T12:00:00Z", "System started", 1);
    insertLogEntry(logTable, "2023-04-01T12:05:00Z", "Error occurred", 3);

    filterLogs(logTable, 2);

    destroyHashTable(logTable);
    return 0;
}
