void initializeDataStructures(int numRecords, int maxKeyValue, int randomRange) {
    if (numRecords > 10000 || maxKeyValue <= 0 || randomRange <= 0) {
        // Handle invalid input
        return;
    }

    long* offsetValues = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    record* records = (record*)malloc(numRecords * sizeof(record));
    int* recordIndices = (int*)malloc(numRecords * sizeof(int));

    if (!offsetValues || !keys || !records || !recordIndices) {
        // Handle memory allocation failure
        return;
    }

    // Initialize offset values
    for (int i = 0; i < numRecords; i++) {
        offsetValues[i] = i;
    }

    // Initialize keys
    for (int i = 0; i < numRecords; i++) {
        keys[i] = i + 1;
    }

    // Initialize records with random values
    srand(time(NULL));
    int lastValue = -1;
    for (int i = 0; i < numRecords; i++) {
        int newValue;
        do {
            newValue = rand() % randomRange + 1;
        } while (newValue == lastValue);
        records[i].value = newValue;
        lastValue = newValue;
    }

    // Initialize record indices
    for (int i = 0; i < numRecords; i++) {
        recordIndices[i] = i;
    }

    // Set used flags to indicate assignment status
    for (int i = 0; i < numRecords; i++) {
        recordIndices[i] |= (i % 2 == 0) ? 1 : 0;
    }

    // Free allocated memory
    free(offsetValues);
    free(keys);
    free(records);
    free(recordIndices);
}
