void init_memory_pool(size_t initial_size) {
    memory_pool.pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memory_pool.pool) {
        perror("Failed to allocate memory for memory pool");
        exit(EXIT_FAILURE);
    }
    memory_pool.pool_size = initial_size;
    memory_pool.used_size = 0;
}

void destroy_memory_pool() {
    free(memory_pool.pool);
    memory_pool.pool = NULL;
    memory_pool.pool_size = 0;
    memory_pool.used_size = 0;
}

NFAPI_CRC_INDICATION_PDU_T *allocate_structure(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.used_size + size > memory_pool.pool_size) {
        // Resize the pool
        NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(memory_pool.pool, memory_pool.pool_size * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            perror("Failed to resize memory pool");
            pthread_mutex_unlock(&memory_pool.lock);
            return NULL;
        }
        memory_pool.pool = new_pool;
        memory_pool.pool_size *= 2;
    }

    NFAPI_CRC_INDICATION_PDU_T *ptr = &memory_pool.pool[memory_pool.used_size];
    memory_pool.used_size += size;
    pthread_mutex_unlock(&memory_pool.lock);
    return ptr;
}

