#define MAX_IP_ADDRESSES 1000

typedef enum {
    ESTABLISHED,
    TIME_WAIT,
    CLOSE_WAIT
} ConnectionState;

typedef struct {
    char ip[16];
    int port;
    ConnectionState state;
} TCPConnectionRecord;

TCPConnectionRecord* connection_records = NULL;
int num_connections = 0;
int max_ip_addresses = MAX_IP_ADDRESSES;

void resize_connection_records() {
    if (num_connections >= max_ip_addresses) {
        max_ip_addresses *= 2;
        connection_records = realloc(connection_records, max_ip_addresses * sizeof(TCPConnectionRecord));
        if (!connection_records) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
}

void add_connection_record(const char* ip, int port, ConnectionState state) {
    resize_connection_records();
    strcpy(connection_records[num_connections].ip, ip);
    connection_records[num_connections].port = port;
    connection_records[num_connections].state = state;
    num_connections++;
}

int find_connection_index(const char* ip) {
    for (int i = 0; i < num_connections; i++) {
        if (strcmp(connection_records[i].ip, ip) == 0) {
            return i;
        }
    }
    return -1;
}

void update_connection_state(const char* ip, ConnectionState state) {
    int index = find_connection_index(ip);
    if (index != -1) {
        connection_records[index].state = state;
    } else {
        fprintf(stderr, "Connection not found\n");
    }
}

void print_connection_records() {
    for (int i = 0; i < num_connections; i++) {
        printf("IP: %s, Port: %d, State: %d\n", connection_records[i].ip, connection_records[i].port, connection_records[i].state);
    }
}

