char* encrypt_string(const char* plaintext, const unsigned char* key, size_t key_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    unsigned char iv[EVP_MAX_BLOCK_LENGTH];
    memset(iv, 0, sizeof(iv));

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Failed to initialize encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    int len;
    unsigned char* ciphertext = malloc(strlen(plaintext) + EVP_MAX_BLOCK_LENGTH);
    if (!ciphertext) {
        fprintf(stderr, "Memory allocation failed for ciphertext\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char*)plaintext, strlen(plaintext))) {
        fprintf(stderr, "Encryption update failed\n");
        free(ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Encryption final failed\n");
        free(ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    ciphertext_len += len;

    ciphertext[ciphertext_len] = '\0';
    EVP_CIPHER_CTX_free(ctx);

    char* result = malloc(ciphertext_len + 1);
    if (!result) {
        fprintf(stderr, "Memory allocation failed for result\n");
        free(ciphertext);
        return NULL;
    }
    memcpy(result, ciphertext, ciphertext_len);
    result[ciphertext_len] = '\0';
    free(ciphertext);

    return result;
}

void dynamicResourceManager(int resource_count, int max_value, int key_limit) {
    if (resource_count * sizeof(resource) > MAX_MEMORY) {
        fprintf(stderr, "Insufficient memory for resources\n");
        return;
    }

    resource* pool = malloc(resource_count * sizeof(resource));
    if (!pool) {
        fprintf(stderr, "Memory allocation failed for resource pool\n");
        return;
    }

    long offset = 0;
    int last_value = -1;

    for (int i = 0; i < resource_count; ++i) {
        while (1) {
            int value = rand() % max_value + 1;
            if (value != last_value && abs(value - last_value) > 1) {
                pool[i].value = value;
                break;
            }
        }

        pool[i].offset = &offset;
        *pool[i].offset = offset;
        offset += sizeof(long);

        pool[i].key = rand() % key_limit + 1;

        printf("Resource %d: Value=%d, Offset=%ld, Key=%d\n", i, pool[i].value, *pool[i].offset, pool[i].key);
    }

    // Implement HTTP PUT and DELETE methods here

    // Free allocated memory
    free(pool);
}

int main() {
    srand(time(NULL));
    dynamicResourceManager(10, 100, 20);
    return 0;
}
