file_processor* create_file_processor(int num_keys) {
    if (num_keys <= 0) {
        fprintf(stderr, "Invalid number of keys\n");
        return NULL;
    }

    file_processor *fp = (file_processor*)malloc(sizeof(file_processor));
    if (!fp) {
        fprintf(stderr, "Memory allocation failed for file_processor\n");
        return NULL;
    }

    fp->offsets = (long*)calloc(num_keys, sizeof(long));
    if (!fp->offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        free(fp);
        return NULL;
    }

    fp->keys = (int*)malloc(num_keys * sizeof(int));
    if (!fp->keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(fp->offsets);
        free(fp);
        return NULL;
    }

    fp->records = (record**)malloc(num_keys * sizeof(record*));
    if (!fp->records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(fp->keys);
        free(fp->offsets);
        free(fp);
        return NULL;
    }

    fp->num_keys = num_keys;
    fp->max_records = num_keys;

    for (int i = 0; i < num_keys; i++) {
        fp->records[i] = (record*)malloc(sizeof(record));
        if (!fp->records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            for (int j = 0; j < i; j++) {
                free(fp->records[j]);
            }
            free(fp->records);
            free(fp->keys);
            free(fp->offsets);
            free(fp);
            return NULL;
        }

        fp->records[i]->value = (int*)malloc(sizeof(int));
        if (!fp->records[i]->value) {
            fprintf(stderr, "Memory allocation failed for value in record %d\n", i);
            free(fp->records[i]);
            for (int j = 0; j < i; j++) {
                free(fp->records[j]);
            }
            free(fp->records);
            free(fp->keys);
            free(fp->offsets);
            free(fp);
            return NULL;
        }

        *fp->records[i]->value = rand() % INT_MAX;
        fp->records[i]->modified = 0;
        fp->records[i]->key_index = i;
    }

    return fp;
}

void destroy_file_processor(file_processor *fp) {
    for (int i = 0; i < fp->num_keys; i++) {
        free(fp->records[i]->value);
        free(fp->records[i]);
    }
    free(fp->records);
    free(fp->keys);
    free(fp->offsets);
    free(fp);
}

void update_records(file_processor *fp, int key_index, int new_value) {
    if (key_index < 0 || key_index >= fp->num_keys) {
        fprintf(stderr, "Invalid key index\n");
        return;
    }

    *fp->records[key_index]->value = new_value;
    fp->records[key_index]->modified = 1;
}

