        fprintf(stderr, "Failed to allocate memory for connection IDs\n");
        return;
    }

    // Initialize connection IDs sequentially
    for (int i = 0; i < maxConnections; i++) {
        connectionIDs[i] = i + 1;
    }

    // Allocate memory for packets
    packet *packets = (packet *)malloc(maxConnections * sizeof(packet));
    if (!packets) {
        fprintf(stderr, "Failed to allocate memory for packets\n");
        free(connectionIDs);
        return;
    }

    // Initialize packet buffers with random data
    for (int i = 0; i < maxConnections; i++) {
        for (int j = 0; j < maxPacketSize; j++) {
            packets[i].buffer[j] = rand() % 256;
        }
    }

    // Allocate memory for connection structures
    connection *connections = (connection *)malloc(maxConnections * sizeof(connection));
    if (!connections) {
        fprintf(stderr, "Failed to allocate memory for connections\n");
        free(connectionIDs);
        free(packets);
        return;
