    // Initialize connections with unique IDs and packet data
    for (int i = 0; i < maxConnections; i++) {
        connections[i].id = connectionIDs[i];
        connections[i].data = &packets[i];
    }

    // Allocate memory for event handlers
    event_handler *handlers = (event_handler *)malloc(maxConnections * sizeof(event_handler));
    if (!handlers) {
        fprintf(stderr, "Failed to allocate memory for event handlers\n");
        free(connectionIDs);
        free(packets);
        free(connections);
        return;
