    srand(time(NULL));

    long current_offset = 0;
    int key_count = 0;

    for (long i = 0; i < max_size; ++i) {
        offsets[i] = current_offset++;
        keys[i] = range_start + rand() % (range_end - range_start + 1);
        records[i].value = range_start + rand() % (range_end - range_start + 1);

        // Handle duplicate keys and frequency threshold
        while (key_count > threshold) {
            keys[i] = range_start + rand() % (range_end - range_start + 1);
            key_count = 0;
        }

        for (int j = 0; j < i; ++j) {
            if (keys[j] == keys[i]) {
                key_count++;
            }
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}
