void manageDynamicList(int N, const char* resourceBundleFile) {
    FILE* file = fopen(resourceBundleFile, "r");
    if (!file) {
        perror("Failed to open resource bundle file");
        return;
    }

    // Dynamically allocate memory for arrays
    NFAPI_CRC_INDICATION_PDU_T* nfaapiArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaapiArray) {
        perror("Failed to allocate memory for NFAPI array");
        fclose(file);
        return;
    }

    long* offsetArray = (long*)malloc(N * sizeof(long));
    if (!offsetArray) {
        perror("Failed to allocate memory for offset array");
        free(nfaapiArray);
        fclose(file);
        return;
    }

    int* keyArray = (int*)malloc(N * sizeof(int));
    if (!keyArray) {
        perror("Failed to allocate memory for key array");
        free(nfaapiArray);
        free(offsetArray);
        fclose(file);
        return;
    }

    Record* recordArray = (Record*)malloc(N * sizeof(Record));
    if (!recordArray) {
        perror("Failed to allocate memory for record array");
        free(nfaapiArray);
        free(offsetArray);
        free(keyArray);
        fclose(file);
        return;
    }

    // Initialize arrays with random values
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        nfaapiArray[i].RX_UE_INFORMATION_TAG = rand();
        nfaapiArray[i].RNTI = rand();
        nfaapiArray[i].CRC_INDICATION_REL8_TAG = rand() % 2;

        offsetArray[i] = (long)rand();
        keyArray[i] = rand();

        recordArray[i].intField = rand() % 100;
    }

    // Read from resource bundle file
    int entriesRead = 0;
    while (fscanf(file, "%ld,%d", &offsetArray[entriesRead], &keyArray[entriesRead]) == 2) {
        entriesRead++;
        if (entriesRead >= N) break;
    }
    fclose(file);

    // Handle discrepancies between expected and actual data
    if (entriesRead != N) {
        fprintf(stderr, "Warning: Discrepancy in resource bundle entries. Expected %d, got %d\n", N, entriesRead);
    }

    // Free allocated memory
    free(nfaapiArray);
    free(offsetArray);
    free(keyArray);
    free(recordArray);
}
