typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t mutex;
} CRC_Indication_Array;

void* allocate_crc_indication_array(size_t max_memory_usage, size_t initial_size) {
    CRC_Indication_Array *array = (CRC_Indication_Array *)malloc(sizeof(CRC_Indication_Array));
    if (!array) return NULL;

    array->allocated_size = 0;
    array->used_size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    size_t max_elements = (size_t)(max_memory_usage / sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (initial_size > max_elements) initial_size = max_elements;

    array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->allocated_size = initial_size;
    return array;
}

void deallocate_crc_indication_array(CRC_Indication_Array *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->array);
    pthread_mutex_unlock(&array->mutex);
    free(array);
}

int add_crc_indication(CRC_Indication_Array *array, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&array->mutex);

    if (array->used_size >= array->allocated_size) {
        size_t new_size = array->allocated_size ? array->allocated_size * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->allocated_size = new_size;
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &array->array[array->used_size];
    entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    entry->RNTI = RNTI;
    entry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    entry->CRCFLAG = CRCFLAG;

    array->used_size++;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

