#define MAX_KEYS 1000
#define RECORD_RANGE 100

typedef struct {
    int value;
} record;

long* offsets;
int* keys;
record* records;
int* timestamps;
int max_keys;
int record_count;
pthread_mutex_t mutex;

void init_data_structures(int num_records, int max_key) {
    offsets = (long*)malloc(num_records * sizeof(long));
    keys = (int*)malloc(num_records * sizeof(int));
    records = (record*)malloc(num_records * sizeof(record));
    timestamps = (int*)malloc(num_records * sizeof(int));
    max_keys = max_key;
    record_count = 0;

    pthread_mutex_init(&mutex, NULL);
}

void* allocate_record(void* arg) {
    int thread_id = *(int*)arg;
    long offset = -1;
    int key = -1;
    int value = -1;
    time_t timestamp;

    while (record_count < record_count + 100) { // Simulate concurrent allocation
        pthread_mutex_lock(&mutex);

        if (offset_count < record_count) {
            offset = offsets[offset_count++];
        } else {
            offset = record_count++;
        }

        key = rand() % max_keys;
        while (key == keys[record_count - 1]) {
            key = rand() % max_keys;
        }
        keys[record_count - 1] = key;

        value = rand() % RECORD_RANGE;
        while (value == records[record_count - 2].value) {
            value = rand() % RECORD_RANGE;
        }
        records[record_count - 1].value = value;

        timestamp = time(NULL);
        timestamps[record_count - 1] = (int)timestamp;

        pthread_mutex_unlock(&mutex);

        // Simulate some processing
        usleep(1000);
    }

    return NULL;
}

void free_data_structures() {
    free(offsets);
    free(keys);
    free(records);
    free(timestamps);
    pthread_mutex_destroy(&mutex);
}

int main() {
    int num_records = 1000;
    int max_key = MAX_KEYS;
    int num_threads = 4;

    srand(time(NULL));

    init_data_structures(num_records, max_key);

    pthread_t threads[num_threads];
    int thread_ids[num_threads];

    for (int i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, allocate_record, &thread_ids[i]);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    free_data_structures();

    return 0;
}
