#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value;
    struct Record *next;
} Record;

typedef struct HashTable {
    Record **buckets;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->size = size;
    ht->buckets = (Record**)calloc(size, sizeof(Record*));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_record(Record *record) {
    while (record != NULL) {
        Record *next = record->next;
        free(record);
        record = next;
    }
}

void destroy_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        pthread_mutex_lock(&ht->lock);
        destroy_record(ht->buckets[i]);
        pthread_mutex_unlock(&ht->lock);
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

void insert_record(HashTable *ht, int key, int value) {
    size_t index = (size_t)key % ht->size;
    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->value = value;
    new_record->next = NULL;

    pthread_mutex_lock(&ht->lock);
    if (ht->buckets[index] == NULL) {
        ht->buckets[index] = new_record;
    } else {
        Record *current = ht->buckets[index];
        while (current->next != NULL && current->value != value) {
            current = current->next;
        }
        if (current->value == value) {
            // Handle duplicate key, e.g., overwrite or skip
            free(new_record);
        } else {
            current->next = new_record;
        }
    }
    pthread_mutex_unlock(&ht->lock);
}

int get_value(HashTable *ht, int key) {
    size_t index = (size_t)key % ht->size;
    Record *current = ht->buckets[index];
    while (current != NULL) {
        if (current->value == key) {
            return current->value;
        }
        current = current->next;
    }
    return -1; // Key not found
}

int main() {
    HashTable *ht = create_hash_table(10);
    insert_record(ht, 5, 42);
    printf("Value for key 5: %d\n", get_value(ht, 5));
    destroy_hash_table(ht);
    return 0;
}
