    public static string InitializeDataProcessingPipeline(string base64EncodedMessage, byte[] key, byte[] iv)
    {
        // Decrypt the message using Triple DES encryption
        using (TripleDESCryptoServiceProvider des = new TripleDESCryptoServiceProvider())
        {
            des.Key = key;
            des.IV = iv;
            des.Mode = CipherMode.CBC;
            des.Padding = PaddingMode.PKCS7;

            byte[] decryptedBytes = Convert.FromBase64String(base64EncodedMessage);
            using (MemoryStream msDecrypt = new MemoryStream(decryptedBytes))
