#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int id;
    char username[50];
    char email[100];
    time_t last_activity;
} Session;

typedef struct {
    Session *sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

SessionManager *session_manager_init(size_t initial_capacity) {
    SessionManager *manager = (SessionManager *)malloc(sizeof(SessionManager));
    manager->sessions = (Session *)calloc(initial_capacity, sizeof(Session));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

int session_manager_add_user(SessionManager *manager, const char *username, const char *email) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        // Resize the sessions array
        manager->sessions = realloc(manager->sessions, manager->capacity * 2 * sizeof(Session));
        manager->capacity *= 2;
    }
    int id = manager->count++;
    strcpy(manager->sessions[id].username, username);
    strcpy(manager->sessions[id].email, email);
    manager->sessions[id].last_activity = time(NULL);
    pthread_mutex_unlock(&manager->lock);
    return id;
}

void session_manager_update_activity(SessionManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    if (id >= 0 && id < manager->count) {
        manager->sessions[id].last_activity = time(NULL);
    }
    pthread_mutex_unlock(&manager->lock);
}

void session_manager_cleanup_inactive_sessions(SessionManager *manager, time_t inactive_threshold) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ) {
        if (time(NULL) - manager->sessions[i].last_activity > inactive_threshold) {
            // Reuse the ID
            manager->count--;
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->count - i) * sizeof(Session));
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void session_manager_free(SessionManager *manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
