#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_ENTRIES 10000
#define GARBAGE_COLLECTION_INTERVAL 500

typedef struct logEntry {
    char* timestamp;
    char* message;
    int severityLevel;
} logEntry;

typedef struct hashTable {
    logEntry** entries;
    int size;
    int count;
    pthread_mutex_t lock;
} hashTable;

hashTable* createHashTable(int size) {
    hashTable* table = (hashTable*)malloc(sizeof(hashTable));
    if (!table) return NULL;
    table->entries = (logEntry**)calloc(size, sizeof(logEntry*));
    if (!table->entries) {
        free(table);
        return NULL;
    }
    table->size = size;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroyHashTable(hashTable* table) {
    for (int i = 0; i < table->size; i++) {
        if (table->entries[i]) {
            free(table->entries[i]->timestamp);
            free(table->entries[i]->message);
            free(table->entries[i]);
        }
    }
    free(table->entries);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int hashFunction(const char* key, int size) {
    // Simple hash function for demonstration purposes
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % size;
}

void insertLogEntry(hashTable* table, const char* timestamp, const char* message, int severityLevel) {
    pthread_mutex_lock(&table->lock);
    int index = hashFunction(timestamp, table->size);
    while (table->entries[index]) {
        if (strcmp(table->entries[index]->timestamp, timestamp) == 0) {
            // Update existing entry
            free(table->entries[index]->message);
            table->entries[index]->message = strdup(message);
            table->entries[index]->severityLevel += severityLevel;
            pthread_mutex_unlock(&table->lock);
            return;
        }
        index = (index + 1) % table->size;
    }
    // Insert new entry
    if (table->count >= table->size * 0.75) {
        // Resize and rehash
        hashTable* newTable = createHashTable(table->size * 2);
        for (int i = 0; i < table->size; i++) {
            if (table->entries[i]) {
                insertLogEntry(newTable, table->entries[i]->timestamp, table->entries[i]->message, table->entries[i]->severityLevel);
                free(table->entries[i]->timestamp);
                free(table->entries[i]->message);
                free(table->entries[i]);
            }
        }
        destroyHashTable(table);
        *table = *newTable;
    } else {
        table->entries[index] = (logEntry*)malloc(sizeof(logEntry));
        if (!table->entries[index]) {
            pthread_mutex_unlock(&table->lock);
            return;
        }
        table->entries[index]->timestamp = strdup(timestamp);
        table->entries[index]->message = strdup(message);
        table->entries[index]->severityLevel = severityLevel;
        table->count++;
    }
    pthread_mutex_unlock(&table->lock);
}

void* processLogFiles(void* arg) {
    hashTable* table = (hashTable*)arg;
    char line[1024];
    while (fgets(line, sizeof(line), stdin)) {
        // Parse the log entry
        char* timestamp = strtok(line, " ");
        char* message = strtok(NULL, " ");
        int severityLevel = atoi(strtok(NULL, " "));
        if (timestamp && message) {
            insertLogEntry(table, timestamp, message, severityLevel);
        }
    }
    return NULL;
}

void calculateAverageSeverity(hashTable* table) {
    pthread_mutex_lock(&table->lock);
    int totalSeverity = 0;
    for (int i = 0; i < table->size; i++) {
        if (table->entries[i]) {
            totalSeverity += table->entries[i]->severityLevel;
        }
    }
    double averageSeverity = (double)totalSeverity / table->count;
    printf("Average Severity: %.2f\n", averageSeverity);
    pthread_mutex_unlock(&table->lock);
}

int main() {
    hashTable* logTable = createHashTable(MAX_LOG_ENTRIES);
    if (!logTable) {
        fprintf(stderr, "Failed to allocate memory for log table.\n");
        return 1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, processLogFiles, logTable) != 0) {
        fprintf(stderr, "Failed to create thread for processing log files.\n");
        destroyHashTable(logTable);
        return 1;
    }

    // Simulate garbage collection
    sleep(GARBAGE_COLLECTION_INTERVAL);

    calculateAverageSeverity(logTable);

    pthread_join(thread, NULL);
    destroyHashTable(logTable);

    return 0;
}
