#include <sys/wait.h>
#include <signal.h>
#include <time.h>

#define MAX_KEY_VALUE 1000
#define RECORD_RANGE 100

typedef struct {
    int value;
} Record;

void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_arrays(long** offsets, int** keys, Record** records, int num_records) {
    *offsets = (long*)custom_malloc(num_records * sizeof(long));
    *keys = (int*)custom_malloc(num_records * sizeof(int));
    *records = (Record*)custom_malloc(num_records * sizeof(Record));

    for (int i = 0; i < num_records; i++) {
        (*offsets)[i] = i;
        (*keys)[i] = rand() % MAX_KEY_VALUE;
        while (i > 0 && (*keys)[i] == (*keys)[i - 1]) {
            (*keys)[i] = rand() % MAX_KEY_VALUE;
        }
        (*records)[i].value = rand() % RECORD_RANGE + 1;
    }
}

void manage_processes(int num_records, int max_processes) {
    pid_t* pids = (pid_t*)custom_malloc(num_records * sizeof(pid_t));
    for (int i = 0; i < num_records; i++) {
        pids[i] = fork();
        if (pids[i] == -1) {
            fprintf(stderr, "Fork failed\n");
            exit(EXIT_FAILURE);
        } else if (pids[i] == 0) {
            // Child process
            sleep(rand() % max_processes); // Simulate work
            exit(0);
        }
    }

    for (int i = 0; i < num_records; i++) {
        int status;
        waitpid(pids[i], &status, 0);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            fprintf(stderr, "Process %d terminated unexpectedly\n", pids[i]);
        }
    }

    free(pids);
}

void handle_signal(int signum) {
    printf("Signal received: %d\n", signum);
    exit(EXIT_FAILURE);
}

void log_status(const char* message) {
    printf("%s\n", message);
}

int main() {
    srand(time(NULL));

    int num_records = 10;
    int max_processes = 5;

    long* offsets;
    int* keys;
    Record* records;

    initialize_arrays(&offsets, &keys, &records, num_records);

    manage_processes(num_records, max_processes);

    signal(SIGCHLD, handle_signal);
    log_status("Starting process management");

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
