    char* extraDataBase = (char*)(*records) + n * recordSize;
    for (int i = 0; i < n; ++i) {
        (*records)[i].rnti = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        (*records)[i].config.logicalChannelIdentity = i; // Example assignment
        if (n > 1) { // Compressed mode
            (*records)[i].extraDataSegment = extraDataBase;
        } else {
            (*records)[i].extraDataSegment = malloc(sharedExtraDataSize);
            if ((*records)[i].extraDataSegment == NULL) {
                fprintf(stderr, "Memory allocation failed for extra data segment.\n");
                exit(EXIT_FAILURE);
            }
        }
    }

    // Initialize offsets
    int* offsets = (int*)(*records) + n;
    for (int i = 0; i < n; ++i) {
        offsets[i] = recordSize * i;
        (*records)[i].config.logicalChannelIdentity = offsets[i];
    }
}

void freeTransportRecords(TransportRecord** records, int n) {
    if (*records != NULL) {
        for (int i = 0; i < n; ++i) {
            if ((*records)[i].extraDataSegment != NULL && (*records)[i].extraDataSegment != (*records) + n * sizeof(TransportRecord)) {
                free((*records)[i].extraDataSegment);
            }
        }
        free(*records);
        *records = NULL;
    }
}

int main() {
    int n = 10; // Example number of records
    TransportRecord* records;

    initializeTransportRecords(&records, n);

    // Use the records...

    freeTransportRecords(&records, n);

    return 0;
}
