int create_directory_and_set_env(const char* dir_name, const char* env_var) {
    if (getenv(env_var) != NULL) {
        printf("%s is already set to %s\n", env_var, getenv(env_var));
        return 0;
    }

    if (mkdir(dir_name, 0755) == -1) {
        perror("Failed to create directory");
        return -1;
    }

    if (setenv(env_var, dir_name, 1) != 0) {
        perror("Failed to set environment variable");
        rmdir(dir_name);
        return -1;
    }

    printf("Directory %s created and %s set to %s\n", dir_name, env_var, dir_name);
    return 0;
}

void log_operation(const char* operation, int result) {
    if (result == 0) {
        printf("%s successful\n", operation);
    } else {
        printf("%s failed\n", operation);
    }
}

