    srand(time(NULL));

    for (long i = 0; i <= max_offset; ++i) {
        records[i].offset = i;
        records[i].key = rand() % (max_key + 1);
        int value;
        do {
            value = rand() % (value_range_end - value_range_start + 1) + value_range_start;
        } while (i > 0 && records[i - 1].record.value == value);
        records[i].record.value = value;
    }

    return records;
}

void free_records(DataRecord* records, long max_offset) {
    free(records);
}

