    int max_key = 500;
    int value_range_start = -100;
    int value_range_end = 100;

    DataRecord* records = initialize_records(max_offset, max_key, value_range_start, value_range_end);

    // Perform operations with records...

    free_records(records, max_offset);

    unsetenv(env_var);
    rmdir(dir_name);

    return EXIT_SUCCESS;
}
