    if (memory == NULL) {
        return NULL; // Memory allocation failed
    }

    long* long_array = (long*)memory;
    int* int_array = (int*)(memory + long_size * sizeof(long));
    record* record_array = (record*)(memory + long_size * sizeof(long) + int_size * sizeof(int));

    for (size_t i = 0; i < long_size; i++) {
        long_array[i] = 0; // Initialize long array
    }

    for (size_t i = 0; i < int_size; i++) {
        int_array[i] = 0; // Initialize int array
    }

    for (size_t i = 0; i < record_size; i++) {
        record_array[i].value = 0; // Initialize record array
    }

    return memory;
}

void free_memory(void* memory) {
    free(memory);
}

// Example usage
int main() {
    size_t long_size = 100;
    size_t int_size = 200;
    size_t record_size = 300;
    size_t limit = 10 * 1024 * 1024; // 10 MB

    void* memory = allocate_memory(long_size, int_size, record_size, limit);
    if (memory != NULL) {
        // Use the allocated memory
        free_memory(memory);
    }

    return 0;
