#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double value;
    char* string;
    union {
        int metadata_int;
        void* metadata_ptr;
    } metadata;
} entry;

entry* allocate_entries(int num_sets, ...) {
    va_list args;
    va_start(args, num_sets);

    entry* entries = (entry*)malloc(num_sets * sizeof(entry));
    if (!entries) {
        fprintf(stderr, "Failed to allocate memory for %d sets of entries.\n", num_sets);
        return NULL;
    }

    for (int i = 0; i < num_sets; ++i) {
        int num_entries = va_arg(args, int);
        int max_string_length = va_arg(args, int);
        int metadata_type = va_arg(args, int);

        entries[i].string = (char*)malloc((max_string_length + 1) * sizeof(char));
        if (!entries[i].string) {
            fprintf(stderr, "Failed to allocate memory for string buffer in set %d.\n", i);
            // Free previously allocated entries
            for (int j = 0; j < i; ++j) {
                free(entries[j].string);
            }
            free(entries);
            return NULL;
        }

        entries[i].value = ((double)rand() / RAND_MAX) * 100.0 - 50.0; // Random double between -50 and 50

        for (int j = 0; j < max_string_length; ++j) {
            entries[i].string[j] = 'a' + rand() % 26;
        }
        entries[i].string[max_string_length] = '\0';

        if (metadata_type == 1) {
            entries[i].metadata.metadata_int = rand();
        } else if (metadata_type == 2) {
            entries[i].metadata.metadata_ptr = malloc(sizeof(int));
            if (!entries[i].metadata.metadata_ptr) {
                fprintf(stderr, "Failed to allocate memory for metadata pointer in set %d.\n", i);
                // Free previously allocated string and entries
                free(entries[i].string);
                for (int j = 0; j < i; ++j) {
                    free(entries[j].string);
                    if (entries[j].metadata.metadata_ptr) {
                        free(entries[j].metadata.metadata_ptr);
                    }
                }
                free(entries);
                return NULL;
            }
            *(int*)entries[i].metadata.metadata_ptr = rand();
        } else {
            fprintf(stderr, "Invalid metadata type in set %d.\n", i);
            // Free previously allocated string and entries
            free(entries[i].string);
            for (int j = 0; j < i; ++j) {
                free(entries[j].string);
                if (entries[j].metadata.metadata_ptr) {
                    free(entries[j].metadata.metadata_ptr);
                }
            }
            free(entries);
            return NULL;
        }
    }

    va_end(args);
    return entries;
}

void free_entries(entry* entries, int num_sets) {
    for (int i = 0; i < num_sets; ++i) {
        free(entries[i].string);
        if (entries[i].metadata.metadata_ptr) {
            free(entries[i].metadata.metadata_ptr);
        }
    }
    free(entries);
}

int main() {
    srand(time(NULL));

    entry* entries = allocate_entries(2, 3, 10, 1, 4, 5, 2);
    if (entries) {
        for (int i = 0; i < 6; ++i) {
            printf("Entry %d: Value = %.2f, String = %s, Metadata Int = %d\n", i, entries[i].value, entries[i].string, entries[i].metadata.metadata_int);
        }
        free_entries(entries, 2);
    }

    return 0;
}
