#define MAX_KEY_VALUE 100
#define MAX_TAG_LENGTH 50

typedef struct {
    long offset;
    int key;
    // Assuming record structure is defined elsewhere
    char tag[MAX_TAG_LENGTH];
    time_t timestamp;
} Record;

void initialize_data_structure(int max_key_value, const char* directory_name) {
    FILE *log_file = fopen("log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    // Check and set environment variable
    char *env_var = getenv("MY_DIRECTORY");
    if (env_var == NULL) {
        if (mkdir(directory_name, 0755) != 0) {
            perror("Failed to create directory");
            fclose(log_file);
            return;
        }
        setenv("MY_DIRECTORY", directory_name, 1);
    } else {
        strcpy(directory_name, env_var);
    }

    // Log directory creation
    fprintf(log_file, "Directory created: %s\n", directory_name);

    // Allocate memory for records
    Record *records = (Record *)malloc(max_key_value * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        fclose(log_file);
        return;
    }

    // Initialize offsets, keys, records, tags, and timestamps
    srand(time(NULL));
    long offset = 0;
    int key = 1;
    while (key <= max_key_value) {
        records[key - 1].offset = offset++;
        records[key - 1].key = key++;
        // Initialize record with random values
        records[key - 2].timestamp = time(NULL);
        snprintf(records[key - 2].tag, MAX_TAG_LENGTH, "Tag%d", rand() % 100);
    }

    // Log successful allocation and data initialization
    fprintf(log_file, "Records initialized successfully\n");

    // Free allocated memory
    free(records);

    fclose(log_file);
}
