import java.io.*;
import java.util.concurrent.*;

public class Deserializer {

    private static final String LOG_FILE = "deserialization.log";
    private static final List<Class<?>> ALLOWED_CLASSES = Arrays.asList(
        MyClass1.class, MyClass2.class, MyClass3.class
    );

    public static <T> T deserialize(byte[] data, Class<T> clazz) throws RuntimeException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            Object obj = ois.readObject();
            if (!ALLOWED_CLASSES.contains(obj.getClass())) {
                throw new ClassNotFoundException("Deserialized object class is not allowed.");
            }
            return clazz.cast(obj);
        } catch (InvalidClassException | StreamCorruptedException | IOException e) {
            logException(e);
            throw new RuntimeException("Failed to deserialize data: " + e.getMessage(), e);
        } catch (ClassNotFoundException e) {
            logException(e);
            throw new ClassNotFoundException("Deserialized object class not found.");
        }
    }

    private static void logException(Exception e) {
        try (FileWriter writer = new FileWriter(LOG_FILE, true)) {
            writer.write(new Date() + " - " + e.getMessage() + "\n");
        } catch (IOException ex) {
            System.err.println("Failed to log exception: " + ex.getMessage());
        }
    }

    public static <T> T deserializeWithTimeout(byte[] data, Class<T> clazz, long timeout, TimeUnit unit)
            throws TimeoutException, RuntimeException {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<T> future = executor.submit(() -> deserialize(data, clazz));
        try {
            return future.get(timeout, unit);
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException("Deserialization failed: " + e.getMessage(), e);
        }
    }
}
