#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    float value;
} DatabaseEntry;

DatabaseEntry* createDatabaseEntry(float minVal, float maxVal) {
    static int nextId = 1;
    static time_t lastTimestamp = 0;
    DatabaseEntry* entry = (DatabaseEntry*)malloc(sizeof(DatabaseEntry));
    if (!entry) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    entry->id = nextId++;
    entry->timestamp = lastTimestamp + 1; // Monotonically increasing timestamp
    lastTimestamp = entry->timestamp;

    float randomValue;
    do {
        randomValue = minVal + (float)rand() / RAND_MAX * (maxVal - minVal);
    } while (randomValue == entry->value); // Ensure no two consecutive entries have the same value
    entry->value = randomValue;

    return entry;
}

void freeDatabaseEntry(DatabaseEntry* entry) {
    if (entry) {
        free(entry);
    }
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    DatabaseEntry** dbList = NULL;
    int listSize = 0;
    int capacity = 10;

    // Populate the database
    for (int i = 0; i < 50; ++i) {
        if (listSize >= capacity) {
            capacity *= 2;
            dbList = realloc(dbList, capacity * sizeof(DatabaseEntry*));
            if (!dbList) {
                fprintf(stderr, "Memory reallocation failed\n");
                break;
            }
        }
        dbList[listSize++] = createDatabaseEntry(0.0f, 100.0f);
    }

    // Clear the database
    for (int i = 0; i < listSize; ++i) {
        freeDatabaseEntry(dbList[i]);
    }
    free(dbList);

    return 0;
}
