    if (!sensor_data) {
        return NULL;
    }

    sensor_data->readings = malloc(num_sensors * sizeof(SensorReading));
    if (!sensor_data->readings) {
        free(sensor_data);
        return NULL;
    }

    sensor_data->num_readings = num_sensors;

    for (int i = 0; i < num_sensors; i++) {
        sensor_data->readings[i].id = i;
        sensor_data->readings[i].reading = (float)i / num_sensors * 100.0f;
    }

    return sensor_data;
}

void free_sensors(SensorData *sensor_data) {
    if (sensor_data) {
        free(sensor_data->readings);
        free(sensor_data);
    }
}

ConfigData* allocate_config(void *config_data, size_t config_size) {
    if (config_size > MAX_CONFIG_SIZE) {
        return NULL;
    }

    ConfigData *config = malloc(sizeof(ConfigData));
    if (!config) {
        return NULL;
    }

    config->config_data = malloc(config_size);
    if (!config->config_data) {
        free(config);
        return NULL;
    }

    memcpy(config->config_data, config_data, config_size);
    config->config_size = config_size;

    return config;
}

void free_config(ConfigData *config) {
    if (config) {
        free(config->config_data);
        free(config);
    }
}

void report_memory_usage(SensorData *sensor_data, ConfigData *config) {
    size_t total_used = sensor_data->num_readings * sizeof(SensorReading) + config->config_size;
    printf("Total Memory Used: %zu bytes\n", total_used);
    printf("Memory Fragmentation: %f%%\n", ((float)(MAX_MEMORY - total_used) / MAX_MEMORY) * 100.0f);
}

void report_alignment(SensorData *sensor_data, ConfigData *config) {
    size_t alignment = (size_t)sensor_data->readings;
    printf("Sensor Data Alignment: %zu\n", alignment);
    if (alignment % sizeof(float)) {
        printf("Alignment Warning: Sensor data is not aligned to float boundary.\n");
    }
}

void process_mode_real_time(SensorData *sensor_data, ConfigData *config) {
    // Implement real-time processing logic here
    report_memory_usage(sensor_data, config);
    report_alignment(sensor_data, config);
}

void process_mode_batch(SensorData *sensor_data, ConfigData *config) {
    // Implement batch processing logic here
    report_memory_usage(sensor_data, config);
    report_alignment(sensor_data, config);
}

void process_mode_streaming(SensorData *sensor_data, ConfigData *config) {
    // Implement streaming processing logic here
    report_memory_usage(sensor_data, config);
    report_alignment(sensor_data, config);
}
