#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define HASH_TABLE_SIZE 1000

typedef struct {
    char *word;
    int count;
} WordEntry;

WordEntry hashTable[HASH_TABLE_SIZE];
int threadCount = 1;

void initializeHashTable() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        hashTable[i].word = NULL;
        hashTable[i].count = 0;
    }
}

unsigned int hashFunction(const char *str) {
    unsigned int hash = 5381;
    int c;

    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash % HASH_TABLE_SIZE;
}

void insertWord(const char *word) {
    unsigned int index = hashFunction(word);
    WordEntry *entry = &hashTable[index];

    if (entry->word == NULL || strcmp(entry->word, word) != 0) {
        entry->word = strdup(word);
        entry->count = 1;
    } else {
        entry->count++;
    }
}

void* processLines(void *arg) {
    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), stdin)) {
        // Trim leading and trailing whitespace
        line[strcspn(line, "\r\n")] = '\0';
        if (strlen(line) > 0) {
            insertWord(line);
        }
    }
    return NULL;
}

void processAndAnalyzeText() {
    initializeHashTable();

    pthread_t threads[threadCount];
    for (int i = 0; i < threadCount; i++) {
        pthread_create(&threads[i], NULL, processLines, NULL);
    }

    for (int i = 0; i < threadCount; i++) {
        pthread_join(threads[i], NULL);
    }

    // Analyze word frequencies and filter based on threshold
    // ...

    // Free allocated memory
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (hashTable[i].word != NULL) {
            free(hashTable[i].word);
        }
    }
}

int main() {
    printf("Enter text. Type 'END' to finish:\n");
    processAndAnalyzeText();
    return 0;
}
