    int count;
    pthread_mutex_t lock;
} StatisticsModule;

void initialize_statistics_module(StatisticsModule *module, int n) {
    module->count = n;
    module->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!module->pdus) {
        perror("Failed to allocate memory for statistics module");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&module->lock, NULL);

    for (int i = 0; i < n; i++) {
        module->pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        module->pdus[i].RNTI = rand() % 256;
        module->pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
}

void update_statistics(StatisticsModule *module, int connection_id, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&module->lock);
    if (connection_id >= 0 && connection_id < module->count) {
        memcpy(&module->pdus[connection_id], &new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    pthread_mutex_unlock(&module->lock);
}

void free_statistics_module(StatisticsModule *module) {
    pthread_mutex_destroy(&module->lock);
    free(module->pdus);
}

int main() {
    StatisticsModule module;
    initialize_statistics_module(&module, MAX_CONNECTIONS);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T new_data = {12345, 67890, 1};
    update_statistics(&module, 0, new_data);

    free_statistics_module(&module);
    return 0;
