resourceAndPerformanceManager* createResourceAndPerformanceManager(size_t initialCapacity) {
    resourceAndPerformanceManager* manager = (resourceAndPerformanceManager*)malloc(sizeof(resourceAndPerformanceManager));
    if (!manager) return NULL;

    manager->records = (record*)malloc(initialCapacity * sizeof(record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initialCapacity;
    manager->logFile = fopen("memory_usage.log", "w");
    if (!manager->logFile) {
        free(manager->records);
        free(manager);
        return NULL;
    }

    return manager;
}

void destroyResourceAndPerformanceManager(resourceAndPerformanceManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i].offset);
    }
    free(manager->records);
    fclose(manager->logFile);
    free(manager);
}

int initializeRecords(resourceAndPerformanceManager* manager, int minValue, int maxValue) {
    for (size_t i = 0; i < manager->count; ++i) {
        manager->records[i].value = rand() % (maxValue - minValue + 1) + minValue;
        manager->records[i].offset = (long*)malloc(sizeof(long));
        if (!manager->records[i].offset) return -1;
        *manager->records[i].offset = i * sizeof(record);
    }
    return 0;
}

void logMemoryUsage(resourceAndPerformanceManager* manager, size_t currentMemoryUsage) {
