int encryptDecryptString(const char* plaintext, const unsigned char* key, int keyLength, char** ciphertext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (EVP_EncryptUpdate(ctx, (unsigned char*)*ciphertext, &len, (const unsigned char*)plaintext, strlen(plaintext)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int ciphertextLen = len;

    if (EVP_EncryptFinal_ex(ctx, (unsigned char*)(*ciphertext + len), &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertextLen += len;

    (*ciphertext)[ciphertextLen] = '\0';
    EVP_CIPHER_CTX_free(ctx);

    return ciphertextLen;
}

typedef struct {
    int errorCode;
    char* errorMessage;
} resultStruct;

resultStruct resourceAndPerformanceManager(resourceAndPerformanceManager* manager, const char* imagePath, const unsigned char* key, int keyLength) {
    resultStruct result = {0};
    size_t currentMemoryUsage = manager->count * sizeof(record);

    if (currentMemoryUsage > MAX_MEMORY) {
        fprintf(stderr, "Memory usage exceeds limit\n");
        result.errorCode = -1;
        result.errorMessage = "Memory usage exceeds limit";
        return result;
    }

    logMemoryUsage(manager, currentMemoryUsage);

    int width, height, compressionType, orientation;
    if (extractImageMetadata(imagePath, &width, &height, &compressionType, &orientation) != 0) {
        fprintf(stderr, "Failed to extract image metadata\n");
        result.errorCode = -1;
        result.errorMessage = "Failed to extract image metadata";
        return result;
    }

    char* ciphertext;
    if (encryptDecryptString("Hello, World!", key, keyLength, &ciphertext) != 0) {
        fprintf(stderr, "Encryption/Decryption failed\n");
        result.errorCode = -1;
        result.errorMessage = "Encryption/Decryption failed";
        return result;
    }

    printf("Image dimensions: %dx%d\n", width, height);
    printf("Compression type: %d\n", compressionType);
    printf("Orientation: %d\n", orientation);
    printf("Encrypted message: %s\n", ciphertext);

    free(ciphertext);
    return result;
}
