#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE_LENGTH 256

typedef struct WordNode {
    char *word;
    struct WordNode *next;
} WordNode;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* processAndAnalyzeText(int N) {
    NFAPI_CRC_INDICATION_PDU_T *pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduArray) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < N; i++) {
        pduArray[i].RX_UE_INFORMATION_TAG = i + 1;
        pduArray[i].RNTI = i * 2;
        pduArray[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    char line[MAX_LINE_LENGTH];
    WordNode *head = NULL, *tail = NULL;

    while (fgets(line, sizeof(line), stdin)) {
        char *token = strtok(line, " ,.!?\n");
        while (token) {
            WordNode *newNode = (WordNode*)malloc(sizeof(WordNode));
            if (!newNode) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(1);
            }
            newNode->word = strdup(token);
            newNode->next = NULL;

            if (!head) {
                head = tail = newNode;
            } else {
                tail->next = newNode;
                tail = newNode;
            }

            token = strtok(NULL, " ,.!?\n");
        }
    }

    // Process the linked list and perform linguistic analysis
    WordNode *current = head;
    while (current) {
        printf("Word: %s\n", current->word);
        // Perform linguistic analysis here
        free(current->word);
        WordNode *temp = current;
        current = current->next;
        free(temp);
    }

    free(pduArray);

    return NULL;
}

int main() {
    int N;
    printf("Enter the number of elements: ");
    scanf("%d", &N);
    processAndAnalyzeText(N);
    return 0;
}
