    *char_array = (char **)malloc(size * sizeof(char *));
    *struct_array = (CustomData *)malloc(size * sizeof(CustomData));

    if (*double_array == NULL || *char_array == NULL || *struct_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*double_array)[i] = 0.1 * i;

        // Simulate file path generation and validation
        char temp_path[256];
        snprintf(temp_path, sizeof(temp_path), "/path/to/file%d.txt", i);
        FILE *file = fopen(temp_path, "r");
        if (file != NULL) {
            (*char_array)[i] = strdup(temp_path);
            fclose(file);
        } else {
            fprintf(stderr, "Failed to open file: %s\n", temp_path);
            exit(EXIT_FAILURE);
        }

        // Initialize struct with random float and current time
        do {
            (*struct_array)[i].value = (float)rand() / RAND_MAX * 10.0;
        } while (i > 0 && (*struct_array)[i].value == (*struct_array)[i - 1].value);
        snprintf((*struct_array)[i].metadata, sizeof((*struct_array)[i].metadata), "Metadata for file %d", i);
        time(&(*struct_array)[i].last_modified);
    }
}

void free_arrays(double *double_array, char **char_array, CustomData *struct_array, int size) {
    for (int i = 0; i < size; i++) {
        free(char_array[i]);
    }
    free(double_array);
    free(char_array);
    free(struct_array);
}

