    CustomAllocator<long> longAlloc;
    CustomAllocator<int> intAlloc;
    CustomAllocator<Record> recordAlloc;

    std::vector<long, CustomAllocator<long>> offsets(longAlloc);
    std::vector<int, CustomAllocator<int>> keys(intAlloc);
    std::vector<Record, CustomAllocator<Record>> records(recordAlloc);

    // Initialize arrays with random values
    for (size_t i = 0; i < offsets.size(); ++i) {
        offsets[i] = dis(gen);
    }
    for (size_t i = 0; i < keys.size(); ++i) {
        keys[i] = dis(gen);
    }
    for (size_t i = 0; i < records.size(); ++i) {
        records[i].value = dis(gen);
    }

    // Track function calls within the last five minutes
    static std::atomic<int> callCount(0);
    static std::mutex callMutex;
    {
        std::lock_guard<std::mutex> lock(callMutex);
        if (callCount.load() >= 1000) { // Example limit of 1000 calls per minute
            throw std::runtime_error("Too many function calls");
        }
        ++callCount;
    }

    // Log execution details
    static std::mutex logMutex;
    {
        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << "Execution details: "
                  << "Timestamp: " << std::chrono::system_clock::now().time_since_epoch().count() << ", "
                  << "Records created: " << records.size() << ", "
                  << "Random value range: [" << dis.min() << ", " << dis.max() << "]" << std::endl;
