void addTask(TaskManager *manager, DataProcessingTask task) {
    pthread_mutex_lock(&manager->lock);
    if (manager->taskCount >= initialCapacity) {
        // Resize the array
        manager->tasks = realloc(manager->tasks, (manager->taskCount + 1) * sizeof(DataProcessingTask));
        manager->configs = realloc(manager->configs, (manager->taskCount + 1) * sizeof(TaskConfiguration *));
        manager->profiles = realloc(manager->profiles, (manager->taskCount + 1) * sizeof(ProcessingProfile *));
    }
    manager->tasks[manager->taskCount] = task;
    manager->configCount++;
    manager->profileCount++;
    pthread_mutex_unlock(&manager->lock);
}

// Add other functions for managing tasks, configurations, and profiles

void destroyTaskManager(TaskManager *manager) {
    free(manager->tasks);
    for (int i = 0; i < manager->configCount; i++) {
        free(manager->configs[i]);
    }
    for (int i = 0; i < manager->profileCount; i++) {
        free(manager->profiles[i]);
    }
    pthread_mutex_destroy(&manager->lock);
}
