    record->fields = (char**)malloc(field_count * sizeof(char*));
    record->field_count = field_count;
    return record;
}

void freeRecord(Record *record) {
    for (int i = 0; i < record->field_count; i++) {
        free(record->fields[i]);
    }
    free(record->fields);
    free(record);
