    free(data);
}

void processCSVStream(const char *filename, const char delimiter, int max_field_length) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    CSVData *data = createCSVData();
    Record *current_record = NULL;

    // Process each line of the CSV
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        trimWhitespace(buffer);
        if (strlen(buffer) == 0) continue; // Skip empty lines

        int field_count = 1;
        for (int i = 0; i < strlen(buffer); i++) {
            if (buffer[i] == delimiter) field_count++;
        }

        if (data->record_count >= data->capacity) {
            data->capacity *= 2;
            data->records = (Record**)realloc(data->records, data->capacity * sizeof(Record*));
        }

        current_record = createRecord(field_count);
        int field_index = 0;
        char *token = strtok(buffer, &delimiter);
        while (token) {
            if (strlen(token) > max_field_length) {
                fprintf(stderr, "Field too long: %s\n", token);
                freeRecord(current_record);
                break;
            }
            current_record->fields[field_index] = strdup(token);
            trimWhitespace(current_record->fields[field_index]);
            if (isNullCharacter(current_record->fields[field_index])) {
                fprintf(stderr, "Null character found in field: %s\n", current_record->fields[field_index]);
                freeRecord(current_record);
                break;
            }
            token = strtok(NULL, &delimiter);
            field_index++;
        }

        if (field_index == field_count) {
            data->records[data->record_count++] = current_record;
        } else {
            freeRecord(current_record);
        }
    }

    fclose(file);

    // Process and report statistics
    // ...

    // Free allocated memory
    freeCSVData(data);
}
