    for (int i = 0; i < resource_count; i++) {
        if (resources[i].id == id) {
            resources[i].value = new_value;
            printf("Resource %d updated to value %d\n", id, new_value);
            return;
        }
    }
    printf("Resource with ID %d not found\n", id);
}

void remove_resource(int id) {
    for (int i = 0; i < resource_count; i++) {
        if (resources[i].id == id) {
            resources[i] = resources[resource_count - 1];
            resource_count--;
