#include <stdlib.h>
#include <stdbool.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    size_t count;
} CRC_LIST_T;

CRC_LIST_T* crc_list_init() {
    CRC_LIST_T *list = (CRC_LIST_T*)malloc(sizeof(CRC_LIST_T));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    return list;
}

void crc_list_free(CRC_LIST_T *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

bool crc_list_insert(CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (list->count >= 1024) return false;

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return false;

    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->CRCFLAG = (list->count % 2 == 0);
    new_node->next = list->head;

    list->head = new_node;
    list->count++;
    return true;
}

bool crc_list_delete(CRC_LIST_T *list, int RX_UE_INFORMATION_TAG) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;

    while (current) {
        if (current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            if (prev) prev->next = current->next;
            else list->head = current->next;
            free(current);
            list->count--;
            return true;
        }
        prev = current;
        current = current->next;
    }

    return false;
}

void crc_list_traverse(CRC_LIST_T *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        callback(current);
        current = current->next;
    }
}
