#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY 1024 * 1024 // 1 MB
#define MAX_METADATA_SIZE 256
#define MAX_IP_RANGE 10

typedef struct {
    time_t timestamp;
    char source_ip[46]; // IPv6 address can be up to 45 characters long + null terminator
    char destination_ip[46];
    int protocol_type;
    size_t payload_size;
    char metadata[MAX_METADATA_SIZE][MAX_IP_RANGE];
} NetworkLog;

typedef struct {
    NetworkLog *logs;
    size_t log_count;
    size_t allocated_memory;
    pthread_mutex_t mutex;
} LogManager;

int initialize_logs(LogManager *manager, size_t n) {
    pthread_mutex_lock(&manager->mutex);
    if (n * sizeof(NetworkLog) + n * MAX_METADATA_SIZE > MAX_MEMORY) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Memory allocation exceeds maximum allowed
    }

    manager->logs = (NetworkLog *)malloc(n * sizeof(NetworkLog));
    if (!manager->logs) {
        pthread_mutex_unlock(&manager->mutex);
        return -2; // Failed to allocate memory for logs
    }

    manager->log_count = n;
    manager->allocated_memory = n * sizeof(NetworkLog) + n * MAX_METADATA_SIZE;

    time_t current_time = time(NULL);
    struct tm *local_time = localtime(&current_time);

    for (size_t i = 0; i < n; ++i) {
        manager->logs[i].timestamp = mktime(local_time); // Set timestamp to current time
        snprintf(manager->logs[i].source_ip, sizeof(manager->logs[i].source_ip), "192.168.1.%d", (int)(rand() % 254 + 1));
        snprintf(manager->logs[i].destination_ip, sizeof(manager->logs[i].destination_ip), "10.0.0.%d", (int)(rand() % 254 + 1));
        manager->logs[i].protocol_type = rand() % 6; // Random protocol type
        manager->logs[i].payload_size = rand() % 1024; // Random payload size

        for (size_t j = 0; j < MAX_IP_RANGE; ++j) {
            snprintf(manager->logs[i].metadata[j], sizeof(manager->logs[i].metadata[j]), "tag%d", (int)(rand() % 10));
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void free_logs(LogManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->logs) {
        free(manager->logs);
        manager->logs = NULL;
        manager->log_count = 0;
        manager->allocated_memory = 0;
    }
    pthread_mutex_unlock(&manager->mutex);
}

int main() {
    LogManager manager;
    pthread_mutex_init(&manager.mutex, NULL);

    int result = initialize_logs(&manager, 10);
    if (result == 0) {
        printf("Logs initialized successfully.\n");
    } else {
        printf("Failed to initialize logs. Error code: %d\n", result);
    }

    free_logs(&manager);
    pthread_mutex_destroy(&manager.mutex);

    return 0;
}
