#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2
#define BUFFER_SIZE 10

typedef struct {
    long value;
    int key;
    char buffer[BUFFER_SIZE];
} record;

record* create_records(int *size, int threshold) {
    record *records = (record *)malloc(INITIAL_CAPACITY * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    *size = INITIAL_CAPACITY;
    srand(time(NULL));
    for (int i = 0; i < *size; i++) {
        records[i].value = rand();
        records[i].key = rand() % threshold;
        snprintf(records[i].buffer, BUFFER_SIZE, "Record%d", i);
    }
    return records;
}

void resize_records(record **records, int *size, int new_capacity) {
    record *new_records = (record *)realloc(*records, new_capacity * sizeof(record));
    if (!new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    *records = new_records;
    *size = new_capacity;
}

void add_record(record **records, int *size, int threshold) {
    if (*size >= threshold) {
        resize_records(records, size, *size * GROWTH_FACTOR);
    }
    record new_record;
    new_record.value = rand();
