                // Initialize data for type 1
                break;
            case 2:
                // Initialize data for type 2
                break;
            // Add cases for other types
            default:
                fprintf(stderr, "Unknown record type.\n");
                return;
        }
    }

    // Free allocated memory
    for (int i = 0; i < num_records; i++) {
        free(records[i].data);
    }
    free(records);

    for (int i = 0; i < num_tasks; i++) {
        free(tasks[i].data);
        free(results[i]);
    }
    free(tasks);
    free(results);
}
