#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_CONTEXTS 1024
#define MAX_MEASUREMENT_REPORTS 64

typedef struct {
    int UE_ID;
    pthread_mutex_t mutex;
} LTE_UE_Context;

typedef struct {
    time_t timestamp;
    int signal_strength;
    int cell_id;
} Measurement_Report;

typedef struct {
    Measurement_Report reports[MAX_MEASUREMENT_REPORTS];
    int count;
    pthread_mutex_t mutex;
} Measurement_List;

LTE_UE_Context UE_Contexs[MAX_UE_CONTEXTS];
Measurement_List measurement_lists[MAX_UE_CONTEXTS];

void initialize_system() {
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        UE_Contexs[i].UE_ID = -1;
        pthread_mutex_init(&UE_Contexs[i].mutex, NULL);
        measurement_lists[i].count = 0;
        pthread_mutex_init(&measurement_lists[i].mutex, NULL);
    }
}

void add_measurement_report(int UE_ID, Measurement_Report report) {
    int index = -1;
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (UE_Contexs[i].UE_ID == UE_ID) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        printf("Error: UE_ID not found\n");
        return;
    }

    pthread_mutex_lock(&measurement_lists[index].mutex);
    if (measurement_lists[index].count < MAX_MEASUREMENT_REPORTS) {
        measurement_lists[index].reports[measurement_lists[index].count++] = report;
    } else {
        printf("Error: Measurement list is full\n");
    }
    pthread_mutex_unlock(&measurement_lists[index].mutex);
}

Measurement_Report get_latest_measurement(int UE_ID) {
    int index = -1;
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (UE_Contexs[i].UE_ID == UE_ID) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        printf("Error: UE_ID not found\n");
        Measurement_Report empty_report = {0};
        return empty_report;
    }

    pthread_mutex_lock(&measurement_lists[index].mutex);
    if (measurement_lists[index].count > 0) {
        Measurement_Report latest_report = measurement_lists[index].reports[measurement_lists[index].count - 1];
        pthread_mutex_unlock(&measurement_lists[index].mutex);
        return latest_report;
    } else {
        pthread_mutex_unlock(&measurement_lists[index].mutex);
        printf("Error: No measurements available\n");
        Measurement_Report empty_report = {0};
        return empty_report;
    }
}

void* network_performance_monitor(void* arg) {
    // Simulate periodic updates and validation
    while (1) {
        for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
            if (UE_Contexs[i].UE_ID != -1) {
                Measurement_Report report;
                report.timestamp = time(NULL);
                report.signal_strength = rand() % 100;
                report.cell_id = rand() % 256;

                add_measurement_report(UE_Contexs[i].UE_ID, report);
            }
        }
        sleep(1); // Simulate periodicity
    }
}

int main() {
    initialize_system();

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, network_performance_monitor, NULL);

    // Example usage
    int UE_ID = 12345;
    Measurement_Report report;
    report.timestamp = time(NULL);
    report.signal_strength = 90;
    report.cell_id = 1;

    add_measurement_report(UE_ID, report);

    Measurement_Report latest_report = get_latest_measurement(UE_ID);
    printf("Latest measurement for UE_ID %d: Timestamp=%ld, Signal Strength=%d, Cell ID=%d\n",
           UE_ID, latest_report.timestamp, latest_report.signal_strength, latest_report.cell_id);

    pthread_join(monitor_thread, NULL);

    return 0;
}
