#include <string.h>
#include <pthread.h>
#include <unistd.h>

typedef struct {
    char* str;
    int id;
    double value;
} item;

typedef struct {
    item** items;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} dynamic_list;

dynamic_list* create_dynamic_list(size_t initial_capacity) {
    dynamic_list* list = (dynamic_list*)malloc(sizeof(dynamic_list));
    list->items = (item**)calloc(initial_capacity, sizeof(item*));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void resize_dynamic_list(dynamic_list* list) {
    size_t new_capacity = list->capacity * 2;
    item** new_items = (item**)realloc(list->items, new_capacity * sizeof(item*));
    if (new_items == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->items = new_items;
    list->capacity = new_capacity;
}

void add_item(dynamic_list* list, char* str, int id, double value) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        resize_dynamic_list(list);
    }
    item* new_item = (item*)malloc(sizeof(item));
    new_item->str = strdup(str);
    new_item->id = id;
    new_item->value = value;
    list->items[list->size++] = new_item;
    pthread_mutex_unlock(&list->lock);
}

void free_dynamic_list(dynamic_list* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->items[i]->str);
        free(list->items[i]);
    }
    free(list->items);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
