#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct DataPacket {
    time_t timestamp;
    int source_id;
    int destination_id;
    size_t payload_size;
    unsigned char *payload;
} DataPacket;

typedef struct PacketList {
    DataPacket *packet;
    struct PacketList *next;
} PacketList;

typedef struct {
    PacketList *head;
    pthread_mutex_t lock;
    time_t last_prune_time;
    time_t prune_window;
} DynamicPacketManager;

DynamicPacketManager *create_packet_manager(time_t prune_window) {
    DynamicPacketManager *manager = (DynamicPacketManager *)malloc(sizeof(DynamicPacketManager));
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->last_prune_time = time(NULL);
    manager->prune_window = prune_window;
    return manager;
}

void destroy_packet_manager(DynamicPacketManager *manager) {
    PacketList *current = manager->head;
    while (current != NULL) {
        PacketList *next = current->next;
        free(current->packet->payload);
        free(current->packet);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void insert_packet(DynamicPacketManager *manager, DataPacket *packet) {
    pthread_mutex_lock(&manager->lock);
    PacketList *new_node = (PacketList *)malloc(sizeof(PacketList));
    new_node->packet = packet;
    new_node->next = manager->head;
    manager->head = new_node;
    pthread_mutex_unlock(&manager->lock);
}

void delete_packet(DynamicPacketManager *manager, DataPacket *packet) {
    pthread_mutex_lock(&manager->lock);
    PacketList *current = manager->head;
    PacketList *prev = NULL;
    while (current != NULL) {
        if (current->packet == packet) {
            if (prev == NULL) {
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->packet->payload);
            free(current->packet);
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void prune_packets(DynamicPacketManager *manager) {
    time_t now = time(NULL);
    if (now - manager->last_prune_time >= manager->prune_window) {
        pthread_mutex_lock(&manager->lock);
        PacketList *current = manager->head;
        PacketList *prev = NULL;
        while (current != NULL) {
            if (now - current->packet->timestamp > manager->prune_window) {
                if (prev == NULL) {
                    manager->head = current->next;
                } else {
                    prev->next = current->next;
                }
                free(current->packet->payload);
                free(current->packet);
                PacketList *temp = current;
                current = current->next;
                free(temp);
            } else {
                prev = current;
                current = current->next;
            }
        }
        manager->last_prune_time = now;
        pthread_mutex_unlock(&manager->lock);
    }
}

void generate_random_payload(DataPacket *packet) {
    packet->payload = (unsigned char *)malloc(packet->payload_size);
    for (size_t i = 0; i < packet->payload_size; i++) {
        packet->payload[i] = rand() % 256;
    }
}
