#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct ConfigNode {
    char *key;
    int value;
    time_t last_modified;
    struct ConfigNode *parent;
    struct ConfigNode **children;
    size_t num_children;
    pthread_mutex_t lock;
} ConfigNode;

ConfigNode* create_config_node(const char *key, int value) {
    ConfigNode *node = (ConfigNode*)malloc(sizeof(ConfigNode));
    node->key = strdup(key);
    node->value = value;
    node->last_modified = time(NULL);
    node->parent = NULL;
    node->children = NULL;
    node->num_children = 0;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

void add_child(ConfigNode *parent, ConfigNode *child) {
    parent->children = realloc(parent->children, (parent->num_children + 1) * sizeof(ConfigNode*));
    parent->children[parent->num_children++] = child;
    child->parent = parent;
}

int get_config_value(ConfigNode *node, const char *key) {
    pthread_mutex_lock(&node->lock);
    if (strcmp(node->key, key) == 0) {
        int value = node->value;
        pthread_mutex_unlock(&node->lock);
        return value;
    }
    for (size_t i = 0; i < node->num_children; ++i) {
        int result = get_config_value(node->children[i], key);
        if (result != -1) {
            pthread_mutex_unlock(&node->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&node->lock);
    return -1;
}

void update_config_value(ConfigNode *node, const char *key, int value) {
    pthread_mutex_lock(&node->lock);
    if (strcmp(node->key, key) == 0) {
        node->value = value;
        node->last_modified = time(NULL);
        pthread_mutex_unlock(&node->lock);
        return;
    }
    for (size_t i = 0; i < node->num_children; ++i) {
        update_config_value(node->children[i], key, value);
    }
    pthread_mutex_unlock(&node->lock);
}

void destroy_config_node(ConfigNode *node) {
    pthread_mutex_lock(&node->lock);
    for (size_t i = 0; i < node->num_children; ++i) {
        destroy_config_node(node->children[i]);
    }
    free(node->key);
    free(node->children);
    pthread_mutex_unlock(&node->lock);
    pthread_mutex_destroy(&node->lock);
    free(node);
}
