LTE_ENB_RRC_CONNECTION_RECONFIGURATION_COMPLETE* messages[MAX_MESSAGES];
int message_count = 0;

void initialize_messages() {
    srand(time(NULL));
    for (int i = 0; i < MAX_MESSAGES; i++) {
        messages[i] = malloc(sizeof(LTE_ENB_RRC_CONNECTION_RECONFIGURATION_COMPLETE));
        if (!messages[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        messages[i]->rsrp_threshold = rand() % 30 + -110; // Random RSRP between -110 and -80
        messages[i]->ssb_index = rand() % 64; // Random SSB index between 0 and 63
        char config_id[20];
        sprintf(config_id, "UE%d", i);
        messages[i]->ue_config_id = strdup(config_id);
    }
    message_count = MAX_MESSAGES;
}

void serialize_messages(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fwrite(messages, sizeof(LTE_ENB_RRC_CONNECTION_RECONFIGURATION_COMPLETE), message_count, file);
    fclose(file);
}

void deserialize_messages(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }
    fread(messages, sizeof(LTE_ENB_RRC_CONNECTION_RECONFIGURATION_COMPLETE), message_count, file);
    fclose(file);
}

void free_messages() {
    for (int i = 0; i < message_count; i++) {
        free(messages[i]->ue_config_id);
        free(messages[i]);
    }
}

int main() {
    initialize_messages();
    serialize_messages("rrc_messages.bin");
    deserialize_messages("rrc_messages.bin");
    free_messages();
    return 0;
}
