#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_IDENTIFIER_LENGTH 256
#define MAX_LIST_SIZE 1000

typedef struct DataNode {
    char identifier[MAX_IDENTIFIER_LENGTH];
    int frequency;
    struct DataNode* prev;
    struct DataNode* next;
} DataNode;

typedef struct DoublyLinkedList {
    DataNode* head;
    DataNode* tail;
    size_t size;
    size_t max_size;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* createList(size_t max_size) {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void freeList(DoublyLinkedList* list) {
    DataNode* current = list->head;
    while (current) {
        DataNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insertOrUpdate(DoublyLinkedList* list, const char* identifier) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    DataNode* current = list->head;
    while (current) {
        if (strcmp(current->identifier, identifier) == 0) {
            current->frequency++;
            pthread_mutex_unlock(&list->lock);
            return 0; // Update successful
        }
        current = current->next;
    }
    DataNode* newNode = (DataNode*)malloc(sizeof(DataNode));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }
    strncpy(newNode->identifier, identifier, MAX_IDENTIFIER_LENGTH);
    newNode->frequency = 1;
    newNode->prev = list->tail;
    newNode->next = NULL;
    if (list->tail) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0; // Insert successful
}

void printTotalFrequency(DoublyLinkedList* list) {
    int total = 0;
    DataNode* current = list->head;
    while (current) {
        total += current->frequency;
        current = current->next;
    }
    printf("Total frequency: %d\n", total);
}

int processAndSummarizeData() {
    DoublyLinkedList* list = createList(MAX_LIST_SIZE);
    if (!list) return -1; // Memory allocation failed

    char line[MAX_IDENTIFIER_LENGTH];
    while (fgets(line, sizeof(line), stdin)) {
        char* identifier = strtok(line, " \t\n");
        if (identifier && strlen(identifier) < MAX_IDENTIFIER_LENGTH) {
            insertOrUpdate(list, identifier);
        }
    }

    printTotalFrequency(list);

    freeList(list);
    return 0;
}
