typedef struct {
    char tag[32];
    int id;
    char payload[MAX_PAYLOAD_SIZE];
} Message;

Message* initialize_messages(int N, size_t *total_memory_used) {
    // Calculate the maximum allowed memory usage
    size_t max_allowed_memory = (size_t)(SYSTEM_RAM_LIMIT * 1024 * 1024 * 1024); // Assuming 1GB per 100% RAM

    // Calculate the required memory for N messages
    size_t required_memory = N * sizeof(Message);

    // Check if the required memory exceeds the allowed limit
    if (required_memory > max_allowed_memory) {
        fprintf(stderr, "Error: Required memory exceeds system RAM limit.\n");
        return NULL;
    }

    // Allocate memory for the message list
    Message *messages = (Message *)malloc(required_memory);
    if (!messages) {
        perror("Failed to allocate memory for messages.");
        return NULL;
    }

    // Initialize each message with a unique ID and a default payload size
    for (int i = 0; i < N; i++) {
        snprintf(messages[i].tag, sizeof(messages[i].tag), "MSG_%d", i);
        messages[i].id = i;
        memset(messages[i].payload, 'A', MAX_PAYLOAD_SIZE - 1); // Example payload
        messages[i].payload[MAX_PAYLOAD_SIZE - 1] = '\0';
    }

    *total_memory_used = required_memory;

    return messages;
}

void free_messages(Message *messages) {
    if (messages) {
        free(messages);
    }
}

int main() {
    int N = 1000000; // Example number of messages
    size_t total_memory_used;

    Message *messages = initialize_messages(N, &total_memory_used);
    if (messages) {
        printf("Successfully initialized %d messages using %zu bytes of memory.\n", N, total_memory_used);

        // Perform operations with the messages...

        free_messages(messages);
    }

    return 0;
}
