### JavaScript Module Implementation

```javascript
class JSModule {
    constructor(basePath) {
        this.basePath = basePath;
        this.modules = {};
    }

    loadModule(moduleName, callback) {
        const filePath = `${this.basePath}/${moduleName}.js`;
        fetch(filePath)
            .then(response => response.text())
            .then(scriptText => {
                try {
                    eval(scriptText);
                    if (callback) {
                        callback(null, this.modules[moduleName]);
                    }
                } catch (error) {
                    if (callback) {
                        callback(error);
                    }
                }
            })
            .catch(error => {
                if (callback) {
                    callback(error);
                }
            });
    }

    loadModules(moduleNames, callback) {
        const results = {};
        let loadedCount = 0;

        moduleNames.forEach((moduleName, index) => {
            this.loadModule(moduleName, (error, module) => {
                if (error) {
                    console.error(`Failed to load module ${moduleName}:`, error);
                } else {
                    results[moduleName] = module;
                }
                loadedCount++;
                if (loadedCount === moduleNames.length && callback) {
                    callback(null, results);
                }
            });
        });
    }
}

// Usage example
const jsModule = new JSModule('/path/to/modules');
jsModule.loadModules(['module1', 'module2'], (error, modules) => {
    if (error) {
        console.error('Failed to load modules:', error);
    } else {
        console.log('Loaded modules:', modules);
    }
});
```

