#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
} record;

int* pre_init_offsets(int num_records) {
    // Pre-initialize offsets array with a pool of values
    static int offsets[1000];
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % 1000;
    }
    return offsets;
}

void initialize_records(record **records, int *offsets, int *keys, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        records[i]->value = rand() % 1000;
        records[i]->offset = &offsets[i];
    }
}

void allocate_and_initialize_keys(int **keys, int range_start, int range_end, int num_records) {
    *keys = (int *)malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys array.\n");
        exit(EXIT_FAILURE);
    }
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        int key;
        do {
            key = rand() % (range_end - range_start + 1) + range_start;
        } while (is_key_used(*keys, i, key));
        (*keys)[i] = key;
    }
}

int is_key_used(int *keys, int index, int key) {
    for (int i = 0; i < index; ++i) {
        if (keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

void free_memory(record **records, int *offsets, int *keys, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
}

record** create_record_collection(int num_records, int range_start, int range_end) {
    record **records = (record **)malloc(num_records * sizeof(record *));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed for records array.\n");
        exit(EXIT_FAILURE);
    }

    int *offsets = pre_init_offsets(num_records);

    int *keys;
    allocate_and_initialize_keys(&keys, range_start, range_end, num_records);

    for (int i = 0; i < num_records; ++i) {
        records[i] = (record *)malloc(sizeof(record));
        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record %d.\n", i);
            free_memory(records, offsets, keys, i);
            exit(EXIT_FAILURE);
        }
    }

    initialize_records(records, offsets, keys, num_records);

    free(keys);

    return records;
}

int main() {
    int num_records = 1000;
    int range_start = 0;
    int range_end = 999;

    record **records = create_record_collection(num_records, range_start, range_end);

    // Use the records...

    free_memory(records, pre_init_offsets(num_records), NULL, num_records);

    return 0;
}
