void initialize_metrics(SystemMetric *metrics, int num_metrics) {
    srand(time(NULL));
    for (int i = 0; i < num_metrics; i++) {
        // Initialize RX_UE_INFORMATION_TAG and RNTI
        snprintf(metrics[i].rx_ue_info_tag, sizeof(metrics[i].rx_ue_info_tag), "RX_UE_%d", i);
        metrics[i].rnti = rand() % MAX_ID;

