        metrics[i].log_value = exp(log(0.1) + i * (log(1000.0) - log(0.1)) / num_metrics);

        // Generate unique unsigned short IDs
        do {
            metrics[i].unique_id = rand() % MAX_ID;
        } while (i > 0 && metrics[i].unique_id == metrics[i-1].unique_id);

        // Fill each data structure with a random string of varying lengths
        int str_len = rand() % 95 + 1; // Random length between 1 and 95
        for (int j = 0; j < str_len; j++) {
