        if (weight < 80) {
            metrics[i].status = STATE_OK;
        } else if (weight < 95) {
            metrics[i].status = STATE_WARNING;
        } else {
            metrics[i].status = STATE_ERROR;
        }

        // Represent the current system time in seconds since the epoch with a random offset
        metrics[i].adjusted_time = time(NULL) + rand() % 201 - 100; // Offset between -100 and 100 seconds
    }
}

