    void* extra_data;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t capacity;
    size_t size;
    size_t max_memory;
    size_t max_extra_data_size;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_POOL_T;

NFAPI_CRC_INDICATION_POOL_T* create_pool(size_t initial_capacity, size_t max_memory, size_t max_extra_data_size) {
    NFAPI_CRC_INDICATION_POOL_T* pool = (NFAPI_CRC_INDICATION_POOL_T*)malloc(sizeof(NFAPI_CRC_INDICATION_POOL_T));
    if (!pool) return NULL;

    pool->pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pdus) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->size = 0;
    pool->max_memory = max_memory;
    pool->max_extra_data_size = max_extra_data_size;
    pthread_mutex_init(&pool->mutex, NULL);

    return pool;
}

void destroy_pool(NFAPI_CRC_INDICATION_POOL_T* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        free(pool->pdus[i].extra_data);
    }
    free(pool->pdus);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

int add_pdu(NFAPI_CRC_INDICATION_POOL_T* pool, RX_UE_INFORMATION_TAG ue_info, RNTI rnti, int crc_flag) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->size >= pool->capacity || pool->size * sizeof(NFAPI_CRC_INDICATION_PDU_T) + pool->size * pool->max_extra_data_size > pool->max_memory) {
        size_t new_capacity = pool->capacity ? pool->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T* new_pdus = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            pthread_mutex_unlock(&pool->mutex);
            return -1; // Memory allocation failed
        }
        pool->pdus = new_pdus;
        pool->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &pool->pdus[pool->size++];
    pdu->ue_info = ue_info;
    pdu->rnti = rnti;
    pdu->crc_indication.crcflag = crc_flag;

    if (pool->max_extra_data_size > 0) {
        pdu->extra_data = malloc(pool->max_extra_data_size);
        if (!pdu->extra_data) {
            pool->size--; // Revert size change on failure
            pthread_mutex_unlock(&pool->mutex);
            return -1; // Memory allocation failed
        }
    } else {
        pdu->extra_data = NULL;
    }

    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

// Additional functions for updating max_memory, max_extra_data_size, logging, monitoring, and garbage collection can be implemented here.
