record* create_record_pool(int n, int max_records) {
    if (n > max_records) {
        fprintf(stderr, "Error: Number of records exceeds maximum allowed.\n");
        return NULL;
    }

    record* pool = malloc(n * sizeof(record));
    if (!pool) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        pool[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        pool[i].offset = malloc(sizeof(long));
        if (!pool[i].offset) {
            fprintf(stderr, "Error: Memory allocation failed for offset.\n");
            free(pool);
            return NULL;
        }
        *pool[i].offset = i; // Assign contiguous memory blocks
        snprintf(pool[i].metadata, sizeof(pool[i].metadata), "record_%d", pool[i].key);
        extra_info* info = malloc(sizeof(extra_info));
        if (!info) {
            fprintf(stderr, "Error: Memory allocation failed for extra_info.\n");
            free(pool[i].offset);
            free(pool);
            return NULL;
        }
        info->timestamp = time(NULL);
        info->flags = 0; // Default flags
        pool[i].extra_info = info;
    }

    return pool;
}

