#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_METADATA_SIZE 1024

typedef struct {
    long sequence_number;
    int tag;
    struct message msg;
    void* extra_metadata;
    atomic_bool is_high_priority;
} Record;

typedef struct {
    Record* records;
    size_t n;
    size_t head;
    size_t tail;
    atomic_size_t count;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} RingBuffer;

typedef struct {
    int priority_level;
    long* offset;
    int tag;
    void* extra_metadata;
    atomic_bool is_high_priority;
} Message;

RingBuffer* create_ring_buffer(size_t n) {
    RingBuffer* rb = (RingBuffer*)malloc(sizeof(RingBuffer));
    rb->records = (Record*)malloc(n * sizeof(Record));
    rb->n = n;
    rb->head = 0;
    rb->tail = 0;
    atomic_init(&rb->count, 0);
    pthread_mutex_init(&rb->lock, NULL);
    pthread_cond_init(&rb->not_full, NULL);
    pthread_cond_init(&rb->not_empty, NULL);
    return rb;
}

void destroy_ring_buffer(RingBuffer* rb) {
    free(rb->records);
    pthread_mutex_destroy(&rb->lock);
    pthread_cond_destroy(&rb->not_full);
    pthread_cond_destroy(&rb->not_empty);
    free(rb);
}

int enqueue_message(RingBuffer* rb, Message msg) {
    pthread_mutex_lock(&rb->lock);
    while (atomic_load(&rb->count) == rb->n) {
        pthread_cond_wait(&rb->not_full, &rb->lock);
    }
    Record* record = &rb->records[rb->tail];
    record->msg = msg;
    atomic_store(&record->is_high_priority, msg.is_high_priority);
    rb->tail = (rb->tail + 1) % rb->n;
    atomic_fetch_add(&rb->count, 1);
    pthread_cond_signal(&rb->not_empty);
    pthread_mutex_unlock(&rb->lock);
    return 0;
}

int dequeue_message(RingBuffer* rb, Message* msg) {
    pthread_mutex_lock(&rb->lock);
    while (atomic_load(&rb->count) == 0) {
        pthread_cond_wait(&rb->not_empty, &rb->lock);
    }
    Record* record = &rb->records[rb->head];
    *msg = record->msg;
    atomic_store(&record->is_high_priority, record->is_high_priority);
    rb->head = (rb->head + 1) % rb->n;
    atomic_fetch_sub(&rb->count, 1);
    pthread_cond_signal(&rb->not_full);
    pthread_mutex_unlock(&rb->lock);
    return 0;
}

// Additional functions for logging, monitoring, and message processing can be implemented here.
