#include <openssl/evp.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MAX_EXTRA_DATA_SIZE 1024

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char *extra_data;
    size_t extra_data_size;
} CipherInstance;

int create_cipher_instance(const char *cipher_name, int mode, CipherInstance **instance) {
    if (sizeof(CipherInstance) + MAX_EXTRA_DATA_SIZE > MAX_MEMORY) {
        return -1; // Memory limit exceeded
    }

    *instance = malloc(sizeof(CipherInstance));
    if (!*instance) {
        return -2; // Memory allocation failed
    }

    (*instance)->ctx = EVP_CIPHER_CTX_new();
    if (!(*instance)->ctx) {
        free(*instance);
        return -3; // EVP_CIPHER_CTX creation failed
    }

    if (EVP_EncryptInit_ex((*instance)->ctx, EVP_get_cipherbyname(cipher_name), NULL, NULL, NULL) != 1) {
        EVP_CIPHER_CTX_free((*instance)->ctx);
        free(*instance);
        return -4; // Cipher initialization failed
    }

    (*instance)->extra_data = malloc(MAX_EXTRA_DATA_SIZE);
    if (!(*instance)->extra_data) {
        EVP_CIPHER_CTX_free((*instance)->ctx);
        free(*instance);
        return -5; // Extra data allocation failed
    }
    (*instance)->extra_data_size = 0;

    return 0; // Success
}

void destroy_cipher_instance(CipherInstance *instance) {
    if (instance->ctx) {
        EVP_CIPHER_CTX_free(instance->ctx);
    }
    if (instance->extra_data) {
        free(instance->extra_data);
    }
    free(instance);
}
