    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DCIPDUManager;

DCIPDUManager* create_manager(size_t initial_capacity) {
    DCIPDUManager *manager = (DCIPDUManager*)malloc(sizeof(DCIPDUManager));
    if (!manager) return NULL;

    manager->pdus = (DCIPDU*)calloc(initial_capacity, sizeof(DCIPDU));
    if (!manager->pdus) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_manager(DCIPDUManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->pdus);
        free(manager);
    }
}

int add_pdu(DCIPDUManager *manager, DCIPDU pdu) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        DCIPDU *new_pdus = (DCIPDU*)realloc(manager->pdus, new_capacity * sizeof(DCIPDU));
        if (!new_pdus) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Allocation failed
        }

        manager->pdus = new_pdus;
        manager->capacity = new_capacity;
    }

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->pdus[i].c_rnti == pdu.c_rnti) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Duplicate C-RNTI
        }
    }

    manager->pdus[manager->size++] = pdu;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Additional functions for synchronization, error handling, and logging levels can be added here.
