#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int value;
    long* offset;
    int key;
} Record;

typedef struct {
    Record* records;
    size_t allocated_size;
    size_t used_size;
    size_t max_memory;
} MemoryPool;

MemoryPool pool = {NULL, 0, 0, MAX_MEMORY};

void init_pool(size_t initial_size) {
    if (initial_size > pool.max_memory) {
        fprintf(stderr, "Initial size exceeds maximum memory limit.\n");
        exit(EXIT_FAILURE);
    }
    pool.records = malloc(initial_size * sizeof(Record));
    if (!pool.records) {
        fprintf(stderr, "Failed to allocate memory for the pool.\n");
        exit(EXIT_FAILURE);
    }
    pool.allocated_size = initial_size;
}

void resize_pool(size_t new_size) {
    if (new_size > pool.max_memory) {
        fprintf(stderr, "New size exceeds maximum memory limit.\n");
        return;
    }
    Record* new_records = realloc(pool.records, new_size * sizeof(Record));
    if (!new_records) {
        fprintf(stderr, "Failed to resize memory pool.\n");
        return;
    }
    pool.records = new_records;
    pool.allocated_size = new_size;
}

void init_record(size_t index) {
    pool.records[index].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    pool.records[index].offset = &pool.records[index].value;
    pool.records[index].key = index;
}

void put_record(int key, int new_value) {
    for (size_t i = 0; i < pool.used_size; ++i) {
        if (pool.records[i].key == key) {
            pool.records[i].value = new_value;
            return;
        }
    }
    fprintf(stderr, "Key not found.\n");
}

void delete_record(int key) {
    for (size_t i = 0; i < pool.used_size; ++i) {
        if (pool.records[i].key == key) {
            pool.records[i] = pool.records[--pool.used_size];
            return;
        }
    }
    fprintf(stderr, "Key not found.\n");
}

int main() {
    srand(time(NULL));
    init_pool(10);
    for (size_t i = 0; i < pool.allocated_size; ++i) {
        init_record(i);
    }
    put_record(5, 99);
    delete_record(3);
    return 0;
}
