            break;
        }
        buffer[strcspn(buffer, "\n")] = '\0'; // Remove newline character
        lines[lineCount] = strdup(buffer);
        if (lines[lineCount] == NULL) {
            fprintf(stderr, "Memory allocation failed for line\n");
            free(pdus);
            for (int i = 0; i < lineCount; i++) {
                free(lines[i]);
            }
            free(lines);
            return;
        }
        lineCount++;
    }

    // Identify and print the longest word in the auxiliary array
    int maxLength = 0;
    char* longestWord = NULL;
    for (int i = 0; i < lineCount; i++) {
        char* token = strtok(lines[i], " ");
        while (token != NULL) {
            if (strlen(token) > maxLength) {
                maxLength = strlen(token);
                longestWord = strdup(token);
            }
            token = strtok(NULL, " ");
        }
    }
    printf("Longest word: %s\n", longestWord);

    // Dynamically modify the file extension of the original filename
    char newFileName[MAX_FILE_NAME_LENGTH];
    snprintf(newFileName, sizeof(newFileName), "%.*s%d.txt", (int)strlen(configFilePath) - 4, configFilePath, maxLength);
    printf("New file name: %s\n", newFileName);

    // Free dynamically allocated memory
    free(pdus);
    for (int i = 0; i < lineCount; i++) {
        free(lines[i]);
    }
    free(lines);
    if (longestWord != NULL) {
        free(longestWord);
    }
}
