Item* create_item(Item* items, int* item_count) {
    if (*item_count >= INT_MAX - 1) return NULL; // Prevent overflow
    Item* new_item = (Item*)realloc(items, (*item_count + 1) * sizeof(Item));
    if (!new_item) return NULL; // Handle out-of-memory condition

    new_item[*item_count].id = *item_count + 1;
    new_item[*item_count].timestamp = time(NULL);
    new_item[*item_count].tags = (char**)malloc(BATCH_SIZE * sizeof(char*));
    if (!new_item[*item_count].tags) {
        free(new_item);
        return NULL; // Handle out-of-memory condition
    }
    new_item[*item_count].tag_count = 0;

    (*item_count)++;
    return &new_item[*item_count - 1];
}

void fetch_tags(char** tags, int* tag_count) {
    // Simulate fetching tags from an external data source
    *tag_count = rand() % MAX_TAGS + 1;
    for (int i = 0; i < *tag_count; i++) {
        tags[i] = (char*)malloc(50 * sizeof(char));
