    for (int i = 0; i < item_count; i++) {
        for (int j = 0; j < items[i].tag_count; j++) {
            free(items[i].tags[j]);
        }
        free(items[i].tags);
    }
    free(items);
}

int main() {
    srand(time(NULL));
    Item* items = NULL;
    int item_count = 0;

    char** tags = (char**)malloc(MAX_TAGS * sizeof(char*));
    if (!tags) return -1; // Handle out-of-memory condition

    fetch_tags(tags, &item_count);

    for (int i = 0; i < BATCH_SIZE; i++) {
        Item* new_item = create_item(items, &item_count);
        if (!new_item) break; // Handle out-of-memory condition
        select_tags(new_item, tags, item_count);
    }

    free_items(items, item_count);
    for (int i = 0; i < item_count; i++) {
        free(tags[i]);
    }
    free(tags);

    return 0;
}
