#define MAX_CAPACITY 1024

typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY_T;

void init_crc_array(NFAPI_CRC_ARRAY_T *crc_array) {
    crc_array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_array->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    crc_array->size = 0;
    crc_array->capacity = MAX_CAPACITY;
    pthread_mutex_init(&crc_array->mutex, NULL);
}

void add_crc_to_array(NFAPI_CRC_ARRAY_T *crc_array, int CRCFLAG) {
    pthread_mutex_lock(&crc_array->mutex);
    if (crc_array->size >= crc_array->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(crc_array->array, crc_array->capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        crc_array->array = new_array;
        crc_array->capacity *= 2;
    }
    crc_array->array[crc_array->size].CRCFLAG = CRCFLAG;
    crc_array->size++;
    pthread_mutex_unlock(&crc_array->mutex);
}

NFAPI_CRC_INDICATION_PDU_T *get_crc_from_array(NFAPI_CRC_ARRAY_T *crc_array, size_t index) {
    if (index >= crc_array->size) {
        fprintf(stderr, "Out-of-bounds access\n");
        return NULL;
    }
    pthread_mutex_lock(&crc_array->mutex);
    NFAPI_CRC_INDICATION_PDU_T *result = &crc_array->array[index];
    pthread_mutex_unlock(&crc_array->mutex);
    return result;
}

void remove_crc_from_array(NFAPI_CRC_ARRAY_T *crc_array, size_t index) {
    if (index >= crc_array->size) {
        fprintf(stderr, "Out-of-bounds access\n");
        return;
    }
    pthread_mutex_lock(&crc_array->mutex);
    for (size_t i = index; i < crc_array->size - 1; i++) {
        crc_array->array[i] = crc_array->array[i + 1];
    }
    crc_array->size--;
    pthread_mutex_unlock(&crc_array->mutex);
}

void free_crc_array(NFAPI_CRC_ARRAY_T *crc_array) {
    pthread_mutex_lock(&crc_array->mutex);
    free(crc_array->array);
    pthread_mutex_destroy(&crc_array->mutex);
}
