void init_memory_pool(memory_pool *pool, size_t initial_capacity) {
    pool->records = (record *)malloc(initial_capacity * sizeof(record));
    if (!pool->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->size = 0;
    pool->capacity = initial_capacity;
}

void free_memory_pool(memory_pool *pool) {
    free(pool->records);
    pool->records = NULL;
    pool->size = 0;
    pool->capacity = 0;
}

record *allocate_record(memory_pool *pool) {
    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity ? pool->capacity * 2 : 16;
        record *new_records = (record *)realloc(pool->records, new_capacity * sizeof(record));
        if (!new_records) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        pool->records = new_records;
        pool->capacity = new_capacity;
    }
    return &pool->records[pool->size++];
}

void validate_offset_key(offset_key *key) {
    if (key->offset < 0 || key->offset >= MAX_OFFSET) {
        fprintf(stderr, "Invalid offset: %ld\n", key->offset);
        exit(EXIT_FAILURE);
    }
}

record generate_random_record() {
    record r;
    r.value = rand() % 201 - 100; // Random value between -100 and 100
    return r;
}

void dynamicDataProcessor(offset_key *keys, size_t n, memory_pool *pool) {
    for (size_t i = 0; i < n; ++i) {
        validate_offset_key(&keys[i]);
        record *r = allocate_record(pool);
        *r = generate_random_record();
    }
}

int main() {
    srand(time(NULL));
    offset_key keys[MAX_RECORDS];
    memory_pool pool;
    init_memory_pool(&pool, 10);

    // Example usage
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        keys[i].offset = rand() % MAX_OFFSET;
        keys[i].key = rand() % 256;
    }

    dynamicDataProcessor(keys, MAX_RECORDS, &pool);

    // Cleanup
    free_memory_pool(&pool);
    return 0;
}
