typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    FILE *error_log;
    FILE *duplicate_log;
} NFAPI_CRC_ARRAY;

NFAPI_CRC_ARRAY* create_nfaapi_crc_array(size_t initial_capacity, size_t max_size) {
    NFAPI_CRC_ARRAY *array = (NFAPI_CRC_ARRAY*)malloc(sizeof(NFAPI_CRC_ARRAY));
    if (!array) return NULL;

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);

    char error_log_name[256];
    snprintf(error_log_name, sizeof(error_log_name), "error_log_%zu.txt", max_size);
    array->error_log = fopen(error_log_name, "w");

    char duplicate_log_name[256];
    snprintf(duplicate_log_name, sizeof(duplicate_log_name), "duplicate_log_%zu.txt", max_size);
    array->duplicate_log = fopen(duplicate_log_name, "w");

    return array;
}

void destroy_nfaapi_crc_array(NFAPI_CRC_ARRAY *array) {
    if (array->array) free(array->array);
    pthread_mutex_destroy(&array->lock);
    fclose(array->error_log);
    fclose(array->duplicate_log);
    free(array);
}

int add_nfaapi_crc_indication(NFAPI_CRC_ARRAY *array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->lock);
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&array->lock);
            fprintf(array->duplicate_log, "Duplicate RNTI: %u\n", pdu.RNTI);
            return -1;
        }
    }

    array->array[array->size++] = pdu;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void check_memory_usage(NFAPI_CRC_ARRAY *array, size_t max_size) {
    pthread_mutex_lock(&array->lock);

    if (sizeof(NFAPI_CRC_INDICATION_PDU_T) * array->size > max_size) {
        fprintf(stderr, "Memory usage exceeds budget\n");
        // Log to error log
    }

    pthread_mutex_unlock(&array->lock);
}

void flush_logs(NFAPI_CRC_ARRAY *array) {
    fflush(array->error_log);
    fflush(array->duplicate_log);
}
