ConfigManager* config_manager_init(int expected_load) {
    ConfigManager *manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    manager->size = 0;
    manager->capacity = expected_load;
    manager->offsets = (long*)calloc(expected_load, sizeof(long));
    manager->keys = (int*)calloc(expected_load, sizeof(int));
    manager->records = (Record*)calloc(expected_load, sizeof(Record));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void config_manager_add(ConfigManager *manager, int key, int value) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        printf("Error: Manager is full\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    manager->keys[manager->size] = key;
    manager->records[manager->size].value = value;
    manager->records[manager->size].last_modified = time(NULL);
    manager->offsets[manager->size] = manager->size * sizeof(Record);
    manager->size++;
    pthread_mutex_unlock(&manager->lock);
}

int config_manager_get(ConfigManager *manager, int key) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; i++) {
        if (manager->keys[i] == key) {
            pthread_mutex_unlock(&manager->lock);
            return manager->records[i].value;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    printf("Error: Key not found\n");
    return -1;
}

void config_manager_update(ConfigManager *manager, int key, int value) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; i++) {
        if (manager->keys[i] == key) {
            manager->records[i].value = value;
            manager->records[i].last_modified = time(NULL);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    printf("Error: Key not found\n");
}

void config_manager_log_changes(ConfigManager *manager) {
    // Implement logging mechanism here
}

void config_manager_cleanup(ConfigManager *manager) {
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
