#include <pthread.h>

#define MAX_RECORDS 1000000
#define EXTRA_DATA_SIZE 128

typedef struct {
    int id;
    time_t timestamp;
    float value;
    char extra[EXTRA_DATA_SIZE];
} Record;

typedef struct {
    Record *records;
    size_t count;
    size_t capacity;
    int mode; // 0 for uncompressed, 1 for compressed
    pthread_mutex_t lock;
} DatabaseTable;

int initDatabaseTable(DatabaseTable *table, int mode) {
    table->records = (Record *)malloc(MAX_RECORDS * sizeof(Record));
    if (!table->records) return -1;
    table->count = 0;
    table->capacity = MAX_RECORDS;
    table->mode = mode;
    pthread_mutex_init(&table->lock, NULL);
    return 0;
}

void freeDatabaseTable(DatabaseTable *table) {
    pthread_mutex_lock(&table->lock);
    free(table->records);
    pthread_mutex_unlock(&table->lock);
    pthread_mutex_destroy(&table->lock);
}

int addRecord(DatabaseTable *table, float value_range_start, float value_range_end) {
    pthread_mutex_lock(&table->lock);
    if (table->count >= table->capacity) {
        pthread_mutex_unlock(&table->lock);
        return -1;
    }
    Record *record = &table->records[table->count];
    record->id = table->count + 1;
    record->timestamp = time(NULL);
    while (1) {
        record->value = value_range_start + (rand() / (float)RAND_MAX) * (value_range_end - value_range_start);
        if (table->mode == 0 || (table->count == 0 || record->value != table->records[table->count - 1].value)) break;
    }
    memset(record->extra, 0, EXTRA_DATA_SIZE);
    table->count++;
    pthread_mutex_unlock(&table->lock);
    return 0;
}

void clearDatabaseTable(DatabaseTable *table) {
    pthread_mutex_lock(&table->lock);
    table->count = 0;
    pthread_mutex_unlock(&table->lock);
}
