            logDuplicateTransactionId(i + 1, logFile);
            continue;
        }

        DataChunk* chunk = allocateDataChunk(1024); // Example size
        if (chunk == NULL) {
            fprintf(logFile, "Memory allocation failed for request %d\n", i + 1);
            result.failedAllocations++;
            continue;
        }

        int compressedSize = compressDataChunk(chunk, 1024);
        decompressDataChunk(chunk, 1024);

        ResourceAllocationRequest request;
        request.transactionId = i + 1;
        request.dataChunk = chunk;

        result.requests[result.successfulAllocations++] = request;
    }

    fprintf(performanceLog, "Successful allocations: %d\n", result.successfulAllocations);
    fprintf(performanceLog, "Failed allocations: %d\n", result.failedAllocations);
    fprintf(performanceLog, "Unique TransactionIDs processed: %d\n", result.uniqueTransactionIds);

    return result;
}
