typedef struct {
    int value;
    bool status;
    void* data;
} Record;

void initializeFramework(long** offsets, int** keys, Record** records, bool** statuses, int maxKey, int minValue, int maxValue) {
    srand(time(NULL));

    *offsets = (long*)malloc((maxKey + 1) * sizeof(long));
    *keys = (int*)malloc((maxKey + 1) * sizeof(int));
    *records = (Record*)malloc((maxKey + 1) * sizeof(Record));
    *statuses = (bool*)malloc((maxKey + 1) * sizeof(bool));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *statuses == NULL) {
        // Handle memory allocation failure
        return;
    }

    for (int i = 0; i <= maxKey; i++) {
        (*offsets)[i] = i;
        (*keys)[i] = i;

        int value;
        do {
            value = rand() % (maxValue - minValue + 1) + minValue;
        } while (i > 0 && (*records)[i - 1].value == value);

        (*records)[i].value = value;
        (*records)[i].status = (value % 2 == 0); // Example validation criteria
        (*records)[i].data = malloc(sizeof(int)); // Allocate memory for external data
        if ((*records)[i].data == NULL) {
            // Handle memory allocation failure for external data
            return;
        }
        *((int*)(*records)[i].data) = value; // Example initialization of external data

        (*statuses)[i] = (*records)[i].status;
    }

    // Additional error handling and resource management can be added here
}

void cleanupFramework(long* offsets, int* keys, Record* records, bool* statuses) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (records != NULL) {
        for (int i = 0; records[i].data != NULL; i++) {
            free(records[i].data);
        }
        free(records);
    }
    if (statuses != NULL) free(statuses);
}
