#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

// Define the record structure
typedef struct Record {
    int value;
    bool flag;
} Record;

// Define the linked list node structure
typedef struct Node {
    int key;
    Record *record;
    struct Node *next;
} Node;

// Function to create a new record
Record* create_record(int value, bool flag) {
    Record *new_record = (Record*)malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Memory allocation failed for record\n");
        exit(EXIT_FAILURE);
    }
    new_record->value = value;
    new_record->flag = flag;
    return new_record;
}

// Function to create a new node
Node* create_node(int key, Record *record) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed for node\n");
        exit(EXIT_FAILURE);
    }
    new_node->key = key;
    new_node->record = record;
    new_node->next = NULL;
    return new_node;
}

// Function to insert a node into the linked list
void insert_node(Node **head, int key, Record *record) {
    Node *new_node = create_node(key, record);
    if (*head == NULL || (*head)->key > key) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node *current = *head;
        while (current->next != NULL && current->next->key < key) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

// Function to delete a node from the linked list
void delete_node(Node **head, int key) {
    Node *current = *head;
    Node *previous = NULL;

    while (current != NULL && current->key != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        fprintf(stderr, "Node with key %d not found\n", key);
        return;
    }

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current->record);
    free(current);
}

// Function to initialize the structures and linked list
void initialize_structures(int initial_value_range, int key_limit) {
    srand(time(NULL));

    long *long_offsets = (long*)malloc(key_limit * sizeof(long));
    if (long_offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for long offsets\n");
        exit(EXIT_FAILURE);
    }

    int *int_keys = (int*)malloc(key_limit * sizeof(int));
    if (int_keys == NULL) {
        fprintf(stderr, "Memory allocation failed for int keys\n");
        free(long_offsets);
        exit(EXIT_FAILURE);
    }

    Record **records = (Record**)malloc(key_limit * sizeof(Record*));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(long_offsets);
        free(int_keys);
        exit(EXIT_FAILURE);
    }

    Node *linked_list_head = NULL;

    int current_value = 0;
    bool flag = false;

    for (int i = 0; i < key_limit; i++) {
        long_offsets[i] = i;
        int_keys[i] = i % key_limit;
        records[i] = create_record(current_value, flag);
        insert_node(&linked_list_head, int_keys[i], records[i]);

        current_value += rand() % initial_value_range + 1;
        flag = !flag;
    }

    // Demonstrate linked list operations
    delete_node(&linked_list_head, key_limit / 2);

    // Free all allocated memory
    for (int i = 0; i < key_limit; i++) {
        free(records[i]);
    }
    free(long_offsets);
    free(int_keys);
    free(records);
    while (linked_list_head != NULL) {
        Node *temp = linked_list_head;
        linked_list_head = linked_list_head->next;
        free(temp->record);
        free(temp);
    }

    printf("Memory freed successfully\n");
}

int main() {
    initialize_structures(10, 20);
    return 0;
}
```

This code snippet demonstrates the implementation of a function that dynamically allocates memory for and initializes four structures: one for 'long' offsets, one for 'int' keys, one for 'record' structures, and another for 'flags'. It also manages a linked list of records to support efficient insertion and deletion based on their keys. The code includes error handling, memory management, and demonstrates how to safely free all allocated memory after the function completes its operations.']

