#include <stdlib.h>
#include <time.h>

typedef struct {
    unsigned long key;
    double value;
} entry;

entry* create_entry_array(size_t size, double min_value, double max_value) {
    if (size == 0 || min_value >= max_value) {
        return NULL; // Error handling for invalid input
    }

    entry* array = malloc(size * sizeof(entry));
    if (array == NULL) {
        return NULL; // Memory allocation failure
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < size; ++i) {
        array[i].key = i;
        array[i].value = min_value + (double(rand()) / RAND_MAX) * (max_value - min_value);
    }

    return array;
}
