#include <iostream>
#include <vector>
#include <random>
#include <mutex>

struct MAC_TransportChannelInfo {
    int rnti;
};

class Connection {
public:
    void* input_data;
    long offset;
    std::mutex data_mutex;

    Connection() : input_data(nullptr), offset(0) {}
};

void processUserInput(Connection& conn, const MAC_TransportChannelInfo& info, int mode, size_t max_memory, size_t max_input_size, int min_value, int max_value) {
    static std::vector<void*> shared_data;
    static std::mutex shared_mutex;

    if (mode == 'efficient') {
        std::lock_guard<std::mutex> lock(shared_mutex);
        if (shared_data.empty()) {
            // Lazy allocation of shared data
            shared_data.resize(max_input_size);
        }
        conn.input_data = &shared_data[info.rnti % max_input_size];
    } else {
        // Allocate unique input data for each connection in balanced or extensive mode
        conn.input_data = new char[max_input_size];
    }

    std::lock_guard<std::mutex> lock(conn.data_mutex);
    if (mode == 'efficient') {
        // Initialize shared input data with random values
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(min_value, max_value);

        for (size_t i = 0; i < max_input_size; ++i) {
            int* ptr = static_cast<int*>(conn.input_data);
            *ptr = dis(gen);
        }
    } else {
        // Initialize unique input data with random values
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(min_value, max_value);

        int* ptr = static_cast<int*>(conn.input_data);
        *ptr = dis(gen);
    }

    conn.offset = reinterpret_cast<long>(conn.input_data) - reinterpret_cast<long>(&shared_data[0]);
}

int main() {
    Connection conn;
    MAC_TransportChannelInfo info{123};
    int mode = 'efficient';
    size_t max_memory = 1024 * 1024; // 1MB
    size_t max_input_size = 1024; // 1KB
    int min_value = 0;
    int max_value = 100;

    processUserInput(conn, info, mode, max_memory, max_input_size, min_value, max_value);

    std::cout << "Offset: " << conn.offset << std::endl;

    return 0;
}
